var ACCA_REVISION_LIBRARY = {"schema": "acca-revision/1", "generated": "2026-11-13", "subjects": [{"id": "acfab", "code": "F1", "name": "Accountant and Business", "level": "Applied Knowledge", "book": "ACCA-AB.pdf | BPP ACCA Workbook (Accountant in Business) | offset 10", "updated": "2026-11-12", "chapters": [{"num": "1", "title": "Business Organisations and Their Stakeholders", "pages": [3, 18], "syllabus": "A1, A2", "status": "published", "branches": [{"kind": "concept", "title": "Purpose of business organisations", "page": [4, 6], "items": [{"t": "def", "k": 1, "term": "Organisation", "text": "'A social arrangement which pursues collective goals, which controls its own performance and which has a boundary separating it from its environment'", "id": "acfab-rv1-a22ae-a0e98f"}, {"t": "pt", "text": "Common characteristics", "kids": [{"t": "pt", "text": "Preoccupied with performance and improving standards", "id": "acfab-rv1-a22ae-7660bc"}, {"t": "pt", "text": "Formal, documented systems and procedures for control", "id": "acfab-rv1-a22ae-d9a5ed"}, {"t": "pt", "text": "Specialisation: different people do different things", "id": "acfab-rv1-a22ae-d9d2be"}, {"t": "pt", "text": "Pursue a variety of objectives and goals", "id": "acfab-rv1-a22ae-d477b5"}, {"t": "pt", "text": "Obtain inputs and process them into outputs", "id": "acfab-rv1-a22ae-527d87"}], "id": "acfab-rv1-a22ae-4d44a1"}, {"t": "pt", "k": 1, "text": "Why organisations exist: they achieve results individuals cannot achieve alone", "kids": [{"t": "pt", "text": "Overcome individual physical/intellectual limitations", "id": "acfab-rv1-a22ae-298830"}, {"t": "pt", "text": "Enable specialisation", "id": "acfab-rv1-a22ae-241b3c"}, {"t": "pt", "text": "Save time (people work together / in parallel)", "id": "acfab-rv1-a22ae-38dbcb"}, {"t": "pt", "text": "Accumulate and share knowledge", "id": "acfab-rv1-a22ae-034f68"}, {"t": "pt", "text": "Synergy: combined output exceeds separate outputs", "id": "acfab-rv1-a22ae-355dc3"}], "id": "acfab-rv1-a22ae-a24f4d"}, {"t": "pt", "text": "How organisations differ: ownership • control • activity • profit orientation • legal status • size • sources of finance • technology", "id": "acfab-rv1-a22ae-de0e3e"}, {"t": "pt", "text": "Sectors of activity: agriculture, manufacturing, extractive/raw materials, energy, retailing/distribution, IT, financial services, other services", "id": "acfab-rv1-a22ae-9610cf"}], "id": "acfab-rv1-a22ae"}, {"kind": "compare", "title": "Types of business organisation", "page": [6, 10], "items": [{"t": "table", "rows": [["Type", "Owned / run by", "Main aim", "Key feature"], ["Commercial (private sector)", "Private owners / shareholders", "Profit", "Costs must be below revenue; profit is the purpose, not incidental"], ["Public sector", "Central or local government, government agencies", "Public service", "Accountable to Parliament; funded by taxes, charges, borrowing"], ["NGO", "People acting independently of any government", "Social / humanitarian", "Legally constituted; not directly linked to government"], ["Co-operative", "Its workers or customers", "Members' benefit", "Open membership; one member, one vote; profits shared"]], "id": "acfab-rv1-a7fde-3e04b9"}, {"t": "def", "k": 1, "term": "Private sector", "text": "Organisations not owned or run by central or local government or government agencies", "id": "acfab-rv1-a7fde-87de96"}, {"t": "def", "k": 1, "term": "Public sector", "text": "Organisations owned or run by central or local government or government agencies", "id": "acfab-rv1-a7fde-ef1f02"}, {"t": "def", "k": 1, "term": "Non-governmental organisation (NGO)", "text": "A legally constituted organisation of people acting together independently from any form of government", "id": "acfab-rv1-a7fde-cc75f8"}, {"t": "pt", "text": "Public sector advantages: fairness (universal access) • fills gaps left by the private sector (public goods eg street lighting) • public interest", "id": "acfab-rv1-a7fde-305e08"}, {"t": "pt", "text": "Public sector disadvantages: weak accountability (taxpayers bear losses) • political interference • inefficiency", "id": "acfab-rv1-a7fde-7f0699"}, {"t": "pt", "text": "Co-operative features: open membership • democratic control (one member, one vote) • distribution of surplus to members • promotion of education", "id": "acfab-rv1-a7fde-1b0633"}], "id": "acfab-rv1-a7fde"}, {"kind": "concept", "title": "Limited companies", "page": [7, 8], "items": [{"t": "pt", "k": 1, "text": "Separate legal personality from its shareholders: it can own property and make contracts", "id": "acfab-rv1-7aef0-f48ecb"}, {"t": "pt", "k": 1, "text": "Limited liability: shareholders' risk is limited to their investment (unless they give a personal guarantee)", "id": "acfab-rv1-7aef0-5f0ac0"}, {"t": "pt", "text": "Private limited company (X Ltd) vs public limited company (X plc)", "kids": [{"t": "pt", "text": "Plc may offer shares to the public; private company may not", "id": "acfab-rv1-7aef0-1ed1e3"}, {"t": "pt", "text": "Most private companies have few shareholders, often a family", "id": "acfab-rv1-7aef0-2f1263"}], "id": "acfab-rv1-7aef0-934a0f"}, {"t": "pt", "text": "Advantages: more finance available • reduced investor risk • separate legal personality • ownership easily transferred", "id": "acfab-rv1-7aef0-9e7730"}, {"t": "pt", "text": "Disadvantages: legal/administrative costs • public disclosure of information • separation of ownership and control (agency issue)", "id": "acfab-rv1-7aef0-94a912"}, {"t": "pt", "text": "Alternatives: sole trader (alone) or partnership (partners share profits) - no separate legal personality", "id": "acfab-rv1-7aef0-c19407"}], "id": "acfab-rv1-7aef0"}, {"kind": "concept", "title": "Stakeholder groups", "page": [11, 12], "items": [{"t": "def", "k": 1, "term": "Stakeholders", "text": "Individuals or groups that, potentially, have an interest in what the organisation does - inside it, connected to it or external to it", "id": "acfab-rv1-16981-3729a5"}, {"t": "pt", "k": 1, "text": "Managers act as agents for stakeholders; the influence of each group varies by organisation", "id": "acfab-rv1-16981-617bbb"}, {"t": "pt", "text": "Internal: employees and management - job security, pay, conditions, career", "id": "acfab-rv1-16981-3b5b23"}, {"t": "pt", "text": "Connected: shareholders, customers, suppliers, lenders/financiers", "kids": [{"t": "pt", "text": "Shareholders: return on investment, share price growth", "id": "acfab-rv1-16981-f53d27"}, {"t": "pt", "text": "Customers: value, quality, availability", "id": "acfab-rv1-16981-aab23e"}, {"t": "pt", "text": "Suppliers: paid on time, continuing business", "id": "acfab-rv1-16981-68570d"}, {"t": "pt", "text": "Lenders: interest paid, capital repaid, security", "id": "acfab-rv1-16981-1e37bb"}], "id": "acfab-rv1-16981-908e77"}, {"t": "pt", "text": "External: government, local authorities, pressure groups, the community, professional bodies", "id": "acfab-rv1-16981-d9a564"}, {"t": "pt", "text": "Primary stakeholders have a contractual relationship with the organisation; secondary stakeholders do not", "id": "acfab-rv1-16981-f0dd29"}, {"t": "pt", "text": "Stakeholder conflict is common because interests differ (eg employees' pay vs shareholders' returns)", "id": "acfab-rv1-16981-864980"}], "id": "acfab-rv1-16981"}, {"kind": "decision", "title": "Mendelow's power/interest matrix", "page": [13, 14], "items": [{"t": "pt", "k": 1, "text": "Axes: power held and likelihood of showing an interest in the organisation's activities", "id": "acfab-rv1-41bf1-2d2156"}, {"t": "table", "rows": [["Segment", "Power", "Interest", "Strategy"], ["A", "Low", "Low", "Minimal effort"], ["B", "Low", "High", "Keep informed"], ["C", "High", "Low", "Keep satisfied"], ["D", "High", "High", "Key players - manage closely"]], "id": "acfab-rv1-41bf1-c21b25"}, {"t": "exam", "text": "Segment C (high power, low interest) must be kept SATISFIED, not merely informed - a classic quick-quiz trap", "id": "acfab-rv1-41bf1-be8238"}, {"t": "pt", "text": "Strategic value: links between employee and customer loyalty, customer loyalty and profitability", "id": "acfab-rv1-41bf1-86c8d0"}, {"t": "pt", "text": "Satisfaction can be measured (eg surveys, indicators per stakeholder group)", "id": "acfab-rv1-41bf1-324d9e"}], "id": "acfab-rv1-41bf1"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "The Study Guide requires application, not just knowledge: expect short scenarios asking you to classify an organisation or stakeholder", "id": "acfab-rv1-308d8-fef2d5"}, {"t": "exam", "text": "Shareholders, customers, suppliers and financiers are CONNECTED stakeholders - only employees and management are internal", "id": "acfab-rv1-308d8-db2add"}, {"t": "exam", "text": "A public sector body is owned/run by government; a private sector body is anything that is not - 'none of the above' is a valid MCQ answer", "id": "acfab-rv1-308d8-f9983a"}, {"t": "exam", "text": "Co-operatives = owned by workers OR customers who share the profits", "id": "acfab-rv1-308d8-479daa"}, {"t": "pt", "text": "ACCA articles flagged by the text: 'Not-for-profit organisations I & II', 'Communicating core values and mission'", "id": "acfab-rv1-308d8-87f1aa"}], "id": "acfab-rv1-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calling shareholders 'internal' stakeholders - they are connected", "id": "acfab-rv1-6483a-b7b201"}, {"t": "x", "text": "Thinking all organisations exist to make a profit - the definition of an organisation does not mention profit", "id": "acfab-rv1-6483a-e56af3"}, {"t": "x", "text": "Mixing up Mendelow segments B (keep informed) and C (keep satisfied)", "id": "acfab-rv1-6483a-969dfc"}, {"t": "x", "text": "Assuming an NGO is part of the public sector - it is independent of government", "id": "acfab-rv1-6483a-b94a18"}], "id": "acfab-rv1-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Organisation = social arrangement, collective goals, controls own performance, boundary with environment", "id": "acfab-rv1-80e78-2f6eef"}, {"t": "pt", "text": "Organisations exist because they achieve more than individuals: specialisation, time, knowledge, synergy", "id": "acfab-rv1-80e78-70091d"}, {"t": "pt", "text": "Eight ways organisations differ: ownership, control, activity, profit orientation, legal status, size, finance, technology", "id": "acfab-rv1-80e78-582d47"}, {"t": "pt", "text": "Key split: profit-orientated (commercial) vs not-for-profit", "id": "acfab-rv1-80e78-3a1d9c"}, {"t": "pt", "text": "Public sector = owned/run by government; private sector = everything else", "id": "acfab-rv1-80e78-a68f93"}, {"t": "pt", "text": "NGO = legally constituted, independent of any government", "id": "acfab-rv1-80e78-0e81dc"}, {"t": "pt", "text": "Co-operative: owned by workers/customers, one member one vote, profits shared", "id": "acfab-rv1-80e78-caa18a"}, {"t": "pt", "text": "Limited company = separate legal personality + limited liability", "id": "acfab-rv1-80e78-c10ce0"}, {"t": "pt", "text": "Ltd vs plc: only a plc can offer shares to the public", "id": "acfab-rv1-80e78-5e91f8"}, {"t": "pt", "text": "Stakeholders: internal (employees, managers), connected (shareholders, customers, suppliers, lenders), external (government, pressure groups, community)", "id": "acfab-rv1-80e78-eaff25"}, {"t": "pt", "text": "Primary = contractual relationship; secondary = no contract", "id": "acfab-rv1-80e78-13b441"}, {"t": "pt", "text": "Managers are agents of the stakeholders", "id": "acfab-rv1-80e78-1f37a2"}, {"t": "pt", "text": "Mendelow: A minimal effort, B keep informed, C keep satisfied, D key players", "id": "acfab-rv1-80e78-98bc13"}, {"t": "pt", "text": "Stakeholder conflict is normal and must be managed when setting policy", "id": "acfab-rv1-80e78-270b63"}], "id": "acfab-rv1-80e78"}], "source": "BPP Workbook ch 1: topic list p3; sections 1-3 pp4-14; chapter roundup p16", "summary": "What organisations are, how they differ, the main types, and how stakeholders with different power and interest are managed.", "id": "acfab-rv1", "updated": "2026-11-12"}, {"num": "2", "title": "The Business Environment", "pages": [19, 56], "syllabus": "A3, A6, A7, A8, A9", "status": "published", "branches": [{"kind": "concept", "title": "Analysing the environment (PEST)", "page": [21, 23], "items": [{"t": "pt", "k": 1, "text": "Aim: review the environment for opportunities and threats and secure 'environmental fit'", "id": "acfab-rv2-7d916-ca273e"}, {"t": "pt", "k": 1, "text": "General (macro) environment = PEST: Political-legal, Economic, Social-cultural, Technological - influences all organisations indirectly", "id": "acfab-rv2-7d916-b7298b"}, {"t": "pt", "text": "Task (micro) environment: direct impact - suppliers of raw materials, competitors, customers (analysed with Porter's five forces)", "id": "acfab-rv2-7d916-a4402b"}, {"t": "pt", "text": "Environmental uncertainty is assessed on two axes: simplicity/complexity and stability/dynamism", "id": "acfab-rv2-7d916-e6eb6b"}, {"t": "pt", "text": "Drivers of change: globalisation of business, technology, deregulation, changing social attitudes", "id": "acfab-rv2-7d916-93a7aa"}, {"t": "exam", "text": "PEST is a useful initial survey of conditions and options; exam questions are not country specific", "id": "acfab-rv2-7d916-3a16c6"}], "id": "acfab-rv2-7d916"}, {"kind": "concept", "title": "Political and legal environment", "page": [24, 27], "items": [{"t": "pt", "k": 1, "text": "Government policy influences the economic environment, the framework of laws, industry structure and operations; political instability is a cause of risk", "id": "acfab-rv2-97156-8fc13b"}, {"t": "pt", "text": "Sources of law: common law, parliamentary legislation and regulations derived from it, treaty obligations (eg EU)", "id": "acfab-rv2-97156-3be5e3"}, {"t": "pt", "text": "Porter: government can directly shape an industry - capacity expansion, demand, divestment/rationalisation, competition policy, regulation", "id": "acfab-rv2-97156-0dda59"}, {"t": "pt", "text": "Businesses influence government via lobbyists, politically connected directors and trade associations", "id": "acfab-rv2-97156-fb5141"}, {"t": "pt", "text": "UK law change is usually predictable: green paper -> white paper -> bill", "id": "acfab-rv2-97156-b8e313"}, {"t": "pt", "text": "International trade: an extra layer of treaties; EU single market (free movement of labour, goods, services); WTO promotes free trade and resolves disputes (theory of comparative advantage)", "id": "acfab-rv2-97156-5f1a6d"}], "id": "acfab-rv2-97156"}, {"kind": "rule", "title": "Employment protection", "page": [27, 29], "items": [{"t": "pt", "k": 1, "text": "All forms of termination of employment must be treated with great care", "id": "acfab-rv2-d6388-b62a31"}, {"t": "pt", "text": "Termination routes: retirement, resignation, dismissal, redundancy", "id": "acfab-rv2-d6388-c3f4e3"}, {"t": "def", "term": "Wrongful dismissal", "text": "Dismissal that breaches the contract of employment (eg failure to give the contractual period of notice)", "id": "acfab-rv2-d6388-2b32e3"}, {"t": "def", "term": "Unfair dismissal", "text": "Statutory protection against arbitrary dismissal, ie dismissal without good reason", "id": "acfab-rv2-d6388-d466fc"}, {"t": "exam", "text": "A dismissal need not be wrongful to be unfair - the two are separate claims", "id": "acfab-rv2-d6388-224395"}, {"t": "pt", "text": "A fair disciplinary system can be evidence that a dismissal was not unfair", "id": "acfab-rv2-d6388-2ffb71"}, {"t": "def", "k": 1, "term": "Redundancy", "text": "Dismissal where the employer has ceased to carry on the business (or at the employee's place of work), or the requirement for employees to do work of a particular kind has ceased or diminished", "id": "acfab-rv2-d6388-9819a9"}, {"t": "pt", "text": "Redundancy handling: consult employees or their representatives; notice of impending redundancies is a legal duty; consider redeployment, retraining, early retirement", "id": "acfab-rv2-d6388-f1b9b7"}, {"t": "pt", "text": "Equal opportunities law prevents unjustified discrimination (developed in ch 13)", "id": "acfab-rv2-d6388-86fb94"}], "id": "acfab-rv2-d6388"}, {"kind": "concept", "title": "Data protection and security", "page": [29, 31], "items": [{"t": "def", "k": 1, "term": "Privacy", "text": "The right of the individual not to suffer unauthorised disclosure of information (and to control the use of information about them)", "id": "acfab-rv2-b9e27-98ef33"}, {"t": "pt", "k": 1, "text": "The (UK) Data Protection Act 2018 protects individuals about whom data is held; it covers BOTH manual and computerised records and embodies the EU GDPR", "id": "acfab-rv2-b9e27-5ab4ad"}, {"t": "pt", "text": "Key terms", "kids": [{"t": "def", "term": "Personal data", "text": "Information about a living individual, including expressions of opinion about them (data about organisations is NOT personal data)", "id": "acfab-rv2-b9e27-f41892"}, {"t": "pt", "text": "Data controller decides the purpose and means of processing; data processor processes on behalf of a controller", "id": "acfab-rv2-b9e27-e3b314"}, {"t": "pt", "text": "Data subject: the individual the data is about", "id": "acfab-rv2-b9e27-419ac1"}], "id": "acfab-rv2-b9e27-ae9678"}, {"t": "pt", "k": 1, "text": "Six data protection principles", "kids": [{"t": "pt", "text": "Lawfulness, fairness and transparency", "id": "acfab-rv2-b9e27-f2ff36"}, {"t": "pt", "text": "Purpose limitation (specified, explicit, legitimate purpose)", "id": "acfab-rv2-b9e27-880d22"}, {"t": "pt", "text": "Data minimisation (adequate, relevant, not excessive)", "id": "acfab-rv2-b9e27-b36416"}, {"t": "pt", "text": "Accuracy", "id": "acfab-rv2-b9e27-03fa8c"}, {"t": "pt", "text": "Storage limitation (not held longer than needed)", "id": "acfab-rv2-b9e27-f57206"}, {"t": "pt", "text": "Integrity and confidentiality (security)", "id": "acfab-rv2-b9e27-f8d1d2"}], "id": "acfab-rv2-b9e27-f47cc5"}, {"t": "pt", "text": "Rights of data subjects: to be informed, access, rectification, erasure ('to be forgotten'), restrict processing, data portability, to object, rights on automated decision-making and profiling", "id": "acfab-rv2-b9e27-4e70c6"}, {"t": "exam", "text": "Access, rectification, erasure and objection requests must be answered within ONE month; access is normally free", "id": "acfab-rv2-b9e27-c0c786"}, {"t": "exam", "text": "There is an absolute right to object to processing for direct marketing", "id": "acfab-rv2-b9e27-531d7a"}], "id": "acfab-rv2-b9e27"}, {"kind": "rule", "title": "Health and safety", "page": [32, 34], "items": [{"t": "pt", "k": 1, "text": "People should not be exposed to excessive risk at work - risk and danger must be actively managed", "id": "acfab-rv2-670c6-a78e5b"}, {"t": "pt", "text": "Why it matters: legal obligations; accidents and illness cost money; damage to image", "id": "acfab-rv2-670c6-fabafd"}, {"t": "pt", "text": "Employer duties: a senior manager made responsible; safe work practices, environment and equipment; information, training and supervision", "id": "acfab-rv2-670c6-c3392a"}, {"t": "pt", "k": 1, "text": "Employee duties: take reasonable care of themselves and others; allow the employer to carry out its duties; do not interfere with safety provisions", "id": "acfab-rv2-670c6-f98a74"}, {"t": "pt", "text": "Cost of accidents: time lost, disruption and repairs, compensation, insurance, morale", "id": "acfab-rv2-670c6-7c589c"}, {"t": "pt", "text": "A health and safety policy promotes awareness and good practice and helps meet legal obligations", "id": "acfab-rv2-670c6-4a0ffb"}], "id": "acfab-rv2-670c6"}, {"kind": "rule", "title": "Consumer protection", "page": [34, 36], "items": [{"t": "def", "k": 1, "term": "Contract", "text": "A legally binding agreement", "id": "acfab-rv2-bfcca-5ae6d5"}, {"t": "pt", "k": 1, "text": "Implied terms in a sale of goods: title (right to sell), description, satisfactory quality, fitness for a disclosed purpose", "id": "acfab-rv2-bfcca-e0a303"}, {"t": "pt", "text": "Time of performance: if time is a condition of the contract, late delivery is a breach", "id": "acfab-rv2-bfcca-662e0a"}, {"t": "pt", "text": "Seller's title: you cannot sell what is not yours - eg a buyer of a stolen car recovered the full price from the seller", "id": "acfab-rv2-bfcca-ec87b4"}, {"t": "pt", "text": "Goods must correspond with the description, even if the buyer has not seen them (secondhand reaping machine example)", "id": "acfab-rv2-bfcca-f3a773"}, {"t": "pt", "text": "Satisfactory quality: the standard a reasonable person would regard as satisfactory", "id": "acfab-rv2-bfcca-5da9cd"}, {"t": "pt", "text": "Fitness for purpose applies where the buyer makes the purpose known, expressly or by implication", "id": "acfab-rv2-bfcca-f209a4"}], "id": "acfab-rv2-bfcca"}, {"kind": "concept", "title": "Social, demographic and cultural trends", "page": [37, 39], "items": [{"t": "pt", "k": 1, "text": "Population affects the supply of labour and hence recruitment and HR policies", "id": "acfab-rv2-318c9-a5b573"}, {"t": "pt", "text": "Employer responses: identify the labour market, flexible and part-time working, recruit older or younger workers, training", "id": "acfab-rv2-318c9-cc47f4"}, {"t": "pt", "text": "Family life cycle combines age, marital status, career and children - used in marketing", "id": "acfab-rv2-318c9-bfe335"}, {"t": "pt", "text": "Social class / socio-economic status groups share occupation, income and education - use with caution for planning", "id": "acfab-rv2-318c9-6f16fa"}, {"t": "pt", "text": "Cultural trends: health and diet, women in work (part-time and flexible working), environmentalism", "id": "acfab-rv2-318c9-45467c"}, {"t": "pt", "text": "Business response: 'green' products, healthier ranges, flexible employment practices", "id": "acfab-rv2-318c9-eb4cc9"}], "id": "acfab-rv2-318c9"}, {"kind": "concept", "title": "Technology and the accountant", "page": [40, 44], "items": [{"t": "pt", "k": 1, "text": "IT has encouraged flatter hierarchies and wider spans of control", "id": "acfab-rv2-3dc18-de78ae"}, {"t": "def", "term": "Span of control", "text": "The number of subordinates responsible to a superior", "id": "acfab-rv2-3dc18-5fd6b3"}, {"t": "pt", "text": "Tall structure = narrow spans, many levels; flat structure = wide spans, few levels", "id": "acfab-rv2-3dc18-ee17b1"}, {"t": "pt", "text": "Effects on accountants and organisations: routine processing (volume, speed, accuracy) • digital records and back-up • new skills and ways of working • reliance on IT • new communication and customer service methods • interoperability and open systems • information as a resource and a commodity ('information market')", "id": "acfab-rv2-3dc18-a113d2"}, {"t": "pt", "text": "IT and employees: less need to follow the chain of command, homeworking/telecommuting", "id": "acfab-rv2-3dc18-984468"}, {"t": "def", "k": 1, "term": "Outsourcing", "text": "The contracting out of specified operations or services to an external vendor", "id": "acfab-rv2-3dc18-961b42"}, {"t": "pt", "text": "Four types of outsourcing: ad hoc (short-term skills) • project management (one project) • partial (some IT services) • total (all IT)", "id": "acfab-rv2-3dc18-454b77"}, {"t": "pt", "text": "Advantages: cost certainty from long-term contracts, access to highly skilled people, frees management time", "id": "acfab-rv2-3dc18-b40563"}, {"t": "pt", "text": "Disadvantages: loss of control, dependence on the vendor, confidentiality risk, hard to reverse", "id": "acfab-rv2-3dc18-6bae13"}, {"t": "pt", "text": "Syllabus terms: downsizing, delayering and outsourcing as effects of technological change", "id": "acfab-rv2-3dc18-c3c508"}], "id": "acfab-rv2-3dc18"}, {"kind": "concept", "title": "Environmental factors and CSR", "page": [44, 46], "items": [{"t": "pt", "k": 1, "text": "Businesses may suffer significant costs and loss of reputation if environmental problems arise", "id": "acfab-rv2-932c0-bdb880"}, {"t": "def", "term": "Environmental footprint", "text": "The impact a business's activities have on the environment, including its resource use and pollution emissions", "id": "acfab-rv2-932c0-af0b15"}, {"t": "pt", "text": "Internal environmental costs (IFAC list) include waste management, remediation, compliance and fines", "id": "acfab-rv2-932c0-22a0cb"}, {"t": "pt", "text": "Stakeholder expectations and reputation risk push wider corporate accountability", "id": "acfab-rv2-932c0-532e89"}, {"t": "def", "term": "Corporate social responsibility (CSR)", "text": "An organisation monitoring its activities to ensure active compliance with the spirit of the law, ethical standards and international norms", "id": "acfab-rv2-932c0-234d6e"}, {"t": "exam", "text": "You may be asked for the main environmental impacts of a given organisation - apply the scenario", "id": "acfab-rv2-932c0-fbfe33"}], "id": "acfab-rv2-932c0"}, {"kind": "compare", "title": "SWOT analysis", "page": [47, 47], "items": [{"t": "table", "rows": [["Element", "Internal or external", "Question it answers"], ["Strengths", "Internal", "What should we exploit with suitable strategies?"], ["Weaknesses", "Internal", "What must we improve or avoid?"], ["Opportunities", "External", "What can our strengths exploit?"], ["Threats", "External", "What must we defend against?"]], "id": "acfab-rv2-54015-74c80c"}, {"t": "pt", "k": 1, "text": "SWOT = internal appraisal (S, W) + external appraisal (O, T)", "id": "acfab-rv2-54015-25d609"}, {"t": "pt", "text": "Used to build resource-based strategies (extend strengths) or to close gaps by acquiring new resources", "id": "acfab-rv2-54015-498183"}], "id": "acfab-rv2-54015"}, {"kind": "process", "title": "Porter's value chain", "page": [47, 50], "items": [{"t": "pt", "k": 1, "text": "The value chain describes activities that add value to purchased inputs; the margin is the excess the customer is prepared to pay over the cost of the activities", "id": "acfab-rv2-bbeca-ace5da"}, {"t": "pt", "k": 1, "text": "Primary activities: inbound logistics -> operations -> outbound logistics -> marketing and sales -> service", "id": "acfab-rv2-bbeca-d85664"}, {"t": "pt", "k": 1, "text": "Support activities: procurement, technology development, human resource management, firm infrastructure", "id": "acfab-rv2-bbeca-38ecee"}, {"t": "pt", "text": "Linkages are relationships between activities; managing them (including suppliers) can give strategic advantage", "id": "acfab-rv2-bbeca-c2e396"}, {"t": "def", "term": "Value network", "text": "The linked value activities of suppliers, the organisation, distributors and customers - value creation does not stop at the organisation's boundary", "id": "acfab-rv2-bbeca-32184d"}, {"t": "eg", "text": "Restaurant: buying food, cooking it and serving it are separate value activities", "id": "acfab-rv2-bbeca-0343dd"}, {"t": "exam", "text": "Commit the value chain diagram to memory - exam questions use its exact terms", "id": "acfab-rv2-bbeca-270b29"}, {"t": "x", "text": "Procurement is a SUPPORT activity; inbound logistics (receiving, storing, handling inputs) is PRIMARY", "id": "acfab-rv2-bbeca-97195a"}], "id": "acfab-rv2-bbeca"}, {"kind": "concept", "title": "Porter's five forces", "page": [51, 52], "items": [{"t": "pt", "k": 1, "text": "Five forces: threat of new entrants (barriers to entry) • threat of substitutes • bargaining power of customers • bargaining power of suppliers • competitive rivalry", "id": "acfab-rv2-1c533-8725da"}, {"t": "pt", "text": "Substitute = a product from ANOTHER industry satisfying the same customer need", "id": "acfab-rv2-1c533-5a90e2"}, {"t": "pt", "text": "Supplier power is high when: one or two dominant suppliers; supplier has other customers; product important or differentiated; high switching costs", "id": "acfab-rv2-1c533-d53563"}, {"t": "pt", "text": "Customers want better quality at lower prices - strong buyers force down industry profitability", "id": "acfab-rv2-1c533-882de1"}, {"t": "pt", "text": "Rivalry takes the form of price competition, advertising, promotions, new products, after-sales service and warranties", "id": "acfab-rv2-1c533-85cdf9"}, {"t": "exam", "text": "Five forces analyses the TASK (industry) environment; PEST analyses the GENERAL environment", "id": "acfab-rv2-1c533-5ccbad"}], "id": "acfab-rv2-1c533"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Treating wrongful and unfair dismissal as the same thing", "id": "acfab-rv2-6483a-6d4680"}, {"t": "x", "text": "Thinking the Data Protection Act covers only computer records - manual records are covered too", "id": "acfab-rv2-6483a-3cc902"}, {"t": "x", "text": "Counting data about a company as 'personal data'", "id": "acfab-rv2-6483a-f982d5"}, {"t": "x", "text": "Classifying procurement as a primary activity in the value chain", "id": "acfab-rv2-6483a-f53d53"}, {"t": "x", "text": "Confusing a substitute (different industry) with a rival's product (same industry)", "id": "acfab-rv2-6483a-99f55e"}], "id": "acfab-rv2-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "PEST = political-legal, economic, social-cultural, technological (general environment)", "id": "acfab-rv2-80e78-8d8950"}, {"t": "pt", "text": "Five forces = entrants, substitutes, buyers, suppliers, rivalry (task environment)", "id": "acfab-rv2-80e78-ffe574"}, {"t": "pt", "text": "Uncertainty axes: simple-complex and stable-dynamic", "id": "acfab-rv2-80e78-defd9a"}, {"t": "pt", "text": "Wrongful dismissal = breach of contract; unfair dismissal = no good reason", "id": "acfab-rv2-80e78-9c4995"}, {"t": "pt", "text": "Redundancy: the business ceases, or the need for that kind of work ceases or diminishes", "id": "acfab-rv2-80e78-07dbe2"}, {"t": "pt", "text": "DPA 2018 covers manual and computer data on living individuals", "id": "acfab-rv2-80e78-ca3e0d"}, {"t": "pt", "text": "Six principles: lawful/fair/transparent, purpose limitation, minimisation, accuracy, storage limitation, integrity and confidentiality", "id": "acfab-rv2-80e78-79843e"}, {"t": "pt", "text": "Data subject requests: answer within one month; absolute right to object to direct marketing", "id": "acfab-rv2-80e78-53b152"}, {"t": "pt", "text": "Implied terms: title, description, satisfactory quality, fitness for purpose", "id": "acfab-rv2-80e78-a64266"}, {"t": "pt", "text": "IT leads to flatter structures and wider spans of control", "id": "acfab-rv2-80e78-0b7693"}, {"t": "pt", "text": "Outsourcing types: ad hoc, project management, partial, total", "id": "acfab-rv2-80e78-b6c39c"}, {"t": "pt", "text": "Value chain primary: inbound, operations, outbound, marketing and sales, service", "id": "acfab-rv2-80e78-e1180b"}, {"t": "pt", "text": "Value chain support: procurement, technology development, HRM, firm infrastructure", "id": "acfab-rv2-80e78-96fde9"}, {"t": "pt", "text": "SWOT: strengths and weaknesses internal; opportunities and threats external", "id": "acfab-rv2-80e78-dc6c56"}], "id": "acfab-rv2-80e78"}], "source": "BPP Workbook ch 2: topic list p19; sections 1-13 pp21-52; chapter roundup p53", "summary": "Analysing the general (PEST) and task environment: law, data protection, health and safety, consumer protection, social, technological and environmental factors, SWOT, the value chain and Porter's five forces.", "id": "acfab-rv2", "updated": "2026-11-12"}, {"num": "3", "title": "The Macroeconomic Environment", "pages": [57, 84], "syllabus": "A5", "status": "published", "branches": [{"kind": "concept", "title": "Circular flow of income", "page": [58, 60], "items": [{"t": "def", "k": 1, "term": "Macroeconomics", "text": "The study of the aggregated effects of the decisions of individual economic units - a complete national economy or the international system as a whole", "id": "acfab-rv3-20b5f-e9f08a"}, {"t": "pt", "k": 1, "text": "In the circular flow, expenditure, output and income all have the same total value", "id": "acfab-rv3-20b5f-9a896f"}, {"t": "pt", "k": 1, "text": "Withdrawals (leakages): savings, taxation, import expenditure", "id": "acfab-rv3-20b5f-63de9d"}, {"t": "pt", "k": 1, "text": "Injections: investment, government spending, export income", "id": "acfab-rv3-20b5f-937805"}, {"t": "pt", "text": "Factors that keep the economy unstable: investment, the multiplier, inflation, savings, confidence, interest rates, exchange rates", "id": "acfab-rv3-20b5f-c32dea"}, {"t": "def", "term": "Multiplier", "text": "An injection of a certain size leads to a much larger increase in national income because the extra income is re-spent around the circular flow", "id": "acfab-rv3-20b5f-4178c0"}], "id": "acfab-rv3-20b5f"}, {"kind": "concept", "title": "Aggregate demand, supply and equilibrium", "page": [60, 62], "items": [{"t": "def", "k": 1, "term": "Aggregate demand (AD)", "text": "Total planned demand in the economy for consumer and capital goods and services: consumption + investment + government spending + (exports - imports)", "id": "acfab-rv3-d71e6-9c1449"}, {"t": "pt", "text": "Aggregate supply (AS) is the economy's ability to produce; it rises with the price level", "id": "acfab-rv3-d71e6-41dd89"}, {"t": "pt", "k": 1, "text": "Equilibrium national income is where AD = AS", "id": "acfab-rv3-d71e6-7e2cfe"}, {"t": "def", "term": "Inflationary gap", "text": "At full employment, extra demand raises prices but not real output", "id": "acfab-rv3-d71e6-c01afd"}, {"t": "def", "term": "Deflationary gap", "text": "With unemployed resources, prices are fairly constant and real output varies with demand", "id": "acfab-rv3-d71e6-435cd8"}, {"t": "def", "term": "Stagflation", "text": "High unemployment AND high inflation together with low or negative growth (the 1970s problem)", "id": "acfab-rv3-d71e6-81ba0b"}, {"t": "pt", "text": "A fall in consumer confidence shifts AD left: lower national income and lower prices", "id": "acfab-rv3-d71e6-b91c30"}], "id": "acfab-rv3-d71e6"}, {"kind": "process", "title": "The business cycle", "page": [63, 64], "items": [{"t": "pt", "k": 1, "text": "Continual sequence: rapid growth -> slowdown -> fall in national income (recession) -> growth again -> peak", "id": "acfab-rv3-55cd8-52830a"}, {"t": "pt", "k": 1, "text": "Four phases: recession, depression, recovery, boom", "id": "acfab-rv3-55cd8-3ea2ec"}, {"t": "pt", "text": "Recession tends to happen quickly; recovery is typically slow", "id": "acfab-rv3-55cd8-186635"}, {"t": "pt", "text": "Recession: demand falls, investment projects become unprofitable, unemployment rises", "id": "acfab-rv3-55cd8-6bf6fe"}, {"t": "pt", "text": "Boom: capacity fully used, shortages of labour, rising prices", "id": "acfab-rv3-55cd8-511997"}], "id": "acfab-rv3-55cd8"}, {"kind": "concept", "title": "Inflation", "page": [64, 66], "items": [{"t": "def", "k": 1, "term": "Inflation", "text": "A general increase in price levels - a decline in the purchasing power of money", "id": "acfab-rv3-3d3c4-21087b"}, {"t": "pt", "k": 1, "text": "Why it is harmful: redistributes income and wealth (eg from creditors to debtors) • balance of payments (exports dearer) • uncertainty about the value of money makes planning hard • resource costs of changing prices • may harm growth and investment", "id": "acfab-rv3-3d3c4-d1e0c4"}, {"t": "pt", "text": "Measures: Retail Prices Index (RPI) and Consumer Prices Index (CPI); 'underlying rate' = RPI excluding mortgage costs", "id": "acfab-rv3-3d3c4-0c6578"}, {"t": "pt", "k": 1, "text": "Causes: demand pull • cost push • import cost factors • expectations • excessive money supply growth", "id": "acfab-rv3-3d3c4-d913af"}, {"t": "def", "term": "Demand pull inflation", "text": "Arises from an excess of aggregate demand over the productive capacity of the economy", "id": "acfab-rv3-3d3c4-e99600"}, {"t": "def", "term": "Cost push inflation", "text": "Arises from increases in the costs of production, whether or not those factors are in short supply", "id": "acfab-rv3-3d3c4-88a165"}, {"t": "pt", "text": "Import cost push: essential imports rise in price (eg oil price rises)", "id": "acfab-rv3-3d3c4-6ccd86"}, {"t": "pt", "text": "Expectational inflation: once inflation rises, people build it into wage and price decisions", "id": "acfab-rv3-3d3c4-19aadc"}, {"t": "pt", "text": "Monetarists: inflation is caused by increases in the money supply", "id": "acfab-rv3-3d3c4-a0b5d8"}], "id": "acfab-rv3-3d3c4"}, {"kind": "formula", "title": "Unemployment", "page": [67, 68], "items": [{"t": "f", "k": 1, "term": "Rate of unemployment", "text": "Number unemployed / Total workforce x 100%", "vars": "workforce = employed + unemployed", "eg": "2m unemployed in a 40m workforce = 5%", "id": "acfab-rv3-39463-ecc21a"}, {"t": "pt", "text": "Consequences: lost output, lost human capital, more social problems, higher government spending on benefits, inequality", "id": "acfab-rv3-39463-4c0d7b"}, {"t": "pt", "text": "Causes of unemployment", "kids": [{"t": "pt", "text": "Real wage: labour supply exceeds demand but real wages do not fall (strong unions, minimum wage set above the market-clearing level)", "id": "acfab-rv3-39463-ac6824"}, {"t": "pt", "k": 1, "text": "Frictional: the time taken to match workers with jobs - temporary", "id": "acfab-rv3-39463-0f1f99"}, {"t": "pt", "text": "Seasonal: demand for labour fluctuates (building, tourism, farming)", "id": "acfab-rv3-39463-77e608"}, {"t": "pt", "k": 1, "text": "Structural: long-term change in an industry's conditions - high regional unemployment", "id": "acfab-rv3-39463-966203"}, {"t": "pt", "text": "Technological: a form of structural unemployment from new technology and automation", "id": "acfab-rv3-39463-54074b"}, {"t": "pt", "text": "Cyclical (demand-deficient): caused by the downswing of the business cycle", "id": "acfab-rv3-39463-239ff5"}], "id": "acfab-rv3-39463-066569"}, {"t": "pt", "text": "Government policies: training and retraining, regional assistance, encouraging labour mobility, demand management", "id": "acfab-rv3-39463-305e98"}, {"t": "exam", "text": "Jobs can be created without reducing unemployment (eg new jobs filled by people not previously counted as unemployed)", "id": "acfab-rv3-39463-204d76"}], "id": "acfab-rv3-39463"}, {"kind": "concept", "title": "Economic growth", "page": [69, 71], "items": [{"t": "pt", "k": 1, "text": "Measured by increases in real gross national product (GNP) per head of the population", "id": "acfab-rv3-4282c-542881"}, {"t": "pt", "text": "Actual growth depends on growth in potential output (aggregate supply) and in aggregate demand", "id": "acfab-rv3-4282c-404162"}, {"t": "pt", "text": "Potential growth (supply side): more labour, more capital, better technology, better use of resources", "id": "acfab-rv3-4282c-2b3fb3"}, {"t": "pt", "text": "Sustained growth needs adequate new investment, which depends on expected future demand", "id": "acfab-rv3-4282c-7f714a"}, {"t": "pt", "text": "Limits: natural resources; technological progress raises output from the same inputs; terms of trade improvements help", "id": "acfab-rv3-4282c-c0b9ea"}, {"t": "pt", "text": "Advantages: higher income per head and living standards; disadvantages: pollution, resource depletion, inequality", "id": "acfab-rv3-4282c-e7f312"}], "id": "acfab-rv3-4282c"}, {"kind": "compare", "title": "Fiscal vs monetary policy", "page": [71, 78], "items": [{"t": "table", "rows": [["Feature", "Fiscal policy", "Monetary policy"], ["Definition", "Government policy on taxation, public borrowing and public spending", "Policy on money supply, the monetary system, interest rates, exchange rates and credit"], ["Main tools", "Tax changes, spending changes, budget deficit or surplus", "Money supply, interest rates, credit controls"], ["Works through", "Aggregate demand via the Budget (annual)", "Aggregate demand via the cost and availability of money (can change any time)"]], "id": "acfab-rv3-ea961-a93a9e"}, {"t": "pt", "k": 1, "text": "Four macroeconomic objectives: economic growth, low inflation, full employment, balance of payments equilibrium", "id": "acfab-rv3-ea961-2c6ca5"}, {"t": "pt", "text": "Budget deficit: spending > tax revenue (expansionary); budget surplus: tax revenue > spending (contractionary)", "id": "acfab-rv3-ea961-fe1410"}, {"t": "pt", "text": "Functions of taxation: raise revenue, discourage harmful goods, redistribute income, manage the economy", "id": "acfab-rv3-ea961-e38ff6"}, {"t": "def", "term": "Direct tax", "text": "Paid direct to the revenue authority by the person who bears it (eg income tax, corporation tax)", "id": "acfab-rv3-ea961-ce77df"}, {"t": "def", "term": "Indirect tax", "text": "Collected by an intermediary (eg sales tax) and passed on in prices", "id": "acfab-rv3-ea961-dd8150"}, {"t": "pt", "k": 1, "text": "Progressive tax takes a higher proportion of a higher income; proportional takes the same proportion; regressive takes a higher proportion of a poor person's income (eg TV licence, road tax)", "id": "acfab-rv3-ea961-f4f205"}, {"t": "pt", "text": "Monetary targets: the money supply (monetarists), interest rates, the exchange rate", "id": "acfab-rv3-ea961-c26487"}, {"t": "pt", "text": "A falling exchange rate makes exports cheaper and imports dearer", "id": "acfab-rv3-ea961-dcdc42"}, {"t": "pt", "text": "Leading indicators move before the economy changes; lagging indicators after", "id": "acfab-rv3-ea961-f42002"}, {"t": "pt", "text": "Government also influences commercial decisions (grants, competition rules) and operational decisions (health and safety, employment, consumer, tax law)", "id": "acfab-rv3-ea961-767e4c"}], "id": "acfab-rv3-ea961"}, {"kind": "concept", "title": "Balance of payments", "page": [79, 80], "items": [{"t": "pt", "k": 1, "text": "Current account (trade in goods, trade in services, income, current transfers) + capital and financial account (external assets and liabilities, including official financing)", "id": "acfab-rv3-d09bf-ecc445"}, {"t": "pt", "k": 1, "text": "A surplus or deficit on the balance of payments usually means a surplus or deficit on the CURRENT account", "id": "acfab-rv3-d09bf-c7f016"}, {"t": "pt", "text": "Equilibrium: over a period of years the exchange rate is stable and autonomous credits and debits are equal", "id": "acfab-rv3-d09bf-4ba170"}, {"t": "pt", "text": "Correcting a current account deficit", "kids": [{"t": "pt", "text": "Depreciation/devaluation of the currency (expenditure switching)", "id": "acfab-rv3-d09bf-257439"}, {"t": "pt", "text": "Direct controls: tariffs, quotas, exchange controls (expenditure switching)", "id": "acfab-rv3-d09bf-45280b"}, {"t": "pt", "text": "Domestic deflation to reduce aggregate demand (expenditure reducing)", "id": "acfab-rv3-d09bf-df61f4"}], "id": "acfab-rv3-d09bf-5d737f"}, {"t": "exam", "text": "Do not confuse the balance of payments with the government Budget", "id": "acfab-rv3-d09bf-55464a"}, {"t": "exam", "text": "A trade surplus or deficit is NOT a 'profit' or 'loss' for the country", "id": "acfab-rv3-d09bf-d30c4e"}], "id": "acfab-rv3-d09bf"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "The examiner can set detailed questions on this chapter even though it seems peripheral", "id": "acfab-rv3-308d8-70b746"}, {"t": "exam", "text": "Know which items are withdrawals (savings, tax, imports) and which are injections (investment, government spending, exports)", "id": "acfab-rv3-308d8-ff475f"}, {"t": "exam", "text": "Distinguish demand pull from cost push inflation in a scenario", "id": "acfab-rv3-308d8-c718ca"}, {"t": "exam", "text": "Know which policy is fiscal (tax/spending) and which is monetary (interest rates/money supply)", "id": "acfab-rv3-308d8-81744c"}], "id": "acfab-rv3-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calling exports a withdrawal - exports are an injection; imports are a withdrawal", "id": "acfab-rv3-6483a-f7288f"}, {"t": "x", "text": "Confusing the balance of payments deficit with the government's budget deficit", "id": "acfab-rv3-6483a-e78c1f"}, {"t": "x", "text": "Thinking frictional unemployment is long-term - it is temporary", "id": "acfab-rv3-6483a-513d62"}, {"t": "x", "text": "Treating a regressive tax as one with falling rates - it is one that takes a larger share of a lower income", "id": "acfab-rv3-6483a-7d1493"}], "id": "acfab-rv3-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Circular flow: expenditure = output = income", "id": "acfab-rv3-80e78-14ac02"}, {"t": "pt", "text": "Withdrawals: savings, taxation, imports; injections: investment, government spending, exports", "id": "acfab-rv3-80e78-24e929"}, {"t": "pt", "text": "Multiplier: an injection raises national income by more than the injection", "id": "acfab-rv3-80e78-5263cb"}, {"t": "pt", "text": "AD = C + I + G + (X - M); equilibrium where AD = AS", "id": "acfab-rv3-80e78-952942"}, {"t": "pt", "text": "Inflationary gap at full employment; deflationary gap with unemployment", "id": "acfab-rv3-80e78-56f75d"}, {"t": "pt", "text": "Stagflation = high inflation + high unemployment + low growth", "id": "acfab-rv3-80e78-01e7e4"}, {"t": "pt", "text": "Business cycle: recession, depression, recovery, boom", "id": "acfab-rv3-80e78-d4300f"}, {"t": "pt", "text": "Inflation causes: demand pull, cost push, imports, expectations, money supply", "id": "acfab-rv3-80e78-74f3b5"}, {"t": "pt", "text": "Unemployment rate = unemployed / total workforce x 100%", "id": "acfab-rv3-80e78-8f7940"}, {"t": "pt", "text": "Unemployment types: real wage, frictional, seasonal, structural, technological, cyclical", "id": "acfab-rv3-80e78-6fd54e"}, {"t": "pt", "text": "Growth = increase in real GNP per head", "id": "acfab-rv3-80e78-9b8e6b"}, {"t": "pt", "text": "Fiscal = tax, borrowing, spending; monetary = money supply, interest rates, credit", "id": "acfab-rv3-80e78-08e23c"}, {"t": "pt", "text": "Progressive / proportional / regressive taxes", "id": "acfab-rv3-80e78-28e120"}, {"t": "pt", "text": "Deficit cures: devaluation and import controls (switching), deflation (reducing)", "id": "acfab-rv3-80e78-745ee0"}], "id": "acfab-rv3-80e78"}], "source": "BPP Workbook ch 3: sections 1-11 pp58-80; chapter roundup p81", "summary": "The national economy: circular flow, aggregate demand and supply, the business cycle, inflation, unemployment, growth, fiscal and monetary policy and the balance of payments.", "id": "acfab-rv3", "updated": "2026-11-12"}, {"num": "4", "title": "Microeconomic Factors", "pages": [85, 122], "syllabus": "A4", "status": "published", "branches": [{"kind": "concept", "title": "Micro environment and markets", "page": [86, 90], "items": [{"t": "def", "k": 1, "term": "Micro environment", "text": "The immediate operational environment: suppliers, competitors, customers, stakeholders and intermediaries", "id": "acfab-rv4-a19c6-708daa"}, {"t": "pt", "k": 1, "text": "In a free market the price mechanism signals demand and supply conditions to producers and consumers", "id": "acfab-rv4-a19c6-34e788"}, {"t": "def", "term": "Market", "text": "The buyers and sellers of a good who influence its price (markets may be local or worldwide, eg oil, wheat, copper)", "id": "acfab-rv4-a19c6-2234cb"}, {"t": "def", "term": "Utility", "text": "The satisfaction or benefit a person derives from consuming goods; marginal utility = extra satisfaction from one more unit", "id": "acfab-rv4-a19c6-43675f"}, {"t": "pt", "text": "Consumer rationality assumption: prefers more to less, trades off between goods, diminishing marginal utility", "id": "acfab-rv4-a19c6-f2c9a2"}], "id": "acfab-rv4-a19c6"}, {"kind": "concept", "title": "Demand", "page": [91, 102], "items": [{"t": "def", "k": 1, "term": "Demand", "text": "The quantity of a good that potential purchasers would be willing AND able to buy at any possible price", "id": "acfab-rv4-849d1-baf25b"}, {"t": "pt", "k": 1, "text": "Demand curve slopes downwards: lower price -> higher quantity demanded", "id": "acfab-rv4-849d1-4fd4a2"}, {"t": "pt", "text": "Conditions of demand (shift the curve): tastes and fashion, household income, prices of substitutes and complements, income distribution, expectations, population", "id": "acfab-rv4-849d1-455a6f"}, {"t": "def", "term": "Substitutes", "text": "Alternatives to each other - a price rise in one increases demand for the other", "id": "acfab-rv4-849d1-3eeb37"}, {"t": "def", "term": "Complements", "text": "Goods bought together (eg cars and petrol) - a price rise in one reduces demand for the other", "id": "acfab-rv4-849d1-fcea0a"}, {"t": "exam", "text": "Movement ALONG the demand curve is caused only by a change in the good's own price (expansion/contraction); a SHIFT of the curve is caused by a change in any other condition of demand", "id": "acfab-rv4-849d1-b8fea1"}], "id": "acfab-rv4-849d1"}, {"kind": "formula", "title": "Elasticity of demand", "page": [95, 100], "items": [{"t": "f", "k": 1, "term": "Price elasticity of demand (PED)", "text": "% change in quantity demanded / % change in price", "vars": "usually negative - ignore the minus sign; >1 elastic, <1 inelastic", "eg": "Price $1.20 -> $1.30, demand 800,000 -> 730,000: arc PED = 9.15% / 8% = 1.14 (elastic)", "id": "acfab-rv4-0e26e-210d33"}, {"t": "f", "term": "Arc elasticity", "text": "Change in Q / average Q  ÷  change in P / average P", "vars": "averages over the range of price and quantity", "eg": "$1.40 -> $1.60, 220,000 -> 200,000: 9.52% / 13.33% = 0.71 (inelastic)", "id": "acfab-rv4-0e26e-e65014"}, {"t": "f", "term": "Point elasticity", "text": "Change in Q / original Q  ÷  change in P / original P", "vars": "measured at the starting point; assume a straight-line demand curve", "eg": "At $1.40: 9.09% / 14.29% = 0.64", "id": "acfab-rv4-0e26e-3fd157"}, {"t": "f", "k": 1, "term": "Income elasticity of demand", "text": "% change in quantity demanded / % change in household income", "vars": ">1 income elastic (luxury); 0-1 income inelastic (necessity); negative = inferior good", "id": "acfab-rv4-0e26e-aaf8e1"}, {"t": "f", "k": 1, "term": "Cross elasticity of demand", "text": "% change in quantity demanded of good A / % change in price of good B", "vars": "positive = substitutes; negative = complements", "id": "acfab-rv4-0e26e-f20dad"}, {"t": "pt", "text": "Revenue link: if demand is elastic, a price rise REDUCES total revenue; if inelastic, a price rise INCREASES total revenue", "id": "acfab-rv4-0e26e-5458d9"}, {"t": "exam", "text": "Know how to calculate each elasticity and how to tell complements from substitutes from the sign of cross elasticity", "id": "acfab-rv4-0e26e-2e35b4"}], "id": "acfab-rv4-0e26e"}, {"kind": "concept", "title": "Supply", "page": [103, 107], "items": [{"t": "pt", "k": 1, "text": "Supply curve shows the quantity producers would supply at each price - slopes upwards", "id": "acfab-rv4-aaf9a-c9b116"}, {"t": "pt", "text": "Profit maximisers produce where marginal cost = marginal revenue; the MC curve is the supply curve", "id": "acfab-rv4-aaf9a-e8931a"}, {"t": "exam", "text": "In the SHORT run a firm keeps producing if price > average VARIABLE cost, even if price < average total cost", "id": "acfab-rv4-aaf9a-0ee213"}, {"t": "pt", "text": "Factors affecting supply: costs of production, prices of other goods, technology, expectations, number of suppliers, taxes and subsidies", "id": "acfab-rv4-aaf9a-23ac38"}, {"t": "exam", "text": "As with demand, distinguish a movement along the supply curve (own price) from a shift (other conditions)", "id": "acfab-rv4-aaf9a-005235"}], "id": "acfab-rv4-aaf9a"}, {"kind": "concept", "title": "Equilibrium price and price controls", "page": [108, 115], "items": [{"t": "def", "k": 1, "term": "Equilibrium price", "text": "The price at which the volume demanded equals the volume firms are willing to supply - the market clearing price (no surplus, no shortage)", "id": "acfab-rv4-cdbff-a2a791"}, {"t": "pt", "text": "Functions of the price mechanism: signals, incentives, rationing", "id": "acfab-rv4-cdbff-bc2fc9"}, {"t": "pt", "text": "Consumer surplus = what consumers would pay minus what they pay; producer surplus = price received minus minimum acceptable price", "id": "acfab-rv4-cdbff-ab5deb"}, {"t": "pt", "k": 1, "text": "Maximum price (ceiling) must be set BELOW equilibrium to have effect -> excess demand, rationing, black markets", "id": "acfab-rv4-cdbff-6ea72d"}, {"t": "pt", "k": 1, "text": "Minimum price (floor) must be set ABOVE equilibrium to have effect -> excess supply", "id": "acfab-rv4-cdbff-961052"}, {"t": "pt", "text": "Minimum wage = floor price in the labour market; may cause unemployment if set above market clearing level", "id": "acfab-rv4-cdbff-e91abc"}, {"t": "eg", "text": "Petrol and second-hand cars are complements: higher petrol prices reduce demand for large cars", "id": "acfab-rv4-cdbff-bba08e"}], "id": "acfab-rv4-cdbff"}, {"kind": "compare", "title": "Types of competition", "page": [116, 117], "items": [{"t": "table", "rows": [["Market type", "Number of firms", "Product", "Barriers to entry"], ["Perfect competition", "Many", "Homogeneous; perfect knowledge", "None - easy entry and exit; demand perfectly elastic"], ["Monopolistic competition", "Many", "Differentiated (seen as unique)", "Low"], ["Oligopoly", "Few large firms", "Similar or differentiated", "High"], ["Monopoly", "One", "No close substitutes", "Very high"]], "id": "acfab-rv4-1278f-ccdc5d"}, {"t": "pt", "text": "Restrictive practices: dumping (selling at a loss), exclusive dealing, price fixing, refusal to deal, limit pricing, retail price maintenance, unfair government subsidies", "id": "acfab-rv4-1278f-01781a"}], "id": "acfab-rv4-1278f"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calling a change in a good's own price a 'shift' in the demand curve - it is a movement along it", "id": "acfab-rv4-6483a-b4ff9a"}, {"t": "x", "text": "Forgetting to ignore the minus sign when classifying PED as elastic or inelastic", "id": "acfab-rv4-6483a-295df8"}, {"t": "x", "text": "Using original values in an ARC calculation - arc uses averages, point uses the starting values", "id": "acfab-rv4-6483a-c35c02"}, {"t": "x", "text": "Setting a maximum price above equilibrium and expecting shortages - it has no effect there", "id": "acfab-rv4-6483a-0fd995"}, {"t": "x", "text": "Reading a positive cross elasticity as complements - positive means substitutes", "id": "acfab-rv4-6483a-6d9221"}], "id": "acfab-rv4-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Micro environment = suppliers, competitors, customers, stakeholders, intermediaries", "id": "acfab-rv4-80e78-c85e11"}, {"t": "pt", "text": "Demand = willing AND able to buy", "id": "acfab-rv4-80e78-bf65d8"}, {"t": "pt", "text": "Own price change = movement along; other conditions = shift", "id": "acfab-rv4-80e78-d4b0dc"}, {"t": "pt", "text": "PED = %ΔQ / %ΔP; >1 elastic, <1 inelastic", "id": "acfab-rv4-80e78-1e822e"}, {"t": "pt", "text": "Arc elasticity uses averages; point elasticity uses starting values", "id": "acfab-rv4-80e78-597b3f"}, {"t": "pt", "text": "Income elasticity > 1 luxury, 0-1 necessity, < 0 inferior", "id": "acfab-rv4-80e78-090d89"}, {"t": "pt", "text": "Cross elasticity: + substitutes, - complements", "id": "acfab-rv4-80e78-ee2e75"}, {"t": "pt", "text": "Elastic demand: price rise reduces revenue", "id": "acfab-rv4-80e78-18e7c3"}, {"t": "pt", "text": "Short run: produce if price > average variable cost", "id": "acfab-rv4-80e78-abeb44"}, {"t": "pt", "text": "Equilibrium = market clearing price", "id": "acfab-rv4-80e78-1a31d7"}, {"t": "pt", "text": "Maximum price below equilibrium -> shortages; minimum price above equilibrium -> surplus", "id": "acfab-rv4-80e78-2d114a"}, {"t": "pt", "text": "Perfect competition: many firms, homogeneous product, perfect knowledge, free entry", "id": "acfab-rv4-80e78-ed5184"}, {"t": "pt", "text": "Monopolistic competition relies on product differentiation", "id": "acfab-rv4-80e78-ff823e"}], "id": "acfab-rv4-80e78"}], "source": "BPP Workbook ch 4: sections 1-9 pp86-117; worked examples pp95-98; chapter roundup p118", "summary": "Markets and the price mechanism: demand, supply, elasticities, equilibrium price, price controls, types of competition and restrictive practices.", "id": "acfab-rv4", "updated": "2026-11-12"}, {"num": "5", "title": "Business Organisation, Structure and Strategy", "pages": [123, 144], "syllabus": "B1", "status": "published", "branches": [{"kind": "concept", "title": "The informal organisation", "page": [124, 126], "items": [{"t": "def", "k": 1, "term": "Informal organisation", "text": "Social relationships, informal communication networks, behavioural norms and power/influence structures that exist alongside the formal organisation and may 'by-pass' it", "id": "acfab-rv5-2ecd9-1e7197"}, {"t": "pt", "text": "It can be beneficial or detrimental depending on how it is managed", "id": "acfab-rv5-2ecd9-121b34"}, {"t": "pt", "text": "Benefits: employee commitment (social needs met), knowledge sharing, speed (grapevine), co-operation, a source of ideas", "id": "acfab-rv5-2ecd9-14c2d3"}, {"t": "pt", "text": "Problems: goals unrelated to the organisation's, rumour, resistance to change, 'us and them'", "id": "acfab-rv5-2ecd9-906c78"}, {"t": "def", "term": "Group norms", "text": "Acceptable levels and methods of behaviour to which all group members are expected to conform", "id": "acfab-rv5-2ecd9-e776aa"}, {"t": "pt", "text": "Hawthorne Studies (human relations school): group attitudes and norms affect output more than physical conditions", "id": "acfab-rv5-2ecd9-99146a"}], "id": "acfab-rv5-2ecd9"}, {"kind": "concept", "title": "Mintzberg's components and structures", "page": [126, 128], "items": [{"t": "pt", "k": 1, "text": "Five components: strategic apex • middle line • operating core • technostructure • support staff", "id": "acfab-rv5-22fe1-f0dcce"}, {"t": "pt", "text": "Each component 'pulls' the organisation towards a structure", "id": "acfab-rv5-22fe1-86689b"}, {"t": "pt", "k": 1, "text": "Mintzberg's five structures", "kids": [{"t": "pt", "text": "Simple structure: centralised, often autocratic, power at the strategic apex (the apex pulls to centralise)", "id": "acfab-rv5-22fe1-db742f"}, {"t": "pt", "text": "Machine bureaucracy: relies on the technostructure; planners and controllers; formal rules; many layers", "id": "acfab-rv5-22fe1-1d5fdf"}, {"t": "pt", "text": "Professional bureaucracy: standards set by professions/regulation; operating core of skilled professionals (eg accountancy firm, hospital)", "id": "acfab-rv5-22fe1-bb59d1"}, {"t": "pt", "text": "Divisionalised: small central core, autonomous business units; the middle line co-ordinates", "id": "acfab-rv5-22fe1-5eba2f"}, {"t": "pt", "text": "Adhocracy: task or project-based, responds quickly to change and innovation", "id": "acfab-rv5-22fe1-00ee37"}], "id": "acfab-rv5-22fe1-4c2ba7"}, {"t": "exam", "text": "ACCA articles flagged: 'Mintzberg's theory on organisations' and 'Organisations'", "id": "acfab-rv5-22fe1-af397c"}], "id": "acfab-rv5-22fe1"}, {"kind": "compare", "title": "Forms of departmentation", "page": [128, 133], "items": [{"t": "table", "rows": [["Basis", "How work is grouped", "Main benefit", "Main drawback"], ["Functional", "Production, marketing, finance etc", "Specialist expertise, economies of scale", "Silo thinking, slow cross-function co-ordination"], ["Geographic", "Region or country", "Local knowledge and responsiveness", "Duplication of functions"], ["Product / brand", "Product lines or brands", "Accountability for each product", "Duplication; rivalry between products"], ["Customer", "Market segment or customer type", "Focus on customer needs", "Duplication; boundary disputes"], ["Matrix", "Crosses functional and product/project lines", "Flexibility; dual focus", "Dual authority, possible conflict and confusion"]], "id": "acfab-rv5-8de3e-7e7882"}, {"t": "def", "k": 1, "term": "Divisionalisation", "text": "The division of a business into autonomous regions or product businesses, each with its own revenues, expenditures and capital asset base", "id": "acfab-rv5-8de3e-b6d8f7"}, {"t": "pt", "text": "Hybrid structures mix types (eg functional head office plus geographic sales)", "id": "acfab-rv5-8de3e-3228d9"}, {"t": "exam", "text": "In a matrix, someone selling product X in country A reports to BOTH the product X manager and the country A manager", "id": "acfab-rv5-8de3e-c68bed"}], "id": "acfab-rv5-8de3e"}, {"kind": "concept", "title": "Spans of control, delayering and new structures", "page": [134, 138], "items": [{"t": "def", "k": 1, "term": "Span of control", "text": "The number of subordinates immediately responsible to a superior", "id": "acfab-rv5-639d1-a613d9"}, {"t": "pt", "k": 1, "text": "Tall organisations: many management levels, narrow spans; flat organisations: fewer levels, wider spans", "id": "acfab-rv5-639d1-0ad33f"}, {"t": "pt", "text": "Factors allowing a wider span: capable subordinates, routine work, good communications and IT, physically close team", "id": "acfab-rv5-639d1-8582a4"}, {"t": "def", "k": 1, "term": "Delayering", "text": "The reduction of the number of management levels from bottom to top - middle-line jobs vanish", "id": "acfab-rv5-639d1-227788"}, {"t": "pt", "text": "New organisation trends: flat structures, horizontal (process) structures, chunked units, outsourcing, flexibility", "id": "acfab-rv5-639d1-0dea28"}, {"t": "pt", "text": "Outsourcing removes whole functions from the structure; offshoring moves them abroad", "id": "acfab-rv5-639d1-9ad478"}, {"t": "def", "term": "Shared services approach", "text": "A single service centre provides a support function (eg finance, HR, IT) across the whole organisation", "id": "acfab-rv5-639d1-4c2519"}], "id": "acfab-rv5-639d1"}, {"kind": "concept", "title": "Levels of strategy", "page": [138, 140], "items": [{"t": "pt", "k": 1, "text": "Corporate strategy: the general direction of the whole organisation - what businesses it is in", "id": "acfab-rv5-addbc-c0c300"}, {"t": "pt", "k": 1, "text": "Business strategy: how the organisation or its strategic business units (SBUs) tackle particular product markets", "id": "acfab-rv5-addbc-870cf4"}, {"t": "pt", "k": 1, "text": "Functional/operational strategy: specific strategies for departments (R&D, purchasing, production, marketing, HR, finance)", "id": "acfab-rv5-addbc-0b9599"}, {"t": "pt", "text": "Anthony hierarchy: strategic management (senior: direction) -> tactical management (middle: efficient use of resources) -> operational management (supervisors: day-to-day tasks)", "id": "acfab-rv5-addbc-18befa"}, {"t": "exam", "text": "The Study Guide stresses the separation between direction setting and day-to-day management", "id": "acfab-rv5-addbc-c70dea"}], "id": "acfab-rv5-addbc"}, {"kind": "compare", "title": "Centralisation vs decentralisation", "page": [141, 141], "items": [{"t": "table", "rows": [["Pro centralisation", "Pro decentralisation"], ["Decisions easier to co-ordinate", "Avoids overburdening top managers"], ["Senior managers take a wider view", "Motivates junior managers given responsibility"], ["Balances interests of different functions", "Better awareness of local problems"], ["Decision quality from senior experience", "Faster decisions and responses"], ["Possibly cheaper - fewer managers", "Develops junior managers - succession"], ["Crisis decisions taken quickly at the centre", "Separate responsibility areas improve control and accountability"], ["Standardised policies and procedures", "Communications technology lets decisions be made locally"]], "id": "acfab-rv5-5a498-75a9af"}, {"t": "def", "k": 1, "term": "Centralisation", "text": "An organisation in which authority is concentrated in one place", "id": "acfab-rv5-5a498-eb1a47"}, {"t": "pt", "k": 1, "text": "Centralisation offers greater control and co-ordination; decentralisation offers greater flexibility", "id": "acfab-rv5-5a498-2db1f3"}], "id": "acfab-rv5-5a498"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Questions require you to APPLY structure concepts to a short scenario (eg identify a professional bureaucracy)", "id": "acfab-rv5-308d8-7a9286"}, {"t": "exam", "text": "Know which Mintzberg component pulls towards which structure (apex -> simple; technostructure -> machine bureaucracy)", "id": "acfab-rv5-308d8-e78ab9"}, {"t": "exam", "text": "Delayering = fewer levels, wider spans - not the same as outsourcing", "id": "acfab-rv5-308d8-2ebc7c"}], "id": "acfab-rv5-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Thinking the informal organisation is always harmful - it can benefit the organisation if managed", "id": "acfab-rv5-6483a-af3fe3"}, {"t": "x", "text": "Confusing the technostructure (planners, analysts) with support staff (canteen, legal, PR)", "id": "acfab-rv5-6483a-73932b"}, {"t": "x", "text": "Saying a tall structure has wide spans of control - tall means narrow spans and many levels", "id": "acfab-rv5-6483a-173f2a"}, {"t": "x", "text": "Mixing up business strategy (one market/SBU) with corporate strategy (whole organisation)", "id": "acfab-rv5-6483a-01e4d2"}], "id": "acfab-rv5-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Informal organisation = relationships, grapevine, norms, influence - beneficial or harmful", "id": "acfab-rv5-80e78-27a7b6"}, {"t": "pt", "text": "Mintzberg components: strategic apex, middle line, operating core, technostructure, support staff", "id": "acfab-rv5-80e78-c434a5"}, {"t": "pt", "text": "Structures: simple, machine bureaucracy, professional bureaucracy, divisionalised, adhocracy", "id": "acfab-rv5-80e78-7d3178"}, {"t": "pt", "text": "Departmentation: functional, geographic, product/brand, customer, matrix, hybrid", "id": "acfab-rv5-80e78-5bb3a5"}, {"t": "pt", "text": "Matrix = dual reporting lines", "id": "acfab-rv5-80e78-1d01d1"}, {"t": "pt", "text": "Divisions are autonomous with their own revenue, costs and assets", "id": "acfab-rv5-80e78-c80b29"}, {"t": "pt", "text": "Span of control = number of direct subordinates", "id": "acfab-rv5-80e78-fec58f"}, {"t": "pt", "text": "Tall = narrow spans, many levels; flat = wide spans, few levels", "id": "acfab-rv5-80e78-aac924"}, {"t": "pt", "text": "Delayering removes management levels", "id": "acfab-rv5-80e78-c20cbc"}, {"t": "pt", "text": "Shared services = one centre serves the whole organisation", "id": "acfab-rv5-80e78-7b3d70"}, {"t": "pt", "text": "Strategy levels: corporate, business, functional/operational", "id": "acfab-rv5-80e78-33109a"}, {"t": "pt", "text": "Anthony: strategic, tactical, operational", "id": "acfab-rv5-80e78-274b3b"}, {"t": "pt", "text": "Centralisation = control and co-ordination; decentralisation = flexibility and speed", "id": "acfab-rv5-80e78-d70bfb"}], "id": "acfab-rv5-80e78"}], "source": "BPP Workbook ch 5: sections 1-4 pp124-141; chapter roundup p142", "summary": "The informal organisation, Mintzberg's components and structures, forms of departmentation, spans of control, delayering, outsourcing, levels of strategy and centralisation versus decentralisation.", "id": "acfab-rv5", "updated": "2026-11-12"}, {"num": "6", "title": "Organisational Culture and Committees", "pages": [145, 176], "syllabus": "B2, B3", "status": "published", "branches": [{"kind": "concept", "title": "Business functions", "page": [147, 153], "items": [{"t": "pt", "k": 1, "text": "Research may be pure, applied or development; product research (the 'offer') vs process research (how it is made)", "id": "acfab-rv6-876c1-1a31ce"}, {"t": "pt", "text": "R&D should support strategy and be closely co-ordinated with marketing", "id": "acfab-rv6-876c1-0a9c0f"}, {"t": "pt", "k": 1, "text": "Purchasing mix: quantity • quality • price • delivery", "id": "acfab-rv6-876c1-afb8ea"}, {"t": "pt", "text": "Purchasing affects profit through value for money, quality of inputs and reliable supply", "id": "acfab-rv6-876c1-704c8f"}, {"t": "pt", "text": "Production plans, organises, directs and controls activities that add value; long-term decisions (equipment, location, job design) and short-term ones (scheduling, inventory)", "id": "acfab-rv6-876c1-ed4d64"}, {"t": "pt", "k": 1, "text": "Services are intangible, cannot be stored (perishable), are variable in quality and give no transfer of property - so people and processes matter most", "id": "acfab-rv6-876c1-5a7b88"}, {"t": "pt", "text": "Administration: centralised admin gives consistency and economies but makes local offices dependent and slower", "id": "acfab-rv6-876c1-10afc3"}, {"t": "pt", "text": "Finance function: financial accounting, treasury management, working capital, management accounting, raising finance, a role in strategic planning", "id": "acfab-rv6-876c1-522114"}, {"t": "pt", "text": "HRM: 'the most effective use of human resources' - organisation, staffing levels, motivation, employee relations, employee services; HR cycle (Fombrun): selection -> performance -> appraisal -> rewards and development", "id": "acfab-rv6-876c1-d3fcb3"}], "id": "acfab-rv6-876c1"}, {"kind": "concept", "title": "Marketing", "page": [152, 156], "items": [{"t": "def", "k": 1, "term": "Marketing", "text": "'The management process which identifies, anticipates and satisfies customer requirements profitably' (Chartered Institute of Marketing)", "id": "acfab-rv6-c769c-c88696"}, {"t": "pt", "text": "Marketing orientations", "kids": [{"t": "pt", "text": "Production orientation: customers will buy whatever we produce", "id": "acfab-rv6-c769c-9c13b1"}, {"t": "pt", "text": "Product orientation: customers want the best quality product", "id": "acfab-rv6-c769c-326fbb"}, {"t": "pt", "text": "Sales orientation: customers must be persuaded to buy", "id": "acfab-rv6-c769c-3596a7"}, {"t": "pt", "k": 1, "text": "Marketing orientation: find out what customers need and supply it", "id": "acfab-rv6-c769c-f81cc6"}], "id": "acfab-rv6-c769c-cbcc0a"}, {"t": "pt", "k": 1, "text": "Marketing mix (4Ps): product, price, place, promotion (services add people, processes, physical evidence)", "id": "acfab-rv6-c769c-dbed45"}, {"t": "pt", "text": "The ideal mix balances all elements - one element is ineffective without the others", "id": "acfab-rv6-c769c-332241"}, {"t": "def", "term": "Market segmentation", "text": "Dividing the market into segments whose customers share common needs and preferences", "id": "acfab-rv6-c769c-a9149a"}, {"t": "exam", "text": "ACCA article flagged: 'The role of marketing'", "id": "acfab-rv6-c769c-11eef7"}], "id": "acfab-rv6-c769c"}, {"kind": "concept", "title": "Culture", "page": [163, 166], "items": [{"t": "def", "k": 1, "term": "Culture", "text": "'The collective programming of the mind which distinguishes the members of one category of people from another' (Hofstede)", "id": "acfab-rv6-3f703-fd1bbf"}, {"t": "def", "k": 1, "term": "Organisation culture", "text": "'The way we do things round here' (Schein)", "id": "acfab-rv6-3f703-3b523c"}, {"t": "pt", "k": 1, "text": "Elements (Schein's levels): observable behaviour and artefacts • underlying values and beliefs • hidden basic assumptions", "id": "acfab-rv6-3f703-52a1f6"}, {"t": "pt", "text": "What shapes culture: the founder, history, leadership, industry, size, technology, the people employed", "id": "acfab-rv6-3f703-3e5837"}, {"t": "pt", "text": "Uses: values guide behaviour without tight control, motivate staff, drive (or block) change", "id": "acfab-rv6-3f703-a56a37"}], "id": "acfab-rv6-3f703"}, {"kind": "compare", "title": "Handy's four cultures", "page": [166, 167], "items": [{"t": "table", "rows": [["Culture", "Deity", "Shaped by", "Typical setting"], ["Power (club)", "Zeus", "One central individual, snap decisions", "Small entrepreneurial firm"], ["Role", "Apollo", "Rationality, rules and procedures (bureaucracy)", "Large stable organisations, civil service"], ["Task", "Athena", "Outputs and results; expertise valued", "Project teams, consultancies"], ["Person (existential)", "Dionysus", "Interests of the individuals", "Professional partnerships, barristers' chambers"]], "id": "acfab-rv6-8b348-20baa4"}, {"t": "exam", "text": "Do not neglect the key link between culture and structure", "id": "acfab-rv6-8b348-e0686d"}, {"t": "pt", "text": "A contingency approach: cultures do not map exactly onto organisation types; different parts may have different cultures", "id": "acfab-rv6-8b348-3042fe"}], "id": "acfab-rv6-8b348"}, {"kind": "concept", "title": "Hofstede's national culture model", "page": [168, 169], "items": [{"t": "pt", "k": 1, "text": "Four dimensions: power distance • uncertainty avoidance • individualism/collectivism • masculinity/femininity", "id": "acfab-rv6-3db22-1c98b5"}, {"t": "pt", "text": "Power distance: how far unequal distribution of power is accepted", "id": "acfab-rv6-3db22-777c56"}, {"t": "pt", "text": "Uncertainty avoidance: preference for structure and rules vs comfort with ambiguity", "id": "acfab-rv6-3db22-c575cc"}, {"t": "pt", "text": "Individualism vs collectivism: looking after oneself vs loyalty to the group", "id": "acfab-rv6-3db22-5dc142"}, {"t": "pt", "text": "Masculinity vs femininity: assertive, achievement-focused vs caring, quality of life", "id": "acfab-rv6-3db22-2efc39"}, {"t": "pt", "text": "Research based on IBM offices worldwide; used to explain how national culture shapes management practices", "id": "acfab-rv6-3db22-d57d02"}], "id": "acfab-rv6-3db22"}, {"kind": "concept", "title": "Committees", "page": [170, 172], "items": [{"t": "pt", "text": "Purposes: creating ideas, communication, co-ordination, consultation, decision-making, delegation", "id": "acfab-rv6-3582f-445943"}, {"t": "pt", "text": "Types: executive (power to govern, eg board), standing (permanent, regular), ad hoc / special (one task), sub-committee, joint (employer-employee)", "id": "acfab-rv6-3582f-379325"}, {"t": "pt", "k": 1, "text": "Advantages: pooled authority, wider range of views, participation and motivation, co-ordination", "id": "acfab-rv6-3582f-ce5cda"}, {"t": "pt", "k": 1, "text": "Disadvantages: slow and costly, too large for constructive action, compromise decisions, diluted responsibility", "id": "acfab-rv6-3582f-bbba05"}, {"t": "pt", "text": "Chair: leads, keeps order, ensures all are heard; Secretary: arranges meetings, agenda, minutes and action points", "id": "acfab-rv6-3582f-a583dc"}, {"t": "def", "term": "Quorum", "text": "The minimum number of members that must attend for business to be conducted - usually over 50% of members", "id": "acfab-rv6-3582f-33c968"}, {"t": "pt", "text": "Success factors: clear written authority and purpose, good chair, manageable size, skilled members, minutes circulated, benefits justify cost", "id": "acfab-rv6-3582f-5c2309"}], "id": "acfab-rv6-3582f"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Mixing up Handy's deities - Zeus power, Apollo role, Athena task, Dionysus person", "id": "acfab-rv6-6483a-ac821e"}, {"t": "x", "text": "Listing 'profit' as a Hofstede dimension - the four are power distance, uncertainty avoidance, individualism, masculinity", "id": "acfab-rv6-6483a-133ef8"}, {"t": "x", "text": "Thinking a marketing orientation means pushing sales - sales orientation is persuasion; marketing orientation starts from customer needs", "id": "acfab-rv6-6483a-20faae"}, {"t": "x", "text": "Forgetting that services cannot be stored - inventory is not an option", "id": "acfab-rv6-6483a-8ab554"}], "id": "acfab-rv6-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Purchasing mix: quantity, quality, price, delivery", "id": "acfab-rv6-80e78-cbcfab"}, {"t": "pt", "text": "Services: intangible, perishable, variable, no transfer of ownership", "id": "acfab-rv6-80e78-fe07a1"}, {"t": "pt", "text": "Marketing = identify, anticipate and satisfy customer needs profitably", "id": "acfab-rv6-80e78-c1c4a7"}, {"t": "pt", "text": "Orientations: production, product, sales, marketing", "id": "acfab-rv6-80e78-7ce1ad"}, {"t": "pt", "text": "4Ps: product, price, place, promotion (+ people, processes, physical evidence)", "id": "acfab-rv6-80e78-656194"}, {"t": "pt", "text": "Culture (Hofstede) = collective programming of the mind", "id": "acfab-rv6-80e78-dac709"}, {"t": "pt", "text": "Organisation culture (Schein) = the way we do things round here", "id": "acfab-rv6-80e78-2a94fb"}, {"t": "pt", "text": "Culture levels: behaviour/artefacts, values and beliefs, hidden assumptions", "id": "acfab-rv6-80e78-679578"}, {"t": "pt", "text": "Handy: power (Zeus), role (Apollo), task (Athena), person (Dionysus)", "id": "acfab-rv6-80e78-276f3e"}, {"t": "pt", "text": "Hofstede: power distance, uncertainty avoidance, individualism-collectivism, masculinity-femininity", "id": "acfab-rv6-80e78-623497"}, {"t": "pt", "text": "Committee types: executive, standing, ad hoc, sub-committee, joint", "id": "acfab-rv6-80e78-4481dc"}, {"t": "pt", "text": "Quorum usually over 50% of members", "id": "acfab-rv6-80e78-9a1e6b"}, {"t": "pt", "text": "HRM = most effective use of human resources", "id": "acfab-rv6-80e78-b37905"}], "id": "acfab-rv6-80e78"}], "source": "BPP Workbook ch 6: sections 1-5 pp147-172; chapter roundup p173", "summary": "The business functions (R&D, purchasing, production, service, marketing, administration, finance, HR), culture and its models (Schein, Handy, Hofstede) and committees.", "id": "acfab-rv6", "updated": "2026-11-12"}, {"num": "7", "title": "Corporate Governance and Social Responsibility", "pages": [177, 198], "syllabus": "B4, C1", "status": "published", "branches": [{"kind": "concept", "title": "Principles of corporate governance", "page": [178, 181], "items": [{"t": "def", "k": 1, "term": "Corporate governance", "text": "The system by which organisations are directed and controlled by senior officers", "id": "acfab-rv7-59cfb-9bc706"}, {"t": "pt", "k": 1, "text": "Core principles: integrity • accountability • independence • good management", "kids": [{"t": "pt", "text": "Integrity: dealing honestly with employees, customers and all business contacts", "id": "acfab-rv7-59cfb-103c0f"}, {"t": "pt", "text": "Accountability: the business being answerable for its actions", "id": "acfab-rv7-59cfb-125892"}, {"t": "pt", "text": "Independence: independent people within the organisation check compliance with the governance code", "id": "acfab-rv7-59cfb-989741"}, {"t": "pt", "text": "Good management: setting best practice guidelines", "id": "acfab-rv7-59cfb-1b936d"}], "id": "acfab-rv7-59cfb-c86e24"}, {"t": "pt", "text": "Most countries take a principles-based approach ('comply or explain'); the debate is how far principles need detailed rules", "id": "acfab-rv7-59cfb-3e14d5"}, {"t": "pt", "text": "Good governance involves risk management and internal control, accountability to stakeholders, and conducting business ethically and effectively", "id": "acfab-rv7-59cfb-377119"}], "id": "acfab-rv7-59cfb"}, {"kind": "compare", "title": "Governance theories", "page": [180, 180], "items": [{"t": "table", "rows": [["Theory", "View of management", "Governance implication"], ["Agency", "Agents (managers) act for principals (shareholders) but pursue their own interests", "Align interests - eg performance-related pay, monitoring"], ["Stewardship", "Stewards of the owners' assets", "Trust management; focus on accountability"], ["Stakeholder", "The organisation has a life of its own and duties to many groups", "Balance the interests of all stakeholders"]], "id": "acfab-rv7-5ced1-aa99ee"}, {"t": "pt", "k": 1, "text": "Agency concept: shareholders = principal; directors/managers = agents", "id": "acfab-rv7-5ced1-fdce32"}], "id": "acfab-rv7-5ced1"}, {"kind": "concept", "title": "Poor governance: features and risks", "page": [181, 184], "items": [{"t": "pt", "k": 1, "text": "Features of poor governance", "kids": [{"t": "pt", "text": "Domination by a single individual", "id": "acfab-rv7-e49a3-c89519"}, {"t": "pt", "text": "Lack of involvement of the board", "id": "acfab-rv7-e49a3-eb939e"}, {"t": "pt", "text": "Lack of an adequate control function (weak or no internal audit)", "id": "acfab-rv7-e49a3-8d6219"}, {"t": "pt", "text": "Lack of supervision of employees", "id": "acfab-rv7-e49a3-a9d2cd"}, {"t": "pt", "text": "Lack of independent scrutiny (external auditors afraid to lose the audit)", "id": "acfab-rv7-e49a3-a2e82c"}, {"t": "pt", "text": "Lack of contact with shareholders", "id": "acfab-rv7-e49a3-e8dc05"}, {"t": "pt", "text": "Emphasis on short-term profitability (concealment, manipulation)", "id": "acfab-rv7-e49a3-07d336"}, {"t": "pt", "text": "Misleading accounts and information", "id": "acfab-rv7-e49a3-b7c2dd"}], "id": "acfab-rv7-e49a3-4c52c2"}, {"t": "pt", "text": "Ultimate risk: losses large enough to cause bankruptcy; also regulatory closure, fines, loss of reputation", "id": "acfab-rv7-e49a3-bdf4e1"}, {"t": "pt", "text": "Driving forces: scandals and corporate failures from the late 1980s onwards; reports in the US (Sarbanes-Oxley) and UK", "id": "acfab-rv7-e49a3-5bea37"}], "id": "acfab-rv7-e49a3"}, {"kind": "rule", "title": "The board of directors", "page": [184, 188], "items": [{"t": "pt", "k": 1, "text": "The board takes major policy and strategic decisions; directors need a mix of skills; performance assessed regularly", "id": "acfab-rv7-9a559-d4b10f"}, {"t": "pt", "text": "Unitary (one-tier) board vs two-tier board (supervisory + management boards)", "id": "acfab-rv7-9a559-a967ea"}, {"t": "pt", "text": "Chairman: leads the board, ensures it is effective; CEO: leads the executive team and day-to-day management", "id": "acfab-rv7-9a559-c16f74"}, {"t": "pt", "k": 1, "text": "Division of responsibilities is most simply achieved by SEPARATING the roles of chair and chief executive", "id": "acfab-rv7-9a559-795d81"}, {"t": "pt", "text": "Company secretary: chief administrative officer, appointed by the directors", "id": "acfab-rv7-9a559-446113"}, {"t": "pt", "text": "Appointments through formal procedures run by a nomination committee", "id": "acfab-rv7-9a559-262cd5"}, {"t": "pt", "text": "Directors must receive full information; board performance should be appraised (UK Corporate Governance Code, FRC 2018)", "id": "acfab-rv7-9a559-795e40"}, {"t": "def", "k": 1, "term": "Non-executive directors (NEDs)", "text": "Directors with no executive (managerial) responsibilities who are not employees but take part in board decisions", "id": "acfab-rv7-9a559-e6500c"}, {"t": "pt", "text": "NED roles: strategy (challenge), scrutiny (of performance), risk (controls are robust), people (appoint, remunerate, remove executives)", "id": "acfab-rv7-9a559-2e05c3"}, {"t": "pt", "text": "NED benefits: external experience, objectivity, credibility with investors; problems: limited time and information, may lack independence", "id": "acfab-rv7-9a559-b01b4e"}, {"t": "exam", "text": "Watch for threats to NED independence: former employee, material business relationship, cross-directorships, long tenure, share options", "id": "acfab-rv7-9a559-ae4169"}], "id": "acfab-rv7-9a559"}, {"kind": "rule", "title": "Board committees", "page": [188, 189], "items": [{"t": "def", "term": "Standing committee", "text": "A permanent committee of the board (eg remuneration, audit, nomination, risk)", "id": "acfab-rv7-02616-d8fabf"}, {"t": "pt", "k": 1, "text": "Remuneration committee: independent NEDs set directors' pay; pay linked to organisation and individual performance; accounts disclose policy and individual packages", "id": "acfab-rv7-02616-734e5b"}, {"t": "pt", "k": 1, "text": "Audit committee of independent NEDs: liaises with external audit, supervises internal audit, reviews the annual accounts and internal controls", "id": "acfab-rv7-02616-de13b3"}, {"t": "exam", "text": "The Study Guide requires only TWO committees: the remuneration committee and the audit committee", "id": "acfab-rv7-02616-009d31"}], "id": "acfab-rv7-02616"}, {"kind": "concept", "title": "Reporting on governance", "page": [189, 190], "items": [{"t": "pt", "k": 1, "text": "Annual reports must give a fair and balanced view and state whether governance codes have been complied with", "id": "acfab-rv7-04ee9-eda60e"}, {"t": "pt", "text": "Disclosures: how the code's principles were applied, board and committee details, review of internal controls, going concern, relations with stakeholders", "id": "acfab-rv7-04ee9-4df0f7"}], "id": "acfab-rv7-04ee9"}, {"kind": "concept", "title": "Corporate social responsibility", "page": [190, 193], "items": [{"t": "pt", "k": 1, "text": "Two views: the strong stakeholder view (pursue a range of goals) vs the business as a purely economic force subject to law", "id": "acfab-rv7-14eb1-2cbc2d"}, {"t": "def", "k": 1, "term": "Corporate social responsibility", "text": "The set of actions an organisation is not obliged to take, taken for the well-being of stakeholders and the public", "id": "acfab-rv7-14eb1-795e98"}, {"t": "pt", "text": "Strategies: proactive (takes full responsibility), reactive, defence, accommodation", "id": "acfab-rv7-14eb1-b84ba9"}, {"t": "pt", "text": "Milton Friedman: the only responsibility of business is to make profits for shareholders within the law", "id": "acfab-rv7-14eb1-558cb9"}, {"t": "pt", "text": "Interaction: law sets the minimum level of behaviour; society's ethics and CSR pressure, directors' ethics and shareholders' needs all shape corporate governance decisions", "id": "acfab-rv7-14eb1-cb9f02"}, {"t": "x", "text": "Businesses do not necessarily have to act ethically - most are run for the benefit of the owners", "id": "acfab-rv7-14eb1-904bde"}], "id": "acfab-rv7-14eb1"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Combining the chair and CEO roles - best practice separates them", "id": "acfab-rv7-6483a-b658fb"}, {"t": "x", "text": "Thinking NEDs are employees - they have no executive responsibilities", "id": "acfab-rv7-6483a-2b3fa2"}, {"t": "x", "text": "Saying the audit committee prepares the accounts - it reviews them and oversees audit and controls", "id": "acfab-rv7-6483a-868092"}, {"t": "x", "text": "Treating stewardship theory and agency theory as the same - agency assumes self-interest, stewardship assumes trust", "id": "acfab-rv7-6483a-cd2dc6"}], "id": "acfab-rv7-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Corporate governance = system by which organisations are directed and controlled", "id": "acfab-rv7-80e78-2f9568"}, {"t": "pt", "text": "Principles: integrity, accountability, independence, good management", "id": "acfab-rv7-80e78-d4087d"}, {"t": "pt", "text": "Agency: shareholders principal, directors agents", "id": "acfab-rv7-80e78-71db74"}, {"t": "pt", "text": "Poor governance: dominant individual, weak board, weak controls, no scrutiny, short-termism, misleading accounts", "id": "acfab-rv7-80e78-be648c"}, {"t": "pt", "text": "Separate chair and CEO", "id": "acfab-rv7-80e78-a85335"}, {"t": "pt", "text": "NEDs: no executive role; strategy, scrutiny, risk, people", "id": "acfab-rv7-80e78-15d8c1"}, {"t": "pt", "text": "Remuneration committee: independent NEDs set directors' pay", "id": "acfab-rv7-80e78-32be7e"}, {"t": "pt", "text": "Audit committee: external audit liaison, internal audit supervision, review accounts and controls", "id": "acfab-rv7-80e78-6fd338"}, {"t": "pt", "text": "Only remuneration and audit committees are in the Study Guide", "id": "acfab-rv7-80e78-403044"}, {"t": "pt", "text": "Nomination committee runs board appointments", "id": "acfab-rv7-80e78-a75b70"}, {"t": "pt", "text": "Annual report: fair and balanced, compliance statement", "id": "acfab-rv7-80e78-5ccf3e"}, {"t": "pt", "text": "CSR = actions not obliged, taken for stakeholders and the public", "id": "acfab-rv7-80e78-8cfe75"}, {"t": "pt", "text": "Friedman: business's responsibility is profit within the law", "id": "acfab-rv7-80e78-06a1fd"}], "id": "acfab-rv7-80e78"}], "source": "BPP Workbook ch 7: sections 1-6 pp178-193; chapter roundup p194", "summary": "Governance principles and theories, features and risks of poor governance, the board, chairman/CEO split, non-executive directors, remuneration and audit committees, governance reporting and CSR.", "id": "acfab-rv7", "updated": "2026-11-12"}, {"num": "8", "title": "The Role of Accounting", "pages": [199, 234], "syllabus": "C2, C3", "status": "published", "branches": [{"kind": "concept", "title": "Purpose and users of accounting", "page": [201, 204], "items": [{"t": "def", "k": 1, "term": "Accounting", "text": "A way of recording, analysing and summarising the transactions of a business", "id": "acfab-rv8-ecf66-f5c62d"}, {"t": "pt", "text": "Process: record in books of prime entry -> analyse and post to ledgers -> summarise in financial statements", "id": "acfab-rv8-ecf66-0cb717"}, {"t": "pt", "text": "Double-entry bookkeeping first explained in print by Luca Pacioli (1494)", "id": "acfab-rv8-ecf66-0471ff"}, {"t": "pt", "k": 1, "text": "Users: managers, shareholders, trade contacts (suppliers, customers), providers of finance, tax authorities, employees, analysts, government, the public", "id": "acfab-rv8-ecf66-4f4e3d"}, {"t": "pt", "text": "Charities, clubs and public bodies also prepare accounts", "id": "acfab-rv8-ecf66-476e11"}, {"t": "pt", "text": "Qualities of good information: accurate, complete, cost-beneficial, user-targeted, relevant, authoritative, timely, easy to use", "id": "acfab-rv8-ecf66-d19eaf"}, {"t": "pt", "text": "Finance director heads the accounting function and sits on the board; financial controller and management accountant report to them", "id": "acfab-rv8-ecf66-c343ea"}, {"t": "exam", "text": "You may be asked what information managers, employees or shareholders need", "id": "acfab-rv8-ecf66-be8241"}], "id": "acfab-rv8-ecf66"}, {"kind": "compare", "title": "Financial vs management accounting", "page": [205, 207], "items": [{"t": "table", "rows": [["Feature", "Financial accounting", "Management accounting"], ["Purpose", "Report results and financial position", "Help managers plan, control and make decisions"], ["Users", "External - shareholders, lenders, tax authorities", "Internal - management"], ["Requirement", "Required by law (limited companies)", "Not a legal requirement"], ["Format", "Set by law and accounting standards", "Whatever management finds useful"], ["Focus", "Historic, the business as a whole", "Historic and future, departments and products"]], "id": "acfab-rv8-c5af9-74a9f1"}, {"t": "def", "term": "Financial management", "text": "A separate discipline: investment, financing and dividend decisions", "id": "acfab-rv8-c5af9-6cf0fb"}, {"t": "pt", "k": 1, "text": "External audit: companies above a size threshold must be audited by a person independent of the company, who reports to the members", "id": "acfab-rv8-c5af9-bceba0"}, {"t": "def", "k": 1, "term": "Internal auditors", "text": "Employees of the company whose duties are fixed by management and who report on the effectiveness of internal control systems", "id": "acfab-rv8-c5af9-55789f"}, {"t": "exam", "text": "Understand clearly why financial and management accounts are prepared - a frequently tested distinction", "id": "acfab-rv8-c5af9-8f896e"}], "id": "acfab-rv8-c5af9"}, {"kind": "rule", "title": "The regulatory system", "page": [208, 210], "items": [{"t": "pt", "text": "Company law (eg UK Companies Act 2006) requires limited companies to prepare and publish annual accounts", "id": "acfab-rv8-629f3-7ca674"}, {"t": "pt", "text": "Accounting concepts involve individual judgement - standards reduce subjectivity and improve comparability", "id": "acfab-rv8-629f3-d616c7"}, {"t": "pt", "text": "UK: FRC is the unified regulator; accounts must state compliance with applicable standards", "id": "acfab-rv8-629f3-9da5a0"}, {"t": "pt", "text": "IASB issues IFRSs, which improve and harmonise financial reporting worldwide; EU requirements shape national law", "id": "acfab-rv8-629f3-a0d30c"}, {"t": "def", "k": 1, "term": "GAAP", "text": "Generally Accepted Accounting Practice - all the rules, from whatever source, which govern accounting", "id": "acfab-rv8-629f3-9cdfbd"}, {"t": "pt", "k": 1, "text": "True and fair view is not defined in law or standards - taken to mean accurate and not misleading", "id": "acfab-rv8-629f3-87c9c5"}, {"t": "pt", "text": "True and fair 'override': directors may depart from a provision if needed to give a true and fair view (with disclosure)", "id": "acfab-rv8-629f3-a499c4"}], "id": "acfab-rv8-629f3"}, {"kind": "concept", "title": "External and internal reports", "page": [211, 212], "items": [{"t": "pt", "k": 1, "text": "Statement of financial position: assets owned and liabilities owed at a particular DATE", "id": "acfab-rv8-845dd-73bc5f"}, {"t": "pt", "k": 1, "text": "Profit or loss account: income generated and expenditure incurred over a PERIOD", "id": "acfab-rv8-845dd-67bd20"}, {"t": "pt", "text": "Statement of cash flows: sources of cash during the period and how it was spent", "id": "acfab-rv8-845dd-d7899c"}, {"t": "pt", "text": "Sustainability and integrated reports: non-financial data demanded by shareholders, customers, regulators, media", "id": "acfab-rv8-845dd-ed542c"}, {"t": "pt", "text": "Internal reports: cost schedules, budgets, variance reports (actual vs budget)", "id": "acfab-rv8-845dd-4af9b1"}], "id": "acfab-rv8-845dd"}, {"kind": "process", "title": "Controls over business transactions", "page": [213, 225], "items": [{"t": "pt", "text": "Transaction types: sales, purchases, overheads, payroll, capital expenditure", "id": "acfab-rv8-3d20a-276685"}, {"t": "pt", "k": 1, "text": "Financial control procedures ensure transactions are properly carried out, assets safeguarded, records accurate and complete", "id": "acfab-rv8-3d20a-99c9c6"}, {"t": "pt", "k": 1, "text": "Payroll key controls: documentation and authorisation of staff changes • calculation of wages and salaries • payment • authorisation of deductions", "id": "acfab-rv8-3d20a-0a818d"}, {"t": "pt", "text": "Payroll file: standing data (name, rates, tax code) vs transaction data (hours, overtime)", "id": "acfab-rv8-3d20a-8e2ffe"}, {"t": "pt", "k": 1, "text": "Purchases cycle tests: buying (authorisation) • goods inwards (custody) • accounting (recording)", "id": "acfab-rv8-3d20a-b14867"}, {"t": "pt", "k": 1, "text": "Sales cycle tests: selling (authorisation) • goods outwards (custody) • accounting (recording)", "id": "acfab-rv8-3d20a-f3dd7c"}, {"t": "pt", "text": "Cash and petty cash must be regularly reconciled; every payment approved by an authorised person", "id": "acfab-rv8-3d20a-86ed54"}, {"t": "pt", "text": "Controls should be reviewed regularly and problems reported to management", "id": "acfab-rv8-3d20a-5fcef7"}], "id": "acfab-rv8-3d20a"}, {"kind": "concept", "title": "Computerised systems, databases and spreadsheets", "page": [225, 230], "items": [{"t": "pt", "k": 1, "text": "Manual systems are inferior to computerised ones in productivity, speed, accessibility, quality of output, errors, bulk and correction", "id": "acfab-rv8-8fcf5-d4be3a"}, {"t": "pt", "text": "Coding: accounts, suppliers and customers given codes for input", "id": "acfab-rv8-8fcf5-a8c6e4"}, {"t": "def", "term": "Module", "text": "A program dealing with one part of the accounting system (eg sales ledger, payroll)", "id": "acfab-rv8-8fcf5-a670bb"}, {"t": "pt", "k": 1, "text": "Integrated system: one entry updates all linked modules - enhances control; but needs more memory and one error spreads", "id": "acfab-rv8-8fcf5-a36dae"}, {"t": "def", "term": "Database", "text": "A 'pool' of data usable by any number of applications - shared, consistent data, less duplication", "id": "acfab-rv8-8fcf5-67456a"}, {"t": "pt", "text": "Spreadsheet: rows and columns; a cell holds text, numbers or formulae; used for financial models, budgets and pro-forma statements", "id": "acfab-rv8-8fcf5-790adc"}], "id": "acfab-rv8-8fcf5"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Saying management accounts are required by law - only financial accounts are", "id": "acfab-rv8-6483a-07d59e"}, {"t": "x", "text": "Thinking internal auditors are independent of the company - they are employees reporting to management", "id": "acfab-rv8-6483a-3f99cd"}, {"t": "x", "text": "Describing the statement of financial position as covering a period - it is at a date", "id": "acfab-rv8-6483a-58909b"}, {"t": "x", "text": "Forgetting custody (goods inwards/outwards) as one of the three control areas", "id": "acfab-rv8-6483a-385b18"}], "id": "acfab-rv8-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Accounting = record, analyse, summarise", "id": "acfab-rv8-80e78-ff2c39"}, {"t": "pt", "text": "Financial accounting: external, legal, historic, whole business", "id": "acfab-rv8-80e78-e6497b"}, {"t": "pt", "text": "Management accounting: internal, not required by law, planning/control/decisions", "id": "acfab-rv8-80e78-91408a"}, {"t": "pt", "text": "External auditor is independent; internal auditor is an employee", "id": "acfab-rv8-80e78-8ddd33"}, {"t": "pt", "text": "GAAP = all rules governing accounting", "id": "acfab-rv8-80e78-f03c49"}, {"t": "pt", "text": "True and fair = accurate and not misleading (not defined in law)", "id": "acfab-rv8-80e78-ca558c"}, {"t": "pt", "text": "SOFP at a date; profit or loss over a period", "id": "acfab-rv8-80e78-bdc5cf"}, {"t": "pt", "text": "Statement of cash flows: where cash came from and went", "id": "acfab-rv8-80e78-244442"}, {"t": "pt", "text": "Payroll controls: staff changes, calculation, payment, deductions", "id": "acfab-rv8-80e78-5289af"}, {"t": "pt", "text": "Purchases: buying, goods inwards, accounting", "id": "acfab-rv8-80e78-91c734"}, {"t": "pt", "text": "Sales: selling, goods outwards, accounting", "id": "acfab-rv8-80e78-a05b72"}, {"t": "pt", "text": "Integrated system: one entry updates all modules", "id": "acfab-rv8-80e78-f3c763"}, {"t": "pt", "text": "Database = shared pool of data", "id": "acfab-rv8-80e78-7f1c7b"}], "id": "acfab-rv8-80e78"}], "source": "BPP Workbook ch 8: sections 1-8 pp201-230; chapter roundup p231", "summary": "Purpose and users of accounting information, financial vs management accounting, audit, the regulatory system, external and internal reports, controls over the main business systems and computerised accounting.", "id": "acfab-rv8", "updated": "2026-11-12"}, {"num": "9", "title": "Control, Security and Audit", "pages": [235, 266], "syllabus": "C4, C5", "status": "published", "branches": [{"kind": "concept", "title": "Internal control systems", "page": [237, 238], "items": [{"t": "pt", "k": 1, "text": "Internal controls help counter risks, maintain the quality of reporting and comply with laws and regulations - they give REASONABLE (not absolute) assurance", "id": "acfab-rv9-540b9-33f954"}, {"t": "pt", "k": 1, "text": "The internal control system = control environment + control procedures", "id": "acfab-rv9-540b9-61451d"}, {"t": "pt", "text": "Framework elements: control environment, risk assessment and response, information sharing, monitoring", "id": "acfab-rv9-540b9-9e8495"}, {"t": "def", "k": 1, "term": "Control environment", "text": "The overall attitude, awareness and actions of directors and management regarding internal controls and their importance in the entity", "id": "acfab-rv9-540b9-957008"}, {"t": "pt", "text": "Strong environment: clear risk strategies, supportive culture and code of conduct, management commitment to competence and integrity, clear authority and accountability, communication of expectations, competent people", "id": "acfab-rv9-540b9-46c69f"}], "id": "acfab-rv9-540b9"}, {"kind": "compare", "title": "Classifying controls", "page": [238, 240], "items": [{"t": "table", "rows": [["Classification", "Meaning", "Example"], ["Prevent / detect / correct", "Stop errors, find them, or fix them", "Authorisation; bank reconciliation; back-up recovery"], ["Discretionary / non-discretionary", "Subject to human judgement / automatic, cannot be overridden", "Checking a signature / PIN at a cash machine"], ["Voluntary / mandated", "Chosen by management / required by law", "Internal budgets / statutory audit"], ["Manual / automated", "Performed by people / by the system", "Manual check / system validation"], ["General / application", "IT environment as a whole / specific processing", "Change management / completeness checks"], ["Administrative / accounting (financial)", "Efficiency and policy / safeguard assets and records", "Procedures manual / reconciliations"]], "id": "acfab-rv9-315d1-89b37d"}], "id": "acfab-rv9-315d1"}, {"kind": "rule", "title": "SPAMSOAP financial control procedures", "page": [240, 242], "items": [{"t": "pt", "k": 1, "text": "Segregation of duties • Physical • Authorisation and approval • Management • Supervision • Organisation • Arithmetical and accounting • Personnel", "id": "acfab-rv9-030de-23dc52"}, {"t": "pt", "text": "Segregation: split custody, authorisation and recording (eg chair/CEO roles split)", "id": "acfab-rv9-030de-d9cdd5"}, {"t": "pt", "text": "Physical: secure custody of assets (locks, restricted access)", "id": "acfab-rv9-030de-5ab411"}, {"t": "pt", "text": "Authorisation: transactions approved within specified limits", "id": "acfab-rv9-030de-8d4de4"}, {"t": "pt", "text": "Arithmetical and accounting: reconciliations, control accounts, trial balances", "id": "acfab-rv9-030de-ed7fd6"}, {"t": "def", "term": "Internal checks", "text": "Checks on day-to-day transactions that operate continuously as part of the routine system, where one person's work is proved independently or complements another's", "id": "acfab-rv9-030de-5f9d5b"}, {"t": "pt", "text": "Good system: clear organisation structure, adequate staff, documented procedures, regular review", "id": "acfab-rv9-030de-c23500"}, {"t": "pt", "text": "Limitations: cost vs benefit, human error, collusion, management override, controls designed for routine transactions only", "id": "acfab-rv9-030de-9326ba"}], "id": "acfab-rv9-030de"}, {"kind": "compare", "title": "Internal vs external audit", "page": [242, 249], "items": [{"t": "table", "rows": [["Feature", "Internal audit", "External audit"], ["Reason", "Add value and improve operations", "Express an opinion on the financial statements"], ["Reports to", "Board / audit committee", "Shareholders (members)"], ["Relates to", "Operations of the organisation - all areas", "The financial statements"], ["Relationship", "Employees of the organisation (or outsourced)", "Independent of the company and management"]], "id": "acfab-rv9-eea7a-14ea14"}, {"t": "def", "k": 1, "term": "Internal audit", "text": "An independent appraisal activity established within an organisation as a service to it - a control which examines and evaluates the adequacy and effectiveness of other controls", "id": "acfab-rv9-eea7a-c18fc8"}, {"t": "pt", "text": "Roles: review of internal control systems, risk management, legal compliance, value for money", "id": "acfab-rv9-eea7a-a3d4ff"}, {"t": "pt", "text": "Types of internal audit: financial, operational, systems, value for money, management, social/environmental", "id": "acfab-rv9-eea7a-c664a6"}, {"t": "pt", "k": 1, "text": "The internal auditor is accountable to the highest executive level - preferably the audit committee", "id": "acfab-rv9-eea7a-226fb5"}, {"t": "pt", "text": "External auditors may RELY on internal audit work only after assessing its objectivity, competence and quality", "id": "acfab-rv9-eea7a-b1c0e1"}, {"t": "pt", "k": 1, "text": "Primary purpose of external audit: a professional opinion on whether the financial statements give a true and fair view", "id": "acfab-rv9-eea7a-e63a9f"}, {"t": "exam", "text": "You may be examined on to whom the internal auditor is accountable", "id": "acfab-rv9-eea7a-adb802"}], "id": "acfab-rv9-eea7a"}, {"kind": "concept", "title": "IT security and physical threats", "page": [250, 252], "items": [{"t": "def", "k": 1, "term": "Security", "text": "Protection of data from accidental or deliberate threats causing unauthorised modification, disclosure or destruction, and protection of the system from loss of service", "id": "acfab-rv9-4c9c6-ca74e5"}, {"t": "pt", "text": "Physical threats: fire (most serious), water, weather, lightning/power surges, terrorism, accidental damage", "id": "acfab-rv9-4c9c6-6b5f84"}, {"t": "pt", "text": "Physical access controls: guards, locks, PINs and cards, biometrics, door logs", "id": "acfab-rv9-4c9c6-8f696c"}], "id": "acfab-rv9-4c9c6"}, {"kind": "process", "title": "Building controls into systems", "page": [253, 257], "items": [{"t": "pt", "k": 1, "text": "Balance the degree of control against the need for a user-friendly system", "id": "acfab-rv9-02bf4-a1f6cf"}, {"t": "def", "term": "Data integrity", "text": "Data is the same as in source documents and has not been accidentally or intentionally altered, destroyed or disclosed", "id": "acfab-rv9-02bf4-09805a"}, {"t": "pt", "text": "Input controls (accuracy, completeness, validity): verification, validation checks (range, format, check digits), batch totals", "id": "acfab-rv9-02bf4-9bac92"}, {"t": "pt", "text": "Processing controls: development controls, testing, control totals", "id": "acfab-rv9-02bf4-d8cfff"}, {"t": "pt", "text": "Output controls: investigate errors, reconcile totals, distribution lists, secure printouts", "id": "acfab-rv9-02bf4-4ad404"}, {"t": "pt", "k": 1, "text": "Back-up strategy: regular back-up (at least daily) • archive plans • disaster recovery plan with off-site storage", "id": "acfab-rv9-02bf4-786c2f"}, {"t": "pt", "text": "Passwords and logical access; administrative controls over trusted staff (vetting, segregation, rotation)", "id": "acfab-rv9-02bf4-eeda2c"}, {"t": "def", "k": 1, "term": "Audit trail", "text": "A record showing who has accessed a system and the operations performed", "id": "acfab-rv9-02bf4-0c1d2d"}, {"t": "pt", "text": "LAN risk: faults spread across the network; WAN: extra communication-link risks (encryption)", "id": "acfab-rv9-02bf4-6c7615"}, {"t": "pt", "text": "Disaster recovery plan: standby procedures, recovery, personnel responsibilities, back-up of data and equipment - from initial response to full recovery", "id": "acfab-rv9-02bf4-ca96e6"}], "id": "acfab-rv9-02bf4"}, {"kind": "concept", "title": "Cyber security and Fintech", "page": [258, 263], "items": [{"t": "pt", "text": "Cyber risks: financial loss, reputational damage, business disruption, regulatory penalties", "id": "acfab-rv9-1701a-ebece5"}, {"t": "pt", "text": "Attacks: phishing, malware/viruses, ransomware, denial of service, hacking", "id": "acfab-rv9-1701a-5d5a9b"}, {"t": "pt", "text": "Security methods: access controls, firewalls, encryption, anti-virus, staff training, penetration testing", "id": "acfab-rv9-1701a-024cde"}, {"t": "pt", "k": 1, "text": "Fintech affecting accountants: cloud computing, automation and AI, big data and data analytics, Blockchain / distributed ledger technology", "id": "acfab-rv9-1701a-0b32c4"}, {"t": "pt", "text": "Cloud: computing as a consumable service - access anywhere, scalable, lower in-house cost", "id": "acfab-rv9-1701a-2e26b3"}, {"t": "pt", "text": "Blockchain: an indelible shared ledger of transactions - more transparency, less need for auditors to verify ownership (eg diamond ownership, Bitcoin)", "id": "acfab-rv9-1701a-d5a835"}], "id": "acfab-rv9-1701a"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Saying internal controls give absolute assurance - only reasonable assurance", "id": "acfab-rv9-6483a-a90be3"}, {"t": "x", "text": "Thinking internal auditors report to shareholders - external auditors do; internal auditors report to the audit committee/board", "id": "acfab-rv9-6483a-3273e6"}, {"t": "x", "text": "Saying the external auditor must detect all fraud - their duty is an opinion on truth and fairness", "id": "acfab-rv9-6483a-cb08f9"}, {"t": "x", "text": "Forgetting that a control can be defeated by collusion or management override", "id": "acfab-rv9-6483a-2a7e0f"}], "id": "acfab-rv9-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Internal control = control environment + control procedures", "id": "acfab-rv9-80e78-5e33be"}, {"t": "pt", "text": "Controls give reasonable assurance, not absolute", "id": "acfab-rv9-80e78-ef005c"}, {"t": "pt", "text": "Control environment = attitude, awareness and actions of directors and management", "id": "acfab-rv9-80e78-65a35c"}, {"t": "pt", "text": "SPAMSOAP: segregation, physical, authorisation, management, supervision, organisation, arithmetical/accounting, personnel", "id": "acfab-rv9-80e78-d8f9ad"}, {"t": "pt", "text": "Prevent, detect, correct controls", "id": "acfab-rv9-80e78-769047"}, {"t": "pt", "text": "Internal audit adds value; reports to the audit committee", "id": "acfab-rv9-80e78-02a319"}, {"t": "pt", "text": "External audit gives a true and fair opinion; reports to shareholders", "id": "acfab-rv9-80e78-dc22b0"}, {"t": "pt", "text": "External auditors can rely on internal audit after assessing it", "id": "acfab-rv9-80e78-202c22"}, {"t": "pt", "text": "Fire is the most serious physical threat", "id": "acfab-rv9-80e78-db922d"}, {"t": "pt", "text": "Input controls: verification and validation", "id": "acfab-rv9-80e78-eb08fc"}, {"t": "pt", "text": "Back-up daily, archive, off-site disaster recovery", "id": "acfab-rv9-80e78-affab4"}, {"t": "pt", "text": "Audit trail = who accessed the system and what they did", "id": "acfab-rv9-80e78-68240f"}, {"t": "pt", "text": "Fintech: cloud, automation/AI, big data, Blockchain", "id": "acfab-rv9-80e78-46a0ec"}], "id": "acfab-rv9-80e78"}], "source": "BPP Workbook ch 9: sections 1-7 pp237-263; chapter roundup p264", "summary": "Internal control systems and environment, classifications of controls and SPAMSOAP, internal vs external audit, IT security (physical, integrity, contingency, cyber) and the impact of Fintech.", "id": "acfab-rv9", "updated": "2026-11-12"}, {"num": "10", "title": "Identifying and Preventing Fraud", "pages": [267, 292], "syllabus": "C6", "status": "published", "branches": [{"kind": "concept", "title": "What is fraud?", "page": [268, 271], "items": [{"t": "def", "k": 1, "term": "Fraud", "text": "'Deprivation by deceit' - a false representation of fact made knowing it is false, or recklessly, intending another to rely on it", "id": "acfab-rv10-49013-73dd2e"}, {"t": "pt", "k": 1, "text": "Two broad types: removal of funds or assets from a business • intentional misrepresentation of the financial position", "id": "acfab-rv10-49013-29889f"}, {"t": "pt", "text": "Removal of funds/assets", "kids": [{"t": "pt", "text": "Theft of cash (petty cash) and inventory", "id": "acfab-rv10-49013-082b6a"}, {"t": "pt", "text": "Payroll fraud: falsified timesheets, 'ghost' employees", "id": "acfab-rv10-49013-20190f"}, {"t": "pt", "k": 1, "text": "Teeming and lading: theft of cash receipts, covered by allocating later receipts from other customers to the first customer's account", "id": "acfab-rv10-49013-a13c10"}, {"t": "pt", "text": "Fictitious customers, collusion with customers, bogus supplies, paying for goods not received", "id": "acfab-rv10-49013-357827"}, {"t": "pt", "text": "Manipulating bank reconciliations and cash books; misuse of pension funds; disposals of assets to employees at undervalue", "id": "acfab-rv10-49013-7a4dde"}], "id": "acfab-rv10-49013-6f1469"}, {"t": "pt", "text": "Misrepresentation (overstating profit): overvalued inventory, irrecoverable debts not written off, fictitious sales, year-end cut-off manipulation (window dressing), understated expenses, manipulated depreciation", "id": "acfab-rv10-49013-52ee43"}, {"t": "exam", "text": "Expect scenario questions: think about where fraud could occur in THIS business", "id": "acfab-rv10-49013-a80f24"}], "id": "acfab-rv10-49013"}, {"kind": "concept", "title": "Prerequisites and risk indicators", "page": [271, 275], "items": [{"t": "pt", "k": 1, "text": "Three prerequisites: dishonesty • motivation • opportunity", "id": "acfab-rv10-a3cb2-9e850c"}, {"t": "pt", "text": "Dishonesty: a predisposition to act unethically; motivation: financial or personal pressure; opportunity: a loophole such as weak controls", "id": "acfab-rv10-a3cb2-6f17ad"}, {"t": "pt", "k": 1, "text": "Signs of high fraud risk: lack of integrity, excessive pressures, poor control systems, unusual transactions, lack of audit evidence", "id": "acfab-rv10-a3cb2-0bc507"}, {"t": "pt", "text": "Assess risk externally (market, industry) then internally (company-specific)", "id": "acfab-rv10-a3cb2-67eb5f"}, {"t": "pt", "text": "Business risks: poor controls, rapid growth, complex structure, pressure to meet targets", "id": "acfab-rv10-a3cb2-d3af50"}, {"t": "pt", "text": "Personnel risks: secretive behaviour, lifestyle beyond means, refusal to take holidays, close supplier/customer relationships", "id": "acfab-rv10-a3cb2-06efbe"}, {"t": "pt", "text": "Computer fraud risk grows with dependence on IT", "id": "acfab-rv10-a3cb2-df30e4"}], "id": "acfab-rv10-a3cb2"}, {"kind": "concept", "title": "Implications of fraud", "page": [275, 276], "items": [{"t": "pt", "text": "Removal of assets: lower profits, less cash/assets, possible business failure, reputational damage", "id": "acfab-rv10-780de-be8849"}, {"t": "pt", "text": "Misrepresentation: financial statements do not give a true and fair view", "id": "acfab-rv10-780de-40b003"}, {"t": "pt", "text": "Overstated results: too much profit distributed, wrong decisions, share price later collapses", "id": "acfab-rv10-780de-dc4e76"}, {"t": "pt", "text": "Understated results: returns to investors reduced unnecessarily, share price falls", "id": "acfab-rv10-780de-703fbd"}], "id": "acfab-rv10-780de"}, {"kind": "process", "title": "Preventing and detecting fraud", "page": [277, 281], "items": [{"t": "pt", "k": 1, "text": "Prevention must be an integral part of corporate strategy; managers must know the risks and signs", "id": "acfab-rv10-b717a-f26973"}, {"t": "pt", "text": "General prevention: emphasis on ethics, personnel policies (references, vetting), training", "id": "acfab-rv10-b717a-a48ce7"}, {"t": "pt", "k": 1, "text": "Specific controls", "kids": [{"t": "pt", "text": "Segregation of duties", "id": "acfab-rv10-b717a-7d19c8"}, {"t": "pt", "text": "Physical controls (lock and key)", "id": "acfab-rv10-b717a-619fb6"}, {"t": "pt", "text": "Authorisation policies (written, by a senior person)", "id": "acfab-rv10-b717a-826ae4"}, {"t": "pt", "text": "Customer signatures for receipt of goods", "id": "acfab-rv10-b717a-9c6b27"}, {"t": "pt", "text": "Quantities written in words, not numbers", "id": "acfab-rv10-b717a-f2706b"}, {"t": "pt", "text": "Separate documents (order, despatch, delivery, invoice) for matching", "id": "acfab-rv10-b717a-e12a7d"}, {"t": "pt", "text": "Sequential numbering of documents", "id": "acfab-rv10-b717a-b0d9a2"}, {"t": "pt", "text": "Dates on documents (cut-off)", "id": "acfab-rv10-b717a-2d4ff3"}, {"t": "pt", "text": "Standard procedures, independent checks", "id": "acfab-rv10-b717a-9115ef"}, {"t": "pt", "text": "Compulsory holidays - fraud is hard to conceal while someone else does the job", "id": "acfab-rv10-b717a-e21916"}, {"t": "pt", "text": "Recruitment checks, computer security", "id": "acfab-rv10-b717a-3f17a9"}], "id": "acfab-rv10-b717a-7c56fc"}, {"t": "pt", "text": "Detection: manager and staff awareness, a fraud officer, available information, whistleblowing protection", "id": "acfab-rv10-b717a-873cd5"}, {"t": "def", "k": 1, "term": "Fraud response plan", "text": "The organisation's plan setting out how the method and extent of a fraud and possible suspects will be investigated", "id": "acfab-rv10-b717a-fa57d1"}, {"t": "pt", "text": "Controls must evolve as risks change", "id": "acfab-rv10-b717a-81505e"}], "id": "acfab-rv10-b717a"}, {"kind": "rule", "title": "Responsibility for fraud", "page": [282, 282], "items": [{"t": "pt", "k": 1, "text": "Directors are responsible for taking such steps as are reasonably open to them to prevent and detect fraud", "id": "acfab-rv10-67cd7-2d5a7d"}, {"t": "pt", "text": "Directors should: run the business with integrity, implement controls, monitor risk", "id": "acfab-rv10-67cd7-3e505f"}, {"t": "exam", "text": "The external auditor's responsibility is ONLY to express an opinion on whether the financial statements give a true and fair view - not to find all fraud", "id": "acfab-rv10-67cd7-f54f9f"}], "id": "acfab-rv10-67cd7"}, {"kind": "process", "title": "Money laundering", "page": [282, 286], "items": [{"t": "def", "k": 1, "term": "Money laundering", "text": "Disguising the proceeds of crime so they appear to come from a legitimate source", "id": "acfab-rv10-4e2fc-94f105"}, {"t": "pt", "k": 1, "text": "Three phases: placement (initial disposal of illegal proceeds into the system) -> layering (transfers to disguise the source) -> integration (funds re-enter the economy as apparently legitimate)", "id": "acfab-rv10-4e2fc-4f9fff"}, {"t": "pt", "text": "Risk-based approach: identify risks, assess the customer base, customer due diligence (check customers are who they say they are), ongoing monitoring, full records", "id": "acfab-rv10-4e2fc-4765b4"}, {"t": "pt", "text": "Offences: assisting laundering, failing to report suspicion, tipping off", "id": "acfab-rv10-4e2fc-e7e53d"}, {"t": "pt", "text": "Report suspicions to the nominated officer, or directly to the National Crime Agency (NCA) via a Suspicious Activity Report (SAR)", "id": "acfab-rv10-4e2fc-92aa8d"}, {"t": "pt", "text": "Penalties (UK): 14 years for knowingly assisting • 5 years for failure to report • 2 years for tipping off (each and/or a fine)", "id": "acfab-rv10-4e2fc-4bd6c7"}, {"t": "pt", "text": "International bodies: Financial Action Task Force (FATF), IMF; FCA rules for financial services firms", "id": "acfab-rv10-4e2fc-0eaef2"}, {"t": "pt", "text": "High-risk businesses: luxury goods dealers, cash businesses, financial services", "id": "acfab-rv10-4e2fc-af4e10"}], "id": "acfab-rv10-4e2fc"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Saying auditors are responsible for preventing fraud - directors are", "id": "acfab-rv10-6483a-a39188"}, {"t": "x", "text": "Mixing up the order of money laundering phases - placement, layering, integration", "id": "acfab-rv10-6483a-90ff8f"}, {"t": "x", "text": "Forgetting that tipping off a suspect is itself a criminal offence", "id": "acfab-rv10-6483a-c6732c"}, {"t": "x", "text": "Describing teeming and lading as a payroll fraud - it is a receivables (sales ledger) fraud", "id": "acfab-rv10-6483a-db3a99"}], "id": "acfab-rv10-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Fraud = deprivation by deceit", "id": "acfab-rv10-80e78-99ee0b"}, {"t": "pt", "text": "Two types: removal of assets; misrepresentation of financial position", "id": "acfab-rv10-80e78-c162ab"}, {"t": "pt", "text": "Prerequisites: dishonesty, motivation, opportunity", "id": "acfab-rv10-80e78-22969c"}, {"t": "pt", "text": "Teeming and lading = stealing receipts, covered by later receipts", "id": "acfab-rv10-80e78-2d301d"}, {"t": "pt", "text": "Overstating profit: inventory, debts, fictitious sales, cut-off, expenses, depreciation", "id": "acfab-rv10-80e78-74d1d3"}, {"t": "pt", "text": "Risk signs: integrity, pressures, poor controls, unusual transactions, missing evidence", "id": "acfab-rv10-80e78-68c2bf"}, {"t": "pt", "text": "Key controls: segregation, authorisation, documents, sequential numbers, holidays", "id": "acfab-rv10-80e78-ddc18f"}, {"t": "pt", "text": "Fraud response plan sets out the investigation", "id": "acfab-rv10-80e78-25ce17"}, {"t": "pt", "text": "Directors prevent and detect fraud; auditors give an opinion", "id": "acfab-rv10-80e78-97eb91"}, {"t": "pt", "text": "Laundering: placement, layering, integration", "id": "acfab-rv10-80e78-521616"}, {"t": "pt", "text": "Report to the nominated officer or NCA (SAR)", "id": "acfab-rv10-80e78-1411a0"}, {"t": "pt", "text": "Penalties: 14 years assisting, 5 failure to report, 2 tipping off", "id": "acfab-rv10-80e78-6fa6e9"}, {"t": "pt", "text": "Customer due diligence = verify identity", "id": "acfab-rv10-80e78-47f821"}], "id": "acfab-rv10-80e78"}], "source": "BPP Workbook ch 10: sections 1-6 pp268-286; chapter roundup p288", "summary": "Types of fraud, the three prerequisites, fraud risk indicators, implications, prevention and detection controls, directors' and auditors' responsibilities and money laundering.", "id": "acfab-rv10", "updated": "2026-11-12"}, {"num": "11", "title": "Leading and Managing People", "pages": [293, 318], "syllabus": "D1", "status": "published", "branches": [{"kind": "concept", "title": "Authority, power and delegation", "page": [294, 298], "items": [{"t": "def", "k": 1, "term": "Management", "text": "'Getting things done through other people' (Stewart); management is accountable to the owners (shareholders, or government in the public sector)", "id": "acfab-rv11-2d071-82271b"}, {"t": "def", "k": 1, "term": "Authority", "text": "The right to do something - the scope of discretion to make decisions given by virtue of a position", "id": "acfab-rv11-2d071-00760d"}, {"t": "def", "k": 1, "term": "Responsibility", "text": "The obligation (liability) to perform duties", "id": "acfab-rv11-2d071-99785f"}, {"t": "pt", "k": 1, "text": "Power is the ABILITY to do something; authority is the RIGHT to do something", "id": "acfab-rv11-2d071-24c32d"}, {"t": "pt", "text": "Sufficient authority should be given to discharge the responsibility; accountability is rendered upwards, authority delegated downwards", "id": "acfab-rv11-2d071-d6e641"}, {"t": "def", "term": "Delegation", "text": "A superior gives a subordinate the discretion to make decisions within a certain sphere of influence - the superior remains accountable", "id": "acfab-rv11-2d071-9f9d3e"}, {"t": "def", "term": "Influence", "text": "The process by which one person modifies the behaviour or attitudes of another", "id": "acfab-rv11-2d071-502203"}, {"t": "pt", "text": "Power sources: legitimate (position), reward, coercive, expert, referent (personal) - plus resource and negative power", "id": "acfab-rv11-2d071-0a66ef"}, {"t": "pt", "text": "Power centres: senior managers (coercive and reward), middle managers (expert, negative), interest groups, departments (functional authority)", "id": "acfab-rv11-2d071-283696"}, {"t": "pt", "text": "Managers organise work: work planning, resource allocation, project management", "id": "acfab-rv11-2d071-722286"}, {"t": "def", "term": "Project", "text": "'An undertaking that has a beginning and an end and is carried out to meet established goals within cost, schedule and quality objectives'", "id": "acfab-rv11-2d071-3b9836"}], "id": "acfab-rv11-2d071"}, {"kind": "compare", "title": "Writers on management", "page": [300, 304], "items": [{"t": "table", "rows": [["Writer", "School", "Key idea"], ["Henri Fayol", "Classical (administrator)", "Universal principles; five functions: planning, organising, commanding, co-ordinating, controlling"], ["F W Taylor", "Scientific management (engineer)", "One best way; work study, standardised methods, piece-rate pay"], ["Elton Mayo", "Human relations", "Hawthorne studies: social and group factors drive productivity"], ["Peter Drucker", "Modern", "Economic performance is the manager's first job; management by objectives"], ["Henry Mintzberg", "Modern", "Management is disjointed and non-systematic; ten managerial roles"]], "id": "acfab-rv11-11308-30a1a3"}, {"t": "pt", "k": 1, "text": "Mintzberg's roles: interpersonal (figurehead, leader, liaison) • informational (monitor, disseminator, spokesperson) • decisional (entrepreneur, disturbance handler, resource allocator, negotiator)", "id": "acfab-rv11-11308-a7d9ce"}, {"t": "pt", "text": "Drucker's management processes: setting objectives, organising, motivating and communicating, measuring, developing people", "id": "acfab-rv11-11308-915ffd"}, {"t": "pt", "text": "Neo-human relations writers focus on higher-order needs: challenge, responsibility, personal development", "id": "acfab-rv11-11308-ee7dbb"}, {"t": "exam", "text": "Fayol's five functions are a foundational model; scientific management applied to modern work (eg call centres) may be examined", "id": "acfab-rv11-11308-613eb1"}, {"t": "def", "term": "Supervisor", "text": "The lowest level of management - the interface between the operational core (non-managerial workers) and management", "id": "acfab-rv11-11308-836394"}], "id": "acfab-rv11-11308"}, {"kind": "concept", "title": "What is leadership?", "page": [306, 307], "items": [{"t": "pt", "k": 1, "text": "Leadership themes: interpersonal influence • securing willing commitment to shared goals • creating direction and energy • orientation to change", "id": "acfab-rv11-e958f-4ae438"}, {"t": "pt", "k": 1, "text": "Three schools: trait (qualities) • style • contingency (including situational and functional)", "id": "acfab-rv11-e958f-3a3617"}, {"t": "pt", "text": "Trait theory: 'great men' - leaders are born, not made; weak because no consistent set of traits found", "id": "acfab-rv11-e958f-9eefd9"}, {"t": "pt", "text": "Bennis: managers administer, maintain, focus on systems, ask how and when; leaders innovate, develop, focus on people, ask what and why", "id": "acfab-rv11-e958f-8581e8"}, {"t": "pt", "text": "Kotter: management copes with complexity; leadership copes with change", "id": "acfab-rv11-e958f-015453"}], "id": "acfab-rv11-e958f"}, {"kind": "concept", "title": "Style theories", "page": [308, 311], "items": [{"t": "pt", "k": 1, "text": "Styles relate to focus on task/performance (directive) vs relationships/people (supportive)", "id": "acfab-rv11-316d6-539a35"}, {"t": "pt", "k": 1, "text": "Ashridge model: tells (autocratic) • sells (persuasive) • consults • joins (democratic)", "id": "acfab-rv11-316d6-58f503"}, {"t": "pt", "k": 1, "text": "Blake and Mouton's managerial grid: concern for production (x axis) vs concern for people (y axis), each 1-9", "kids": [{"t": "pt", "text": "1.1 impoverished • 1.9 country club • 9.1 task management • 5.5 middle of the road • 9.9 team management (ideal)", "id": "acfab-rv11-316d6-82bd78"}], "id": "acfab-rv11-316d6-68222d"}, {"t": "exam", "text": "Grid positions are a likely source of exam questions - remember 9.1 = high task, low people", "id": "acfab-rv11-316d6-74c800"}, {"t": "pt", "text": "Limitation: style theories ignore other variables (task, team, situation)", "id": "acfab-rv11-316d6-735d32"}], "id": "acfab-rv11-316d6"}, {"kind": "concept", "title": "Contingency approaches", "page": [311, 314], "items": [{"t": "pt", "k": 1, "text": "Effective leadership depends on contingent factors - the leader adapts style to the team and situation", "id": "acfab-rv11-62ad8-e97970"}, {"t": "pt", "text": "Fiedler: psychologically distant (task-oriented) vs psychologically close (relationship-oriented) leaders; best style depends on leader-member relations, task structure and position power", "id": "acfab-rv11-62ad8-7ebc4c"}, {"t": "pt", "k": 1, "text": "Adair's action-centred (functional) leadership: balance task needs, group (team maintenance) needs and individual needs", "id": "acfab-rv11-62ad8-b10970"}, {"t": "pt", "text": "Heifetz: dispersed leadership - leadership as a process shared across people, adaptive work", "id": "acfab-rv11-62ad8-89c6c3"}, {"t": "pt", "text": "Schein's critique: variables are hard to measure; technical competence ignored; leaders find it hard to change behaviour", "id": "acfab-rv11-62ad8-60ab5e"}, {"t": "exam", "text": "The Study Guide names Adair, Bennis, Fiedler, Heifetz and Kotter - most theories are North American and may ignore cultural differences", "id": "acfab-rv11-62ad8-62216b"}], "id": "acfab-rv11-62ad8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing power (ability) with authority (right)", "id": "acfab-rv11-6483a-16dcfa"}, {"t": "x", "text": "Thinking delegation passes on accountability - the delegator stays accountable", "id": "acfab-rv11-6483a-f34266"}, {"t": "x", "text": "Mixing up Blake and Mouton 1.9 (country club) and 9.1 (task)", "id": "acfab-rv11-6483a-915b6d"}, {"t": "x", "text": "Attributing the Hawthorne studies to Taylor - they are Mayo's human relations work", "id": "acfab-rv11-6483a-193dc3"}], "id": "acfab-rv11-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Management = getting things done through other people", "id": "acfab-rv11-80e78-0b9cdf"}, {"t": "pt", "text": "Authority = right; power = ability; responsibility = obligation", "id": "acfab-rv11-80e78-f831e6"}, {"t": "pt", "text": "Delegate authority, not accountability", "id": "acfab-rv11-80e78-3e1268"}, {"t": "pt", "text": "Fayol: plan, organise, command, co-ordinate, control", "id": "acfab-rv11-80e78-1132d6"}, {"t": "pt", "text": "Taylor: scientific management; Mayo: human relations", "id": "acfab-rv11-80e78-c4d6b8"}, {"t": "pt", "text": "Drucker: economic performance; Mintzberg: ten roles in three groups", "id": "acfab-rv11-80e78-63b1d0"}, {"t": "pt", "text": "Supervisor = interface between workers and management", "id": "acfab-rv11-80e78-60e5b4"}, {"t": "pt", "text": "Leadership schools: trait, style, contingency", "id": "acfab-rv11-80e78-eb9143"}, {"t": "pt", "text": "Ashridge: tells, sells, consults, joins", "id": "acfab-rv11-80e78-01aad2"}, {"t": "pt", "text": "Blake and Mouton 9.9 = team management", "id": "acfab-rv11-80e78-65f659"}, {"t": "pt", "text": "Fiedler: psychologically distant vs close", "id": "acfab-rv11-80e78-b3ad47"}, {"t": "pt", "text": "Adair: task, group, individual needs", "id": "acfab-rv11-80e78-50d725"}, {"t": "pt", "text": "Bennis: managers administer, leaders innovate", "id": "acfab-rv11-80e78-befad1"}, {"t": "pt", "text": "Heifetz: dispersed leadership", "id": "acfab-rv11-80e78-f5913e"}], "id": "acfab-rv11-80e78"}], "source": "BPP Workbook ch 11: sections 1-5 pp294-314; chapter roundup p315", "summary": "Authority, responsibility, power and delegation; classical and modern management writers; supervision; and trait, style and contingency theories of leadership.", "id": "acfab-rv11", "updated": "2026-11-12"}, {"num": "12", "title": "Recruitment and Selection", "pages": [319, 342], "syllabus": "D2", "status": "published", "branches": [{"kind": "concept", "title": "Responsibility for recruitment", "page": [320, 322], "items": [{"t": "pt", "k": 1, "text": "Effective recruitment ensures the firm has enough people with the right skills; it is part of the HR plan", "id": "acfab-rv12-0f37d-2d60d4"}, {"t": "pt", "k": 1, "text": "The process involves HR specialists and line managers, sometimes with recruitment consultants", "id": "acfab-rv12-0f37d-ae952d"}, {"t": "pt", "text": "Senior managers: senior posts and authorising headcount; HR department: policy, advertising, administration; line manager: knows the job, often interviews and decides", "id": "acfab-rv12-0f37d-c2d4a7"}, {"t": "pt", "text": "Using consultants depends on: cost, expertise available in-house, specialist knowledge, time available, desire for impartiality", "id": "acfab-rv12-0f37d-1f955f"}], "id": "acfab-rv12-0f37d"}, {"kind": "process", "title": "The recruitment process", "page": [322, 327], "items": [{"t": "def", "k": 1, "term": "Recruitment", "text": "A systematic process of identifying and defining skill needs and attracting suitably skilled candidates", "id": "acfab-rv12-c2e64-381ebd"}, {"t": "pt", "k": 1, "text": "Sequence: HR planning -> job analysis -> job description -> job/person specification -> advertise -> selection", "id": "acfab-rv12-c2e64-b698c0"}, {"t": "def", "term": "Job analysis", "text": "Determines the requirements of a job - its tasks, responsibilities and context", "id": "acfab-rv12-c2e64-102ae0"}, {"t": "def", "k": 1, "term": "Job description", "text": "Sets out the purpose of the job, where it fits in the structure, its context, accountabilities and main tasks", "id": "acfab-rv12-c2e64-367892"}, {"t": "def", "k": 1, "term": "Person specification", "text": "Describes the sort of person suitable for the job (skills, qualifications, personality, experience)", "id": "acfab-rv12-c2e64-e2b592"}, {"t": "def", "term": "Competence", "text": "A capacity that leads to behaviour meeting the job demands within the organisation's parameters", "id": "acfab-rv12-c2e64-def57c"}, {"t": "pt", "text": "Job design parameters (Mintzberg): specialisation, behaviour formalisation, training and indoctrination", "id": "acfab-rv12-c2e64-a5f303"}, {"t": "pt", "text": "A role is more than a job - the part played in meeting objectives by working with others", "id": "acfab-rv12-c2e64-23e738"}, {"t": "pt", "k": 1, "text": "Rodger's seven-point plan: physical make-up • attainments • general intelligence • special aptitudes • interests • disposition • circumstances", "id": "acfab-rv12-c2e64-0cfbed"}, {"t": "pt", "text": "Recruitment policy: fair, consistent, coherent code of conduct; covers recruit vs promote/transfer", "id": "acfab-rv12-c2e64-586cfe"}, {"t": "pt", "text": "Promote internally: motivates, known quantity, cheaper; recruit externally: new ideas, wider pool", "id": "acfab-rv12-c2e64-c16c42"}], "id": "acfab-rv12-c2e64"}, {"kind": "concept", "title": "Advertising vacancies", "page": [327, 329], "items": [{"t": "pt", "k": 1, "text": "Aim: attract quality applicants and aid self-selection (unsuitable people choose not to apply)", "id": "acfab-rv12-06746-ee8ebc"}, {"t": "pt", "text": "Good advert: concise but comprehensive, attractive, positive and honest, relevant to the target audience, non-discriminatory", "id": "acfab-rv12-06746-58369a"}, {"t": "pt", "text": "Contents: the organisation, the job, conditions, qualifications and experience required, how to apply", "id": "acfab-rv12-06746-b8a046"}, {"t": "pt", "text": "Media: newspapers and journals, online job boards, the organisation's website, social media, recruitment agencies, job centres, universities", "id": "acfab-rv12-06746-31aa3b"}, {"t": "pt", "text": "Choice of medium depends on reach, targeting and cost", "id": "acfab-rv12-06746-93115a"}, {"t": "exam", "text": "A question might ask you to identify a discriminatory job advertisement (links to ch 13)", "id": "acfab-rv12-06746-e8b434"}], "id": "acfab-rv12-06746"}, {"kind": "compare", "title": "Selection methods", "page": [329, 338], "items": [{"t": "table", "rows": [["Method", "Strength", "Weakness"], ["Interview (individual)", "Flexible, two-way, personal rapport", "Poor predictor; interviewer bias, halo effect"], ["Panel / selection board", "Several views, less individual bias", "Formal, intimidating, hard to co-ordinate"], ["Proficiency / attainment tests", "Measure current ability on job tasks", "Narrow - ignore potential"], ["Intelligence / aptitude tests", "Measure general ability / potential to learn", "Cultural bias; not always job-related"], ["Personality tests", "Identify traits and preferences", "Candidates can fake answers"], ["Assessment centre (group)", "Longer, more natural, in-depth appraisal", "Costly and time-consuming"], ["References", "Verify facts and past performance", "Subjective, often unreliable"]], "id": "acfab-rv12-9d0b9-33e3ad"}, {"t": "pt", "k": 1, "text": "All selection methods are limited in their ability to predict future job performance", "id": "acfab-rv12-9d0b9-2d6892"}, {"t": "pt", "text": "Systematic selection: shortlisting -> interviewing and other methods -> decision -> follow-up (offer, references)", "id": "acfab-rv12-9d0b9-39ec2f"}, {"t": "pt", "text": "Tests must be sensitive, standardised, reliable and valid", "id": "acfab-rv12-9d0b9-3f76cb"}, {"t": "pt", "text": "Interview errors: snap judgements, halo effect, stereotyping, contrast effect, talking too much", "id": "acfab-rv12-9d0b9-c910f8"}], "id": "acfab-rv12-9d0b9"}, {"kind": "concept", "title": "Evaluating recruitment and selection", "page": [339, 339], "items": [{"t": "pt", "k": 1, "text": "Effectiveness and cost-effectiveness should be evaluated systematically", "id": "acfab-rv12-ef942-b1bf92"}, {"t": "pt", "text": "Measures: costs per hire, time to fill, quality of applicants, staff turnover of new recruits, equal opportunities monitoring, attitude surveys, actual job performance vs expected", "id": "acfab-rv12-ef942-d37032"}, {"t": "pt", "text": "Improvements: better policies, systematic procedures, training of selectors, audit of advertising, wider range of techniques, use of agencies", "id": "acfab-rv12-ef942-31f85c"}], "id": "acfab-rv12-ef942"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing the job description (the job) with the person specification (the person)", "id": "acfab-rv12-6483a-dc6f58"}, {"t": "x", "text": "Treating recruitment and selection as the same - recruitment attracts candidates; selection chooses between them", "id": "acfab-rv12-6483a-f5aaea"}, {"t": "x", "text": "Assuming interviews are good predictors of performance - they are popular but weak predictors", "id": "acfab-rv12-6483a-a97957"}, {"t": "x", "text": "Forgetting that self-selection is a purpose of a good job advert", "id": "acfab-rv12-6483a-49a9e9"}], "id": "acfab-rv12-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Recruitment = identify needs + attract candidates", "id": "acfab-rv12-80e78-8ebe76"}, {"t": "pt", "text": "Selection = choose the best candidate", "id": "acfab-rv12-80e78-894ef2"}, {"t": "pt", "text": "HR specialists + line managers (+ consultants)", "id": "acfab-rv12-80e78-bc3f05"}, {"t": "pt", "text": "Job analysis -> job description -> person specification", "id": "acfab-rv12-80e78-63f2ed"}, {"t": "pt", "text": "Rodger: physical, attainments, intelligence, aptitudes, interests, disposition, circumstances", "id": "acfab-rv12-80e78-d72d08"}, {"t": "pt", "text": "Adverts attract applicants and aid self-selection", "id": "acfab-rv12-80e78-e3b2a4"}, {"t": "pt", "text": "Medium choice: reach, targeting, cost", "id": "acfab-rv12-80e78-a6289a"}, {"t": "pt", "text": "Interviews: flexible but poor predictors", "id": "acfab-rv12-80e78-2d29d1"}, {"t": "pt", "text": "Tests: proficiency, intelligence, aptitude, personality", "id": "acfab-rv12-80e78-77543e"}, {"t": "pt", "text": "Assessment centres: final stage, in-depth, costly", "id": "acfab-rv12-80e78-4ad870"}, {"t": "pt", "text": "References verify claims but are subjective", "id": "acfab-rv12-80e78-50f529"}, {"t": "pt", "text": "Evaluate by cost, time, quality, turnover, performance", "id": "acfab-rv12-80e78-68bd98"}], "id": "acfab-rv12-80e78"}], "source": "BPP Workbook ch 12: sections 1-10 pp320-339; chapter roundup p340", "summary": "Who recruits, the systematic recruitment process (job analysis, descriptions, specifications), advertising, selection methods (interviews, tests, assessment centres, references) and evaluating the process.", "id": "acfab-rv12", "updated": "2026-11-12"}, {"num": "13", "title": "Diversity and Equal Opportunities", "pages": [343, 354], "syllabus": "D3", "status": "published", "branches": [{"kind": "concept", "title": "Equal opportunities", "page": [344, 345], "items": [{"t": "def", "k": 1, "term": "Equal opportunities", "text": "An approach to the management of people at work based on equal access to benefits and fair treatment", "id": "acfab-rv13-12a2d-a29773"}, {"t": "pt", "k": 1, "text": "Business case: widen the recruitment pool, better use of talent, reputation and employer brand, reflects the customer base, avoids legal costs, improves morale", "id": "acfab-rv13-12a2d-2ae48f"}, {"t": "pt", "text": "Historical issue: under-representation of women and minorities in senior roles and higher pay", "id": "acfab-rv13-12a2d-bcccb0"}, {"t": "exam", "text": "ACCA article flagged: 'Equal opportunities'", "id": "acfab-rv13-12a2d-0a355b"}], "id": "acfab-rv13-12a2d"}, {"kind": "rule", "title": "Grounds of illegal discrimination (UK)", "page": [345, 346], "items": [{"t": "pt", "k": 1, "text": "Sex and marital status • colour, race, nationality, ethnic or national origin • disability • sexual orientation and religious beliefs • age", "id": "acfab-rv13-3f8b3-158b43"}, {"t": "pt", "text": "Types of discrimination", "kids": [{"t": "def", "term": "Direct discrimination", "text": "Treating one person less favourably than another on a prohibited ground", "id": "acfab-rv13-3f8b3-4034f2"}, {"t": "def", "term": "Indirect discrimination", "text": "Applying a requirement that, although applied equally, a substantially smaller proportion of one group can meet, and which cannot be justified", "id": "acfab-rv13-3f8b3-95ceac"}, {"t": "pt", "text": "Victimisation: penalising someone for complaining or giving evidence", "id": "acfab-rv13-3f8b3-0371a3"}, {"t": "pt", "text": "Harassment: unwanted conduct violating dignity or creating a hostile environment", "id": "acfab-rv13-3f8b3-72c564"}], "id": "acfab-rv13-3f8b3-a4cabd"}, {"t": "pt", "text": "Non-discrimination applies to ALL aspects of employment: advertisements, recruitment and selection, training, promotion, terms, dismissal", "id": "acfab-rv13-3f8b3-b0d299"}, {"t": "pt", "text": "Disability: employers must make reasonable adjustments", "id": "acfab-rv13-3f8b3-23cb9f"}, {"t": "pt", "text": "Age: recruit on skills and abilities; avoid age-related criteria in adverts", "id": "acfab-rv13-3f8b3-32e838"}, {"t": "exam", "text": "These provisions are UK examples - other countries differ, but the principles apply", "id": "acfab-rv13-3f8b3-60b836"}], "id": "acfab-rv13-3f8b3"}, {"kind": "process", "title": "Practical implications", "page": [347, 348], "items": [{"t": "pt", "k": 1, "text": "Codes of practice do not have the force of law but are taken into account by tribunals", "id": "acfab-rv13-23127-ab354c"}, {"t": "pt", "k": 1, "text": "An equal opportunities policy statement may give some protection in the event of complaints", "id": "acfab-rv13-23127-fb7413"}, {"t": "pt", "text": "Policy contents: commitment from the top, named responsible manager, monitoring of the workforce, action plans, training, complaints procedure", "id": "acfab-rv13-23127-59cb27"}, {"t": "pt", "k": 1, "text": "Recruitment and selection are particularly sensitive to discrimination claims", "kids": [{"t": "pt", "text": "Adverts: avoid wording that deters a group (eg 'young', gendered job titles)", "id": "acfab-rv13-23127-496d13"}, {"t": "pt", "text": "Application forms: no unnecessary questions on marital status, age, children", "id": "acfab-rv13-23127-873dae"}, {"t": "pt", "text": "Interviews: same questions for all, trained interviewers, record reasons for decisions", "id": "acfab-rv13-23127-2224fe"}, {"t": "pt", "text": "Tests: free of cultural bias, related to the job", "id": "acfab-rv13-23127-1f3408"}], "id": "acfab-rv13-23127-47ac88"}, {"t": "pt", "text": "Other initiatives: flexible hours, career-break schemes, workplace nurseries, mentoring, positive action training", "id": "acfab-rv13-23127-e51f4b"}], "id": "acfab-rv13-23127"}, {"kind": "concept", "title": "Managing diversity", "page": [349, 350], "items": [{"t": "def", "k": 1, "term": "Managing diversity", "text": "Recognising that the dimensions of difference organisations usually focus on (sex, race, age) are crude, performance-irrelevant classifications - each individual's differences should be valued and used", "id": "acfab-rv13-3a6e3-8d4651"}, {"t": "pt", "text": "Equal opportunities = compliance, treating people the same; managing diversity = proactive, meeting the needs of a diverse workforce", "id": "acfab-rv13-3a6e3-70dacc"}, {"t": "pt", "text": "Ingham's steps to a diversity policy include: leaders implement policy, involve staff at all levels, communicate internally and externally, understand your needs, evaluate and benchmark", "id": "acfab-rv13-3a6e3-d22536"}, {"t": "pt", "text": "Benefits: creativity, better problem-solving, market insight, attracting talent", "id": "acfab-rv13-3a6e3-efcf1e"}], "id": "acfab-rv13-3a6e3"}, {"kind": "compare", "title": "Equal opportunities vs diversity", "page": [344, 350], "items": [{"t": "table", "rows": [["Aspect", "Equal opportunities", "Managing diversity"], ["Driver", "Legal compliance, fairness", "Business benefit, valuing individuals"], ["Focus", "Groups defined by law", "Every individual difference"], ["Approach", "Reactive - treat everyone the same", "Proactive - meet differing needs"], ["Responsibility", "HR / personnel", "All managers"]], "id": "acfab-rv13-7d708-b2f486"}], "id": "acfab-rv13-7d708"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Thinking indirect discrimination needs intent - it arises from an unjustified condition that disadvantages a group", "id": "acfab-rv13-6483a-328222"}, {"t": "x", "text": "Believing codes of practice are legally binding - they are not, but tribunals take them into account", "id": "acfab-rv13-6483a-aae0bb"}, {"t": "x", "text": "Treating diversity as identical to equal opportunities - diversity goes beyond legal categories", "id": "acfab-rv13-6483a-ed7cb1"}, {"t": "x", "text": "Forgetting that discrimination law covers adverts and selection, not just existing employees", "id": "acfab-rv13-6483a-a6b648"}], "id": "acfab-rv13-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Equal opportunities = equal access to benefits and fair treatment", "id": "acfab-rv13-80e78-b06248"}, {"t": "pt", "text": "Grounds: sex/marital status, race etc, disability, sexual orientation/religion, age", "id": "acfab-rv13-80e78-fbda48"}, {"t": "pt", "text": "Direct = less favourable treatment; indirect = unjustified condition fewer of a group can meet", "id": "acfab-rv13-80e78-afbd87"}, {"t": "pt", "text": "Victimisation and harassment are also unlawful", "id": "acfab-rv13-80e78-56edc7"}, {"t": "pt", "text": "Law covers every stage from advert to dismissal", "id": "acfab-rv13-80e78-bcb972"}, {"t": "pt", "text": "Codes of practice: not law, but persuasive", "id": "acfab-rv13-80e78-1c2265"}, {"t": "pt", "text": "A policy statement may protect the employer in complaints", "id": "acfab-rv13-80e78-bd599a"}, {"t": "pt", "text": "Recruitment and selection are the most sensitive areas", "id": "acfab-rv13-80e78-b10ce3"}, {"t": "pt", "text": "Reasonable adjustments for disability", "id": "acfab-rv13-80e78-5afd21"}, {"t": "pt", "text": "Managing diversity values all individual differences", "id": "acfab-rv13-80e78-913984"}, {"t": "pt", "text": "Diversity is proactive; equal opportunities is compliance-led", "id": "acfab-rv13-80e78-633b35"}, {"t": "pt", "text": "Evaluate diversity with benchmarks, surveys and scorecards", "id": "acfab-rv13-80e78-d1757e"}], "id": "acfab-rv13-80e78"}], "source": "BPP Workbook ch 13: sections 1-4 pp344-350; chapter roundup p351", "summary": "Equal opportunities and why they matter, grounds of illegal discrimination, the practical implications for policy and recruitment, and the wider concept of managing diversity.", "id": "acfab-rv13", "updated": "2026-11-12"}, {"num": "14", "title": "Individuals, Groups and Teams", "pages": [355, 376], "syllabus": "D4", "status": "published", "branches": [{"kind": "concept", "title": "Individuals at work", "page": [356, 359], "items": [{"t": "def", "k": 1, "term": "Personality", "text": "The total pattern of an individual's thoughts, feelings and behaviour - shaped by inherited and environmental factors", "id": "acfab-rv14-f7ff7-fce3cc"}, {"t": "pt", "text": "Personality described by traits (eg introvert/extrovert) and types", "id": "acfab-rv14-f7ff7-001e14"}, {"t": "pt", "text": "Personality should be compatible with the task, the systems/management culture and other people", "id": "acfab-rv14-f7ff7-a84027"}, {"t": "def", "k": 1, "term": "Perception", "text": "The process by which the brain selects and organises information to make sense of it - people act on what they PERCEIVE, not on what really is", "id": "acfab-rv14-f7ff7-f881b4"}, {"t": "pt", "text": "Attitudes come from what people think, feel and want to do - formed by perception, experience and personality", "id": "acfab-rv14-f7ff7-d84248"}, {"t": "pt", "text": "Intelligence is wider than IQ: analytical, spatial, verbal, practical, emotional", "id": "acfab-rv14-f7ff7-15e9b8"}, {"t": "def", "k": 1, "term": "Role theory", "text": "People behave in a situation according to other people's expectations of how they should behave", "id": "acfab-rv14-f7ff7-400cd4"}], "id": "acfab-rv14-f7ff7"}, {"kind": "compare", "title": "Groups vs teams", "page": [360, 363], "items": [{"t": "table", "rows": [["Feature", "Group", "Team"], ["Definition", "Individuals who perceive themselves as a group - sense of identity", "More than a group: joint objectives and accountability"], ["Formation", "Formal or informal (cliques, networks)", "Usually set up by the organisation under a leader (or self-managed)"], ["Purpose", "Social needs, identity, information", "Organising work, control, ideas, decisions, pooling knowledge"]], "id": "acfab-rv14-bffaf-75d4e6"}, {"t": "pt", "k": 1, "text": "People contribute differently in groups (group dynamics, synergy) - positive or negative", "id": "acfab-rv14-bffaf-046183"}, {"t": "pt", "k": 1, "text": "Team problems: conflict on one hand, group think (excessive cohesion) on the other", "id": "acfab-rv14-bffaf-466c4a"}, {"t": "pt", "text": "Multi-disciplinary teams: people from different departments pooling specialist skills", "id": "acfab-rv14-bffaf-addfbd"}, {"t": "pt", "text": "Multi-skilled teams: individuals who can each perform any of the team's tasks", "id": "acfab-rv14-bffaf-948488"}, {"t": "pt", "text": "Virtual teams: members in remote locations linked by technology", "id": "acfab-rv14-bffaf-f534d8"}, {"t": "exam", "text": "ACCA article flagged: 'The importance of teams'", "id": "acfab-rv14-bffaf-9c940a"}], "id": "acfab-rv14-bffaf"}, {"kind": "concept", "title": "Belbin's team roles", "page": [363, 366], "items": [{"t": "pt", "k": 1, "text": "Nine roles: plant • resource investigator • co-ordinator • shaper • monitor-evaluator • teamworker • implementer • completer-finisher • specialist", "id": "acfab-rv14-32ed7-fd1301"}, {"t": "pt", "text": "Plant: creative, imaginative, solves difficult problems", "id": "acfab-rv14-32ed7-4c76a3"}, {"t": "pt", "text": "Resource investigator: extrovert, explores opportunities, develops contacts", "id": "acfab-rv14-32ed7-150b7a"}, {"t": "pt", "text": "Co-ordinator: mature, clarifies goals, delegates well (chairperson)", "id": "acfab-rv14-32ed7-2b986f"}, {"t": "pt", "text": "Shaper: challenging, dynamic, drive to overcome obstacles", "id": "acfab-rv14-32ed7-7ce055"}, {"t": "pt", "text": "Monitor-evaluator: sober, strategic, judges accurately", "id": "acfab-rv14-32ed7-216a37"}, {"t": "pt", "text": "Teamworker: co-operative, diplomatic, averts friction", "id": "acfab-rv14-32ed7-c6f0dc"}, {"t": "pt", "text": "Implementer: disciplined, turns ideas into practical action", "id": "acfab-rv14-32ed7-ef908f"}, {"t": "pt", "text": "Completer-finisher: painstaking, finds errors, delivers on time", "id": "acfab-rv14-32ed7-4fc8dd"}, {"t": "pt", "text": "Specialist: single-minded, provides scarce knowledge", "id": "acfab-rv14-32ed7-ce7a57"}, {"t": "pt", "text": "A balanced team covers all roles; individuals may hold more than one role or switch to back-up roles", "id": "acfab-rv14-32ed7-37e621"}, {"t": "pt", "text": "Contributions are made in task performance and team maintenance (proposing, supporting, blocking)", "id": "acfab-rv14-32ed7-75f19b"}], "id": "acfab-rv14-32ed7"}, {"kind": "process", "title": "Tuckman's stages of team development", "page": [367, 368], "items": [{"t": "pt", "k": 1, "text": "Forming -> storming -> norming -> performing (then dorming, or mourning/adjourning)", "id": "acfab-rv14-31417-c49162"}, {"t": "pt", "text": "Forming: the team comes together; members find out about each other and the task", "id": "acfab-rv14-31417-08d33c"}, {"t": "pt", "text": "Storming: conflict over objectives, roles and leadership", "id": "acfab-rv14-31417-24d23f"}, {"t": "pt", "text": "Norming: agreement on norms, procedures and roles", "id": "acfab-rv14-31417-7398bf"}, {"t": "pt", "text": "Performing: the team focuses on the task and is effective", "id": "acfab-rv14-31417-af39de"}, {"t": "pt", "text": "Dorming: the team grows complacent; mourning/adjourning: the team breaks up", "id": "acfab-rv14-31417-61cf77"}, {"t": "exam", "text": "Tuckman and Belbin are the named team models most often examined", "id": "acfab-rv14-31417-1cc364"}], "id": "acfab-rv14-31417"}, {"kind": "concept", "title": "Building and evaluating teams", "page": [368, 372], "items": [{"t": "pt", "k": 1, "text": "Team building supports team identity, solidarity and commitment to shared objectives", "id": "acfab-rv14-92cad-475dd4"}, {"t": "pt", "text": "Identity: name, logo, shared space, boundaries; solidarity: cohesion, loyalty, managing conflict; commitment: clear objectives, involvement, feedback", "id": "acfab-rv14-92cad-5830f7"}, {"t": "pt", "k": 1, "text": "Effectiveness criteria: quantifiable (output, quality, targets met, costs) and qualitative (member satisfaction, morale, low absenteeism and turnover)", "id": "acfab-rv14-92cad-6cb07d"}, {"t": "pt", "text": "Team rewards: group bonus schemes, profit sharing (pool of cash related to profit), gain sharing (formula linked to an indicator within employees' control), employee share option schemes", "id": "acfab-rv14-92cad-d93eee"}], "id": "acfab-rv14-92cad"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calling any group a team - a team has joint objectives and mutual accountability", "id": "acfab-rv14-6483a-81167c"}, {"t": "x", "text": "Mixing up the order of Tuckman's stages - storming comes BEFORE norming", "id": "acfab-rv14-6483a-a3343e"}, {"t": "x", "text": "Confusing the plant (ideas) with the resource investigator (external contacts)", "id": "acfab-rv14-6483a-497795"}, {"t": "x", "text": "Thinking high cohesion is always good - it can cause group think", "id": "acfab-rv14-6483a-4fe0f5"}], "id": "acfab-rv14-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Personality = total pattern of thoughts, feelings, behaviour", "id": "acfab-rv14-80e78-885af8"}, {"t": "pt", "text": "People act on perception, not reality", "id": "acfab-rv14-80e78-12a9cf"}, {"t": "pt", "text": "Role theory = behaviour follows others' expectations", "id": "acfab-rv14-80e78-95a016"}, {"t": "pt", "text": "Group = shared sense of identity", "id": "acfab-rv14-80e78-8f7215"}, {"t": "pt", "text": "Team = joint objectives and accountability", "id": "acfab-rv14-80e78-1e7162"}, {"t": "pt", "text": "Team problems: conflict and group think", "id": "acfab-rv14-80e78-bc3a40"}, {"t": "pt", "text": "Multi-disciplinary = different specialists; multi-skilled = each can do all tasks", "id": "acfab-rv14-80e78-54f42a"}, {"t": "pt", "text": "Belbin: plant, resource investigator, co-ordinator, shaper, monitor-evaluator, teamworker, implementer, completer-finisher, specialist", "id": "acfab-rv14-80e78-677a6f"}, {"t": "pt", "text": "Tuckman: forming, storming, norming, performing (dorming, adjourning)", "id": "acfab-rv14-80e78-3cf2c9"}, {"t": "pt", "text": "Team building: identity, solidarity, commitment", "id": "acfab-rv14-80e78-084c89"}, {"t": "pt", "text": "Team effectiveness: output and member satisfaction", "id": "acfab-rv14-80e78-f65c50"}, {"t": "pt", "text": "Team rewards: group bonus, profit sharing, gain sharing, share options", "id": "acfab-rv14-80e78-1512e3"}], "id": "acfab-rv14-80e78"}], "source": "BPP Workbook ch 14: sections 1-7 pp356-372; chapter roundup p373", "summary": "Individual differences (personality, perception, attitudes, roles), groups and teams, Belbin's team roles, Tuckman's stages, team building, evaluating and rewarding teams.", "id": "acfab-rv14", "updated": "2026-11-12"}, {"num": "15", "title": "Motivating Individuals and Groups", "pages": [377, 396], "syllabus": "D5", "status": "published", "branches": [{"kind": "concept", "title": "Motivation basics", "page": [378, 380], "items": [{"t": "def", "k": 1, "term": "Motivation", "text": "What causes people to act in a certain way - innate needs and the goals through which they expect to satisfy them drive behaviour", "id": "acfab-rv15-1ae60-7d51af"}, {"t": "pt", "text": "Motivation is useful even though its impact on performance is hard to measure", "id": "acfab-rv15-1ae60-bc45d5"}, {"t": "pt", "k": 1, "text": "Content theories: find out employees' needs and offer rewards that satisfy them (Maslow, Herzberg)", "id": "acfab-rv15-1ae60-2e56a7"}, {"t": "pt", "k": 1, "text": "Process theories: how people decide which rewards are worth going for (Vroom)", "id": "acfab-rv15-1ae60-1e4495"}, {"t": "exam", "text": "Motivation appears regularly in the exam; ACCA articles: 'Let's get motivated', 'Understanding Herzberg's motivational theory'", "id": "acfab-rv15-1ae60-6b2f32"}], "id": "acfab-rv15-1ae60"}, {"kind": "concept", "title": "Maslow's hierarchy of needs", "page": [381, 382], "items": [{"t": "pt", "k": 1, "text": "Five levels, lowest first: physiological -> safety -> love/social -> esteem -> self-actualisation", "id": "acfab-rv15-ee020-5ed953"}, {"t": "pt", "text": "A need, once satisfied, stops motivating; people progress to higher-order needs", "id": "acfab-rv15-ee020-bc6d49"}, {"t": "pt", "text": "Maslow also noted freedom of inquiry and the need for knowledge and understanding", "id": "acfab-rv15-ee020-957923"}, {"t": "pt", "text": "Evaluation: simple and intuitive, but needs do not always follow the order, and differ by culture and individual", "id": "acfab-rv15-ee020-abdc71"}], "id": "acfab-rv15-ee020"}, {"kind": "compare", "title": "Herzberg's two-factor theory", "page": [382, 383], "items": [{"t": "table", "rows": [["Factor type", "Need system", "Examples", "Effect"], ["Hygiene (maintenance)", "Avoid unpleasantness", "Company policy, supervision, salary, interpersonal relations, working conditions, job security", "Absence causes dissatisfaction; presence only prevents it"], ["Motivators", "Personal growth", "Achievement, recognition, the work itself, responsibility, advancement", "Create satisfaction and motivate"]], "id": "acfab-rv15-e9ff0-183fec"}, {"t": "pt", "k": 1, "text": "Pay is the most important hygiene factor - but it can still be a powerful short-term motivator (eg a bonus)", "id": "acfab-rv15-e9ff0-77e9dc"}, {"t": "pt", "text": "Criticised: based on 203 Pittsburgh engineers and accountants - a narrow sample", "id": "acfab-rv15-e9ff0-c1b088"}], "id": "acfab-rv15-e9ff0"}, {"kind": "formula", "title": "Vroom's expectancy theory", "page": [383, 384], "items": [{"t": "f", "k": 1, "term": "Expectancy theory", "text": "F = V x E", "vars": "F = force (strength of motivation); V = valence (strength of preference for an outcome); E = expectation that behaviour will produce the outcome", "eg": "If V or E is 0, there is NO motivation", "id": "acfab-rv15-510ff-f05612"}, {"t": "pt", "text": "Managerial implications: make intended results clear, make rewards valued, link reward clearly to performance, give feedback", "id": "acfab-rv15-510ff-971bcf"}, {"t": "exam", "text": "This equation could be the subject of a one-mark question", "id": "acfab-rv15-510ff-b9bff0"}], "id": "acfab-rv15-510ff"}, {"kind": "compare", "title": "McGregor: Theory X vs Theory Y", "page": [384, 384], "items": [{"t": "table", "rows": [["Theory X", "Theory Y"], ["People dislike work and avoid it", "Work is as natural as play or rest"], ["Must be coerced, controlled and threatened", "Will exercise self-direction towards objectives they are committed to"], ["Prefer to be directed and avoid responsibility", "Accept and seek responsibility"], ["Motivated mainly by money and security", "Motivated by achievement and self-fulfilment"]], "id": "acfab-rv15-3bdb1-1f8087"}, {"t": "pt", "text": "Managers' assumptions shape their approach; treating people as Theory X can become self-fulfilling", "id": "acfab-rv15-3bdb1-9328ba"}], "id": "acfab-rv15-3bdb1"}, {"kind": "concept", "title": "Rewards and job design", "page": [385, 388], "items": [{"t": "def", "k": 1, "term": "Extrinsic rewards", "text": "External to the work and the individual - pay, benefits, working conditions", "id": "acfab-rv15-98473-0911ac"}, {"t": "def", "k": 1, "term": "Intrinsic rewards", "text": "Arise from performance of the work itself - satisfaction, sense of achievement, challenge", "id": "acfab-rv15-98473-135d83"}, {"t": "exam", "text": "Candidates often get this wrong: 'enjoyment of the job' is INTRINSIC", "id": "acfab-rv15-98473-f9de5b"}, {"t": "pt", "text": "Reward system should: attract and retain staff, increase predictability of behaviour, encourage flexibility, support goals, be fair, be cost-effective", "id": "acfab-rv15-98473-723d9b"}, {"t": "pt", "k": 1, "text": "Job enrichment: VERTICAL extension - more responsibility, planning and decision-making", "id": "acfab-rv15-98473-d73fb3"}, {"t": "pt", "k": 1, "text": "Job enlargement: HORIZONTAL extension - more tasks of a similar level", "id": "acfab-rv15-98473-2c735d"}, {"t": "pt", "k": 1, "text": "Job rotation: planned transfer between jobs for variety (sequential extension)", "id": "acfab-rv15-98473-eef81e"}, {"t": "pt", "text": "Job optimisation core dimensions (Hackman and Oldham): skill variety, task identity, task significance, autonomy, feedback", "id": "acfab-rv15-98473-81b34a"}, {"t": "pt", "text": "Constructive feedback and genuine participation in decision-making increase commitment", "id": "acfab-rv15-98473-ad767f"}, {"t": "pt", "text": "Inappropriate rewards: bonuses regardless of performance, pay rises not linked to results", "id": "acfab-rv15-98473-da4b14"}], "id": "acfab-rv15-98473"}, {"kind": "concept", "title": "Pay as a motivator", "page": [388, 392], "items": [{"t": "pt", "text": "Pay determined by job evaluation, market rates, negotiation, individual performance", "id": "acfab-rv15-ef686-9d7c81"}, {"t": "def", "k": 1, "term": "Performance-related pay (PRP)", "text": "An incentive system awarding extra pay for extra output or performance", "id": "acfab-rv15-ef686-b63634"}, {"t": "pt", "text": "PRP benefits: commitment, focus on business performance; problems: subjective assessment, short-termism, divisive, budgets cap rewards", "id": "acfab-rv15-ef686-eb9c68"}, {"t": "pt", "text": "Group rewards: group bonus schemes, profit sharing, gain sharing", "id": "acfab-rv15-ef686-94b500"}, {"t": "pt", "text": "Golden handcuffs: long-term rewards (eg share options) to retain key staff", "id": "acfab-rv15-ef686-28396b"}, {"t": "pt", "text": "Golden handshake: extra payment when a senior executive leaves", "id": "acfab-rv15-ef686-73a7a5"}, {"t": "pt", "text": "Voluntary redundancy: generous payments to volunteers retain goodwill of remaining staff", "id": "acfab-rv15-ef686-73842c"}], "id": "acfab-rv15-ef686"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Treating pay as a Herzberg motivator - it is a hygiene factor", "id": "acfab-rv15-6483a-09a699"}, {"t": "x", "text": "Calling 'enjoyment of the job' an extrinsic reward - it is intrinsic", "id": "acfab-rv15-6483a-ef5734"}, {"t": "x", "text": "Confusing job enrichment (vertical, more responsibility) with job enlargement (horizontal, more tasks)", "id": "acfab-rv15-6483a-b489ec"}, {"t": "x", "text": "Forgetting that in F = V x E a zero in either factor gives zero motivation", "id": "acfab-rv15-6483a-35b494"}], "id": "acfab-rv15-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Content theories: Maslow, Herzberg; process theory: Vroom", "id": "acfab-rv15-80e78-f093b5"}, {"t": "pt", "text": "Maslow: physiological, safety, social, esteem, self-actualisation", "id": "acfab-rv15-80e78-247f60"}, {"t": "pt", "text": "Herzberg hygiene: policy, supervision, pay, relations, conditions, security", "id": "acfab-rv15-80e78-9a9ab2"}, {"t": "pt", "text": "Herzberg motivators: achievement, recognition, work itself, responsibility, advancement", "id": "acfab-rv15-80e78-57b969"}, {"t": "pt", "text": "Vroom: F = V x E", "id": "acfab-rv15-80e78-432692"}, {"t": "pt", "text": "Theory X coerce; Theory Y empower", "id": "acfab-rv15-80e78-c4f8f1"}, {"t": "pt", "text": "Extrinsic = external rewards; intrinsic = from the work itself", "id": "acfab-rv15-80e78-564f7a"}, {"t": "pt", "text": "Enrichment vertical; enlargement horizontal; rotation sequential", "id": "acfab-rv15-80e78-73d187"}, {"t": "pt", "text": "Core job dimensions: variety, identity, significance, autonomy, feedback", "id": "acfab-rv15-80e78-3a562c"}, {"t": "pt", "text": "PRP = extra pay for extra performance", "id": "acfab-rv15-80e78-901796"}, {"t": "pt", "text": "Golden handcuffs retain; golden handshake on leaving", "id": "acfab-rv15-80e78-568ef4"}, {"t": "pt", "text": "Pay: main hygiene factor, short-term motivator", "id": "acfab-rv15-80e78-47a5ca"}], "id": "acfab-rv15-80e78"}], "source": "BPP Workbook ch 15: sections 1-6 pp378-392; chapter roundup p393", "summary": "Content theories (Maslow, Herzberg), process theory (Vroom), McGregor's X and Y, intrinsic and extrinsic rewards, job design, feedback, participation and pay as a motivator.", "id": "acfab-rv15", "updated": "2026-11-12"}, {"num": "16", "title": "Training and Development", "pages": [397, 418], "syllabus": "D6", "status": "published", "branches": [{"kind": "concept", "title": "How people learn", "page": [398, 401], "items": [{"t": "pt", "k": 1, "text": "Schools of learning theory: behaviourist (stimulus-response, reinforcement) and cognitive (information processing, understanding)", "id": "acfab-rv16-4cc28-b2c2b0"}, {"t": "pt", "text": "Lessons: clear objectives, motivation to learn, feedback, active participation, reinforcement, practice", "id": "acfab-rv16-4cc28-8746d7"}, {"t": "pt", "k": 1, "text": "Honey and Mumford learning styles: activist (learns by doing) • reflector (observes and thinks) • theorist (needs models and concepts) • pragmatist (wants practical application)", "id": "acfab-rv16-4cc28-023a62"}, {"t": "pt", "k": 1, "text": "Kolb's learning cycle: concrete experience -> reflective observation -> abstract conceptualisation (generalisation) -> active experimentation (application)", "id": "acfab-rv16-4cc28-869ca6"}, {"t": "def", "k": 1, "term": "Learning organisation", "text": "An organisation that facilitates the learning of all its members (Pedler et al) - gathering and sharing knowledge, tolerating experiment and solving problems analytically", "id": "acfab-rv16-4cc28-a3ad5e"}, {"t": "pt", "text": "Learning organisations are good at: systematic problem-solving, experimentation, learning from past experience and from others, transferring knowledge", "id": "acfab-rv16-4cc28-778c1b"}, {"t": "exam", "text": "Honey and Mumford and Kolb are named in the Study Guide", "id": "acfab-rv16-4cc28-795dd7"}], "id": "acfab-rv16-4cc28"}, {"kind": "concept", "title": "Purpose and benefits of training", "page": [401, 404], "items": [{"t": "pt", "k": 1, "text": "Main purpose: raise competence and therefore performance standards; also personal development and motivation", "id": "acfab-rv16-71a16-df5095"}, {"t": "pt", "text": "Factors affecting job performance include ability, motivation, the work environment - training addresses only some", "id": "acfab-rv16-71a16-046eb0"}, {"t": "pt", "text": "Organisation benefits: lower cost of obtaining skills, higher productivity and quality, flexibility, commitment and retention, succession, supports change", "id": "acfab-rv16-71a16-112f5e"}, {"t": "pt", "text": "Employee benefits: enhanced skills and employability, promotion prospects, satisfaction, confidence", "id": "acfab-rv16-71a16-57f1bc"}, {"t": "x", "text": "Training is not the solution to every work problem - poor performance may come from motivation or systems", "id": "acfab-rv16-71a16-dda338"}], "id": "acfab-rv16-71a16"}, {"kind": "process", "title": "Systematic approach to training", "page": [404, 408], "items": [{"t": "pt", "k": 1, "text": "Steps: define needs -> set objectives -> plan programmes -> deliver training -> evaluate results", "id": "acfab-rv16-cdb7c-ed2845"}, {"t": "pt", "text": "Indicators of need: new legislation, new technology or products, poor performance, new recruits, promotions, complaints", "id": "acfab-rv16-cdb7c-5ed0e3"}, {"t": "f", "k": 1, "term": "Training gap", "text": "Required level of competence - Present level of competence = Training need", "vars": "required level from job analysis; present level from appraisal and assessment", "eg": "Job needs 'prepare a trial balance'; employee can only post ledgers -> train on extracting and balancing", "id": "acfab-rv16-cdb7c-e1e6c9"}, {"t": "pt", "text": "Training objectives should be clear, specific and measurable (what the trainee will be able to do)", "id": "acfab-rv16-cdb7c-c8eb7e"}, {"t": "pt", "text": "Personal development plan: analyse current position -> set goals -> draw up an action plan -> implement -> review", "id": "acfab-rv16-cdb7c-dafaef"}], "id": "acfab-rv16-cdb7c"}, {"kind": "compare", "title": "Training methods", "page": [408, 411], "items": [{"t": "table", "rows": [["Method", "Advantages", "Disadvantages"], ["Off the job (courses, e-learning, college)", "Minimises risk; focused time away from work; expert trainers", "Transfer of learning to the job is not guaranteed; cost; time away"], ["On the job (coaching, job rotation, temporary promotion, assistant-to, committees, projects)", "Maximises transfer of learning; real tasks; cheap", "Distractions; errors on real work; trainer may lack skill"]], "id": "acfab-rv16-d01f3-b8eef0"}, {"t": "pt", "k": 1, "text": "Off the job minimises risk; on the job maximises transfer of learning", "id": "acfab-rv16-d01f3-5320c2"}, {"t": "def", "k": 1, "term": "Induction", "text": "The process whereby a person is formally introduced and integrated into an organisation or system", "id": "acfab-rv16-d01f3-7a6abc"}, {"t": "pt", "text": "Induction purposes: get bearings, begin socialisation, start training, set expectations; starts with the immediate superior", "id": "acfab-rv16-d01f3-5570f8"}], "id": "acfab-rv16-d01f3"}, {"kind": "concept", "title": "Responsibility and evaluation", "page": [412, 413], "items": [{"t": "pt", "k": 1, "text": "Responsibility is increasingly devolved to the individual learner, with line managers and training providers", "id": "acfab-rv16-52060-29e5f2"}, {"t": "pt", "text": "HR/training department: strategy, programmes, records; line managers: identify needs, coach, give opportunities; training manager: arranges and runs training", "id": "acfab-rv16-52060-a28fd5"}, {"t": "def", "term": "Validation", "text": "Observing the results of the course and measuring whether training objectives have been met", "id": "acfab-rv16-52060-4c15f8"}, {"t": "def", "term": "Evaluation", "text": "Comparing the costs of training with the benefits to the organisation", "id": "acfab-rv16-52060-87abcf"}, {"t": "pt", "k": 1, "text": "Hamblin's five levels: 1 trainees' reactions -> 2 learning achieved -> 3 changes in job behaviour -> 4 impact on organisational/departmental results -> 5 ultimate value (goals such as growth, profitability)", "id": "acfab-rv16-52060-0c88b5"}], "id": "acfab-rv16-52060"}, {"kind": "concept", "title": "Development", "page": [413, 414], "items": [{"t": "def", "k": 1, "term": "Development", "text": "A range of learning activities and experiences (not just training) to enhance competence, experience and capability for personal, professional or career progression", "id": "acfab-rv16-759b7-ffd0e6"}, {"t": "pt", "text": "Approaches: management development (MBA, planned experience) • career development (lateral moves, secondments in delayered organisations) • professional development (CPD) • personal development", "id": "acfab-rv16-759b7-43face"}, {"t": "pt", "text": "CPD: professional qualification as the basis for lifelong development and adherence to ethics", "id": "acfab-rv16-759b7-a4eb23"}], "id": "acfab-rv16-759b7"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Mixing up Honey and Mumford's styles with Kolb's stages - styles are preferences; Kolb is a cycle", "id": "acfab-rv16-6483a-b329c4"}, {"t": "x", "text": "Thinking off the job training guarantees transfer to the job - it minimises risk but transfer is weak", "id": "acfab-rv16-6483a-a8ac39"}, {"t": "x", "text": "Treating validation and evaluation as the same - validation checks objectives; evaluation compares costs and benefits", "id": "acfab-rv16-6483a-a4d19e"}, {"t": "x", "text": "Saying training fixes every performance problem", "id": "acfab-rv16-6483a-1325a3"}], "id": "acfab-rv16-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Learning styles: activist, reflector, theorist, pragmatist", "id": "acfab-rv16-80e78-39c883"}, {"t": "pt", "text": "Kolb: experience, reflection, conceptualisation, experimentation", "id": "acfab-rv16-80e78-9245a2"}, {"t": "pt", "text": "Learning organisation facilitates learning of all members", "id": "acfab-rv16-80e78-1ca30b"}, {"t": "pt", "text": "Training purpose: raise competence and performance", "id": "acfab-rv16-80e78-dc90d2"}, {"t": "pt", "text": "Systematic training: needs, objectives, plan, deliver, evaluate", "id": "acfab-rv16-80e78-f34e17"}, {"t": "pt", "text": "Training need = required competence - present competence", "id": "acfab-rv16-80e78-fc3692"}, {"t": "pt", "text": "Off the job minimises risk; on the job maximises transfer", "id": "acfab-rv16-80e78-fcb59e"}, {"t": "pt", "text": "Induction = formal introduction and integration", "id": "acfab-rv16-80e78-cd5b52"}, {"t": "pt", "text": "Responsibility moving to the individual learner", "id": "acfab-rv16-80e78-0c8fa9"}, {"t": "pt", "text": "Validation = objectives met; evaluation = costs vs benefits", "id": "acfab-rv16-80e78-57a1b4"}, {"t": "pt", "text": "Hamblin: reactions, learning, job behaviour, organisation results, ultimate value", "id": "acfab-rv16-80e78-333352"}, {"t": "pt", "text": "Development is wider than training", "id": "acfab-rv16-80e78-7ba026"}, {"t": "pt", "text": "CPD maintains professional standards", "id": "acfab-rv16-80e78-7fd050"}], "id": "acfab-rv16-80e78"}], "source": "BPP Workbook ch 16: sections 1-7 pp398-414; chapter roundup p415", "summary": "Learning theory and styles (Honey and Mumford, Kolb), the learning organisation, the systematic approach to training, training needs analysis, methods, induction, responsibilities, evaluation (Hamblin) and development.", "id": "acfab-rv16", "updated": "2026-11-12"}, {"num": "17", "title": "Performance Appraisal", "pages": [419, 434], "syllabus": "D7", "status": "published", "branches": [{"kind": "concept", "title": "Performance management", "page": [420, 421], "items": [{"t": "def", "k": 1, "term": "Performance management", "text": "Getting better results for the organisation by measuring and evaluating individual performance against agreed objectives, standards and competences", "id": "acfab-rv17-3fd4f-5b4ef1"}, {"t": "pt", "text": "Steps: identify key objectives -> agree targets and performance standards -> continuous monitoring and feedback -> formal appraisal -> agree development and new objectives", "id": "acfab-rv17-3fd4f-1f9909"}, {"t": "exam", "text": "ACCA article flagged: 'Understanding the importance of appraisals'", "id": "acfab-rv17-3fd4f-0cf4af"}], "id": "acfab-rv17-3fd4f"}, {"kind": "concept", "title": "Purposes of appraisal", "page": [422, 423], "items": [{"t": "pt", "k": 1, "text": "Three components: reward review (pay, bonus) • performance review (planning and improvement) • potential review (promotion and development)", "id": "acfab-rv17-a6cf8-0eccd6"}, {"t": "pt", "text": "Specific objectives: establish what the individual should be doing; assess performance; identify training needs; assess potential; set targets; improve communication; motivate", "id": "acfab-rv17-a6cf8-14cde2"}, {"t": "pt", "k": 1, "text": "Formal appraisal supports objective, positive, relevant and consistent feedback - informal judgement alone is subjective and irregular", "id": "acfab-rv17-a6cf8-52f517"}, {"t": "pt", "text": "Three basic requirements of a formal system: define what is to be appraised, record assessments, have the appraiser and appraisee discuss them", "id": "acfab-rv17-a6cf8-5292e2"}], "id": "acfab-rv17-a6cf8"}, {"kind": "compare", "title": "Appraisal techniques", "page": [424, 426], "items": [{"t": "table", "rows": [["Technique", "How it works", "Weakness"], ["Overall assessment", "Narrative judgement written by the manager", "No consistent criteria"], ["Guided assessment", "Comments on specified characteristics with guidelines", "More precise but still vague"], ["Grading (rating scales)", "Select a level for each characteristic, possibly scored", "Raters cluster around the middle"], ["Behavioural incident methods", "Assess actual behaviour against typical job incidents", "Time-consuming to design"], ["Results-oriented", "Performance against agreed targets (MBO)", "Targets may be outside the person's control"], ["Self-appraisal", "Individuals evaluate themselves as a major input", "May be lenient or over-critical"]], "id": "acfab-rv17-4a30c-022c09"}, {"t": "pt", "k": 1, "text": "Assessments must relate to a common standard so individuals can be compared", "id": "acfab-rv17-4a30c-919ed3"}], "id": "acfab-rv17-4a30c"}, {"kind": "process", "title": "The appraisal interview and follow-up", "page": [426, 428], "items": [{"t": "pt", "k": 1, "text": "Steps: prepare (review self-appraisal) -> interview (choose a style; encourage the employee to talk) -> agree (summarise, gain commitment, action plan) -> report -> follow up", "id": "acfab-rv17-a5654-3704e4"}, {"t": "pt", "k": 1, "text": "Maier's three approaches", "kids": [{"t": "pt", "text": "Tell and sell: manager tells the assessment and tries to persuade acceptance", "id": "acfab-rv17-a5654-658c5f"}, {"t": "pt", "text": "Tell and listen: manager tells, then invites the appraisee to respond - more coaching", "id": "acfab-rv17-a5654-2cc774"}, {"t": "pt", "text": "Problem-solving: manager and appraisee jointly identify problems and solutions - most appraisees prefer this", "id": "acfab-rv17-a5654-bf67d1"}], "id": "acfab-rv17-a5654-fe3931"}, {"t": "pt", "text": "Follow-up: inform appraisees of results, carry out agreed actions (training, promotion), monitor progress, provide help to reach objectives", "id": "acfab-rv17-a5654-563a1e"}, {"t": "x", "text": "Without follow-up an appraisal becomes a pleasant chat with no effect on performance", "id": "acfab-rv17-a5654-3f66d8"}], "id": "acfab-rv17-a5654"}, {"kind": "concept", "title": "Barriers and new approaches", "page": [428, 430], "items": [{"t": "pt", "k": 1, "text": "Lockett's barriers: appraisal as confrontation • as judgement • as chat • as bureaucracy • as unfinished business • as an annual event", "id": "acfab-rv17-23cad-b98d10"}, {"t": "exam", "text": "Lockett's list is the accepted framework for discussing barriers to appraisal - learn it", "id": "acfab-rv17-23cad-390a2e"}, {"t": "pt", "text": "Linking appraisal to pay: staff may hide weaknesses to protect rewards; many organisations separate pay review from development review", "id": "acfab-rv17-23cad-4cd448"}, {"t": "def", "term": "Upward appraisal", "text": "Subordinates appraise their manager", "id": "acfab-rv17-23cad-4d6b5c"}, {"t": "def", "term": "360-degree feedback", "text": "Performance assessed from several perspectives - superiors, peers, subordinates, customers and self", "id": "acfab-rv17-23cad-ca382d"}, {"t": "pt", "text": "Customer appraisal: feedback from internal or external customers forms part of the assessment", "id": "acfab-rv17-23cad-2b67fe"}], "id": "acfab-rv17-23cad"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calling 'tell and sell' the most effective Maier style - the problem-solving approach is preferred", "id": "acfab-rv17-6483a-d754a7"}, {"t": "x", "text": "Thinking appraisal is only about pay - it also covers performance and potential", "id": "acfab-rv17-6483a-6d8c0f"}, {"t": "x", "text": "Treating the appraisal as an annual event with no follow-up", "id": "acfab-rv17-6483a-a9381e"}, {"t": "x", "text": "Confusing upward appraisal (subordinates rate the boss) with 360-degree feedback (many sources)", "id": "acfab-rv17-6483a-207fed"}], "id": "acfab-rv17-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Performance management = objectives, monitoring, feedback, appraisal, development", "id": "acfab-rv17-80e78-7e7cf9"}, {"t": "pt", "text": "Appraisal components: reward, performance, potential", "id": "acfab-rv17-80e78-f16534"}, {"t": "pt", "text": "Formal system: define criteria, record, discuss", "id": "acfab-rv17-80e78-646ed4"}, {"t": "pt", "text": "Techniques: overall, guided, grading, behavioural, results-oriented, self-appraisal", "id": "acfab-rv17-80e78-2920a5"}, {"t": "pt", "text": "Interview: prepare, interview, agree, report, follow up", "id": "acfab-rv17-80e78-621e98"}, {"t": "pt", "text": "Maier: tell and sell, tell and listen, problem-solving", "id": "acfab-rv17-80e78-a5709b"}, {"t": "pt", "text": "Problem-solving style is preferred by most appraisees", "id": "acfab-rv17-80e78-563193"}, {"t": "pt", "text": "Lockett: confrontation, judgement, chat, bureaucracy, unfinished business, annual event", "id": "acfab-rv17-80e78-e27436"}, {"t": "pt", "text": "Pay link can make staff hide weaknesses", "id": "acfab-rv17-80e78-b69af4"}, {"t": "pt", "text": "Upward appraisal: subordinates rate the manager", "id": "acfab-rv17-80e78-a87a32"}, {"t": "pt", "text": "360-degree: superiors, peers, subordinates, customers, self", "id": "acfab-rv17-80e78-7e40ec"}, {"t": "pt", "text": "Follow-up turns appraisal into action", "id": "acfab-rv17-80e78-aaa4f1"}], "id": "acfab-rv17-80e78"}], "source": "BPP Workbook ch 17: sections 1-4 pp420-430; appraisal interview pp426-428", "summary": "Performance management, the purposes and process of appraisal, appraisal techniques, the appraisal interview (Maier), follow-up, barriers to effective appraisal (Lockett) and newer techniques such as upward, 360-degree and customer appraisal.", "id": "acfab-rv17", "updated": "2026-11-12"}, {"num": "18", "title": "Personal Effectiveness and Communication", "pages": [435, 474], "syllabus": "E1, E2", "status": "published", "branches": [{"kind": "process", "title": "Time management", "page": [437, 440], "items": [{"t": "pt", "k": 1, "text": "Time is a scarce resource: recognise urgency and importance", "id": "acfab-rv18-ed4e9-931e5e"}, {"t": "pt", "text": "Principles: goals -> action plans -> priorities -> urgency (do it now) -> organisation (checklists, schedules, a tidy workspace)", "id": "acfab-rv18-ed4e9-840099"}, {"t": "pt", "k": 1, "text": "Prioritise by relative consequences, time-sensitivity and dependencies; plan each day with important as well as urgent tasks", "id": "acfab-rv18-ed4e9-a96573"}, {"t": "pt", "text": "Work planning: establishing priorities • loading (allocation of tasks) • sequencing • scheduling (timetables)", "id": "acfab-rv18-ed4e9-91b610"}, {"t": "exam", "text": "Expect questions on helping OTHERS with their time management - do not dismiss it as common sense", "id": "acfab-rv18-ed4e9-1969ba"}], "id": "acfab-rv18-ed4e9"}, {"kind": "concept", "title": "Technology and effectiveness", "page": [441, 444], "items": [{"t": "pt", "text": "Tools: mobile communications, voice messaging, bulletin boards, videoconferencing, Electronic Data Interchange (computer-to-computer exchange of documents)", "id": "acfab-rv18-69669-9d3252"}, {"t": "pt", "text": "Office automation: routine processing, (more) paperless office, better management information, flatter structures, better customer service, homeworking", "id": "acfab-rv18-69669-bae695"}, {"t": "pt", "text": "Intranets deliver training; proprietary tools enable video calls and collaboration", "id": "acfab-rv18-69669-8a2447"}, {"t": "pt", "text": "Employee ineffectiveness: failing to communicate problems, missing deadlines, poor time management - so problems are not spotted in time", "id": "acfab-rv18-69669-72d31f"}], "id": "acfab-rv18-69669"}, {"kind": "compare", "title": "Coaching, mentoring and counselling", "page": [444, 448], "items": [{"t": "table", "rows": [["Approach", "Relationship", "Purpose"], ["Coaching", "Trainee guided by an experienced employee on the job", "Learn to do specific tasks better"], ["Mentoring", "Long-term; experienced person as teacher, counsellor, role model, supporter", "Career and personal development"], ["Counselling", "Interpersonal interview facilitating the other person", "Help them define and work through their own problems"]], "id": "acfab-rv18-b79ff-9ee2b5"}, {"t": "def", "k": 1, "term": "Competence framework", "text": "Sets out what an employee should be able to do and ought to know - fairer assessment, but hard to develop", "id": "acfab-rv18-b79ff-512b53"}, {"t": "pt", "k": 1, "text": "Counselling is facilitative, not directive - the counsellee finds their own solutions; confidentiality is essential", "id": "acfab-rv18-b79ff-b97b0e"}, {"t": "pt", "text": "Counselling benefits the organisation: retains staff, resolves problems early, shows care", "id": "acfab-rv18-b79ff-860a00"}, {"t": "pt", "text": "Personal development plan: analyse current position -> set objectives -> plan actions -> implement -> review", "id": "acfab-rv18-b79ff-840148"}], "id": "acfab-rv18-b79ff"}, {"kind": "concept", "title": "Conflict and grievances", "page": [450, 456], "items": [{"t": "def", "k": 1, "term": "Conflict", "text": "The clash of opposing forces - personalities, interests, opinions or beliefs of individuals or groups", "id": "acfab-rv18-64f62-6d32be"}, {"t": "pt", "k": 1, "text": "Management responses: denial/withdrawal • suppression (smoothing over) • dominance (win-lose resentment) • compromise (bargaining) • integration/collaboration (focus on the task)", "id": "acfab-rv18-64f62-e5786e"}, {"t": "pt", "k": 1, "text": "Win-win model: outcomes can be win-lose, lose-lose or win-win - aim for win-win where both parties' needs are met", "id": "acfab-rv18-64f62-c1d91e"}, {"t": "pt", "text": "Know the limits of your own authority - refer to the line manager or HR when needed", "id": "acfab-rv18-64f62-55dfac"}, {"t": "def", "term": "Grievance", "text": "When an individual thinks they are being wrongly treated by colleagues or supervisor", "id": "acfab-rv18-64f62-df4471"}, {"t": "pt", "text": "Formal grievance procedure: raise with immediate superior -> next level of management -> appeal, with a right to be accompanied and time limits", "id": "acfab-rv18-64f62-1061ff"}], "id": "acfab-rv18-64f62"}, {"kind": "concept", "title": "Information for decisions", "page": [456, 461], "items": [{"t": "pt", "text": "Communication flows downwards, upwards, sideways (lateral) and diagonally", "id": "acfab-rv18-1e6f4-4c4e7f"}, {"t": "pt", "text": "Communication patterns: wheel, chain, Y, circle, all-channel - centralised patterns are fast for simple tasks; all-channel is better for complex problems", "id": "acfab-rv18-1e6f4-c28deb"}, {"t": "pt", "text": "Internal sources: accounting records, other internal records, staff; external: tax specialists, legal advisers, trade bodies, government, the internet", "id": "acfab-rv18-1e6f4-5d319b"}, {"t": "pt", "k": 1, "text": "Information is needed for planning, controlling and decision-making", "id": "acfab-rv18-1e6f4-f2705f"}, {"t": "pt", "k": 1, "text": "Good information - ACCURATE: Accurate • Complete • Cost-beneficial • User-targeted • Relevant • Authoritative • Timely • Easy to use", "id": "acfab-rv18-1e6f4-187349"}, {"t": "exam", "text": "The qualities of good information are named in the Study Guide", "id": "acfab-rv18-1e6f4-806ab8"}], "id": "acfab-rv18-1e6f4"}, {"kind": "process", "title": "The communication process", "page": [462, 468], "items": [{"t": "pt", "k": 1, "text": "Radio signal model: sender encodes -> message transmitted through a channel/medium -> receiver decodes -> feedback; noise can distort at any stage", "id": "acfab-rv18-96777-2526bb"}, {"t": "def", "k": 1, "term": "Effective communication", "text": "The right person receives the right information in the right way at the right time", "id": "acfab-rv18-96777-00bdf2"}, {"t": "pt", "text": "Informal communication: the grapevine - fast, selective, often accurate, uses informal networks; managers may rely on it", "id": "acfab-rv18-96777-7a2199"}, {"t": "pt", "text": "Interpersonal skills: active listening, reading non-verbal communication (body language), observation", "id": "acfab-rv18-96777-8352ae"}, {"t": "pt", "k": 1, "text": "Barriers: noise, poorly coded/decoded messages, status differences, jargon, information overload, distrust, cultural differences, secrecy, physical distance", "id": "acfab-rv18-96777-2b76e3"}, {"t": "pt", "text": "Overcoming barriers: better links, recorded standing instructions, training in communication, confirmation of messages in more than one form, feedback", "id": "acfab-rv18-96777-d93ac0"}, {"t": "pt", "text": "Method choice: speed, cost, confidentiality, need for a record, complexity, audience (meeting, phone, email, memo, report, notice board)", "id": "acfab-rv18-96777-254d01"}], "id": "acfab-rv18-96777"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Treating counselling as giving advice - it facilitates the person to solve their own problem", "id": "acfab-rv18-6483a-f5d7d9"}, {"t": "x", "text": "Calling compromise a win-win solution - both parties give something up", "id": "acfab-rv18-6483a-7bab13"}, {"t": "x", "text": "Forgetting feedback in the communication model", "id": "acfab-rv18-6483a-1bb2fc"}, {"t": "x", "text": "Confusing coaching (task skills, short term) with mentoring (long-term development)", "id": "acfab-rv18-6483a-5da7b5"}], "id": "acfab-rv18-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Time management: goals, plans, priorities, urgency, organisation", "id": "acfab-rv18-80e78-9a5196"}, {"t": "pt", "text": "Work planning: prioritise, load, sequence, schedule", "id": "acfab-rv18-80e78-e080df"}, {"t": "pt", "text": "Competence framework = what staff should do and know", "id": "acfab-rv18-80e78-3a81ea"}, {"t": "pt", "text": "Coaching task-focused; mentoring long-term; counselling facilitative", "id": "acfab-rv18-80e78-3876a5"}, {"t": "pt", "text": "Conflict responses: denial, suppression, dominance, compromise, integration", "id": "acfab-rv18-80e78-aff225"}, {"t": "pt", "text": "Aim for win-win outcomes", "id": "acfab-rv18-80e78-885fda"}, {"t": "pt", "text": "Grievance = feeling wrongly treated; use the formal procedure", "id": "acfab-rv18-80e78-4f8001"}, {"t": "pt", "text": "Communication flows: down, up, lateral, diagonal", "id": "acfab-rv18-80e78-cf6f56"}, {"t": "pt", "text": "ACCURATE: accurate, complete, cost-beneficial, user-targeted, relevant, authoritative, timely, easy to use", "id": "acfab-rv18-80e78-dc9ed0"}, {"t": "pt", "text": "Information supports planning, control and decisions", "id": "acfab-rv18-80e78-888765"}, {"t": "pt", "text": "Communication model: encode, transmit, decode, feedback, noise", "id": "acfab-rv18-80e78-fc08d3"}, {"t": "pt", "text": "Grapevine: fast, selective, informal", "id": "acfab-rv18-80e78-32c8b1"}, {"t": "pt", "text": "Barriers: noise, status, jargon, overload, culture, distance", "id": "acfab-rv18-80e78-7fdaec"}], "id": "acfab-rv18-80e78"}], "source": "BPP Workbook ch 18: sections 1-10 pp437-468", "summary": "Time management, technology for personal effectiveness, competence frameworks, coaching, mentoring and counselling, conflict and grievances, information, the communication process, informal channels and barriers.", "id": "acfab-rv18", "updated": "2026-11-12"}, {"num": "19", "title": "Ethical Considerations", "pages": [475, 500], "syllabus": "F1", "status": "published", "branches": [{"kind": "concept", "title": "Rules and governance concepts", "page": [477, 480], "items": [{"t": "pt", "text": "Three main sources of rules: law, ethics and governance (corporate codes)", "id": "acfab-rv19-0aa16-d5c77b"}, {"t": "pt", "k": 1, "text": "Governance concepts: fairness • openness/transparency • probity/honesty • responsibility • accountability • reputation • judgement • integrity", "id": "acfab-rv19-0aa16-db8e11"}, {"t": "pt", "text": "Transparency: open and clear disclosure of relevant information to shareholders and stakeholders", "id": "acfab-rv19-0aa16-31bb14"}, {"t": "pt", "text": "Integrity: high moral character - sticking to principles whatever the pressure", "id": "acfab-rv19-0aa16-d14ba8"}, {"t": "def", "k": 1, "term": "Fiduciary responsibility", "text": "Managers must act in the interests of those the organisation serves (usually shareholders), not their own - they can fail this duty without being corrupt (eg a takeover bid pursued for personal prestige)", "id": "acfab-rv19-0aa16-b14069"}, {"t": "exam", "text": "ACCA article flagged: 'A question of ethics'", "id": "acfab-rv19-0aa16-85a85a"}], "id": "acfab-rv19-0aa16"}, {"kind": "compare", "title": "Ethical theories", "page": [481, 484], "items": [{"t": "table", "rows": [["Approach", "Basis", "Key point"], ["Consequences - utilitarianism", "Outcomes", "The greatest good for the greatest number"], ["Egoism", "Self-interest", "An act is right if it serves the decision maker's own desires; criticised as short-term and selfish"], ["Pluralism", "Consensus", "Different views exist but agreement can be reached on some issues"], ["Duty - deontology", "Rules and duties", "Some acts are right or wrong regardless of consequences"], ["Relativism", "Context", "Many acceptable ethical beliefs exist, varying by society and time"], ["Absolutism", "Universal principles", "An unchanging set of principles applies in all situations"]], "id": "acfab-rv19-9307a-2c102e"}, {"t": "pt", "text": "Rights and virtues: natural rights should not be abused; virtues (eg honesty, courage) should be cultivated", "id": "acfab-rv19-9307a-2b500b"}, {"t": "pt", "text": "Managers face a tension between the duty to aim for profit and modern ethical standards", "id": "acfab-rv19-9307a-99575e"}], "id": "acfab-rv19-9307a"}, {"kind": "concept", "title": "Ethics in organisations", "page": [484, 488], "items": [{"t": "pt", "text": "Social responsibility, environmental duties and voluntary social/ethical objectives (eg fair trade, community projects)", "id": "acfab-rv19-7862a-c20ef1"}, {"t": "def", "k": 1, "term": "Corporate code of ethics", "text": "A published statement communicating the organisation's values to stakeholders and guiding employee behaviour", "id": "acfab-rv19-7862a-2d04b6"}, {"t": "pt", "text": "Code contents: values, conduct towards customers, suppliers, employees and the community, gifts, conflicts of interest, reporting concerns", "id": "acfab-rv19-7862a-fc71e6"}, {"t": "pt", "k": 1, "text": "Nolan's Seven Principles of Public Life: selflessness • integrity • objectivity • accountability • openness • honesty • leadership", "id": "acfab-rv19-7862a-82c72a"}, {"t": "exam", "text": "Candidates often perform poorly on corporate codes of ethics - know what a typical code contains", "id": "acfab-rv19-7862a-65f318"}, {"t": "pt", "k": 1, "text": "Compliance-based approach: act within the letter of the law, prevent and punish violations - bureaucratic control", "id": "acfab-rv19-7862a-b1af88"}, {"t": "pt", "k": 1, "text": "Integrity-based approach: combines the law with managerial responsibility for ethical behaviour - values and culture", "id": "acfab-rv19-7862a-78bcdc"}, {"t": "pt", "text": "Leadership and culture shape the ethical climate of the organisation", "id": "acfab-rv19-7862a-9325b5"}], "id": "acfab-rv19-7862a"}, {"kind": "rule", "title": "ACCA Code: fundamental principles", "page": [489, 491], "items": [{"t": "pt", "k": 1, "text": "Integrity: straightforward and honest in all professional and business relationships", "id": "acfab-rv19-8e40c-9c885b"}, {"t": "pt", "k": 1, "text": "Objectivity: no bias, conflict of interest or undue influence", "id": "acfab-rv19-8e40c-267ede"}, {"t": "pt", "k": 1, "text": "Professional competence and due care: maintain knowledge and skill; act diligently", "id": "acfab-rv19-8e40c-99e9ec"}, {"t": "pt", "k": 1, "text": "Confidentiality: do not disclose without proper authority unless there is a legal or professional right or duty; do not use for personal advantage", "id": "acfab-rv19-8e40c-8fc4f2"}, {"t": "pt", "k": 1, "text": "Professional behaviour: comply with laws and regulations; avoid actions that discredit the profession", "id": "acfab-rv19-8e40c-317d65"}, {"t": "pt", "text": "IFAC (International Federation of Accountants) sets the international code; ACCA members agree to be bound by the ACCA Code of Ethics and Conduct", "id": "acfab-rv19-8e40c-d7c0e4"}, {"t": "pt", "text": "Professional qualities: independence, scepticism, accountability, social responsibility", "id": "acfab-rv19-8e40c-c92f0e"}, {"t": "pt", "text": "Conflicts of interest must be identified and managed (or the engagement declined)", "id": "acfab-rv19-8e40c-adb154"}], "id": "acfab-rv19-8e40c"}, {"kind": "compare", "title": "Threats to independence", "page": [491, 499], "items": [{"t": "table", "rows": [["Threat", "Arises when", "Examples"], ["Self-interest", "Financial or other interest in the client", "Shares in the client, close business relationships, loans, overdue fees, contingent fees, high % of fees, lowballing, gifts and hospitality"], ["Self-review", "Reviewing your own work", "Preparing the accounts you audit, valuations, recent employment with the client, some corporate finance"], ["Advocacy", "Promoting the client's position", "Legal services, acting for the client in disputes, contingent fees"], ["Familiarity", "Too close and sympathetic", "Long association of senior staff, family relationships"], ["Intimidation", "Pressure from the client", "Threatened litigation, threats to change auditor, second opinions"]], "id": "acfab-rv19-d4041-bba9a8"}, {"t": "pt", "k": 1, "text": "Gifts and hospitality must be declined unless clearly insignificant", "id": "acfab-rv19-d4041-6c91d4"}, {"t": "pt", "text": "A partner or employee of an audit firm should not serve on the board of an assurance client", "id": "acfab-rv19-d4041-724a78"}, {"t": "pt", "text": "Taxation services are generally not seen to impair independence", "id": "acfab-rv19-d4041-a9c947"}, {"t": "pt", "k": 1, "text": "Safeguards include rotation of senior staff, independent review, declining the service or the engagement", "id": "acfab-rv19-d4041-205f84"}], "id": "acfab-rv19-d4041"}, {"kind": "concept", "title": "Ethics in business and dilemmas", "page": [499, 500], "items": [{"t": "def", "k": 1, "term": "Ethics in business", "text": "The application of ethical values to business behaviour", "id": "acfab-rv19-68664-4c8748"}, {"t": "pt", "text": "There is a public expectation of trust - especially of professionals", "id": "acfab-rv19-68664-38a12d"}, {"t": "pt", "text": "Corporate responsibility policies and reports make ethical strategy visible to outsiders", "id": "acfab-rv19-68664-533c55"}, {"t": "def", "k": 1, "term": "Ethical dilemma", "text": "A situation where two ethical values or requirements seem to be incompatible", "id": "acfab-rv19-68664-9b52ea"}, {"t": "pt", "text": "Resolving a dilemma: gather the facts, identify the ethical issues and principles affected, consider alternatives, consult internal procedures and the professional body, then act and document", "id": "acfab-rv19-68664-093304"}], "id": "acfab-rv19-68664"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Listing 'independence' as one of the five fundamental principles - the five are integrity, objectivity, competence and due care, confidentiality, professional behaviour", "id": "acfab-rv19-6483a-308a99"}, {"t": "x", "text": "Classifying preparing a client's accounts as a familiarity threat - it is a self-review threat", "id": "acfab-rv19-6483a-518433"}, {"t": "x", "text": "Confusing advocacy (promoting the client) with intimidation (pressure from the client)", "id": "acfab-rv19-6483a-ebaf3d"}, {"t": "x", "text": "Thinking confidentiality can never be broken - legal or professional duty may require disclosure", "id": "acfab-rv19-6483a-fe8576"}], "id": "acfab-rv19-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Governance concepts include fairness, transparency, probity, accountability, integrity", "id": "acfab-rv19-80e78-0df2f5"}, {"t": "pt", "text": "Fiduciary duty: act for those you serve, not yourself", "id": "acfab-rv19-80e78-205004"}, {"t": "pt", "text": "Utilitarianism = greatest good for the greatest number", "id": "acfab-rv19-80e78-3f3904"}, {"t": "pt", "text": "Deontology = duty-based ethics", "id": "acfab-rv19-80e78-3b0be2"}, {"t": "pt", "text": "Relativism vs absolutism", "id": "acfab-rv19-80e78-92740c"}, {"t": "pt", "text": "Nolan: selflessness, integrity, objectivity, accountability, openness, honesty, leadership", "id": "acfab-rv19-80e78-1cd6d0"}, {"t": "pt", "text": "Compliance-based vs integrity-based ethics management", "id": "acfab-rv19-80e78-d770ac"}, {"t": "pt", "text": "ACCA principles: integrity, objectivity, competence and due care, confidentiality, professional behaviour", "id": "acfab-rv19-80e78-7796bb"}, {"t": "pt", "text": "Threats: self-interest, self-review, advocacy, familiarity, intimidation", "id": "acfab-rv19-80e78-e35611"}, {"t": "pt", "text": "Overdue and contingent fees = self-interest", "id": "acfab-rv19-80e78-0f44a4"}, {"t": "pt", "text": "Long association = familiarity", "id": "acfab-rv19-80e78-c74b26"}, {"t": "pt", "text": "Litigation threats = intimidation", "id": "acfab-rv19-80e78-7aceb5"}, {"t": "pt", "text": "Ethical dilemma = two values in conflict", "id": "acfab-rv19-80e78-ade6a8"}], "id": "acfab-rv19-80e78"}], "source": "BPP Workbook ch 19: sections 1-8 pp477-500", "summary": "Rules and governance concepts, fiduciary duty, ethical theories, ethics in organisations and codes, the ACCA/IFAC fundamental principles, threats to independence and ethical dilemmas.", "id": "acfab-rv19", "updated": "2026-11-12"}], "plannedChapters": 19}, {"id": "acfbe", "code": "F2", "name": "Management Accounting", "level": "Applied Knowledge", "book": "ACCA-BE.pdf | BPP ACCA Workbook (Management Accounting) | offset 10", "updated": "2026-11-12", "note": "The file in the portal is named ACCA-BE.pdf but its cover and contents are the BPP F2 Management Accounting workbook; chapter numbers follow that book (1, 2a, 2b ... 17).", "chapters": [{"num": "1", "title": "Accounting for Management", "pages": [3, 18], "syllabus": "A1", "status": "published", "branches": [{"kind": "concept", "title": "Data and information", "page": [4, 7], "items": [{"t": "def", "k": 1, "term": "Data", "text": "The raw material for data processing - facts, events and transactions", "id": "acfbe-rv1-3c1cc-589d85"}, {"t": "def", "k": 1, "term": "Information", "text": "Data that has been processed in such a way as to be meaningful to the person who receives it", "id": "acfbe-rv1-3c1cc-cdb141"}, {"t": "pt", "k": 1, "text": "Good information: relevant, complete, accurate, clear, inspires confidence, appropriately communicated, manageable volume, timely, cost less than its benefits", "id": "acfbe-rv1-3c1cc-8498d2"}, {"t": "pt", "text": "Information needed: financial, non-financial, or a combination", "id": "acfbe-rv1-3c1cc-fed55c"}, {"t": "eg", "text": "Providing a staff canteen: financial (costs, subsidy) and non-financial (staff morale, time saved) information both matter", "id": "acfbe-rv1-3c1cc-811555"}, {"t": "exam", "text": "An introductory chapter, but highly examinable - expect questions on every study session", "id": "acfbe-rv1-3c1cc-d27d58"}], "id": "acfbe-rv1-3c1cc"}, {"kind": "concept", "title": "Planning, control and decision making", "page": [7, 11], "items": [{"t": "pt", "k": 1, "text": "Management information is used for planning, control and decision making", "id": "acfbe-rv1-70761-87b989"}, {"t": "def", "term": "Objective", "text": "The aim or goal of an organisation (or individual)", "id": "acfbe-rv1-70761-73e908"}, {"t": "def", "term": "Strategy", "text": "A possible course of action that might enable an organisation to achieve its objectives", "id": "acfbe-rv1-70761-0e9789"}, {"t": "pt", "text": "Long-term strategic (corporate) planning sets the framework; short-term tactical plans make it operational", "id": "acfbe-rv1-70761-095a44"}, {"t": "pt", "text": "Control: compare actual results with the plan and take corrective action", "id": "acfbe-rv1-70761-1e4ec8"}, {"t": "pt", "text": "Decision making always involves a choice between alternatives", "id": "acfbe-rv1-70761-42d77c"}, {"t": "pt", "text": "Structure follows strategy (and some argue strategy follows structure)", "id": "acfbe-rv1-70761-af6b14"}], "id": "acfbe-rv1-70761"}, {"kind": "compare", "title": "Anthony's hierarchy", "page": [10, 12], "items": [{"t": "table", "rows": [["Level", "Who", "Concerned with", "Information"], ["Strategic planning", "Senior management", "Setting or changing objectives and strategic targets", "Strategic - long-term, external, summarised, often non-financial"], ["Management (tactical) control", "Middle management", "Using resources efficiently to meet objectives", "Tactical - short to medium term, internal, eg productivity, budget vs actual"], ["Operational control", "Front-line managers (foremen, head clerks)", "Ensuring specific tasks are carried out effectively", "Operational - very detailed, frequent, immediate"]], "id": "acfbe-rv1-b4650-8151e4"}, {"t": "def", "k": 1, "term": "Management control system", "text": "A system which measures and corrects the performance of subordinates so that the organisation's objectives are met and plans carried out", "id": "acfbe-rv1-b4650-d4b5d6"}], "id": "acfbe-rv1-b4650"}, {"kind": "compare", "title": "Financial vs management vs cost accounting", "page": [13, 15], "items": [{"t": "table", "rows": [["Feature", "Financial accounts", "Management accounts"], ["Users", "Shareholders and external parties", "Managers within the organisation"], ["Legal requirement", "Required by law (limited companies)", "Not required"], ["Format", "Set by law and standards", "Whatever is useful"], ["Time frame", "Historic, a defined period", "Historic and future (budgets, forecasts)"], ["Scope", "The business as a whole", "Products, departments, activities"], ["Content", "Monetary", "Monetary and non-monetary"]], "id": "acfbe-rv1-59d8a-5a6c7a"}, {"t": "pt", "k": 1, "text": "Cost accounting is PART of management accounting - it provides a bank of data for the management accountant", "id": "acfbe-rv1-59d8a-56e15d"}, {"t": "pt", "text": "Aims of cost accounts: cost of goods/services, of departments, revenues, profitability, inventory valuation, future costs", "id": "acfbe-rv1-59d8a-5c8cfc"}, {"t": "pt", "k": 1, "text": "Cost accounting information is, in general, unsuitable for decision making - decision information must be relevant and future-based; absorption costing figures can mislead", "id": "acfbe-rv1-59d8a-6d359f"}, {"t": "pt", "text": "Decisions concern the future, so information should allow for uncertainty (competitors, inflation, interest rates, legislation, shortages, disputes)", "id": "acfbe-rv1-59d8a-50333d"}], "id": "acfbe-rv1-59d8a"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Treating 'cost accounting' and 'management accounting' as the same - cost accounting is part of it", "id": "acfbe-rv1-6483a-fb6262"}, {"t": "x", "text": "Thinking management accounts are required by law", "id": "acfbe-rv1-6483a-63b386"}, {"t": "x", "text": "Placing productivity reports at the strategic level - they are tactical/operational", "id": "acfbe-rv1-6483a-c43b14"}, {"t": "x", "text": "Assuming absorption cost data is suitable for decisions - it may be misleading", "id": "acfbe-rv1-6483a-58a9b1"}], "id": "acfbe-rv1-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Data = raw facts; information = processed, meaningful data", "id": "acfbe-rv1-80e78-58167a"}, {"t": "pt", "text": "Good information: relevant, complete, accurate, clear, timely, worth its cost", "id": "acfbe-rv1-80e78-841d46"}, {"t": "pt", "text": "Uses: planning, control, decision making", "id": "acfbe-rv1-80e78-40c77c"}, {"t": "pt", "text": "Objective = goal; strategy = course of action to reach it", "id": "acfbe-rv1-80e78-7060a6"}, {"t": "pt", "text": "Anthony: strategic planning, management control, operational control", "id": "acfbe-rv1-80e78-3dabea"}, {"t": "pt", "text": "Strategic info is long-term and external; operational info is detailed and frequent", "id": "acfbe-rv1-80e78-dfad12"}, {"t": "pt", "text": "Management control system measures and corrects performance", "id": "acfbe-rv1-80e78-153f43"}, {"t": "pt", "text": "Financial accounts: external, legal, historic", "id": "acfbe-rv1-80e78-05c39a"}, {"t": "pt", "text": "Management accounts: internal, not legal, past and future", "id": "acfbe-rv1-80e78-8277cb"}, {"t": "pt", "text": "Cost accounting is part of management accounting", "id": "acfbe-rv1-80e78-aa384c"}, {"t": "pt", "text": "Cost accounting info is generally unsuitable for decisions", "id": "acfbe-rv1-80e78-8172b7"}, {"t": "pt", "text": "Decision information must allow for uncertainty", "id": "acfbe-rv1-80e78-72ebe2"}], "id": "acfbe-rv1-80e78"}], "source": "BPP Workbook ch 1: sections 1-4 pp4-15; chapter roundup p16", "summary": "Data vs information, qualities of good information, planning, control and decision making, Anthony's hierarchy, and how financial, cost and management accounting differ.", "id": "acfbe-rv1", "updated": "2026-11-12"}, {"num": "2a", "title": "Sources of Data", "pages": [19, 40], "syllabus": "A2", "status": "published", "branches": [{"kind": "concept", "title": "Types of data", "page": [20, 21], "items": [{"t": "def", "k": 1, "term": "Primary data", "text": "Data collected specifically for the purpose of a survey", "id": "acfbe-rv2a-07318-834342"}, {"t": "def", "k": 1, "term": "Secondary data", "text": "Data collected for some other purpose", "id": "acfbe-rv2a-07318-66805c"}, {"t": "def", "k": 1, "term": "Discrete data", "text": "Can only take a countable number of values (eg goals scored: 0, 1, 2)", "id": "acfbe-rv2a-07318-99f1ab"}, {"t": "def", "k": 1, "term": "Continuous data", "text": "Can take any value (eg heights 1.542 m, 1.639 m)", "id": "acfbe-rv2a-07318-fdaf6d"}, {"t": "pt", "text": "Sample data come from investigating a selection of the population; population data from the whole population", "id": "acfbe-rv2a-07318-c30b3d"}, {"t": "pt", "text": "Quantitative (measurable) vs qualitative (attributes)", "id": "acfbe-rv2a-07318-83b5b9"}], "id": "acfbe-rv2a-07318"}, {"kind": "concept", "title": "Sources of data", "page": [21, 25], "items": [{"t": "pt", "text": "Internal sources: accounting records (ledgers, cash book), other records tied to the accounting system (payroll, production, sales), staff and managers", "id": "acfbe-rv2a-fd2c0-e3fc52"}, {"t": "pt", "text": "External sources: suppliers, customers, competitors, official bodies, the internet", "id": "acfbe-rv2a-fd2c0-da4f3b"}, {"t": "pt", "k": 1, "text": "Main secondary sources: governments (eg ONS), banks (eg Bank of England), financial newspapers, trade journals, information bureaux, consultancies, libraries and information services, the internet", "id": "acfbe-rv2a-fd2c0-deb12c"}, {"t": "pt", "text": "The economic environment affects firms through activity levels, exchange rates, interest rates and inflation", "id": "acfbe-rv2a-fd2c0-963d95"}], "id": "acfbe-rv2a-fd2c0"}, {"kind": "concept", "title": "Big Data", "page": [26, 27], "items": [{"t": "def", "k": 1, "term": "Big Data", "text": "The mass of data society creates each year, far beyond traditional financial and enterprise data - collected and analysed to find trends, understand customers and focus resources", "id": "acfbe-rv2a-44d6c-10e893"}, {"t": "pt", "k": 1, "text": "Three Vs: volume (scale) • velocity (speed of creation and processing) • variety (many formats - text, video, sensor data)", "id": "acfbe-rv2a-44d6c-e4d1b4"}, {"t": "pt", "text": "Uses: business value, understanding the customer, supporting corporate strategy", "id": "acfbe-rv2a-44d6c-152e1c"}, {"t": "pt", "text": "Effects on decisions: faster decisions, better targeting, real-time analysis", "id": "acfbe-rv2a-44d6c-7a47fa"}, {"t": "pt", "text": "Criticisms: correlation is not causation; sampling bias; overconfidence in large datasets", "id": "acfbe-rv2a-44d6c-92943b"}], "id": "acfbe-rv2a-44d6c"}, {"kind": "compare", "title": "Sampling methods", "page": [28, 34], "items": [{"t": "table", "rows": [["Method", "Type", "How it works", "Key point"], ["Simple random", "Probability", "Every item has an equal chance", "Needs a sampling frame (numbered list of the population)"], ["Stratified random", "Probability", "Population split into strata; random sample from each in proportion", "Representative of each group"], ["Systematic", "Probability", "Every nth item after a random start", "Simple; biased if the list has a pattern"], ["Multistage", "Probability", "Divide into sub-populations, select some, then sample within them", "Practical for national surveys"], ["Cluster", "Selected subsection", "One definable subsection (cluster) is chosen and all of it surveyed", "Cheap; may be unrepresentative"], ["Quota", "Non-probability", "Investigators interview a set number from each group", "Cheap and simple; randomness forfeited, interviewer bias"]], "id": "acfbe-rv2a-30561-b05afe"}, {"t": "def", "k": 1, "term": "Census", "text": "A survey that examines the whole population", "id": "acfbe-rv2a-30561-da2821"}, {"t": "def", "k": 1, "term": "Probability sampling method", "text": "Each member of the population has a KNOWN chance of appearing in the sample", "id": "acfbe-rv2a-30561-6ae05d"}, {"t": "def", "k": 1, "term": "Non-probability sampling method", "text": "The chance of each member appearing in the sample is not known (eg quota sampling)", "id": "acfbe-rv2a-30561-ef69eb"}, {"t": "def", "k": 1, "term": "Sampling frame", "text": "A numbered list of all items in a population", "id": "acfbe-rv2a-30561-ddf410"}, {"t": "pt", "text": "Drawbacks of random sampling: full range of variation, may be unrepresentative, needs a frame, items may be widely spread", "id": "acfbe-rv2a-30561-ec7b69"}, {"t": "eg", "text": "Stratified: if 500 of 2,000 accountants work in partnerships, a 100-person sample takes 25 from partnerships", "id": "acfbe-rv2a-30561-3f9b44"}, {"t": "eg", "text": "Multistage: 8 regions x 5 towns x 200 people = 8,000 people sampled", "id": "acfbe-rv2a-30561-c88469"}, {"t": "exam", "text": "Know how each method works so you can choose the appropriate method in a given situation", "id": "acfbe-rv2a-30561-1009e9"}], "id": "acfbe-rv2a-30561"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calling secondary data 'second-hand primary data' - it was collected for a different purpose", "id": "acfbe-rv2a-6483a-180ae0"}, {"t": "x", "text": "Saying quota sampling is a probability method - it is non-probability", "id": "acfbe-rv2a-6483a-fe0fb3"}, {"t": "x", "text": "Forgetting that random sampling needs a sampling frame", "id": "acfbe-rv2a-6483a-f82246"}, {"t": "x", "text": "Classifying 'number of employees' as continuous - it is discrete", "id": "acfbe-rv2a-6483a-08956f"}, {"t": "x", "text": "Assuming poor data can be fixed by careful presentation - it cannot", "id": "acfbe-rv2a-6483a-f041b8"}], "id": "acfbe-rv2a-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Primary data: collected for this purpose; secondary: for another purpose", "id": "acfbe-rv2a-80e78-89de9c"}, {"t": "pt", "text": "Discrete = countable values; continuous = any value", "id": "acfbe-rv2a-80e78-994a77"}, {"t": "pt", "text": "Internal sources: accounting and related records", "id": "acfbe-rv2a-80e78-119e00"}, {"t": "pt", "text": "Secondary sources: government, banks, newspapers, journals, bureaux, consultancies, internet", "id": "acfbe-rv2a-80e78-d616a3"}, {"t": "pt", "text": "Big Data three Vs: volume, velocity, variety", "id": "acfbe-rv2a-80e78-642833"}, {"t": "pt", "text": "Census = whole population", "id": "acfbe-rv2a-80e78-06f5eb"}, {"t": "pt", "text": "Probability sampling: known chance of selection", "id": "acfbe-rv2a-80e78-3a0e7c"}, {"t": "pt", "text": "Random, stratified, systematic, multistage = probability methods", "id": "acfbe-rv2a-80e78-a91546"}, {"t": "pt", "text": "Quota = non-probability, cheap", "id": "acfbe-rv2a-80e78-e31e67"}, {"t": "pt", "text": "Sampling frame = numbered list of the population", "id": "acfbe-rv2a-80e78-2442a2"}, {"t": "pt", "text": "Systematic = every nth item after a random start", "id": "acfbe-rv2a-80e78-721d48"}, {"t": "pt", "text": "Stratified = random within proportional groups", "id": "acfbe-rv2a-80e78-0c9c3f"}], "id": "acfbe-rv2a-80e78"}], "source": "BPP Workbook ch 2a: sections 1-6 pp20-34; chapter roundup p36", "summary": "Types of data, internal and external sources, secondary data, Big Data and its three Vs, and probability and non-probability sampling methods.", "id": "acfbe-rv2a", "updated": "2026-11-12"}, {"num": "2b", "title": "Presenting Information", "pages": [41, 62], "syllabus": "A3", "status": "published", "branches": [{"kind": "concept", "title": "Written reports", "page": [42, 47], "items": [{"t": "pt", "k": 1, "text": "The purpose of a report must be clear; reports usually initiate a decision or action", "id": "acfbe-rv2b-23277-9693e9"}, {"t": "pt", "text": "Report types by purpose: control, planning, decision; routine vs special 'one-off'", "id": "acfbe-rv2b-23277-d30ebf"}, {"t": "pt", "text": "Planning questions: who is the user, what type of report, what is its purpose, what information is needed, when is it needed", "id": "acfbe-rv2b-23277-661d03"}, {"t": "pt", "k": 1, "text": "Stylistic qualities: objectivity and balance, ease of understanding", "id": "acfbe-rv2b-23277-5c754f"}, {"t": "pt", "k": 1, "text": "Put detailed explanations, charts and tables in APPENDICES, cross-referenced from the short main body", "id": "acfbe-rv2b-23277-c0680b"}, {"t": "pt", "text": "Formats: short formal report (middle to senior management), short informal report (lower-level info), memorandum report (A4 memo format)", "id": "acfbe-rv2b-23277-19a914"}, {"t": "pt", "text": "A report produced too late is of no use - timeliness", "id": "acfbe-rv2b-23277-d73a1d"}], "id": "acfbe-rv2b-23277"}, {"kind": "concept", "title": "Tables", "page": [47, 48], "items": [{"t": "pt", "k": 1, "text": "Tables present information about TWO variables (a matrix of rows and columns)", "id": "acfbe-rv2b-9ab2e-adae7e"}, {"t": "pt", "text": "Guidelines: clear title, labelled rows and columns, totals, units stated, source given, secondary statistics (eg percentages) to support the main figures", "id": "acfbe-rv2b-9ab2e-7f43c4"}, {"t": "pt", "text": "Spreadsheets are the basic tool for recording and manipulating management information", "id": "acfbe-rv2b-9ab2e-686621"}], "id": "acfbe-rv2b-9ab2e"}, {"kind": "compare", "title": "Charts", "page": [49, 55], "items": [{"t": "table", "rows": [["Chart", "Shows", "Note"], ["Simple bar chart", "Magnitude of each item by bar length", "One bar per item"], ["Component bar chart", "Breakdown of each total into components", "Bar length = total"], ["Percentage component bar chart", "Components as % of each total", "All bars the same length (100%)"], ["Multiple (compound) bar chart", "Two or more bars side by side for each category", "Compares components directly"], ["Pie chart", "Relative size of components of a total", "Total = 360 degrees = 100%"]], "id": "acfbe-rv2b-cc188-9bb02d"}, {"t": "pt", "k": 1, "text": "Three main types of bar chart: simple, component (including percentage component) and multiple (compound)", "id": "acfbe-rv2b-cc188-c8b245"}, {"t": "f", "term": "Pie chart segment angle", "text": "Component % x 3.6 (= component / total x 360°)", "vars": "360° represents 100%", "eg": "A 25% share = 90°", "id": "acfbe-rv2b-cc188-847162"}, {"t": "pt", "text": "Pie chart advantages: simple picture of relative sizes; disadvantages: no absolute values, hard to compare small segments or two pies", "id": "acfbe-rv2b-cc188-a9566e"}, {"t": "exam", "text": "A CBE cannot ask you to draw a chart - expect labelling, calculating values, choosing an appropriate chart and drawing conclusions", "id": "acfbe-rv2b-cc188-40c589"}], "id": "acfbe-rv2b-cc188"}, {"kind": "formula", "title": "Scatter diagrams and trend lines", "page": [56, 59], "items": [{"t": "pt", "k": 1, "text": "Scatter diagrams exhibit data to compare how two variables vary with each other", "id": "acfbe-rv2b-75bdb-31c3be"}, {"t": "x", "k": 1, "text": "axis = independent variable; y axis = dependent variable", "id": "acfbe-rv2b-75bdb-edde6f"}, {"t": "pt", "text": "Trend line (line of best fit) drawn by eye through the points, then used for prediction", "id": "acfbe-rv2b-75bdb-a0b015"}, {"t": "f", "k": 1, "term": "Straight line", "text": "y = a + bx", "vars": "a = intercept on the y axis (fixed cost); b = gradient (variable cost per unit); x = activity; y = total cost", "eg": "Line through (0, 20) with slope 0.9: y = 20 + 0.9x", "id": "acfbe-rv2b-75bdb-be55b1"}, {"t": "pt", "text": "The intercept where the line of best fit meets the vertical axis estimates monthly fixed costs (cost at zero output)", "id": "acfbe-rv2b-75bdb-3627f1"}, {"t": "eg", "text": "Line of best fit gives cost of 12,000 widgets as $70,000 and fixed costs of $10,000 a month", "id": "acfbe-rv2b-75bdb-ca132a"}], "id": "acfbe-rv2b-75bdb"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Putting the dependent variable on the x axis", "id": "acfbe-rv2b-6483a-8aade4"}, {"t": "x", "text": "Expecting percentage component bars to differ in length - they are all 100%", "id": "acfbe-rv2b-6483a-cb2fbd"}, {"t": "x", "text": "Filling the main body of a report with detailed tables instead of using appendices", "id": "acfbe-rv2b-6483a-962ca9"}, {"t": "x", "text": "Reading the gradient b as fixed cost - a is the fixed element, b the variable cost per unit", "id": "acfbe-rv2b-6483a-491315"}], "id": "acfbe-rv2b-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Reports initiate decisions or actions", "id": "acfbe-rv2b-80e78-fb5947"}, {"t": "pt", "text": "Report style: objective, balanced, easy to understand", "id": "acfbe-rv2b-80e78-ba5f70"}, {"t": "pt", "text": "Detail goes in appendices", "id": "acfbe-rv2b-80e78-aae50a"}, {"t": "pt", "text": "Formats: short formal, short informal, memorandum", "id": "acfbe-rv2b-80e78-a2b311"}, {"t": "pt", "text": "Tables show two variables", "id": "acfbe-rv2b-80e78-f23444"}, {"t": "pt", "text": "Bar charts: simple, component, percentage component, multiple", "id": "acfbe-rv2b-80e78-3da4c7"}, {"t": "pt", "text": "Pie chart: 360° = 100%; angle = % x 3.6", "id": "acfbe-rv2b-80e78-905daa"}, {"t": "pt", "text": "Pie charts show relative not absolute values", "id": "acfbe-rv2b-80e78-e68a31"}, {"t": "pt", "text": "Scatter: x independent, y dependent", "id": "acfbe-rv2b-80e78-8a1b6e"}, {"t": "pt", "text": "Trend line y = a + bx", "id": "acfbe-rv2b-80e78-f236bb"}, {"t": "pt", "text": "a = fixed cost (intercept); b = variable cost per unit (slope)", "id": "acfbe-rv2b-80e78-ed3b6a"}, {"t": "pt", "text": "CBE: no drawing - interpret, label, calculate, choose", "id": "acfbe-rv2b-80e78-31b78d"}], "id": "acfbe-rv2b-80e78"}], "source": "BPP Workbook ch 2b: sections 1-6 pp42-59; chapter roundup p60", "summary": "Reports and their formats, tables, bar charts, pie charts, scatter diagrams and trend lines (y = a + bx).", "id": "acfbe-rv2b", "updated": "2026-11-12"}, {"num": "3a", "title": "Cost Classification", "pages": [63, 80], "syllabus": "A4", "status": "published", "branches": [{"kind": "concept", "title": "Direct and indirect costs", "page": [64, 67], "items": [{"t": "def", "k": 1, "term": "Direct cost", "text": "A cost that can be traced in full to the product, service or department being costed", "id": "acfbe-rv3a-63ae9-261f5b"}, {"t": "def", "k": 1, "term": "Indirect cost (overhead)", "text": "A cost incurred in making a product, providing a service or running a department that cannot be traced directly and in full to it", "id": "acfbe-rv3a-63ae9-224d2f"}, {"t": "pt", "text": "Total cost = direct materials + direct labour + direct expenses (= PRIME COST) + overheads", "id": "acfbe-rv3a-63ae9-6f2f98"}, {"t": "pt", "text": "Direct material: all material becoming part of the product (unless negligible in amount/cost) - eg components, primary packing", "id": "acfbe-rv3a-63ae9-ac82af"}, {"t": "pt", "text": "Direct labour: wages for work on the product itself (basic hours or overtime) - eg assembly workers", "id": "acfbe-rv3a-63ae9-54ce26"}, {"t": "pt", "text": "Direct expenses: other expenses incurred on a specific product (eg hire of a special tool, sub-contract work, royalties)", "id": "acfbe-rv3a-63ae9-f39f98"}, {"t": "pt", "k": 1, "text": "Production overhead: indirect materials, wages and expenses in the factory (eg supervisors, factory rent, machine maintenance)", "id": "acfbe-rv3a-63ae9-da353f"}, {"t": "pt", "text": "Administration overhead: direction, control and administration (eg office depreciation)", "id": "acfbe-rv3a-63ae9-373934"}, {"t": "pt", "text": "Selling overhead: promoting sales and retaining customers (eg catalogues, sales staff)", "id": "acfbe-rv3a-63ae9-6e42b3"}, {"t": "pt", "text": "Distribution overhead: making the packed product ready for despatch and delivering it (eg packers, drivers)", "id": "acfbe-rv3a-63ae9-ba30e0"}, {"t": "exam", "text": "Overtime PREMIUM and idle time are usually production OVERHEAD, not direct labour - unless overtime is worked at a customer's specific request", "id": "acfbe-rv3a-63ae9-7ac923"}, {"t": "exam", "text": "Cost classification is a key syllabus area - expect it in the exam", "id": "acfbe-rv3a-63ae9-1012a6"}], "id": "acfbe-rv3a-63ae9"}, {"kind": "compare", "title": "Ways to classify cost", "page": [68, 71], "items": [{"t": "table", "rows": [["Basis", "Categories", "Used for"], ["Traceability", "Direct / indirect", "Building up product cost"], ["Function", "Production, administration, selling and distribution", "Full cost of sales, statement of profit or loss"], ["Behaviour", "Fixed / variable / semi-variable / step", "Planning, budgeting, decisions"], ["Financial statements", "Production / non-production", "Inventory valuation"]], "id": "acfbe-rv3a-71a2c-d96fdc"}, {"t": "pt", "k": 1, "text": "Production costs are identified with goods produced or purchased for resale (included in inventory); non-production costs are expensed in the current period", "id": "acfbe-rv3a-71a2c-ef78df"}, {"t": "eg", "text": "Costs: materials 600, labour 1,000, production overhead 500, admin 700 -> production cost 2,100 goes to inventory/cost of sales; 700 is a period expense", "id": "acfbe-rv3a-71a2c-3fe79e"}, {"t": "exam", "text": "The exam uses 'statement of profit or loss' (not 'income statement')", "id": "acfbe-rv3a-71a2c-d6521f"}], "id": "acfbe-rv3a-71a2c"}, {"kind": "concept", "title": "Cost codes", "page": [71, 74], "items": [{"t": "pt", "k": 1, "text": "A coding system makes cost data easier to manage in manual and computerised systems", "id": "acfbe-rv3a-7b70a-7b8e6a"}, {"t": "pt", "text": "Good code: unique, brief, comprehensive, elastic (room for new items), uniform length, unambiguous, centrally controlled", "id": "acfbe-rv3a-7b70a-4b0d6a"}, {"t": "pt", "text": "Composite code: digits represent different classifications (eg first three digits = cost centre, next digits = type of expenditure)", "id": "acfbe-rv3a-7b70a-7813ad"}, {"t": "pt", "text": "Other codes: sequence (progressive), block, significant digit, hierarchical, faceted, mnemonic", "id": "acfbe-rv3a-7b70a-157472"}, {"t": "pt", "text": "Advantages: briefer than descriptions, less ambiguity, easier analysis and computer processing", "id": "acfbe-rv3a-7b70a-0ad3dd"}], "id": "acfbe-rv3a-7b70a"}, {"kind": "compare", "title": "Centres and units", "page": [74, 77], "items": [{"t": "table", "rows": [["Term", "Accountable for", "Example measure"], ["Cost centre", "Costs only - collecting place for costs", "Costs vs budget"], ["Revenue centre", "Revenues only", "Sales vs target"], ["Profit centre", "Costs AND revenues", "Profit"], ["Investment centre", "Costs, revenues AND capital investment (possibly financing)", "Return on investment"]], "id": "acfbe-rv3a-b16d7-7b9bce"}, {"t": "def", "k": 1, "term": "Cost unit", "text": "A unit of product or service to which costs can be related - the basic control unit for costing (eg a room night, a patient day, a batch)", "id": "acfbe-rv3a-b16d7-a7ac0a"}, {"t": "def", "k": 1, "term": "Cost object", "text": "Any activity for which a separate measurement of costs is desired", "id": "acfbe-rv3a-b16d7-0a0b4f"}, {"t": "def", "k": 1, "term": "Responsibility centre", "text": "A department or function whose performance is the direct responsibility of a specific manager", "id": "acfbe-rv3a-b16d7-b06c79"}, {"t": "pt", "text": "Costs are traced to cost centres first, then analysed into cost units", "id": "acfbe-rv3a-b16d7-4b12c5"}, {"t": "exam", "text": "A defining feature of an investment centre: managers can purchase capital assets", "id": "acfbe-rv3a-b16d7-5143db"}], "id": "acfbe-rv3a-b16d7"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Treating overtime premium as direct labour by default - it is normally an overhead", "id": "acfbe-rv3a-6483a-44d953"}, {"t": "x", "text": "Including administration or selling costs in inventory valuation - only production costs", "id": "acfbe-rv3a-6483a-3a674a"}, {"t": "x", "text": "Confusing a cost unit (output) with a cost centre (location/function)", "id": "acfbe-rv3a-6483a-a45333"}, {"t": "x", "text": "Calling a profit centre an investment centre - only the investment centre controls capital", "id": "acfbe-rv3a-6483a-8554fd"}], "id": "acfbe-rv3a-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Direct cost: traced in full; indirect cost: cannot be traced in full", "id": "acfbe-rv3a-80e78-9f35d5"}, {"t": "pt", "text": "Prime cost = direct materials + direct labour + direct expenses", "id": "acfbe-rv3a-80e78-1b7635"}, {"t": "pt", "text": "Overheads: production, administration, selling, distribution", "id": "acfbe-rv3a-80e78-dc90b6"}, {"t": "pt", "text": "Overtime premium and idle time are usually overhead", "id": "acfbe-rv3a-80e78-c726f9"}, {"t": "pt", "text": "Classify by traceability, function, behaviour, production/non-production", "id": "acfbe-rv3a-80e78-1731a9"}, {"t": "pt", "text": "Production costs valued in inventory; non-production costs expensed", "id": "acfbe-rv3a-80e78-98b729"}, {"t": "pt", "text": "Good code: unique, brief, elastic, unambiguous", "id": "acfbe-rv3a-80e78-1fb234"}, {"t": "pt", "text": "Cost centre = collecting place for costs", "id": "acfbe-rv3a-80e78-790e94"}, {"t": "pt", "text": "Cost unit = unit of output to which costs relate", "id": "acfbe-rv3a-80e78-a3ef66"}, {"t": "pt", "text": "Revenue centre: revenue only", "id": "acfbe-rv3a-80e78-997eec"}, {"t": "pt", "text": "Profit centre: costs and revenues", "id": "acfbe-rv3a-80e78-e4dfeb"}, {"t": "pt", "text": "Investment centre: plus capital investment, measured by ROI", "id": "acfbe-rv3a-80e78-c65d8d"}, {"t": "pt", "text": "Responsibility centre = performance owned by a specific manager", "id": "acfbe-rv3a-80e78-b657d8"}], "id": "acfbe-rv3a-80e78"}], "source": "BPP Workbook ch 3a: sections 1-7 pp64-77; chapter roundup p78", "summary": "Direct and indirect costs, functional costs, fixed and variable costs, production and non-production costs, cost codes, and cost/profit/revenue/investment and responsibility centres.", "id": "acfbe-rv3a", "updated": "2026-11-12"}, {"num": "3b", "title": "Cost Behaviour", "pages": [81, 102], "syllabus": "A4", "status": "published", "branches": [{"kind": "concept", "title": "Cost behaviour patterns", "page": [82, 88], "items": [{"t": "def", "k": 1, "term": "Cost behaviour", "text": "The way in which costs are affected by changes in the volume of output", "id": "acfbe-rv3b-8b535-ec0b6e"}, {"t": "pt", "text": "Knowledge of cost behaviour is essential for budgeting, decision making and control", "id": "acfbe-rv3b-8b535-43d7f8"}, {"t": "def", "k": 1, "term": "Fixed cost", "text": "A cost unaffected by increases or decreases in the volume of output - a period charge (eg rent, salaries)", "id": "acfbe-rv3b-8b535-4c8284"}, {"t": "def", "k": 1, "term": "Step cost", "text": "A cost which is fixed in nature but only within certain levels of activity (eg a supervisor's salary until a second supervisor is needed)", "id": "acfbe-rv3b-8b535-8a1a81"}, {"t": "def", "k": 1, "term": "Variable cost", "text": "A cost which varies directly with output - the variable cost PER UNIT is constant", "id": "acfbe-rv3b-8b535-9d08ce"}, {"t": "pt", "text": "Curvilinear variable cost: relationship shown as a curve (eg bulk discounts, learning effects)", "id": "acfbe-rv3b-8b535-819b74"}, {"t": "def", "k": 1, "term": "Semi-variable (semi-fixed, mixed) cost", "text": "Contains both fixed and variable components (eg electricity standing charge + charge per unit; salary + commission; car road tax and insurance + petrol)", "id": "acfbe-rv3b-8b535-006308"}, {"t": "pt", "k": 1, "text": "Per unit: fixed cost per unit FALLS as output rises; variable cost per unit stays CONSTANT", "id": "acfbe-rv3b-8b535-c1a951"}, {"t": "pt", "text": "Assumption: within the relevant range of output, costs behave as fixed or linear variable", "id": "acfbe-rv3b-8b535-b91a3b"}, {"t": "exam", "text": "An exam question may give you a graph and ask you to interpret it", "id": "acfbe-rv3b-8b535-84a925"}], "id": "acfbe-rv3b-8b535"}, {"kind": "process", "title": "High-low method", "page": [89, 93], "items": [{"t": "pt", "text": "Purpose: split a semi-variable cost into its fixed and variable elements", "id": "acfbe-rv3b-b518e-56d395"}, {"t": "pt", "text": "Step 1: identify the periods with the HIGHEST and LOWEST ACTIVITY (not cost)", "id": "acfbe-rv3b-b518e-128806"}, {"t": "pt", "text": "Step 2: variable cost per unit = (cost at high activity - cost at low activity) / (high units - low units)", "id": "acfbe-rv3b-b518e-8d87a6"}, {"t": "pt", "text": "Step 3: fixed cost = total cost at high (or low) activity - (units x variable cost per unit)", "id": "acfbe-rv3b-b518e-211ca6"}, {"t": "f", "k": 1, "term": "High-low variable cost per unit", "text": "(Total cost at high activity - Total cost at low activity) / (High units - Low units)", "vars": "activity = units, hours etc", "eg": "DG Co: (170,000 - 140,000) / (90,000 - 60,000) = $1 per unit; fixed cost = 170,000 - 90,000 = $80,000", "id": "acfbe-rv3b-b518e-471caf"}, {"t": "pt", "text": "Stepped fixed costs: remove the step before calculating (eg deduct the extra $4,700 fixed cost first)", "id": "acfbe-rv3b-b518e-2018a0"}, {"t": "pt", "text": "Change in variable cost per unit (eg a wage rise): adjust one of the cost figures to the same price basis first", "id": "acfbe-rv3b-b518e-f7366c"}, {"t": "exam", "text": "Use the highest and lowest VOLUME, not the highest and lowest cost - a frequent trap", "id": "acfbe-rv3b-b518e-ca4552"}, {"t": "exam", "text": "The examining team says calculation questions such as high-low are often poorly attempted", "id": "acfbe-rv3b-b518e-7d55b5"}], "id": "acfbe-rv3b-b518e"}, {"kind": "formula", "title": "Linear equations", "page": [93, 96], "items": [{"t": "f", "k": 1, "term": "Linear equation", "text": "y = a + bx", "vars": "y = dependent variable; x = independent variable; a = constant (intercept, fixed cost); b = coefficient of x (gradient, variable cost per unit)", "eg": "Weekly wage $100 + $5 per item: y = 100 + 5x", "id": "acfbe-rv3b-8f580-7194b9"}, {"t": "f", "term": "Gradient (slope)", "text": "(y2 - y1) / (x2 - x1)", "vars": "(x1, y1), (x2, y2) are two points on the line", "eg": "y = 4x + 5 through (2,13) and (4,21): 8/2 = 4", "id": "acfbe-rv3b-8f580-af4db0"}, {"t": "pt", "text": "Intercept = a = value of y when x = 0, point (0, a)", "id": "acfbe-rv3b-8f580-bca16d"}, {"t": "pt", "text": "Positive gradient slopes upwards left to right; negative slopes downwards; larger b = steeper", "id": "acfbe-rv3b-8f580-056327"}, {"t": "pt", "text": "Rearrange to y = a + bx first: 4y = 16x - 12 gives y = -3 + 4x (intercept -3, slope 4)", "id": "acfbe-rv3b-8f580-5e2e8f"}], "id": "acfbe-rv3b-8f580"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Picking the highest and lowest COST in high-low instead of activity", "id": "acfbe-rv3b-6483a-d1299c"}, {"t": "x", "text": "Saying fixed cost per unit is constant - it falls as output rises", "id": "acfbe-rv3b-6483a-69927e"}, {"t": "x", "text": "Forgetting to remove a step in fixed costs before using high-low", "id": "acfbe-rv3b-6483a-91143a"}, {"t": "x", "text": "Reading the intercept from an equation not yet in the form y = a + bx", "id": "acfbe-rv3b-6483a-181e88"}], "id": "acfbe-rv3b-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Cost behaviour = how costs change with output", "id": "acfbe-rv3b-80e78-530506"}, {"t": "pt", "text": "Fixed: total constant, per unit falls", "id": "acfbe-rv3b-80e78-ee00b9"}, {"t": "pt", "text": "Variable: total rises, per unit constant", "id": "acfbe-rv3b-80e78-988580"}, {"t": "pt", "text": "Step cost: fixed within ranges of activity", "id": "acfbe-rv3b-80e78-37a87d"}, {"t": "pt", "text": "Semi-variable: fixed + variable parts", "id": "acfbe-rv3b-80e78-85ea77"}, {"t": "pt", "text": "High-low: highest and lowest ACTIVITY", "id": "acfbe-rv3b-80e78-d23a4f"}, {"t": "pt", "text": "VC per unit = Δcost / Δunits", "id": "acfbe-rv3b-80e78-98c067"}, {"t": "pt", "text": "FC = total cost - (units x VC per unit)", "id": "acfbe-rv3b-80e78-6fa09a"}, {"t": "pt", "text": "Adjust for steps or price changes before high-low", "id": "acfbe-rv3b-80e78-5f1d98"}, {"t": "pt", "text": "y = a + bx: a intercept (fixed), b gradient (variable)", "id": "acfbe-rv3b-80e78-38a6cd"}, {"t": "pt", "text": "Gradient = (y2 - y1) / (x2 - x1)", "id": "acfbe-rv3b-80e78-a06d61"}, {"t": "pt", "text": "Relevant range assumption underlies linear behaviour", "id": "acfbe-rv3b-80e78-26058e"}], "id": "acfbe-rv3b-80e78"}], "source": "BPP Workbook ch 3b: sections 1-5 pp82-96; chapter roundup p97", "summary": "Fixed, step, variable, curvilinear and semi-variable costs, cost per unit at different activity levels, the high-low method and linear equations (y = a + bx).", "id": "acfbe-rv3b", "updated": "2026-11-12"}, {"num": "4a", "title": "Forecasting", "pages": [103, 146], "syllabus": "B1", "status": "published", "branches": [{"kind": "concept", "title": "Correlation", "page": [104, 110], "items": [{"t": "pt", "k": 1, "text": "Two variables are correlated if a change in one is accompanied by a change in the other", "id": "acfbe-rv4a-3ad31-40527e"}, {"t": "pt", "text": "Degrees: perfect (all points on a straight line), partial, none; direction: positive (both rise together) or negative (one rises as the other falls)", "id": "acfbe-rv4a-3ad31-615a75"}, {"t": "f", "k": 1, "term": "Correlation coefficient (Pearson)", "text": "r = [nΣxy - ΣxΣy] / √{[nΣx² - (Σx)²][nΣy² - (Σy)²]}", "vars": "n = number of pairs of data; r ranges from -1 to +1", "eg": "r = -0.992 is strong negative correlation", "id": "acfbe-rv4a-3ad31-dffd65"}, {"t": "f", "k": 1, "term": "Coefficient of determination", "text": "r²", "vars": "proportion of the total variation in y explained by variation in x", "eg": "r = 0.9 -> r² = 0.81: 81% of variation in y explained by x", "id": "acfbe-rv4a-3ad31-abd23b"}, {"t": "exam", "text": "The correlation formula is GIVEN in the exam; it measures the strength of a LINEAR relationship only", "id": "acfbe-rv4a-3ad31-fe684e"}, {"t": "exam", "text": "Correlation does not prove causation - it may be chance or a third factor", "id": "acfbe-rv4a-3ad31-5fecfc"}], "id": "acfbe-rv4a-3ad31"}, {"kind": "formula", "title": "Least squares regression", "page": [110, 114], "items": [{"t": "pt", "k": 1, "text": "Regression gives the equation of the line of best fit Y = a + bX (Y dependent, X independent)", "id": "acfbe-rv4a-7ad66-dff7ef"}, {"t": "f", "term": "Regression slope b", "text": "b = [nΣXY - ΣXΣY] / [nΣX² - (ΣX)²]", "vars": "n = number of pairs", "eg": "Formula given in the exam", "id": "acfbe-rv4a-7ad66-70bc13"}, {"t": "f", "term": "Regression intercept a", "text": "a = ΣY/n - b(ΣX/n)", "vars": "= mean of Y - b x mean of X", "eg": "Output/cost data gave Y = 28 + 2.6X", "id": "acfbe-rv4a-7ad66-47e4de"}, {"t": "pt", "text": "Time series regression: X = time period (eg X = 0 for 20X0 quarter 1, so X = 23 is 20X5 quarter 4)", "id": "acfbe-rv4a-7ad66-727312"}, {"t": "eg", "text": "Y = 300 - 4.7X sales trend: plug in the X for the quarter required", "id": "acfbe-rv4a-7ad66-d68120"}, {"t": "pt", "k": 1, "text": "Advantages: definitive line using all the data; disadvantages: assumes a linear relationship and that the past applies to the future", "id": "acfbe-rv4a-7ad66-40e61d"}, {"t": "pt", "k": 1, "text": "Reliability: high r, a large sample, and INTERPOLATION within the data range; EXTRAPOLATION beyond the range is less reliable", "id": "acfbe-rv4a-7ad66-ea8e6f"}, {"t": "exam", "text": "If a question does not say which variable is X, work out which one depends on the other", "id": "acfbe-rv4a-7ad66-97dc2a"}], "id": "acfbe-rv4a-7ad66"}, {"kind": "process", "title": "High-low forecasting", "page": [115, 117], "items": [{"t": "pt", "text": "Select highest and lowest ACTIVITY periods; variable rate = change in cost (or revenue) / change in activity", "id": "acfbe-rv4a-aff67-04f40b"}, {"t": "eg", "text": "Revenue: 80,000 hits $115,000; 60,000 hits $97,000 -> $0.90 per hit; fixed element $43,000", "id": "acfbe-rv4a-aff67-927ac1"}, {"t": "pt", "text": "Stepped fixed costs: adjust for the step before applying the method", "id": "acfbe-rv4a-aff67-a6f19e"}, {"t": "pt", "k": 1, "text": "Inflation: deflate costs to a common price level (divide by the index) BEFORE applying high-low", "id": "acfbe-rv4a-aff67-8cf786"}, {"t": "pt", "text": "Advantages: easy, needs only two observations; disadvantages: ignores other data, highest/lowest may be unrepresentative", "id": "acfbe-rv4a-aff67-b4f2fa"}], "id": "acfbe-rv4a-aff67"}, {"kind": "concept", "title": "Time series analysis", "page": [118, 131], "items": [{"t": "pt", "k": 1, "text": "Four components: trend (T) • seasonal variations (S) • cyclical variations (C) • random variations (R)", "id": "acfbe-rv4a-ca20d-b5fabb"}, {"t": "def", "term": "Trend", "text": "The underlying long-term movement over time in the values recorded", "id": "acfbe-rv4a-ca20d-994515"}, {"t": "def", "term": "Seasonal variations", "text": "Short-term fluctuations due to circumstances recurring in a regular pattern (eg quarters, days)", "id": "acfbe-rv4a-ca20d-28547f"}, {"t": "pt", "text": "Cyclical variations: longer than seasonal (eg business cycle)", "id": "acfbe-rv4a-ca20d-eb6f48"}, {"t": "pt", "k": 1, "text": "Moving average: an average of a fixed number of periods' results - the cycle length (eg 4 for quarterly data)", "id": "acfbe-rv4a-ca20d-747c52"}, {"t": "pt", "text": "With an EVEN number of periods, take a moving average of the moving averages to CENTRE the trend", "id": "acfbe-rv4a-ca20d-72f785"}, {"t": "f", "k": 1, "term": "Additive model", "text": "Y = T + S + R", "vars": "seasonal variation = actual - trend", "eg": "seasonal variations should sum to zero over the cycle", "id": "acfbe-rv4a-ca20d-212423"}, {"t": "f", "k": 1, "term": "Multiplicative model", "text": "Y = T x S x R", "vars": "S = Y / T (seasonal index)", "eg": "indices average to 1 (or 100%) over a cycle", "id": "acfbe-rv4a-ca20d-3b9334"}, {"t": "pt", "text": "Additive weakness: assumes seasonal variations are constant amounts even if the trend changes - the multiplicative model suits growing trends", "id": "acfbe-rv4a-ca20d-788bf6"}, {"t": "pt", "k": 1, "text": "Deseasonalise: additive -> SUBTRACT the seasonal variation (subtract a positive variation, add back a negative one); multiplicative -> DIVIDE by the seasonal index", "id": "acfbe-rv4a-ca20d-0c3953"}, {"t": "pt", "text": "Forecast: extrapolate the trend (by eye, rule of thumb, or regression) then ADD (or multiply by) the seasonal variation", "id": "acfbe-rv4a-ca20d-625c67"}, {"t": "exam", "text": "An exam is unlikely to ask you to derive all seasonal variations, but you must understand the method", "id": "acfbe-rv4a-ca20d-be3835"}, {"t": "pt", "text": "Forecasting problems: the further ahead, the less reliable; past patterns may not continue; random events", "id": "acfbe-rv4a-ca20d-218373"}], "id": "acfbe-rv4a-ca20d"}, {"kind": "formula", "title": "Index numbers", "page": [132, 141], "items": [{"t": "def", "k": 1, "term": "Index", "text": "A measure, over time, of the average changes in value (price or quantity) of a group of items relative to a base period (= 100)", "id": "acfbe-rv4a-49501-d940a7"}, {"t": "f", "term": "Simple price index", "text": "P1 / P0 x 100", "vars": "P0 = base period price, P1 = current price", "eg": "Coffee 40c -> 50c -> 76c: indices 125 and 190", "id": "acfbe-rv4a-49501-3c13e0"}, {"t": "f", "term": "Chain base index", "text": "This period's value / previous period's value x 100", "vars": "shows year-on-year change", "eg": "$2.70, $3.11, $3.42: 115, then 110", "id": "acfbe-rv4a-49501-694579"}, {"t": "f", "k": 1, "term": "Laspeyre price index", "text": "Σ(Pn x Q0) / Σ(P0 x Q0) x 100", "vars": "base-period quantities as weights", "eg": "tends to OVERSTATE price rises", "id": "acfbe-rv4a-49501-7ea46e"}, {"t": "f", "k": 1, "term": "Paasche price index", "text": "Σ(Pn x Qn) / Σ(P0 x Qn) x 100", "vars": "current-period quantities as weights", "eg": "tends to UNDERSTATE; weights must be updated every period", "id": "acfbe-rv4a-49501-5d440d"}, {"t": "f", "term": "Laspeyre quantity index", "text": "Σ(Qn x P0) / Σ(Q0 x P0) x 100", "vars": "base-period prices as weights", "id": "acfbe-rv4a-49501-21e707"}, {"t": "f", "term": "Paasche quantity index", "text": "Σ(Qn x Pn) / Σ(Q0 x Pn) x 100", "vars": "current-period prices as weights", "id": "acfbe-rv4a-49501-22fa93"}, {"t": "f", "term": "Fisher's ideal index", "text": "√(Laspeyre x Paasche)", "vars": "geometric mean of the two", "eg": "balances over- and under-statement", "id": "acfbe-rv4a-49501-5344c1"}, {"t": "pt", "text": "Limitations: approximations; items and weights become out of date; base year must be representative", "id": "acfbe-rv4a-49501-551a1b"}, {"t": "pt", "text": "RPI and CPI measure changes in the cost of living", "id": "acfbe-rv4a-49501-665ffb"}], "id": "acfbe-rv4a-49501"}, {"kind": "process", "title": "Product life cycle", "page": [142, 142], "items": [{"t": "pt", "k": 1, "text": "Introduction -> growth -> maturity -> decline", "id": "acfbe-rv4a-a412c-4a65b6"}, {"t": "pt", "text": "Introduction: slow sales growth, high unit costs, losses likely", "id": "acfbe-rv4a-a412c-e458cf"}, {"t": "pt", "text": "Growth: sales rise sharply, profits start, competitors enter", "id": "acfbe-rv4a-a412c-2bd1fb"}, {"t": "pt", "text": "Maturity: sales growth slows - usually the LONGEST stage", "id": "acfbe-rv4a-a412c-8d8cda"}, {"t": "pt", "text": "Decline: sales fall, overcapacity, severe competition", "id": "acfbe-rv4a-a412c-25634a"}, {"t": "pt", "text": "Life cycle stage affects sales forecasts and pricing decisions", "id": "acfbe-rv4a-a412c-356c5d"}], "id": "acfbe-rv4a-a412c"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Treating a high correlation as proof that one variable causes the other", "id": "acfbe-rv4a-6483a-0541a5"}, {"t": "x", "text": "Extrapolating a regression line far outside the data range and trusting it", "id": "acfbe-rv4a-6483a-8f1b35"}, {"t": "x", "text": "Not centring a moving average taken over an even number of periods", "id": "acfbe-rv4a-6483a-2dbe22"}, {"t": "x", "text": "Deseasonalising by adding a positive additive variation - you must subtract it", "id": "acfbe-rv4a-6483a-2d4de2"}, {"t": "x", "text": "Mixing up Laspeyre (base weights) and Paasche (current weights)", "id": "acfbe-rv4a-6483a-595939"}], "id": "acfbe-rv4a-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "r between -1 and +1; r² = % variation explained", "id": "acfbe-rv4a-80e78-bb6877"}, {"t": "pt", "text": "Correlation ≠ causation", "id": "acfbe-rv4a-80e78-2e5571"}, {"t": "pt", "text": "Regression line Y = a + bX by least squares", "id": "acfbe-rv4a-80e78-80781e"}, {"t": "pt", "text": "Interpolation reliable; extrapolation less so", "id": "acfbe-rv4a-80e78-715b3d"}, {"t": "pt", "text": "Deflate costs by an index before high-low", "id": "acfbe-rv4a-80e78-01eed2"}, {"t": "pt", "text": "Time series: trend, seasonal, cyclical, random", "id": "acfbe-rv4a-80e78-5aef5b"}, {"t": "pt", "text": "Even-period moving averages must be centred", "id": "acfbe-rv4a-80e78-97ee0d"}, {"t": "pt", "text": "Additive Y = T + S + R; multiplicative Y = T x S x R", "id": "acfbe-rv4a-80e78-1f6690"}, {"t": "pt", "text": "Deseasonalise: subtract (additive) or divide (multiplicative)", "id": "acfbe-rv4a-80e78-3d6a12"}, {"t": "pt", "text": "Laspeyre = base weights (overstates); Paasche = current weights (understates)", "id": "acfbe-rv4a-80e78-b1071b"}, {"t": "pt", "text": "Fisher = √(Laspeyre x Paasche)", "id": "acfbe-rv4a-80e78-73e5ec"}, {"t": "pt", "text": "Chain base compares with the previous period", "id": "acfbe-rv4a-80e78-f0cdcc"}, {"t": "pt", "text": "PLC: introduction, growth, maturity, decline", "id": "acfbe-rv4a-80e78-945daf"}, {"t": "pt", "text": "Maturity is usually the longest stage", "id": "acfbe-rv4a-80e78-b0b848"}], "id": "acfbe-rv4a-80e78"}], "source": "BPP Workbook ch 4a: sections 1-14 pp104-142", "summary": "Correlation and the coefficient of determination, least-squares regression, high-low forecasting, time series (trend, moving averages, seasonal variations, deseasonalisation), index numbers (Laspeyre, Paasche, Fisher) and the product life cycle.", "id": "acfbe-rv4a", "updated": "2026-11-12"}, {"num": "4b", "title": "Summarising and Analysing Data", "pages": [147, 178], "syllabus": "B2", "status": "published", "branches": [{"kind": "concept", "title": "Frequency distributions", "page": [148, 153], "items": [{"t": "pt", "k": 1, "text": "Grouped data: frequency shown for a range (class); ungrouped data: frequency shown for individual values", "id": "acfbe-rv4b-11e7b-8cbe96"}, {"t": "pt", "text": "Class intervals should be of equal width where possible and must not overlap", "id": "acfbe-rv4b-11e7b-542cd9"}, {"t": "pt", "text": "Cumulative frequency distribution shows the total number of times a value at or below each class limit occurs", "id": "acfbe-rv4b-11e7b-1d8263"}, {"t": "def", "k": 1, "term": "Ogive", "text": "A graph of a cumulative frequency distribution - used to read off the median and other values", "id": "acfbe-rv4b-11e7b-2e2562"}, {"t": "def", "k": 1, "term": "Histogram", "text": "A frequency distribution shown as bars where the AREA of each bar represents the frequency", "id": "acfbe-rv4b-11e7b-0dfb76"}, {"t": "f", "term": "Unequal class adjustment", "text": "Bar height = frequency x (standard class width / actual class width)", "vars": "formula to learn", "eg": "A class 1.5 times the standard width: multiply frequency by 2/3 (0.67)", "id": "acfbe-rv4b-11e7b-82f923"}], "id": "acfbe-rv4b-11e7b"}, {"kind": "formula", "title": "Averages", "page": [154, 159], "items": [{"t": "f", "k": 1, "term": "Arithmetic mean (ungrouped)", "text": "x̄ = Σx / n", "vars": "Σx = sum of values; n = number of items", "eg": "20 days' demand totalling 185 units: mean 9.25 units", "id": "acfbe-rv4b-68c58-081997"}, {"t": "f", "k": 1, "term": "Arithmetic mean (frequency or grouped data)", "text": "x̄ = Σfx / Σf", "vars": "f = frequency; x = value (class mid-point for grouped data)", "eg": "Grouped data uses mid-points so the mean is an estimate", "id": "acfbe-rv4b-68c58-accfd3"}, {"t": "def", "k": 1, "term": "Mode", "text": "The most frequently occurring value (grouped data: read from the histogram's modal class)", "id": "acfbe-rv4b-68c58-a806b0"}, {"t": "def", "k": 1, "term": "Median", "text": "The value of the middle member of an array (values in order); the ((n + 1)/2)th item", "id": "acfbe-rv4b-68c58-537016"}, {"t": "eg", "text": "Even number of items: the median is the average of the two middle values", "id": "acfbe-rv4b-68c58-47057a"}, {"t": "pt", "text": "Grouped data: median read from the ogive at the n/2 point", "id": "acfbe-rv4b-68c58-b1ab9d"}, {"t": "pt", "text": "Mean uses all values but is distorted by extremes; median and mode are not distorted by extremes", "id": "acfbe-rv4b-68c58-3800e8"}], "id": "acfbe-rv4b-68c58"}, {"kind": "formula", "title": "Dispersion", "page": [160, 161], "items": [{"t": "pt", "k": 1, "text": "Averages locate the centre but say nothing about the spread of the data", "id": "acfbe-rv4b-aac26-9f19af"}, {"t": "f", "k": 1, "term": "Standard deviation", "text": "σ = √[Σ(x - x̄)² / n] (ungrouped); σ = √[Σf(x - x̄)² / Σf] (grouped)", "vars": "variance = σ²; standard deviation = √variance", "eg": "Variance 256 hours² -> standard deviation 16 hours", "id": "acfbe-rv4b-aac26-293820"}, {"t": "f", "k": 1, "term": "Coefficient of variation", "text": "Standard deviation / Mean", "vars": "compares relative spread of two distributions with different means", "eg": "the higher the coefficient, the more relatively dispersed", "id": "acfbe-rv4b-aac26-260a96"}, {"t": "pt", "text": "Standard deviation is the most important measure of spread used in statistics", "id": "acfbe-rv4b-aac26-14fc52"}], "id": "acfbe-rv4b-aac26"}, {"kind": "formula", "title": "Expected values", "page": [161, 162], "items": [{"t": "f", "k": 1, "term": "Expected value", "text": "EV = Σpx", "vars": "x = outcome; p = probability of that outcome (probabilities sum to 1)", "eg": "Outcomes $100 (0.4) and $50 (0.6): EV = 40 + 30 = $70", "id": "acfbe-rv4b-42bf3-5e8335"}, {"t": "def", "k": 1, "term": "Expected value", "text": "A weighted average of the possible outcomes of a decision, weighted by their probabilities", "id": "acfbe-rv4b-42bf3-6c9c33"}, {"t": "pt", "text": "Choose the option with the highest EV (for profit) - a long-run average, not the outcome of a single decision", "id": "acfbe-rv4b-42bf3-adcce6"}, {"t": "x", "text": "EV ignores risk attitude and is less meaningful for a one-off decision", "id": "acfbe-rv4b-42bf3-ef2b70"}], "id": "acfbe-rv4b-42bf3"}, {"kind": "concept", "title": "The normal distribution", "page": [163, 172], "items": [{"t": "pt", "k": 1, "text": "Properties: symmetrical and bell-shaped • mean = median = mode at the centre • area under the curve = 1 (area left of the mean = area right = 0.5) • tails approach but never touch the axis", "id": "acfbe-rv4b-2dd61-f92760"}, {"t": "f", "k": 1, "term": "z score", "text": "z = (x - μ) / σ", "vars": "x = value; μ = mean; σ = standard deviation; z = number of standard deviations from the mean", "eg": "Mean 100, σ 10: x = 80 gives z = -2", "id": "acfbe-rv4b-2dd61-2f1f15"}, {"t": "pt", "text": "Normal tables give the area (probability) between the mean and z standard deviations", "id": "acfbe-rv4b-2dd61-e13982"}, {"t": "pt", "text": "Key areas: z = 1 -> 0.3413; z = 1.96 -> 0.475 (so ±1.96σ = 95%); z = 2 -> 0.4772; z = 2.58 -> 0.495 (±2.58σ = 99%)", "id": "acfbe-rv4b-2dd61-0da6d2"}, {"t": "eg", "text": "Mean 100, σ 10: P(above 80) = 0.5 + 0.4772 = 0.9772; P(above 115) = 0.5 - 0.4332 = 0.0668; P(80 to 110) = 0.4772 + 0.3413 = 0.8185", "id": "acfbe-rv4b-2dd61-4295e3"}, {"t": "exam", "text": "The z formula is given on the normal distribution table", "id": "acfbe-rv4b-2dd61-f1a53e"}, {"t": "exam", "text": "Always sketch the curve to see which areas to add (either side of the mean) or subtract (same side)", "id": "acfbe-rv4b-2dd61-431e56"}, {"t": "exam", "text": "You may need to work backwards from a % of the population to a z score and then to an x value", "id": "acfbe-rv4b-2dd61-8c97f6"}, {"t": "exam", "text": "The syllabus requires you to explain the properties of the normal distribution", "id": "acfbe-rv4b-2dd61-001de8"}], "id": "acfbe-rv4b-2dd61"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using bar HEIGHT instead of AREA for histograms with unequal class widths", "id": "acfbe-rv4b-6483a-adfe73"}, {"t": "x", "text": "Forgetting to sort data before finding the median", "id": "acfbe-rv4b-6483a-e1cfc4"}, {"t": "x", "text": "Adding 0.5 when both values are on the same side of the mean - subtract the areas instead", "id": "acfbe-rv4b-6483a-d478db"}, {"t": "x", "text": "Comparing spreads of distributions with different means using standard deviation instead of the coefficient of variation", "id": "acfbe-rv4b-6483a-b94b17"}], "id": "acfbe-rv4b-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Histogram: area represents frequency", "id": "acfbe-rv4b-80e78-90a219"}, {"t": "pt", "text": "Ogive = cumulative frequency graph", "id": "acfbe-rv4b-80e78-5a9b75"}, {"t": "pt", "text": "Mean = Σx/n or Σfx/Σf", "id": "acfbe-rv4b-80e78-4515c5"}, {"t": "pt", "text": "Mode = most frequent value", "id": "acfbe-rv4b-80e78-8d8ba2"}, {"t": "pt", "text": "Median = middle item, (n + 1)/2", "id": "acfbe-rv4b-80e78-f33b72"}, {"t": "pt", "text": "Standard deviation = √variance", "id": "acfbe-rv4b-80e78-f6c47c"}, {"t": "pt", "text": "Coefficient of variation = σ / mean", "id": "acfbe-rv4b-80e78-2de913"}, {"t": "pt", "text": "EV = Σpx (long-run average)", "id": "acfbe-rv4b-80e78-617331"}, {"t": "pt", "text": "Normal: symmetrical, bell-shaped, mean = median = mode", "id": "acfbe-rv4b-80e78-950e16"}, {"t": "pt", "text": "Total area = 1; each half = 0.5", "id": "acfbe-rv4b-80e78-1b787d"}, {"t": "pt", "text": "z = (x - μ) / σ", "id": "acfbe-rv4b-80e78-aa4eda"}, {"t": "pt", "text": "±1.96σ = 95%; ±2.58σ = 99%", "id": "acfbe-rv4b-80e78-aace46"}, {"t": "pt", "text": "Sketch the curve before reading tables", "id": "acfbe-rv4b-80e78-2bccf6"}], "id": "acfbe-rv4b-80e78"}], "source": "BPP Workbook ch 4b: sections 1-7 pp148-172", "summary": "Frequency distributions, ogives and histograms, the mean, mode and median, standard deviation and coefficient of variation, expected values, and the normal distribution with z scores.", "id": "acfbe-rv4b", "updated": "2026-11-12"}, {"num": "5", "title": "Accounting for Materials", "pages": [179, 212], "syllabus": "C1", "status": "published", "branches": [{"kind": "process", "title": "Ordering, receiving and issuing materials", "page": [180, 184], "items": [{"t": "pt", "k": 1, "text": "Every movement of materials must be documented", "id": "acfbe-rv5-e10aa-e69915"}, {"t": "pt", "text": "Purchase requisition (stores -> purchasing) -> quotations -> purchase order (to supplier) -> delivery note (signed for the carrier) -> goods received note (GRN, by stores) -> invoice checked against order and GRN", "id": "acfbe-rv5-e10aa-23c629"}, {"t": "pt", "k": 1, "text": "Materials can only be issued against a materials (stores) requisition note, which records the cost centre/job charged", "id": "acfbe-rv5-e10aa-9dbe72"}, {"t": "pt", "text": "Materials transfer note (job to job) and materials returned note (back to stores)", "id": "acfbe-rv5-e10aa-8a1952"}, {"t": "pt", "text": "Computerised systems update records in real time and can trigger reorders", "id": "acfbe-rv5-e10aa-0e789b"}], "id": "acfbe-rv5-e10aa"}, {"kind": "concept", "title": "Storage and inventory records", "page": [185, 188], "items": [{"t": "pt", "text": "Objectives of storing: speedy issue/receipt, full identification, protection from damage and theft, minimum stockholding cost, correct quantities", "id": "acfbe-rv5-e5959-d93f3c"}, {"t": "pt", "text": "Bin card: QUANTITY of an item at a stores location (kept with the inventory)", "id": "acfbe-rv5-e5959-10b36e"}, {"t": "pt", "text": "Stores ledger account: quantity AND VALUE (kept in the cost department)", "id": "acfbe-rv5-e5959-cab048"}, {"t": "f", "k": 1, "term": "Free inventory", "text": "Physical inventory + Materials on order from suppliers - Materials requisitioned but not yet issued", "vars": "free inventory helps ORDERING decisions; physical inventory helps issuing and counting", "eg": "3,925 in inventory, 8,450 owed to customers, free 5,525 -> on order 10,050", "id": "acfbe-rv5-e5959-8caa32"}, {"t": "pt", "text": "Periodic stocktake (all items at one time) vs continuous stocktaking (a few items checked regularly - avoids annual disruption)", "id": "acfbe-rv5-e5959-762f0a"}, {"t": "def", "term": "Perpetual inventory", "text": "A recording system where bin cards and stores ledger accounts are updated for every receipt and issue, so the balance is always known", "id": "acfbe-rv5-e5959-0504f1"}, {"t": "pt", "text": "Discrepancies from errors, theft, damage, evaporation - investigate and adjust records", "id": "acfbe-rv5-e5959-beb73e"}, {"t": "pt", "text": "Obsolete, deteriorating and slow-moving items should be identified and written down", "id": "acfbe-rv5-e5959-65dc7f"}], "id": "acfbe-rv5-e5959"}, {"kind": "formula", "title": "Inventory control levels", "page": [188, 191], "items": [{"t": "pt", "k": 1, "text": "Inventory costs: purchase cost, holding costs (capital tied up, storage, insurance, deterioration, obsolescence, theft), ordering costs, stockout costs (lost sales, goodwill, production stoppages)", "id": "acfbe-rv5-f2d1d-ee2e03"}, {"t": "pt", "text": "Objective: keep inventory at the level that minimises total costs while meeting demand", "id": "acfbe-rv5-f2d1d-b08fab"}, {"t": "f", "k": 1, "term": "Reorder level", "text": "Maximum usage x Maximum lead time", "vars": "lead time = time between placing and receiving an order", "eg": "avoids stockouts in the worst case", "id": "acfbe-rv5-f2d1d-83d9e6"}, {"t": "f", "k": 1, "term": "Minimum (buffer) level", "text": "Reorder level - (Average usage x Average lead time)", "vars": "a warning that inventory is dangerously low", "eg": "buffer inventory = minimum level", "id": "acfbe-rv5-f2d1d-2f514f"}, {"t": "f", "k": 1, "term": "Maximum level", "text": "Reorder level + Reorder quantity - (Minimum usage x Minimum lead time)", "vars": "a warning that inventory is wastefully high", "eg": "formula to learn", "id": "acfbe-rv5-f2d1d-65a943"}, {"t": "f", "term": "Average inventory", "text": "Buffer (safety) inventory + ½ Reorder quantity", "vars": "assumes inventory falls evenly", "eg": "no buffer -> average = Q/2", "id": "acfbe-rv5-f2d1d-b222a3"}], "id": "acfbe-rv5-f2d1d"}, {"kind": "formula", "title": "EOQ, EBQ and bulk discounts", "page": [192, 198], "items": [{"t": "f", "k": 1, "term": "Economic order quantity", "text": "EOQ = √(2 x Co x D / Ch)", "vars": "Co = cost of placing one order; D = annual demand; Ch = cost of holding one unit for a year", "eg": "D 25,000, Co $32, Ch $6.40: √250,000 = 500 units", "warn": "Ch is per unit per year - convert a % of purchase price into $", "id": "acfbe-rv5-97054-18854d"}, {"t": "pt", "k": 1, "text": "At the EOQ, total holding cost = total ordering cost (the curves intersect at minimum total cost)", "id": "acfbe-rv5-97054-40064d"}, {"t": "pt", "text": "Annual ordering cost = (D / Q) x Co; annual holding cost = (Q / 2) x Ch", "id": "acfbe-rv5-97054-f6e843"}, {"t": "f", "term": "Economic batch quantity", "text": "EBQ = √[2 x Co x D / (Ch x (1 - D/R))]", "vars": "Co = set-up cost per batch; R = production rate per period (must exceed usage D)", "eg": "used when resupply is gradual (own production), not instant", "id": "acfbe-rv5-97054-060719"}, {"t": "pt", "k": 1, "text": "Bulk discounts: compare total annual cost (purchase + ordering + holding) at the EOQ and at EACH discount threshold; holding cost may fall with the discounted price", "id": "acfbe-rv5-97054-b15be1"}, {"t": "eg", "text": "Demand 45, price $200, holding 15% of price, order cost $300: compare EOQ (30 units) with 60 units at 3% discount and 90 units at 5% discount", "id": "acfbe-rv5-97054-1bb4c4"}, {"t": "exam", "text": "The EOQ formula is given in the exam - know its purpose: minimising total ordering and holding costs", "id": "acfbe-rv5-97054-f5d564"}, {"t": "pt", "text": "Order cycling: review items periodically and order up to a set level", "id": "acfbe-rv5-97054-8675f6"}, {"t": "pt", "text": "Two-bin system: when the first bin empties, reorder and use the second bin", "id": "acfbe-rv5-97054-e4c878"}, {"t": "pt", "k": 1, "text": "ABC / Pareto (80/20): roughly 20% of items account for 80% of value - control expensive items most closely", "id": "acfbe-rv5-97054-d3d6ea"}], "id": "acfbe-rv5-97054"}, {"kind": "compare", "title": "Inventory valuation methods", "page": [199, 203], "items": [{"t": "table", "rows": [["Method", "Issues priced at", "Closing inventory", "In rising prices"], ["FIFO", "Earliest remaining deliveries", "Most recent prices", "Lower cost of issues, higher profit and inventory value"], ["LIFO", "Most recent deliveries", "Older prices", "Higher cost of issues, lower profit (not allowed under IAS 2)"], ["AVCO (cumulative weighted average)", "Average cost recalculated after each receipt", "Average price", "Between FIFO and LIFO"]], "id": "acfbe-rv5-d5417-fae409"}, {"t": "pt", "k": 1, "text": "Cost of issues + closing inventory = opening inventory + purchases (all methods)", "id": "acfbe-rv5-d5417-84353d"}, {"t": "pt", "text": "Material control account: Dr purchases (from payables); Cr issues to WIP (direct) and production overhead (indirect); balance = closing inventory", "id": "acfbe-rv5-d5417-b3d0b6"}, {"t": "exam", "text": "Inventory is valued at the lower of cost and net realisable value in the financial accounts", "id": "acfbe-rv5-d5417-5ef494"}], "id": "acfbe-rv5-d5417"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using minimum usage in the reorder level formula - it uses MAXIMUM usage x MAXIMUM lead time", "id": "acfbe-rv5-6483a-e281cc"}, {"t": "x", "text": "Entering holding cost as a % in the EOQ formula instead of $ per unit per year", "id": "acfbe-rv5-6483a-29f310"}, {"t": "x", "text": "Ignoring the effect of a discount on holding cost per unit", "id": "acfbe-rv5-6483a-8b0360"}, {"t": "x", "text": "Treating the bin card as a record of value - it shows quantity only", "id": "acfbe-rv5-6483a-17c321"}, {"t": "x", "text": "Forgetting to deduct materials requisitioned but not issued when calculating free inventory", "id": "acfbe-rv5-6483a-ff0705"}], "id": "acfbe-rv5-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Requisition -> order -> delivery note -> GRN -> issue on materials requisition", "id": "acfbe-rv5-80e78-19fefd"}, {"t": "pt", "text": "Bin card = quantity; stores ledger = quantity and value", "id": "acfbe-rv5-80e78-e607bc"}, {"t": "pt", "text": "Free inventory = physical + on order - requisitioned not issued", "id": "acfbe-rv5-80e78-cccddc"}, {"t": "pt", "text": "Reorder level = max usage x max lead time", "id": "acfbe-rv5-80e78-fa7712"}, {"t": "pt", "text": "Minimum = reorder level - (avg usage x avg lead time)", "id": "acfbe-rv5-80e78-77a85e"}, {"t": "pt", "text": "Maximum = reorder level + reorder qty - (min usage x min lead time)", "id": "acfbe-rv5-80e78-299f08"}, {"t": "pt", "text": "Average inventory = buffer + Q/2", "id": "acfbe-rv5-80e78-dc1d20"}, {"t": "pt", "text": "EOQ = √(2CoD/Ch); holding cost = ordering cost at EOQ", "id": "acfbe-rv5-80e78-0f09ca"}, {"t": "pt", "text": "EBQ adds (1 - D/R) for gradual replenishment", "id": "acfbe-rv5-80e78-c44c0c"}, {"t": "pt", "text": "Bulk discounts: compare total cost at each threshold", "id": "acfbe-rv5-80e78-66a6ea"}, {"t": "pt", "text": "Two-bin, order cycling, ABC/Pareto controls", "id": "acfbe-rv5-80e78-bd3f43"}, {"t": "pt", "text": "FIFO: issues at oldest prices; closing inventory at latest", "id": "acfbe-rv5-80e78-b484df"}, {"t": "pt", "text": "Rising prices: FIFO gives highest profit", "id": "acfbe-rv5-80e78-011a89"}], "id": "acfbe-rv5-80e78"}], "source": "BPP Workbook ch 5: sections 1-7 pp180-203", "summary": "Inventory control documents, storage and stock records, inventory costs and control levels, EOQ, EBQ and bulk discounts, other reordering systems, the material control account and FIFO/LIFO/AVCO valuation.", "id": "acfbe-rv5", "updated": "2026-11-12"}, {"num": "6", "title": "Accounting for Labour", "pages": [213, 234], "syllabus": "C2", "status": "published", "branches": [{"kind": "formula", "title": "Measuring labour activity", "page": [214, 217], "items": [{"t": "def", "k": 1, "term": "Production", "text": "The quantity or volume of output produced", "id": "acfbe-rv6-78f33-b90bb6"}, {"t": "def", "k": 1, "term": "Productivity", "text": "A measure of the efficiency with which output has been produced (output relative to input)", "id": "acfbe-rv6-78f33-7ad5c0"}, {"t": "f", "term": "Productivity ratio", "text": "Actual output / Expected output x 100%", "vars": "expected output = hours worked x expected rate", "eg": "42 units vs 40 expected = 105%", "id": "acfbe-rv6-78f33-032f76"}, {"t": "pt", "text": "Improved productivity reduces unit costs; automation replaces labour with machines and changes cost structure", "id": "acfbe-rv6-78f33-db1906"}, {"t": "f", "k": 1, "term": "Efficiency ratio", "text": "Expected (standard) hours to make actual output / Actual hours worked x 100%", "vars": "standard hours = output x standard hours per unit", "eg": "above 100% = more efficient than standard", "id": "acfbe-rv6-78f33-7960d0"}, {"t": "f", "k": 1, "term": "Capacity ratio", "text": "Actual hours worked / Budgeted hours x 100%", "vars": "measures use of available labour hours", "id": "acfbe-rv6-78f33-2f9cb6"}, {"t": "f", "k": 1, "term": "Production volume ratio", "text": "Expected (standard) hours to make actual output / Budgeted hours x 100%", "vars": "= efficiency ratio x capacity ratio", "eg": "90% efficiency x 120% capacity = 108%", "id": "acfbe-rv6-78f33-14a181"}], "id": "acfbe-rv6-78f33"}, {"kind": "compare", "title": "Remuneration methods", "page": [217, 221], "items": [{"t": "table", "rows": [["Method", "How pay is calculated", "Strength", "Weakness"], ["Time work (day rate)", "Hours worked x rate per hour (+ overtime premium)", "Simple, stable pay", "No incentive to work faster"], ["Straight piecework", "Units produced x rate per unit (often with a guaranteed minimum)", "Rewards output", "Quality may suffer; pay fluctuates"], ["Differential piecework", "Higher rate per unit above output thresholds", "Stronger incentive", "More complex"], ["High day rate", "High hourly rate expecting high output", "Simple, attracts good workers", "Must monitor output"], ["Individual bonus", "Bonus for output/targets beyond a set level", "Rewards individual effort", "Can be divisive"], ["Group bonus", "Bonus based on the whole group's output", "Encourages teamwork", "Weak link to individual effort"]], "id": "acfbe-rv6-60965-00ffa9"}, {"t": "f", "k": 1, "term": "Time work wages", "text": "Hours worked x Rate of pay per hour", "vars": "overtime premium is paid on top for extra hours", "id": "acfbe-rv6-60965-a63d70"}, {"t": "f", "k": 1, "term": "Piecework wages", "text": "Units produced x Rate of pay per unit", "vars": "formula to learn", "eg": "$5 per piecework hour, 47.5 hours produced = $237.50", "id": "acfbe-rv6-60965-9621e0"}, {"t": "pt", "text": "Bonus schemes compensate time-paid workers for their inability to increase earnings by working harder", "id": "acfbe-rv6-60965-9edccc"}], "id": "acfbe-rv6-60965"}, {"kind": "process", "title": "Recording labour and idle time", "page": [221, 227], "items": [{"t": "pt", "k": 1, "text": "Attendance time recorded on clock cards/attendance records; job time on job cards, route cards, timesheets", "id": "acfbe-rv6-bcdae-ea861b"}, {"t": "pt", "text": "Departments involved: personnel (HR), production planning, timekeeping, wages (payroll), cost accounting", "id": "acfbe-rv6-bcdae-9f9e7a"}, {"t": "pt", "text": "Salaried staff may still complete timesheets to charge time to jobs or clients", "id": "acfbe-rv6-bcdae-685b62"}, {"t": "def", "term": "Idle time", "text": "Paid time in which no productive work is done (eg machine breakdowns, waiting for materials)", "id": "acfbe-rv6-bcdae-b5f18e"}, {"t": "f", "k": 1, "term": "Idle time ratio", "text": "Idle hours / Total hours x 100%", "vars": "formula to learn", "eg": "shows the proportion of paid time lost", "id": "acfbe-rv6-bcdae-093f89"}, {"t": "pt", "text": "Idle time is usually a production OVERHEAD (abnormal idle time may be written off to profit or loss)", "id": "acfbe-rv6-bcdae-04eccb"}], "id": "acfbe-rv6-bcdae"}, {"kind": "formula", "title": "Labour turnover", "page": [227, 229], "items": [{"t": "def", "k": 1, "term": "Labour turnover", "text": "The rate at which employees leave a company - should be kept as low as possible", "id": "acfbe-rv6-47965-8b1559"}, {"t": "f", "k": 1, "term": "Labour turnover rate", "text": "Number of leavers who require replacement / Average number of employees in the period x 100%", "vars": "average = (opening + closing) / 2", "eg": "leavers who are NOT replaced are excluded", "id": "acfbe-rv6-47965-a817ba"}, {"t": "pt", "text": "Reasons: unavoidable (retirement, illness, relocation) or avoidable (pay, conditions, poor management, lack of prospects)", "id": "acfbe-rv6-47965-1f7a03"}, {"t": "pt", "text": "Replacement costs: recruitment, selection, training, lower initial productivity, mistakes, extra wear and scrap", "id": "acfbe-rv6-47965-8ede55"}, {"t": "pt", "text": "Preventative costs: personnel administration, welfare, pay and conditions improvements", "id": "acfbe-rv6-47965-e6718a"}, {"t": "pt", "text": "Prevention: satisfactory pay and conditions, good management, career prospects, a pleasant environment", "id": "acfbe-rv6-47965-3b79c8"}, {"t": "exam", "text": "Make sure you can calculate labour turnover", "id": "acfbe-rv6-47965-4eb50d"}], "id": "acfbe-rv6-47965"}, {"kind": "concept", "title": "Accounting for labour costs", "page": [229, 231], "items": [{"t": "pt", "text": "Wages control account: Dr with gross pay (net pay, deductions); Cr direct wages to WIP, indirect wages to production overhead, non-production wages to admin/selling overheads", "id": "acfbe-rv6-1a219-d0a132"}, {"t": "pt", "k": 1, "text": "Direct labour = basic pay of direct workers for productive hours (including overtime at BASIC rate)", "id": "acfbe-rv6-1a219-1c7bb2"}, {"t": "pt", "k": 1, "text": "Overtime PREMIUM is indirect (production overhead) unless worked at a customer's specific request (then direct to that job)", "id": "acfbe-rv6-1a219-114b13"}, {"t": "pt", "text": "Indirect labour: indirect workers' pay, idle time, sick pay, holiday pay, bonuses (usually), overtime premium", "id": "acfbe-rv6-1a219-daf90f"}, {"t": "exam", "text": "The Study Guide requires you to calculate direct and indirect labour costs", "id": "acfbe-rv6-1a219-38328c"}], "id": "acfbe-rv6-1a219"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Including leavers who are not replaced in the labour turnover rate", "id": "acfbe-rv6-6483a-f21355"}, {"t": "x", "text": "Mixing up the capacity ratio (actual/budgeted hours) and efficiency ratio (standard/actual hours)", "id": "acfbe-rv6-6483a-25e038"}, {"t": "x", "text": "Charging overtime premium to the job as direct labour when it was not requested by the customer", "id": "acfbe-rv6-6483a-9b86b4"}, {"t": "x", "text": "Treating idle time as direct labour - it is normally an overhead", "id": "acfbe-rv6-6483a-bdeeea"}], "id": "acfbe-rv6-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Production = output; productivity = efficiency of output", "id": "acfbe-rv6-80e78-f4a7a8"}, {"t": "pt", "text": "Efficiency = standard hours / actual hours", "id": "acfbe-rv6-80e78-617880"}, {"t": "pt", "text": "Capacity = actual hours / budgeted hours", "id": "acfbe-rv6-80e78-e2ad30"}, {"t": "pt", "text": "Production volume = standard hours / budgeted hours = efficiency x capacity", "id": "acfbe-rv6-80e78-daf8e7"}, {"t": "pt", "text": "Time work = hours x rate; piecework = units x rate", "id": "acfbe-rv6-80e78-3003b1"}, {"t": "pt", "text": "Differential piecework: higher rates above thresholds", "id": "acfbe-rv6-80e78-d5ae9a"}, {"t": "pt", "text": "Group bonus encourages teamwork", "id": "acfbe-rv6-80e78-058dea"}, {"t": "pt", "text": "Idle time ratio = idle hours / total hours", "id": "acfbe-rv6-80e78-324485"}, {"t": "pt", "text": "Labour turnover = replaced leavers / average employees", "id": "acfbe-rv6-80e78-6c6192"}, {"t": "pt", "text": "Overtime at basic rate = direct; premium = overhead", "id": "acfbe-rv6-80e78-172ae8"}, {"t": "pt", "text": "Idle time and most bonuses = overhead", "id": "acfbe-rv6-80e78-c081e8"}, {"t": "pt", "text": "Wages control: Cr WIP (direct), production overhead (indirect)", "id": "acfbe-rv6-80e78-460ab8"}], "id": "acfbe-rv6-80e78"}], "source": "BPP Workbook ch 6: sections 1-5 pp214-231", "summary": "Production and productivity, efficiency/capacity/production volume ratios, remuneration methods (time work, piecework, bonus schemes), recording labour time, idle time, labour turnover and the wages control account.", "id": "acfbe-rv6", "updated": "2026-11-12"}, {"num": "7a", "title": "Accounting for Overheads", "pages": [235, 262], "syllabus": "C3", "status": "published", "branches": [{"kind": "concept", "title": "Absorption costing basics", "page": [236, 238], "items": [{"t": "def", "k": 1, "term": "Overhead", "text": "The cost incurred in making a product, providing a service or running a department that cannot be traced directly and in full to it", "id": "acfbe-rv7a-fdfff-32d9d3"}, {"t": "pt", "k": 1, "text": "Objective of absorption costing: include in the total cost of a product an appropriate share of the organisation's total overhead", "id": "acfbe-rv7a-fdfff-0c8178"}, {"t": "pt", "text": "Reasons: inventory valuation (IAS 2 requires production overheads in inventory), pricing, establishing profitability", "id": "acfbe-rv7a-fdfff-897218"}, {"t": "pt", "k": 1, "text": "Three stages: 1 allocation -> 2 apportionment -> 3 absorption", "id": "acfbe-rv7a-fdfff-cd9d0f"}, {"t": "exam", "text": "Overhead apportionment and absorption is one of the most important F2 topics - almost certain to be examined", "id": "acfbe-rv7a-fdfff-1fa8e0"}], "id": "acfbe-rv7a-fdfff"}, {"kind": "process", "title": "Allocation and apportionment", "page": [239, 250], "items": [{"t": "def", "k": 1, "term": "Allocation", "text": "Charging WHOLE cost items direct to a cost unit or cost centre (eg a department's foreman's wages)", "id": "acfbe-rv7a-d5a4e-d92d3a"}, {"t": "def", "k": 1, "term": "Apportionment", "text": "Spreading shared indirect costs fairly between cost centres using a suitable basis", "id": "acfbe-rv7a-d5a4e-ffd6f3"}, {"t": "pt", "text": "Stage 1 bases for general overheads: rent, rates, heating -> floor area • building insurance -> floor area/value • machinery depreciation and insurance -> machinery value • canteen, personnel -> number of employees • power -> machine hours or kW usage", "id": "acfbe-rv7a-d5a4e-1b7971"}, {"t": "pt", "text": "Stage 2: reapportion SERVICE cost centre costs (stores, maintenance, canteen) to PRODUCTION cost centres - only production departments make saleable output", "id": "acfbe-rv7a-d5a4e-224869"}, {"t": "pt", "k": 1, "text": "Direct method: ignores work service centres do for each other - service costs go straight to production departments", "id": "acfbe-rv7a-d5a4e-8a6585"}, {"t": "pt", "k": 1, "text": "Step-down method: reapportion one service centre (usually the one doing most work for the other) including to the second service centre; then reapportion the second only to production", "id": "acfbe-rv7a-d5a4e-e6e973"}, {"t": "pt", "k": 1, "text": "Reciprocal method: recognises inter-service work fully - repeated distribution or algebraic equations", "id": "acfbe-rv7a-d5a4e-082cb2"}, {"t": "f", "term": "Reciprocal (algebraic) method", "text": "M = Maintenance own cost + share of S; S = Stores own cost + share of M", "vars": "define each variable, solve the simultaneous equations, then apportion M and S to production", "eg": "e.g. M = 10,000 + 0.2S; S = 12,000 + 0.1M", "id": "acfbe-rv7a-d5a4e-e33824"}, {"t": "exam", "text": "Never ignore reciprocal services unless the question tells you to", "id": "acfbe-rv7a-d5a4e-90db74"}], "id": "acfbe-rv7a-d5a4e"}, {"kind": "formula", "title": "Overhead absorption", "page": [251, 255], "items": [{"t": "def", "k": 1, "term": "Absorption", "text": "Charging overheads allocated and apportioned to production cost centres to the cost units passing through them, using a predetermined rate", "id": "acfbe-rv7a-fb0d4-e2b296"}, {"t": "f", "k": 1, "term": "Overhead absorption rate (OAR)", "text": "Budgeted overhead / Budgeted activity level", "vars": "activity = units, direct labour hours, machine hours, % of prime cost etc", "eg": "$50,000 / 100,000 hours = $0.50 per direct labour hour", "id": "acfbe-rv7a-fb0d4-5f6e8a"}, {"t": "pt", "text": "Steps: estimate overhead -> estimate activity level -> divide to get the rate (all BUDGETED figures, set in advance)", "id": "acfbe-rv7a-fb0d4-061e3e"}, {"t": "pt", "text": "Choice of base: machine hours for machine-intensive departments; labour hours for labour-intensive; units only if products are identical", "id": "acfbe-rv7a-fb0d4-7d9474"}, {"t": "pt", "k": 1, "text": "Blanket (single factory-wide) rate vs departmental rates - departmental rates are fairer when products use departments differently", "id": "acfbe-rv7a-fb0d4-4e40e9"}, {"t": "eg", "text": "Old Grammar School: blanket $2.33 per hour vs separate rates $1.80 (A) and $5.00 (B) per hour give very different job costs", "id": "acfbe-rv7a-fb0d4-dc3109"}], "id": "acfbe-rv7a-fb0d4"}, {"kind": "formula", "title": "Under- and over-absorption", "page": [256, 259], "items": [{"t": "pt", "k": 1, "text": "Absorbed overhead = actual activity x predetermined OAR", "id": "acfbe-rv7a-4738c-3a8e07"}, {"t": "f", "k": 1, "term": "Under/over absorption", "text": "Actual overhead incurred - Absorbed overhead", "vars": "POSITIVE = UNDER-absorbed (debit to profit or loss); NEGATIVE = OVER-absorbed (credit to profit or loss)", "eg": "Budget $80,000 for 40,000 hrs ($2/hr); actual 36,000 hrs and $84,000 -> absorbed $72,000, under-absorbed $12,000", "id": "acfbe-rv7a-4738c-71633d"}, {"t": "pt", "text": "Causes: actual overhead differs from budget (expenditure) and/or actual activity differs from budget (volume)", "id": "acfbe-rv7a-4738c-885da6"}, {"t": "pt", "text": "Ledger: production overhead control account - Dr actual overhead; Cr absorbed to WIP; balance transferred to the under/over-absorbed overhead account and then to profit or loss", "id": "acfbe-rv7a-4738c-6838a1"}, {"t": "exam", "text": "Under-absorption REDUCES profit; over-absorption INCREASES profit", "id": "acfbe-rv7a-4738c-6eaf75"}], "id": "acfbe-rv7a-4738c"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using ACTUAL overhead or activity to calculate the OAR - it uses BUDGETED figures", "id": "acfbe-rv7a-6483a-434201"}, {"t": "x", "text": "Calling actual overhead > absorbed overhead 'over-absorbed' - it is under-absorbed", "id": "acfbe-rv7a-6483a-89d5fe"}, {"t": "x", "text": "Leaving service cost centre costs unapportioned - they must end up in production centres", "id": "acfbe-rv7a-6483a-150d89"}, {"t": "x", "text": "Using the direct method when the question requires reciprocal servicing to be recognised", "id": "acfbe-rv7a-6483a-8fa8b6"}], "id": "acfbe-rv7a-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Absorption costing stages: allocate, apportion, absorb", "id": "acfbe-rv7a-80e78-2908b4"}, {"t": "pt", "text": "Allocation = whole cost to one centre", "id": "acfbe-rv7a-80e78-88f120"}, {"t": "pt", "text": "Apportionment = share costs on a fair basis", "id": "acfbe-rv7a-80e78-d129b9"}, {"t": "pt", "text": "Floor area for rent; employees for canteen; machine value for depreciation", "id": "acfbe-rv7a-80e78-8a1425"}, {"t": "pt", "text": "Service centres reapportioned to production centres", "id": "acfbe-rv7a-80e78-c225a5"}, {"t": "pt", "text": "Methods: direct, step-down, reciprocal (repeated distribution or algebra)", "id": "acfbe-rv7a-80e78-f4d184"}, {"t": "pt", "text": "OAR = budgeted overhead / budgeted activity", "id": "acfbe-rv7a-80e78-88c3e1"}, {"t": "pt", "text": "Absorbed = actual activity x OAR", "id": "acfbe-rv7a-80e78-2beb47"}, {"t": "pt", "text": "Actual > absorbed = under-absorbed (reduces profit)", "id": "acfbe-rv7a-80e78-cc8f9d"}, {"t": "pt", "text": "Absorbed > actual = over-absorbed (increases profit)", "id": "acfbe-rv7a-80e78-2b632c"}, {"t": "pt", "text": "Departmental rates are fairer than a blanket rate", "id": "acfbe-rv7a-80e78-5e3be6"}, {"t": "pt", "text": "IAS 2 requires production overheads in inventory", "id": "acfbe-rv7a-80e78-fdd7d0"}], "id": "acfbe-rv7a-80e78"}], "source": "BPP Workbook ch 7a: sections 1-8 pp236-259", "summary": "Absorption costing: allocation, apportionment (bases, service cost centre reapportionment by direct, step-down and reciprocal methods), absorption rates, blanket vs departmental rates and under/over absorption.", "id": "acfbe-rv7a", "updated": "2026-11-12"}, {"num": "7b", "title": "Absorption and Marginal Costing", "pages": [263, 276], "syllabus": "C3", "status": "published", "branches": [{"kind": "concept", "title": "Marginal costing", "page": [264, 267], "items": [{"t": "def", "k": 1, "term": "Marginal cost", "text": "The variable cost of one unit of product or service", "id": "acfbe-rv7b-d19c6-f9dcbc"}, {"t": "def", "k": 1, "term": "Marginal costing", "text": "An alternative to absorption costing: only variable costs are charged to cost units; fixed costs of the period are written off in full against contribution", "id": "acfbe-rv7b-d19c6-9dce17"}, {"t": "def", "k": 1, "term": "Contribution", "text": "Sales value minus variable cost of sales - a contribution towards fixed costs and then profit", "id": "acfbe-rv7b-d19c6-74b6b3"}, {"t": "pt", "text": "Principles: period fixed costs are the same whatever the volume; each extra unit sold adds its contribution to profit; closing inventory valued at variable production cost", "id": "acfbe-rv7b-d19c6-3df8c2"}, {"t": "pt", "text": "Contribution information shows how profit changes with volume - useful for decisions", "id": "acfbe-rv7b-d19c6-0ab1a0"}], "id": "acfbe-rv7b-d19c6"}, {"kind": "compare", "title": "Marginal vs absorption costing", "page": [267, 273], "items": [{"t": "table", "rows": [["Feature", "Marginal costing", "Absorption costing"], ["Fixed production overhead", "Period cost - written off as incurred", "Product cost - absorbed into units"], ["Inventory valued at", "Variable production cost", "Full production cost (variable + fixed)"], ["Key profit measure", "Contribution", "Gross profit"], ["Use", "Planning and decision making", "Routine profit reporting; required for financial accounts (IAS 2)"], ["Profit when inventory rises", "Lower", "Higher"]], "id": "acfbe-rv7b-5e023-d271cd"}, {"t": "pt", "k": 1, "text": "No change in inventory -> both methods give the SAME profit", "id": "acfbe-rv7b-5e023-4c4d65"}, {"t": "pt", "k": 1, "text": "Inventory INCREASES (production > sales) -> absorption profit is HIGHER (fixed overhead carried forward in inventory)", "id": "acfbe-rv7b-5e023-c6ca04"}, {"t": "pt", "k": 1, "text": "Inventory DECREASES (sales > production) -> marginal profit is HIGHER", "id": "acfbe-rv7b-5e023-308918"}, {"t": "pt", "text": "Arguments for absorption: complies with IAS 2, 'fair' to share fixed production costs, avoids fictitious losses when building inventory", "id": "acfbe-rv7b-5e023-fb15df"}, {"t": "pt", "text": "Arguments for marginal: simple, no under/over absorption, contribution aids decisions, profit cannot be manipulated by building inventory", "id": "acfbe-rv7b-5e023-bc54fa"}], "id": "acfbe-rv7b-5e023"}, {"kind": "formula", "title": "Reconciling the profits", "page": [270, 272], "items": [{"t": "f", "k": 1, "term": "Profit difference", "text": "Change in inventory (units) x Fixed overhead absorption rate per unit", "vars": "inventory up -> absorption profit higher; inventory down -> marginal profit higher", "eg": "Inventory 100 -> 150 units, OAR $1.25: difference = 50 x 1.25 = $62.50", "id": "acfbe-rv7b-b33ba-8ddd6f"}, {"t": "f", "term": "Change in inventory from profits", "text": "Difference in profit / Fixed production cost per unit", "vars": "Absorption profit $2,000, marginal loss $3,000, fixed cost $2/unit: 5,000/2 = 2,500 units increase; sales 10,000 -> production 12,500", "id": "acfbe-rv7b-b33ba-ab4832"}, {"t": "f", "term": "Closing inventory", "text": "Opening inventory + Production - Sales", "vars": "in units", "id": "acfbe-rv7b-b33ba-242ec6"}, {"t": "exam", "text": "Don't overlook the possibility of a LOSS rather than a profit under one method", "id": "acfbe-rv7b-b33ba-68c082"}, {"t": "exam", "text": "Expect questions requiring profit or loss under both methods", "id": "acfbe-rv7b-b33ba-d04346"}], "id": "acfbe-rv7b-b33ba"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Valuing closing inventory at full cost under marginal costing - use variable production cost only", "id": "acfbe-rv7b-6483a-fde962"}, {"t": "x", "text": "Treating fixed selling or administration overhead as absorbed into inventory - only fixed PRODUCTION overhead is", "id": "acfbe-rv7b-6483a-4dba50"}, {"t": "x", "text": "Reversing the reconciliation direction - rising inventory gives higher ABSORPTION profit", "id": "acfbe-rv7b-6483a-254c40"}, {"t": "x", "text": "Using the budgeted fixed cost per unit of SALES rather than the absorption rate per unit of production", "id": "acfbe-rv7b-6483a-7d9f87"}], "id": "acfbe-rv7b-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Marginal cost = variable cost of one unit", "id": "acfbe-rv7b-80e78-56fdb4"}, {"t": "pt", "text": "Contribution = sales - variable costs", "id": "acfbe-rv7b-80e78-a00567"}, {"t": "pt", "text": "Marginal costing: fixed production overhead is a period cost", "id": "acfbe-rv7b-80e78-351d91"}, {"t": "pt", "text": "Absorption costing: fixed production overhead is in inventory", "id": "acfbe-rv7b-80e78-d8d13f"}, {"t": "pt", "text": "Same profit when inventory does not change", "id": "acfbe-rv7b-80e78-17bb2e"}, {"t": "pt", "text": "Inventory up: absorption profit higher", "id": "acfbe-rv7b-80e78-86fa89"}, {"t": "pt", "text": "Inventory down: marginal profit higher", "id": "acfbe-rv7b-80e78-498b9b"}, {"t": "pt", "text": "Difference = change in inventory units x fixed OAR per unit", "id": "acfbe-rv7b-80e78-5316fd"}, {"t": "pt", "text": "Closing inventory = opening + production - sales", "id": "acfbe-rv7b-80e78-39b8ef"}, {"t": "pt", "text": "Absorption required for financial reporting (IAS 2)", "id": "acfbe-rv7b-80e78-8127d0"}, {"t": "pt", "text": "Marginal costing is better for decisions", "id": "acfbe-rv7b-80e78-833b50"}, {"t": "pt", "text": "Watch for losses under one method", "id": "acfbe-rv7b-80e78-845e36"}], "id": "acfbe-rv7b-80e78"}], "source": "BPP Workbook ch 7b: sections 1-5 pp264-273", "summary": "Marginal cost and contribution, the principles of marginal costing, profit under marginal vs absorption costing, reconciling the two profits and the arguments for each method.", "id": "acfbe-rv7b", "updated": "2026-11-12"}, {"num": "8a", "title": "Process Costing", "pages": [277, 306], "syllabus": "C4", "status": "published", "branches": [{"kind": "concept", "title": "Process costing basics", "page": [278, 280], "items": [{"t": "def", "k": 1, "term": "Process costing", "text": "A costing method used where it is not possible to identify separate units of production (eg chemicals, oil, food), usually because of the continuous nature of production", "id": "acfbe-rv8a-92f93-f4acdc"}, {"t": "pt", "text": "Features: the output of one process is the input to the next; output is homogeneous; costs collected per process; losses and WIP are common", "id": "acfbe-rv8a-92f93-66a000"}, {"t": "pt", "k": 1, "text": "Four-step framework: 1 determine output and losses (expected output, normal/abnormal loss or gain, equivalent units) -> 2 calculate cost per unit -> 3 calculate total cost of output, losses and WIP -> 4 complete the accounts", "id": "acfbe-rv8a-92f93-802c41"}, {"t": "exam", "text": "Expect several process costing questions - shorter than textbook examples", "id": "acfbe-rv8a-92f93-796588"}], "id": "acfbe-rv8a-92f93"}, {"kind": "rule", "title": "Losses and gains", "page": [280, 292], "items": [{"t": "def", "k": 1, "term": "Normal loss", "text": "The loss expected during a process - it is NOT given a cost (valued at scrap value, if any)", "id": "acfbe-rv8a-1fdfe-7847f6"}, {"t": "def", "k": 1, "term": "Abnormal loss", "text": "Actual loss GREATER than normal loss - it IS given a cost (same cost per unit as good output)", "id": "acfbe-rv8a-1fdfe-c62f25"}, {"t": "def", "k": 1, "term": "Abnormal gain", "text": "Actual loss LESS than normal loss - valued at the same cost per unit as good output", "id": "acfbe-rv8a-1fdfe-1240a6"}, {"t": "f", "k": 1, "term": "Cost per expected unit", "text": "(Process costs - Scrap value of normal loss) / Expected output", "vars": "expected output = input - normal loss", "eg": "Input 1,000 units, $4,500, normal loss 10% (no scrap): $4,500 / 900 = $5 per unit", "id": "acfbe-rv8a-1fdfe-b0643a"}, {"t": "pt", "text": "Scrap: 'discarded material having some value' - scrap value of NORMAL loss is credited to the process account (reducing cost per unit)", "id": "acfbe-rv8a-1fdfe-06ea20"}, {"t": "pt", "k": 1, "text": "Abnormal loss account: Dr with abnormal loss at full cost; Cr with scrap value of abnormal loss; balance (net cost) to profit or loss", "id": "acfbe-rv8a-1fdfe-9f2939"}, {"t": "pt", "text": "Abnormal gain account: Cr at full cost; Dr with the scrap value forgone (normal loss not lost); net gain to profit or loss", "id": "acfbe-rv8a-1fdfe-ff261f"}, {"t": "pt", "text": "Disposal cost: the cost of disposing of normal loss is ADDED to process costs; abnormal loss disposal cost goes to the abnormal loss account", "id": "acfbe-rv8a-1fdfe-384cb4"}, {"t": "exam", "text": "When abnormal losses can be sold for scrap, their net cost = cost per unit less scrap revenue", "id": "acfbe-rv8a-1fdfe-940e56"}], "id": "acfbe-rv8a-1fdfe"}, {"kind": "formula", "title": "Closing work in progress", "page": [292, 295], "items": [{"t": "def", "k": 1, "term": "Equivalent units", "text": "Notional whole units representing incomplete work, used to apportion costs between finished output and work in progress", "id": "acfbe-rv8a-0dc3a-c16e71"}, {"t": "f", "term": "Equivalent units of WIP", "text": "Number of WIP units x % complete", "vars": "calculated separately for each cost element (materials, labour, overhead)", "eg": "300 units 50% complete for conversion = 150 EU", "id": "acfbe-rv8a-0dc3a-5d2ca7"}, {"t": "f", "term": "Cost per equivalent unit", "text": "Cost of the element / Total equivalent units for that element", "vars": "total EU = completed units + WIP EU", "eg": "Columbine Co: total cost per unit $4.00", "id": "acfbe-rv8a-0dc3a-b548ba"}, {"t": "pt", "text": "Materials are often 100% complete at the start; conversion costs (labour, overhead) partly complete", "id": "acfbe-rv8a-0dc3a-926129"}, {"t": "exam", "text": "The Study Guide states that losses and work in progress in the SAME process will not be examined", "id": "acfbe-rv8a-0dc3a-4c191a"}], "id": "acfbe-rv8a-0dc3a"}, {"kind": "compare", "title": "Opening WIP: FIFO vs weighted average", "page": [296, 303], "items": [{"t": "table", "rows": [["Point", "FIFO", "Weighted average"], ["Assumption", "Opening WIP is completed first", "Opening WIP costs are averaged with the period's costs"], ["Equivalent units for this period", "Work to complete opening WIP + units started and finished + closing WIP", "All completed units + closing WIP EU"], ["Costs used", "Only costs incurred THIS period", "Opening WIP value + this period's costs"], ["Cost per unit reflects", "Current period efficiency", "A blend of periods"]], "id": "acfbe-rv8a-5aebb-ae8fea"}, {"t": "pt", "k": 1, "text": "Under FIFO, finished output = opening WIP (its b/f value + cost to complete) + fully worked units", "id": "acfbe-rv8a-5aebb-38acd0"}, {"t": "pt", "text": "If degrees of completion of opening WIP for each cost element are given, FIFO is usually expected; if not given, use weighted average", "id": "acfbe-rv8a-5aebb-8075a1"}, {"t": "exam", "text": "Read ACCA's technical article on process costing", "id": "acfbe-rv8a-5aebb-53e200"}], "id": "acfbe-rv8a-5aebb"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Giving normal loss a share of process cost - it is valued only at scrap value", "id": "acfbe-rv8a-6483a-a16939"}, {"t": "x", "text": "Dividing by actual output instead of EXPECTED output when finding cost per unit", "id": "acfbe-rv8a-6483a-da8d14"}, {"t": "x", "text": "Crediting the scrap value of abnormal loss to the process account - it goes to the abnormal loss account", "id": "acfbe-rv8a-6483a-544591"}, {"t": "x", "text": "Using one equivalent-unit figure for all cost elements when completion differs", "id": "acfbe-rv8a-6483a-a696bb"}, {"t": "x", "text": "Including opening WIP costs in the FIFO cost per equivalent unit", "id": "acfbe-rv8a-6483a-8fab77"}], "id": "acfbe-rv8a-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Process costing: continuous, homogeneous output", "id": "acfbe-rv8a-80e78-e5a15b"}, {"t": "pt", "text": "Steps: output and losses, cost per unit, total costs, accounts", "id": "acfbe-rv8a-80e78-03506c"}, {"t": "pt", "text": "Normal loss: expected, no cost, valued at scrap value", "id": "acfbe-rv8a-80e78-0939e3"}, {"t": "pt", "text": "Abnormal loss/gain: valued at full cost per unit", "id": "acfbe-rv8a-80e78-a2b08d"}, {"t": "pt", "text": "Cost per unit = (costs - scrap of normal loss) / expected output", "id": "acfbe-rv8a-80e78-45ceb6"}, {"t": "pt", "text": "Expected output = input - normal loss", "id": "acfbe-rv8a-80e78-9a7fc9"}, {"t": "pt", "text": "Scrap of normal loss credited to the process account", "id": "acfbe-rv8a-80e78-9a0144"}, {"t": "pt", "text": "Abnormal loss net cost goes to profit or loss", "id": "acfbe-rv8a-80e78-7b9a2e"}, {"t": "pt", "text": "Equivalent units = units x % complete, per cost element", "id": "acfbe-rv8a-80e78-07b151"}, {"t": "pt", "text": "Cost per EU = cost / total EU", "id": "acfbe-rv8a-80e78-dd26a8"}, {"t": "pt", "text": "FIFO: this period's costs only; opening WIP finished first", "id": "acfbe-rv8a-80e78-5d1972"}, {"t": "pt", "text": "Weighted average: opening WIP + period costs averaged", "id": "acfbe-rv8a-80e78-3a8c62"}], "id": "acfbe-rv8a-80e78"}], "source": "BPP Workbook ch 8a: sections 1-7 pp278-303", "summary": "Features of process costing, the four-step framework, normal and abnormal losses and gains, scrap value and disposal costs, equivalent units for closing WIP, and FIFO vs weighted average for opening WIP.", "id": "acfbe-rv8a", "updated": "2026-11-12"}, {"num": "8b", "title": "Process Costing, Joint Products and By-Products", "pages": [307, 320], "syllabus": "C4", "status": "published", "branches": [{"kind": "compare", "title": "Joint products vs by-products", "page": [308, 309], "items": [{"t": "table", "rows": [["Feature", "Joint products", "By-products"], ["Definition", "Two or more products separated in a process, EACH of significant value", "A product with some, but relatively little, value compared with the main product(s)"], ["Joint costs", "Apportioned between them", "Usually not apportioned"], ["Accounting", "Separate cost and profit for each", "Net realisable value usually deducted from the main product's cost"]], "id": "acfbe-rv8b-05bd9-27d946"}, {"t": "def", "k": 1, "term": "Split-off point", "text": "The point in a process at which joint products and by-products become separately identifiable", "id": "acfbe-rv8b-05bd9-1c3684"}, {"t": "pt", "text": "Costs incurred before split-off are joint (common) costs; costs after split-off are further processing costs of a specific product", "id": "acfbe-rv8b-05bd9-6257ea"}, {"t": "pt", "text": "Common costs must be shared to value closing inventory of each product, record the cost and profit of each, and perhaps assist pricing", "id": "acfbe-rv8b-05bd9-a3ebb2"}, {"t": "eg", "text": "Oil refining: petrol, naphtha, kerosene share the common refining cost", "id": "acfbe-rv8b-05bd9-51a62c"}, {"t": "exam", "text": "The Study Guide requires you to distinguish between joint products and by-products", "id": "acfbe-rv8b-05bd9-152a37"}], "id": "acfbe-rv8b-05bd9"}, {"kind": "formula", "title": "Apportioning joint costs", "page": [309, 314], "items": [{"t": "f", "k": 1, "term": "Physical measurement method", "text": "Joint cost x (Units (or weight/volume) of product / Total units of all joint products)", "vars": "uses output quantity at split-off", "eg": "Dolly is 10,000 of 20,000 good units: 50% of $330,000 = $165,000", "id": "acfbe-rv8b-dd5ad-4a99d2"}, {"t": "f", "k": 1, "term": "Sales value at split-off method", "text": "Joint cost x (Sales value of product's PRODUCTION at split-off / Total sales value of all joint products' production)", "vars": "the most widely used method", "eg": "products with higher value bear more cost", "id": "acfbe-rv8b-dd5ad-a4b193"}, {"t": "pt", "text": "Physical measurement is unsuitable where products are measured in different units or have very different values - it can make a product look loss-making", "id": "acfbe-rv8b-dd5ad-244b9a"}, {"t": "exam", "text": "Apportion on the sales value of PRODUCTION, not of sales and not on individual selling prices", "id": "acfbe-rv8b-dd5ad-9ccadc"}, {"t": "pt", "text": "Process account: joint products appear as separate output lines, each at its apportioned cost", "id": "acfbe-rv8b-dd5ad-19ade1"}], "id": "acfbe-rv8b-dd5ad"}, {"kind": "process", "title": "Accounting for by-products", "page": [315, 318], "items": [{"t": "pt", "k": 1, "text": "Most common method: deduct the net realisable value (NRV) of the by-product from the cost of the main products (reduces joint costs)", "id": "acfbe-rv8b-dbff2-1f674e"}, {"t": "pt", "text": "Other treatments", "kids": [{"t": "pt", "text": "Add by-product income (net of further processing/selling costs) to sales of the main product", "id": "acfbe-rv8b-dbff2-dfaf20"}, {"t": "pt", "text": "Treat by-product sales as a separate incidental source of income", "id": "acfbe-rv8b-dbff2-338f53"}, {"t": "pt", "text": "Treat by-product sales as a reduction in the cost of goods sold", "id": "acfbe-rv8b-dbff2-2f5285"}], "id": "acfbe-rv8b-dbff2-9a6bdc"}, {"t": "pt", "text": "NRV = sales value - further processing and selling costs after split-off", "id": "acfbe-rv8b-dbff2-af59f5"}, {"t": "pt", "text": "Closing inventory of joint products = (production units - sales units) x production cost per unit", "id": "acfbe-rv8b-dbff2-5c8e42"}], "id": "acfbe-rv8b-dbff2"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Apportioning joint costs on units SOLD - use units (or sales value) of PRODUCTION", "id": "acfbe-rv8b-6483a-d8665d"}, {"t": "x", "text": "Apportioning joint costs to a by-product - its NRV is normally deducted from joint costs instead", "id": "acfbe-rv8b-6483a-24acfd"}, {"t": "x", "text": "Including post-separation costs in the joint cost to be apportioned", "id": "acfbe-rv8b-6483a-516f46"}, {"t": "x", "text": "Forgetting to deduct further processing and selling costs when calculating a by-product's NRV", "id": "acfbe-rv8b-6483a-7b495c"}], "id": "acfbe-rv8b-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Joint products: each of significant value", "id": "acfbe-rv8b-80e78-6ad1e4"}, {"t": "pt", "text": "By-product: relatively small value", "id": "acfbe-rv8b-80e78-f53701"}, {"t": "pt", "text": "Split-off point: products become separately identifiable", "id": "acfbe-rv8b-80e78-27c37d"}, {"t": "pt", "text": "Joint costs arise before split-off", "id": "acfbe-rv8b-80e78-b0b07b"}, {"t": "pt", "text": "Physical measurement: share by units/weight/volume", "id": "acfbe-rv8b-80e78-74e7c2"}, {"t": "pt", "text": "Sales value at split-off: share by sales value of production", "id": "acfbe-rv8b-80e78-3de2ba"}, {"t": "pt", "text": "Sales value method is the most widely used", "id": "acfbe-rv8b-80e78-39244f"}, {"t": "pt", "text": "Use production, not sales, figures", "id": "acfbe-rv8b-80e78-010a04"}, {"t": "pt", "text": "By-product NRV usually deducted from main product cost", "id": "acfbe-rv8b-80e78-d6fec6"}, {"t": "pt", "text": "NRV = sales value - further costs after split-off", "id": "acfbe-rv8b-80e78-2ff39f"}, {"t": "pt", "text": "Further processing costs are product-specific", "id": "acfbe-rv8b-80e78-49341f"}, {"t": "pt", "text": "Joint cost apportionment values inventory and profit", "id": "acfbe-rv8b-80e78-f5ae26"}], "id": "acfbe-rv8b-80e78"}], "source": "BPP Workbook ch 8b: sections 1-4 pp308-318", "summary": "Joint products vs by-products, the split-off point, apportioning common (joint) costs by physical measurement and by sales value at split-off, joint products in process accounts, and accounting for by-products.", "id": "acfbe-rv8b", "updated": "2026-11-12"}, {"num": "9a", "title": "Job, Batch and Service Costing", "pages": [321, 342], "syllabus": "C4", "status": "published", "branches": [{"kind": "concept", "title": "Job costing", "page": [322, 330], "items": [{"t": "def", "k": 1, "term": "Job costing", "text": "A costing method applied where work is undertaken to customers' special requirements and each order is of comparatively short duration", "id": "acfbe-rv9a-c040f-15416c"}, {"t": "pt", "text": "Each job is a separately identifiable cost unit; costs collected on a job cost sheet/card", "id": "acfbe-rv9a-c040f-706eb0"}, {"t": "pt", "text": "Sources: direct materials from materials requisition notes (bill of materials for estimates); direct labour from job/time cards; direct expenses from invoices; production overheads absorbed at the predetermined rate", "id": "acfbe-rv9a-c040f-2cae85"}, {"t": "pt", "text": "Non-production overheads (admin, selling, distribution) may be added as a % of production cost to reach total cost", "id": "acfbe-rv9a-c040f-30074e"}, {"t": "pt", "k": 1, "text": "Rectification costs: if caused by an exceptional event, charge to the job; if normal/expected, treat as production overhead", "id": "acfbe-rv9a-c040f-c688b4"}, {"t": "pt", "text": "Closing WIP = the sum of costs incurred on incomplete jobs", "id": "acfbe-rv9a-c040f-bd1d65"}, {"t": "pt", "text": "Job costing can also control the costs of internal services (eg maintenance jobs)", "id": "acfbe-rv9a-c040f-809950"}, {"t": "exam", "text": "A question may ask you to accumulate costs to a job cost and then work out the selling price", "id": "acfbe-rv9a-c040f-cd074f"}], "id": "acfbe-rv9a-c040f"}, {"kind": "formula", "title": "Margins and mark-ups", "page": [325, 327], "items": [{"t": "f", "k": 1, "term": "Selling price from a margin", "text": "Unit cost / (1 - margin %)", "vars": "margin = profit as a % of SELLING PRICE", "eg": "Cost $150, margin 20%: $150 / 0.80 = $187.50", "id": "acfbe-rv9a-ba1ba-51f0a6"}, {"t": "f", "k": 1, "term": "Selling price from a mark-up", "text": "Unit cost x (1 + mark-up %)", "vars": "mark-up = profit as a % of COST", "eg": "Cost $650, mark-up 20%: $650 x 1.20 = $780", "id": "acfbe-rv9a-ba1ba-fd15fa"}, {"t": "f", "term": "Cost from price and mark-up", "text": "Selling price / (1 + mark-up %)", "vars": "reverse the mark-up", "eg": "Price $935, mark-up 10%: $935 / 1.10 = $850", "id": "acfbe-rv9a-ba1ba-a28254"}, {"t": "pt", "text": "Cost plus pricing is the usual pricing method in jobbing concerns", "id": "acfbe-rv9a-ba1ba-969c37"}, {"t": "x", "text": "A 20% margin is NOT the same as a 20% mark-up", "id": "acfbe-rv9a-ba1ba-3c1428"}], "id": "acfbe-rv9a-ba1ba"}, {"kind": "concept", "title": "Batch costing", "page": [331, 332], "items": [{"t": "def", "k": 1, "term": "Batch costing", "text": "Similar to job costing: each batch of similar articles is separately identifiable and costed as a job", "id": "acfbe-rv9a-4d0fb-09246a"}, {"t": "f", "term": "Cost per unit in a batch", "text": "Total batch cost / Number of units in the batch", "vars": "used to value inventory and set prices", "id": "acfbe-rv9a-4d0fb-ba8892"}, {"t": "pt", "text": "Used for production of identical items in groups (eg shoes, pharmaceuticals, components)", "id": "acfbe-rv9a-4d0fb-64c660"}], "id": "acfbe-rv9a-4d0fb"}, {"kind": "concept", "title": "Service costing", "page": [332, 338], "items": [{"t": "def", "k": 1, "term": "Service costing", "text": "Costing used in service industries or for internal services (canteens, maintenance, transport) where the output is a service, not a product", "id": "acfbe-rv9a-1000d-3d6f0a"}, {"t": "pt", "text": "Differences from product costing: direct material cost is often small; indirect costs are a high proportion; output is hard to define", "id": "acfbe-rv9a-1000d-b73184"}, {"t": "pt", "k": 1, "text": "Characteristics of services: simultaneity (produced and consumed together) • intangibility • perishability (cannot be stored) • heterogeneity (variable quality)", "id": "acfbe-rv9a-1000d-157a4b"}, {"t": "pt", "k": 1, "text": "The main problem is defining a realistic cost unit - often a COMPOSITE cost unit (two measures)", "id": "acfbe-rv9a-1000d-c1040c"}, {"t": "f", "term": "Cost per service unit", "text": "Total costs for the period / Number of service units supplied in the period", "vars": "formula to learn", "eg": "Transport: total cost / tonne-kilometres = eg $1.50 per tonne-km", "id": "acfbe-rv9a-1000d-22d1be"}, {"t": "pt", "text": "Composite cost unit examples: tonne-kilometre (haulage), passenger-kilometre (bus), patient-day (hospital), room-night (hotel), meals served (canteen), student-hour (education)", "id": "acfbe-rv9a-1000d-9dfb67"}, {"t": "pt", "text": "Purposes: control costs, set charges (eg transfer charges to user departments), compare internal provision with outside suppliers, encourage efficient use", "id": "acfbe-rv9a-1000d-71e89e"}], "id": "acfbe-rv9a-1000d"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing margin (on selling price) with mark-up (on cost)", "id": "acfbe-rv9a-6483a-e17510"}, {"t": "x", "text": "Charging normal rectification costs to the specific job - they are production overheads", "id": "acfbe-rv9a-6483a-b15a0d"}, {"t": "x", "text": "Using a single measure (eg km) when a composite unit (tonne-km) reflects the service better", "id": "acfbe-rv9a-6483a-82b360"}, {"t": "x", "text": "Forgetting that services cannot be stored, so capacity cannot be built up as inventory", "id": "acfbe-rv9a-6483a-abb54c"}], "id": "acfbe-rv9a-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Job costing: customer's special requirements, short duration", "id": "acfbe-rv9a-80e78-185981"}, {"t": "pt", "text": "Job cost sheet collects material, labour, expenses, overheads", "id": "acfbe-rv9a-80e78-aa0a36"}, {"t": "pt", "text": "Abnormal rectification -> job; normal rectification -> overhead", "id": "acfbe-rv9a-80e78-aa6dff"}, {"t": "pt", "text": "WIP = costs on incomplete jobs", "id": "acfbe-rv9a-80e78-6bd41e"}, {"t": "pt", "text": "Price from margin: cost / (1 - margin)", "id": "acfbe-rv9a-80e78-5e139f"}, {"t": "pt", "text": "Price from mark-up: cost x (1 + mark-up)", "id": "acfbe-rv9a-80e78-59ff1d"}, {"t": "pt", "text": "Batch costing: batch is the cost unit, then ÷ units", "id": "acfbe-rv9a-80e78-445f3a"}, {"t": "pt", "text": "Service costing for service industries and internal services", "id": "acfbe-rv9a-80e78-f0eecb"}, {"t": "pt", "text": "Services: simultaneity, intangibility, perishability, heterogeneity", "id": "acfbe-rv9a-80e78-4a7f18"}, {"t": "pt", "text": "Composite cost units: tonne-km, patient-day, passenger-km", "id": "acfbe-rv9a-80e78-3b573b"}, {"t": "pt", "text": "Cost per service unit = total cost / service units", "id": "acfbe-rv9a-80e78-ada303"}, {"t": "pt", "text": "Service costing helps control and charge internal services", "id": "acfbe-rv9a-80e78-f500fa"}], "id": "acfbe-rv9a-80e78"}], "source": "BPP Workbook ch 9a: sections 1-4 pp322-338", "summary": "Job costing (cost sheets, rectification, WIP, cost-plus pricing with margins and mark-ups), batch costing and service costing with composite cost units.", "id": "acfbe-rv9a", "updated": "2026-11-12"}, {"num": "9b", "title": "Alternative Costing Principles", "pages": [343, 362], "syllabus": "C5", "status": "published", "branches": [{"kind": "process", "title": "Activity based costing (ABC)", "page": [344, 348], "items": [{"t": "pt", "k": 1, "text": "Why ABC developed: overheads are now a large share of cost; many overheads relate to activities (set-ups, orders, inspections) not production volume; product ranges are more diverse", "id": "acfbe-rv9b-4c8a2-546d2b"}, {"t": "pt", "k": 1, "text": "ABC steps: 1 identify major activities -> 2 identify the cost driver for each activity -> 3 collect overheads into cost pools (one per activity) -> 4 calculate a cost driver rate -> 5 charge overheads to products using their use of each driver", "id": "acfbe-rv9b-4c8a2-828cfe"}, {"t": "def", "term": "Cost driver", "text": "The factor that causes the cost of an activity (eg number of set-ups, number of orders, number of inspections)", "id": "acfbe-rv9b-4c8a2-4a6c47"}, {"t": "f", "term": "Cost driver rate", "text": "Cost pool / Total number of cost driver units", "vars": "charged to products by their usage of the driver", "eg": "Set-up pool $40,000 / 100 set-ups = $400 per set-up", "id": "acfbe-rv9b-4c8a2-9e62c4"}, {"t": "pt", "k": 1, "text": "Volume-related costs still use volume drivers (labour or machine hours); support-activity costs use transaction drivers", "id": "acfbe-rv9b-4c8a2-a7c0bd"}, {"t": "pt", "text": "ABC typically shows low-volume, complex products cost MORE (and high-volume products less) than traditional absorption suggests", "id": "acfbe-rv9b-4c8a2-5f5395"}, {"t": "exam", "text": "The Study Guide says you will NOT be required to calculate ABC costs - understand the method and merits", "id": "acfbe-rv9b-4c8a2-fd917b"}], "id": "acfbe-rv9b-4c8a2"}, {"kind": "compare", "title": "ABC vs traditional absorption", "page": [349, 350], "items": [{"t": "table", "rows": [["Point", "Traditional absorption", "ABC"], ["Overhead collection", "Production departments (cost centres)", "Activities (cost pools)"], ["Absorption basis", "Usually one volume-related rate (labour or machine hours)", "Several cost drivers, many transaction-based"], ["Accuracy", "Can distort costs of low-volume or complex products", "More realistic product costs"]], "id": "acfbe-rv9b-feb48-dd0fed"}, {"t": "pt", "text": "Merits of ABC: better cost understanding, better pricing and product mix decisions, cost reduction by managing drivers", "id": "acfbe-rv9b-feb48-4a70fe"}, {"t": "pt", "text": "Criticisms: some arbitrary apportionment remains (eg rent), more than one cost driver may cause a cost, cost and complexity of the system, may be unnecessary when overheads are small", "id": "acfbe-rv9b-feb48-63d3de"}], "id": "acfbe-rv9b-feb48"}, {"kind": "concept", "title": "Quality and TQM", "page": [351, 353], "items": [{"t": "pt", "k": 1, "text": "Costs of quality: prevention costs • appraisal costs • internal failure costs • external failure costs", "kids": [{"t": "pt", "text": "Prevention: training, quality planning, design reviews", "id": "acfbe-rv9b-09001-c18b3f"}, {"t": "pt", "text": "Appraisal: inspection, testing, audits", "id": "acfbe-rv9b-09001-7ba708"}, {"t": "pt", "text": "Internal failure: scrap, rework, downtime - found BEFORE delivery", "id": "acfbe-rv9b-09001-1043cb"}, {"t": "pt", "text": "External failure: warranty claims, returns, lost goodwill - found AFTER delivery", "id": "acfbe-rv9b-09001-ea3dbe"}], "id": "acfbe-rv9b-09001-e36e42"}, {"t": "pt", "text": "Conformance costs = prevention + appraisal; non-conformance costs = internal + external failure", "id": "acfbe-rv9b-09001-ccbebe"}, {"t": "def", "k": 1, "term": "Total quality management (TQM)", "text": "Applying a zero defect philosophy to the management of all resources and relationships within the organisation to achieve excellence", "id": "acfbe-rv9b-09001-ee031d"}, {"t": "pt", "k": 1, "text": "TQM principles: get it right first time (prevention is cheaper than correction) • continuous improvement (dissatisfaction with the status quo)", "id": "acfbe-rv9b-09001-79b8a7"}, {"t": "pt", "text": "Performance measures for TQM must cover every activity, including non-financial measures", "id": "acfbe-rv9b-09001-a5d614"}], "id": "acfbe-rv9b-09001"}, {"kind": "concept", "title": "Life cycle costing", "page": [354, 355], "items": [{"t": "def", "k": 1, "term": "Life cycle costing", "text": "Tracking and accumulating costs and revenues attributable to each product over its entire life cycle", "id": "acfbe-rv9b-c17a6-7fd4ce"}, {"t": "pt", "text": "Life cycle costs run from design and development, through production and marketing, to decommissioning/disposal", "id": "acfbe-rv9b-c17a6-b5da22"}, {"t": "pt", "text": "Traditional systems relate costs to periods, hiding pre-production (R&D, design) and post-production costs", "id": "acfbe-rv9b-c17a6-be811b"}, {"t": "pt", "text": "Value: most costs are committed at the design stage - life cycle costing focuses attention there and shows each product's full profitability", "id": "acfbe-rv9b-c17a6-3a3540"}], "id": "acfbe-rv9b-c17a6"}, {"kind": "process", "title": "Target costing", "page": [356, 357], "items": [{"t": "def", "k": 1, "term": "Target costing", "text": "Setting a target cost by subtracting a desired profit margin from a competitive market price", "id": "acfbe-rv9b-f92a0-9f457b"}, {"t": "pt", "text": "Steps: determine the market price (target selling price) -> deduct target profit -> target cost -> estimate the actual cost -> find the cost gap -> close the gap (design changes, value engineering, cheaper materials, negotiate with suppliers and customers)", "id": "acfbe-rv9b-f92a0-3ca97f"}, {"t": "f", "k": 1, "term": "Target cost", "text": "Target selling price - Target profit", "vars": "price set by the market; profit by the company", "eg": "Price $50, required margin 20%: target cost = $40", "id": "acfbe-rv9b-f92a0-fa2acb"}, {"t": "f", "k": 1, "term": "Cost gap", "text": "Estimated cost - Target cost", "vars": "must be closed before launch or the product is reconsidered", "eg": "Estimated $46 vs target $40 = $6 gap", "id": "acfbe-rv9b-f92a0-598ee7"}, {"t": "pt", "text": "Most effective at the design stage, before costs are committed", "id": "acfbe-rv9b-f92a0-6848bc"}], "id": "acfbe-rv9b-f92a0"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Thinking ABC eliminates all arbitrary apportionment - facility costs like rent remain arbitrary", "id": "acfbe-rv9b-6483a-8f0fd8"}, {"t": "x", "text": "Classifying inspection costs as prevention - they are appraisal costs", "id": "acfbe-rv9b-6483a-358d6f"}, {"t": "x", "text": "Treating rework found before delivery as an external failure cost - it is internal", "id": "acfbe-rv9b-6483a-312636"}, {"t": "x", "text": "Calculating target cost as estimated cost minus profit - it is market PRICE minus target profit", "id": "acfbe-rv9b-6483a-e17b2a"}], "id": "acfbe-rv9b-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "ABC: activities, cost drivers, cost pools, driver rates", "id": "acfbe-rv9b-80e78-eb3f17"}, {"t": "pt", "text": "Cost driver = factor that causes an activity's cost", "id": "acfbe-rv9b-80e78-26941b"}, {"t": "pt", "text": "ABC shows low-volume complex products cost more", "id": "acfbe-rv9b-80e78-f259d6"}, {"t": "pt", "text": "No ABC calculations required in the exam", "id": "acfbe-rv9b-80e78-5ae6ae"}, {"t": "pt", "text": "Quality costs: prevention, appraisal, internal failure, external failure", "id": "acfbe-rv9b-80e78-6ab08b"}, {"t": "pt", "text": "Conformance = prevention + appraisal", "id": "acfbe-rv9b-80e78-b71446"}, {"t": "pt", "text": "TQM: zero defects, right first time, continuous improvement", "id": "acfbe-rv9b-80e78-c0a504"}, {"t": "pt", "text": "Life cycle costing: costs and revenues over the whole life", "id": "acfbe-rv9b-80e78-dc2f39"}, {"t": "pt", "text": "Most life cycle costs are committed at design", "id": "acfbe-rv9b-80e78-8f2b46"}, {"t": "pt", "text": "Target cost = target price - target profit", "id": "acfbe-rv9b-80e78-2facac"}, {"t": "pt", "text": "Cost gap = estimated cost - target cost", "id": "acfbe-rv9b-80e78-1df8c3"}, {"t": "pt", "text": "Close the gap at the design stage", "id": "acfbe-rv9b-80e78-ea1636"}], "id": "acfbe-rv9b-80e78"}], "source": "BPP Workbook ch 9b: sections 1-7 pp344-357", "summary": "Activity based costing, ABC vs traditional absorption costing, costs of quality and TQM, life cycle costing and target costing.", "id": "acfbe-rv9b", "updated": "2026-11-12"}, {"num": "10a", "title": "Budgeting", "pages": [363, 392], "syllabus": "D1, D2", "status": "published", "branches": [{"kind": "process", "title": "The planning and control cycle", "page": [364, 367], "items": [{"t": "pt", "k": 1, "text": "Seven steps: 1 identify objectives -> 2 identify potential strategies -> 3 evaluate strategies -> 4 choose alternative courses of action -> 5 implement the long-term plan (via annual budgets) -> 6 measure actual results and compare with the plan -> 7 respond to divergences from the plan", "id": "acfbe-rv10a-772e3-2375c8"}, {"t": "pt", "text": "Steps 1-5 are planning; steps 6-7 are control", "id": "acfbe-rv10a-772e3-76a68c"}, {"t": "def", "k": 1, "term": "Budget", "text": "A quantified plan of action for a forthcoming accounting period", "id": "acfbe-rv10a-772e3-758fa2"}, {"t": "pt", "text": "Purposes of budgets: ensure objectives are achieved, compel planning, communicate, co-ordinate, provide a framework for responsibility accounting, establish control, motivate", "id": "acfbe-rv10a-772e3-a2d463"}], "id": "acfbe-rv10a-772e3"}, {"kind": "concept", "title": "Responsibility centres and controllability", "page": [368, 372], "items": [{"t": "pt", "k": 1, "text": "Cost centre (costs), revenue centre (revenues), profit centre (costs and revenues), investment centre (profit and capital invested - measured by return on capital)", "id": "acfbe-rv10a-58a2c-b92e28"}, {"t": "def", "k": 1, "term": "Controllable cost", "text": "A cost which can be influenced by its budget holder", "id": "acfbe-rv10a-58a2c-df1ed9"}, {"t": "pt", "k": 1, "text": "Managers should only be held accountable for costs over which they have some influence (responsibility accounting)", "id": "acfbe-rv10a-58a2c-571e25"}, {"t": "pt", "text": "Fixed costs are often uncontrollable in the short term but may be controllable in the long term or by a higher manager", "id": "acfbe-rv10a-58a2c-cb4f51"}, {"t": "pt", "text": "Apportioned costs (eg share of head office rent) are usually NOT controllable by the receiving manager", "id": "acfbe-rv10a-58a2c-41d233"}], "id": "acfbe-rv10a-58a2c"}, {"kind": "compare", "title": "Fixed vs flexible budgets", "page": [372, 381], "items": [{"t": "table", "rows": [["Point", "Fixed budget", "Flexible budget"], ["Definition", "Unchanged regardless of the actual level of activity", "Recognises cost behaviour; designed to change as the volume of activity changes"], ["Prepared", "At the planned level of activity, before the period", "For several activity levels (planning) or flexed to the actual level (control)"], ["Use", "Planning, and control where activity is predictable or costs are fixed", "Meaningful control - compares like with like"]], "id": "acfbe-rv10a-21f0c-eb9307"}, {"t": "pt", "k": 1, "text": "A flexible budget uses marginal costing principles: variable costs flex with activity; fixed costs stay the same", "id": "acfbe-rv10a-21f0c-1f2ff1"}, {"t": "pt", "k": 1, "text": "Budgetary control variances should compare ACTUAL results with the FLEXED budget (same activity level)", "id": "acfbe-rv10a-21f0c-7b97b0"}, {"t": "pt", "text": "Semi-variable costs: split them with the high-low method before flexing", "id": "acfbe-rv10a-21f0c-15ce47"}, {"t": "f", "term": "Flexed cost", "text": "Fixed cost + (Variable cost per unit x Actual activity)", "vars": "fixed element unchanged", "eg": "Fixed $10,000 + $1.50 x 8,000 units = $22,000", "id": "acfbe-rv10a-21f0c-ee4b94"}, {"t": "eg", "text": "Maintenance: high 8,000 units $115,000, low 6,000 units $97,000 -> variable $9 per unit, fixed $43,000", "id": "acfbe-rv10a-21f0c-3b7f4f"}, {"t": "pt", "text": "Choice of activity measure: units for single products; standard hours or labour hours for mixed output", "id": "acfbe-rv10a-21f0c-0f4c68"}, {"t": "exam", "text": "Do not fall into the trap of flexing FIXED costs - they remain unchanged regardless of activity", "id": "acfbe-rv10a-21f0c-996c70"}, {"t": "exam", "text": "Flexible budgets are a key syllabus area - be able to explain why variances should be based on them", "id": "acfbe-rv10a-21f0c-d71e8a"}], "id": "acfbe-rv10a-21f0c"}, {"kind": "concept", "title": "Spreadsheets for budgeting", "page": [382, 387], "items": [{"t": "def", "k": 1, "term": "Spreadsheet", "text": "An electronic piece of paper divided into rows and columns; each intersection is a cell holding text, values or formulae", "id": "acfbe-rv10a-ac70c-0238a8"}, {"t": "pt", "text": "Formulae refer to other cells and always begin with '=' (eg =B6*0.175, =SUM(E6:E7)); parentheses change the order of operations", "id": "acfbe-rv10a-ac70c-2098cd"}, {"t": "pt", "text": "Uses: budgets, forecasts, what-if (sensitivity) analysis, cash flow forecasts, reports and charts", "id": "acfbe-rv10a-ac70c-6cbb18"}, {"t": "pt", "text": "Advantages: easy to learn, fast recalculation, what-if analysis, presentation", "id": "acfbe-rv10a-ac70c-5c47c4"}, {"t": "pt", "k": 1, "text": "Disadvantages: only as good as its original design (garbage in = garbage out); hidden formulae hide the logic; errors are easy to make and hard to spot; security and version control risks", "id": "acfbe-rv10a-ac70c-585153"}, {"t": "exam", "text": "Spreadsheet questions focus on features, formulae and issues", "id": "acfbe-rv10a-ac70c-9d6204"}], "id": "acfbe-rv10a-ac70c"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Flexing fixed costs in a flexible budget", "id": "acfbe-rv10a-6483a-8f21d7"}, {"t": "x", "text": "Comparing actual results with the original fixed budget when activity has changed", "id": "acfbe-rv10a-6483a-ab478e"}, {"t": "x", "text": "Holding a manager accountable for apportioned head office costs", "id": "acfbe-rv10a-6483a-01b296"}, {"t": "x", "text": "Assuming all fixed costs are uncontrollable at every level and in every time frame", "id": "acfbe-rv10a-6483a-79f49e"}], "id": "acfbe-rv10a-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Planning and control cycle: seven steps, planning then control", "id": "acfbe-rv10a-80e78-172bf0"}, {"t": "pt", "text": "Budget = quantified plan for a forthcoming period", "id": "acfbe-rv10a-80e78-e5144c"}, {"t": "pt", "text": "Budget purposes: plan, co-ordinate, communicate, control, motivate, responsibility", "id": "acfbe-rv10a-80e78-74c24d"}, {"t": "pt", "text": "Cost, revenue, profit and investment centres", "id": "acfbe-rv10a-80e78-81943d"}, {"t": "pt", "text": "Controllable cost = influenced by the budget holder", "id": "acfbe-rv10a-80e78-e538cf"}, {"t": "pt", "text": "Responsibility accounting: hold managers to controllable costs only", "id": "acfbe-rv10a-80e78-59da99"}, {"t": "pt", "text": "Fixed budget: one activity level, unchanged", "id": "acfbe-rv10a-80e78-3834a1"}, {"t": "pt", "text": "Flexible budget: changes with activity", "id": "acfbe-rv10a-80e78-3e652e"}, {"t": "pt", "text": "Flexed cost = fixed + variable rate x actual activity", "id": "acfbe-rv10a-80e78-8fb983"}, {"t": "pt", "text": "Variances: actual vs flexed budget", "id": "acfbe-rv10a-80e78-a458ed"}, {"t": "pt", "text": "Use high-low to split semi-variable costs", "id": "acfbe-rv10a-80e78-b8c1d4"}, {"t": "pt", "text": "Never flex fixed costs", "id": "acfbe-rv10a-80e78-77bd1e"}, {"t": "pt", "text": "Spreadsheet formulae start with =", "id": "acfbe-rv10a-80e78-79e07c"}], "id": "acfbe-rv10a-80e78"}], "source": "BPP Workbook ch 10a: sections 1-11 pp364-387", "summary": "The planning and control cycle, budgetary planning and control, responsibility centres and controllable costs, fixed vs flexible budgets (using the high-low method) and spreadsheets for budgeting.", "id": "acfbe-rv10a", "updated": "2026-11-12"}, {"num": "10b", "title": "The Budgetary Process", "pages": [393, 426], "syllabus": "D3", "status": "published", "branches": [{"kind": "process", "title": "Budget administration and timetable", "page": [394, 399], "items": [{"t": "pt", "text": "Budget period: usually one year, often split into quarters or months (capital budgets cover longer)", "id": "acfbe-rv10b-f6427-64c349"}, {"t": "def", "k": 1, "term": "Budget manual", "text": "A collection of instructions governing the responsibilities of people and the procedures, forms and records relating to the budget", "id": "acfbe-rv10b-f6427-27a81b"}, {"t": "pt", "text": "Budgets should be prepared by the managers responsible for achieving them (with help from the accountant)", "id": "acfbe-rv10b-f6427-492716"}, {"t": "pt", "text": "Budget committee (representatives of each function, chaired by a senior manager) co-ordinates and administers budgets; the budget officer is its secretary", "id": "acfbe-rv10b-f6427-5ac115"}, {"t": "pt", "k": 1, "text": "Preparation sequence: communicate budget policy -> determine the principal budget factor -> prepare the sales budget -> prepare other functional budgets -> negotiate budgets with superiors -> co-ordinate and review -> final acceptance (master budget) -> budget review during the period", "id": "acfbe-rv10b-f6427-3f43b6"}, {"t": "def", "k": 1, "term": "Principal budget factor", "text": "The factor which limits the activities of the organisation - usually SALES demand (could be materials, labour or capacity); it must be identified first", "id": "acfbe-rv10b-f6427-b053ae"}], "id": "acfbe-rv10b-f6427"}, {"kind": "formula", "title": "Functional budgets", "page": [400, 408], "items": [{"t": "def", "k": 1, "term": "Functional (departmental) budgets", "text": "Budgets for the various functions and departments of the organisation (sales, production, materials, labour, overheads)", "id": "acfbe-rv10b-1ada0-08e64a"}, {"t": "pt", "text": "Order: sales budget -> production budget -> materials usage -> materials purchases -> labour -> overheads (non-manufacturing departments too)", "id": "acfbe-rv10b-1ada0-0f4e16"}, {"t": "f", "k": 1, "term": "Production budget (units)", "text": "Sales + Closing inventory of finished goods - Opening inventory of finished goods", "vars": "units, not $", "eg": "Sales 700, closing 70, opening 50: production 720", "id": "acfbe-rv10b-1ada0-72b572"}, {"t": "f", "k": 1, "term": "Material usage budget", "text": "Production units x Material per unit", "vars": "include expected wastage", "id": "acfbe-rv10b-1ada0-3d5bdc"}, {"t": "f", "k": 1, "term": "Material purchases budget", "text": "Material usage + Closing inventory of materials - Opening inventory of materials", "vars": "then x price per unit", "eg": "quantity first, then value", "id": "acfbe-rv10b-1ada0-3c3860"}, {"t": "f", "term": "Labour budget", "text": "Production units x Standard hours per unit (x rate)", "vars": "allow for efficiency (eg 80% of 2 hours = 1.6 hours) and idle time", "id": "acfbe-rv10b-1ada0-a84f6c"}, {"t": "def", "term": "Standard hour", "text": "The amount of work achievable at standard efficiency levels in one hour - a common measure for different products", "id": "acfbe-rv10b-1ada0-982563"}, {"t": "exam", "text": "Material purchases often require you to manipulate opening inventory + purchases - usage = closing inventory", "id": "acfbe-rv10b-1ada0-10dd98"}, {"t": "pt", "text": "Co-ordinate functional budgets in the right order so they are consistent", "id": "acfbe-rv10b-1ada0-f4d35a"}], "id": "acfbe-rv10b-1ada0"}, {"kind": "formula", "title": "Cash budgets", "page": [409, 414], "items": [{"t": "def", "k": 1, "term": "Cash budget", "text": "A detailed budget of cash inflows and outflows incorporating both revenue and capital items", "id": "acfbe-rv10b-8cfdc-a7bc12"}, {"t": "pt", "text": "Profit and cash differ because of timing (credit sales/purchases), non-cash items (depreciation), capital items (asset purchases, loans) and inventory changes", "id": "acfbe-rv10b-8cfdc-c74691"}, {"t": "pt", "k": 1, "text": "Exclude non-cash items such as depreciation and irrecoverable debt write-offs; include capital receipts and payments", "id": "acfbe-rv10b-8cfdc-fd7920"}, {"t": "f", "term": "Cash received from customers", "text": "Sales + Opening receivables - Closing receivables", "vars": "or apply collection pattern (eg 40% in the month, 60% next month)", "id": "acfbe-rv10b-8cfdc-00e260"}, {"t": "f", "term": "Purchases", "text": "Cost of sales + Closing inventory - Opening inventory", "vars": "then apply payment pattern", "id": "acfbe-rv10b-8cfdc-655150"}, {"t": "f", "term": "Cash paid to suppliers", "text": "Purchases + Opening payables - Closing payables", "vars": "timing of payments", "id": "acfbe-rv10b-8cfdc-ca1337"}, {"t": "pt", "text": "Uses: plan financing ahead, identify surpluses to invest or deficits to finance", "id": "acfbe-rv10b-8cfdc-eef77f"}, {"t": "pt", "text": "Short-term surplus: pay suppliers early (discounts), invest short term; short-term deficit: overdraft, delay payments, chase receivables; long-term surplus: expand, repay debt; long-term deficit: raise long-term finance", "id": "acfbe-rv10b-8cfdc-64fc96"}, {"t": "exam", "text": "Read the ACCA article on cash budgets", "id": "acfbe-rv10b-8cfdc-f950a3"}], "id": "acfbe-rv10b-8cfdc"}, {"kind": "concept", "title": "Master budget", "page": [415, 419], "items": [{"t": "def", "k": 1, "term": "Master budget", "text": "The summary and consolidation of all functional budgets: budgeted statement of profit or loss, budgeted statement of financial position and cash budget", "id": "acfbe-rv10b-7180e-6bd235"}, {"t": "pt", "text": "Budgeted SOFP picks up closing receivables, payables, inventory and cash from the other budgets", "id": "acfbe-rv10b-7180e-ab8872"}, {"t": "eg", "text": "Selling price = cost of sales x 150% -> cost of sales = sales / 1.5", "id": "acfbe-rv10b-7180e-168c23"}], "id": "acfbe-rv10b-7180e"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Including depreciation in a cash budget - it is not a cash flow", "id": "acfbe-rv10b-6483a-30f715"}, {"t": "x", "text": "Adding opening inventory and deducting closing inventory in the production budget - it is the other way round", "id": "acfbe-rv10b-6483a-356d26"}, {"t": "x", "text": "Starting with the production budget when sales demand is the principal budget factor", "id": "acfbe-rv10b-6483a-bae78f"}, {"t": "x", "text": "Valuing purchases before working out quantities", "id": "acfbe-rv10b-6483a-511306"}], "id": "acfbe-rv10b-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Budget manual = instructions and procedures", "id": "acfbe-rv10b-80e78-adf72e"}, {"t": "pt", "text": "Budget committee co-ordinates; budget officer administers", "id": "acfbe-rv10b-80e78-53f6d7"}, {"t": "pt", "text": "Principal budget factor limits activity - usually sales", "id": "acfbe-rv10b-80e78-281d26"}, {"t": "pt", "text": "Sales budget first (if sales is the PBF)", "id": "acfbe-rv10b-80e78-0b5f7d"}, {"t": "pt", "text": "Production = sales + closing FG - opening FG", "id": "acfbe-rv10b-80e78-20bdfc"}, {"t": "pt", "text": "Purchases = usage + closing materials - opening materials", "id": "acfbe-rv10b-80e78-eb7749"}, {"t": "pt", "text": "Standard hour = work achievable in one hour at standard efficiency", "id": "acfbe-rv10b-80e78-3d0975"}, {"t": "pt", "text": "Cash budget: cash inflows and outflows, revenue and capital", "id": "acfbe-rv10b-80e78-26cd19"}, {"t": "pt", "text": "Exclude depreciation from cash budgets", "id": "acfbe-rv10b-80e78-2e067d"}, {"t": "pt", "text": "Receipts = sales + opening receivables - closing receivables", "id": "acfbe-rv10b-80e78-1691c2"}, {"t": "pt", "text": "Payments = purchases + opening payables - closing payables", "id": "acfbe-rv10b-80e78-48cdb5"}, {"t": "pt", "text": "Master budget = budgeted P/L + SOFP + cash budget", "id": "acfbe-rv10b-80e78-b0a160"}], "id": "acfbe-rv10b-80e78"}], "source": "BPP Workbook ch 10b: sections 1-6 pp394-419", "summary": "Budget administration (period, manual, committee), the preparation timetable and principal budget factor, functional budgets, cash budgets, budgeted financial statements and the master budget.", "id": "acfbe-rv10b", "updated": "2026-11-12"}, {"num": "11", "title": "Making Budgets Work", "pages": [427, 442], "syllabus": "D4", "status": "published", "branches": [{"kind": "concept", "title": "Behaviour and motivation", "page": [428, 430], "items": [{"t": "pt", "k": 1, "text": "Used correctly a budgetary control system can motivate - but it can also produce undesirable negative reactions", "id": "acfbe-rv11-32ad3-332c2e"}, {"t": "pt", "text": "Poor attitudes when SETTING budgets: managers may pad costs, see budgets as pressure devices, resent imposed targets", "id": "acfbe-rv11-32ad3-4d3f92"}, {"t": "pt", "text": "Poor attitudes when IMPLEMENTING: concentrate on short-term results, ignore other areas, poor communication", "id": "acfbe-rv11-32ad3-eac401"}, {"t": "pt", "text": "Poor attitudes to CONTROL information: reports seen as hostile, late or irrelevant information, blame culture", "id": "acfbe-rv11-32ad3-fbe443"}, {"t": "pt", "text": "Pay can motivate when there is a formal link between achieving budget targets and rewards", "id": "acfbe-rv11-32ad3-bb8e9d"}], "id": "acfbe-rv11-32ad3"}, {"kind": "compare", "title": "Budget-setting styles", "page": [430, 432], "items": [{"t": "table", "rows": [["Style", "Definition", "Advantages", "Disadvantages"], ["Imposed (top-down)", "Set without permitting the budget holder to participate", "Strategic plans built in; quick; good when staff lack skills or in a crisis", "Dissatisfaction, low commitment, unrealistic targets"], ["Participative (bottom-up)", "All budget holders take part in setting their own budgets", "Better morale and commitment, uses local knowledge, more realistic", "Slower, budgetary slack, may not align with strategy"], ["Negotiated", "Allowances set largely by negotiation between holders and those to whom they report", "A realistic compromise", "Time-consuming; power politics"]], "id": "acfbe-rv11-1d0d5-d4283f"}, {"t": "pt", "k": 1, "text": "Participation improves motivation when managers can influence outcomes, but is less useful when the environment is very uncertain or time is short", "id": "acfbe-rv11-1d0d5-030e3d"}, {"t": "def", "k": 1, "term": "Budgetary slack", "text": "The difference between the minimum necessary costs and the costs built into the budget or actually incurred - managers pad budgets to make targets easier", "id": "acfbe-rv11-1d0d5-71b2e9"}, {"t": "x", "text": "Participative budgeting encourages budgetary slack - the main danger", "id": "acfbe-rv11-1d0d5-020204"}, {"t": "exam", "text": "Expect scenario MCQs asking you to identify the budgeting style (imposed, participative, negotiated) or its likely behavioural effect", "id": "acfbe-rv11-1d0d5-615af1"}], "id": "acfbe-rv11-1d0d5"}, {"kind": "concept", "title": "Performance evaluation and targets", "page": [432, 435], "items": [{"t": "pt", "k": 1, "text": "Performance evaluation is an important source of motivation - targets should be challenging but attainable", "id": "acfbe-rv11-cdb43-551828"}, {"t": "pt", "text": "Feedback: reports clear and comprehensive; the exception principle applied (focus on significant variances); controllable vs uncontrollable costs separated; timely; regular; focused on improvement", "id": "acfbe-rv11-cdb43-3540e1"}, {"t": "pt", "k": 1, "text": "Expectations budget (likely outcome - used for planning and decision making) vs aspirations budget (challenging target - used to motivate)", "id": "acfbe-rv11-cdb43-a3f023"}, {"t": "pt", "text": "Too-easy targets demotivate; too-difficult targets cause frustration and give-up", "id": "acfbe-rv11-cdb43-1fe3f1"}], "id": "acfbe-rv11-cdb43"}, {"kind": "formula", "title": "Incentive schemes", "page": [435, 439], "items": [{"t": "def", "k": 1, "term": "Profit sharing scheme", "text": "Employees receive a certain proportion of the company's year-end profits", "id": "acfbe-rv11-aec62-d2ff82"}, {"t": "pt", "text": "Share-based schemes: share option schemes, share incentive plans - link employees to long-term value", "id": "acfbe-rv11-aec62-4271d0"}, {"t": "f", "k": 1, "term": "Value added", "text": "Sales - Cost of bought-in materials and services", "vars": "an alternative to profit as a performance measure for incentive schemes", "eg": "shows the wealth created by the business's own efforts", "id": "acfbe-rv11-aec62-55a563"}, {"t": "pt", "text": "Value added schemes share a proportion of value added (above a target) with employees", "id": "acfbe-rv11-aec62-c22544"}, {"t": "pt", "text": "Group schemes encourage co-operation; individual schemes encourage personal effort", "id": "acfbe-rv11-aec62-372f0e"}], "id": "acfbe-rv11-aec62"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Assuming participation always improves performance - it can create slack and is slow", "id": "acfbe-rv11-6483a-86411b"}, {"t": "x", "text": "Calling a budget set by negotiation 'imposed'", "id": "acfbe-rv11-6483a-aa4751"}, {"t": "x", "text": "Using an aspirations budget for planning cash or resources - use the expectations budget", "id": "acfbe-rv11-6483a-5febb6"}, {"t": "x", "text": "Defining value added as sales minus ALL costs - only bought-in materials and services are deducted", "id": "acfbe-rv11-6483a-c85276"}], "id": "acfbe-rv11-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Budgets can motivate or demotivate", "id": "acfbe-rv11-80e78-de8928"}, {"t": "pt", "text": "Imposed = top-down; participative = bottom-up; negotiated = compromise", "id": "acfbe-rv11-80e78-91da60"}, {"t": "pt", "text": "Participation: commitment and local knowledge, but slack and delay", "id": "acfbe-rv11-80e78-ec20e5"}, {"t": "pt", "text": "Budgetary slack = padding between needed and budgeted cost", "id": "acfbe-rv11-80e78-27e97d"}, {"t": "pt", "text": "Feedback: clear, timely, exception-based, controllable items", "id": "acfbe-rv11-80e78-7e1e56"}, {"t": "pt", "text": "Targets: challenging but attainable", "id": "acfbe-rv11-80e78-029131"}, {"t": "pt", "text": "Expectations budget for planning; aspirations budget to motivate", "id": "acfbe-rv11-80e78-67f5eb"}, {"t": "pt", "text": "Profit sharing: share of year-end profits", "id": "acfbe-rv11-80e78-fadff1"}, {"t": "pt", "text": "Value added = sales - bought-in materials and services", "id": "acfbe-rv11-80e78-7f179f"}, {"t": "pt", "text": "Share schemes link staff to long-term value", "id": "acfbe-rv11-80e78-7dac98"}, {"t": "pt", "text": "Group bonuses encourage teamwork", "id": "acfbe-rv11-80e78-67e769"}, {"t": "pt", "text": "Pay motivates when formally linked to targets", "id": "acfbe-rv11-80e78-1a4a2a"}], "id": "acfbe-rv11-80e78"}], "source": "BPP Workbook ch 11: sections 1-4 pp428-439", "summary": "Behavioural implications of budgeting, imposed, participative and negotiated budgets, performance evaluation and feedback, budgetary slack, expectations vs aspirations budgets, and incentive schemes.", "id": "acfbe-rv11", "updated": "2026-11-12"}, {"num": "12a", "title": "Capital Expenditure Budgeting", "pages": [443, 450], "syllabus": "D6", "status": "published", "branches": [{"kind": "compare", "title": "Capital vs revenue", "page": [444, 446], "items": [{"t": "table", "rows": [["Item", "Capital", "Revenue"], ["Expenditure", "Acquires non-current assets or improves their earning capacity", "Goods and services used up in the period, or maintaining existing assets"], ["Income", "Proceeds from the sale of non-trading assets (eg a non-current asset)", "Income from trading (sales) and investments (interest, dividends)"], ["Accounting", "Capitalised in the statement of financial position, depreciated", "Charged to profit or loss in the period"]], "id": "acfbe-rv12a-ab159-cbd21c"}, {"t": "def", "k": 1, "term": "Capital expenditure", "text": "Expenditure which results in the acquisition of non-current assets or an improvement in their earning capacity", "id": "acfbe-rv12a-ab159-5f542c"}, {"t": "def", "k": 1, "term": "Revenue expenditure", "text": "Expenditure for the purpose of the trade, or to maintain the existing earning capacity of non-current assets (eg repairs)", "id": "acfbe-rv12a-ab159-ff90b4"}, {"t": "pt", "text": "Other capital transactions: raising finance (share issues, loans) and repaying it are not revenue items", "id": "acfbe-rv12a-ab159-b311ba"}, {"t": "eg", "text": "Repainting an existing building = revenue; building an extension = capital", "id": "acfbe-rv12a-ab159-a6ea86"}, {"t": "pt", "k": 1, "text": "The distinction matters because it determines whether cost is matched against the current period's revenue or spread over the asset's life - getting it wrong misstates profit and assets", "id": "acfbe-rv12a-ab159-007ad7"}], "id": "acfbe-rv12a-ab159"}, {"kind": "concept", "title": "Self-constructed assets", "page": [446, 446], "items": [{"t": "pt", "k": 1, "text": "Where a business builds its own non-current asset, the costs of materials, labour and attributable overheads are capitalised as the asset's cost, not expensed", "id": "acfbe-rv12a-5db7b-af4f37"}, {"t": "pt", "text": "Only production costs directly attributable to bringing the asset into use are capitalised", "id": "acfbe-rv12a-5db7b-026e34"}], "id": "acfbe-rv12a-5db7b"}, {"kind": "process", "title": "Capital expenditure budgets", "page": [447, 450], "items": [{"t": "pt", "k": 1, "text": "Recurring and minor asset purchases may be covered by an annual capital expenditure budget allowance", "id": "acfbe-rv12a-96372-f1a752"}, {"t": "pt", "text": "Major projects require individual appraisal and authorisation before inclusion in the capital budget", "id": "acfbe-rv12a-96372-3644b4"}, {"t": "pt", "text": "Process: identify investment opportunities -> collect data and forecast cash flows -> appraise (payback, NPV, IRR) -> authorise -> implement -> monitor and post-completion audit", "id": "acfbe-rv12a-96372-cad205"}, {"t": "pt", "text": "Capital budgets often cover several years and feed into the cash budget and budgeted statement of financial position", "id": "acfbe-rv12a-96372-0d629e"}, {"t": "pt", "text": "Authorisation levels depend on the size of the investment (eg board approval for major projects)", "id": "acfbe-rv12a-96372-71a842"}, {"t": "exam", "text": "Capital expenditure links to the appraisal methods in chapter 12b", "id": "acfbe-rv12a-96372-53c3b2"}], "id": "acfbe-rv12a-96372"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Treating repairs that restore an asset as capital - they are revenue", "id": "acfbe-rv12a-6483a-7bf029"}, {"t": "x", "text": "Recording proceeds from selling a non-current asset as revenue income - it is capital income", "id": "acfbe-rv12a-6483a-6e4d95"}, {"t": "x", "text": "Expensing the labour used to build a company's own asset - it is capitalised", "id": "acfbe-rv12a-6483a-c8568a"}, {"t": "x", "text": "Treating loan repayments as revenue expenditure", "id": "acfbe-rv12a-6483a-af0420"}], "id": "acfbe-rv12a-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Capital expenditure: acquire or improve non-current assets", "id": "acfbe-rv12a-80e78-abade7"}, {"t": "pt", "text": "Revenue expenditure: day-to-day running and maintenance", "id": "acfbe-rv12a-80e78-d4a41b"}, {"t": "pt", "text": "Capital income: sale of non-trading assets", "id": "acfbe-rv12a-80e78-1da915"}, {"t": "pt", "text": "Revenue income: trading and investment income", "id": "acfbe-rv12a-80e78-cbf3fa"}, {"t": "pt", "text": "Capital items capitalised and depreciated", "id": "acfbe-rv12a-80e78-cd9e44"}, {"t": "pt", "text": "Revenue items charged to profit or loss", "id": "acfbe-rv12a-80e78-7841fa"}, {"t": "pt", "text": "Misclassification misstates profit and assets", "id": "acfbe-rv12a-80e78-9c6d24"}, {"t": "pt", "text": "Self-constructed assets: capitalise directly attributable costs", "id": "acfbe-rv12a-80e78-357b50"}, {"t": "pt", "text": "Raising and repaying finance are capital transactions", "id": "acfbe-rv12a-80e78-47cc9d"}, {"t": "pt", "text": "Minor recurring purchases: annual capital allowance", "id": "acfbe-rv12a-80e78-3d82a8"}, {"t": "pt", "text": "Major projects: appraise and authorise individually", "id": "acfbe-rv12a-80e78-5f9b26"}, {"t": "pt", "text": "Post-completion audit reviews the outcome", "id": "acfbe-rv12a-80e78-70665c"}], "id": "acfbe-rv12a-80e78"}], "source": "BPP Workbook ch 12a: sections 1-3 pp444-447", "summary": "Capital vs revenue expenditure and income, other capital transactions, why the distinction matters, self-constructed assets and preparing capital expenditure budgets.", "id": "acfbe-rv12a", "updated": "2026-11-12"}, {"num": "12b", "title": "Methods of Project Appraisal", "pages": [451, 478], "syllabus": "D6, D7", "status": "published", "branches": [{"kind": "formula", "title": "Payback and the time value of money", "page": [453, 458], "items": [{"t": "f", "k": 1, "term": "Payback period", "text": "Time taken for the initial investment to be recovered from the project's cash INFLOWS", "vars": "uses cash flows, not profits (add back depreciation)", "eg": "Cost $60,000, inflows $20,000 a year: payback 3 years", "id": "acfbe-rv12b-5291f-fd518b"}, {"t": "pt", "text": "Payback: simple, favours quick returns and liquidity; but ignores cash flows after payback and the time value of money", "id": "acfbe-rv12b-5291f-dd999d"}, {"t": "f", "k": 1, "term": "Compound interest", "text": "S = P(1 + r)^n", "vars": "S = sum after n years; P = amount invested now; r = interest rate; n = number of years", "eg": "$1,000 at 10% for 2 years = $1,210", "id": "acfbe-rv12b-5291f-c7cdd3"}, {"t": "f", "k": 1, "term": "Discounting (present value)", "text": "P = S / (1 + r)^n = S(1 + r)^-n", "vars": "discount factor = 1/(1 + r)^n", "eg": "$11,000 in 1 year at 10% = $10,000 now", "id": "acfbe-rv12b-5291f-0dfabe"}, {"t": "f", "k": 1, "term": "Effective annual rate", "text": "(1 + R) = (1 + r)^n", "vars": "R = effective annual rate; r = rate per period; n = number of periods in a year", "eg": "1% a month: 1.01^12 - 1 = 12.68%", "id": "acfbe-rv12b-5291f-6bf47d"}, {"t": "pt", "text": "Nominal rate = stated per annum rate (eg 10% paid quarterly); effective annual rate = APR = compound annual rate", "id": "acfbe-rv12b-5291f-6c523f"}, {"t": "exam", "text": "Students often confuse nominal and effective rates - effective includes compounding within the year", "id": "acfbe-rv12b-5291f-e800ed"}, {"t": "exam", "text": "In NPV calculations finance costs (interest) are IRRELEVANT - the discounting process already allows for them", "id": "acfbe-rv12b-5291f-5e703a"}], "id": "acfbe-rv12b-5291f"}, {"kind": "formula", "title": "Net present value", "page": [459, 462], "items": [{"t": "def", "k": 1, "term": "Net present value (NPV)", "text": "The present value of all cash inflows minus the present value of all cash outflows of a project, discounted at the cost of capital", "id": "acfbe-rv12b-82ddc-15fcc3"}, {"t": "pt", "k": 1, "text": "Decision rule: NPV positive -> accept; negative -> reject; choose the highest NPV among mutually exclusive projects", "id": "acfbe-rv12b-82ddc-3747e0"}, {"t": "pt", "text": "Year 0 = now (factor 1.000); cash flows assumed to arise at the END of each year", "id": "acfbe-rv12b-82ddc-6b6368"}, {"t": "pt", "text": "Advantages: maximises shareholder wealth, uses all cash flows, allows for time value; disadvantages: cost of capital hard to estimate, harder to understand", "id": "acfbe-rv12b-82ddc-873295"}, {"t": "f", "term": "Discounted payback", "text": "Time until cumulative DISCOUNTED cash flows recover the investment", "vars": "longer than simple payback", "eg": "still ignores flows after payback", "id": "acfbe-rv12b-82ddc-39b9f7"}, {"t": "def", "term": "Cost of capital", "text": "The appropriate discount rate - the cost of the funds used (the return investors require)", "id": "acfbe-rv12b-82ddc-7818d4"}], "id": "acfbe-rv12b-82ddc"}, {"kind": "formula", "title": "Annuities and perpetuities", "page": [462, 465], "items": [{"t": "f", "k": 1, "term": "Annuity", "text": "PV = Annual cash flow x Annuity factor", "vars": "annuity = same amount every year for a number of years; annuity factor = sum of the discount factors", "eg": "$1 a year for years 1-6 at 5% = 5.076", "id": "acfbe-rv12b-6c1ef-fc8826"}, {"t": "pt", "text": "Delayed annuity (eg years 3-7) = annuity factor for years 1-7 minus factor for years 1-2", "id": "acfbe-rv12b-6c1ef-7509f5"}, {"t": "f", "k": 1, "term": "Perpetuity", "text": "PV = Annual cash flow / r", "vars": "an annuity that lasts forever, first flow at year 1", "eg": "$1 a year at 10% = $10", "id": "acfbe-rv12b-6c1ef-9c6f5d"}, {"t": "f", "term": "Breakeven annual income", "text": "Fall in income = NPV / annuity factor", "vars": "income can fall by this much before NPV = 0", "eg": "NPV $8,416 / 4.868 = $1,729 fall", "id": "acfbe-rv12b-6c1ef-3a1657"}], "id": "acfbe-rv12b-6c1ef"}, {"kind": "formula", "title": "IRR and ARR", "page": [465, 468], "items": [{"t": "def", "k": 1, "term": "Internal rate of return (IRR)", "text": "The discount rate at which the NPV of a project is zero", "id": "acfbe-rv12b-9c8a7-ecc084"}, {"t": "f", "k": 1, "term": "IRR (interpolation)", "text": "IRR = A + [NPV_A / (NPV_A - NPV_B)] x (B - A)", "vars": "A = lower rate (positive NPV); B = higher rate (negative NPV)", "eg": "an estimate - linear interpolation", "id": "acfbe-rv12b-9c8a7-37d8e0"}, {"t": "pt", "text": "Decision: accept if IRR > cost of capital", "id": "acfbe-rv12b-9c8a7-e70190"}, {"t": "pt", "text": "IRR advantages: considers time value, a % is easy to understand; problems: unconventional cash flows can give several IRRs, ignores project size, can conflict with NPV", "id": "acfbe-rv12b-9c8a7-4b590c"}, {"t": "f", "k": 1, "term": "Accounting rate of return (ARR)", "text": "Average annual profit / Average investment x 100%", "vars": "average investment = (initial cost + scrap value) / 2; uses profit AFTER depreciation", "eg": "ARR is a profit-based measure that ignores time value", "id": "acfbe-rv12b-9c8a7-e6789a"}], "id": "acfbe-rv12b-9c8a7"}, {"kind": "concept", "title": "Relevant costs", "page": [468, 471], "items": [{"t": "def", "k": 1, "term": "Relevant cost", "text": "A future, incremental cash flow arising as a direct consequence of the decision", "id": "acfbe-rv12b-a12af-7af159"}, {"t": "pt", "text": "Relevant: avoidable costs, differential (incremental) costs, opportunity costs", "id": "acfbe-rv12b-a12af-71845b"}, {"t": "pt", "k": 1, "text": "Non-relevant: sunk (past) costs, committed costs, non-cash items (depreciation), notional costs, allocated/apportioned fixed overheads, historical cost", "id": "acfbe-rv12b-a12af-2da570"}, {"t": "pt", "text": "Assume variable costs are relevant and fixed costs irrelevant unless told otherwise; attributable (specific) fixed costs ARE relevant", "id": "acfbe-rv12b-a12af-c8b382"}, {"t": "def", "term": "Opportunity cost", "text": "The benefit forgone by choosing one opportunity instead of the next best alternative", "id": "acfbe-rv12b-a12af-a74321"}, {"t": "pt", "text": "Machine user costs: incremental hire charges and running costs are relevant; historical depreciation is not", "id": "acfbe-rv12b-a12af-0248f4"}], "id": "acfbe-rv12b-a12af"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Including interest/finance costs in NPV cash flows", "id": "acfbe-rv12b-6483a-601643"}, {"t": "x", "text": "Including depreciation in DCF cash flows - it is not a cash flow", "id": "acfbe-rv12b-6483a-48f9f3"}, {"t": "x", "text": "Using profit instead of cash flow for payback", "id": "acfbe-rv12b-6483a-d3e553"}, {"t": "x", "text": "Interpolating IRR with two positive NPVs and no sign check - ideally one positive and one negative", "id": "acfbe-rv12b-6483a-1313f1"}, {"t": "x", "text": "Treating a sunk cost already paid as relevant to the decision", "id": "acfbe-rv12b-6483a-696abe"}], "id": "acfbe-rv12b-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Payback = time to recover investment from cash inflows", "id": "acfbe-rv12b-80e78-444fd7"}, {"t": "pt", "text": "S = P(1 + r)^n; PV = S/(1 + r)^n", "id": "acfbe-rv12b-80e78-0dc02d"}, {"t": "pt", "text": "Effective rate: (1 + R) = (1 + r)^n", "id": "acfbe-rv12b-80e78-a97a7e"}, {"t": "pt", "text": "NPV > 0 accept", "id": "acfbe-rv12b-80e78-a4ecb8"}, {"t": "pt", "text": "Ignore finance costs and depreciation in DCF", "id": "acfbe-rv12b-80e78-b79d60"}, {"t": "pt", "text": "Annuity PV = cash flow x annuity factor", "id": "acfbe-rv12b-80e78-9cc181"}, {"t": "pt", "text": "Perpetuity PV = cash flow / r", "id": "acfbe-rv12b-80e78-5fb1a7"}, {"t": "pt", "text": "IRR = rate where NPV = 0", "id": "acfbe-rv12b-80e78-7d9c89"}, {"t": "pt", "text": "IRR = A + [NPV_A/(NPV_A - NPV_B)] x (B - A)", "id": "acfbe-rv12b-80e78-25ff5f"}, {"t": "pt", "text": "Accept if IRR > cost of capital", "id": "acfbe-rv12b-80e78-cf989b"}, {"t": "pt", "text": "ARR = average profit / average investment", "id": "acfbe-rv12b-80e78-a9070a"}, {"t": "pt", "text": "Average investment = (cost + scrap) / 2", "id": "acfbe-rv12b-80e78-89836f"}, {"t": "pt", "text": "Relevant = future incremental cash flows; sunk and committed costs are irrelevant", "id": "acfbe-rv12b-80e78-09fdfb"}], "id": "acfbe-rv12b-80e78"}], "source": "BPP Workbook ch 12b: sections 1-7 pp452-471", "summary": "Payback, time value of money (compounding, discounting, effective rates), NPV, discounted payback, annuities, perpetuities, breakeven NPV, IRR, ARR, and relevant costs for decisions.", "id": "acfbe-rv12b", "updated": "2026-11-12"}, {"num": "13", "title": "Standard Costing", "pages": [479, 488], "syllabus": "E1", "status": "published", "branches": [{"kind": "concept", "title": "What is standard costing?", "page": [480, 482], "items": [{"t": "def", "k": 1, "term": "Standard cost", "text": "A predetermined estimated unit cost, used for inventory valuation and control", "id": "acfbe-rv13-ae326-5aaf06"}, {"t": "def", "k": 1, "term": "Standard cost card", "text": "Shows full details of the standard cost of each product: standard quantities and prices of materials, standard hours and rates of labour, and overhead absorbed at standard rates", "id": "acfbe-rv13-ae326-e1e481"}, {"t": "pt", "k": 1, "text": "Two principal uses: valuing inventories and cost of production • acting as a control device (establishing budgets and comparing actual with standard)", "id": "acfbe-rv13-ae326-d29a55"}, {"t": "pt", "text": "Other uses: setting selling prices, motivation via targets, simplifying bookkeeping (inventory at standard cost)", "id": "acfbe-rv13-ae326-74abfb"}, {"t": "def", "k": 1, "term": "Variance", "text": "The difference between actual and standard cost (or revenue)", "id": "acfbe-rv13-ae326-158004"}, {"t": "pt", "text": "Standard costing can be applied under BOTH absorption and marginal costing", "id": "acfbe-rv13-ae326-de7d1c"}, {"t": "pt", "text": "Most suited to repetitive, standardised production; less useful for one-off jobs or rapidly changing environments", "id": "acfbe-rv13-ae326-ec3348"}], "id": "acfbe-rv13-ae326"}, {"kind": "compare", "title": "Types of performance standard", "page": [483, 483], "items": [{"t": "table", "rows": [["Standard", "Basis", "Effect on motivation"], ["Ideal", "Perfect operating conditions - no wastage, idle time or inefficiency", "Demotivating - unattainable; constant adverse variances"], ["Attainable", "Efficient operations with allowance for normal losses, waste and downtime", "Motivating - challenging but achievable (most common)"], ["Current", "Current working conditions (current wastage and inefficiency)", "No incentive to improve"], ["Basic", "Unaltered over a long period", "Useful for trends only; becomes outdated"]], "id": "acfbe-rv13-e1563-93071e"}], "id": "acfbe-rv13-e1563"}, {"kind": "process", "title": "Setting standards", "page": [483, 485], "items": [{"t": "pt", "k": 1, "text": "Material prices: estimated by the purchasing department (prices, discounts, inflation, quality)", "id": "acfbe-rv13-42608-323090"}, {"t": "pt", "k": 1, "text": "Labour rates: set with the personnel/HR department (pay rates, agreed increases)", "id": "acfbe-rv13-42608-72e51d"}, {"t": "pt", "text": "Overhead absorption rates: budgeted overhead / budgeted activity (fixed rate based on standard hours for full absorption)", "id": "acfbe-rv13-42608-74ae57"}, {"t": "pt", "text": "Standard resource requirements: material usage and labour hours from technical specifications, work study and past experience", "id": "acfbe-rv13-42608-9b4fbf"}, {"t": "pt", "text": "Standards are usually revised annually when the budget is prepared", "id": "acfbe-rv13-42608-6060be"}, {"t": "exam", "text": "An exam question may give actual costs and variances and ask you to work back to the standard cost", "id": "acfbe-rv13-42608-87fa73"}], "id": "acfbe-rv13-42608"}, {"kind": "concept", "title": "Standard costing as control", "page": [481, 482], "items": [{"t": "pt", "k": 1, "text": "Control by comparison: actual results vs standard -> variances -> investigate significant variances -> corrective action (management by exception)", "id": "acfbe-rv13-5e16e-0b7524"}, {"t": "pt", "text": "Standards provide the basis for budgets (budgeted cost = standard cost x budgeted output)", "id": "acfbe-rv13-5e16e-cd1401"}, {"t": "pt", "text": "Problems: setting realistic standards, keeping standards up to date, behavioural effects of unattainable standards, less relevant in modern flexible manufacturing", "id": "acfbe-rv13-5e16e-6d50e3"}], "id": "acfbe-rv13-5e16e"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calling an ideal standard 'attainable' - ideal allows for NO waste or inefficiency", "id": "acfbe-rv13-6483a-bb0b01"}, {"t": "x", "text": "Thinking standard costing only works with absorption costing - it also works with marginal costing", "id": "acfbe-rv13-6483a-108cf8"}, {"t": "x", "text": "Assuming standards never need revision - they are usually reviewed annually", "id": "acfbe-rv13-6483a-d55e63"}, {"t": "x", "text": "Confusing a standard (per unit) with a budget (in total for the period)", "id": "acfbe-rv13-6483a-35b0ce"}], "id": "acfbe-rv13-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Standard cost = predetermined unit cost", "id": "acfbe-rv13-80e78-34272e"}, {"t": "pt", "text": "Standard cost card lists quantities, hours, rates and overheads", "id": "acfbe-rv13-80e78-06e72e"}, {"t": "pt", "text": "Uses: inventory valuation and control", "id": "acfbe-rv13-80e78-833f67"}, {"t": "pt", "text": "Variance = actual vs standard", "id": "acfbe-rv13-80e78-bed9f2"}, {"t": "pt", "text": "Works with absorption and marginal costing", "id": "acfbe-rv13-80e78-1a3b35"}, {"t": "pt", "text": "Ideal standard: perfect conditions, demotivating", "id": "acfbe-rv13-80e78-5a549c"}, {"t": "pt", "text": "Attainable standard: allows normal losses, motivating", "id": "acfbe-rv13-80e78-d3d439"}, {"t": "pt", "text": "Current standard: today's conditions, no improvement incentive", "id": "acfbe-rv13-80e78-1ea217"}, {"t": "pt", "text": "Basic standard: long-term, for trends", "id": "acfbe-rv13-80e78-9388a4"}, {"t": "pt", "text": "Prices from purchasing; rates from HR", "id": "acfbe-rv13-80e78-a3313b"}, {"t": "pt", "text": "Usage and hours from technical specifications and work study", "id": "acfbe-rv13-80e78-c1b71b"}, {"t": "pt", "text": "Management by exception: investigate significant variances", "id": "acfbe-rv13-80e78-8becbc"}], "id": "acfbe-rv13-80e78"}], "source": "BPP Workbook ch 13: sections 1-2 pp480-485", "summary": "What a standard cost is, the standard cost card, uses of standard costing, standard costing as a control technique, setting standards and the four types of performance standard.", "id": "acfbe-rv13", "updated": "2026-11-12"}, {"num": "14a", "title": "Cost Variances", "pages": [489, 514], "syllabus": "E2, D5", "status": "published", "branches": [{"kind": "concept", "title": "Variances basics", "page": [490, 490], "items": [{"t": "def", "k": 1, "term": "Variance", "text": "The difference between a planned, budgeted or standard cost and the actual cost incurred (the same comparison can be made for revenues)", "id": "acfbe-rv14a-07693-15b530"}, {"t": "pt", "k": 1, "text": "Favourable (F): actual results better than expected; adverse (A): worse than expected", "id": "acfbe-rv14a-07693-f6f27d"}, {"t": "pt", "text": "Groups: variable cost variances, sales variances, fixed production overhead variances", "id": "acfbe-rv14a-07693-52e561"}, {"t": "exam", "text": "Variance calculation is vital - you must be able to calculate every variance in the syllabus", "id": "acfbe-rv14a-07693-6495c2"}], "id": "acfbe-rv14a-07693"}, {"kind": "formula", "title": "Material variances", "page": [491, 492], "items": [{"t": "f", "k": 1, "term": "Material price variance", "text": "(Standard price - Actual price) x Actual quantity PURCHASED", "vars": "usually calculated at purchase so inventory is held at standard", "eg": "Std $2/kg, bought 5,000 kg for $9,500: (10,000 - 9,500) = $500 F", "id": "acfbe-rv14a-21743-c580e4"}, {"t": "f", "k": 1, "term": "Material usage variance", "text": "(Standard quantity for actual output - Actual quantity USED) x Standard price", "vars": "standard quantity = actual output x standard kg per unit", "eg": "1,000 units x 10 kg = 10,000 kg std; used 10,400 kg at $2: $800 A", "id": "acfbe-rv14a-21743-c55d50"}, {"t": "f", "term": "Material total variance", "text": "Standard cost of actual output - Actual cost", "vars": "= price + usage (when purchases = usage)", "id": "acfbe-rv14a-21743-a6a0fe"}], "id": "acfbe-rv14a-21743"}, {"kind": "formula", "title": "Labour variances", "page": [493, 493], "items": [{"t": "f", "k": 1, "term": "Labour rate variance", "text": "(Standard rate - Actual rate) x Actual hours PAID", "vars": "higher pay rate -> adverse", "id": "acfbe-rv14a-30b6b-3bc0f5"}, {"t": "f", "k": 1, "term": "Labour efficiency variance", "text": "(Standard hours for actual output - Actual hours WORKED) x Standard rate", "vars": "standard hours = actual output x standard hours per unit", "id": "acfbe-rv14a-30b6b-da8992"}, {"t": "f", "term": "Idle time variance", "text": "Idle hours x Standard rate", "vars": "always ADVERSE; hours paid but not worked", "id": "acfbe-rv14a-30b6b-6a0e73"}, {"t": "f", "term": "Labour total variance", "text": "Standard labour cost of actual output - Actual labour cost", "id": "acfbe-rv14a-30b6b-e596ca"}], "id": "acfbe-rv14a-30b6b"}, {"kind": "formula", "title": "Variable overhead variances", "page": [494, 494], "items": [{"t": "f", "k": 1, "term": "Variable overhead expenditure variance", "text": "(Actual hours worked x Standard variable overhead rate) - Actual variable overhead cost", "vars": "what it should have cost for the hours worked vs what it did cost", "id": "acfbe-rv14a-1f9d3-6aa0e0"}, {"t": "f", "k": 1, "term": "Variable overhead efficiency variance", "text": "(Standard hours for actual output - Actual hours worked) x Standard variable overhead rate", "vars": "same hours as the labour efficiency variance", "id": "acfbe-rv14a-1f9d3-369e71"}, {"t": "exam", "text": "The examining team has noted weakness in calculating variable overhead variances", "id": "acfbe-rv14a-1f9d3-8fd7ef"}], "id": "acfbe-rv14a-1f9d3"}, {"kind": "formula", "title": "Fixed overhead variances", "page": [495, 507], "items": [{"t": "pt", "k": 1, "text": "Under absorption costing, fixed overhead total variance = under/over-absorbed overhead", "id": "acfbe-rv14a-0beba-e41e05"}, {"t": "f", "k": 1, "term": "Fixed overhead expenditure variance", "text": "Budgeted fixed overhead - Actual fixed overhead", "vars": "the numerator of the absorption rate was wrong", "eg": "Budget $15,000, actual $20,000: $5,000 A", "id": "acfbe-rv14a-0beba-e63a11"}, {"t": "f", "k": 1, "term": "Fixed overhead volume variance", "text": "(Actual output - Budgeted output) x Standard fixed overhead per unit", "vars": "the denominator (activity) was different from budget", "eg": "3,500 vs 3,000 units at $5: $2,500 F", "id": "acfbe-rv14a-0beba-31c786"}, {"t": "f", "term": "Fixed overhead volume efficiency variance", "text": "(Standard hours for actual output - Actual hours worked) x Standard fixed overhead rate per hour", "id": "acfbe-rv14a-0beba-dd4c25"}, {"t": "f", "term": "Fixed overhead volume capacity variance", "text": "(Actual hours worked - Budgeted hours) x Standard fixed overhead rate per hour", "vars": "more hours worked than budgeted -> favourable", "id": "acfbe-rv14a-0beba-5c40d0"}, {"t": "pt", "text": "Volume variance = efficiency + capacity", "id": "acfbe-rv14a-0beba-eb3e90"}, {"t": "f", "term": "Fixed overhead total variance", "text": "Fixed overhead absorbed (actual output x standard rate) - Actual fixed overhead", "vars": "= expenditure + volume", "id": "acfbe-rv14a-0beba-eab161"}, {"t": "pt", "k": 1, "text": "Under MARGINAL costing there is NO volume variance - only the fixed overhead expenditure variance", "id": "acfbe-rv14a-0beba-3d5962"}, {"t": "exam", "text": "The examining team highlights fixed overhead expenditure, volume, efficiency and capacity variances", "id": "acfbe-rv14a-0beba-d8e9fe"}], "id": "acfbe-rv14a-0beba"}, {"kind": "process", "title": "Causes and significance", "page": [508, 511], "items": [{"t": "pt", "text": "Total cost variances compare the flexed budget (actual output at standard cost) with actual results", "id": "acfbe-rv14a-1f9c3-ff9888"}, {"t": "pt", "text": "Material price: price changes, discounts, different quality/supplier • usage: wastage, theft, quality of material, efficiency of labour", "id": "acfbe-rv14a-1f9c3-985c62"}, {"t": "pt", "text": "Labour rate: pay rise, overtime premium, grade of labour • efficiency: skill, motivation, machine problems, material quality", "id": "acfbe-rv14a-1f9c3-c03a4e"}, {"t": "pt", "text": "Fixed overhead expenditure: price changes, unexpected costs • volume: output higher/lower than budget, strikes, demand", "id": "acfbe-rv14a-1f9c3-134490"}, {"t": "pt", "k": 1, "text": "Four general causes: inappropriate standard • measurement errors • random or chance fluctuations • efficient or inefficient operations", "id": "acfbe-rv14a-1f9c3-de3ff4"}, {"t": "pt", "k": 1, "text": "Factors in deciding whether to investigate: materiality, controllability, type of standard, interdependence, cost vs benefit of investigation", "id": "acfbe-rv14a-1f9c3-bcdf64"}, {"t": "pt", "k": 1, "text": "Interdependence: cheaper, poorer-quality material -> favourable price but adverse usage; higher-skilled labour -> adverse rate but favourable efficiency", "id": "acfbe-rv14a-1f9c3-7330b7"}], "id": "acfbe-rv14a-1f9c3"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using actual quantity USED for the price variance when material was purchased into inventory - use quantity PURCHASED", "id": "acfbe-rv14a-6483a-464384"}, {"t": "x", "text": "Using hours PAID in the efficiency variance - use hours WORKED (idle time is separate)", "id": "acfbe-rv14a-6483a-8685bc"}, {"t": "x", "text": "Calculating a fixed overhead volume variance under marginal costing - it does not exist", "id": "acfbe-rv14a-6483a-1f79c5"}, {"t": "x", "text": "Comparing actual cost with the ORIGINAL budget rather than the standard cost of actual output", "id": "acfbe-rv14a-6483a-9ed843"}], "id": "acfbe-rv14a-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Material price = (SP - AP) x AQ purchased", "id": "acfbe-rv14a-80e78-be5d16"}, {"t": "pt", "text": "Material usage = (SQ - AQ used) x SP", "id": "acfbe-rv14a-80e78-6dadfe"}, {"t": "pt", "text": "Labour rate = (SR - AR) x hours paid", "id": "acfbe-rv14a-80e78-e686ec"}, {"t": "pt", "text": "Labour efficiency = (SH - AH worked) x SR", "id": "acfbe-rv14a-80e78-379bea"}, {"t": "pt", "text": "Idle time = idle hours x SR (always adverse)", "id": "acfbe-rv14a-80e78-f7263b"}, {"t": "pt", "text": "VOH expenditure = AH x std rate - actual cost", "id": "acfbe-rv14a-80e78-82cf03"}, {"t": "pt", "text": "VOH efficiency = (SH - AH) x std VOH rate", "id": "acfbe-rv14a-80e78-bf9718"}, {"t": "pt", "text": "FOH expenditure = budget - actual", "id": "acfbe-rv14a-80e78-9f16a0"}, {"t": "pt", "text": "FOH volume = (actual - budgeted output) x std FOH per unit", "id": "acfbe-rv14a-80e78-ad32e1"}, {"t": "pt", "text": "Volume = efficiency + capacity", "id": "acfbe-rv14a-80e78-74c58a"}, {"t": "pt", "text": "No volume variance in marginal costing", "id": "acfbe-rv14a-80e78-2123a8"}, {"t": "pt", "text": "Causes: bad standard, measurement, chance, (in)efficiency", "id": "acfbe-rv14a-80e78-280b82"}, {"t": "pt", "text": "Interdependence: cheap material = F price, A usage", "id": "acfbe-rv14a-80e78-2b8a7c"}], "id": "acfbe-rv14a-80e78"}], "source": "BPP Workbook ch 14a: sections 1-8 pp490-511", "summary": "Material, labour, variable overhead and fixed overhead variances, flexed budgets and variances, the causes of variances, their significance and interdependence.", "id": "acfbe-rv14a", "updated": "2026-11-12"}, {"num": "14b", "title": "Sales Variances and Operating Statements", "pages": [515, 534], "syllabus": "E3", "status": "published", "branches": [{"kind": "formula", "title": "Sales variances", "page": [516, 517], "items": [{"t": "f", "k": 1, "term": "Selling price variance", "text": "(Actual price - Standard price) x Actual quantity SOLD", "vars": "= actual revenue - (actual units sold x standard price)", "eg": "Std $15, 500 units sold for $8,500: 8,500 - 7,500 = $1,000 F", "id": "acfbe-rv14b-89d0f-5bae60"}, {"t": "f", "k": 1, "term": "Sales volume profit variance", "text": "(Actual units sold - Budgeted units sold) x Standard PROFIT per unit", "vars": "absorption costing", "eg": "Budget 8,000 units, sold 8,500, std profit $4: $2,000 F", "id": "acfbe-rv14b-89d0f-b2c3c6"}, {"t": "f", "k": 1, "term": "Sales volume contribution variance", "text": "(Actual units sold - Budgeted units sold) x Standard CONTRIBUTION per unit", "vars": "marginal costing", "eg": "Std contribution $(20 - 6.60) = $13.40 per unit", "id": "acfbe-rv14b-89d0f-260b99"}, {"t": "pt", "text": "Interdependence: a price cut may give an adverse price variance but a favourable volume variance", "id": "acfbe-rv14b-89d0f-586e12"}, {"t": "exam", "text": "Variance analysis is a very popular exam topic - be able to prepare operating statements", "id": "acfbe-rv14b-89d0f-afe224"}], "id": "acfbe-rv14b-89d0f"}, {"kind": "process", "title": "Operating statements", "page": [518, 525], "items": [{"t": "def", "k": 1, "term": "Operating statement", "text": "A statement reconciling budgeted profit (or contribution) with actual profit through the individual variances", "id": "acfbe-rv14b-75302-c6cea1"}, {"t": "pt", "text": "Absorption format: budgeted profit -> sales volume profit variance -> = standard profit on actual sales -> selling price variance -> cost variances (material, labour, variable overhead, fixed overhead expenditure and volume) -> actual profit", "id": "acfbe-rv14b-75302-055756"}, {"t": "pt", "k": 1, "text": "Marginal costing statement - two main differences from absorption:", "kids": [{"t": "pt", "text": "Sales volume variance valued at standard CONTRIBUTION, not profit", "id": "acfbe-rv14b-75302-b41a80"}, {"t": "pt", "text": "No fixed overhead volume variance - only the expenditure variance; actual fixed overhead deducted from contribution", "id": "acfbe-rv14b-75302-2e419c"}], "id": "acfbe-rv14b-75302-a745db"}, {"t": "pt", "text": "Add favourable variances; deduct adverse variances", "id": "acfbe-rv14b-75302-5e4ab5"}, {"t": "exam", "text": "The examining team found only a minority chose correctly in a past marginal costing operating statement question - remember the two differences", "id": "acfbe-rv14b-75302-c11c42"}], "id": "acfbe-rv14b-75302"}, {"kind": "formula", "title": "Deriving actual data", "page": [526, 527], "items": [{"t": "pt", "k": 1, "text": "Work backwards: variance = standard - actual, so actual = standard ± variance", "id": "acfbe-rv14b-82d8a-16664a"}, {"t": "eg", "text": "Rate variance $10,400 A on 260,000 hours at standard $5.00: $0.04 per hour adverse -> actual rate $5.04", "id": "acfbe-rv14b-82d8a-401ac2"}, {"t": "pt", "text": "Let the unknown be a symbol (eg Y = quantity used) and solve the variance equation", "id": "acfbe-rv14b-82d8a-ebad0c"}, {"t": "exam", "text": "Questions may give actual results and variances and ask for the standard, or vice versa", "id": "acfbe-rv14b-82d8a-f24226"}], "id": "acfbe-rv14b-82d8a"}, {"kind": "process", "title": "Control action", "page": [527, 528], "items": [{"t": "pt", "k": 1, "text": "Investigate a variance only if the expected benefits of investigation and correction exceed the costs", "id": "acfbe-rv14b-a813a-974212"}, {"t": "pt", "text": "Possible causes and action", "kids": [{"t": "pt", "text": "Measurement errors: correct the recording system", "id": "acfbe-rv14b-a813a-d8a5ea"}, {"t": "pt", "text": "Out-of-date standards: revise the standard (eg after price inflation)", "id": "acfbe-rv14b-a813a-490106"}, {"t": "pt", "text": "Efficient or inefficient operations: corrective action or reward", "id": "acfbe-rv14b-a813a-775283"}, {"t": "pt", "text": "Random or chance fluctuations: no action - a standard is an average within a range", "id": "acfbe-rv14b-a813a-471253"}], "id": "acfbe-rv14b-a813a-d6d83d"}, {"t": "pt", "text": "Use control limits or trends to decide which variances are significant", "id": "acfbe-rv14b-a813a-785605"}], "id": "acfbe-rv14b-a813a"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Valuing the sales volume variance at selling price - use standard profit (absorption) or standard contribution (marginal)", "id": "acfbe-rv14b-6483a-ca481b"}, {"t": "x", "text": "Including a fixed overhead volume variance in a marginal costing operating statement", "id": "acfbe-rv14b-6483a-aec1f2"}, {"t": "x", "text": "Using budgeted quantity in the selling price variance - it uses ACTUAL quantity sold", "id": "acfbe-rv14b-6483a-f3db5c"}, {"t": "x", "text": "Subtracting favourable variances in the reconciliation", "id": "acfbe-rv14b-6483a-01d46f"}], "id": "acfbe-rv14b-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Selling price variance = (AP - SP) x actual units sold", "id": "acfbe-rv14b-80e78-b57eb6"}, {"t": "pt", "text": "Sales volume = (actual - budgeted units) x std profit (absorption)", "id": "acfbe-rv14b-80e78-486c7b"}, {"t": "pt", "text": "Marginal: sales volume x std contribution", "id": "acfbe-rv14b-80e78-19068a"}, {"t": "pt", "text": "Operating statement reconciles budgeted to actual profit", "id": "acfbe-rv14b-80e78-b944e2"}, {"t": "pt", "text": "Add favourable, deduct adverse", "id": "acfbe-rv14b-80e78-035d2b"}, {"t": "pt", "text": "Marginal costing: no FOH volume variance", "id": "acfbe-rv14b-80e78-508f16"}, {"t": "pt", "text": "Marginal costing: deduct actual fixed overhead", "id": "acfbe-rv14b-80e78-753455"}, {"t": "pt", "text": "Actual = standard ± variance", "id": "acfbe-rv14b-80e78-d4dc85"}, {"t": "pt", "text": "Investigate when benefits exceed costs", "id": "acfbe-rv14b-80e78-9c6d14"}, {"t": "pt", "text": "Causes: measurement, out-of-date standard, (in)efficiency, chance", "id": "acfbe-rv14b-80e78-f88a60"}, {"t": "pt", "text": "Price cut: price A, volume F", "id": "acfbe-rv14b-80e78-c1b24d"}, {"t": "pt", "text": "Revise standards that are out of date", "id": "acfbe-rv14b-80e78-2a53d3"}], "id": "acfbe-rv14b-80e78"}], "source": "BPP Workbook ch 14b: sections 1-5 pp516-528", "summary": "Selling price and sales volume variances, operating statements under absorption and marginal costing, deriving actual data from variances and control action.", "id": "acfbe-rv14b", "updated": "2026-11-12"}, {"num": "15", "title": "Target Setting", "pages": [535, 546], "syllabus": "F1", "status": "published", "branches": [{"kind": "concept", "title": "Mission", "page": [536, 538], "items": [{"t": "def", "k": 1, "term": "Mission statement", "text": "A formal statement of an organisation's mission describing its basic purpose and what it is trying to achieve", "id": "acfbe-rv15-6c654-3022ac"}, {"t": "pt", "k": 1, "text": "Elements of mission: purpose (why the company exists) • strategy (competitive position and distinctive competence) • policies and standards of behaviour • values (beliefs and culture)", "id": "acfbe-rv15-6c654-0d74bc"}, {"t": "pt", "text": "Importance: values are integral to consumer appeal, guides employees, links to planning; can be bland or ignored in practice", "id": "acfbe-rv15-6c654-05bcf5"}, {"t": "pt", "text": "The mission statement guides strategy formulation and the objectives that cascade from it", "id": "acfbe-rv15-6c654-686cb1"}], "id": "acfbe-rv15-6c654"}, {"kind": "concept", "title": "Goals, objectives, CSFs and KPIs", "page": [538, 541], "items": [{"t": "pt", "k": 1, "text": "A hierarchy of SMART objectives cascades downwards from the mission statement", "id": "acfbe-rv15-da8fc-86ecc4"}, {"t": "pt", "k": 1, "text": "SMART: specific • measurable • attainable (achievable) • relevant • time-bound", "id": "acfbe-rv15-da8fc-cdb3a1"}, {"t": "pt", "text": "Objectives may be long term or short term, and strategic (corporate), tactical or operational", "id": "acfbe-rv15-da8fc-98b84a"}, {"t": "pt", "text": "Strategic objectives: quantified statements of what the organisation actually aims to achieve (eg profitability, market share, growth)", "id": "acfbe-rv15-da8fc-32c9e2"}, {"t": "def", "k": 1, "term": "Critical success factor (CSF)", "text": "A performance requirement that is fundamental to competitive success", "id": "acfbe-rv15-da8fc-e7b7c5"}, {"t": "def", "k": 1, "term": "Key performance indicator (KPI)", "text": "A quantifiable measure used to assess whether a CSF is being achieved", "id": "acfbe-rv15-da8fc-2d0aa9"}, {"t": "pt", "text": "Link: mission -> objectives -> CSFs -> KPIs", "id": "acfbe-rv15-da8fc-3e85bd"}, {"t": "eg", "text": "CSF: excellent customer service -> KPIs: % complaints, average response time", "id": "acfbe-rv15-da8fc-7003ee"}, {"t": "exam", "text": "If asked to recommend performance indicators, recommend KPIs (measurable) rather than CSFs", "id": "acfbe-rv15-da8fc-f3fa33"}], "id": "acfbe-rv15-da8fc"}, {"kind": "concept", "title": "Short-termism", "page": [541, 541], "items": [{"t": "def", "k": 1, "term": "Short-termism", "text": "A bias towards short-term rather than long-term performance (eg cutting R&D or training to boost this year's profit)", "id": "acfbe-rv15-90466-68ef02"}, {"t": "pt", "text": "Encourage a long-term view: multiple and non-financial measures, long-term targets, share-based rewards, evaluating over several periods, a balanced scorecard approach", "id": "acfbe-rv15-90466-0c7cdb"}], "id": "acfbe-rv15-90466"}, {"kind": "process", "title": "Benchmarking", "page": [542, 543], "items": [{"t": "def", "k": 1, "term": "Benchmarking", "text": "An attempt to identify best practices and, by comparison of operations, achieve improved performance", "id": "acfbe-rv15-a8d7e-d6e8f7"}, {"t": "pt", "text": "Types: internal (other units within the organisation), functional/operational (best practice in a function, any industry), competitive (direct competitors), strategic (competitors' strategic decisions)", "id": "acfbe-rv15-a8d7e-a9271b"}, {"t": "pt", "text": "Financial information about competitors is easier to obtain than non-financial information", "id": "acfbe-rv15-a8d7e-d854b6"}, {"t": "pt", "text": "Benefits: establishes attainable standards from real best practice, identifies improvement areas, motivates; problems: competitors may not share data, cost, focus on catching up rather than leading", "id": "acfbe-rv15-a8d7e-2ec880"}], "id": "acfbe-rv15-a8d7e"}, {"kind": "concept", "title": "External conditions", "page": [543, 544], "items": [{"t": "pt", "text": "External conditions affect performance and should be considered when setting targets", "id": "acfbe-rv15-4c613-50e7e0"}, {"t": "pt", "text": "Government influence: regulation, taxation, subsidies, environmental and employment law", "id": "acfbe-rv15-4c613-674d9b"}, {"t": "pt", "text": "Market conditions: economic cycle, competition, consumer demand, exchange and interest rates", "id": "acfbe-rv15-4c613-0bac43"}, {"t": "pt", "text": "Targets should be adjusted for uncontrollable external factors so managers are judged fairly", "id": "acfbe-rv15-4c613-228d14"}], "id": "acfbe-rv15-4c613"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Recommending a CSF (eg 'good service') when the question asks for a measurable KPI", "id": "acfbe-rv15-6483a-3582c3"}, {"t": "x", "text": "Writing vague objectives that are not measurable or time-bound", "id": "acfbe-rv15-6483a-ea5d86"}, {"t": "x", "text": "Treating the mission statement as a set of numerical targets - it is a broad statement of purpose", "id": "acfbe-rv15-6483a-1f0239"}, {"t": "x", "text": "Ignoring external factors when judging managers against targets", "id": "acfbe-rv15-6483a-384767"}], "id": "acfbe-rv15-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Mission = purpose of the organisation", "id": "acfbe-rv15-80e78-46f9e6"}, {"t": "pt", "text": "Mission elements: purpose, strategy, policies/standards, values", "id": "acfbe-rv15-80e78-5839dc"}, {"t": "pt", "text": "Objectives cascade from the mission", "id": "acfbe-rv15-80e78-082f77"}, {"t": "pt", "text": "SMART: specific, measurable, attainable, relevant, time-bound", "id": "acfbe-rv15-80e78-31131f"}, {"t": "pt", "text": "Objectives: strategic, tactical, operational", "id": "acfbe-rv15-80e78-2af1f2"}, {"t": "pt", "text": "CSF = what must go right for success", "id": "acfbe-rv15-80e78-d0ecd3"}, {"t": "pt", "text": "KPI = measurable indicator of a CSF", "id": "acfbe-rv15-80e78-5c0ca8"}, {"t": "pt", "text": "Mission -> objectives -> CSFs -> KPIs", "id": "acfbe-rv15-80e78-e84c8b"}, {"t": "pt", "text": "Short-termism sacrifices long-term value", "id": "acfbe-rv15-80e78-bc3660"}, {"t": "pt", "text": "Counter short-termism with long-term and non-financial measures", "id": "acfbe-rv15-80e78-52186a"}, {"t": "pt", "text": "Benchmarking: internal, functional, competitive, strategic", "id": "acfbe-rv15-80e78-4372e2"}, {"t": "pt", "text": "Adjust targets for uncontrollable external conditions", "id": "acfbe-rv15-80e78-7b96aa"}], "id": "acfbe-rv15-80e78"}], "source": "BPP Workbook ch 15: sections 1-4 pp536-544", "summary": "Mission statements, SMART goals and objectives, critical success factors and KPIs, short-termism, benchmarking and the external conditions that affect performance.", "id": "acfbe-rv15", "updated": "2026-11-12"}, {"num": "16", "title": "Financial Performance Measurement", "pages": [547, 580], "syllabus": "F2, F3", "status": "published", "branches": [{"kind": "formula", "title": "Profitability measures", "page": [548, 555], "items": [{"t": "pt", "k": 1, "text": "Performance measures split into financial and non-financial measures", "id": "acfbe-rv16-185a7-dd340b"}, {"t": "f", "k": 1, "term": "Return on investment (ROI / ROCE)", "text": "Profit / Capital employed x 100%", "vars": "for a division use controllable (traceable) profit / controllable investment; capital employed = non-current assets + investments + current assets - current liabilities", "eg": "Traceable profit $5m / investment $20m = 25%", "id": "acfbe-rv16-185a7-049cdc"}, {"t": "f", "k": 1, "term": "Residual income (RI)", "text": "Controllable profit - Imputed interest charge on controllable investment", "vars": "imputed interest = investment x cost of capital (notional)", "eg": "$5m - (10% x $20m) = $3m", "id": "acfbe-rv16-185a7-03233e"}, {"t": "pt", "text": "ROI is relative (%); RI is absolute ($) - RI encourages managers to accept projects earning above the cost of capital, whereas ROI may make them reject projects that would lower the division's ROI", "id": "acfbe-rv16-185a7-ac19eb"}, {"t": "pt", "text": "Common disadvantages: short-termism, distorted by asset values (old depreciated assets give a high ROI), manipulable", "id": "acfbe-rv16-185a7-e8e28c"}, {"t": "f", "term": "Return on equity (ROE)", "text": "Net income / Shareholders' equity", "vars": "profit attributable to shareholders against their investment", "id": "acfbe-rv16-185a7-1c24d8"}, {"t": "f", "k": 1, "term": "Profit margin", "text": "Profit / Revenue x 100%", "vars": "gross profit margin uses gross profit; analyse cost/sales ratios (production, distribution, admin costs as % of sales)", "id": "acfbe-rv16-185a7-4c93c3"}, {"t": "f", "term": "Productivity", "text": "Output / Resources input", "vars": "eg invoices processed per hour", "id": "acfbe-rv16-185a7-964bb1"}], "id": "acfbe-rv16-185a7"}, {"kind": "formula", "title": "Statement of financial position measures", "page": [556, 562], "items": [{"t": "f", "k": 1, "term": "Asset turnover", "text": "Sales / Capital employed", "vars": "how well assets generate sales", "id": "acfbe-rv16-91512-14ff0a"}, {"t": "f", "k": 1, "term": "ROI link", "text": "Profit margin x Asset turnover = ROI", "vars": "(Profit/Sales) x (Sales/Capital employed)", "id": "acfbe-rv16-91512-beff25"}, {"t": "f", "k": 1, "term": "Current ratio", "text": "Current assets / Current liabilities", "vars": "the standard test of liquidity", "id": "acfbe-rv16-91512-e0db04"}, {"t": "f", "k": 1, "term": "Quick (acid test) ratio", "text": "(Current assets - Inventories) / Current liabilities", "vars": "excludes inventory, the least liquid current asset", "id": "acfbe-rv16-91512-3e3482"}, {"t": "f", "term": "Receivables collection period", "text": "Trade receivables / Credit sales x 365 days", "id": "acfbe-rv16-91512-2f5ff5"}, {"t": "f", "term": "Inventory turnover period", "text": "Inventory / Cost of sales x 365 days", "vars": "14,000 / 42,000 x 365 = 122 days", "id": "acfbe-rv16-91512-cd4a20"}, {"t": "f", "term": "Payables payment period", "text": "Trade payables / Purchases (or cost of sales) x 365 days", "id": "acfbe-rv16-91512-65a264"}, {"t": "pt", "text": "Working capital (cash operating) cycle = inventory days + receivables days - payables days", "id": "acfbe-rv16-91512-2c0f05"}, {"t": "f", "term": "Gearing", "text": "Long-term debt / (Debt + Equity) (or debt / equity)", "vars": "higher gearing = higher financial risk", "id": "acfbe-rv16-91512-88bf2a"}, {"t": "f", "term": "Interest cover", "text": "Profit before interest and tax / Interest", "vars": "can the company pay its interest?", "id": "acfbe-rv16-91512-a86004"}, {"t": "pt", "text": "Limitations: one ratio means little alone - compare with prior years, budgets, other divisions or competitors; historic data; accounting policies differ", "id": "acfbe-rv16-91512-2948f4"}, {"t": "exam", "text": "You may not be given capital employed directly and may be given several profit figures - choose the right ones", "id": "acfbe-rv16-91512-b90d33"}], "id": "acfbe-rv16-91512"}, {"kind": "concept", "title": "Management performance and cost reduction", "page": [566, 572], "items": [{"t": "pt", "text": "Management performance measures: subjective (ranking), judgement of outsiders, upward appraisal, accounting measures linked to controllable items", "id": "acfbe-rv16-89ca7-1fe86e"}, {"t": "pt", "k": 1, "text": "Cost CONTROL: keeping costs within acceptable limits (eg budgets and standards)", "id": "acfbe-rv16-89ca7-96b3a2"}, {"t": "pt", "k": 1, "text": "Cost REDUCTION: a planned and positive approach to reducing the unit cost of goods or services below current levels without reducing their suitability for use", "id": "acfbe-rv16-89ca7-322d8c"}, {"t": "pt", "text": "Cost reduction methods: improving efficiency, reducing material costs (cheaper sources, less waste), labour costs (work study, O&M), finance costs, rationalisation after mergers, control over spending decisions", "id": "acfbe-rv16-89ca7-39d1c7"}, {"t": "def", "term": "Work study", "text": "A means of raising productivity by reorganising work - method study and work measurement", "id": "acfbe-rv16-89ca7-a61785"}, {"t": "pt", "text": "Organisation and methods (O&M): work study applied to clerical and administrative work", "id": "acfbe-rv16-89ca7-cc51ff"}], "id": "acfbe-rv16-89ca7"}, {"kind": "process", "title": "Value analysis", "page": [573, 575], "items": [{"t": "def", "k": 1, "term": "Value analysis (VA)", "text": "A planned, scientific approach to cost reduction which reviews the material composition of a product and its design so that modifications can reduce cost without reducing value to the customer", "id": "acfbe-rv16-2a2bd-07fc5c"}, {"t": "pt", "k": 1, "text": "Four aspects of value: cost value (cost to produce and sell) • exchange value (market value) • use value (what it does) • esteem value (prestige to the owner)", "id": "acfbe-rv16-2a2bd-54df9d"}, {"t": "pt", "text": "VA keeps use and esteem value while reducing cost value", "id": "acfbe-rv16-2a2bd-2f8f62"}, {"t": "pt", "text": "Steps: select a product -> obtain and record information -> analyse functions -> consider alternatives -> select the least-cost alternative -> recommend -> implement -> evaluate", "id": "acfbe-rv16-2a2bd-6c57c2"}, {"t": "pt", "text": "Carried out by a team of experts with varying backgrounds", "id": "acfbe-rv16-2a2bd-7b9bb9"}], "id": "acfbe-rv16-2a2bd"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using total company profit instead of controllable profit to judge a divisional manager", "id": "acfbe-rv16-6483a-018a28"}, {"t": "x", "text": "Thinking ROI and RI always lead to the same decision - ROI can cause rejection of worthwhile projects", "id": "acfbe-rv16-6483a-54fbab"}, {"t": "x", "text": "Including inventory in the quick ratio", "id": "acfbe-rv16-6483a-5f6d7d"}, {"t": "x", "text": "Treating cost control and cost reduction as the same thing", "id": "acfbe-rv16-6483a-adc013"}], "id": "acfbe-rv16-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "ROI = profit / capital employed", "id": "acfbe-rv16-80e78-f79044"}, {"t": "pt", "text": "RI = controllable profit - imputed interest", "id": "acfbe-rv16-80e78-77caad"}, {"t": "pt", "text": "ROI relative; RI absolute", "id": "acfbe-rv16-80e78-dce7bb"}, {"t": "pt", "text": "Profit margin x asset turnover = ROI", "id": "acfbe-rv16-80e78-7c2aa6"}, {"t": "pt", "text": "Current ratio = CA / CL", "id": "acfbe-rv16-80e78-713871"}, {"t": "pt", "text": "Quick ratio = (CA - inventory) / CL", "id": "acfbe-rv16-80e78-a09ac2"}, {"t": "pt", "text": "Receivables days = receivables / credit sales x 365", "id": "acfbe-rv16-80e78-d3aa27"}, {"t": "pt", "text": "Inventory days = inventory / COS x 365", "id": "acfbe-rv16-80e78-fbd907"}, {"t": "pt", "text": "Payables days = payables / purchases x 365", "id": "acfbe-rv16-80e78-1b5d6d"}, {"t": "pt", "text": "Gearing = debt / (debt + equity)", "id": "acfbe-rv16-80e78-fc9c83"}, {"t": "pt", "text": "Interest cover = PBIT / interest", "id": "acfbe-rv16-80e78-9ba1a2"}, {"t": "pt", "text": "Cost reduction is planned and permanent; cost control keeps to targets", "id": "acfbe-rv16-80e78-52b129"}, {"t": "pt", "text": "Value: cost, exchange, use, esteem", "id": "acfbe-rv16-80e78-5d4304"}], "id": "acfbe-rv16-80e78"}], "source": "BPP Workbook ch 16: sections 1-6 pp548-575", "summary": "Financial performance measures: ROI, residual income, ROE, margins, asset turnover, liquidity, efficiency and gearing ratios, management performance measures, cost control vs cost reduction, and value analysis.", "id": "acfbe-rv16", "updated": "2026-11-12"}, {"num": "17", "title": "Assessing Non-Financial Performance", "pages": [581, 606], "syllabus": "F4, F5", "status": "published", "branches": [{"kind": "concept", "title": "Non-financial objectives and indicators", "page": [583, 586], "items": [{"t": "pt", "k": 1, "text": "Non-financial objectives include the welfare of employees and society, product quality, customer satisfaction and the environment", "id": "acfbe-rv17-4c7d0-b1879f"}, {"t": "pt", "text": "Use of non-financial performance indicators (NFPIs) has increased with changes in cost structures, competition and manufacturing methods", "id": "acfbe-rv17-4c7d0-35f4f1"}, {"t": "pt", "text": "NFPIs: quick to produce, harder to manipulate, measure drivers of future financial performance", "id": "acfbe-rv17-4c7d0-b42139"}, {"t": "pt", "text": "Sales: customer rejections/returns, deliveries late, complaints, market share, repeat orders", "id": "acfbe-rv17-4c7d0-644685"}, {"t": "pt", "text": "Materials: quality of supplies, delivery reliability, wastage; labour: absenteeism, labour turnover, training hours, productivity; overheads: machine down time, set-up time", "id": "acfbe-rv17-4c7d0-e38060"}], "id": "acfbe-rv17-4c7d0"}, {"kind": "formula", "title": "Standard hour ratios", "page": [586, 587], "items": [{"t": "def", "k": 1, "term": "Standard hour", "text": "The quantity of work achievable at standard performance in one hour - a common unit for different products", "id": "acfbe-rv17-6723e-bea519"}, {"t": "f", "k": 1, "term": "Efficiency ratio", "text": "Standard hours produced / Actual hours worked x 100%", "vars": "how efficiently hours were used", "id": "acfbe-rv17-6723e-07ee8c"}, {"t": "f", "k": 1, "term": "Capacity ratio", "text": "Actual hours worked / Budgeted hours x 100%", "vars": "Nico: 1,200 / 1,100 = 109%", "id": "acfbe-rv17-6723e-2f9cb6"}, {"t": "f", "k": 1, "term": "Activity (production volume) ratio", "text": "Standard hours produced / Budgeted hours x 100%", "vars": "= efficiency x capacity", "id": "acfbe-rv17-6723e-8156b9"}], "id": "acfbe-rv17-6723e"}, {"kind": "compare", "title": "The balanced scorecard", "page": [588, 590], "items": [{"t": "table", "rows": [["Perspective", "Question", "Example measures"], ["Financial", "How do we look to shareholders?", "ROI, profit growth, cash flow"], ["Customer", "How do customers see us?", "Customer satisfaction, retention, market share, delivery times"], ["Internal business process", "What must we excel at?", "Cycle time, quality, productivity, cost"], ["Innovation and learning", "Can we continue to improve and create value?", "% sales from new products, training, time to market"]], "id": "acfbe-rv17-7fa9e-cd9954"}, {"t": "pt", "k": 1, "text": "The balanced scorecard measures performance from four perspectives - financial AND non-financial - avoiding a focus on short-term profit", "id": "acfbe-rv17-7fa9e-fe1f88"}, {"t": "pt", "text": "Advantages: balanced view, links measures to strategy, highlights trade-offs; disadvantages: conflicting measures, too many measures, selecting and interpreting measures is subjective", "id": "acfbe-rv17-7fa9e-739c92"}, {"t": "exam", "text": "KPIs should be specific, measurable, relevant to the objective, and linked to the strategy", "id": "acfbe-rv17-7fa9e-64fda4"}], "id": "acfbe-rv17-7fa9e"}, {"kind": "concept", "title": "Not-for-profit and public sector: the 3Es", "page": [591, 597], "items": [{"t": "pt", "k": 1, "text": "Problems of performance measurement in the public sector: lack of a profit measure, multiple objectives and different expectations, political, social and legal considerations, outputs hard to measure, nature of the service, financial constraints", "id": "acfbe-rv17-9fa9d-259fa4"}, {"t": "pt", "k": 1, "text": "The 3Es", "kids": [{"t": "def", "term": "Economy", "text": "Obtaining inputs of the appropriate quality at the lowest cost (spending less)", "id": "acfbe-rv17-9fa9d-e8ab27"}, {"t": "def", "term": "Efficiency", "text": "Getting the maximum output from the inputs used (spending well) - output/input", "id": "acfbe-rv17-9fa9d-77fe4a"}, {"t": "def", "term": "Effectiveness", "text": "The extent to which outputs achieve the organisation's objectives (spending wisely)", "id": "acfbe-rv17-9fa9d-6b9e91"}], "id": "acfbe-rv17-9fa9d-17bb47"}, {"t": "pt", "text": "Value for money = economy + efficiency + effectiveness", "id": "acfbe-rv17-9fa9d-14c166"}, {"t": "pt", "text": "Other solutions: judge inputs, use judgement, comparisons with similar bodies, quantitative unit cost measures (eg cost per patient day, cost of borrowing one library book)", "id": "acfbe-rv17-9fa9d-26d608"}, {"t": "exam", "text": "The examining team noted 'imprecise' knowledge of the 3Es - know each definition exactly", "id": "acfbe-rv17-9fa9d-9bb168"}, {"t": "pt", "text": "Central and local government publish performance indicators and league tables", "id": "acfbe-rv17-9fa9d-f94074"}], "id": "acfbe-rv17-9fa9d"}, {"kind": "concept", "title": "Contract and process environments", "page": [598, 598], "items": [{"t": "pt", "text": "Measures should suit the costing environment", "id": "acfbe-rv17-3f71c-ebe328"}, {"t": "pt", "text": "Contracts: completion on time and within budget, profit per contract, client satisfaction", "id": "acfbe-rv17-3f71c-b2e4b7"}, {"t": "pt", "text": "Process industries: yield, normal/abnormal loss rates, throughput, down time, quality", "id": "acfbe-rv17-3f71c-cd126f"}], "id": "acfbe-rv17-3f71c"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Mixing up economy (cost of inputs) and efficiency (output per input)", "id": "acfbe-rv17-6483a-04f796"}, {"t": "x", "text": "Calling effectiveness 'doing things cheaply' - it is achieving objectives", "id": "acfbe-rv17-6483a-bfe0be"}, {"t": "x", "text": "Forgetting the innovation and learning perspective of the balanced scorecard", "id": "acfbe-rv17-6483a-d2604d"}, {"t": "x", "text": "Using capacity ratio as a measure of how fast work was done - that is efficiency", "id": "acfbe-rv17-6483a-d01ac7"}], "id": "acfbe-rv17-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "NFPIs measure quality, delivery, satisfaction, staff, environment", "id": "acfbe-rv17-80e78-2e3310"}, {"t": "pt", "text": "NFPIs are harder to manipulate and predict future results", "id": "acfbe-rv17-80e78-43b5c7"}, {"t": "pt", "text": "Efficiency = standard hours produced / actual hours", "id": "acfbe-rv17-80e78-fd1b56"}, {"t": "pt", "text": "Capacity = actual hours / budgeted hours", "id": "acfbe-rv17-80e78-e2ad30"}, {"t": "pt", "text": "Activity = standard hours produced / budgeted hours", "id": "acfbe-rv17-80e78-a86084"}, {"t": "pt", "text": "Activity = efficiency x capacity", "id": "acfbe-rv17-80e78-99f1d1"}, {"t": "pt", "text": "Balanced scorecard: financial, customer, internal process, innovation and learning", "id": "acfbe-rv17-80e78-3878ca"}, {"t": "pt", "text": "Public sector: no profit measure, multiple objectives, hard-to-measure outputs", "id": "acfbe-rv17-80e78-3bf502"}, {"t": "pt", "text": "Economy = lowest-cost inputs", "id": "acfbe-rv17-80e78-3debb1"}, {"t": "pt", "text": "Efficiency = maximum output per input", "id": "acfbe-rv17-80e78-c8f82e"}, {"t": "pt", "text": "Effectiveness = objectives achieved", "id": "acfbe-rv17-80e78-ccf84a"}, {"t": "pt", "text": "VFM = the 3Es", "id": "acfbe-rv17-80e78-abfc7d"}], "id": "acfbe-rv17-80e78"}], "source": "BPP Workbook ch 17: sections 1-5 pp583-598", "summary": "Non-financial objectives and indicators, measures for sales, materials, labour and overheads, efficiency/activity/capacity ratios, the balanced scorecard, the 3Es for not-for-profit and public sector bodies, and measures for contract and process environments.", "id": "acfbe-rv17", "updated": "2026-11-12"}], "plannedChapters": 26}, {"id": "acffa1st", "code": "FA1", "name": "Recording Financial Transactions", "level": "Foundations in Accountancy", "book": "ACCA-FA1-ST.pdf | Kaplan FIA FA1 Study Text (2022-2023) | offset 14", "updated": "2026-11-12", "chapters": [{"num": "1", "title": "Business Transactions", "pages": [1, 12], "syllabus": "A1", "status": "published", "branches": [{"kind": "concept", "title": "Types of transaction", "page": [2, 3], "items": [{"t": "pt", "k": 1, "text": "Main transactions: sales • purchases • receiving money • paying money (expenses, wages, suppliers) • buying non-current assets", "id": "acffa1st-rv1-f9e51-f73ed8"}, {"t": "pt", "k": 1, "text": "Cash transaction: payment made at the time of the transaction (notes, cheque, card)", "id": "acffa1st-rv1-f9e51-57dc40"}, {"t": "pt", "k": 1, "text": "Credit transaction: goods or services supplied now, paid for later - creates a receivable (seller) or payable (buyer)", "id": "acffa1st-rv1-f9e51-541d7b"}, {"t": "eg", "text": "A client pays a hairdresser $20 cash for a haircut = a cash sale for the hairdresser", "id": "acffa1st-rv1-f9e51-2e5c8f"}], "id": "acffa1st-rv1-f9e51"}, {"kind": "def", "title": "Key terms", "page": [3, 9], "items": [{"t": "def", "k": 1, "term": "Sales", "text": "The exchange of goods or services for money (also called commission or fees for some services)", "id": "acffa1st-rv1-01454-388e85"}, {"t": "def", "k": 1, "term": "Purchases", "text": "Buying goods for RESALE", "id": "acffa1st-rv1-01454-e14688"}, {"t": "def", "k": 1, "term": "Expenses", "text": "Money spent on rent, electricity, telephone and so on - NOT purchases of goods for resale", "id": "acffa1st-rv1-01454-51c3e2"}, {"t": "def", "term": "Income", "text": "A wider term than sales - also includes interest received and rent received", "id": "acffa1st-rv1-01454-32755a"}, {"t": "def", "term": "Account", "text": "A record of similar financial transactions in a business", "id": "acffa1st-rv1-01454-932afb"}, {"t": "def", "term": "Ledger", "text": "A set of related accounts", "id": "acffa1st-rv1-01454-827fdc"}, {"t": "def", "term": "Petty cash", "text": "A small amount of cash held for the payment of (minor) expenses", "id": "acffa1st-rv1-01454-f8f476"}, {"t": "def", "term": "Payroll", "text": "A list of employees and the wages or salaries due to each", "id": "acffa1st-rv1-01454-4cf853"}, {"t": "def", "term": "Receipt", "text": "A written statement of an amount of money that has been paid/received", "id": "acffa1st-rv1-01454-9aa2c2"}, {"t": "def", "term": "Till roll", "text": "Printed listing of all payments received through a till in a retail outlet", "id": "acffa1st-rv1-01454-191b5a"}], "id": "acffa1st-rv1-01454"}, {"kind": "concept", "title": "Payments, records and personnel", "page": [4, 7], "items": [{"t": "pt", "text": "Methods of payment: cash, cheque, debit/credit card, bank transfer (eg BACS), standing order, direct debit", "id": "acffa1st-rv1-2c1dd-388289"}, {"t": "pt", "text": "Payroll: weekly-paid (wages) or monthly-paid (salaries) employees, with deductions for tax and benefit contributions", "id": "acffa1st-rv1-2c1dd-beb742"}, {"t": "pt", "k": 1, "text": "Keeping a record: every transaction must be recorded from source documents into the accounting records", "id": "acffa1st-rv1-2c1dd-d499f2"}, {"t": "pt", "text": "Key personnel: sales staff, purchasing, payroll, accounts staff, cashier, managers authorising transactions", "id": "acffa1st-rv1-2c1dd-69aa1f"}], "id": "acffa1st-rv1-2c1dd"}, {"kind": "rule", "title": "Control over transactions", "page": [7, 7], "items": [{"t": "pt", "k": 1, "text": "Internal checks and controls protect assets and ensure accurate records", "id": "acffa1st-rv1-2f697-fe561d"}, {"t": "pt", "text": "Examples: reconciling cash in the till to the till roll; checking invoices against orders and delivery notes; authorisation of payments; segregation of duties", "id": "acffa1st-rv1-2f697-44d72a"}, {"t": "pt", "text": "Timing: a transaction must be recorded in the correct accounting period (when it occurs, not necessarily when cash moves)", "id": "acffa1st-rv1-2f697-0ad984"}, {"t": "exam", "text": "Expect MCQs asking whether an item is a purchase (for resale) or an expense", "id": "acffa1st-rv1-2f697-a9a5eb"}], "id": "acffa1st-rv1-2f697"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calling the purchase of office furniture a 'purchase' - purchases are goods for resale; furniture is an asset", "id": "acffa1st-rv1-6483a-a3cea7"}, {"t": "x", "text": "Treating a credit sale as cash received", "id": "acffa1st-rv1-6483a-83fe70"}, {"t": "x", "text": "Thinking 'income' only means sales", "id": "acffa1st-rv1-6483a-8b1a2f"}, {"t": "x", "text": "Ignoring the period in which a transaction occurs", "id": "acffa1st-rv1-6483a-02aad4"}], "id": "acffa1st-rv1-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Transactions: sales, purchases, receipts, payments, assets", "id": "acffa1st-rv1-80e78-f523d7"}, {"t": "pt", "text": "Cash transaction: paid immediately", "id": "acffa1st-rv1-80e78-5c5317"}, {"t": "pt", "text": "Credit transaction: paid later -> receivable/payable", "id": "acffa1st-rv1-80e78-6db2a7"}, {"t": "pt", "text": "Purchases = goods for resale", "id": "acffa1st-rv1-80e78-f7798e"}, {"t": "pt", "text": "Expenses = running costs, not goods for resale", "id": "acffa1st-rv1-80e78-94607c"}, {"t": "pt", "text": "Income includes interest and rent received", "id": "acffa1st-rv1-80e78-5912ab"}, {"t": "pt", "text": "Account = record of similar transactions", "id": "acffa1st-rv1-80e78-5c42cf"}, {"t": "pt", "text": "Ledger = set of related accounts", "id": "acffa1st-rv1-80e78-f5525d"}, {"t": "pt", "text": "Petty cash = small float for minor expenses", "id": "acffa1st-rv1-80e78-6ae32d"}, {"t": "pt", "text": "Payroll = list of employees and pay due", "id": "acffa1st-rv1-80e78-298cdd"}, {"t": "pt", "text": "Controls: reconciliations, authorisation, checking documents", "id": "acffa1st-rv1-80e78-1073d1"}, {"t": "pt", "text": "Record transactions in the right period", "id": "acffa1st-rv1-80e78-a09e62"}], "id": "acffa1st-rv1-80e78"}], "source": "Kaplan FA1 Study Text ch 1: sections 1-9 pp2-8; key terms p9", "summary": "The main types of business transaction, cash vs credit, terminology, methods of payment, petty cash, payroll, keeping records, key personnel, control and timing of transactions.", "id": "acffa1st-rv1", "updated": "2026-11-12"}, {"num": "2", "title": "Types of Business Documentation", "pages": [13, 36], "syllabus": "A2", "status": "published", "branches": [{"kind": "process", "title": "Credit purchase cycle", "page": [18, 25], "items": [{"t": "pt", "k": 1, "text": "Purchase requisition (internal, authorised) -> purchase order (to the supplier) -> delivery note (with goods) -> goods received note (GRN) -> purchase invoice -> checked to order and GRN -> payment with remittance advice", "id": "acffa1st-rv2-9ed55-d1f3b0"}, {"t": "pt", "text": "Internal cheque requisition: completed by junior staff, authorised by senior management before a payment is made", "id": "acffa1st-rv2-9ed55-1d28cd"}, {"t": "pt", "text": "Invoices are particularly important source documents for recording credit sales and purchases", "id": "acffa1st-rv2-9ed55-177585"}, {"t": "pt", "text": "The buyer checks the invoice against the purchase order (price, terms) and the GRN (quantity received)", "id": "acffa1st-rv2-9ed55-a26d99"}], "id": "acffa1st-rv2-9ed55"}, {"kind": "def", "title": "Documents and their purpose", "page": [14, 34], "items": [{"t": "def", "k": 1, "term": "Delivery note", "text": "Document sent with products delivered to a customer - one copy kept by the customer, one signed and retained by the supplier", "id": "acffa1st-rv2-2eadb-1a1ba8"}, {"t": "def", "term": "Advice note", "text": "Issued to a customer advising that a delivery will be made on a specific day and listing the items", "id": "acffa1st-rv2-2eadb-c9dc39"}, {"t": "def", "k": 1, "term": "Credit note", "text": "Document issued to a customer (or received from a supplier) indicating the amount owed is being REDUCED for returns", "id": "acffa1st-rv2-2eadb-dbb20d"}, {"t": "def", "k": 1, "term": "Debit note", "text": "Raised by a CUSTOMER and issued to a supplier to request a credit note (eg for faulty goods returned)", "id": "acffa1st-rv2-2eadb-c0cf92"}, {"t": "def", "term": "Internal cheque requisition", "text": "Form used within a business properly authorising payment to a supplier", "id": "acffa1st-rv2-2eadb-b39cbf"}, {"t": "def", "term": "Payslip", "text": "Document given to each employee showing pay and deductions", "id": "acffa1st-rv2-2eadb-ef3302"}, {"t": "def", "term": "Petty cash voucher", "text": "Document kept in petty cash giving details of money paid out and the reason", "id": "acffa1st-rv2-2eadb-025b29"}, {"t": "pt", "text": "Statement of account: summary sent to a customer of invoices, credit notes, payments and the balance owed", "id": "acffa1st-rv2-2eadb-f3ade7"}], "id": "acffa1st-rv2-2eadb"}, {"kind": "compare", "title": "Credit note vs debit note", "page": [26, 27], "items": [{"t": "table", "rows": [["Feature", "Credit note", "Debit note"], ["Raised by", "The SELLER (supplier)", "The BUYER (customer)"], ["Purpose", "Reduces the amount the customer owes", "Requests a credit note from the supplier"], ["Effect on records", "Recorded in returns day books", "A request only - no accounting entry until the credit note arrives"]], "id": "acffa1st-rv2-8cdb7-99de26"}], "id": "acffa1st-rv2-8cdb7"}, {"kind": "rule", "title": "Petty cash, retention and data protection", "page": [28, 31], "items": [{"t": "pt", "k": 1, "text": "Each petty cash claim must be supported by a receipt and an authorised voucher", "id": "acffa1st-rv2-f6c59-008488"}, {"t": "pt", "text": "Document retention policies keep records for legal, tax and audit purposes for a set period, then destroy securely", "id": "acffa1st-rv2-f6c59-77679e"}, {"t": "pt", "k": 1, "text": "Data protection law (eg UK Data Protection Act 2018 implementing GDPR) governs holding personal data about individuals", "id": "acffa1st-rv2-f6c59-5f1c63"}, {"t": "exam", "text": "A question may ask you to put sales or purchase documents in the order they are produced", "id": "acffa1st-rv2-f6c59-a9181d"}], "id": "acffa1st-rv2-f6c59"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Thinking the debit note is issued by the supplier - it is raised by the customer", "id": "acffa1st-rv2-6483a-da5c8d"}, {"t": "x", "text": "Paying an invoice without matching it to the order and the GRN", "id": "acffa1st-rv2-6483a-b8eed5"}, {"t": "x", "text": "Confusing a delivery note (with the goods) with an advice note (before delivery)", "id": "acffa1st-rv2-6483a-72f8f3"}, {"t": "x", "text": "Paying petty cash claims without receipts or authorisation", "id": "acffa1st-rv2-6483a-5ae2cf"}], "id": "acffa1st-rv2-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Requisition -> order -> delivery note -> GRN -> invoice -> payment", "id": "acffa1st-rv2-80e78-b35e64"}, {"t": "pt", "text": "Remittance advice accompanies payment", "id": "acffa1st-rv2-80e78-fbcccd"}, {"t": "pt", "text": "Invoice checked against order and GRN", "id": "acffa1st-rv2-80e78-fd1772"}, {"t": "pt", "text": "Credit note: seller reduces the amount owed", "id": "acffa1st-rv2-80e78-b8de28"}, {"t": "pt", "text": "Debit note: customer requests a credit note", "id": "acffa1st-rv2-80e78-b17b76"}, {"t": "pt", "text": "Delivery note travels with the goods", "id": "acffa1st-rv2-80e78-a67e87"}, {"t": "pt", "text": "Advice note warns of delivery in advance", "id": "acffa1st-rv2-80e78-38e033"}, {"t": "pt", "text": "Statement of account summarises the balance owed", "id": "acffa1st-rv2-80e78-26f0db"}, {"t": "pt", "text": "Cheque requisition authorises payment internally", "id": "acffa1st-rv2-80e78-7e3007"}, {"t": "pt", "text": "Petty cash needs a voucher and receipt", "id": "acffa1st-rv2-80e78-77fe92"}, {"t": "pt", "text": "Retain documents for legal and tax periods", "id": "acffa1st-rv2-80e78-9822d9"}, {"t": "pt", "text": "Data protection governs personal data", "id": "acffa1st-rv2-80e78-28e508"}], "id": "acffa1st-rv2-80e78"}], "source": "Kaplan FA1 Study Text ch 2: sections 1-10 pp14-33; key terms p34", "summary": "Documents for cash and credit transactions, the credit sale and credit purchase cycles, statements of account, returns with credit and debit notes, petty cash claims, document retention and data protection.", "id": "acffa1st-rv2", "updated": "2026-11-12"}, {"num": "3", "title": "Double Entry Bookkeeping", "pages": [37, 72], "syllabus": "B1", "status": "published", "branches": [{"kind": "def", "title": "Elements and the entity", "page": [38, 42], "items": [{"t": "def", "k": 1, "term": "Asset", "text": "A present economic resource controlled by the entity as a result of past events", "id": "acffa1st-rv3-7b35c-2301fb"}, {"t": "def", "term": "Liability", "text": "A present obligation to transfer an economic resource as a result of past events", "id": "acffa1st-rv3-7b35c-9c87eb"}, {"t": "def", "k": 1, "term": "Capital", "text": "An owner's investment in the business", "id": "acffa1st-rv3-7b35c-9be565"}, {"t": "pt", "text": "Income increases equity; expenses decrease equity (other than owners' contributions or withdrawals)", "id": "acffa1st-rv3-7b35c-b3306a"}, {"t": "pt", "k": 1, "text": "Separate entity concept: the business is accounted for separately from its owner, even if the law treats them as one (sole trader)", "id": "acffa1st-rv3-7b35c-387f8f"}], "id": "acffa1st-rv3-7b35c"}, {"kind": "formula", "title": "The accounting equation", "page": [42, 46], "items": [{"t": "f", "k": 1, "term": "Accounting equation", "text": "Assets = Liabilities + Capital", "vars": "every transaction keeps both sides equal", "id": "acffa1st-rv3-c82f7-e525d1"}, {"t": "f", "term": "Expanded equation", "text": "Assets = Liabilities + Capital + Profit - Drawings", "vars": "profit = income - expenses", "id": "acffa1st-rv3-c82f7-a2e90d"}, {"t": "pt", "k": 1, "text": "Dual aspect: every transaction has TWO effects (eg bank loan: cash asset up, loan liability up)", "id": "acffa1st-rv3-c82f7-077571"}, {"t": "pt", "text": "Inventory bought for resale is an asset until sold; profit from trading = sales - cost of goods sold", "id": "acffa1st-rv3-c82f7-efaf4c"}], "id": "acffa1st-rv3-c82f7"}, {"kind": "rule", "title": "Debits and credits", "page": [47, 58], "items": [{"t": "pt", "k": 1, "text": "Debit (left): increase in an asset or expense (or drawings); decrease in a liability, income or capital", "id": "acffa1st-rv3-bc8f7-72b412"}, {"t": "pt", "k": 1, "text": "Credit (right): increase in a liability, income or capital; decrease in an asset or expense", "id": "acffa1st-rv3-bc8f7-f95561"}, {"t": "pt", "text": "Nominal (general) ledger holds all the accounts in a double entry system", "id": "acffa1st-rv3-bc8f7-9f4851"}, {"t": "def", "k": 1, "term": "Balance on an account", "text": "The amount by which total debits exceed total credits (debit balance) or total credits exceed total debits (credit balance)", "id": "acffa1st-rv3-bc8f7-9f2e3e"}, {"t": "pt", "text": "Balancing off: total both sides, balance c/d on the smaller side, balance b/d on the opposite side", "id": "acffa1st-rv3-bc8f7-f54c76"}, {"t": "eg", "text": "Pay rent by cheque: Dr Rent, Cr Bank; buy goods on credit: Dr Purchases, Cr Payables", "id": "acffa1st-rv3-bc8f7-06aeb3"}], "id": "acffa1st-rv3-bc8f7"}, {"kind": "compare", "title": "Capital vs revenue expenditure", "page": [59, 59], "items": [{"t": "table", "rows": [["Feature", "Capital (asset) expenditure", "Revenue expenditure"], ["What", "Non-current assets used for more than one year", "Day-to-day running costs, repairs, goods for resale"], ["Where", "Statement of financial position (asset)", "Statement of profit or loss (expense)"], ["Example", "Office premises, delivery van", "Rent, wages, purchases for resale"]], "id": "acffa1st-rv3-22ce0-5a62f9"}, {"t": "pt", "text": "Current assets: cash, receivables, inventory - expected to be used within one year", "id": "acffa1st-rv3-22ce0-395dbf"}], "id": "acffa1st-rv3-22ce0"}, {"kind": "concept", "title": "Books of prime entry and computers", "page": [60, 67], "items": [{"t": "def", "k": 1, "term": "Books of prime entry", "text": "Books where a transaction is first recorded (eg sales day book) - also called books of original entry", "id": "acffa1st-rv3-04139-1b97f8"}, {"t": "pt", "text": "Books of prime entry: sales day book, purchase day book, returns day books, cash book, petty cash book, journal", "id": "acffa1st-rv3-04139-09180c"}, {"t": "pt", "text": "Computer advantages: speed, accuracy, volume, automatic posting and reports; disadvantages: no intelligence (garbage in, garbage out), set-up cost, reliance on IT", "id": "acffa1st-rv3-04139-df273d"}, {"t": "pt", "text": "Integrated accounting packages: modules (sales, purchases, nominal, payroll) share data", "id": "acffa1st-rv3-04139-6aa593"}, {"t": "pt", "k": 1, "text": "Coding: each account given a unique code; block/hierarchical codes form a CHART OF ACCOUNTS", "id": "acffa1st-rv3-04139-97acdb"}, {"t": "pt", "text": "Good coding system: unique, brief, comprehensive, flexible (room for expansion), consistent", "id": "acffa1st-rv3-04139-5dfa38"}, {"t": "exam", "text": "Know which book of prime entry records which transaction - a common MCQ", "id": "acffa1st-rv3-04139-0a8c43"}], "id": "acffa1st-rv3-04139"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Recording the owner's personal spending as a business expense - it is drawings", "id": "acffa1st-rv3-6483a-9a5fe2"}, {"t": "x", "text": "Debiting a liability when it increases", "id": "acffa1st-rv3-6483a-ddf553"}, {"t": "x", "text": "Treating office premises as revenue expenditure", "id": "acffa1st-rv3-6483a-8fced1"}, {"t": "x", "text": "Confusing the journal (a book of prime entry) with the ledger", "id": "acffa1st-rv3-6483a-d5c383"}], "id": "acffa1st-rv3-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Assets = liabilities + capital", "id": "acffa1st-rv3-80e78-174515"}, {"t": "pt", "text": "Every transaction has a dual effect", "id": "acffa1st-rv3-80e78-e4d7a5"}, {"t": "pt", "text": "Separate entity: business separate from owner", "id": "acffa1st-rv3-80e78-541254"}, {"t": "pt", "text": "Dr: assets and expenses up", "id": "acffa1st-rv3-80e78-d0e880"}, {"t": "pt", "text": "Cr: liabilities, income and capital up", "id": "acffa1st-rv3-80e78-290482"}, {"t": "pt", "text": "Balance c/d on the smaller side; b/d opposite", "id": "acffa1st-rv3-80e78-e455a4"}, {"t": "pt", "text": "Capital expenditure: long-term assets", "id": "acffa1st-rv3-80e78-630be7"}, {"t": "pt", "text": "Revenue expenditure: running costs", "id": "acffa1st-rv3-80e78-865d09"}, {"t": "pt", "text": "Books of prime entry record transactions first", "id": "acffa1st-rv3-80e78-d96be1"}, {"t": "pt", "text": "Day books, cash book, petty cash book, journal", "id": "acffa1st-rv3-80e78-bd08b8"}, {"t": "pt", "text": "Chart of accounts = coded list of accounts", "id": "acffa1st-rv3-80e78-1a6923"}, {"t": "pt", "text": "Good codes: unique, brief, flexible, consistent", "id": "acffa1st-rv3-80e78-cba413"}], "id": "acffa1st-rv3-80e78"}], "source": "Kaplan FA1 Study Text ch 3: sections 1-11 pp38-67; key terms p68", "summary": "Elements of the financial statements, the separate entity concept, the accounting equation, income, expenses and profit, the dual aspect, debit and credit rules, balancing accounts, capital vs revenue expenditure, books of prime entry and computerised accounting and coding.", "id": "acffa1st-rv3", "updated": "2026-11-12"}, {"num": "4", "title": "Banking: Payments and Receipts", "pages": [73, 104], "syllabus": "C1", "status": "published", "branches": [{"kind": "concept", "title": "Bank and customer", "page": [74, 76], "items": [{"t": "pt", "k": 1, "text": "When a business pays money into its account, the bank becomes a PAYABLE of the business (it owes the money back)", "id": "acffa1st-rv4-31571-629b89"}, {"t": "pt", "text": "Bank's obligations: honour cheques when funds are available, keep accounts confidential, provide statements", "id": "acffa1st-rv4-31571-1902d5"}, {"t": "pt", "text": "Customer's obligations: take reasonable care when drawing cheques to prevent fraud or forgery", "id": "acffa1st-rv4-31571-3ce1f6"}, {"t": "pt", "k": 1, "text": "Clearing banks (eg HSBC, Barclays) process cheques through the central clearing system - takes time", "id": "acffa1st-rv4-31571-41bb35"}, {"t": "pt", "text": "Dishonoured cheque: the paying bank refuses to pay (eg insufficient funds, errors) - returned unpaid", "id": "acffa1st-rv4-31571-1dd8c4"}], "id": "acffa1st-rv4-31571"}, {"kind": "def", "title": "Methods of payment", "page": [76, 87], "items": [{"t": "def", "k": 1, "term": "Crossed cheque", "text": "A cheque with two parallel lines - it must be paid into a bank account", "id": "acffa1st-rv4-d0313-c0758a"}, {"t": "pt", "text": "'A/c payee' crossing: can only be paid into the payee's account - cannot be endorsed to someone else", "id": "acffa1st-rv4-d0313-d70aa5"}, {"t": "def", "k": 1, "term": "Standing order", "text": "An instruction by the customer to the bank to pay a FIXED amount at regular intervals", "id": "acffa1st-rv4-d0313-6994a3"}, {"t": "def", "k": 1, "term": "Direct debit", "text": "An order allowing the PAYEE to collect amounts (which may vary) from the payer's account", "id": "acffa1st-rv4-d0313-fda7d8"}, {"t": "pt", "text": "Credit transfer: instructing the bank to pay a third party; banker's draft: payment guaranteed by the bank", "id": "acffa1st-rv4-d0313-aae064"}, {"t": "def", "k": 1, "term": "BACS", "text": "Automated payments by bank transfer - commonly used for salaries and regular suppliers", "id": "acffa1st-rv4-d0313-2d30a7"}, {"t": "def", "k": 1, "term": "Debit card", "text": "Instant payment from the customer's bank account to a retailer electronically", "id": "acffa1st-rv4-d0313-3d88c2"}, {"t": "def", "k": 1, "term": "Credit card", "text": "Payment from an agreed credit facility; the cardholder settles later with the card company", "id": "acffa1st-rv4-d0313-f9d585"}, {"t": "def", "term": "Charge card", "text": "Like a credit card, but the balance must be paid in full every month", "id": "acffa1st-rv4-d0313-82b0e6"}, {"t": "pt", "text": "Contactless payments: cards or phones for small amounts without a PIN", "id": "acffa1st-rv4-d0313-31bc01"}, {"t": "def", "term": "Designated signatory", "text": "A person authorised to sign cheques in defined circumstances", "id": "acffa1st-rv4-d0313-1b41b0"}], "id": "acffa1st-rv4-d0313"}, {"kind": "process", "title": "Preparing and authorising payments", "page": [80, 89], "items": [{"t": "pt", "text": "Prepare the cheque from the supplier statement or remittance after checking invoices are authorised", "id": "acffa1st-rv4-87072-da11b0"}, {"t": "pt", "k": 1, "text": "Cheque signatories: limits by amount (eg two signatures above a set amount) - the final authorisation of expenditure", "id": "acffa1st-rv4-87072-81acd4"}, {"t": "pt", "text": "Unusual features: payment disagrees with supporting documents, unsigned cheques, wrong dates - investigate before processing", "id": "acffa1st-rv4-87072-f79290"}, {"t": "pt", "text": "Employee expense claims must be supported by receipts and authorised", "id": "acffa1st-rv4-87072-90506c"}], "id": "acffa1st-rv4-87072"}, {"kind": "process", "title": "Banking money received", "page": [90, 99], "items": [{"t": "pt", "k": 1, "text": "Paying-in slip: details of the account, notes and coins by denomination, cheques listed, total - must agree with the money banked", "id": "acffa1st-rv4-6afc8-e83054"}, {"t": "pt", "text": "Check paying-in slips against till rolls, remittance lists and receipts", "id": "acffa1st-rv4-6afc8-27e7de"}, {"t": "pt", "text": "Credit card vouchers/merchant receipts are also banked", "id": "acffa1st-rv4-6afc8-479a7f"}, {"t": "pt", "k": 1, "text": "Security: bank money promptly (same day where possible), keep cash in a safe, limit access, vary banking times, use security services for large amounts", "id": "acffa1st-rv4-6afc8-22d006"}, {"t": "pt", "text": "Bank services: accounts, loans and overdrafts, internet and telephone banking, foreign exchange", "id": "acffa1st-rv4-6afc8-11c2b9"}, {"t": "exam", "text": "Exam-style questions test the effect of an 'account payee' crossing and which payment method suits a scenario (fixed vs variable regular payments)", "id": "acffa1st-rv4-6afc8-e12a81"}], "id": "acffa1st-rv4-6afc8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing a standing order (fixed amount, payer instructs) with a direct debit (payee collects variable amounts)", "id": "acffa1st-rv4-6483a-7ffa2c"}, {"t": "x", "text": "Thinking a charge card allows the balance to be carried forward - it must be paid in full monthly", "id": "acffa1st-rv4-6483a-57c780"}, {"t": "x", "text": "Endorsing an 'A/c payee' cheque to a third party", "id": "acffa1st-rv4-6483a-c6ebda"}, {"t": "x", "text": "Leaving cash unbanked for long periods", "id": "acffa1st-rv4-6483a-6c13df"}], "id": "acffa1st-rv4-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Money in the bank: the bank owes the business", "id": "acffa1st-rv4-80e78-30230d"}, {"t": "pt", "text": "Crossed cheque must be paid into an account", "id": "acffa1st-rv4-80e78-d0072d"}, {"t": "pt", "text": "A/c payee: only the payee's account", "id": "acffa1st-rv4-80e78-3a90ef"}, {"t": "pt", "text": "Standing order: fixed amount, set dates", "id": "acffa1st-rv4-80e78-7a4fc6"}, {"t": "pt", "text": "Direct debit: payee collects variable amounts", "id": "acffa1st-rv4-80e78-b7b5c9"}, {"t": "pt", "text": "BACS: automated bank transfers (wages)", "id": "acffa1st-rv4-80e78-3645df"}, {"t": "pt", "text": "Debit card: instant from the bank account", "id": "acffa1st-rv4-80e78-8e70a3"}, {"t": "pt", "text": "Credit card: credit facility, settle later", "id": "acffa1st-rv4-80e78-e9234d"}, {"t": "pt", "text": "Charge card: pay in full monthly", "id": "acffa1st-rv4-80e78-346284"}, {"t": "pt", "text": "Dishonoured cheque: returned unpaid", "id": "acffa1st-rv4-80e78-e04567"}, {"t": "pt", "text": "Paying-in slip lists notes, coins and cheques", "id": "acffa1st-rv4-80e78-781fd2"}, {"t": "pt", "text": "Bank money promptly and keep it secure", "id": "acffa1st-rv4-80e78-434ed2"}, {"t": "pt", "text": "Signatories authorise payments within limits", "id": "acffa1st-rv4-80e78-f740ce"}], "id": "acffa1st-rv4-80e78"}], "source": "Kaplan FA1 Study Text ch 4: sections 1-10 pp74-101; key terms p102", "summary": "The bank-customer relationship, the clearing system and dishonoured cheques, types of payment (cheques, crossings, standing orders, direct debits, transfers, cards, BACS), cheque signatories, banking receipts and paying-in slips, and security of money.", "id": "acffa1st-rv4", "updated": "2026-11-12"}, {"num": "5", "title": "Sales and Sales Records", "pages": [105, 134], "syllabus": "C2", "status": "published", "branches": [{"kind": "concept", "title": "Invoices and credit notes", "page": [106, 112], "items": [{"t": "pt", "k": 1, "text": "A sales invoice records a credit sale and requests payment; produced in multiple copies (top copy to the customer, copies for accounts and filing)", "id": "acffa1st-rv5-0ad41-0a9a09"}, {"t": "pt", "text": "Settlement terms on invoices (eg 'net 30 days', '2% discount if paid within 10 days')", "id": "acffa1st-rv5-0ad41-6e614b"}, {"t": "pt", "k": 1, "text": "A credit note is the REVERSE of a sales invoice - sent to a customer to reduce the amount owed (eg returned or faulty goods)", "id": "acffa1st-rv5-0ad41-792941"}], "id": "acffa1st-rv5-0ad41"}, {"kind": "formula", "title": "Discounts and sales tax", "page": [112, 118], "items": [{"t": "def", "k": 1, "term": "Trade discount", "text": "A discount on the price of goods, agreed in advance (often for regular or bulk customers) - deducted on the invoice", "id": "acffa1st-rv5-2d91c-d1564b"}, {"t": "def", "k": 1, "term": "Settlement (cash) discount", "text": "Discount offered for early payment of an invoice", "id": "acffa1st-rv5-2d91c-af75f9"}, {"t": "pt", "text": "Settlement discount accounting: if the customer is expected to take it, revenue is recorded net; if it is taken when not expected, adjust; if not taken when expected, record the extra as revenue", "id": "acffa1st-rv5-2d91c-a02be8"}, {"t": "f", "k": 1, "term": "Sales tax", "text": "Net price (after trade discount) x Sales tax rate", "vars": "sales tax-registered businesses must charge it", "eg": "$400 net at 20% = $80 tax; invoice total $480", "id": "acffa1st-rv5-2d91c-5d5c75"}, {"t": "f", "term": "Sales tax from gross", "text": "Gross x rate / (100 + rate)", "vars": "20%: $480 x 20/120 = $80", "id": "acffa1st-rv5-2d91c-ea1343"}, {"t": "def", "term": "Tax point", "text": "The date on which a transaction is deemed to have taken place for sales tax purposes", "id": "acffa1st-rv5-2d91c-098e56"}, {"t": "pt", "text": "A credit note also reduces the sales tax payable", "id": "acffa1st-rv5-2d91c-2eeac9"}], "id": "acffa1st-rv5-2d91c"}, {"kind": "process", "title": "Preparing and coding invoices", "page": [118, 124], "items": [{"t": "pt", "k": 1, "text": "Authorisation: do not invoice until the goods/services have been supplied (check despatch notes/orders)", "id": "acffa1st-rv5-1f1bc-5321df"}, {"t": "pt", "text": "Information needed: customer details, prices from the price list, discounts, sales tax, terms", "id": "acffa1st-rv5-1f1bc-8c9dfd"}, {"t": "pt", "text": "Check completed invoices: quantities, prices, extensions (quantity x price), discounts, tax, totals", "id": "acffa1st-rv5-1f1bc-b74bdd"}, {"t": "pt", "text": "Credit notes need authorisation too", "id": "acffa1st-rv5-1f1bc-aa0e5e"}, {"t": "pt", "text": "Coding: enough to post to the correct customer account and sales/general ledger accounts (grid box stamp)", "id": "acffa1st-rv5-1f1bc-4e8bed"}], "id": "acffa1st-rv5-1f1bc"}, {"kind": "process", "title": "Day books", "page": [125, 130], "items": [{"t": "def", "k": 1, "term": "Day book", "text": "A book of prime entry", "id": "acffa1st-rv5-cdaaf-5e4640"}, {"t": "def", "k": 1, "term": "Sales day book", "text": "Book of prime entry for recording credit sale transactions (sales invoices)", "id": "acffa1st-rv5-cdaaf-9ecceb"}, {"t": "def", "term": "Sales returns day book", "text": "Book of prime entry for credit notes issued to customers", "id": "acffa1st-rv5-cdaaf-59ca5b"}, {"t": "pt", "text": "Columns: date, customer, invoice number, gross, sales tax, net (and analysis columns)", "id": "acffa1st-rv5-cdaaf-6571cb"}, {"t": "def", "k": 1, "term": "Posting", "text": "Transferring details from a book of prime entry to accounts in the ledger", "id": "acffa1st-rv5-cdaaf-a19975"}, {"t": "def", "k": 1, "term": "Sales ledger", "text": "Ledger of individual credit customers' accounts (also called the receivables ledger)", "id": "acffa1st-rv5-cdaaf-31491a"}, {"t": "exam", "text": "The book of prime entry for credit notes sent to customers is the sales RETURNS day book", "id": "acffa1st-rv5-cdaaf-778fce"}], "id": "acffa1st-rv5-cdaaf"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calculating sales tax before deducting the trade discount", "id": "acffa1st-rv5-6483a-863f84"}, {"t": "x", "text": "Recording a credit note in the sales day book - it goes in the sales returns day book", "id": "acffa1st-rv5-6483a-b6c068"}, {"t": "x", "text": "Invoicing before goods are supplied", "id": "acffa1st-rv5-6483a-bd7714"}, {"t": "x", "text": "Treating trade discounts as an expense - the sale is recorded net", "id": "acffa1st-rv5-6483a-19501f"}], "id": "acffa1st-rv5-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Sales invoice = credit sale and request for payment", "id": "acffa1st-rv5-80e78-ec57f5"}, {"t": "pt", "text": "Credit note reverses an invoice", "id": "acffa1st-rv5-80e78-799970"}, {"t": "pt", "text": "Trade discount: agreed in advance, deducted on the invoice", "id": "acffa1st-rv5-80e78-665c42"}, {"t": "pt", "text": "Settlement discount: for early payment", "id": "acffa1st-rv5-80e78-18bb7f"}, {"t": "pt", "text": "Sales tax = net (after trade discount) x rate", "id": "acffa1st-rv5-80e78-c99228"}, {"t": "pt", "text": "Tax point = date for sales tax purposes", "id": "acffa1st-rv5-80e78-9a32f0"}, {"t": "pt", "text": "Credit notes reduce sales tax too", "id": "acffa1st-rv5-80e78-515872"}, {"t": "pt", "text": "Authorise before invoicing", "id": "acffa1st-rv5-80e78-d47455"}, {"t": "pt", "text": "Check extensions, discounts, tax, totals", "id": "acffa1st-rv5-80e78-cbdf4b"}, {"t": "pt", "text": "Sales day book: credit sales invoices", "id": "acffa1st-rv5-80e78-9e2af4"}, {"t": "pt", "text": "Sales returns day book: credit notes", "id": "acffa1st-rv5-80e78-ce841e"}, {"t": "pt", "text": "Sales ledger = receivables ledger of customer accounts", "id": "acffa1st-rv5-80e78-cd0d5c"}], "id": "acffa1st-rv5-80e78"}], "source": "Kaplan FA1 Study Text ch 5: sections 1-9 pp106-130; key terms p131", "summary": "Sales invoices and credit notes, trade and settlement discounts, sales tax principles, preparing and authorising invoices and credit notes, coding, and the sales and sales returns day books.", "id": "acffa1st-rv5", "updated": "2026-11-12"}, {"num": "6", "title": "Recording Sales", "pages": [135, 156], "syllabus": "C2", "status": "published", "branches": [{"kind": "rule", "title": "Posting day book totals", "page": [136, 140], "items": [{"t": "pt", "k": 1, "text": "Sales day book totals: Dr Receivables ledger control account (gross), Cr Sales (net), Cr Sales tax (tax)", "id": "acffa1st-rv6-94aec-42bb79"}, {"t": "pt", "k": 1, "text": "Individual invoices are posted to each customer's account in the receivables (sales) ledger - Dr customer account", "id": "acffa1st-rv6-94aec-9ea63e"}, {"t": "pt", "k": 1, "text": "Sales returns day book totals: Dr Sales returns (net), Dr Sales tax, Cr Receivables ledger control account (gross); Cr each customer's account", "id": "acffa1st-rv6-94aec-15770f"}, {"t": "pt", "text": "Analysed sales day book: separate columns for product lines or regions, posted to separate sales accounts", "id": "acffa1st-rv6-94aec-9628f9"}, {"t": "pt", "text": "Computerised ledgers post automatically from invoices and credit notes", "id": "acffa1st-rv6-94aec-f8a8aa"}], "id": "acffa1st-rv6-94aec"}, {"kind": "concept", "title": "Statements and aged analysis", "page": [140, 144], "items": [{"t": "pt", "k": 1, "text": "Statement of account: sets out transactions with the customer in the period and the balance owed - a reminder to pay", "id": "acffa1st-rv6-e2d1c-f1e137"}, {"t": "def", "k": 1, "term": "Aged receivables analysis", "text": "A list of credit customers and amounts owed, analysed by how long since the invoice was issued (eg current, 30+, 60+, 90+ days)", "id": "acffa1st-rv6-e2d1c-080916"}, {"t": "pt", "text": "Uses: identify slow payers, prioritise chasing, decide on credit limits and allowances", "id": "acffa1st-rv6-e2d1c-c86f9d"}], "id": "acffa1st-rv6-e2d1c"}, {"kind": "process", "title": "Chasing debts and credit control", "page": [144, 148], "items": [{"t": "pt", "text": "Procedures for overdue payments: statement -> reminder letter -> telephone call -> final demand -> stop supplies -> legal action / debt collection agency", "id": "acffa1st-rv6-10e10-3bab83"}, {"t": "pt", "text": "Letters in the organisation's 'house style', polite but firm", "id": "acffa1st-rv6-10e10-b2b088"}, {"t": "pt", "k": 1, "text": "Credit limits: the maximum a customer may owe - check before accepting new orders", "id": "acffa1st-rv6-10e10-57ae5e"}, {"t": "pt", "text": "Providing credit: check references and credit ratings before opening an account", "id": "acffa1st-rv6-10e10-b7c0cd"}], "id": "acffa1st-rv6-10e10"}, {"kind": "formula", "title": "Irrecoverable debts and allowances", "page": [149, 153], "items": [{"t": "def", "k": 1, "term": "Irrecoverable debt", "text": "A debt for which payment is reasonably certain NOT to be received", "id": "acffa1st-rv6-153f0-8b77c0"}, {"t": "pt", "k": 1, "text": "Write-off: Dr Irrecoverable debts expense, Cr Receivables ledger control (and the customer's account)", "id": "acffa1st-rv6-153f0-dc7221"}, {"t": "pt", "k": 1, "text": "Recovered later: Dr Bank, Cr Irrecoverable debts expense (the receivable is NOT reinstated)", "id": "acffa1st-rv6-153f0-6cba05"}, {"t": "def", "k": 1, "term": "Allowance for receivables", "text": "An amount set aside recognising that some debts may not be fully recovered", "id": "acffa1st-rv6-153f0-d373e2"}, {"t": "f", "term": "Allowance movement", "text": "Required closing allowance - Opening allowance", "vars": "increase -> Dr Irrecoverable debts expense, Cr Allowance; decrease -> Dr Allowance, Cr Irrecoverable debts expense", "id": "acffa1st-rv6-153f0-bb69e8"}, {"t": "exam", "text": "Only the movement in the allowance affects profit", "id": "acffa1st-rv6-153f0-4a314a"}], "id": "acffa1st-rv6-153f0"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Posting individual customer balances to the nominal ledger - the control account takes the total", "id": "acffa1st-rv6-6483a-3f378c"}, {"t": "x", "text": "Reinstating a receivable when a written-off debt is recovered", "id": "acffa1st-rv6-6483a-0703ef"}, {"t": "x", "text": "Charging the full allowance balance to profit each year", "id": "acffa1st-rv6-6483a-0d3478"}, {"t": "x", "text": "Forgetting to post sales tax on returns", "id": "acffa1st-rv6-6483a-fd52cf"}], "id": "acffa1st-rv6-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "SDB: Dr receivables control (gross), Cr sales (net), Cr sales tax", "id": "acffa1st-rv6-80e78-34ff36"}, {"t": "pt", "text": "SRDB: Dr sales returns, Dr sales tax, Cr receivables control", "id": "acffa1st-rv6-80e78-f37b58"}, {"t": "pt", "text": "Individual customer accounts in the receivables ledger", "id": "acffa1st-rv6-80e78-5b4811"}, {"t": "pt", "text": "Statement of account = transactions and balance owed", "id": "acffa1st-rv6-80e78-ff24a4"}, {"t": "pt", "text": "Aged receivables: how long debts are outstanding", "id": "acffa1st-rv6-80e78-61d756"}, {"t": "pt", "text": "Chase: statement, letter, call, final demand, stop supply, legal", "id": "acffa1st-rv6-80e78-6eb9e6"}, {"t": "pt", "text": "Credit limits cap what customers may owe", "id": "acffa1st-rv6-80e78-3c1afd"}, {"t": "pt", "text": "Irrecoverable debt: Dr expense, Cr receivables", "id": "acffa1st-rv6-80e78-2230de"}, {"t": "pt", "text": "Recovered debt: Dr bank, Cr irrecoverable debts expense", "id": "acffa1st-rv6-80e78-0c8b79"}, {"t": "pt", "text": "Allowance: only the movement to P/L", "id": "acffa1st-rv6-80e78-158066"}, {"t": "pt", "text": "Increase: Dr expense, Cr allowance", "id": "acffa1st-rv6-80e78-b366cd"}, {"t": "pt", "text": "Decrease: Dr allowance, Cr expense", "id": "acffa1st-rv6-80e78-6f77ed"}], "id": "acffa1st-rv6-80e78"}], "source": "Kaplan FA1 Study Text ch 6: sections 1-10 pp136-151; key terms p154", "summary": "Posting the sales and sales returns day books to the nominal and receivables ledgers, computerised ledgers, statements of account, aged receivables analysis, chasing overdue debts, credit limits, irrecoverable debts and the allowance for receivables.", "id": "acffa1st-rv6", "updated": "2026-11-12"}, {"num": "7", "title": "Purchases and Purchase Records", "pages": [157, 180], "syllabus": "C3", "status": "published", "branches": [{"kind": "process", "title": "Buying and source documents", "page": [158, 160], "items": [{"t": "pt", "k": 1, "text": "Expenditure must be properly authorised - a purchase requisition starts the process", "id": "acffa1st-rv7-4d599-7cf9f4"}, {"t": "def", "k": 1, "term": "Purchase order", "text": "A written request by an organisation for the supply of a specified quantity of goods or services at an agreed price", "id": "acffa1st-rv7-4d599-37b8db"}, {"t": "def", "term": "Price quotation", "text": "Sent to a potential customer quoting a price; if accepted it becomes a purchase order", "id": "acffa1st-rv7-4d599-3ee0a1"}, {"t": "pt", "text": "Delivery note / advice note accompanies goods; a goods received note (GRN) records what was received", "id": "acffa1st-rv7-4d599-62f71c"}, {"t": "pt", "text": "Services: a timesheet or job sheet confirms the service was provided (may replace a purchase order)", "id": "acffa1st-rv7-4d599-9375de"}, {"t": "pt", "text": "Purchase invoice: request for payment from the supplier", "id": "acffa1st-rv7-4d599-0edb22"}], "id": "acffa1st-rv7-4d599"}, {"kind": "rule", "title": "Checking supplier invoices", "page": [160, 169], "items": [{"t": "pt", "k": 1, "text": "Check each invoice against the purchase order (prices, terms, discounts) and the GRN (quantities received)", "id": "acffa1st-rv7-17ff8-d4f78d"}, {"t": "def", "k": 1, "term": "Price extensions", "text": "The multiplication of the quantity by the unit price for each item - check for calculation errors", "id": "acffa1st-rv7-17ff8-b2ea78"}, {"t": "pt", "text": "Check trade discounts, sales tax calculation and the total", "id": "acffa1st-rv7-17ff8-12e470"}, {"t": "f", "term": "Sales tax on an invoice", "text": "(Goods total - Trade discount) x Rate", "vars": "tax on the net amount", "eg": "$400 + 20% = $480", "id": "acffa1st-rv7-17ff8-0498b3"}, {"t": "pt", "text": "Invoices for services: fewer items to check - rate x time, tax, total", "id": "acffa1st-rv7-17ff8-6fc8fa"}, {"t": "pt", "text": "Credit notes received: check against the returns made and the original invoice", "id": "acffa1st-rv7-17ff8-7b47b4"}], "id": "acffa1st-rv7-17ff8"}, {"kind": "process", "title": "Authorising, numbering and coding", "page": [170, 172], "items": [{"t": "pt", "k": 1, "text": "Purchase invoices should be AUTHORISED for payment before they are paid", "id": "acffa1st-rv7-56c0d-c35d7c"}, {"t": "pt", "text": "Code invoices to distinguish asset (capital) expenditure from revenue expenditure, and to the right supplier and expense accounts", "id": "acffa1st-rv7-56c0d-734110"}, {"t": "pt", "text": "Number purchase invoices sequentially on receipt for internal control", "id": "acffa1st-rv7-56c0d-82cd07"}, {"t": "pt", "text": "Grid box stamp / front sheet: evidences checks (order, GRN, calculations), authorisation and coding", "id": "acffa1st-rv7-56c0d-76494f"}], "id": "acffa1st-rv7-56c0d"}, {"kind": "concept", "title": "Purchase day books", "page": [173, 177], "items": [{"t": "def", "k": 1, "term": "Purchase day book", "text": "Book of prime entry for recording purchase transactions on credit (purchase invoices)", "id": "acffa1st-rv7-ae504-59d5d6"}, {"t": "def", "k": 1, "term": "Purchase returns day book", "text": "Book of prime entry for recording credit notes received from suppliers", "id": "acffa1st-rv7-ae504-644736"}, {"t": "pt", "text": "Batch invoices for processing and use control totals", "id": "acffa1st-rv7-ae504-531cb7"}, {"t": "pt", "text": "Columns: date, supplier, invoice number, gross, sales tax, net and analysis columns (purchases, expenses)", "id": "acffa1st-rv7-ae504-40b30f"}, {"t": "pt", "text": "Settlement discounts are NOT recorded in the purchase day book - they are recorded when payment is made", "id": "acffa1st-rv7-ae504-2364f6"}, {"t": "exam", "text": "What can take the place of a purchase order when services are bought? A timesheet/service record agreed with the supplier", "id": "acffa1st-rv7-ae504-d36456"}], "id": "acffa1st-rv7-ae504"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Paying an invoice that has not been matched to the GRN", "id": "acffa1st-rv7-6483a-5a3195"}, {"t": "x", "text": "Coding capital expenditure as an expense", "id": "acffa1st-rv7-6483a-1342d5"}, {"t": "x", "text": "Recording settlement discounts in the purchase day book", "id": "acffa1st-rv7-6483a-73a390"}, {"t": "x", "text": "Missing errors in price extensions or tax calculations", "id": "acffa1st-rv7-6483a-06e061"}], "id": "acffa1st-rv7-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Requisition authorises the need", "id": "acffa1st-rv7-80e78-8cff95"}, {"t": "pt", "text": "Purchase order to the supplier", "id": "acffa1st-rv7-80e78-6de200"}, {"t": "pt", "text": "Delivery note and GRN confirm receipt", "id": "acffa1st-rv7-80e78-afc714"}, {"t": "pt", "text": "Invoice checked to order and GRN", "id": "acffa1st-rv7-80e78-c6e9ec"}, {"t": "pt", "text": "Price extension = quantity x unit price", "id": "acffa1st-rv7-80e78-254794"}, {"t": "pt", "text": "Check discounts, tax and totals", "id": "acffa1st-rv7-80e78-de9da0"}, {"t": "pt", "text": "Authorise invoices before payment", "id": "acffa1st-rv7-80e78-015a71"}, {"t": "pt", "text": "Code capital vs revenue correctly", "id": "acffa1st-rv7-80e78-3e1f97"}, {"t": "pt", "text": "Number invoices sequentially", "id": "acffa1st-rv7-80e78-55c077"}, {"t": "pt", "text": "Purchase day book: credit purchase invoices", "id": "acffa1st-rv7-80e78-c37323"}, {"t": "pt", "text": "Purchase returns day book: supplier credit notes", "id": "acffa1st-rv7-80e78-cfab5c"}, {"t": "pt", "text": "Settlement discounts recorded at payment", "id": "acffa1st-rv7-80e78-5fb375"}], "id": "acffa1st-rv7-80e78"}], "source": "Kaplan FA1 Study Text ch 7: sections 1-7 pp158-177; key terms p178", "summary": "Buying goods and services, source documents, checking supplier invoices (calculations, extensions, sales tax), credit notes, authorising and coding invoices, the purchase day book and purchase returns day book.", "id": "acffa1st-rv7", "updated": "2026-11-12"}, {"num": "8", "title": "Recording Purchases", "pages": [181, 190], "syllabus": "C3", "status": "published", "branches": [{"kind": "rule", "title": "Posting day book totals", "page": [182, 184], "items": [{"t": "pt", "k": 1, "text": "Purchase day book totals: Dr Purchases / expense accounts (net, by analysis column), Dr Sales tax, Cr Payables ledger control account (gross)", "id": "acffa1st-rv8-94aec-cd3b47"}, {"t": "pt", "k": 1, "text": "Each invoice is credited to the individual supplier's account in the payables ledger", "id": "acffa1st-rv8-94aec-b24e45"}, {"t": "pt", "k": 1, "text": "Purchase returns day book totals: Dr Payables ledger control (gross), Cr Purchases returns (net), Cr Sales tax; Dr each supplier's account", "id": "acffa1st-rv8-94aec-a8cd12"}, {"t": "pt", "text": "Computerised ledgers post these entries automatically from invoice input", "id": "acffa1st-rv8-94aec-24078f"}, {"t": "def", "term": "Payables ledger", "text": "A ledger containing accounts for individual suppliers", "id": "acffa1st-rv8-94aec-78a9e8"}], "id": "acffa1st-rv8-94aec"}, {"kind": "process", "title": "Supplier statements", "page": [185, 188], "items": [{"t": "pt", "text": "Balancing a supplier's account shows the amount owed at a date (credit balance)", "id": "acffa1st-rv8-a064b-117c60"}, {"t": "pt", "k": 1, "text": "Suppliers send statements listing invoices, credit notes, payments and the balance; businesses often pay at a set time each month from statements", "id": "acffa1st-rv8-a064b-03e9cf"}, {"t": "pt", "k": 1, "text": "Check each statement against the supplier's account in the payables ledger: agree invoices and credit notes, identify payments in transit, missing invoices, errors or disputed items", "id": "acffa1st-rv8-a064b-96790f"}, {"t": "pt", "text": "Only pay amounts that are agreed and authorised", "id": "acffa1st-rv8-a064b-f923df"}], "id": "acffa1st-rv8-a064b"}, {"kind": "concept", "title": "Aged payables analysis", "page": [188, 189], "items": [{"t": "def", "k": 1, "term": "Aged payables analysis", "text": "A list of payables analysed according to how long until payment is due (or how long outstanding)", "id": "acffa1st-rv8-d3fac-c6c736"}, {"t": "pt", "text": "Uses: plan payments and cash flow, take settlement discounts, avoid paying late and damaging supplier relationships", "id": "acffa1st-rv8-d3fac-7ddf2b"}, {"t": "pt", "text": "Communication with suppliers: query discrepancies promptly, confirm payment dates, keep a courteous professional tone", "id": "acffa1st-rv8-d3fac-59c2cf"}, {"t": "exam", "text": "Questions may give a supplier statement and ask why it differs from the payables ledger", "id": "acffa1st-rv8-d3fac-971486"}], "id": "acffa1st-rv8-d3fac"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Debiting the payables control account for credit purchases - purchases on credit are CREDITED to payables", "id": "acffa1st-rv8-6483a-58ee19"}, {"t": "x", "text": "Paying the statement balance without checking it against the ledger", "id": "acffa1st-rv8-6483a-f30dac"}, {"t": "x", "text": "Forgetting the sales tax element when posting purchase returns", "id": "acffa1st-rv8-6483a-c519b0"}, {"t": "x", "text": "Treating an aged payables analysis as a credit control tool for customers", "id": "acffa1st-rv8-6483a-3dfa30"}], "id": "acffa1st-rv8-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "PDB: Dr purchases/expenses (net), Dr sales tax, Cr payables control (gross)", "id": "acffa1st-rv8-80e78-1aafe4"}, {"t": "pt", "text": "PRDB: Dr payables control, Cr purchases returns, Cr sales tax", "id": "acffa1st-rv8-80e78-f7713b"}, {"t": "pt", "text": "Individual suppliers in the payables ledger (credit balances)", "id": "acffa1st-rv8-80e78-c313bd"}, {"t": "pt", "text": "Computerised ledgers post automatically", "id": "acffa1st-rv8-80e78-a10ff6"}, {"t": "pt", "text": "Supplier statement lists invoices, credits, payments, balance", "id": "acffa1st-rv8-80e78-901404"}, {"t": "pt", "text": "Reconcile statements to the payables ledger", "id": "acffa1st-rv8-80e78-028ee1"}, {"t": "pt", "text": "Differences: payments in transit, missing invoices, errors, disputes", "id": "acffa1st-rv8-80e78-a885c6"}, {"t": "pt", "text": "Pay only agreed, authorised amounts", "id": "acffa1st-rv8-80e78-fa598e"}, {"t": "pt", "text": "Aged payables: plan payments and cash flow", "id": "acffa1st-rv8-80e78-455dc1"}, {"t": "pt", "text": "Take settlement discounts where worthwhile", "id": "acffa1st-rv8-80e78-eb4c53"}, {"t": "pt", "text": "Communicate discrepancies promptly", "id": "acffa1st-rv8-80e78-f31038"}, {"t": "pt", "text": "Supplier account balance = amount owed", "id": "acffa1st-rv8-80e78-c8cb3f"}], "id": "acffa1st-rv8-80e78"}], "source": "Kaplan FA1 Study Text ch 8: sections 1-5 pp182-189; key terms p189", "summary": "Posting the purchase and purchase returns day books to the nominal and payables ledgers, computerised ledgers, balancing supplier accounts, checking supplier statements, aged payables analysis and communication with suppliers.", "id": "acffa1st-rv8", "updated": "2026-11-12"}, {"num": "9", "title": "Recording Receipts and Payments", "pages": [191, 212], "syllabus": "C4", "status": "published", "branches": [{"kind": "process", "title": "Recording receipts", "page": [192, 194], "items": [{"t": "pt", "k": 1, "text": "Cash sales: check the amount received (till roll, receipts) and record in the cash book", "id": "acffa1st-rv9-ac21f-be948c"}, {"t": "pt", "k": 1, "text": "Receipts from credit customers: match each receipt to the invoice(s) being paid using the remittance advice; list on a remittance list", "id": "acffa1st-rv9-ac21f-d269e3"}, {"t": "pt", "text": "Remittance list: customer name, account, invoice numbers, amount - checked to the money banked", "id": "acffa1st-rv9-ac21f-707b01"}, {"t": "pt", "text": "Batching transactions: split large numbers of receipts into batches with control totals", "id": "acffa1st-rv9-ac21f-513326"}], "id": "acffa1st-rv9-ac21f"}, {"kind": "concept", "title": "The cash book", "page": [194, 198], "items": [{"t": "def", "k": 1, "term": "Cash book", "text": "Book of prime entry for recording receipts into and payments from the business bank account - may also serve as the ledger account for cash and bank", "id": "acffa1st-rv9-766b6-09618e"}, {"t": "pt", "text": "Cash receipts book columns: date, details, reference, total, sales tax (cash sales), receivables, cash sales, other", "id": "acffa1st-rv9-766b6-526fc7"}, {"t": "pt", "text": "Cash payments book columns: date, payee, cheque number, total, sales tax, payables, cash purchases, expenses", "id": "acffa1st-rv9-766b6-542b98"}, {"t": "pt", "text": "Receivables ledger: individual customer accounts credited with their receipts", "id": "acffa1st-rv9-766b6-70bd94"}], "id": "acffa1st-rv9-766b6"}, {"kind": "rule", "title": "Posting from the cash book", "page": [198, 208], "items": [{"t": "pt", "k": 1, "text": "Receipts: Dr Bank (total); Cr Receivables ledger control (credit customers), Cr Sales (cash sales net), Cr Sales tax", "id": "acffa1st-rv9-21561-475aac"}, {"t": "pt", "k": 1, "text": "Payments: Cr Bank (total); Dr Payables ledger control (suppliers), Dr expenses/cash purchases (net), Dr Sales tax", "id": "acffa1st-rv9-21561-a6d4f6"}, {"t": "pt", "text": "Individual customers' and suppliers' accounts are posted from the cash book too", "id": "acffa1st-rv9-21561-284578"}, {"t": "def", "k": 1, "term": "Settlement discount", "text": "Discount for early payment of an invoice - discount received is recorded in the nominal ledger as discounts received (income)", "id": "acffa1st-rv9-21561-f59b35"}, {"t": "pt", "text": "Discount received: Dr Payables ledger control, Cr Discounts received", "id": "acffa1st-rv9-21561-d694bc"}, {"t": "def", "term": "Trade discount", "text": "A discount agreed in advance (regular or bulk customers) - deducted on the invoice, not recorded separately", "id": "acffa1st-rv9-21561-da634b"}, {"t": "exam", "text": "The book of prime entry for cash sales is the cash book (cash receipts book)", "id": "acffa1st-rv9-21561-e5100f"}], "id": "acffa1st-rv9-21561"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Posting a receipt from a credit customer to sales - it reduces receivables", "id": "acffa1st-rv9-6483a-2d4b95"}, {"t": "x", "text": "Recording cash sales in the sales day book", "id": "acffa1st-rv9-6483a-3d3a2d"}, {"t": "x", "text": "Missing the sales tax column on cash sales and cash purchases", "id": "acffa1st-rv9-6483a-669f14"}, {"t": "x", "text": "Recording a trade discount as discount received", "id": "acffa1st-rv9-6483a-5ae15f"}], "id": "acffa1st-rv9-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Match receipts to invoices via remittance advices", "id": "acffa1st-rv9-80e78-88b536"}, {"t": "pt", "text": "Remittance list summarises receipts", "id": "acffa1st-rv9-80e78-6aed07"}, {"t": "pt", "text": "Batch receipts with control totals", "id": "acffa1st-rv9-80e78-9f3135"}, {"t": "pt", "text": "Cash book = book of prime entry (and possibly ledger)", "id": "acffa1st-rv9-80e78-101a84"}, {"t": "pt", "text": "Receipts: Dr bank, Cr receivables control / sales / sales tax", "id": "acffa1st-rv9-80e78-a3a2ef"}, {"t": "pt", "text": "Payments: Cr bank, Dr payables control / expenses / sales tax", "id": "acffa1st-rv9-80e78-b02448"}, {"t": "pt", "text": "Cash sales recorded in the cash book", "id": "acffa1st-rv9-80e78-b54d47"}, {"t": "pt", "text": "Settlement discount received = income", "id": "acffa1st-rv9-80e78-bdfb3f"}, {"t": "pt", "text": "Discount received: Dr payables, Cr discounts received", "id": "acffa1st-rv9-80e78-284b4c"}, {"t": "pt", "text": "Trade discount deducted on the invoice", "id": "acffa1st-rv9-80e78-807962"}, {"t": "pt", "text": "Post individual accounts in the subsidiary ledgers", "id": "acffa1st-rv9-80e78-2924da"}, {"t": "pt", "text": "Cash control is fundamental to any business", "id": "acffa1st-rv9-80e78-54f5c5"}], "id": "acffa1st-rv9-80e78"}], "source": "Kaplan FA1 Study Text ch 9: sections 1-6 pp192-209; key terms p209", "summary": "Recording money received from cash and credit customers, remittance lists and batching, the cash book (receipts and payments), posting the cash book to the nominal and receivables/payables ledgers, and settlement discounts.", "id": "acffa1st-rv9", "updated": "2026-11-12"}, {"num": "10", "title": "Maintaining Petty Cash Records", "pages": [213, 232], "syllabus": "C4", "status": "published", "branches": [{"kind": "process", "title": "Operation and authorisation", "page": [214, 218], "items": [{"t": "pt", "k": 1, "text": "Petty cash covers small expenses (stationery, postage, refreshments, travel) not worth paying by cheque", "id": "acffa1st-rv10-4cb86-eb08ed"}, {"t": "def", "k": 1, "term": "Petty cash voucher", "text": "Document kept in petty cash giving details of money paid out and the reason for the expense", "id": "acffa1st-rv10-4cb86-f330e7"}, {"t": "pt", "text": "Vouchers are numbered sequentially for control; the claimant signs for the cash", "id": "acffa1st-rv10-4cb86-c50a9d"}, {"t": "pt", "k": 1, "text": "Authorisation: check the claim is a valid business expense and within the authoriser's limit; support with a receipt", "id": "acffa1st-rv10-4cb86-134e10"}, {"t": "pt", "text": "No receipt: a manager may authorise with an explanation; payments in advance: cash given before the purchase, receipt and change returned later", "id": "acffa1st-rv10-4cb86-c76c6a"}, {"t": "pt", "k": 1, "text": "Security: lockable petty cash box kept in a safe, limited access, a named petty cashier", "id": "acffa1st-rv10-4cb86-d4435d"}], "id": "acffa1st-rv10-4cb86"}, {"kind": "formula", "title": "The imprest system", "page": [219, 225], "items": [{"t": "def", "k": 1, "term": "Imprest system", "text": "The petty cash is periodically topped up to a fixed amount (the imprest); at all times vouchers + cash in the box = the imprest amount", "id": "acffa1st-rv10-3b018-bac8ec"}, {"t": "f", "term": "Top-up amount", "text": "Imprest amount - Cash remaining = Total of vouchers paid", "vars": "Imprest $200, cash left $46: top up $154", "id": "acffa1st-rv10-3b018-535e98"}, {"t": "pt", "text": "Non-imprest system: fixed amounts added regardless - no in-built control, risk of running out", "id": "acffa1st-rv10-3b018-26ab09"}, {"t": "pt", "text": "Petty cash book: receipts column (top-ups) and analysed payment columns (stationery, postage, travel, sales tax)", "id": "acffa1st-rv10-3b018-b59200"}, {"t": "pt", "k": 1, "text": "Posting: Dr each expense account and Sales tax (column totals), Cr Petty cash; top-up: Dr Petty cash, Cr Bank", "id": "acffa1st-rv10-3b018-0c20e3"}, {"t": "pt", "text": "The petty cash book may act as both a book of prime entry and the ledger account", "id": "acffa1st-rv10-3b018-a005b4"}], "id": "acffa1st-rv10-3b018"}, {"kind": "process", "title": "Petty cash reconciliation", "page": [226, 228], "items": [{"t": "f", "k": 1, "term": "Petty cash check", "text": "Cash in the box + Total of vouchers = Imprest amount", "vars": "any difference must be investigated", "eg": "Box short by $1: find the reason", "id": "acffa1st-rv10-9bd1f-80a511"}, {"t": "pt", "text": "Possible reasons for differences: error in giving change, a missing voucher, theft, arithmetic errors", "id": "acffa1st-rv10-9bd1f-c07e45"}, {"t": "pt", "text": "The petty cash can be checked at any time, even if the petty cash book is not up to date", "id": "acffa1st-rv10-9bd1f-0dd0ac"}, {"t": "exam", "text": "Expect questions on the top-up amount and on reconciling cash plus vouchers to the imprest", "id": "acffa1st-rv10-9bd1f-4ca04c"}], "id": "acffa1st-rv10-9bd1f"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Topping up by a fixed amount under an imprest system - top up by the amount SPENT", "id": "acffa1st-rv10-6483a-2755b9"}, {"t": "x", "text": "Paying claims without an authorised voucher", "id": "acffa1st-rv10-6483a-b124a4"}, {"t": "x", "text": "Posting the gross voucher totals to expenses and forgetting sales tax", "id": "acffa1st-rv10-6483a-16728e"}, {"t": "x", "text": "Ignoring small petty cash differences - all differences must be investigated", "id": "acffa1st-rv10-6483a-eb3074"}], "id": "acffa1st-rv10-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Petty cash: small, minor expenses", "id": "acffa1st-rv10-80e78-2b0837"}, {"t": "pt", "text": "Every payment needs a numbered, authorised voucher", "id": "acffa1st-rv10-80e78-19ba03"}, {"t": "pt", "text": "Support claims with receipts", "id": "acffa1st-rv10-80e78-a47a15"}, {"t": "pt", "text": "Keep petty cash locked with limited access", "id": "acffa1st-rv10-80e78-8159e4"}, {"t": "pt", "text": "Imprest: top up to a fixed float", "id": "acffa1st-rv10-80e78-3a141c"}, {"t": "pt", "text": "Top-up = vouchers paid = imprest - cash left", "id": "acffa1st-rv10-80e78-714f64"}, {"t": "pt", "text": "Vouchers + cash = imprest at all times", "id": "acffa1st-rv10-80e78-ea29ff"}, {"t": "pt", "text": "Non-imprest: no in-built control", "id": "acffa1st-rv10-80e78-4e2f8d"}, {"t": "pt", "text": "Petty cash book: analysed payment columns", "id": "acffa1st-rv10-80e78-eef0be"}, {"t": "pt", "text": "Post: Dr expenses and sales tax, Cr petty cash", "id": "acffa1st-rv10-80e78-2d6bad"}, {"t": "pt", "text": "Top-up: Dr petty cash, Cr bank", "id": "acffa1st-rv10-80e78-cca368"}, {"t": "pt", "text": "Investigate any difference", "id": "acffa1st-rv10-80e78-42a7f9"}], "id": "acffa1st-rv10-80e78"}], "source": "Kaplan FA1 Study Text ch 10: sections 1-8 pp214-228; key terms p230", "summary": "How petty cash works, petty cash vouchers and authorisation, security, the petty cash book, imprest and non-imprest systems, posting the petty cash book and petty cash reconciliation.", "id": "acffa1st-rv10", "updated": "2026-11-12"}, {"num": "11", "title": "Payroll", "pages": [233, 262], "syllabus": "C5", "status": "published", "branches": [{"kind": "def", "title": "Gross pay, net pay and deductions", "page": [234, 238], "items": [{"t": "def", "k": 1, "term": "Gross pay", "text": "Money due to an employee BEFORE deductions for income tax, state benefit contributions etc", "id": "acffa1st-rv11-1daf0-958633"}, {"t": "def", "k": 1, "term": "Net pay", "text": "Money payable to an employee AFTER deductions", "id": "acffa1st-rv11-1daf0-23d3f8"}, {"t": "pt", "k": 1, "text": "Statutory deductions (required by law): income tax, employee state benefit contributions (eg NIC)", "id": "acffa1st-rv11-1daf0-cac818"}, {"t": "pt", "text": "Non-statutory (voluntary) deductions: pension contributions, trade union subscriptions, charitable giving, savings schemes", "id": "acffa1st-rv11-1daf0-0e4dc4"}, {"t": "def", "term": "State benefit contributions", "text": "Amounts paid by employees (and possibly the employer) to the state for social security", "id": "acffa1st-rv11-1daf0-008881"}, {"t": "pt", "k": 1, "text": "Employer's costs = gross pay + EMPLOYER'S state benefit contributions (+ employer pension contributions)", "id": "acffa1st-rv11-1daf0-db348f"}, {"t": "def", "term": "Payslip", "text": "Document given to each employee showing pay and deductions", "id": "acffa1st-rv11-1daf0-ef3302"}, {"t": "pt", "text": "Employer pays deductions to outside agencies (tax authority, pension fund) by set dates", "id": "acffa1st-rv11-1daf0-f3357f"}], "id": "acffa1st-rv11-1daf0"}, {"kind": "formula", "title": "Calculating pay", "page": [239, 253], "items": [{"t": "f", "k": 1, "term": "Basic pay (hourly)", "text": "Hours worked x Hourly rate", "vars": "hours recorded on clock cards, timesheets, job cards", "id": "acffa1st-rv11-25bbf-1e3231"}, {"t": "f", "term": "Salary per period", "text": "Annual salary / Number of pay periods", "vars": "eg / 12 for monthly", "id": "acffa1st-rv11-25bbf-3d952b"}, {"t": "f", "k": 1, "term": "Piecework", "text": "Units produced x Rate per unit", "vars": "may have a guaranteed minimum", "eg": "$3.00 per packing case made", "id": "acffa1st-rv11-25bbf-031d29"}, {"t": "f", "k": 1, "term": "Overtime pay", "text": "Overtime hours x Hourly rate x Overtime multiple", "vars": "eg time-and-a-half = 1.5", "eg": "5 hours x $10 x 1.5 = $75", "id": "acffa1st-rv11-25bbf-172d39"}, {"t": "pt", "text": "Bonuses: extra earnings as a reward (individual, group, company-wide)", "id": "acffa1st-rv11-25bbf-b61068"}, {"t": "f", "term": "Commission", "text": "Sales value x Commission %", "vars": "may have tiered rates", "eg": "2% on all machinery + 0.5% extra on items over $10,000", "id": "acffa1st-rv11-25bbf-2be5ca"}, {"t": "pt", "text": "Salaried staff may or may not receive overtime", "id": "acffa1st-rv11-25bbf-ff6417"}], "id": "acffa1st-rv11-25bbf"}, {"kind": "rule", "title": "Authorisation, security and control", "page": [253, 255], "items": [{"t": "pt", "k": 1, "text": "Rates of pay must be authorised (personnel department) and recorded on the payroll record", "id": "acffa1st-rv11-e3e06-44b4ba"}, {"t": "pt", "text": "Job and department codes on time records allow costs to be charged correctly", "id": "acffa1st-rv11-e3e06-e01639"}, {"t": "pt", "k": 1, "text": "A responsible person reviews and authorises the payroll before payment", "id": "acffa1st-rv11-e3e06-62b7f2"}, {"t": "pt", "text": "Confidentiality: do not disclose pay details, restrict access, secure records and passwords", "id": "acffa1st-rv11-e3e06-8f96d2"}, {"t": "pt", "text": "Security: large sums are paid - segregation of duties between those who set rates, calculate pay and make payments", "id": "acffa1st-rv11-e3e06-6649cd"}, {"t": "pt", "text": "Personnel department: records of new starters, leavers, rates of pay and deductions authorisations", "id": "acffa1st-rv11-e3e06-201f7e"}], "id": "acffa1st-rv11-e3e06"}, {"kind": "process", "title": "Accounting for payroll", "page": [256, 260], "items": [{"t": "pt", "k": 1, "text": "Wages expense = gross pay + employer's contributions", "id": "acffa1st-rv11-f17ce-2b438b"}, {"t": "pt", "text": "Entries (via a wages control account): Dr Wages expense; Cr Bank (net pay), Cr Tax/benefit contributions payable (employee + employer amounts), Cr Pension payable (non-statutory deductions)", "id": "acffa1st-rv11-f17ce-c0999b"}, {"t": "pt", "k": 1, "text": "Amounts owed to the tax authority and pension fund are LIABILITIES (credit balances) until paid", "id": "acffa1st-rv11-f17ce-2e4884"}, {"t": "pt", "text": "Payment methods: cash, cheque, BACS/bank transfer", "id": "acffa1st-rv11-f17ce-da59c5"}, {"t": "exam", "text": "Which item does NOT appear on a payslip? Employer's contributions are not deductions from the employee's pay", "id": "acffa1st-rv11-f17ce-48a5be"}], "id": "acffa1st-rv11-f17ce"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Treating employer's contributions as a deduction from the employee's gross pay", "id": "acffa1st-rv11-6483a-11fe56"}, {"t": "x", "text": "Recording only net pay as the wages expense", "id": "acffa1st-rv11-6483a-657238"}, {"t": "x", "text": "Applying the overtime multiple to all hours instead of overtime hours only", "id": "acffa1st-rv11-6483a-8bf571"}, {"t": "x", "text": "Leaving payroll liabilities to the tax authority unrecorded", "id": "acffa1st-rv11-6483a-b867a7"}], "id": "acffa1st-rv11-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Gross pay = before deductions", "id": "acffa1st-rv11-80e78-bb5e3c"}, {"t": "pt", "text": "Net pay = after deductions", "id": "acffa1st-rv11-80e78-16234f"}, {"t": "pt", "text": "Statutory: income tax and employee contributions", "id": "acffa1st-rv11-80e78-1ff8f5"}, {"t": "pt", "text": "Non-statutory: pension, union, charity", "id": "acffa1st-rv11-80e78-0d63a6"}, {"t": "pt", "text": "Employer cost = gross pay + employer contributions", "id": "acffa1st-rv11-80e78-403baf"}, {"t": "pt", "text": "Basic pay = hours x rate", "id": "acffa1st-rv11-80e78-8960de"}, {"t": "pt", "text": "Overtime = overtime hours x rate x multiple", "id": "acffa1st-rv11-80e78-938653"}, {"t": "pt", "text": "Piecework = units x rate", "id": "acffa1st-rv11-80e78-6b3548"}, {"t": "pt", "text": "Commission = sales x %", "id": "acffa1st-rv11-80e78-2995b4"}, {"t": "pt", "text": "Authorise rates and the payroll", "id": "acffa1st-rv11-80e78-0ab156"}, {"t": "pt", "text": "Keep payroll confidential and segregated", "id": "acffa1st-rv11-80e78-ace61b"}, {"t": "pt", "text": "Dr wages expense; Cr bank, tax payable, pension payable", "id": "acffa1st-rv11-80e78-bd3b56"}, {"t": "pt", "text": "Deductions owed are liabilities", "id": "acffa1st-rv11-80e78-9d4327"}], "id": "acffa1st-rv11-80e78"}], "source": "Kaplan FA1 Study Text ch 11: sections 1-7 pp234-260; key terms p261", "summary": "The payroll system, gross and net pay, statutory and non-statutory deductions, payslips and payments, basic pay, overtime, bonuses and commission, authorisation, security and confidentiality, and accounting for payroll.", "id": "acffa1st-rv11", "updated": "2026-11-12"}, {"num": "12", "title": "Bank Reconciliations", "pages": [263, 280], "syllabus": "D1", "status": "published", "branches": [{"kind": "concept", "title": "Why reconcile", "page": [264, 266], "items": [{"t": "def", "k": 1, "term": "Bank reconciliation statement", "text": "A statement reconciling the balance in the cash book (bank account) with the balance on the bank statement", "id": "acffa1st-rv12-988a2-715cfd"}, {"t": "pt", "text": "Differences arise from timing (clearing system delays), items the bank knows about first, and errors", "id": "acffa1st-rv12-988a2-366886"}, {"t": "pt", "text": "Interest and charges are often only known when the bank statement arrives", "id": "acffa1st-rv12-988a2-a89556"}, {"t": "pt", "text": "Bank statement: a credit balance = money in the account (from the bank's view the bank owes the customer)", "id": "acffa1st-rv12-988a2-c24644"}], "id": "acffa1st-rv12-988a2"}, {"kind": "process", "title": "Preparing a bank reconciliation", "page": [266, 274], "items": [{"t": "pt", "k": 1, "text": "Step 1: compare the cash book with the bank statement and tick matching items", "id": "acffa1st-rv12-54d88-add4ef"}, {"t": "pt", "k": 1, "text": "Step 2: update the CASH BOOK for items on the bank statement not in the cash book (bank charges, interest, standing orders, direct debits, BACS receipts, dishonoured cheques) and for cash book errors", "id": "acffa1st-rv12-54d88-7ef9f6"}, {"t": "pt", "text": "Step 3: balance off the adjusted cash book", "id": "acffa1st-rv12-54d88-d45123"}, {"t": "pt", "k": 1, "text": "Step 4: identify items in the cash book not yet on the bank statement - unpresented cheques and outstanding lodgements (deposits)", "id": "acffa1st-rv12-54d88-649230"}, {"t": "pt", "k": 1, "text": "Step 5: prepare the reconciliation statement", "id": "acffa1st-rv12-54d88-5aa870"}, {"t": "f", "term": "Bank reconciliation", "text": "Balance per bank statement + Outstanding lodgements - Unpresented cheques = Balance per adjusted cash book", "vars": "work in the direction the question asks; take care with overdrafts", "id": "acffa1st-rv12-54d88-261270"}], "id": "acffa1st-rv12-54d88"}, {"kind": "concept", "title": "Errors and omissions", "page": [275, 275], "items": [{"t": "pt", "k": 1, "text": "Cash book errors: wrong amount entered, transposed figures, receipt entered as a payment (or vice versa) - correct in the cash book", "id": "acffa1st-rv12-abea7-d662d9"}, {"t": "pt", "text": "Cash book omissions: items on the bank statement not yet entered (standing orders, direct debits, charges, interest) - enter them in the cash book", "id": "acffa1st-rv12-abea7-f401c4"}, {"t": "pt", "text": "Bank errors: notify the bank - shown as a reconciling item, not in the cash book", "id": "acffa1st-rv12-abea7-f7363d"}, {"t": "exam", "text": "Exam-style questions ask which items require an entry in the cash book and which are reconciling items", "id": "acffa1st-rv12-abea7-3ed228"}], "id": "acffa1st-rv12-abea7"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Entering unpresented cheques in the cash book again", "id": "acffa1st-rv12-6483a-45f85e"}, {"t": "x", "text": "Forgetting to update the cash book for bank charges and direct debits", "id": "acffa1st-rv12-6483a-3dce42"}, {"t": "x", "text": "Reversing debit/credit when reading a bank statement", "id": "acffa1st-rv12-6483a-2aea0f"}, {"t": "x", "text": "Mishandling an overdraft as a positive balance", "id": "acffa1st-rv12-6483a-56dd11"}], "id": "acffa1st-rv12-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Reconcile cash book to bank statement", "id": "acffa1st-rv12-80e78-345483"}, {"t": "pt", "text": "Differences: timing, bank-only items, errors", "id": "acffa1st-rv12-80e78-ba934c"}, {"t": "pt", "text": "Update the cash book for charges, interest, SOs, DDs, BACS, dishonoured cheques", "id": "acffa1st-rv12-80e78-88fe84"}, {"t": "pt", "text": "Correct cash book errors", "id": "acffa1st-rv12-80e78-b28eb3"}, {"t": "pt", "text": "Reconciling items: unpresented cheques, outstanding lodgements, bank errors", "id": "acffa1st-rv12-80e78-36ca8a"}, {"t": "pt", "text": "Bank balance + lodgements - unpresented cheques = cash book", "id": "acffa1st-rv12-80e78-4ea1a4"}, {"t": "pt", "text": "Bank statement credit = money in the account", "id": "acffa1st-rv12-80e78-d84c44"}, {"t": "pt", "text": "Cash book debit = money in the bank", "id": "acffa1st-rv12-80e78-3d8ebb"}, {"t": "pt", "text": "Notify the bank of its errors", "id": "acffa1st-rv12-80e78-3eefa5"}, {"t": "pt", "text": "Watch overdraft signs", "id": "acffa1st-rv12-80e78-41ad66"}, {"t": "pt", "text": "Balance off the cash book after adjustments", "id": "acffa1st-rv12-80e78-b8aa0f"}, {"t": "pt", "text": "Reconcile regularly to detect errors and fraud", "id": "acffa1st-rv12-80e78-d8a8fd"}], "id": "acffa1st-rv12-80e78"}], "source": "Kaplan FA1 Study Text ch 12: sections 1-4 pp264-275; key terms p278", "summary": "Bank services and the clearing system, banking documentation, the step-by-step bank reconciliation statement, and errors and omissions in the cash book.", "id": "acffa1st-rv12", "updated": "2026-11-12"}, {"num": "13", "title": "Control Accounts", "pages": [281, 306], "syllabus": "D2", "status": "published", "branches": [{"kind": "def", "title": "Control accounts and ledgers", "page": [282, 282], "items": [{"t": "def", "k": 1, "term": "Receivables' ledger control account", "text": "Where the double entries for amounts due from customers are made - part of the nominal (general) ledger", "id": "acffa1st-rv13-1110d-1e2b2d"}, {"t": "def", "k": 1, "term": "Receivables' ledger", "text": "The summary of amounts owed by individual customers ('memorandum') - NOT part of the double entry", "id": "acffa1st-rv13-1110d-5de283"}, {"t": "def", "k": 1, "term": "Payables' ledger control account", "text": "Where the double entries for amounts owed to suppliers are made - part of the nominal ledger", "id": "acffa1st-rv13-1110d-c52d64"}, {"t": "def", "term": "Payables' ledger", "text": "Summary of amounts owed to individual suppliers - memorandum, not part of the double entry", "id": "acffa1st-rv13-1110d-61a8c1"}, {"t": "pt", "k": 1, "text": "A control account is a 'totals' account: its balance should equal the total of the individual balances in the subsidiary ledger", "id": "acffa1st-rv13-1110d-1341a7"}], "id": "acffa1st-rv13-1110d"}, {"kind": "compare", "title": "Control account entries", "page": [282, 293], "items": [{"t": "table", "rows": [["Receivables ledger control", "Payables ledger control"], ["Dr: balance b/f, credit sales (SDB), dishonoured cheques", "Dr: payments (cash book), purchase returns (PRDB), discounts received, contras"], ["Cr: receipts (cash book), sales returns (SRDB), irrecoverable debts, discounts allowed, contras", "Cr: balance b/f, credit purchases (PDB)"], ["Normal balance: debit (asset)", "Normal balance: credit (liability)"]], "id": "acffa1st-rv13-8ff92-ca7e5f"}, {"t": "pt", "text": "Contra entry: a business that is both customer and supplier sets off balances - Dr Payables control, Cr Receivables control", "id": "acffa1st-rv13-8ff92-382c8d"}], "id": "acffa1st-rv13-8ff92"}, {"kind": "process", "title": "Reconciling control accounts", "page": [286, 303], "items": [{"t": "pt", "k": 1, "text": "Compare the control account balance with the total of the list of individual balances; investigate and correct differences", "id": "acffa1st-rv13-9264d-8b229b"}, {"t": "pt", "text": "Errors affecting the CONTROL ACCOUNT only (correct with a journal): day book or cash book totals miscast, discounts omitted from the control account", "id": "acffa1st-rv13-9264d-a81dbb"}, {"t": "pt", "text": "Errors affecting the LIST of balances only: posting the wrong amount to a customer's account, posting to the wrong side, a balance omitted from the list, a balance miscopied", "id": "acffa1st-rv13-9264d-a01b69"}, {"t": "f", "k": 1, "term": "Reconciliation", "text": "Adjusted control account balance = Adjusted total of individual ledger balances", "vars": "correct each side for the errors that affect it", "id": "acffa1st-rv13-9264d-12b8ec"}, {"t": "pt", "text": "Correct control account errors by journal entries in the nominal ledger", "id": "acffa1st-rv13-9264d-a53557"}, {"t": "exam", "text": "Questions give a list of errors - decide whether each affects the control account, the list, or both", "id": "acffa1st-rv13-9264d-27c39d"}], "id": "acffa1st-rv13-9264d"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Correcting a list-of-balances error with a journal in the control account", "id": "acffa1st-rv13-6483a-618c4b"}, {"t": "x", "text": "Treating the receivables ledger as part of the double entry", "id": "acffa1st-rv13-6483a-c87ebf"}, {"t": "x", "text": "Posting a contra the wrong way round", "id": "acffa1st-rv13-6483a-ae22ac"}, {"t": "x", "text": "Forgetting that a debit-side posting error doubles the difference (eg $50 credited instead of debited = $100 difference)", "id": "acffa1st-rv13-6483a-f90bde"}], "id": "acffa1st-rv13-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Control accounts are in the nominal ledger", "id": "acffa1st-rv13-80e78-13a3d8"}, {"t": "pt", "text": "Individual ledgers are memorandum", "id": "acffa1st-rv13-80e78-17fa54"}, {"t": "pt", "text": "Control balance = total of individual balances", "id": "acffa1st-rv13-80e78-3f9f2e"}, {"t": "pt", "text": "Receivables control: debit balance", "id": "acffa1st-rv13-80e78-7a9eb3"}, {"t": "pt", "text": "Payables control: credit balance", "id": "acffa1st-rv13-80e78-ff8400"}, {"t": "pt", "text": "Receivables Dr: sales, dishonoured cheques", "id": "acffa1st-rv13-80e78-241334"}, {"t": "pt", "text": "Receivables Cr: receipts, returns, irrecoverable debts, contras", "id": "acffa1st-rv13-80e78-6292e3"}, {"t": "pt", "text": "Payables Dr: payments, returns, discounts received, contras", "id": "acffa1st-rv13-80e78-692ba5"}, {"t": "pt", "text": "Payables Cr: credit purchases", "id": "acffa1st-rv13-80e78-44d6ca"}, {"t": "pt", "text": "Contra: Dr payables control, Cr receivables control", "id": "acffa1st-rv13-80e78-11a320"}, {"t": "pt", "text": "Day book miscasts affect the control account", "id": "acffa1st-rv13-80e78-817e72"}, {"t": "pt", "text": "Posting errors to individual accounts affect the list only", "id": "acffa1st-rv13-80e78-4c8141"}, {"t": "pt", "text": "Correct control account errors by journal", "id": "acffa1st-rv13-80e78-0ca627"}], "id": "acffa1st-rv13-80e78"}], "source": "Kaplan FA1 Study Text ch 13: sections 1-5 pp282-303; key terms p305", "summary": "The purpose of control accounts, preparing receivables and payables ledger control accounts, reconciling them to the list of individual balances, typical discrepancies and correcting them with journals.", "id": "acffa1st-rv13", "updated": "2026-11-12"}, {"num": "14", "title": "The Trial Balance", "pages": [307, 332], "syllabus": "D3", "status": "published", "branches": [{"kind": "concept", "title": "The trial balance", "page": [308, 311], "items": [{"t": "def", "k": 1, "term": "Trial balance", "text": "A memorandum listing of all the nominal (general) ledger account balances", "id": "acffa1st-rv14-a3d69-cf4b1c"}, {"t": "pt", "k": 1, "text": "Three main reasons: check the arithmetical accuracy of the double entry • a basis for preparing the financial statements • identify errors", "id": "acffa1st-rv14-a3d69-6d0f05"}, {"t": "pt", "text": "Initial trial balance: list each ledger balance as debit or credit; total debits should equal total credits", "id": "acffa1st-rv14-a3d69-932a1c"}, {"t": "pt", "text": "Debit balances: assets, expenses, drawings; credit balances: liabilities, income, capital", "id": "acffa1st-rv14-a3d69-732841"}, {"t": "x", "text": "A trial balance that balances does NOT mean the records are error-free", "id": "acffa1st-rv14-a3d69-9b0f8a"}], "id": "acffa1st-rv14-a3d69"}, {"kind": "compare", "title": "Errors", "page": [312, 325], "items": [{"t": "table", "rows": [["Error", "TB still balances?", "Example"], ["Omission", "Yes", "Invoice never recorded"], ["Commission", "Yes", "Correct type of account but the wrong one (eg wrong expense account)"], ["Principle", "Yes", "Capital expenditure posted to an expense"], ["Original entry", "Yes", "Wrong amount in both entries"], ["Reversal", "Yes", "Debit and credit swapped"], ["Compensating", "Yes", "Two errors cancel"], ["One-sided / unequal entries", "No", "Only the debit posted"], ["Casting error", "No", "Column added up wrongly"]], "id": "acffa1st-rv14-07213-13b637"}, {"t": "eg", "text": "Stationery posted to the wrong expense account: Dr Stationery, Cr the wrong expense account (no suspense)", "id": "acffa1st-rv14-07213-e25d25"}], "id": "acffa1st-rv14-07213"}, {"kind": "process", "title": "Suspense account and journals", "page": [320, 327], "items": [{"t": "def", "k": 1, "term": "Suspense account", "text": "A temporary account used to hold the difference between trial balance column totals; closed once errors are identified and corrected", "id": "acffa1st-rv14-84dde-7c135d"}, {"t": "pt", "k": 1, "text": "Journal: Dr account, Cr account, amount, date and narrative - used to correct errors", "id": "acffa1st-rv14-84dde-80b037"}, {"t": "pt", "text": "If one side of an entry is missing or wrong, the correcting journal's other side goes to SUSPENSE", "id": "acffa1st-rv14-84dde-bb9794"}, {"t": "eg", "text": "Credit purchases debited to the payables control instead of credited: an imbalance of twice the amount - correct via suspense", "id": "acffa1st-rv14-84dde-fced87"}, {"t": "pt", "k": 1, "text": "Good practice: extract a revised trial balance after errors are corrected", "id": "acffa1st-rv14-84dde-93116a"}, {"t": "exam", "text": "Exam-style questions ask for the suspense balance or the correcting journal for a list of errors", "id": "acffa1st-rv14-84dde-8ebfa1"}], "id": "acffa1st-rv14-84dde"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Passing every correction through the suspense account - only errors that caused an imbalance", "id": "acffa1st-rv14-6483a-4231f3"}, {"t": "x", "text": "Getting the side of the initial suspense entry wrong", "id": "acffa1st-rv14-6483a-09285e"}, {"t": "x", "text": "Assuming a balanced TB proves accuracy", "id": "acffa1st-rv14-6483a-77ff38"}, {"t": "x", "text": "Correcting a reversal error with a single amount - it needs double the amount", "id": "acffa1st-rv14-6483a-ce7271"}], "id": "acffa1st-rv14-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "TB = memorandum list of nominal ledger balances", "id": "acffa1st-rv14-80e78-abb2dc"}, {"t": "pt", "text": "Purposes: arithmetic check, basis for accounts, find errors", "id": "acffa1st-rv14-80e78-bdc0bb"}, {"t": "pt", "text": "Debits = credits if double entry is arithmetically correct", "id": "acffa1st-rv14-80e78-130a18"}, {"t": "pt", "text": "Errors not revealed: omission, commission, principle, original entry, reversal, compensating", "id": "acffa1st-rv14-80e78-d90845"}, {"t": "pt", "text": "Errors revealed: one-sided, unequal, casting", "id": "acffa1st-rv14-80e78-33cc72"}, {"t": "pt", "text": "Suspense holds the TB difference temporarily", "id": "acffa1st-rv14-80e78-464b7d"}, {"t": "pt", "text": "Journals correct errors with narratives", "id": "acffa1st-rv14-80e78-d38105"}, {"t": "pt", "text": "Only one-sided errors use suspense", "id": "acffa1st-rv14-80e78-3eba47"}, {"t": "pt", "text": "Reversal corrected with twice the amount", "id": "acffa1st-rv14-80e78-a9c5b7"}, {"t": "pt", "text": "Clear suspense, then redraft the TB", "id": "acffa1st-rv14-80e78-8e8c19"}, {"t": "pt", "text": "Debit balances: assets, expenses, drawings", "id": "acffa1st-rv14-80e78-0661ad"}, {"t": "pt", "text": "Credit balances: liabilities, income, capital", "id": "acffa1st-rv14-80e78-f21baf"}], "id": "acffa1st-rv14-80e78"}], "source": "Kaplan FA1 Study Text ch 14: sections 1-4 pp308-327; key terms p328", "summary": "Why and how an initial trial balance is prepared, errors that do and do not affect its balance, the suspense account, correcting errors with journals and redrafting the trial balance.", "id": "acffa1st-rv14", "updated": "2026-11-12"}], "plannedChapters": 14}, {"id": "acffa2", "code": "F3", "name": "Financial Accounting", "level": "Applied Knowledge", "book": "ACCA-FA-ed2.pdf | Kaplan ACCA FA Study Text (2024/25 edition) | offset 31", "updated": "2026-11-12", "chapters": [{"num": "1", "title": "Introduction to Financial Reporting", "pages": [1, 24], "syllabus": "A1, A2", "status": "published", "branches": [{"kind": "concept", "title": "Financial reporting and its users", "page": [2, 5], "items": [{"t": "pt", "k": 1, "text": "Financial accounting: recording, classifying and summarising transactions to produce annual financial statements for EXTERNAL stakeholders - a report on the directors' stewardship", "id": "acffa2-rv1-63186-6d050d"}, {"t": "pt", "text": "Management accounting: detailed, up-to-date information for management to plan, control and make decisions (formulating strategy, planning and control, decision making, optimising resources)", "id": "acffa2-rv1-63186-dfddf5"}, {"t": "pt", "k": 1, "text": "Users: investors (profit, returns, security), employees and unions (job security, pay), lenders (repayment), government and tax authorities, suppliers (will they be paid), customers (continuity of supply), the public; also management and competitors", "id": "acffa2-rv1-63186-82b7e5"}, {"t": "exam", "text": "Management need the MOST detailed information - they use management accounts rather than published accounts", "id": "acffa2-rv1-63186-f9f52d"}], "id": "acffa2-rv1-63186"}, {"kind": "compare", "title": "Types of business entity", "page": [5, 9], "items": [{"t": "table", "rows": [["Feature", "Sole trader", "Partnership", "Limited liability company"], ["Owners", "One individual", "Two or more partners", "Shareholders"], ["Legal identity", "Not separate from the owner", "Not separate from the partners", "Separate legal entity (incorporation)"], ["Liability", "Unlimited", "Unlimited, joint and several", "Limited to shareholders' investment"], ["Capital", "Capital account; drawings", "Capital and current accounts per partner", "Share capital, reserves; dividends not drawings"], ["Managed by", "Owner", "Partners", "Board of directors elected by shareholders"]], "id": "acffa2-rv1-bd4b1-ce6745"}, {"t": "pt", "k": 1, "text": "Accounting treats every business as separate from its owner (business entity concept), even when the law does not", "id": "acffa2-rv1-bd4b1-e22d5e"}, {"t": "pt", "text": "Company advantages: owns property in its own name, transferable shares, sues and is sued, can secure loans with floating charges, taxed separately", "id": "acffa2-rv1-bd4b1-30df22"}, {"t": "pt", "text": "Disadvantages of incorporation: formation costs, publication of accounts, audit, more regulation", "id": "acffa2-rv1-bd4b1-46b431"}], "id": "acffa2-rv1-bd4b1"}, {"kind": "concept", "title": "The Conceptual Framework", "page": [9, 13], "items": [{"t": "pt", "k": 1, "text": "Purpose: assist the IASB in developing standards and help preparers develop policies where standards give no guidance; aid understanding of standards", "id": "acffa2-rv1-0c40d-d2feac"}, {"t": "pt", "k": 1, "text": "Objective: provide financial information about the reporting entity that is useful to users in making decisions about providing economic resources", "id": "acffa2-rv1-0c40d-132176"}, {"t": "pt", "text": "Prudence: caution when making judgements under uncertainty - assets and income not overstated, liabilities and expenses not understated", "id": "acffa2-rv1-0c40d-ad0352"}, {"t": "pt", "k": 1, "text": "Fundamental qualitative characteristics: RELEVANCE (predictive and/or confirmatory value; materiality) and FAITHFUL REPRESENTATION (complete, neutral, free from error)", "id": "acffa2-rv1-0c40d-42f0a2"}, {"t": "pt", "k": 1, "text": "Enhancing characteristics: comparability • verifiability • timeliness • understandability", "id": "acffa2-rv1-0c40d-27e157"}], "id": "acffa2-rv1-0c40d"}, {"kind": "def", "title": "The elements", "page": [13, 16], "items": [{"t": "def", "k": 1, "term": "Asset", "text": "A present economic resource controlled by the entity as a result of past events", "id": "acffa2-rv1-e8841-2301fb"}, {"t": "def", "k": 1, "term": "Liability", "text": "A present obligation of the entity to transfer an economic resource as a result of past events", "id": "acffa2-rv1-e8841-1ee451"}, {"t": "def", "k": 1, "term": "Equity", "text": "The residual interest in the assets of the entity after deducting all its liabilities", "id": "acffa2-rv1-e8841-5c505d"}, {"t": "def", "term": "Income", "text": "Increases in assets or decreases in liabilities that increase equity, other than contributions from equity holders", "id": "acffa2-rv1-e8841-c02e1f"}, {"t": "def", "term": "Expenses", "text": "Decreases in assets or increases in liabilities that decrease equity, other than distributions to equity holders", "id": "acffa2-rv1-e8841-fd0391"}, {"t": "pt", "text": "Current vs non-current: current assets are expected to be realised within 12 months / in the normal operating cycle; current liabilities settled within 12 months", "id": "acffa2-rv1-e8841-622542"}, {"t": "eg", "text": "Land and buildings, delivery van = non-current assets; receivables and cash = current assets; loan repayable in two years = non-current liability; payables = current liability", "id": "acffa2-rv1-e8841-c9666d"}], "id": "acffa2-rv1-e8841"}, {"kind": "concept", "title": "Components of financial statements", "page": [16, 19], "items": [{"t": "pt", "k": 1, "text": "Statement of financial position (assets, liabilities, equity at the reporting date)", "id": "acffa2-rv1-01ca1-c8829b"}, {"t": "pt", "k": 1, "text": "Statement of profit or loss and other comprehensive income (revenue and expenses for the period)", "id": "acffa2-rv1-01ca1-92d9c8"}, {"t": "pt", "text": "Statement of changes in equity (movements in share capital, premium, revaluation surplus, retained earnings)", "id": "acffa2-rv1-01ca1-6ad4e8"}, {"t": "pt", "text": "Statement of cash flows (cash paid and received)", "id": "acffa2-rv1-01ca1-d68f89"}, {"t": "pt", "text": "Notes (accounting policies and other disclosures)", "id": "acffa2-rv1-01ca1-cffe64"}], "id": "acffa2-rv1-01ca1"}, {"kind": "rule", "title": "Accounting principles and concepts", "page": [19, 22], "items": [{"t": "pt", "k": 1, "text": "Materiality: an item is material if its omission or misstatement would change users' understanding/decisions", "id": "acffa2-rv1-68edc-0e5fd3"}, {"t": "pt", "k": 1, "text": "Substance over form: account for economic reality, not just the legal form", "id": "acffa2-rv1-68edc-40a426"}, {"t": "pt", "k": 1, "text": "Going concern: the entity will continue to operate for the foreseeable future", "id": "acffa2-rv1-68edc-57990e"}, {"t": "pt", "text": "Business entity: the accounts relate only to the business, not the owner's personal affairs", "id": "acffa2-rv1-68edc-f0be85"}, {"t": "pt", "k": 1, "text": "Accrual accounting: record revenue when earned and expenses when incurred, regardless of cash timing", "id": "acffa2-rv1-68edc-7646d6"}, {"t": "pt", "text": "Prudence, consistency (same treatment period to period and within a period), no offsetting (unless required/permitted)", "id": "acffa2-rv1-68edc-0a8fd0"}, {"t": "pt", "text": "Duality: every transaction has two effects - the basis of double entry", "id": "acffa2-rv1-68edc-3fb8c7"}, {"t": "pt", "text": "Historical cost (original transaction value) vs current value (eg fair value)", "id": "acffa2-rv1-68edc-be56cd"}], "id": "acffa2-rv1-68edc"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Saying sole traders and partners have limited liability", "id": "acffa2-rv1-6483a-c3bb9c"}, {"t": "x", "text": "Listing comparability as a fundamental characteristic - it is enhancing", "id": "acffa2-rv1-6483a-695823"}, {"t": "x", "text": "Treating a loan repayable in two years as a current liability", "id": "acffa2-rv1-6483a-160570"}, {"t": "x", "text": "Recording revenue only when cash is received - accruals basis applies", "id": "acffa2-rv1-6483a-47bc3a"}], "id": "acffa2-rv1-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Financial accounting: external users, stewardship", "id": "acffa2-rv1-80e78-c4e8a8"}, {"t": "pt", "text": "Management accounting: internal, detailed, future-focused", "id": "acffa2-rv1-80e78-62a99d"}, {"t": "pt", "text": "Users: investors, employees, lenders, government, suppliers, customers, public", "id": "acffa2-rv1-80e78-cf149a"}, {"t": "pt", "text": "Company = separate legal entity, limited liability", "id": "acffa2-rv1-80e78-ddb745"}, {"t": "pt", "text": "Sole traders and partners: unlimited liability", "id": "acffa2-rv1-80e78-376449"}, {"t": "pt", "text": "Fundamental: relevance and faithful representation", "id": "acffa2-rv1-80e78-c5fb5c"}, {"t": "pt", "text": "Enhancing: comparability, verifiability, timeliness, understandability", "id": "acffa2-rv1-80e78-cd1577"}, {"t": "pt", "text": "Faithful representation: complete, neutral, free from error", "id": "acffa2-rv1-80e78-bece1a"}, {"t": "pt", "text": "Asset = present economic resource controlled from past events", "id": "acffa2-rv1-80e78-2f7f85"}, {"t": "pt", "text": "Liability = present obligation to transfer an economic resource", "id": "acffa2-rv1-80e78-b16f1b"}, {"t": "pt", "text": "Equity = assets - liabilities", "id": "acffa2-rv1-80e78-223c9b"}, {"t": "pt", "text": "Five statements: SOFP, P/L and OCI, SOCE, cash flows, notes", "id": "acffa2-rv1-80e78-231b57"}, {"t": "pt", "text": "Concepts: materiality, substance over form, going concern, accruals, prudence, consistency, duality", "id": "acffa2-rv1-80e78-96141e"}], "id": "acffa2-rv1-80e78"}], "source": "Kaplan FA Study Text ch 1: sections 1-8 pp2-22; chapter summary p23", "summary": "Financial vs management accounting, users and their needs, types of business entity, the Conceptual Framework, qualitative characteristics, the elements, the components of financial statements and key accounting principles.", "id": "acffa2-rv1", "updated": "2026-11-12"}, {"num": "2", "title": "The Regulatory Framework", "pages": [25, 38], "syllabus": "B1", "status": "published", "branches": [{"kind": "concept", "title": "Why regulation is needed", "page": [26, 27], "items": [{"t": "pt", "k": 1, "text": "Regulation ensures financial statements are reliable, comparable and meet users' needs, and reduces the scope for manipulation", "id": "acffa2-rv2-091a7-781dfe"}, {"t": "pt", "text": "National frameworks combine company law, national standards, stock exchange rules and tax law", "id": "acffa2-rv2-091a7-c93518"}, {"t": "pt", "k": 1, "text": "Harmonisation through IFRS Accounting Standards reduces differences between countries, helping cross-border investment and comparison", "id": "acffa2-rv2-091a7-a1297f"}], "id": "acffa2-rv2-091a7"}, {"kind": "process", "title": "The international regulatory structure", "page": [28, 30], "items": [{"t": "pt", "k": 1, "text": "IFRS Foundation: supervisory body - governance, funding, appointing members of the Board", "id": "acffa2-rv2-0d491-f65e74"}, {"t": "pt", "k": 1, "text": "International Accounting Standards Board (IASB): independent standard-setter - develops IFRS Standards", "id": "acffa2-rv2-0d491-7fb39c"}, {"t": "pt", "k": 1, "text": "IFRS Interpretations Committee (IFRIC): reviews widespread accounting issues and provides authoritative guidance (interpretations)", "id": "acffa2-rv2-0d491-631d2e"}, {"t": "pt", "text": "IFRS Advisory Council: formal advisory body to the Board and the Foundation - wide range of members", "id": "acffa2-rv2-0d491-0d9d59"}, {"t": "pt", "text": "International Sustainability Standards Board (ISSB): formed 2021 to deliver a global baseline of sustainability-related disclosure standards", "id": "acffa2-rv2-0d491-e739bb"}, {"t": "pt", "k": 1, "text": "Development of an IFRS Standard (due process): identify a subject and set up an advisory committee -> discussion paper -> exposure draft for public comment -> consider comments -> issue the standard", "id": "acffa2-rv2-0d491-52a933"}, {"t": "exam", "text": "Know which body does what - eg IFRIC interprets, the IASB sets standards, the Foundation oversees", "id": "acffa2-rv2-0d491-a0c028"}], "id": "acffa2-rv2-0d491"}, {"kind": "concept", "title": "Ownership, control and audit", "page": [30, 32], "items": [{"t": "pt", "k": 1, "text": "In a company, ownership (shareholders) is separated from control (directors) - shareholders rely on the financial statements to judge directors' stewardship", "id": "acffa2-rv2-f5861-04f076"}, {"t": "pt", "k": 1, "text": "External auditors: independent and appropriately qualified; express an opinion on whether the financial statements give a true and fair view (present fairly)", "id": "acffa2-rv2-f5861-859397"}, {"t": "pt", "text": "Unreliable and fraudulent reporting by directors led to stronger governance and audit requirements", "id": "acffa2-rv2-f5861-d815b8"}], "id": "acffa2-rv2-f5861"}, {"kind": "concept", "title": "Corporate governance", "page": [32, 35], "items": [{"t": "def", "k": 1, "term": "Corporate governance", "text": "The system by which companies are directed and controlled", "id": "acffa2-rv2-d9a3e-8d2bfd"}, {"t": "pt", "text": "Purpose: monitor those who control the company's resources and assets, protect shareholders and maintain market confidence", "id": "acffa2-rv2-d9a3e-43faea"}, {"t": "pt", "k": 1, "text": "UK Corporate Governance Code (2018): 'comply or explain' - listed companies comply with the principles or explain why not", "id": "acffa2-rv2-d9a3e-236272"}, {"t": "pt", "k": 1, "text": "US Sarbanes-Oxley Act: governance enshrined in LAW - compliance compulsory, failure can bring criminal penalties", "id": "acffa2-rv2-d9a3e-6b066d"}, {"t": "pt", "text": "Typical provisions: separate chair and CEO, independent non-executive directors, audit and remuneration committees, internal control reporting", "id": "acffa2-rv2-d9a3e-b0589b"}], "id": "acffa2-rv2-d9a3e"}, {"kind": "compare", "title": "Principles vs rules", "page": [34, 35], "items": [{"t": "table", "rows": [["Feature", "Principles-based (UK code)", "Rules-based (US SOX)"], ["Status", "Code - comply or explain", "Law - compulsory"], ["Flexibility", "High - adapt to circumstances", "Low - detailed rules"], ["Penalty", "Market and reputational pressure", "Legal and criminal penalties"]], "id": "acffa2-rv2-259f4-375e3b"}], "id": "acffa2-rv2-259f4"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Saying the IFRS Foundation writes the standards - the IASB does", "id": "acffa2-rv2-6483a-4f1d9f"}, {"t": "x", "text": "Confusing IFRIC (interpretations) with the Advisory Council (advice)", "id": "acffa2-rv2-6483a-e7a797"}, {"t": "x", "text": "Treating the UK Corporate Governance Code as law - it is 'comply or explain'", "id": "acffa2-rv2-6483a-91d207"}, {"t": "x", "text": "Thinking auditors prepare the financial statements - directors prepare them; auditors give an opinion", "id": "acffa2-rv2-6483a-c46a3b"}], "id": "acffa2-rv2-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Regulation: reliability, comparability, less manipulation", "id": "acffa2-rv2-80e78-d598cb"}, {"t": "pt", "text": "Harmonisation via IFRS Accounting Standards", "id": "acffa2-rv2-80e78-ac20b2"}, {"t": "pt", "text": "IFRS Foundation oversees; IASB sets standards", "id": "acffa2-rv2-80e78-2a01d6"}, {"t": "pt", "text": "IFRIC issues interpretations", "id": "acffa2-rv2-80e78-4c1349"}, {"t": "pt", "text": "Advisory Council advises", "id": "acffa2-rv2-80e78-b0efd2"}, {"t": "pt", "text": "ISSB: sustainability disclosure standards (2021)", "id": "acffa2-rv2-80e78-bc1f43"}, {"t": "pt", "text": "Due process: discussion paper -> exposure draft -> standard", "id": "acffa2-rv2-80e78-b7ec38"}, {"t": "pt", "text": "Separation of ownership and control", "id": "acffa2-rv2-80e78-19aba6"}, {"t": "pt", "text": "External auditor: independent true and fair opinion", "id": "acffa2-rv2-80e78-ca096a"}, {"t": "pt", "text": "Corporate governance = directed and controlled", "id": "acffa2-rv2-80e78-0858f1"}, {"t": "pt", "text": "UK code: comply or explain", "id": "acffa2-rv2-80e78-2a08da"}, {"t": "pt", "text": "Sarbanes-Oxley: compulsory law", "id": "acffa2-rv2-80e78-41f06d"}], "id": "acffa2-rv2-80e78"}], "source": "Kaplan FA Study Text ch 2: sections 1-7 pp26-35; chapter summary p36", "summary": "Why regulation is needed, national frameworks, harmonisation through IFRS Standards, the IFRS Foundation, IASB, IFRIC, Advisory Council and ISSB, standard-setting due process, external audit and corporate governance (UK code, Sarbanes-Oxley).", "id": "acffa2-rv2", "updated": "2026-11-12"}, {"num": "3", "title": "Double-entry Bookkeeping", "pages": [39, 68], "syllabus": "C1, C2", "status": "published", "branches": [{"kind": "compare", "title": "Business documents", "page": [40, 42], "items": [{"t": "table", "rows": [["Document", "Purpose"], ["Quotation", "Establishes price from suppliers"], ["Purchase requisition", "Internal request for goods/services"], ["Purchase order", "Order sent to the supplier"], ["Sales order", "Customer's requirements recorded by the seller"], ["Despatch note (GDN)", "Goods despatched - signed by the customer"], ["Goods received note (GRN)", "Customer's proof of receipt, matched with the despatch note"], ["Sales / purchase invoice", "Request for payment: goods, price, sales tax, credit terms"], ["Credit note", "Seller reduces the amount owed (eg goods returned)"], ["Debit note", "Buyer's request for a credit note"], ["Supplier statement", "Summary of invoices, payments and balance"], ["Remittance advice", "Sent by the customer with payment, listing invoices paid"], ["Receipt", "Confirms payment received"]], "id": "acffa2-rv3-bf6cb-846ea7"}], "id": "acffa2-rv3-bf6cb"}, {"kind": "formula", "title": "Duality and the accounting equation", "page": [42, 47], "items": [{"t": "pt", "k": 1, "text": "Duality: every transaction has two effects, so it is recorded twice", "id": "acffa2-rv3-2d95d-88ff85"}, {"t": "f", "k": 1, "term": "Accounting equation", "text": "Assets = Equity + Liabilities", "vars": "equity = capital introduced + profit - drawings", "eg": "Ali introduces $1,000: assets 1,000 = equity 1,000", "id": "acffa2-rv3-2d95d-329448"}, {"t": "pt", "text": "Paying rent: assets down, equity down (expense); buying a van for cash: one asset up, another down", "id": "acffa2-rv3-2d95d-2be898"}, {"t": "pt", "text": "Bank loan: assets up, liabilities up; credit sale at a profit: receivables up more than inventory down, equity up by the profit", "id": "acffa2-rv3-2d95d-06617c"}, {"t": "eg", "text": "Purchases on credit: increase inventory, increase payables", "id": "acffa2-rv3-2d95d-d49e6d"}], "id": "acffa2-rv3-2d95d"}, {"kind": "rule", "title": "Debit and credit rules", "page": [48, 56], "items": [{"t": "pt", "k": 1, "text": "Debit (Dr, left side): increase in an ASSET or EXPENSE (or drawings); decrease in a liability, income or equity", "id": "acffa2-rv3-6a9dd-da46db"}, {"t": "pt", "k": 1, "text": "Credit (Cr, right side): increase in a LIABILITY, INCOME or EQUITY; decrease in an asset or expense", "id": "acffa2-rv3-6a9dd-02af87"}, {"t": "pt", "text": "Process: source documents -> books of prime entry -> ledger accounts -> trial balance -> financial statements", "id": "acffa2-rv3-6a9dd-f9f955"}, {"t": "pt", "text": "Balancing a ledger account: total both sides, insert the balancing figure as 'balance c/f' on the smaller side, bring it down ('balance b/f') on the opposite side", "id": "acffa2-rv3-6a9dd-d9369b"}, {"t": "pt", "k": 1, "text": "Debit balances: assets, expenses, drawings; credit balances: liabilities, income, capital", "id": "acffa2-rv3-6a9dd-732841"}, {"t": "pt", "text": "Income and expense accounts are closed off to the statement of profit or loss at the year end; asset, liability and capital balances are carried forward", "id": "acffa2-rv3-6a9dd-ee3621"}, {"t": "exam", "text": "Mnemonic: DEAD CLIC - Debit: Expenses, Assets, Drawings; Credit: Liabilities, Income, Capital", "id": "acffa2-rv3-6a9dd-9987f5"}], "id": "acffa2-rv3-6a9dd"}, {"kind": "concept", "title": "Accounting systems and developments", "page": [49, 53], "items": [{"t": "pt", "text": "Accounting systems record transactions and monitor the effectiveness of the business (eg credit control, inventory levels)", "id": "acffa2-rv3-2a4dc-14d8d3"}, {"t": "def", "k": 1, "term": "Cloud computing", "text": "Access to software and data storage hosted on remote servers via the internet", "id": "acffa2-rv3-2a4dc-801b53"}, {"t": "def", "k": 1, "term": "Cloud accounting", "text": "The application of cloud computing to accounting systems and processes - external access to accounting data anywhere", "id": "acffa2-rv3-2a4dc-c05dea"}, {"t": "pt", "text": "Cloud advantages: no software to install or protect on each machine, scalable capacity, real-time access, automatic updates, easier collaboration (eg with the accountant)", "id": "acffa2-rv3-2a4dc-e9bf2d"}, {"t": "pt", "text": "Cloud risks: data security, reliance on the provider and the internet, loss of control", "id": "acffa2-rv3-2a4dc-bd47e6"}], "id": "acffa2-rv3-2a4dc"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Crediting an expense when it is incurred - expenses are debited", "id": "acffa2-rv3-6483a-8af0be"}, {"t": "x", "text": "Thinking a credit to the bank account means money received - it means money paid out", "id": "acffa2-rv3-6483a-e5ffe5"}, {"t": "x", "text": "Bringing down the balance on the same side as the c/f figure - b/f goes on the opposite side", "id": "acffa2-rv3-6483a-ee60ce"}, {"t": "x", "text": "Treating drawings as an expense of the business - drawings reduce equity", "id": "acffa2-rv3-6483a-cb3dbe"}], "id": "acffa2-rv3-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Assets = equity + liabilities", "id": "acffa2-rv3-80e78-01160e"}, {"t": "pt", "text": "Every transaction has two effects", "id": "acffa2-rv3-80e78-5e5819"}, {"t": "pt", "text": "Dr: assets, expenses, drawings increase", "id": "acffa2-rv3-80e78-369353"}, {"t": "pt", "text": "Cr: liabilities, income, capital increase", "id": "acffa2-rv3-80e78-c52473"}, {"t": "pt", "text": "DEAD CLIC", "id": "acffa2-rv3-80e78-4b1bf2"}, {"t": "pt", "text": "Source documents -> prime entry -> ledgers -> TB -> FS", "id": "acffa2-rv3-80e78-5df3a2"}, {"t": "pt", "text": "Balance c/f then b/f on the opposite side", "id": "acffa2-rv3-80e78-1e602b"}, {"t": "pt", "text": "Income and expenses close to P/L; SOFP balances carry forward", "id": "acffa2-rv3-80e78-9d8b15"}, {"t": "pt", "text": "Despatch note with goods; GRN on receipt", "id": "acffa2-rv3-80e78-e3b03e"}, {"t": "pt", "text": "Credit note reduces the amount owed", "id": "acffa2-rv3-80e78-47e74d"}, {"t": "pt", "text": "Remittance advice accompanies payment", "id": "acffa2-rv3-80e78-fbcccd"}, {"t": "pt", "text": "Cloud accounting: remote, real-time, scalable", "id": "acffa2-rv3-80e78-828429"}], "id": "acffa2-rv3-80e78"}], "source": "Kaplan FA Study Text ch 3: sections 1-7 pp40-61; chapter summary p63", "summary": "Business documents, duality and the accounting equation, the process from transactions to financial statements, ledger accounts and debit/credit rules, balancing accounts, accounting systems and cloud accounting.", "id": "acffa2-rv3", "updated": "2026-11-12"}, {"num": "4", "title": "Recording Transactions and Events", "pages": [69, 96], "syllabus": "C1", "status": "published", "branches": [{"kind": "rule", "title": "Cash, credit and bank transactions", "page": [70, 76], "items": [{"t": "pt", "k": 1, "text": "Cash sale: Dr Cash at bank, Cr Sales; credit sale: Dr Receivables, Cr Sales", "id": "acffa2-rv4-0f7b3-3ea07f"}, {"t": "pt", "k": 1, "text": "Cash purchase: Dr Purchases, Cr Cash at bank; credit purchase: Dr Purchases, Cr Payables", "id": "acffa2-rv4-0f7b3-b5ab59"}, {"t": "pt", "text": "Bank payments report is analysed (payables, wages, rent, petty cash) and posted: Dr each expense/payable, Cr Cash at bank (total)", "id": "acffa2-rv4-0f7b3-0b63d9"}, {"t": "pt", "text": "Bank receipts report: Dr Cash at bank, Cr receivables, interest, sales tax etc", "id": "acffa2-rv4-0f7b3-867b0c"}, {"t": "def", "k": 1, "term": "Petty cash", "text": "Small sums of notes and coins held to reimburse minor expenses", "id": "acffa2-rv4-0f7b3-04c3a8"}, {"t": "pt", "text": "Imprest system: petty cash is topped up to a fixed float - top-up: Dr Petty cash, Cr Cash at bank; payments: Dr expenses (and sales tax), Cr Petty cash", "id": "acffa2-rv4-0f7b3-ffc404"}], "id": "acffa2-rv4-0f7b3"}, {"kind": "compare", "title": "Returns", "page": [78, 78], "items": [{"t": "table", "rows": [["Transaction", "Originally credit", "Originally cash"], ["Sales returns (returns inwards)", "Dr Sales returns, Cr Receivables", "Dr Sales returns, Cr Cash at bank"], ["Purchases returns (returns outwards)", "Dr Payables, Cr Purchases returns", "Dr Cash at bank, Cr Purchases returns"]], "id": "acffa2-rv4-7fff8-e74342"}], "id": "acffa2-rv4-7fff8"}, {"kind": "formula", "title": "Sales tax", "page": [79, 84], "items": [{"t": "pt", "k": 1, "text": "Sales tax is levied on the FINAL consumer; a registered business collects it on sales and recovers it on purchases", "id": "acffa2-rv4-87f66-7944bb"}, {"t": "def", "k": 1, "term": "Output tax", "text": "Sales tax charged on sales - owed to the tax authority", "id": "acffa2-rv4-87f66-a9b13f"}, {"t": "def", "k": 1, "term": "Input tax", "text": "Sales tax paid on purchases - recoverable from the tax authority", "id": "acffa2-rv4-87f66-4b9951"}, {"t": "f", "term": "Sales tax on a net amount", "text": "Net price x sales tax rate", "vars": "20% on $1,000 net = $200; gross $1,200", "id": "acffa2-rv4-87f66-7719ba"}, {"t": "f", "term": "Sales tax in a gross amount", "text": "Gross price x rate / (100 + rate)", "vars": "20% rate: $1,200 x 20/120 = $200", "id": "acffa2-rv4-87f66-600398"}, {"t": "pt", "k": 1, "text": "Purchase: Dr Purchases (net), Dr Sales tax (input), Cr Payables/Bank (gross)", "id": "acffa2-rv4-87f66-523738"}, {"t": "pt", "k": 1, "text": "Sale: Dr Receivables/Bank (gross), Cr Sales (net), Cr Sales tax (output)", "id": "acffa2-rv4-87f66-f6cae9"}, {"t": "pt", "text": "Output tax > input tax -> pay the difference to the tax authority (credit balance on the sales tax account = liability)", "id": "acffa2-rv4-87f66-525dbc"}, {"t": "pt", "text": "Input tax > output tax -> refund due (debit balance = asset)", "id": "acffa2-rv4-87f66-ea9218"}, {"t": "x", "text": "Revenue and purchases are recorded NET of sales tax", "id": "acffa2-rv4-87f66-b953ac"}], "id": "acffa2-rv4-87f66"}, {"kind": "compare", "title": "Discounts", "page": [84, 89], "items": [{"t": "table", "rows": [["Feature", "Trade discount", "Settlement (early payment) discount"], ["Purpose", "Increase volume, loyalty", "Encourage prompt payment"], ["When", "Deducted at the point of sale", "Depends on the customer paying early"], ["Recording", "Sale/purchase recorded net of the trade discount - no separate entry", "Seller: IFRS 15 variable consideration; purchaser: discount received"]], "id": "acffa2-rv4-9544f-9976ad"}, {"t": "pt", "k": 1, "text": "Seller: if the customer is EXPECTED to take the settlement discount, record revenue net of it; if not expected, record the full amount and adjust if the discount is later taken", "id": "acffa2-rv4-9544f-8791a3"}, {"t": "pt", "k": 1, "text": "Purchaser: initially records the full amount; if the discount is taken, Dr Payables, Cr Discount received (income)", "id": "acffa2-rv4-9544f-f30ac4"}, {"t": "pt", "text": "Sales tax is calculated on the price after trade discount", "id": "acffa2-rv4-9544f-f5f2dc"}, {"t": "exam", "text": "Exam questions state whether the customer is expected to take the settlement discount", "id": "acffa2-rv4-9544f-1dd1cc"}], "id": "acffa2-rv4-9544f"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Recording sales or purchases gross of sales tax", "id": "acffa2-rv4-6483a-0d5137"}, {"t": "x", "text": "Showing trade discount as a separate expense - sales are simply recorded net", "id": "acffa2-rv4-6483a-870d51"}, {"t": "x", "text": "Debiting the sales tax account for output tax - output tax is a credit (liability)", "id": "acffa2-rv4-6483a-200bb7"}, {"t": "x", "text": "Recording discount received as a reduction of sales - it is income of the purchaser", "id": "acffa2-rv4-6483a-33d887"}], "id": "acffa2-rv4-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Credit sale: Dr Receivables, Cr Sales", "id": "acffa2-rv4-80e78-7fe95f"}, {"t": "pt", "text": "Credit purchase: Dr Purchases, Cr Payables", "id": "acffa2-rv4-80e78-4dfc85"}, {"t": "pt", "text": "Sales returns: Dr Sales returns, Cr Receivables", "id": "acffa2-rv4-80e78-2ed5c6"}, {"t": "pt", "text": "Purchase returns: Dr Payables, Cr Purchases returns", "id": "acffa2-rv4-80e78-a89841"}, {"t": "pt", "text": "Imprest petty cash topped up to the float", "id": "acffa2-rv4-80e78-e10cc7"}, {"t": "pt", "text": "Output tax on sales = liability", "id": "acffa2-rv4-80e78-1d258f"}, {"t": "pt", "text": "Input tax on purchases = recoverable", "id": "acffa2-rv4-80e78-042edc"}, {"t": "pt", "text": "Tax in gross price = gross x rate / (100 + rate)", "id": "acffa2-rv4-80e78-d54613"}, {"t": "pt", "text": "Sales and purchases recorded net of sales tax", "id": "acffa2-rv4-80e78-ee74b2"}, {"t": "pt", "text": "Trade discount: deducted at sale, no entry", "id": "acffa2-rv4-80e78-75d91a"}, {"t": "pt", "text": "Settlement discount expected: revenue net", "id": "acffa2-rv4-80e78-da6786"}, {"t": "pt", "text": "Discount received = income of the purchaser", "id": "acffa2-rv4-80e78-ae99d7"}], "id": "acffa2-rv4-80e78"}], "source": "Kaplan FA Study Text ch 4: sections 1-7 pp70-89; chapter summary p90", "summary": "Recording cash and credit transactions, bank and petty cash, sales and purchase returns, sales tax (input and output), and trade and settlement discounts.", "id": "acffa2-rv4", "updated": "2026-11-12"}, {"num": "5", "title": "Inventory", "pages": [97, 124], "syllabus": "D1", "status": "published", "branches": [{"kind": "formula", "title": "Inventory and cost of sales", "page": [98, 103], "items": [{"t": "pt", "k": 1, "text": "Carrying forward unused inventory applies the MATCHING (accruals) concept - cost of goods is matched with the revenue they generate", "id": "acffa2-rv5-a6faf-9b4c8a"}, {"t": "f", "k": 1, "term": "Cost of sales", "text": "Opening inventory + Purchases - Closing inventory", "vars": "closing inventory = asset carried forward", "id": "acffa2-rv5-a6faf-748255"}, {"t": "f", "term": "Gross profit", "text": "Sales revenue - Cost of sales", "id": "acffa2-rv5-a6faf-56e1f2"}, {"t": "pt", "k": 1, "text": "Year-end entries: (1) Dr Cost of sales, Cr Inventory (opening inventory transferred); (2) Dr Inventory, Cr Cost of sales (closing inventory recognised)", "id": "acffa2-rv5-a6faf-034a65"}, {"t": "pt", "text": "Closing inventory appears in the SOFP as a current asset and reduces cost of sales", "id": "acffa2-rv5-a6faf-d6138c"}], "id": "acffa2-rv5-a6faf"}, {"kind": "rule", "title": "IAS 2 Inventories", "page": [103, 107], "items": [{"t": "pt", "k": 1, "text": "Inventory is measured at the LOWER of cost and net realisable value (NRV)", "id": "acffa2-rv5-c419f-f2e7c1"}, {"t": "pt", "k": 1, "text": "Cost = all costs of purchase, costs of conversion and other costs incurred in bringing the inventories to their present location and condition (IAS 2 para 10)", "kids": [{"t": "pt", "text": "Purchase: price, import duties, transport and handling, less trade discounts", "id": "acffa2-rv5-c419f-137024"}, {"t": "pt", "text": "Conversion: direct labour and production overheads (based on normal capacity)", "id": "acffa2-rv5-c419f-5f4206"}], "id": "acffa2-rv5-c419f-f21781"}, {"t": "x", "text": "Exclude from cost: abnormal waste, storage (unless necessary in production), administrative overheads, selling costs", "id": "acffa2-rv5-c419f-c09b7a"}, {"t": "def", "k": 1, "term": "Net realisable value", "text": "Estimated selling price in the ordinary course of business less estimated costs of completion and costs necessary to make the sale (also referred to as 'fair value less further costs to sell')", "id": "acffa2-rv5-c419f-d5da5e"}, {"t": "pt", "k": 1, "text": "The comparison of cost and NRV is made ITEM BY ITEM (or for groups of similar items), not on total inventory", "id": "acffa2-rv5-c419f-f6238d"}, {"t": "pt", "text": "Disclosure: accounting policies (including cost formula), carrying amounts by classification, amount expensed, write-downs", "id": "acffa2-rv5-c419f-bc06cd"}], "id": "acffa2-rv5-c419f"}, {"kind": "compare", "title": "Cost formulas", "page": [107, 113], "items": [{"t": "table", "rows": [["Method", "Assumption", "Closing inventory in rising prices"], ["FIFO", "Oldest items sold first", "Highest - recent prices"], ["Periodic weighted average (AVCO)", "One average cost for the period: (opening + purchases) / units", "Between"], ["Continuous weighted average (AVCO)", "New average cost after each purchase", "Between"]], "id": "acffa2-rv5-4c600-91a20b"}, {"t": "pt", "k": 1, "text": "Different methods give different closing inventory and therefore different profit", "id": "acffa2-rv5-4c600-295ff7"}, {"t": "x", "text": "LIFO is NOT permitted under IAS 2", "id": "acffa2-rv5-4c600-ce4de4"}, {"t": "pt", "text": "Periodic (period-end) records: count inventory at the year end; continuous (perpetual) records: update after each movement", "id": "acffa2-rv5-4c600-211769"}, {"t": "exam", "text": "Expect FIFO/AVCO closing inventory and gross profit calculations in MCQs", "id": "acffa2-rv5-4c600-a97361"}], "id": "acffa2-rv5-4c600"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Comparing total cost with total NRV instead of item by item", "id": "acffa2-rv5-6483a-5dccad"}, {"t": "x", "text": "Including selling or storage costs in inventory cost", "id": "acffa2-rv5-6483a-d00888"}, {"t": "x", "text": "Recording closing inventory as Dr Cost of sales - it is Dr Inventory, Cr Cost of sales", "id": "acffa2-rv5-6483a-b34608"}, {"t": "x", "text": "Using LIFO - not allowed under IAS 2", "id": "acffa2-rv5-6483a-5ce2ee"}], "id": "acffa2-rv5-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Inventory carried forward = matching concept", "id": "acffa2-rv5-80e78-bf7c9a"}, {"t": "pt", "text": "Cost of sales = opening + purchases - closing", "id": "acffa2-rv5-80e78-ef65f4"}, {"t": "pt", "text": "Closing inventory: Dr Inventory, Cr Cost of sales", "id": "acffa2-rv5-80e78-e7f177"}, {"t": "pt", "text": "IAS 2: lower of cost and NRV", "id": "acffa2-rv5-80e78-53dcf9"}, {"t": "pt", "text": "Cost = purchase + conversion + bringing to location and condition", "id": "acffa2-rv5-80e78-c6985a"}, {"t": "pt", "text": "NRV = selling price - costs to complete and sell", "id": "acffa2-rv5-80e78-1a592c"}, {"t": "pt", "text": "Compare item by item", "id": "acffa2-rv5-80e78-f22e61"}, {"t": "pt", "text": "Exclude abnormal waste, storage, admin, selling costs", "id": "acffa2-rv5-80e78-9adee6"}, {"t": "pt", "text": "FIFO: oldest sold first", "id": "acffa2-rv5-80e78-02f1fe"}, {"t": "pt", "text": "Periodic AVCO: one average for the period", "id": "acffa2-rv5-80e78-c7c359"}, {"t": "pt", "text": "Continuous AVCO: average after each purchase", "id": "acffa2-rv5-80e78-5b1a8c"}, {"t": "pt", "text": "LIFO not permitted", "id": "acffa2-rv5-80e78-3e7609"}, {"t": "pt", "text": "Rising prices: FIFO gives the highest profit", "id": "acffa2-rv5-80e78-8096d4"}], "id": "acffa2-rv5-80e78"}], "source": "Kaplan FA Study Text ch 5: sections 1-5 pp98-113; chapter summary p115", "summary": "Inventory in the financial statements and the matching concept, year-end inventory adjustments, IAS 2 valuation at the lower of cost and NRV, and FIFO, periodic and continuous weighted average cost.", "id": "acffa2-rv5", "updated": "2026-11-12"}, {"num": "6", "title": "Non-current Assets: Acquisition and Depreciation", "pages": [125, 144], "syllabus": "D2", "status": "published", "branches": [{"kind": "concept", "title": "Non-current assets and capitalisation", "page": [126, 129], "items": [{"t": "pt", "k": 1, "text": "Non-current assets: held for continuing use in the business (not for resale), expected to be used for more than one period", "id": "acffa2-rv6-55c9b-81f62e"}, {"t": "pt", "k": 1, "text": "Capital expenditure is capitalised (SOFP); revenue expenditure is expensed (P/L)", "id": "acffa2-rv6-55c9b-cecf0a"}, {"t": "pt", "text": "Non-current asset register: cost, date of purchase, description, serial number, location, depreciation method and rate, carrying amount - a control over physical assets", "id": "acffa2-rv6-55c9b-2f31d0"}, {"t": "pt", "k": 1, "text": "Capitalise: purchase price (less trade discounts) + import duties + costs directly attributable to bringing the asset to working condition (delivery, installation, site preparation, professional fees, testing)", "id": "acffa2-rv6-55c9b-8882c0"}, {"t": "x", "text": "Do NOT capitalise: maintenance contracts, repairs, training, general admin, abnormal costs", "id": "acffa2-rv6-55c9b-e7fa08"}, {"t": "pt", "k": 1, "text": "Subsequent expenditure is capitalised only if it improves the asset or extends its life beyond the original standard; repairs and maintenance are expensed", "id": "acffa2-rv6-55c9b-2ca7be"}], "id": "acffa2-rv6-55c9b"}, {"kind": "formula", "title": "Depreciation (IAS 16)", "page": [129, 133], "items": [{"t": "def", "k": 1, "term": "Depreciation", "text": "The systematic allocation of the depreciable amount of an asset over its useful life (IAS 16 para 6)", "id": "acffa2-rv6-8f6fd-9f4007"}, {"t": "def", "term": "Depreciable amount", "text": "Cost (or revalued amount) less residual value", "id": "acffa2-rv6-8f6fd-3224a7"}, {"t": "pt", "text": "Depreciation arises from use, wear and tear, passage of time, obsolescence", "id": "acffa2-rv6-8f6fd-8ffe44"}, {"t": "pt", "text": "Method should reflect the pattern in which the asset's benefits are expected to be consumed (IAS 16 para 60)", "id": "acffa2-rv6-8f6fd-e36206"}, {"t": "f", "k": 1, "term": "Straight-line", "text": "(Cost - Residual value) / Useful life", "vars": "or a % of cost", "eg": "Cost $10,000, residual $2,000, 4 years: $2,000 a year", "id": "acffa2-rv6-8f6fd-131eb2"}, {"t": "f", "k": 1, "term": "Reducing balance", "text": "X% x Carrying amount", "vars": "carrying amount = cost - accumulated depreciation", "eg": "20% on $1,000: $200, then $160, then $128", "id": "acffa2-rv6-8f6fd-7e837c"}, {"t": "pt", "text": "Land is usually not depreciated (unlimited life); buildings are", "id": "acffa2-rv6-8f6fd-ef7280"}, {"t": "pt", "text": "Pro rata depreciation for part-year use when the policy says so (eg months owned / 12)", "id": "acffa2-rv6-8f6fd-55b6fa"}, {"t": "exam", "text": "MCQs often test which costs can be capitalised and the year's total depreciation charge after part-year additions - read the policy (full year vs pro rata) carefully", "id": "acffa2-rv6-8f6fd-e83dc9"}], "id": "acffa2-rv6-8f6fd"}, {"kind": "process", "title": "Accounting for depreciation", "page": [134, 136], "items": [{"t": "pt", "k": 1, "text": "Annual charge: Dr Depreciation expense (P/L), Cr Accumulated depreciation (SOFP)", "id": "acffa2-rv6-15ad9-387aa6"}, {"t": "pt", "text": "Cost is kept in the asset cost account; accumulated depreciation in a separate account", "id": "acffa2-rv6-15ad9-469649"}, {"t": "f", "k": 1, "term": "Carrying amount", "text": "Cost - Accumulated depreciation", "vars": "shown in the SOFP", "eg": "Van cost $22,000, accumulated $1,375 -> $20,625", "id": "acffa2-rv6-15ad9-a388a5"}], "id": "acffa2-rv6-15ad9"}, {"kind": "rule", "title": "Changing estimates", "page": [137, 138], "items": [{"t": "pt", "k": 1, "text": "Useful life, residual value and depreciation method are reviewed at least annually", "id": "acffa2-rv6-f1b1d-85592a"}, {"t": "pt", "k": 1, "text": "A change is a change in ACCOUNTING ESTIMATE - applied prospectively: depreciate the CURRENT carrying amount over the REMAINING useful life (no restatement of prior years)", "id": "acffa2-rv6-f1b1d-f443b0"}, {"t": "f", "term": "Revised depreciation", "text": "(Carrying amount at date of change - Residual value) / Remaining useful life", "id": "acffa2-rv6-f1b1d-173df2"}], "id": "acffa2-rv6-f1b1d"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Capitalising repairs or annual maintenance", "id": "acffa2-rv6-6483a-5f9eb0"}, {"t": "x", "text": "Applying the reducing balance % to cost instead of carrying amount", "id": "acffa2-rv6-6483a-7736ad"}, {"t": "x", "text": "Restating past depreciation when the useful life changes - apply prospectively", "id": "acffa2-rv6-6483a-1ac484"}, {"t": "x", "text": "Depreciating land", "id": "acffa2-rv6-6483a-165f33"}], "id": "acffa2-rv6-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Non-current assets: long-term use, not resale", "id": "acffa2-rv6-80e78-adf3dc"}, {"t": "pt", "text": "Capitalise cost to bring to working condition", "id": "acffa2-rv6-80e78-7162eb"}, {"t": "pt", "text": "Expense repairs, maintenance and training", "id": "acffa2-rv6-80e78-9a2bf0"}, {"t": "pt", "text": "Asset register = control and record", "id": "acffa2-rv6-80e78-ae3b03"}, {"t": "pt", "text": "Depreciation = systematic allocation of depreciable amount", "id": "acffa2-rv6-80e78-a12106"}, {"t": "pt", "text": "Depreciable amount = cost - residual value", "id": "acffa2-rv6-80e78-7e2b8e"}, {"t": "pt", "text": "Straight-line = (cost - residual) / life", "id": "acffa2-rv6-80e78-931ef5"}, {"t": "pt", "text": "Reducing balance = % x carrying amount", "id": "acffa2-rv6-80e78-44744e"}, {"t": "pt", "text": "Dr Depreciation expense, Cr Accumulated depreciation", "id": "acffa2-rv6-80e78-240d14"}, {"t": "pt", "text": "Carrying amount = cost - accumulated depreciation", "id": "acffa2-rv6-80e78-853b25"}, {"t": "pt", "text": "Review estimates annually", "id": "acffa2-rv6-80e78-b1d8d0"}, {"t": "pt", "text": "Change in estimate: prospective, remaining life", "id": "acffa2-rv6-80e78-073692"}, {"t": "pt", "text": "Land not depreciated", "id": "acffa2-rv6-80e78-f7e969"}], "id": "acffa2-rv6-80e78"}], "source": "Kaplan FA Study Text ch 6: sections 1-9 pp126-138; chapter summary p139", "summary": "What a non-current asset is, capital vs revenue expenditure, the asset register, capitalising cost and subsequent expenditure, IAS 16 depreciation, straight-line and reducing balance methods, ledger entries and changes in estimates.", "id": "acffa2-rv6", "updated": "2026-11-12"}, {"num": "7", "title": "Non-current Assets: Disposal and Revaluation", "pages": [145, 162], "syllabus": "D2", "status": "published", "branches": [{"kind": "process", "title": "Disposals", "page": [146, 148], "items": [{"t": "pt", "k": 1, "text": "An asset is derecognised on disposal or when no future benefits are expected from it (IAS 16 para 67)", "id": "acffa2-rv7-7d86f-567448"}, {"t": "f", "k": 1, "term": "Profit or loss on disposal", "text": "Disposal proceeds - Carrying amount at the disposal date", "vars": "proceeds > CA = profit; proceeds < CA = loss", "eg": "Proceeds $3,000, CA $2,500 = $500 profit", "id": "acffa2-rv7-7d86f-4f8c81"}, {"t": "pt", "k": 1, "text": "Three steps using a disposal account", "kids": [{"t": "pt", "text": "Remove cost: Dr Disposal, Cr Asset cost", "id": "acffa2-rv7-7d86f-e40b16"}, {"t": "pt", "text": "Remove accumulated depreciation: Dr Accumulated depreciation, Cr Disposal", "id": "acffa2-rv7-7d86f-097d90"}, {"t": "pt", "text": "Record proceeds: Dr Bank (or receivable), Cr Disposal", "id": "acffa2-rv7-7d86f-6f0b7e"}, {"t": "pt", "text": "Balancing figure = profit (Dr Disposal, Cr P/L) or loss (Dr P/L, Cr Disposal)", "id": "acffa2-rv7-7d86f-09330b"}], "id": "acffa2-rv7-7d86f-2dc3a8"}, {"t": "pt", "k": 1, "text": "Part-exchange: the part-exchange allowance is the disposal proceeds of the old asset: Dr New asset cost, Cr Disposal (allowance); the new asset's cost = allowance + cash paid", "id": "acffa2-rv7-7d86f-44a4fa"}, {"t": "exam", "text": "Charge depreciation up to the disposal date if the policy requires a pro rata charge", "id": "acffa2-rv7-7d86f-4301dc"}], "id": "acffa2-rv7-7d86f"}, {"kind": "rule", "title": "Revaluation (IAS 16)", "page": [149, 152], "items": [{"t": "pt", "k": 1, "text": "Entities may choose the revaluation model for a whole CLASS of assets; revaluations must then be kept up to date", "id": "acffa2-rv7-4475e-a68bd6"}, {"t": "f", "k": 1, "term": "Revaluation surplus", "text": "Revalued amount - Carrying amount", "vars": "credited to other comprehensive income and accumulated in equity (revaluation surplus)", "eg": "Land $200,000 revalued to $300,000 -> surplus $100,000", "id": "acffa2-rv7-4475e-7058e7"}, {"t": "pt", "k": 1, "text": "Depreciated asset: Dr Asset (to bring cost up to the valuation, or as needed), Dr Accumulated depreciation (remove it), Cr Revaluation surplus", "id": "acffa2-rv7-4475e-059fe5"}, {"t": "eg", "text": "Building cost $300,000, accumulated depreciation $100,000, revalued $750,000: Dr Asset $450,000, Dr Accumulated depreciation $100,000, Cr Revaluation surplus $550,000", "id": "acffa2-rv7-4475e-873ea0"}, {"t": "pt", "k": 1, "text": "The gain is shown as OTHER COMPREHENSIVE INCOME - an item that will not be reclassified to profit or loss", "id": "acffa2-rv7-4475e-a7af15"}], "id": "acffa2-rv7-4475e"}, {"kind": "process", "title": "Depreciation and disposal after revaluation", "page": [152, 154], "items": [{"t": "pt", "k": 1, "text": "After revaluation, depreciation is based on the REVALUED amount over the remaining useful life", "id": "acffa2-rv7-e5062-0efd63"}, {"t": "pt", "k": 1, "text": "Excess depreciation transfer (optional): each year Dr Revaluation surplus, Cr Retained earnings with (depreciation on revalued amount - depreciation on historical cost) - a movement in equity, not through P/L", "id": "acffa2-rv7-e5062-ea578f"}, {"t": "pt", "k": 1, "text": "Disposal of a revalued asset: gain or loss = proceeds - carrying amount (revalued); the remaining revaluation surplus is transferred DIRECTLY to retained earnings (IAS 16 para 41) - not recycled through profit or loss", "id": "acffa2-rv7-e5062-a33579"}], "id": "acffa2-rv7-e5062"}, {"kind": "concept", "title": "IAS 16 disclosures", "page": [155, 155], "items": [{"t": "pt", "text": "For each class: measurement basis, depreciation methods, useful lives or rates", "id": "acffa2-rv7-3affc-965e62"}, {"t": "pt", "text": "Reconciliation of carrying amounts: opening and closing cost/valuation and accumulated depreciation, additions, disposals, revaluations, depreciation", "id": "acffa2-rv7-3affc-d18983"}, {"t": "pt", "text": "Revalued assets: date of revaluation, whether an independent valuer was used, carrying amount under the cost model", "id": "acffa2-rv7-3affc-61d188"}], "id": "acffa2-rv7-3affc"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calculating profit on disposal using cost instead of carrying amount", "id": "acffa2-rv7-6483a-038980"}, {"t": "x", "text": "Crediting a revaluation gain to profit or loss - it goes to OCI and the revaluation surplus", "id": "acffa2-rv7-6483a-512428"}, {"t": "x", "text": "Revaluing a single asset in a class - the whole class must be revalued", "id": "acffa2-rv7-6483a-d7d32f"}, {"t": "x", "text": "Transferring the revaluation surplus on disposal through profit or loss - transfer it to retained earnings", "id": "acffa2-rv7-6483a-9236e3"}], "id": "acffa2-rv7-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Profit on disposal = proceeds - carrying amount", "id": "acffa2-rv7-80e78-c6c1ef"}, {"t": "pt", "text": "Disposal account: cost in, accumulated depreciation out, proceeds out", "id": "acffa2-rv7-80e78-fe55d6"}, {"t": "pt", "text": "Part-exchange allowance = disposal proceeds", "id": "acffa2-rv7-80e78-3d5686"}, {"t": "pt", "text": "New asset cost = allowance + cash paid", "id": "acffa2-rv7-80e78-be2a70"}, {"t": "pt", "text": "Revaluation: whole class, kept up to date", "id": "acffa2-rv7-80e78-d9458c"}, {"t": "pt", "text": "Revaluation surplus = revalued amount - carrying amount", "id": "acffa2-rv7-80e78-de9eb3"}, {"t": "pt", "text": "Gain to OCI and revaluation surplus (equity)", "id": "acffa2-rv7-80e78-233883"}, {"t": "pt", "text": "Remove accumulated depreciation on revaluation", "id": "acffa2-rv7-80e78-7429f8"}, {"t": "pt", "text": "Depreciate revalued amount over remaining life", "id": "acffa2-rv7-80e78-6d5a8b"}, {"t": "pt", "text": "Excess depreciation: surplus to retained earnings", "id": "acffa2-rv7-80e78-35bb4a"}, {"t": "pt", "text": "On disposal: surplus to retained earnings, not P/L", "id": "acffa2-rv7-80e78-a58161"}, {"t": "pt", "text": "Disclose reconciliation of carrying amounts", "id": "acffa2-rv7-80e78-c3909d"}], "id": "acffa2-rv7-80e78"}], "source": "Kaplan FA Study Text ch 7: sections 1-5 pp146-155; chapter summary p157", "summary": "Disposals for cash and by part-exchange, profit or loss on disposal, revaluation under IAS 16 and the revaluation surplus, depreciation and disposal of revalued assets, and IAS 16 disclosures.", "id": "acffa2-rv7", "updated": "2026-11-12"}, {"num": "8", "title": "Intangible Assets", "pages": [163, 174], "syllabus": "D3", "status": "published", "branches": [{"kind": "def", "title": "Definition and recognition", "page": [164, 165], "items": [{"t": "def", "k": 1, "term": "Intangible asset", "text": "An identifiable non-monetary asset without physical substance (IAS 38 para 8)", "id": "acffa2-rv8-f7a99-7c8888"}, {"t": "pt", "text": "Key characteristics: identifiable (separable or arising from legal/contractual rights), control by the entity, future economic benefits", "id": "acffa2-rv8-f7a99-9a3bc4"}, {"t": "pt", "k": 1, "text": "Recognise only if future economic benefits are probable and cost can be measured reliably", "id": "acffa2-rv8-f7a99-e78474"}, {"t": "pt", "text": "Examples: patents, trademarks, licences, purchased brands, capitalised development costs", "id": "acffa2-rv8-f7a99-ec4571"}, {"t": "x", "text": "Internally generated goodwill, brands, mastheads and customer lists are NOT recognised as assets", "id": "acffa2-rv8-f7a99-ed6813"}], "id": "acffa2-rv8-f7a99"}, {"kind": "decision", "title": "Research vs development", "page": [166, 168], "items": [{"t": "def", "k": 1, "term": "Research", "text": "Original and planned investigation undertaken with the prospect of gaining new scientific or technical knowledge and understanding (IAS 38 para 8)", "id": "acffa2-rv8-302db-f04f19"}, {"t": "def", "k": 1, "term": "Development", "text": "Application of research findings or other knowledge to a plan or design for new or substantially improved products or processes before commercial production or use", "id": "acffa2-rv8-302db-d246af"}, {"t": "pt", "k": 1, "text": "Research expenditure: ALWAYS expensed to profit or loss as incurred", "id": "acffa2-rv8-302db-75e7ca"}, {"t": "dq", "text": "Do ALL capitalisation criteria (PIRATE) apply to the development spend?", "yes": "Capitalise as an intangible asset - MUST capitalise", "no": "Expense to profit or loss as incurred", "id": "acffa2-rv8-302db-ee527d"}, {"t": "pt", "k": 1, "text": "PIRATE criteria: Probable future economic benefits • Intention to complete and use or sell • Resources available to complete • Ability to use or sell • Technically feasible • Expenditure can be measured reliably", "id": "acffa2-rv8-302db-709165"}, {"t": "x", "text": "Development costs expensed in earlier periods cannot be reinstated later", "id": "acffa2-rv8-302db-0a3b74"}, {"t": "exam", "text": "MCQs give a mix of research and development costs and ask for the amount capitalised or expensed - expense everything until ALL criteria are first met", "id": "acffa2-rv8-302db-2c77b2"}], "id": "acffa2-rv8-302db"}, {"kind": "formula", "title": "Amortisation and subsequent measurement", "page": [167, 171], "items": [{"t": "pt", "k": 1, "text": "Capitalised development costs are amortised from when the product/process is available for use (commercial production begins), over its expected useful life", "id": "acffa2-rv8-5db3c-22f982"}, {"t": "f", "term": "Straight-line amortisation", "text": "(Cost - Residual value) / Useful life", "vars": "residual value usually nil", "eg": "$600,000 over 4 years = $150,000 a year", "id": "acffa2-rv8-5db3c-90ed3a"}, {"t": "pt", "text": "Amortisation: Dr Amortisation expense (P/L), Cr Accumulated amortisation; intangibles with an indefinite life are not amortised but tested for impairment", "id": "acffa2-rv8-5db3c-9bffe6"}, {"t": "pt", "k": 1, "text": "Subsequent measurement: cost model (cost less accumulated amortisation and impairment) OR revaluation model", "id": "acffa2-rv8-5db3c-f5a11c"}, {"t": "pt", "k": 1, "text": "Revaluation model requires fair value measured by reference to an ACTIVE MARKET - rare for intangibles (eg not possible for patents or brands)", "id": "acffa2-rv8-5db3c-fa621d"}, {"t": "pt", "text": "Disclosure: useful lives/rates, methods, reconciliation of carrying amounts, R&D expensed in the period", "id": "acffa2-rv8-5db3c-a064c4"}], "id": "acffa2-rv8-5db3c"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Capitalising research costs", "id": "acffa2-rv8-6483a-773c89"}, {"t": "x", "text": "Treating capitalisation of qualifying development costs as optional - it is required", "id": "acffa2-rv8-6483a-989a20"}, {"t": "x", "text": "Starting amortisation when development spend is incurred - it starts when commercial production/use begins", "id": "acffa2-rv8-6483a-737e80"}, {"t": "x", "text": "Recognising internally generated goodwill or brands", "id": "acffa2-rv8-6483a-3a51a6"}], "id": "acffa2-rv8-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Intangible = identifiable, non-monetary, no physical substance", "id": "acffa2-rv8-80e78-239306"}, {"t": "pt", "text": "Research: always expense", "id": "acffa2-rv8-80e78-430859"}, {"t": "pt", "text": "Development: capitalise if ALL PIRATE criteria met", "id": "acffa2-rv8-80e78-d6ff79"}, {"t": "pt", "text": "PIRATE: probable benefits, intention, resources, ability, technical feasibility, expenditure measurable", "id": "acffa2-rv8-80e78-69ce52"}, {"t": "pt", "text": "Capitalisation is compulsory if criteria met", "id": "acffa2-rv8-80e78-d61d99"}, {"t": "pt", "text": "Amortise from commercial production over useful life", "id": "acffa2-rv8-80e78-b0929a"}, {"t": "pt", "text": "Cost model or revaluation model", "id": "acffa2-rv8-80e78-02fbbb"}, {"t": "pt", "text": "Revaluation needs an active market (rare)", "id": "acffa2-rv8-80e78-bac700"}, {"t": "pt", "text": "Internally generated goodwill and brands not recognised", "id": "acffa2-rv8-80e78-b33db6"}, {"t": "pt", "text": "Previously expensed costs cannot be reinstated", "id": "acffa2-rv8-80e78-f26f17"}, {"t": "pt", "text": "Disclose R&D expensed in the period", "id": "acffa2-rv8-80e78-c0b837"}, {"t": "pt", "text": "Indefinite-life intangibles: impairment test, no amortisation", "id": "acffa2-rv8-80e78-e90006"}], "id": "acffa2-rv8-80e78"}], "source": "Kaplan FA Study Text ch 8: sections 1-5 pp164-171; chapter summary p172", "summary": "IAS 38: definition and recognition of intangible assets, research vs development expenditure and the capitalisation criteria, amortisation, subsequent measurement (cost vs revaluation model) and disclosure.", "id": "acffa2-rv8", "updated": "2026-11-12"}, {"num": "9", "title": "Accruals and Prepayments", "pages": [175, 190], "syllabus": "D4", "status": "published", "branches": [{"kind": "concept", "title": "The accruals concept", "page": [176, 177], "items": [{"t": "pt", "k": 1, "text": "Accrual accounting depicts the effects of transactions in the periods in which they occur, even if cash is received or paid in a different period (Conceptual Framework)", "id": "acffa2-rv9-fc7ac-9f3fb4"}, {"t": "pt", "text": "Sales revenue recognised when the sale is made; cost of sales matched with those sales", "id": "acffa2-rv9-fc7ac-cbc637"}, {"t": "pt", "text": "Year-end adjustments make expenses and income reflect the period, not the cash flows", "id": "acffa2-rv9-fc7ac-b0958d"}], "id": "acffa2-rv9-fc7ac"}, {"kind": "compare", "title": "Accruals and prepayments", "page": [177, 185], "items": [{"t": "table", "rows": [["Item", "Meaning", "SOFP", "Effect on profit"], ["Accrued expense", "Expense incurred but not yet paid", "Current LIABILITY", "Increases the expense - reduces profit"], ["Prepaid expense", "Paid in advance for a future period", "Current ASSET", "Reduces the expense - increases profit"], ["Accrued income", "Income earned but not yet received", "Current ASSET", "Increases income"], ["Prepaid (deferred) income", "Received in advance of being earned", "Current LIABILITY", "Reduces income"]], "id": "acffa2-rv9-9a741-2d6b59"}, {"t": "pt", "k": 1, "text": "Accrued expense: Dr Expense, Cr Accruals; prepaid expense: Dr Prepayments, Cr Expense", "id": "acffa2-rv9-9a741-8db6e8"}, {"t": "pt", "k": 1, "text": "Accrued income: Dr Accrued income, Cr Income; prepaid income: Dr Income, Cr Deferred income", "id": "acffa2-rv9-9a741-e5f101"}, {"t": "eg", "text": "Fuel paid $9,000, $3,000 owing at year end: P/L charge $12,000, accrual $3,000", "id": "acffa2-rv9-9a741-4d5089"}, {"t": "eg", "text": "Insurance paid $30,000 of which $6,000 relates to next year: P/L $24,000, prepayment $6,000", "id": "acffa2-rv9-9a741-71b4ec"}, {"t": "eg", "text": "Rent received $64,000 of which $16,000 is for next year: rental income $48,000, prepaid income liability $16,000", "id": "acffa2-rv9-9a741-6fbee2"}], "id": "acffa2-rv9-9a741"}, {"kind": "formula", "title": "Proforma T-accounts", "page": [181, 186], "items": [{"t": "f", "k": 1, "term": "Expense charge", "text": "Cash paid - Opening accrual + Closing accrual + Opening prepayment - Closing prepayment", "vars": "the expense account balancing figure = P/L charge", "id": "acffa2-rv9-1e90c-f61fa7"}, {"t": "f", "term": "Income credit", "text": "Cash received - Opening accrued income + Closing accrued income + Opening prepaid income - Closing prepaid income", "vars": "balancing figure in the income account", "id": "acffa2-rv9-1e90c-f963f1"}, {"t": "pt", "text": "Opening balances reverse: an opening accrual is a credit b/f in the expense account; an opening prepayment is a debit b/f", "id": "acffa2-rv9-1e90c-fccc95"}, {"t": "pt", "text": "Presentation: prepayments and accrued income within trade and other receivables; accruals and deferred income within trade and other payables", "id": "acffa2-rv9-1e90c-e40cfd"}, {"t": "exam", "text": "Time-apportion carefully: count the months that fall in the current accounting period", "id": "acffa2-rv9-1e90c-2c864a"}], "id": "acffa2-rv9-1e90c"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Showing an accrual as an asset - an accrued expense is a liability", "id": "acffa2-rv9-6483a-719e4f"}, {"t": "x", "text": "Adding a prepayment to the expense - it reduces the expense", "id": "acffa2-rv9-6483a-748090"}, {"t": "x", "text": "Ignoring opening accruals/prepayments brought forward in the T-account", "id": "acffa2-rv9-6483a-44b114"}, {"t": "x", "text": "Confusing accrued income (asset) with prepaid income (liability)", "id": "acffa2-rv9-6483a-4f6734"}], "id": "acffa2-rv9-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Accruals concept: match to the period, not the cash", "id": "acffa2-rv9-80e78-be0fc5"}, {"t": "pt", "text": "Accrued expense: incurred, unpaid -> liability, increase expense", "id": "acffa2-rv9-80e78-8e93be"}, {"t": "pt", "text": "Prepaid expense: paid in advance -> asset, reduce expense", "id": "acffa2-rv9-80e78-949577"}, {"t": "pt", "text": "Accrued income: earned, unreceived -> asset, increase income", "id": "acffa2-rv9-80e78-06bec6"}, {"t": "pt", "text": "Prepaid income: received in advance -> liability, reduce income", "id": "acffa2-rv9-80e78-03db3e"}, {"t": "pt", "text": "Accrual: Dr Expense, Cr Accruals", "id": "acffa2-rv9-80e78-2a1f3a"}, {"t": "pt", "text": "Prepayment: Dr Prepayments, Cr Expense", "id": "acffa2-rv9-80e78-ebb2ea"}, {"t": "pt", "text": "P/L charge = balancing figure in the T-account", "id": "acffa2-rv9-80e78-770d63"}, {"t": "pt", "text": "Opening accrual = credit b/f", "id": "acffa2-rv9-80e78-04de92"}, {"t": "pt", "text": "Opening prepayment = debit b/f", "id": "acffa2-rv9-80e78-e14e2d"}, {"t": "pt", "text": "Time-apportion by months in the period", "id": "acffa2-rv9-80e78-2ffb36"}, {"t": "pt", "text": "Receivables include prepayments; payables include accruals", "id": "acffa2-rv9-80e78-f8470b"}], "id": "acffa2-rv9-80e78"}], "source": "Kaplan FA Study Text ch 9: sections 1-7 pp176-186; chapter summary p187", "summary": "The accruals concept, accrued and prepaid expenses, accrued and prepaid income, the proforma T-accounts and SOFP presentation.", "id": "acffa2-rv9", "updated": "2026-11-12"}, {"num": "10", "title": "Receivables", "pages": [191, 208], "syllabus": "D5", "status": "published", "branches": [{"kind": "concept", "title": "Trade receivables and credit", "page": [192, 195], "items": [{"t": "pt", "text": "Trade receivables account: Dr balance b/f, credit sales, dishonoured cheques; Cr receipts, sales returns, irrecoverable debts written off, contras", "id": "acffa2-rv10-07265-def1f8"}, {"t": "pt", "text": "Benefits of offering credit: enter new markets, increase sales, compete; costs: delayed cash, financing cost, risk of non-payment, admin", "id": "acffa2-rv10-07265-a37693"}, {"t": "pt", "k": 1, "text": "Aged receivables analysis lists balances by how long they have been outstanding - used for credit control and for the allowance", "id": "acffa2-rv10-07265-35f859"}], "id": "acffa2-rv10-07265"}, {"kind": "process", "title": "Irrecoverable debts", "page": [195, 198], "items": [{"t": "def", "k": 1, "term": "Irrecoverable debt", "text": "A debt that is definitely not going to be received (eg customer bankrupt) - written off", "id": "acffa2-rv10-0030f-af5e1f"}, {"t": "pt", "k": 1, "text": "Write-off: Dr Irrecoverable debts expense, Cr Trade receivables", "id": "acffa2-rv10-0030f-e61975"}, {"t": "pt", "k": 1, "text": "Recovery of a debt previously written off: Dr Cash at bank, Cr Irrecoverable debts expense (or a recoveries income account) - the receivable is not reinstated", "id": "acffa2-rv10-0030f-fd09ec"}, {"t": "pt", "text": "Sales tax adjustments on write-offs are outside the FA syllabus unless stated", "id": "acffa2-rv10-0030f-130527"}], "id": "acffa2-rv10-0030f"}, {"kind": "formula", "title": "Allowance for receivables", "page": [198, 202], "items": [{"t": "def", "k": 1, "term": "Allowance for receivables", "text": "An estimate of the amount of receivables that may not be collected (expected credit losses) - a contra asset deducted from receivables", "id": "acffa2-rv10-cce1c-5fb645"}, {"t": "pt", "k": 1, "text": "Only the INCREASE or DECREASE in the allowance goes to profit or loss", "kids": [{"t": "pt", "text": "Increase: Dr Irrecoverable debts expense, Cr Allowance for receivables", "id": "acffa2-rv10-cce1c-787f52"}, {"t": "pt", "text": "Decrease: Dr Allowance for receivables, Cr Irrecoverable debts expense", "id": "acffa2-rv10-cce1c-56559e"}], "id": "acffa2-rv10-cce1c-ff2f80"}, {"t": "f", "term": "Required allowance", "text": "% x (Receivables after write-offs) or specific amounts identified", "vars": "always write off irrecoverable debts FIRST", "eg": "Receivables $10,000 after write-offs, 3% = $300", "id": "acffa2-rv10-cce1c-cc2b78"}, {"t": "f", "term": "Irrecoverable debts expense", "text": "Debts written off + Increase (or - decrease) in allowance - Recoveries", "id": "acffa2-rv10-cce1c-a5d9ed"}, {"t": "pt", "text": "SOFP: Trade receivables less allowance = carrying amount (eg 10,000 - 300 = 9,700)", "id": "acffa2-rv10-cce1c-16b6fb"}, {"t": "exam", "text": "Compare the required closing allowance with the opening allowance - the difference is the P/L charge or credit", "id": "acffa2-rv10-cce1c-baaa8a"}], "id": "acffa2-rv10-cce1c"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Charging the whole closing allowance to profit or loss instead of the movement", "id": "acffa2-rv10-6483a-4d510e"}, {"t": "x", "text": "Calculating the allowance before deducting irrecoverable debts written off", "id": "acffa2-rv10-6483a-35f569"}, {"t": "x", "text": "Reinstating the receivable when a written-off debt is recovered", "id": "acffa2-rv10-6483a-3cf1f0"}, {"t": "x", "text": "Crediting the allowance account when it decreases - a decrease is a debit to the allowance", "id": "acffa2-rv10-6483a-82334d"}], "id": "acffa2-rv10-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Aged analysis supports credit control", "id": "acffa2-rv10-80e78-3d2dca"}, {"t": "pt", "text": "Irrecoverable debt: definitely not recoverable", "id": "acffa2-rv10-80e78-956163"}, {"t": "pt", "text": "Write-off: Dr Irrecoverable debts expense, Cr Receivables", "id": "acffa2-rv10-80e78-b7502c"}, {"t": "pt", "text": "Recovery: Dr Cash, Cr Irrecoverable debts expense", "id": "acffa2-rv10-80e78-fe0e17"}, {"t": "pt", "text": "Allowance = estimate of debts not collected", "id": "acffa2-rv10-80e78-4b4650"}, {"t": "pt", "text": "Write off first, then calculate the allowance", "id": "acffa2-rv10-80e78-0fa136"}, {"t": "pt", "text": "Only the change in allowance goes to P/L", "id": "acffa2-rv10-80e78-d3f160"}, {"t": "pt", "text": "Increase: Dr expense, Cr allowance", "id": "acffa2-rv10-80e78-b366cd"}, {"t": "pt", "text": "Decrease: Dr allowance, Cr expense", "id": "acffa2-rv10-80e78-6f77ed"}, {"t": "pt", "text": "SOFP: receivables less allowance", "id": "acffa2-rv10-80e78-a8fdee"}, {"t": "pt", "text": "Expense = write-offs + allowance movement - recoveries", "id": "acffa2-rv10-80e78-a6d21b"}, {"t": "pt", "text": "Credit control balances sales growth against risk", "id": "acffa2-rv10-80e78-625690"}], "id": "acffa2-rv10-80e78"}], "source": "Kaplan FA Study Text ch 10: sections 1-8 pp192-202; chapter summary p203", "summary": "Trade receivables, credit facilities and aged receivables analysis, writing off irrecoverable debts, recoveries, and the allowance for receivables (expected credit losses).", "id": "acffa2-rv10", "updated": "2026-11-12"}, {"num": "11", "title": "Payables, Provisions and Contingent Liabilities", "pages": [209, 222], "syllabus": "D6", "status": "published", "branches": [{"kind": "concept", "title": "Trade payables", "page": [210, 212], "items": [{"t": "pt", "text": "Trade payables account: Dr cash paid, purchases returns, settlement discounts received, contras; Cr balance b/f, credit purchases", "id": "acffa2-rv11-eabf7-8a3973"}, {"t": "def", "k": 1, "term": "Liability", "text": "A present obligation of the entity to transfer an economic resource as a result of past events", "id": "acffa2-rv11-eabf7-1ee451"}], "id": "acffa2-rv11-eabf7"}, {"kind": "rule", "title": "Provisions (IAS 37)", "page": [213, 216], "items": [{"t": "def", "k": 1, "term": "Provision", "text": "A liability of uncertain timing or amount (IAS 37 para 10)", "id": "acffa2-rv11-e9f49-76e77c"}, {"t": "pt", "k": 1, "text": "Recognise a provision when ALL three apply (IAS 37 para 14)", "kids": [{"t": "pt", "text": "A present obligation (legal or constructive) as a result of a past event", "id": "acffa2-rv11-e9f49-f27e37"}, {"t": "pt", "text": "It is PROBABLE that an outflow of economic benefits will be required to settle it", "id": "acffa2-rv11-e9f49-4fb2d4"}, {"t": "pt", "text": "A reliable estimate can be made of the amount", "id": "acffa2-rv11-e9f49-38e03b"}], "id": "acffa2-rv11-e9f49-ec0271"}, {"t": "pt", "k": 1, "text": "Legal obligation: from a contract, legislation or other operation of law", "id": "acffa2-rv11-e9f49-9eb38f"}, {"t": "pt", "k": 1, "text": "Constructive obligation: from the entity's actions - an established pattern of past practice, published policies or a specific current statement that it will accept responsibilities, creating a valid expectation in others", "id": "acffa2-rv11-e9f49-8c1935"}, {"t": "pt", "text": "Recording: Dr Expense, Cr Provision (liability)", "id": "acffa2-rv11-e9f49-295e76"}, {"t": "pt", "k": 1, "text": "Movement in provisions: review at each reporting date; increase -> Dr Expense, Cr Provision; decrease -> Dr Provision, Cr Expense (only the movement goes to P/L)", "id": "acffa2-rv11-e9f49-ec980f"}, {"t": "eg", "text": "Warranty provision based on past experience of claims; legal claim where the lawyers think the entity will probably lose", "id": "acffa2-rv11-e9f49-afa990"}], "id": "acffa2-rv11-e9f49"}, {"kind": "decision", "title": "Contingencies", "page": [217, 219], "items": [{"t": "table", "rows": [["Probability of occurrence", "Contingent liability", "Contingent asset"], ["Virtually certain", "Not contingent - recognise a liability", "Not contingent - recognise the asset"], ["Probable", "Recognise a provision (disclose if no reliable estimate - very rare)", "Disclose in a note"], ["Possible", "Disclose in a note", "Ignore"], ["Remote", "Ignore", "Ignore"]], "id": "acffa2-rv11-ae310-f5cad9"}, {"t": "def", "k": 1, "term": "Contingent liability", "text": "A possible obligation arising from past events whose existence will be confirmed only by uncertain future events not wholly within the entity's control; OR a present obligation not recognised because an outflow is not probable or cannot be measured reliably", "id": "acffa2-rv11-ae310-5958d5"}, {"t": "def", "k": 1, "term": "Contingent asset", "text": "A possible asset arising from past events whose existence will be confirmed only by uncertain future events not wholly within the entity's control (eg a compensation claim being pursued)", "id": "acffa2-rv11-ae310-dfde5a"}, {"t": "exam", "text": "Contingent assets are NEVER recognised unless virtually certain; contingent liabilities are never recognised - they are disclosed (unless remote)", "id": "acffa2-rv11-ae310-d61053"}], "id": "acffa2-rv11-ae310"}, {"kind": "concept", "title": "Reporting provisions", "page": [220, 220], "items": [{"t": "pt", "text": "Provisions are reported as liabilities in the SOFP (current or non-current depending on timing)", "id": "acffa2-rv11-dc7c8-fae300"}, {"t": "pt", "text": "Notes disclose the nature, movement in the year and uncertainties", "id": "acffa2-rv11-dc7c8-e1f106"}, {"t": "pt", "text": "No provisions for future operating losses (no present obligation)", "id": "acffa2-rv11-dc7c8-12ed85"}], "id": "acffa2-rv11-dc7c8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Recognising a provision when the outflow is only possible - disclose a contingent liability instead", "id": "acffa2-rv11-6483a-1d143d"}, {"t": "x", "text": "Recognising a probable contingent asset - it is only disclosed", "id": "acffa2-rv11-6483a-d09351"}, {"t": "x", "text": "Charging the whole closing provision to P/L each year - only the movement", "id": "acffa2-rv11-6483a-5fdc86"}, {"t": "x", "text": "Forgetting constructive obligations (eg a published refund policy)", "id": "acffa2-rv11-6483a-2b5797"}], "id": "acffa2-rv11-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Provision = liability of uncertain timing or amount", "id": "acffa2-rv11-80e78-0e7ab4"}, {"t": "pt", "text": "Recognise: present obligation + probable outflow + reliable estimate", "id": "acffa2-rv11-80e78-fa9012"}, {"t": "pt", "text": "Obligations: legal or constructive", "id": "acffa2-rv11-80e78-1b20dc"}, {"t": "pt", "text": "Dr Expense, Cr Provision", "id": "acffa2-rv11-80e78-0c2b5a"}, {"t": "pt", "text": "Only the movement in a provision hits P/L", "id": "acffa2-rv11-80e78-b25ea9"}, {"t": "pt", "text": "Contingent liability: probable -> provision; possible -> disclose; remote -> ignore", "id": "acffa2-rv11-80e78-3f47d5"}, {"t": "pt", "text": "Contingent asset: virtually certain -> recognise; probable -> disclose; otherwise ignore", "id": "acffa2-rv11-80e78-730250"}, {"t": "pt", "text": "Contingent liabilities are disclosed, not recognised", "id": "acffa2-rv11-80e78-982a4c"}, {"t": "pt", "text": "No provisions for future operating losses", "id": "acffa2-rv11-80e78-5fa898"}, {"t": "pt", "text": "Review provisions at each reporting date", "id": "acffa2-rv11-80e78-d83648"}, {"t": "pt", "text": "Trade payables: Cr credit purchases, Dr payments and returns", "id": "acffa2-rv11-80e78-cfc723"}], "id": "acffa2-rv11-80e78"}], "source": "Kaplan FA Study Text ch 11: sections 1-6 pp210-220; chapter summary p221", "summary": "Trade payables, liabilities, IAS 37 provisions (recognition criteria, legal and constructive obligations, movements), contingent liabilities and contingent assets, and reporting.", "id": "acffa2-rv11", "updated": "2026-11-12"}, {"num": "12", "title": "Capital Structure and Finance Costs", "pages": [223, 242], "syllabus": "D7", "status": "published", "branches": [{"kind": "concept", "title": "Share capital terminology", "page": [224, 227], "items": [{"t": "pt", "k": 1, "text": "Nominal (par) value: an arbitrary value per share (eg $1, 50c) - not the market value", "id": "acffa2-rv12-d40dd-370c0b"}, {"t": "pt", "text": "Issued share capital: number and nominal value of shares issued; called-up and paid-up capital", "id": "acffa2-rv12-d40dd-a637a4"}, {"t": "pt", "text": "Ordinary (equity) shares: votes, variable dividends, residual interest; preference shares: fixed dividend, usually no votes", "id": "acffa2-rv12-d40dd-7b9232"}, {"t": "pt", "k": 1, "text": "Issue at a premium: Dr Bank (total proceeds), Cr Share capital (nominal value), Cr Share premium (excess over nominal)", "id": "acffa2-rv12-d40dd-b78460"}, {"t": "eg", "text": "100,000 $1 shares issued at $1.50: Dr Bank 150,000, Cr Share capital 100,000, Cr Share premium 50,000", "id": "acffa2-rv12-d40dd-b82ed4"}], "id": "acffa2-rv12-d40dd"}, {"kind": "compare", "title": "Rights issue vs bonus issue", "page": [227, 229], "items": [{"t": "table", "rows": [["Feature", "Rights issue", "Bonus issue"], ["Definition", "New shares offered to existing shareholders in proportion to holdings, at a price (usually below market)", "New shares issued to existing shareholders in proportion to holdings, free - no cash"], ["Cash raised", "Yes", "No"], ["Entries", "Dr Bank; Cr Share capital (nominal), Cr Share premium (excess)", "Dr Share premium (or other reserve/retained earnings); Cr Share capital"], ["Purpose", "Raise finance cheaply", "Capitalise reserves; increase number of shares"]], "id": "acffa2-rv12-279f1-c07a1b"}, {"t": "pt", "text": "Rights issue advantages: cheapest way to issue shares, control preserved; disadvantages: more expensive than debt, may not raise enough", "id": "acffa2-rv12-279f1-8992cd"}, {"t": "exam", "text": "Bonus issues are usually funded from share premium first", "id": "acffa2-rv12-279f1-db9f56"}], "id": "acffa2-rv12-279f1"}, {"kind": "rule", "title": "Dividends and loan notes", "page": [229, 231], "items": [{"t": "pt", "k": 1, "text": "Ordinary dividends are a distribution of profit - recorded in the STATEMENT OF CHANGES IN EQUITY, not as an expense in P/L", "id": "acffa2-rv12-8045c-a0f0ea"}, {"t": "pt", "k": 1, "text": "Interim dividend paid: Dr Retained earnings, Cr Bank", "id": "acffa2-rv12-8045c-44bd75"}, {"t": "pt", "k": 1, "text": "Final dividends proposed (declared/approved after the year end) are NOT a liability at the year end - disclose in a note", "id": "acffa2-rv12-8045c-1601e9"}, {"t": "pt", "k": 1, "text": "Loan notes (debentures) are LIABILITIES; interest is a finance cost in P/L", "id": "acffa2-rv12-8045c-a6d401"}, {"t": "f", "term": "Loan note interest", "text": "Nominal value x Interest rate x Months outstanding / 12", "vars": "accrue any unpaid interest at the year end", "eg": "$10,000 at 6% for a full year = $600 (accrue if unpaid)", "id": "acffa2-rv12-8045c-373c0f"}], "id": "acffa2-rv12-8045c"}, {"kind": "concept", "title": "Reserves and the SOCE", "page": [231, 232], "items": [{"t": "pt", "text": "Other reserves: share premium (capital), revaluation surplus (capital), retained earnings (revenue - available for distribution), general reserves", "id": "acffa2-rv12-d8532-285875"}, {"t": "pt", "k": 1, "text": "Statement of changes in equity reconciles opening and closing balances of share capital, share premium, revaluation surplus and retained earnings: issues of shares, profit for the year, other comprehensive income (revaluation gains), dividends paid", "id": "acffa2-rv12-d8532-0495d7"}, {"t": "pt", "text": "Retained earnings: accumulated profits not distributed", "id": "acffa2-rv12-d8532-774d21"}], "id": "acffa2-rv12-d8532"}, {"kind": "formula", "title": "Income tax", "page": [233, 235], "items": [{"t": "pt", "text": "Sole traders and partners pay tax personally; a company is taxed as a separate entity", "id": "acffa2-rv12-b8515-438a2a"}, {"t": "pt", "k": 1, "text": "Year end: Dr Income tax expense (P/L), Cr Income tax liability (current liability) with the ESTIMATED tax for the year", "id": "acffa2-rv12-b8515-9fd9d9"}, {"t": "pt", "k": 1, "text": "Next year: the difference between the estimate and the amount actually paid is an under- or over-provision, adjusted in NEXT year's tax expense", "id": "acffa2-rv12-b8515-bcd1d8"}, {"t": "f", "term": "Income tax expense", "text": "Current year estimate + Under-provision of prior year (or - over-provision)", "vars": "SOFP liability = current year estimate only", "eg": "Estimate $265,000 + prior under-provision $8,000 = expense $273,000; liability $265,000", "id": "acffa2-rv12-b8515-21241b"}], "id": "acffa2-rv12-b8515"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Crediting the full issue proceeds to share capital - the excess over nominal goes to share premium", "id": "acffa2-rv12-6483a-7e36dc"}, {"t": "x", "text": "Recording dividends as an expense in profit or loss", "id": "acffa2-rv12-6483a-b63e2a"}, {"t": "x", "text": "Recognising a final dividend declared after the year end as a liability", "id": "acffa2-rv12-6483a-d34f3c"}, {"t": "x", "text": "Adding the prior-year under-provision to the SOFP tax liability - it affects the expense only", "id": "acffa2-rv12-6483a-975a3a"}], "id": "acffa2-rv12-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Nominal value is arbitrary, not market value", "id": "acffa2-rv12-80e78-41b2ca"}, {"t": "pt", "text": "Premium = proceeds - nominal value -> share premium", "id": "acffa2-rv12-80e78-407453"}, {"t": "pt", "text": "Rights issue: cash, at a price, pro rata", "id": "acffa2-rv12-80e78-5128f8"}, {"t": "pt", "text": "Bonus issue: free, from reserves, pro rata", "id": "acffa2-rv12-80e78-3ddbf9"}, {"t": "pt", "text": "Bonus issue: Dr share premium, Cr share capital", "id": "acffa2-rv12-80e78-8c9a54"}, {"t": "pt", "text": "Dividends: in SOCE, Dr retained earnings", "id": "acffa2-rv12-80e78-ba7daa"}, {"t": "pt", "text": "Final dividend after year end: note only", "id": "acffa2-rv12-80e78-c07c6f"}, {"t": "pt", "text": "Loan notes: liability; interest = finance cost", "id": "acffa2-rv12-80e78-b28d5d"}, {"t": "pt", "text": "Accrue unpaid loan interest", "id": "acffa2-rv12-80e78-419117"}, {"t": "pt", "text": "SOCE: share issues, profit, OCI, dividends", "id": "acffa2-rv12-80e78-9e7b40"}, {"t": "pt", "text": "Tax expense = estimate ± prior-year under/over provision", "id": "acffa2-rv12-80e78-cb3e35"}, {"t": "pt", "text": "Tax liability = current-year estimate only", "id": "acffa2-rv12-80e78-b9a0a2"}], "id": "acffa2-rv12-80e78"}], "source": "Kaplan FA Study Text ch 12: sections 1-10 pp224-235; chapter summary p236", "summary": "Share capital terminology, issuing shares at nominal value and at a premium, rights and bonus issues, dividends, loan notes and finance costs, other reserves, the statement of changes in equity and income tax.", "id": "acffa2-rv12", "updated": "2026-11-12"}, {"num": "13", "title": "Reconciliations", "pages": [243, 260], "syllabus": "E1", "status": "published", "branches": [{"kind": "concept", "title": "Purpose of a bank reconciliation", "page": [244, 246], "items": [{"t": "pt", "k": 1, "text": "A bank reconciliation compares the cash at bank ledger account (cash book) with the bank statement and explains the differences", "id": "acffa2-rv13-40aeb-ed83ab"}, {"t": "pt", "text": "Purposes: detect errors and fraud, identify unrecorded items, confirm the correct cash figure for the SOFP", "id": "acffa2-rv13-40aeb-cb64dd"}, {"t": "exam", "text": "The SOFP always shows the REVISED (corrected) cash at bank ledger balance - never the bank statement balance", "id": "acffa2-rv13-40aeb-84958f"}], "id": "acffa2-rv13-40aeb"}, {"kind": "compare", "title": "Two types of difference", "page": [246, 247], "items": [{"t": "table", "rows": [["Adjust the cash book (ledger)", "Adjust the bank statement (reconciling items)"], ["Unrecorded items: bank charges, interest, standing orders, direct debits, direct credits (BACS receipts), dishonoured cheques", "Timing differences: outstanding (unpresented) cheques and outstanding deposits (lodgements)"], ["Errors in the cash book (eg transposed amounts)", "Errors made by the bank"]], "id": "acffa2-rv13-a27f2-28ddb3"}, {"t": "pt", "k": 1, "text": "Outstanding (unpresented) cheques: recorded in the cash book but not yet cleared by the bank - DEDUCT from the bank statement balance", "id": "acffa2-rv13-a27f2-268ce8"}, {"t": "pt", "k": 1, "text": "Outstanding deposits (lodgements): recorded in the cash book but not yet credited by the bank - ADD to the bank statement balance", "id": "acffa2-rv13-a27f2-0633fa"}, {"t": "pt", "text": "Dishonoured cheque received from a customer: Dr Receivables, Cr Cash at bank", "id": "acffa2-rv13-a27f2-371168"}], "id": "acffa2-rv13-a27f2"}, {"kind": "process", "title": "The reconciliation format", "page": [248, 251], "items": [{"t": "pt", "text": "Step 1: update the cash at bank ledger account for unrecorded items and cash book errors -> revised balance", "id": "acffa2-rv13-ff2f6-fccde5"}, {"t": "pt", "text": "Step 2: reconcile the bank statement balance to that revised balance", "id": "acffa2-rv13-ff2f6-87fb35"}, {"t": "f", "k": 1, "term": "Bank reconciliation", "text": "Balance per bank statement - Outstanding cheques + Outstanding deposits ± Bank errors = Revised cash at bank ledger balance", "vars": "watch overdrafts - treat them as negative balances", "id": "acffa2-rv13-ff2f6-fe0529"}, {"t": "exam", "text": "On a bank STATEMENT a credit balance means money in the account (the bank owes you); in the CASH BOOK a debit balance means money in the bank - the two are mirror images", "id": "acffa2-rv13-ff2f6-dbc08b"}], "id": "acffa2-rv13-ff2f6"}, {"kind": "concept", "title": "Supplier statement reconciliations", "page": [252, 254], "items": [{"t": "pt", "k": 1, "text": "Compare the supplier's statement with the payables ledger account for that supplier", "id": "acffa2-rv13-68edc-219525"}, {"t": "pt", "text": "Differences: payments in transit (made but not yet received by the supplier), invoices or credit notes not yet recorded, discounts, errors, disputed items", "id": "acffa2-rv13-68edc-24f1bb"}, {"t": "pt", "text": "Customer statements (aged) remind customers of credit terms and amounts overdue", "id": "acffa2-rv13-68edc-f4ceed"}], "id": "acffa2-rv13-68edc"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Adjusting the cash book for unpresented cheques - they are reconciling items on the bank statement side", "id": "acffa2-rv13-6483a-b80278"}, {"t": "x", "text": "Forgetting bank charges and direct debits in the cash book", "id": "acffa2-rv13-6483a-305df1"}, {"t": "x", "text": "Reporting the bank statement balance in the SOFP", "id": "acffa2-rv13-6483a-50f290"}, {"t": "x", "text": "Mixing up debit/credit meaning on a bank statement vs the cash book", "id": "acffa2-rv13-6483a-5f9881"}], "id": "acffa2-rv13-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Reconciliation explains cash book vs bank statement differences", "id": "acffa2-rv13-80e78-b14c2e"}, {"t": "pt", "text": "Cash book adjusted for unrecorded items and its own errors", "id": "acffa2-rv13-80e78-afdec1"}, {"t": "pt", "text": "Unrecorded: charges, interest, standing orders, direct debits, credits, dishonoured cheques", "id": "acffa2-rv13-80e78-226c2b"}, {"t": "pt", "text": "Bank statement side: outstanding cheques, outstanding deposits, bank errors", "id": "acffa2-rv13-80e78-d82c15"}, {"t": "pt", "text": "Unpresented cheques: deduct from bank balance", "id": "acffa2-rv13-80e78-407591"}, {"t": "pt", "text": "Outstanding deposits: add to bank balance", "id": "acffa2-rv13-80e78-0b7caa"}, {"t": "pt", "text": "SOFP uses the revised cash book balance", "id": "acffa2-rv13-80e78-9d79c0"}, {"t": "pt", "text": "Bank statement credit = money in your account", "id": "acffa2-rv13-80e78-04670e"}, {"t": "pt", "text": "Dishonoured cheque: Dr Receivables, Cr Bank", "id": "acffa2-rv13-80e78-fbb0f0"}, {"t": "pt", "text": "Supplier statement reconciliation explains payables differences", "id": "acffa2-rv13-80e78-bd90a2"}, {"t": "pt", "text": "Payments in transit cause timing differences", "id": "acffa2-rv13-80e78-61dabe"}, {"t": "pt", "text": "Overdrafts are negative balances", "id": "acffa2-rv13-80e78-228e1c"}], "id": "acffa2-rv13-80e78"}], "source": "Kaplan FA Study Text ch 13: sections 1-5 pp244-254; chapter summary p256", "summary": "The purpose of a bank reconciliation, adjustments to the cash book (unrecorded items, errors) vs reconciling items on the bank statement (timing differences, bank errors), the reconciliation format, and supplier statement reconciliations.", "id": "acffa2-rv13", "updated": "2026-11-12"}, {"num": "14", "title": "The Trial Balance, Errors and Suspense Accounts", "pages": [261, 280], "syllabus": "E2, E3", "status": "published", "branches": [{"kind": "concept", "title": "The trial balance", "page": [262, 264], "items": [{"t": "def", "k": 1, "term": "Trial balance", "text": "A list of all the ledger account balances (debits and credits) at a point in time - total debits should equal total credits", "id": "acffa2-rv14-a3d69-1c1ef3"}, {"t": "pt", "text": "Debit balances: assets, expenses, drawings; credit balances: liabilities, income, capital", "id": "acffa2-rv14-a3d69-732841"}, {"t": "pt", "k": 1, "text": "A balancing trial balance does NOT prove the ledgers are free of errors", "id": "acffa2-rv14-a3d69-b4bb6d"}], "id": "acffa2-rv14-a3d69"}, {"kind": "compare", "title": "Types of error", "page": [265, 267], "items": [{"t": "table", "rows": [["Error", "Description", "TB balances?"], ["Omission", "Transaction completely left out", "Yes"], ["Commission", "Correct amount, correct side, but the WRONG ACCOUNT of the same type (eg wrong receivable)", "Yes"], ["Principle", "Recorded in the wrong TYPE of account (eg capital expenditure as an expense)", "Yes"], ["Original entry (transposition)", "Wrong amount used for both debit and credit (eg 54 for 45)", "Yes"], ["Reversal of entries", "Debit and credit the wrong way round", "Yes"], ["Compensating", "Two errors cancel each other out", "Yes"], ["Single-sided entry / unequal entries", "Only one side posted, or different amounts", "No"], ["Casting (addition) error", "An account or listing added up wrongly", "No"], ["Transposition in one account", "Figures swapped on one side only", "No"]], "id": "acffa2-rv14-75d6c-142515"}, {"t": "pt", "k": 1, "text": "Only errors that make debits ≠ credits create a suspense account", "id": "acffa2-rv14-75d6c-2a51ca"}, {"t": "exam", "text": "A transposition difference is always divisible by 9", "id": "acffa2-rv14-75d6c-ecb229"}], "id": "acffa2-rv14-75d6c"}, {"kind": "process", "title": "Suspense accounts", "page": [267, 272], "items": [{"t": "pt", "k": 1, "text": "A suspense account is opened with the trial balance difference so that the TB balances temporarily - it must be cleared before the financial statements are finalised", "id": "acffa2-rv14-ac9a2-5dbf10"}, {"t": "pt", "text": "If the debit side of the TB is short, the suspense balance is a DEBIT; if the credit side is short, a CREDIT", "id": "acffa2-rv14-ac9a2-9b1f0e"}, {"t": "pt", "k": 1, "text": "Correcting journals: (1) what was done? (2) what should have been done? (3) the journal = the difference; if only one side is wrong, the other side of the correction goes to SUSPENSE", "id": "acffa2-rv14-ac9a2-096dd7"}, {"t": "eg", "text": "Payment of $500 recorded only in the bank: Dr Expense $500, Cr Suspense $500", "id": "acffa2-rv14-ac9a2-dcc7ac"}, {"t": "pt", "k": 1, "text": "Errors that did not affect the TB balance (omission, commission, principle etc) are corrected WITHOUT the suspense account", "id": "acffa2-rv14-ac9a2-5eaf12"}, {"t": "pt", "text": "Corrections may change profit - prepare a statement of adjustments to profit if required", "id": "acffa2-rv14-ac9a2-31dc3e"}, {"t": "exam", "text": "Questions often ask for the effect of correcting journals on profit or on the SOFP", "id": "acffa2-rv14-ac9a2-f9005c"}], "id": "acffa2-rv14-ac9a2"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using the suspense account to correct an error of principle - both sides are already posted", "id": "acffa2-rv14-6483a-f304eb"}, {"t": "x", "text": "Assuming a balanced TB means no errors", "id": "acffa2-rv14-6483a-2e55fb"}, {"t": "x", "text": "Getting the side of the suspense balance wrong - it sits on the side that was SHORT", "id": "acffa2-rv14-6483a-e5c6b7"}, {"t": "x", "text": "Forgetting that a correction moving cost between P/L and SOFP changes profit", "id": "acffa2-rv14-6483a-1935cd"}], "id": "acffa2-rv14-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "TB lists all ledger balances; debits = credits", "id": "acffa2-rv14-80e78-d68282"}, {"t": "pt", "text": "Balanced TB ≠ error-free ledgers", "id": "acffa2-rv14-80e78-e580b7"}, {"t": "pt", "text": "Errors not shown: omission, commission, principle, original entry, reversal, compensating", "id": "acffa2-rv14-80e78-4e9384"}, {"t": "pt", "text": "Errors shown: single-sided, unequal amounts, casting", "id": "acffa2-rv14-80e78-f2c606"}, {"t": "pt", "text": "Transposition differences divisible by 9", "id": "acffa2-rv14-80e78-254051"}, {"t": "pt", "text": "Suspense opened for the TB difference", "id": "acffa2-rv14-80e78-0f1d84"}, {"t": "pt", "text": "Suspense balance is on the short side", "id": "acffa2-rv14-80e78-8c41a2"}, {"t": "pt", "text": "Journal = what should have been - what was done", "id": "acffa2-rv14-80e78-8c68bb"}, {"t": "pt", "text": "One-sided errors corrected through suspense", "id": "acffa2-rv14-80e78-b568a9"}, {"t": "pt", "text": "Two-sided errors corrected without suspense", "id": "acffa2-rv14-80e78-76ad80"}, {"t": "pt", "text": "Clear suspense before preparing accounts", "id": "acffa2-rv14-80e78-618bab"}, {"t": "pt", "text": "Check the effect of corrections on profit", "id": "acffa2-rv14-80e78-41ee8f"}], "id": "acffa2-rv14-80e78"}], "source": "Kaplan FA Study Text ch 14: sections 1-6 pp262-272; chapter summary p274", "summary": "Extracting a trial balance, errors that do and do not cause an imbalance, opening a suspense account, correcting errors with journals and clearing the suspense account.", "id": "acffa2-rv14", "updated": "2026-11-12"}, {"num": "15", "title": "Preparing Basic Financial Statements", "pages": [281, 314], "syllabus": "F1, F2", "status": "published", "branches": [{"kind": "process", "title": "Common year-end adjustments", "page": [282, 284], "items": [{"t": "pt", "k": 1, "text": "Closing inventory (Dr Inventory, Cr Cost of sales) • depreciation • accruals and prepayments • irrecoverable debts and allowance movements • tax estimate • loan interest accrual", "id": "acffa2-rv15-47cd4-da503b"}, {"t": "pt", "k": 1, "text": "Tax: over-provision in prior year -> Dr Tax liability, Cr Tax charge; under-provision -> Dr Tax charge, Cr Tax liability", "id": "acffa2-rv15-47cd4-8c997f"}, {"t": "pt", "text": "Work methodically: list each adjustment and post both sides before drafting statements", "id": "acffa2-rv15-47cd4-9a24fb"}], "id": "acffa2-rv15-47cd4"}, {"kind": "concept", "title": "IAS 1 formats", "page": [285, 290], "items": [{"t": "pt", "k": 1, "text": "SOFP: non-current assets (PPE, intangibles, investments) + current assets (inventories, trade and other receivables, prepayments, cash) = equity (share capital, share premium, revaluation surplus, retained earnings) + non-current liabilities (loan notes) + current liabilities (trade and other payables, overdrafts, tax payable)", "id": "acffa2-rv15-e2a57-a6d8e9"}, {"t": "pt", "k": 1, "text": "Statement of profit or loss: revenue - cost of sales = gross profit - distribution costs - administrative expenses = profit from operations - finance costs = profit before tax - income tax = profit for the year", "id": "acffa2-rv15-e2a57-70d110"}, {"t": "pt", "text": "Other comprehensive income: items that will not be reclassified to profit or loss (eg gain on property revaluation) -> total comprehensive income", "id": "acffa2-rv15-e2a57-b8617d"}, {"t": "pt", "k": 1, "text": "SOCE: share capital, share premium, revaluation surplus, retained earnings - with share issues, profit, OCI and dividends", "id": "acffa2-rv15-e2a57-7e0685"}, {"t": "pt", "text": "Revaluation surplus: created when non-current assets are revalued; retained earnings: all profits and losses since incorporation less dividends", "id": "acffa2-rv15-e2a57-10ff8e"}, {"t": "exam", "text": "Current vs non-current split: realised/settled within 12 months or the normal operating cycle", "id": "acffa2-rv15-e2a57-549225"}], "id": "acffa2-rv15-e2a57"}, {"kind": "rule", "title": "IAS 10 Events after the reporting period", "page": [299, 301], "items": [{"t": "pt", "k": 1, "text": "Events between the reporting date and the date the financial statements are authorised for issue", "id": "acffa2-rv15-ad070-7a9c2e"}, {"t": "pt", "k": 1, "text": "Adjusting events provide evidence of conditions EXISTING at the reporting date -> adjust the figures", "kids": [{"t": "pt", "text": "Settlement of a court case confirming a year-end obligation", "id": "acffa2-rv15-ad070-e37de9"}, {"t": "pt", "text": "Sale of year-end inventory below cost (evidence of NRV)", "id": "acffa2-rv15-ad070-7366a7"}, {"t": "pt", "text": "Insolvency of a customer that owed money at the year end", "id": "acffa2-rv15-ad070-02c24c"}, {"t": "pt", "text": "Discovery of fraud or errors", "id": "acffa2-rv15-ad070-81d4f9"}], "id": "acffa2-rv15-ad070-5cc650"}, {"t": "pt", "k": 1, "text": "Non-adjusting events relate to conditions ARISING after the reporting date -> disclose if material (nature and estimated financial effect)", "kids": [{"t": "pt", "text": "Announcing a plan to discontinue an operation", "id": "acffa2-rv15-ad070-de9ad7"}, {"t": "pt", "text": "Major purchases of assets", "id": "acffa2-rv15-ad070-3632f0"}, {"t": "pt", "text": "Destruction of assets by fire or flood after the year end", "id": "acffa2-rv15-ad070-95a2a8"}, {"t": "pt", "text": "Share issues, large changes in asset prices or exchange rates", "id": "acffa2-rv15-ad070-1cbf27"}], "id": "acffa2-rv15-ad070-b8bb6f"}, {"t": "x", "text": "Dividends declared after the reporting date are not a liability at the reporting date", "id": "acffa2-rv15-ad070-c6df86"}, {"t": "pt", "text": "Going concern: if events show the entity is not a going concern, the basis of preparation changes", "id": "acffa2-rv15-ad070-c5f09f"}], "id": "acffa2-rv15-ad070"}, {"kind": "process", "title": "IFRS 15 Revenue", "page": [302, 304], "items": [{"t": "def", "k": 1, "term": "Revenue", "text": "Income arising in the course of an entity's ordinary activities", "id": "acffa2-rv15-28650-823c3c"}, {"t": "pt", "k": 1, "text": "Five-step approach: 1 identify the contract -> 2 identify the performance obligations -> 3 determine the transaction price -> 4 allocate the price to the performance obligations -> 5 recognise revenue when (or as) each obligation is satisfied", "id": "acffa2-rv15-28650-28054d"}, {"t": "pt", "k": 1, "text": "Revenue is recognised either at a point in time (when control passes) or over time (as the obligation is satisfied)", "id": "acffa2-rv15-28650-06599d"}, {"t": "pt", "text": "Disclosure: revenue by category, contract balances, performance obligations", "id": "acffa2-rv15-28650-5894d5"}], "id": "acffa2-rv15-28650"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Showing finance costs within administrative expenses - they are a separate line", "id": "acffa2-rv15-6483a-64f340"}, {"t": "x", "text": "Treating a post-year-end fire as an adjusting event - it is non-adjusting", "id": "acffa2-rv15-6483a-d259da"}, {"t": "x", "text": "Putting a revaluation gain in profit for the year - it is OCI", "id": "acffa2-rv15-6483a-eb529e"}, {"t": "x", "text": "Recognising revenue on receipt of cash rather than when the performance obligation is satisfied", "id": "acffa2-rv15-6483a-05c5e0"}], "id": "acffa2-rv15-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Year-end adjustments: inventory, depreciation, accruals, prepayments, receivables, tax, interest", "id": "acffa2-rv15-80e78-b22075"}, {"t": "pt", "text": "SOFP: assets = equity + liabilities, current/non-current", "id": "acffa2-rv15-80e78-cb2de0"}, {"t": "pt", "text": "P/L: revenue -> gross profit -> operating profit -> PBT -> profit for the year", "id": "acffa2-rv15-80e78-8980c0"}, {"t": "pt", "text": "OCI: revaluation gains (not reclassified)", "id": "acffa2-rv15-80e78-ac8f1e"}, {"t": "pt", "text": "SOCE: share capital, premium, revaluation surplus, retained earnings", "id": "acffa2-rv15-80e78-558303"}, {"t": "pt", "text": "IAS 10: adjusting = conditions at the reporting date", "id": "acffa2-rv15-80e78-e3745d"}, {"t": "pt", "text": "Non-adjusting = conditions after; disclose if material", "id": "acffa2-rv15-80e78-a4481c"}, {"t": "pt", "text": "Post-year-end dividends: not a liability", "id": "acffa2-rv15-80e78-348fd4"}, {"t": "pt", "text": "Inventory sold below cost after year end: adjusting", "id": "acffa2-rv15-80e78-b141b6"}, {"t": "pt", "text": "IFRS 15 five steps: contract, obligations, price, allocate, recognise", "id": "acffa2-rv15-80e78-5597ee"}, {"t": "pt", "text": "Revenue at a point in time or over time", "id": "acffa2-rv15-80e78-f96884"}, {"t": "pt", "text": "Tax over-provision reduces the tax charge", "id": "acffa2-rv15-80e78-2fcce9"}], "id": "acffa2-rv15-80e78"}], "source": "Kaplan FA Study Text ch 15: sections 1-9 pp282-304; chapter summary p306", "summary": "From trial balance to financial statements: common year-end adjustments, IAS 1 formats for the SOFP, statement of profit or loss and OCI, SOCE, IAS 10 events after the reporting period, and IFRS 15 revenue recognition.", "id": "acffa2-rv15", "updated": "2026-11-12"}, {"num": "16", "title": "Incomplete Records", "pages": [315, 334], "syllabus": "F3", "status": "published", "branches": [{"kind": "formula", "title": "The accounting equation approach", "page": [316, 317], "items": [{"t": "f", "k": 1, "term": "Net assets approach", "text": "Closing net assets - Opening net assets = Capital introduced + Profit - Drawings", "vars": "rearrange to find the missing figure (usually profit or drawings)", "eg": "Opening net assets 10,000, closing 15,000, drawings 2,000, no capital introduced: profit = 7,000", "id": "acffa2-rv16-3bb00-6855c5"}, {"t": "f", "term": "Company version", "text": "Closing retained earnings = Opening retained earnings + Profit (or - loss) - Dividends", "vars": "total assets = share capital + retained earnings + other reserves + liabilities", "id": "acffa2-rv16-3bb00-499124"}], "id": "acffa2-rv16-3bb00"}, {"kind": "process", "title": "Ledger account reconstruction", "page": [318, 324], "items": [{"t": "pt", "k": 1, "text": "Use control accounts with the missing figure as the BALANCING figure", "id": "acffa2-rv16-2054c-8dc457"}, {"t": "pt", "text": "Receivables: b/f + credit sales = receipts + returns + irrecoverable debts + discounts + c/f -> missing credit sales or receipts", "id": "acffa2-rv16-2054c-cc1470"}, {"t": "pt", "text": "Payables: payments + returns + discounts + c/f = b/f + credit purchases -> missing credit purchases or payments", "id": "acffa2-rv16-2054c-6513ad"}, {"t": "pt", "text": "Cash in hand: cash sales + sundry income = sundry cash expenses + amounts banked + drawings + c/f -> missing cash taken or stolen", "id": "acffa2-rv16-2054c-ed4af0"}, {"t": "pt", "text": "Cash at bank: receipts from customers + banked cash = payments to suppliers + expenses + c/f", "id": "acffa2-rv16-2054c-628124"}, {"t": "exam", "text": "Total sales = cash sales + credit sales; total purchases = cash purchases + credit purchases", "id": "acffa2-rv16-2054c-92c857"}], "id": "acffa2-rv16-2054c"}, {"kind": "formula", "title": "Margins and mark-ups", "page": [325, 325], "items": [{"t": "f", "k": 1, "term": "Gross profit margin", "text": "Gross profit / Sales x 100%", "vars": "margin is based on SELLING PRICE", "eg": "25% margin: if sales $100, cost of sales $75", "id": "acffa2-rv16-ba1ba-977ac9"}, {"t": "f", "k": 1, "term": "Mark-up", "text": "Gross profit / Cost of sales x 100%", "vars": "mark-up is based on COST", "eg": "25% mark-up: if cost $100, sales $125", "id": "acffa2-rv16-ba1ba-d5a312"}, {"t": "f", "term": "Converting", "text": "Margin 20% = mark-up 25% (20/80); mark-up 25% = margin 20% (25/125)", "vars": "use the cost structure: sales 100 / cost 80 / profit 20", "id": "acffa2-rv16-ba1ba-48051d"}, {"t": "exam", "text": "Exam questions often give a margin or mark-up and ask for sales, cost of sales or missing inventory", "id": "acffa2-rv16-ba1ba-e00987"}], "id": "acffa2-rv16-ba1ba"}, {"kind": "process", "title": "Missing and lost inventory", "page": [325, 327], "items": [{"t": "pt", "k": 1, "text": "Find expected closing inventory: opening inventory + purchases - cost of sales (using the margin/mark-up to get cost of sales from sales)", "id": "acffa2-rv16-7d467-9ba0f9"}, {"t": "pt", "text": "Lost/stolen/destroyed inventory = expected closing inventory - actual closing inventory", "id": "acffa2-rv16-7d467-7c69c3"}, {"t": "pt", "text": "Inventory lost (uninsured): Dr Expense (P/L), Cr Cost of sales (purchases)", "id": "acffa2-rv16-7d467-355077"}, {"t": "pt", "text": "Insured loss: Dr Insurance receivable, Cr Cost of sales; owner's personal use: Dr Drawings, Cr Cost of sales", "id": "acffa2-rv16-7d467-a49b94"}], "id": "acffa2-rv16-7d467"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Applying the margin % to cost instead of to sales", "id": "acffa2-rv16-6483a-540b7d"}, {"t": "x", "text": "Forgetting cash sales when deriving total sales", "id": "acffa2-rv16-6483a-3b01dd"}, {"t": "x", "text": "Treating the net assets increase as profit without adjusting for drawings and capital introduced", "id": "acffa2-rv16-6483a-dc07ee"}, {"t": "x", "text": "Leaving lost inventory in cost of sales without recording the loss separately when required", "id": "acffa2-rv16-6483a-9c30c5"}], "id": "acffa2-rv16-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Δ net assets = capital introduced + profit - drawings", "id": "acffa2-rv16-80e78-133e8c"}, {"t": "pt", "text": "Missing figure = balancing figure in a control account", "id": "acffa2-rv16-80e78-d0ef43"}, {"t": "pt", "text": "Receivables account finds credit sales or receipts", "id": "acffa2-rv16-80e78-9d9638"}, {"t": "pt", "text": "Payables account finds credit purchases or payments", "id": "acffa2-rv16-80e78-35a6d0"}, {"t": "pt", "text": "Cash account finds cash stolen or drawings", "id": "acffa2-rv16-80e78-e0d620"}, {"t": "pt", "text": "Total sales = cash + credit", "id": "acffa2-rv16-80e78-c91ed5"}, {"t": "pt", "text": "Margin = GP / sales", "id": "acffa2-rv16-80e78-56e418"}, {"t": "pt", "text": "Mark-up = GP / cost", "id": "acffa2-rv16-80e78-af6579"}, {"t": "pt", "text": "20% margin = 25% mark-up", "id": "acffa2-rv16-80e78-2a6f78"}, {"t": "pt", "text": "Expected closing inventory = opening + purchases - cost of sales", "id": "acffa2-rv16-80e78-aab7a7"}, {"t": "pt", "text": "Lost inventory = expected - actual", "id": "acffa2-rv16-80e78-7571fd"}, {"t": "pt", "text": "Goods taken by owner: Dr Drawings", "id": "acffa2-rv16-80e78-36131d"}, {"t": "pt", "text": "Insured losses: Dr insurance receivable", "id": "acffa2-rv16-80e78-0ea911"}], "id": "acffa2-rv16-80e78"}], "source": "Kaplan FA Study Text ch 16: sections 1-6 pp316-327; chapter summary p328", "summary": "Techniques for missing figures: the accounting equation and net asset approach, ledger account reconstruction (receivables, payables, cash and bank), margins and mark-ups, and missing or lost inventory.", "id": "acffa2-rv16", "updated": "2026-11-12"}, {"num": "17", "title": "Statement of Cash Flows", "pages": [335, 368], "syllabus": "F4", "status": "published", "branches": [{"kind": "concept", "title": "Profit, cash and IAS 7", "page": [336, 338], "items": [{"t": "pt", "k": 1, "text": "A profitable entity can still fail if it runs out of cash - cash flow is vital to survival", "id": "acffa2-rv17-3081d-d443fa"}, {"t": "pt", "text": "IAS 7 objective: report cash flows classified by operating, investing and financing activities", "id": "acffa2-rv17-3081d-8bdbb8"}, {"t": "def", "k": 1, "term": "Cash flows", "text": "Inflows and outflows of cash and cash equivalents (IAS 7 para 6)", "id": "acffa2-rv17-3081d-0e6acc"}, {"t": "pt", "text": "Benefits: shows ability to generate cash, liquidity and solvency, harder to manipulate than profit, helps assess future cash flows", "id": "acffa2-rv17-3081d-d7df55"}, {"t": "pt", "text": "Drawbacks: historic, does not show profitability, can be distorted by the timing of transactions near the year end", "id": "acffa2-rv17-3081d-d1dea6"}], "id": "acffa2-rv17-3081d"}, {"kind": "compare", "title": "The three classifications", "page": [339, 339], "items": [{"t": "table", "rows": [["Section", "Examples"], ["Operating activities", "Cash generated from operations, interest paid, income taxes paid"], ["Investing activities", "Purchase of PPE, proceeds of sale of PPE, interest and dividends received"], ["Financing activities", "Proceeds of issue of shares, new loans, repayment of loans, dividends paid"]], "id": "acffa2-rv17-9ce78-97c9b7"}, {"t": "pt", "text": "Net increase/(decrease) in cash and cash equivalents + opening cash and cash equivalents = closing cash and cash equivalents", "id": "acffa2-rv17-9ce78-99fe00"}, {"t": "exam", "text": "A proposed dividend never appears in a statement of cash flows - only dividends actually PAID", "id": "acffa2-rv17-9ce78-2d9f62"}], "id": "acffa2-rv17-9ce78"}, {"kind": "process", "title": "Operating cash flows: indirect method", "page": [340, 347], "items": [{"t": "pt", "k": 1, "text": "Start with profit before tax, then:", "kids": [{"t": "pt", "text": "Add back: depreciation, amortisation, loss on disposal, finance costs (interest expense), increase in allowance/provisions", "id": "acffa2-rv17-cd591-e4762a"}, {"t": "pt", "text": "Deduct: profit on disposal, investment income", "id": "acffa2-rv17-cd591-31f18d"}, {"t": "pt", "text": "Working capital: deduct INCREASE in inventories and receivables; add INCREASE in payables (reverse for decreases)", "id": "acffa2-rv17-cd591-6e3231"}], "id": "acffa2-rv17-cd591-a34dc0"}, {"t": "pt", "text": "= Cash generated from operations, then deduct interest paid and tax paid = net cash from operating activities", "id": "acffa2-rv17-cd591-f2de45"}, {"t": "pt", "k": 1, "text": "Direct method: cash received from customers - cash paid to suppliers and employees - other operating payments (gross cash flows from ledger reconstruction)", "id": "acffa2-rv17-cd591-0f2abf"}, {"t": "pt", "text": "Both methods give the SAME net cash from operating activities", "id": "acffa2-rv17-cd591-004b17"}], "id": "acffa2-rv17-cd591"}, {"kind": "formula", "title": "Working out individual cash flows", "page": [347, 351], "items": [{"t": "f", "k": 1, "term": "Tax (or interest) paid", "text": "Opening liability + P/L charge - Closing liability", "vars": "balancing figure in the tax/interest payable account", "eg": "include deferred amounts where relevant", "id": "acffa2-rv17-0fc80-b968f0"}, {"t": "f", "term": "Interest/dividends received", "text": "Opening receivable + P/L income - Closing receivable", "id": "acffa2-rv17-0fc80-1cd75c"}, {"t": "f", "k": 1, "term": "PPE purchased (cash)", "text": "Closing carrying amount - Opening carrying amount + Depreciation + Carrying amount of disposals - Revaluation surplus in the year", "vars": "balancing figure in the PPE account", "id": "acffa2-rv17-0fc80-390342"}, {"t": "f", "term": "Proceeds of sale of PPE", "text": "Carrying amount of disposal + Profit on disposal (or - loss)", "id": "acffa2-rv17-0fc80-fa9373"}, {"t": "f", "term": "Loans raised or repaid", "text": "Closing loans - Opening loans", "id": "acffa2-rv17-0fc80-11e1df"}, {"t": "f", "term": "Dividends paid", "text": "Opening retained earnings + Profit for the year - Closing retained earnings (if no other movements)", "id": "acffa2-rv17-0fc80-49c4fa"}, {"t": "exam", "text": "PPE additions are often the trickiest figure - remember revaluations and disposals", "id": "acffa2-rv17-0fc80-bfde96"}], "id": "acffa2-rv17-0fc80"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Adding an increase in receivables or inventory - increases use cash, so deduct them", "id": "acffa2-rv17-6483a-0bb2cc"}, {"t": "x", "text": "Forgetting to add back depreciation and the loss on disposal", "id": "acffa2-rv17-6483a-a19bb0"}, {"t": "x", "text": "Including the revaluation surplus as a cash inflow", "id": "acffa2-rv17-6483a-add1a6"}, {"t": "x", "text": "Showing the profit on disposal as investing cash - the PROCEEDS are the investing inflow", "id": "acffa2-rv17-6483a-d288ba"}], "id": "acffa2-rv17-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Profit is not cash", "id": "acffa2-rv17-80e78-583aba"}, {"t": "pt", "text": "Three sections: operating, investing, financing", "id": "acffa2-rv17-80e78-f5c75a"}, {"t": "pt", "text": "Indirect: PBT + non-cash items ± working capital", "id": "acffa2-rv17-80e78-9cd8d3"}, {"t": "pt", "text": "Increase in inventory/receivables: deduct", "id": "acffa2-rv17-80e78-4d0980"}, {"t": "pt", "text": "Increase in payables: add", "id": "acffa2-rv17-80e78-765e4d"}, {"t": "pt", "text": "Add back depreciation, losses, interest expense", "id": "acffa2-rv17-80e78-0e188a"}, {"t": "pt", "text": "Then deduct interest paid and tax paid", "id": "acffa2-rv17-80e78-7e2eaf"}, {"t": "pt", "text": "Direct method uses gross receipts and payments", "id": "acffa2-rv17-80e78-0fb5a3"}, {"t": "pt", "text": "Tax paid = opening + charge - closing liability", "id": "acffa2-rv17-80e78-f1ce5a"}, {"t": "pt", "text": "PPE additions = balancing figure (allow for depreciation, disposals, revaluation)", "id": "acffa2-rv17-80e78-2e2957"}, {"t": "pt", "text": "Proceeds = carrying amount ± profit/loss", "id": "acffa2-rv17-80e78-d878a3"}, {"t": "pt", "text": "Dividends paid are financing (proposed dividends excluded)", "id": "acffa2-rv17-80e78-810ef3"}, {"t": "pt", "text": "Net change in cash links opening to closing cash", "id": "acffa2-rv17-80e78-52f8f2"}], "id": "acffa2-rv17-80e78"}], "source": "Kaplan FA Study Text ch 17: sections 1-7 pp336-355; chapter summary p357", "summary": "Profit vs cash, IAS 7 objectives, benefits and drawbacks, the three classifications, direct and indirect methods for operating cash flows, and working out interest, tax, PPE, loans and dividends.", "id": "acffa2-rv17", "updated": "2026-11-12"}, {"num": "18", "title": "Interpretation of Financial Statements", "pages": [369, 390], "syllabus": "G1", "status": "published", "branches": [{"kind": "formula", "title": "Profitability", "page": [371, 376], "items": [{"t": "f", "k": 1, "term": "Gross profit margin", "text": "Gross profit / Revenue x 100%", "vars": "compare over time and with other companies - changes in prices, sales mix, purchase costs", "id": "acffa2-rv18-70bb2-cf06ab"}, {"t": "f", "k": 1, "term": "Operating (net) profit margin", "text": "Operating profit (PBIT) / Revenue x 100%", "vars": "affected by more factors: overhead control as well as gross margin", "id": "acffa2-rv18-70bb2-5486cd"}, {"t": "f", "k": 1, "term": "Return on capital employed (ROCE)", "text": "Profit before interest and tax / Capital employed x 100%", "vars": "capital employed = equity + non-current liabilities (= total assets - current liabilities)", "eg": "measures how efficiently resources generate profit", "id": "acffa2-rv18-70bb2-983c20"}, {"t": "f", "k": 1, "term": "Net asset turnover", "text": "Revenue / Capital employed (net assets)", "vars": "times per year - how well management uses assets to generate revenue", "id": "acffa2-rv18-70bb2-00b8db"}, {"t": "f", "k": 1, "term": "ROCE relationship", "text": "ROCE = Operating profit margin x Net asset turnover", "vars": "margin = quality of profit; turnover = volume of activity", "id": "acffa2-rv18-70bb2-29564e"}, {"t": "pt", "text": "Users interpret ratios differently: investors (returns), lenders (security, gearing), suppliers (liquidity)", "id": "acffa2-rv18-70bb2-e21e9e"}], "id": "acffa2-rv18-70bb2"}, {"kind": "formula", "title": "Liquidity and efficiency", "page": [376, 382], "items": [{"t": "f", "k": 1, "term": "Current ratio", "text": "Current assets / Current liabilities : 1", "vars": "adequacy of current assets to meet short-term liabilities", "id": "acffa2-rv18-dc804-f23044"}, {"t": "f", "k": 1, "term": "Quick (acid test) ratio", "text": "(Current assets - Inventory) / Current liabilities : 1", "vars": "excludes inventory, the least liquid asset", "id": "acffa2-rv18-dc804-08a470"}, {"t": "f", "k": 1, "term": "Inventory turnover period", "text": "Inventory / Cost of sales x 365 days", "vars": "how efficiently inventory is managed", "eg": "14,000 / 42,000 x 365 = 122 days", "id": "acffa2-rv18-dc804-cd4a20"}, {"t": "f", "k": 1, "term": "Receivables collection period", "text": "Trade receivables / Credit sales x 365 days", "vars": "compare with credit terms", "id": "acffa2-rv18-dc804-2f5ff5"}, {"t": "f", "k": 1, "term": "Payables payment period", "text": "Trade payables / Credit purchases (or cost of sales) x 365 days", "id": "acffa2-rv18-dc804-78138b"}, {"t": "pt", "text": "Year-end inventory may be unrepresentative (seasonal businesses) - use average where possible", "id": "acffa2-rv18-dc804-1d634e"}, {"t": "exam", "text": "Too high a current ratio may mean idle assets (excess inventory or cash); too low may signal liquidity problems", "id": "acffa2-rv18-dc804-7c4335"}], "id": "acffa2-rv18-dc804"}, {"kind": "formula", "title": "Gearing and interest cover", "page": [383, 384], "items": [{"t": "f", "k": 1, "term": "Gearing (debt/equity)", "text": "Interest-bearing debt / Equity x 100%", "vars": "or debt / (debt + equity)", "id": "acffa2-rv18-5375b-475460"}, {"t": "pt", "k": 1, "text": "Higher gearing = higher financial risk: interest is mandatory, while dividends are discretionary", "id": "acffa2-rv18-5375b-69914b"}, {"t": "pt", "text": "Debt is usually cheaper to service than equity (and interest is tax-deductible) but increases risk", "id": "acffa2-rv18-5375b-f72d51"}, {"t": "f", "k": 1, "term": "Interest cover", "text": "PBIT / Interest payable", "vars": "ability to pay interest out of profit - low cover is risky", "id": "acffa2-rv18-5375b-6708a2"}], "id": "acffa2-rv18-5375b"}, {"kind": "process", "title": "Interpreting ratios", "page": [385, 386], "items": [{"t": "pt", "k": 1, "text": "Calculate -> compare (prior year, competitors, industry averages) -> explain causes -> conclude for the user", "id": "acffa2-rv18-76272-c4d896"}, {"t": "eg", "text": "Rising revenue with falling margin may mean price cuts to win sales; longer receivables days may mean weak credit control", "id": "acffa2-rv18-76272-1a888b"}, {"t": "pt", "text": "Limitations: historic data, different accounting policies, inflation, year-end window dressing, one ratio means little alone", "id": "acffa2-rv18-76272-509ce6"}], "id": "acffa2-rv18-76272"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using total sales instead of CREDIT sales for receivables days", "id": "acffa2-rv18-6483a-de8d73"}, {"t": "x", "text": "Including inventory in the quick ratio", "id": "acffa2-rv18-6483a-5f6d7d"}, {"t": "x", "text": "Using profit AFTER interest for ROCE - use PBIT", "id": "acffa2-rv18-6483a-0dadde"}, {"t": "x", "text": "Concluding from one ratio without comparison or explanation", "id": "acffa2-rv18-6483a-9219e5"}], "id": "acffa2-rv18-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "GP margin = GP / revenue", "id": "acffa2-rv18-80e78-0069db"}, {"t": "pt", "text": "Operating margin = PBIT / revenue", "id": "acffa2-rv18-80e78-f44ea3"}, {"t": "pt", "text": "ROCE = PBIT / capital employed", "id": "acffa2-rv18-80e78-1240e9"}, {"t": "pt", "text": "Asset turnover = revenue / capital employed", "id": "acffa2-rv18-80e78-242314"}, {"t": "pt", "text": "ROCE = margin x asset turnover", "id": "acffa2-rv18-80e78-1030d8"}, {"t": "pt", "text": "Current = CA / CL", "id": "acffa2-rv18-80e78-7922a2"}, {"t": "pt", "text": "Quick = (CA - inventory) / CL", "id": "acffa2-rv18-80e78-ff65a7"}, {"t": "pt", "text": "Inventory days = inventory / COS x 365", "id": "acffa2-rv18-80e78-fbd907"}, {"t": "pt", "text": "Receivables days = receivables / credit sales x 365", "id": "acffa2-rv18-80e78-d3aa27"}, {"t": "pt", "text": "Payables days = payables / credit purchases x 365", "id": "acffa2-rv18-80e78-c22447"}, {"t": "pt", "text": "Gearing = debt / equity (or debt / (debt + equity))", "id": "acffa2-rv18-80e78-931eb8"}, {"t": "pt", "text": "Interest cover = PBIT / interest", "id": "acffa2-rv18-80e78-9ba1a2"}, {"t": "pt", "text": "Higher gearing = higher risk", "id": "acffa2-rv18-80e78-6415b5"}], "id": "acffa2-rv18-80e78"}], "source": "Kaplan FA Study Text ch 18: sections 1-6 pp370-386; chapter summary p387", "summary": "Users and interpretation, profitability ratios (gross margin, operating margin, ROCE, asset turnover), liquidity and efficiency ratios (current, quick, inventory, receivables and payables days) and gearing and interest cover.", "id": "acffa2-rv18", "updated": "2026-11-12"}, {"num": "19", "title": "Consolidated Statement of Financial Position", "pages": [391, 434], "syllabus": "F6", "status": "published", "branches": [{"kind": "def", "title": "Control and group terms", "page": [392, 394], "items": [{"t": "def", "k": 1, "term": "Control (IFRS 10)", "text": "An investor controls an investee when it has power over it, exposure or rights to variable returns from its involvement, and the ability to use its power to affect those returns", "id": "acffa2-rv19-31c41-cee7e5"}, {"t": "pt", "k": 1, "text": "Usually evidenced by owning MORE THAN 50% of the equity (voting) shares", "id": "acffa2-rv19-31c41-e79825"}, {"t": "def", "k": 1, "term": "Parent", "text": "An entity that controls one or more entities", "id": "acffa2-rv19-31c41-46a6d1"}, {"t": "def", "k": 1, "term": "Subsidiary", "text": "An entity that is controlled by another entity", "id": "acffa2-rv19-31c41-4b6f17"}, {"t": "def", "k": 1, "term": "Non-controlling interest (NCI)", "text": "The equity in a subsidiary not attributable to the parent (eg 20% when the parent owns 80%)", "id": "acffa2-rv19-31c41-2f56b9"}, {"t": "pt", "text": "Consolidated statements present the group as a single economic entity", "id": "acffa2-rv19-31c41-6a519c"}], "id": "acffa2-rv19-31c41"}, {"kind": "process", "title": "The five workings", "page": [395, 399], "items": [{"t": "pt", "k": 1, "text": "W1 Group structure: parent's % and NCI %, date of acquisition", "id": "acffa2-rv19-6707b-285978"}, {"t": "pt", "k": 1, "text": "W2 Net assets of the subsidiary at acquisition and at the reporting date (share capital + share premium + revaluation surplus + retained earnings + fair value adjustments)", "id": "acffa2-rv19-6707b-a6fb41"}, {"t": "pt", "k": 1, "text": "W3 Goodwill", "id": "acffa2-rv19-6707b-dea992"}, {"t": "pt", "k": 1, "text": "W4 Non-controlling interest: FV of NCI at acquisition + NCI % of post-acquisition reserves (- NCI share of goodwill impairment)", "id": "acffa2-rv19-6707b-6e2d11"}, {"t": "pt", "k": 1, "text": "W5 Group retained earnings: P's retained earnings (100%) + P's % of S's post-acquisition retained earnings - PURP (if P sold) - goodwill impairment (P's share)", "id": "acffa2-rv19-6707b-03655e"}, {"t": "pt", "text": "Consolidation: add P's and S's assets and liabilities in FULL (100%), cancel P's investment in S, show goodwill, NCI within equity", "id": "acffa2-rv19-6707b-55cc30"}], "id": "acffa2-rv19-6707b"}, {"kind": "formula", "title": "Goodwill", "page": [395, 405], "items": [{"t": "f", "k": 1, "term": "Goodwill", "text": "FV of consideration paid + FV of NCI at acquisition - FV of net assets of the subsidiary at acquisition", "vars": "positive goodwill is an intangible non-current asset", "eg": "Consideration 50,000 + NCI 12,500 - net assets 45,000 = 17,500", "id": "acffa2-rv19-fd268-8ccaa7"}, {"t": "pt", "text": "Goodwill is not amortised - tested annually for impairment", "id": "acffa2-rv19-fd268-148444"}, {"t": "pt", "k": 1, "text": "Fair value (IFRS 13): the price that would be received to sell an asset (or paid to transfer a liability) in an orderly transaction between market participants at the measurement date - an EXIT price", "id": "acffa2-rv19-fd268-608eda"}, {"t": "pt", "k": 1, "text": "Fair value adjustments to the subsidiary's net assets go in BOTH columns of W2 (and affect depreciation/post-acquisition profit if relevant)", "id": "acffa2-rv19-fd268-822c4e"}, {"t": "pt", "text": "Deferred consideration is measured at present value; share consideration at the market value of P's shares issued", "id": "acffa2-rv19-fd268-ef46f8"}], "id": "acffa2-rv19-fd268"}, {"kind": "process", "title": "Intra-group items", "page": [410, 416], "items": [{"t": "pt", "k": 1, "text": "Intra-group receivables and payables (current accounts) cancel: Dr Payables, Cr Receivables - reconcile cash and goods in transit first", "id": "acffa2-rv19-b36ed-35f47e"}, {"t": "pt", "k": 1, "text": "Unrealised profit (PURP): profit on goods sold within the group still held in inventory at the year end is removed", "id": "acffa2-rv19-b36ed-e32099"}, {"t": "f", "term": "PURP", "text": "Profit in inventory still held = Inventory at transfer price x margin (or x mark-up / (100 + mark-up))", "vars": "25% mark-up on $8,000 held: 25/125 x 8,000 = $1,600", "id": "acffa2-rv19-b36ed-e446fc"}, {"t": "pt", "k": 1, "text": "Seller = parent: Dr Group retained earnings, Cr Inventory; seller = subsidiary: reduce S's post-acquisition profits in W2 (shared with NCI)", "id": "acffa2-rv19-b36ed-b7db69"}], "id": "acffa2-rv19-b36ed"}, {"kind": "process", "title": "Mid-year acquisitions", "page": [416, 418], "items": [{"t": "pt", "k": 1, "text": "Calculate the subsidiary's reserves at the acquisition date by time-apportioning the year's profit (assume it accrues evenly)", "id": "acffa2-rv19-d1e49-34b91b"}, {"t": "eg", "text": "K acquired 60% of S on 1 May 20X7 for $76,000: S's retained earnings at acquisition = opening + profit for the months before acquisition", "id": "acffa2-rv19-d1e49-5d1c1e"}, {"t": "pt", "text": "Post-acquisition profit = profit for the months after acquisition only", "id": "acffa2-rv19-d1e49-63d655"}, {"t": "exam", "text": "MCQs often ask for goodwill, the NCI figure, group retained earnings, or where goodwill is classified (intangible non-current asset)", "id": "acffa2-rv19-d1e49-3c1925"}], "id": "acffa2-rv19-d1e49"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Adding only the parent's % of the subsidiary's assets - consolidate 100% and show NCI", "id": "acffa2-rv19-6483a-e09fcb"}, {"t": "x", "text": "Including pre-acquisition profits in group retained earnings", "id": "acffa2-rv19-6483a-810cc9"}, {"t": "x", "text": "Forgetting fair value adjustments at the reporting date column of W2", "id": "acffa2-rv19-6483a-ee6c40"}, {"t": "x", "text": "Deducting the full PURP from group retained earnings when the SUBSIDIARY is the seller - share it with NCI", "id": "acffa2-rv19-6483a-91bd2a"}], "id": "acffa2-rv19-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Control: power + variable returns + ability to use power", "id": "acffa2-rv19-80e78-493296"}, {"t": "pt", "text": "Usually > 50% voting shares", "id": "acffa2-rv19-80e78-f8ae4b"}, {"t": "pt", "text": "W1 structure, W2 net assets, W3 goodwill, W4 NCI, W5 group RE", "id": "acffa2-rv19-80e78-805e08"}, {"t": "pt", "text": "Goodwill = consideration + NCI - net assets at acquisition", "id": "acffa2-rv19-80e78-8433bf"}, {"t": "pt", "text": "Goodwill: intangible asset, impairment tested, not amortised", "id": "acffa2-rv19-80e78-9579b9"}, {"t": "pt", "text": "Fair value = exit price", "id": "acffa2-rv19-80e78-79cdeb"}, {"t": "pt", "text": "Consolidate 100% of S's assets and liabilities", "id": "acffa2-rv19-80e78-bee714"}, {"t": "pt", "text": "NCI = FV at acquisition + share of post-acquisition reserves", "id": "acffa2-rv19-80e78-124cf8"}, {"t": "pt", "text": "Group RE = P 100% + P% of S post-acquisition - PURP - impairment", "id": "acffa2-rv19-80e78-d5bbaf"}, {"t": "pt", "text": "Cancel intra-group balances", "id": "acffa2-rv19-80e78-a07cb8"}, {"t": "pt", "text": "PURP = profit in inventory still held", "id": "acffa2-rv19-80e78-1654bb"}, {"t": "pt", "text": "Mid-year: time-apportion profit to find pre-acquisition reserves", "id": "acffa2-rv19-80e78-f096ac"}], "id": "acffa2-rv19-80e78"}], "source": "Kaplan FA Study Text ch 19: sections 1-12 pp392-418; chapter summary p421", "summary": "Control and the parent-subsidiary relationship (IFRS 10), non-controlling interests, the five standard workings, goodwill, fair values (IFRS 13), intra-group balances, unrealised profit in inventory and mid-year acquisitions.", "id": "acffa2-rv19", "updated": "2026-11-12"}, {"num": "20", "title": "Consolidated Statement of Profit or Loss and Associates", "pages": [435, 460], "syllabus": "F6", "status": "published", "branches": [{"kind": "process", "title": "Consolidated statement of profit or loss", "page": [436, 438], "items": [{"t": "pt", "k": 1, "text": "Add P's and S's income and expenses line by line in FULL (100%) from revenue down to profit for the year", "id": "acffa2-rv20-f3a84-97842c"}, {"t": "pt", "k": 1, "text": "Profit for the year is then split: attributable to owners of the parent and to the non-controlling interest", "id": "acffa2-rv20-f3a84-65eacb"}, {"t": "f", "k": 1, "term": "NCI share of profit", "text": "NCI % x Subsidiary's profit for the year (after PURP if the subsidiary is the seller, and after fair value depreciation adjustments)", "vars": "eg 20% x $50,000 = $10,000", "id": "acffa2-rv20-f3a84-691ee4"}, {"t": "pt", "text": "Dividends from the subsidiary to the parent are cancelled (not group income)", "id": "acffa2-rv20-f3a84-0d0a92"}], "id": "acffa2-rv20-f3a84"}, {"kind": "formula", "title": "Intra-group trading", "page": [438, 440], "items": [{"t": "f", "k": 1, "term": "Group revenue", "text": "P revenue + S revenue - Intra-group sales", "vars": "$630 + $260 - $42 = $848", "id": "acffa2-rv20-bf24f-c5b7fe"}, {"t": "f", "k": 1, "term": "Group cost of sales", "text": "P COS + S COS - Intra-group purchases + Unrealised profit (PURP)", "vars": "the PURP increases cost of sales", "id": "acffa2-rv20-bf24f-d6abbd"}, {"t": "f", "term": "PURP", "text": "Inventory still held at transfer price x profit %", "vars": "Selling price $42, cost $28 -> profit $14 on goods held", "id": "acffa2-rv20-bf24f-320783"}, {"t": "exam", "text": "Remove intra-group sales from BOTH revenue and cost of sales, then add the PURP to cost of sales", "id": "acffa2-rv20-bf24f-95c934"}], "id": "acffa2-rv20-bf24f"}, {"kind": "process", "title": "Mid-year acquisitions", "page": [440, 443], "items": [{"t": "pt", "k": 1, "text": "Consolidate the subsidiary's results only from the date of acquisition - time-apportion its income and expenses", "id": "acffa2-rv20-d1e49-05cd3f"}, {"t": "eg", "text": "Acquired 1 December, year end 31 March: include 4/12 of S's revenue and costs (eg $151,800 + $108,850 x 4/12)", "id": "acffa2-rv20-d1e49-72c8a8"}, {"t": "pt", "text": "Intra-group adjustments apply only to trading after acquisition", "id": "acffa2-rv20-d1e49-5a8f99"}, {"t": "pt", "text": "NCI share of profit is based on the post-acquisition profit only", "id": "acffa2-rv20-d1e49-598fcf"}], "id": "acffa2-rv20-d1e49"}, {"kind": "decision", "title": "Associates and investments", "page": [444, 446], "items": [{"t": "def", "k": 1, "term": "Associate", "text": "An entity over which the investor has significant influence (IAS 28)", "id": "acffa2-rv20-58216-d6f044"}, {"t": "def", "k": 1, "term": "Significant influence", "text": "The power to participate in the financial and operating policy decisions of the investee but not control or joint control - usually 20% to 50% of voting rights", "id": "acffa2-rv20-58216-937f4a"}, {"t": "dq", "text": "Does the investor control the investee (usually > 50%)?", "yes": "Subsidiary - consolidate line by line", "no": "Go on to check significant influence", "id": "acffa2-rv20-58216-3213df"}, {"t": "dq", "text": "Does the investor have significant influence (usually 20-50%)?", "yes": "Associate - equity method", "no": "Simple investment - at fair value (dividends as income)", "id": "acffa2-rv20-58216-b9628c"}, {"t": "f", "k": 1, "term": "Investment in associate (SOFP)", "text": "Cost + Group share of post-acquisition retained earnings - Impairment", "vars": "one line in non-current assets", "id": "acffa2-rv20-58216-eb54ad"}, {"t": "f", "k": 1, "term": "Share of profit of associate (P/L)", "text": "Group % x Associate's profit for the year (after tax)", "vars": "one line, shown before group profit before tax", "id": "acffa2-rv20-58216-61aa89"}, {"t": "pt", "text": "Trading with an associate: sales and purchases are NOT eliminated (the associate is outside the group); unrealised profit on group share is removed", "id": "acffa2-rv20-58216-3c823e"}], "id": "acffa2-rv20-58216"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Consolidating an associate line by line - use the equity method", "id": "acffa2-rv20-6483a-a3119e"}, {"t": "x", "text": "Eliminating only the profit, not the full intra-group sale, from revenue", "id": "acffa2-rv20-6483a-ab02fd"}, {"t": "x", "text": "Including a full year of a subsidiary acquired mid-year", "id": "acffa2-rv20-6483a-e20c22"}, {"t": "x", "text": "Calculating NCI share before deducting a PURP when the subsidiary sold the goods", "id": "acffa2-rv20-6483a-748a9f"}], "id": "acffa2-rv20-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Consolidated P/L: add 100% line by line", "id": "acffa2-rv20-80e78-1da2b6"}, {"t": "pt", "text": "Split profit between parent owners and NCI", "id": "acffa2-rv20-80e78-28f33d"}, {"t": "pt", "text": "NCI share = NCI% x S's (adjusted) profit", "id": "acffa2-rv20-80e78-f662df"}, {"t": "pt", "text": "Group revenue = P + S - intra-group sales", "id": "acffa2-rv20-80e78-5e3522"}, {"t": "pt", "text": "Group COS = P + S - intra-group purchases + PURP", "id": "acffa2-rv20-80e78-888ef9"}, {"t": "pt", "text": "Mid-year: time-apportion S's results", "id": "acffa2-rv20-80e78-80f00c"}, {"t": "pt", "text": "Intra-group dividends cancelled", "id": "acffa2-rv20-80e78-5ccb4b"}, {"t": "pt", "text": "Associate = significant influence, 20-50%", "id": "acffa2-rv20-80e78-784af9"}, {"t": "pt", "text": "Equity method: cost + share of post-acquisition reserves", "id": "acffa2-rv20-80e78-bd5175"}, {"t": "pt", "text": "P/L: share of associate's profit after tax (one line)", "id": "acffa2-rv20-80e78-471d37"}, {"t": "pt", "text": "Subsidiary > 50%: consolidate", "id": "acffa2-rv20-80e78-c787de"}, {"t": "pt", "text": "Simple investment < 20%: fair value, dividends as income", "id": "acffa2-rv20-80e78-9b0131"}, {"t": "pt", "text": "Associate trading not eliminated", "id": "acffa2-rv20-80e78-4d0caf"}], "id": "acffa2-rv20-80e78"}], "source": "Kaplan FA Study Text ch 20: sections 1-9 pp436-446; chapter summary p447", "summary": "The consolidated statement of profit or loss, NCI share of profit, eliminating intra-group sales and unrealised profit, mid-year acquisitions, associates and the equity method (IAS 28), and simple investments.", "id": "acffa2-rv20", "updated": "2026-11-12"}], "plannedChapters": 20}, {"id": "acffa2st", "code": "FA2", "name": "Maintaining Financial Records", "level": "Foundations in Accountancy", "book": "ACCA-FA2.pdf | BPP FA2 Practice & Revision Kit (scanned) | offset 12", "updated": "2026-11-13", "note": "No FA2 study text is in the portal: ACCA-FA2.pdf is the BPP Practice & Revision Kit (byte-identical to ACCA-FA2-KIT.pdf). These maps are built from the kit's 'Did you know?' revision pages, questions and worked answers (OCR of the scanned kit). Page numbers are kit pages. Add the FA2 study text to the portal to re-base them on it.", "chapters": [{"num": "1", "title": "Assets, Liabilities and the Accounting Equation", "pages": [3, 8], "syllabus": "A1", "status": "published", "branches": [{"kind": "def", "title": "Core definitions", "page": [4, 4], "items": [{"t": "def", "k": 1, "term": "Asset", "text": "Something owned by a business (a resource controlled by it)", "id": "acffa2st-rv1-ea66c-777559"}, {"t": "def", "k": 1, "term": "Liability", "text": "Something owed by a business", "id": "acffa2st-rv1-ea66c-9c0867"}, {"t": "pt", "text": "Non-current assets are held and used in operations for a long time; current assets are held for only a short time", "id": "acffa2st-rv1-ea66c-77cb03"}, {"t": "def", "k": 1, "term": "Profit", "text": "The excess of income over expenditure (a loss when expenditure exceeds income)", "id": "acffa2st-rv1-ea66c-39258a"}, {"t": "def", "term": "Payables", "text": "Balances due to suppliers - liabilities", "id": "acffa2st-rv1-ea66c-a13d6b"}, {"t": "def", "term": "Receivables", "text": "Balances due from customers - assets", "id": "acffa2st-rv1-ea66c-4f3b7f"}], "id": "acffa2st-rv1-ea66c"}, {"kind": "formula", "title": "The accounting equation", "page": [4, 7], "items": [{"t": "f", "k": 1, "term": "Accounting equation", "text": "Capital + Liabilities = Assets", "vars": "capital = the owner's interest; every transaction keeps it in balance", "eg": "Andy introduces $5,000 cash: assets 5,000 = capital 5,000", "id": "acffa2st-rv1-c82f7-53aaad"}, {"t": "f", "k": 1, "term": "Business equation", "text": "Increase in net assets - Capital introduced + Drawings = Net profit", "vars": "net assets = assets - liabilities", "eg": "Net assets up $8,000, capital introduced $2,000, drawings $3,000: profit = 9,000", "id": "acffa2st-rv1-c82f7-618f9e"}, {"t": "pt", "text": "Drawings reduce capital; capital introduced and profit increase it", "id": "acffa2st-rv1-c82f7-3d48bf"}, {"t": "eg", "text": "Buying goods on credit: inventory (asset) up and payables (liability) up - equation stays balanced", "id": "acffa2st-rv1-c82f7-ab01f7"}], "id": "acffa2st-rv1-c82f7"}, {"kind": "compare", "title": "The two main statements", "page": [4, 4], "items": [{"t": "table", "rows": [["Statement", "What it shows", "Time"], ["Statement of profit or loss", "Income generated and expenditure incurred", "Over a PERIOD"], ["Statement of financial position", "Assets owned and liabilities owed (and capital)", "At a particular DATE"]], "id": "acffa2st-rv1-86a2c-55d4f8"}, {"t": "pt", "k": 1, "text": "Net profit = gross profit + other income - overheads not in cost of goods sold (selling, distribution, administration)", "id": "acffa2st-rv1-86a2c-244406"}], "id": "acffa2st-rv1-86a2c"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Questions give opening and closing net assets with capital and drawings and ask for profit - use the business equation", "id": "acffa2st-rv1-308d8-741dc9"}, {"t": "exam", "text": "An owner who takes goods or cash for personal use makes DRAWINGS, not an expense", "id": "acffa2st-rv1-308d8-86ed5d"}], "id": "acffa2st-rv1-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing assets and liabilities (eg a bank overdraft is a liability)", "id": "acffa2st-rv1-6483a-1162a8"}, {"t": "x", "text": "Mixing statement of profit or loss items with statement of financial position items", "id": "acffa2st-rv1-6483a-b3e738"}, {"t": "x", "text": "Adding drawings instead of deducting them from capital", "id": "acffa2st-rv1-6483a-3074d2"}, {"t": "x", "text": "Treating capital introduced as profit", "id": "acffa2st-rv1-6483a-4e1c7a"}], "id": "acffa2st-rv1-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Asset = owned; liability = owed", "id": "acffa2st-rv1-80e78-f803ea"}, {"t": "pt", "text": "Non-current assets: long-term use", "id": "acffa2st-rv1-80e78-0e1050"}, {"t": "pt", "text": "Current assets: short-term", "id": "acffa2st-rv1-80e78-7499bc"}, {"t": "pt", "text": "Profit = income - expenditure", "id": "acffa2st-rv1-80e78-ce36bd"}, {"t": "pt", "text": "Capital + liabilities = assets", "id": "acffa2st-rv1-80e78-ed42b0"}, {"t": "pt", "text": "Payables = liabilities; receivables = assets", "id": "acffa2st-rv1-80e78-1216b0"}, {"t": "pt", "text": "P/L covers a period; SOFP is at a date", "id": "acffa2st-rv1-80e78-ee2cbb"}, {"t": "pt", "text": "Net profit = GP + other income - overheads", "id": "acffa2st-rv1-80e78-fb6134"}, {"t": "pt", "text": "Δ net assets - capital introduced + drawings = profit", "id": "acffa2st-rv1-80e78-7444e0"}, {"t": "pt", "text": "Drawings reduce capital", "id": "acffa2st-rv1-80e78-6fdc25"}, {"t": "pt", "text": "Every transaction keeps the equation balanced", "id": "acffa2st-rv1-80e78-5ab597"}, {"t": "pt", "text": "Overdraft is a liability", "id": "acffa2st-rv1-80e78-22aafd"}], "id": "acffa2st-rv1-80e78"}], "source": "BPP FA2 Kit section 1: 'Did you know?' p4; questions 1.1-1.15 pp5-7; answers p119", "summary": "Assets and liabilities, current vs non-current, profit, the accounting equation, payables and receivables, the statement of profit or loss and statement of financial position, and the business equation.", "id": "acffa2st-rv1", "updated": "2026-11-13"}, {"num": "2", "title": "Statement of Financial Position and Statement of Profit or Loss", "pages": [9, 14], "syllabus": "A2", "status": "published", "branches": [{"kind": "rule", "title": "Non-current assets", "page": [10, 10], "items": [{"t": "pt", "k": 1, "text": "To be a non-current asset an item must satisfy THREE conditions", "kids": [{"t": "pt", "text": "It must be used by the business", "id": "acffa2st-rv2-b403a-0a83ab"}, {"t": "pt", "text": "It must be used with a view to earning income or generating profits from its use", "id": "acffa2st-rv2-b403a-53cb95"}, {"t": "pt", "text": "It must have a life in use of more than one accounting period (typically one year)", "id": "acffa2st-rv2-b403a-959e79"}], "id": "acffa2st-rv2-b403a-fc58ce"}, {"t": "eg", "text": "A delivery van used for deliveries over five years = non-current asset; goods bought for resale = inventory (current asset)", "id": "acffa2st-rv2-b403a-ce3c66"}], "id": "acffa2st-rv2-b403a"}, {"kind": "def", "title": "Current items", "page": [10, 10], "items": [{"t": "def", "k": 1, "term": "Current assets", "text": "Items owned with the intention of turning them into cash within one year (inventories and receivables), or cash itself, including money in the bank", "id": "acffa2st-rv2-944b7-fe4a75"}, {"t": "def", "k": 1, "term": "Current liabilities", "text": "Debts that must be paid within a fairly short period of time (by convention, one year)", "id": "acffa2st-rv2-944b7-150ba4"}, {"t": "pt", "k": 1, "text": "Any liability that is not current must be NON-current (eg a five-year bank loan, except the instalment due within a year)", "id": "acffa2st-rv2-944b7-219d7f"}], "id": "acffa2st-rv2-944b7"}, {"kind": "compare", "title": "Capital vs revenue expenditure", "page": [10, 10], "items": [{"t": "table", "rows": [["Type", "Definition", "Example"], ["Capital expenditure", "Results in the acquisition of non-current assets", "Buying a machine, building an extension"], ["Revenue expenditure", "Incurred for the trade of the business or the maintenance of non-current assets", "Repairs, wages, purchases for resale"]], "id": "acffa2st-rv2-22ce0-ed8065"}, {"t": "pt", "text": "Capital expenditure goes to the SOFP (then depreciated); revenue expenditure goes to the statement of profit or loss", "id": "acffa2st-rv2-22ce0-89e134"}], "id": "acffa2st-rv2-22ce0"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Questions ask how a five-year loan or a prepaid item is classified, or which items are capital expenditure", "id": "acffa2st-rv2-308d8-5a505c"}, {"t": "exam", "text": "Watch for the part of a long-term loan repayable within 12 months - it is a current liability", "id": "acffa2st-rv2-308d8-f1f53e"}], "id": "acffa2st-rv2-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Miscategorising non-current and current assets, or current and non-current liabilities", "id": "acffa2st-rv2-6483a-db3bc3"}, {"t": "x", "text": "Treating repairs to existing assets as capital expenditure", "id": "acffa2st-rv2-6483a-840fe0"}, {"t": "x", "text": "Mixing statement of profit or loss and statement of financial position items", "id": "acffa2st-rv2-6483a-92daa3"}, {"t": "x", "text": "Confusing assets and liabilities", "id": "acffa2st-rv2-6483a-1a1d3b"}], "id": "acffa2st-rv2-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Non-current asset: used by the business, to earn income, life > one period", "id": "acffa2st-rv2-80e78-7e7728"}, {"t": "pt", "text": "Current assets: inventory, receivables, cash", "id": "acffa2st-rv2-80e78-85e3e7"}, {"t": "pt", "text": "Current assets turn into cash within one year", "id": "acffa2st-rv2-80e78-1cd1ea"}, {"t": "pt", "text": "Current liabilities: payable within one year", "id": "acffa2st-rv2-80e78-5c46b7"}, {"t": "pt", "text": "Not current = non-current", "id": "acffa2st-rv2-80e78-ad3b23"}, {"t": "pt", "text": "Five-year loan: non-current (except the current instalment)", "id": "acffa2st-rv2-80e78-50d9d3"}, {"t": "pt", "text": "Capital expenditure: acquires non-current assets", "id": "acffa2st-rv2-80e78-b64fd6"}, {"t": "pt", "text": "Revenue expenditure: trade and maintenance", "id": "acffa2st-rv2-80e78-f7c72b"}, {"t": "pt", "text": "Capital expenditure to the SOFP", "id": "acffa2st-rv2-80e78-47ea5b"}, {"t": "pt", "text": "Revenue expenditure to profit or loss", "id": "acffa2st-rv2-80e78-b0a5d0"}, {"t": "pt", "text": "Repairs are revenue expenditure", "id": "acffa2st-rv2-80e78-e7741e"}, {"t": "pt", "text": "Goods for resale are current assets", "id": "acffa2st-rv2-80e78-d663d9"}], "id": "acffa2st-rv2-80e78"}], "source": "BPP FA2 Kit section 2: 'Did you know?' p10; questions 2.1-2.14 pp11-13; answers pp120-121", "summary": "The three conditions for a non-current asset, current assets and current liabilities, non-current liabilities, and capital vs revenue expenditure.", "id": "acffa2st-rv2", "updated": "2026-11-13"}, {"num": "3", "title": "Recording and Summarising Transactions", "pages": [15, 20], "syllabus": "A3", "status": "published", "branches": [{"kind": "concept", "title": "Books of prime entry", "page": [16, 16], "items": [{"t": "pt", "k": 1, "text": "Transactions are initially recorded in BOOKS OF PRIME ENTRY", "id": "acffa2st-rv3-d8210-960a4f"}, {"t": "pt", "k": 1, "text": "Sales day book: a list of all invoices sent out to customers each day", "id": "acffa2st-rv3-d8210-1a9b31"}, {"t": "pt", "text": "Sales returns day book: records goods returned by customers", "id": "acffa2st-rv3-d8210-020938"}, {"t": "pt", "k": 1, "text": "Purchase day book: the record of all invoices received from suppliers", "id": "acffa2st-rv3-d8210-cb5b38"}, {"t": "pt", "text": "Purchase returns day book: records credit notes received for goods sent back to suppliers", "id": "acffa2st-rv3-d8210-df29f8"}, {"t": "pt", "k": 1, "text": "Cash book: a cumulative record of money received and paid out via the business's bank account", "id": "acffa2st-rv3-d8210-214c52"}, {"t": "pt", "text": "Petty cash book: small cash payments; journal: unusual items and corrections", "id": "acffa2st-rv3-d8210-833c85"}, {"t": "eg", "text": "Tallon sells goods on credit for $150: record in the sales day book, then post to the ledger", "id": "acffa2st-rv3-d8210-56e045"}], "id": "acffa2st-rv3-d8210"}, {"kind": "compare", "title": "Discounts", "page": [16, 16], "items": [{"t": "table", "rows": [["Discount", "Meaning", "Recording"], ["Trade discount", "A reduction in the PRICE of goods (eg for regular or bulk customers)", "Deducted on the invoice - goods recorded net"], ["Settlement discount", "A reduction in the AMOUNT PAYABLE for early payment", "Recorded when payment is made early (discount received/allowed)"]], "id": "acffa2st-rv3-9544f-4a4fb4"}], "id": "acffa2st-rv3-9544f"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Questions ask which book of prime entry records a document (eg credit note received -> purchase returns day book)", "id": "acffa2st-rv3-308d8-1952b4"}, {"t": "exam", "text": "Day book totals are posted to the general ledger - check you post to the correct account and side", "id": "acffa2st-rv3-308d8-b80b4f"}], "id": "acffa2st-rv3-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing books of prime entry with ledger accounts", "id": "acffa2st-rv3-6483a-8465ea"}, {"t": "x", "text": "Posting totals to incorrect ledger accounts, or to the wrong side of the correct account", "id": "acffa2st-rv3-6483a-0abe65"}, {"t": "x", "text": "Treating a trade discount as a separate expense", "id": "acffa2st-rv3-6483a-b310ea"}, {"t": "x", "text": "Recording credit notes received in the sales returns day book", "id": "acffa2st-rv3-6483a-070162"}], "id": "acffa2st-rv3-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Books of prime entry record transactions first", "id": "acffa2st-rv3-80e78-d96be1"}, {"t": "pt", "text": "Sales day book: invoices to customers", "id": "acffa2st-rv3-80e78-ab5658"}, {"t": "pt", "text": "Sales returns day book: customer returns", "id": "acffa2st-rv3-80e78-b94e6d"}, {"t": "pt", "text": "Purchase day book: supplier invoices", "id": "acffa2st-rv3-80e78-4519d0"}, {"t": "pt", "text": "Purchase returns day book: credit notes from suppliers", "id": "acffa2st-rv3-80e78-e2e2af"}, {"t": "pt", "text": "Cash book: bank receipts and payments", "id": "acffa2st-rv3-80e78-ef1247"}, {"t": "pt", "text": "Journal: unusual items and corrections", "id": "acffa2st-rv3-80e78-e94dc7"}, {"t": "pt", "text": "Trade discount reduces the price", "id": "acffa2st-rv3-80e78-e7414d"}, {"t": "pt", "text": "Settlement discount reduces the amount payable for early payment", "id": "acffa2st-rv3-80e78-395ab5"}, {"t": "pt", "text": "Day book totals posted to the general ledger", "id": "acffa2st-rv3-80e78-9e6253"}, {"t": "pt", "text": "Books of prime entry are not ledger accounts", "id": "acffa2st-rv3-80e78-b42a2d"}, {"t": "pt", "text": "Post to the correct side", "id": "acffa2st-rv3-80e78-fdd7c9"}], "id": "acffa2st-rv3-80e78"}], "source": "BPP FA2 Kit section 3: 'Did you know?' p16; questions 3.1-3.13 pp17-19; answers p121", "summary": "Books of prime entry - sales, sales returns, purchases and purchase returns day books, the cash book - and trade and settlement discounts.", "id": "acffa2st-rv3", "updated": "2026-11-13"}, {"num": "4", "title": "Posting Transactions, Balancing Accounts and the Trial Balance", "pages": [21, 30], "syllabus": "A4", "status": "published", "branches": [{"kind": "concept", "title": "The general ledger and posting", "page": [22, 22], "items": [{"t": "def", "k": 1, "term": "General ledger", "text": "The accounting record that summarises the financial affairs of a business - many ledger accounts each with its own code or name (also called the nominal ledger)", "id": "acffa2st-rv4-773ce-c8fd9f"}, {"t": "def", "k": 1, "term": "Posting", "text": "Entering transactions in the general ledger accounts from the books of prime entry", "id": "acffa2st-rv4-773ce-f96d3d"}, {"t": "pt", "k": 1, "text": "Every debit must have an equal credit and vice versa", "id": "acffa2st-rv4-773ce-fba214"}, {"t": "pt", "k": 1, "text": "A cash PAYMENT is a CREDIT entry in the cash account; a cash RECEIPT is a DEBIT entry", "id": "acffa2st-rv4-773ce-34ec2f"}, {"t": "pt", "text": "Output sales tax is charged on sales; input sales tax is incurred on purchases", "id": "acffa2st-rv4-773ce-dc01ed"}, {"t": "pt", "text": "Credit transactions are also entered in the individual accounts for receivables and payables", "id": "acffa2st-rv4-773ce-5916d3"}], "id": "acffa2st-rv4-773ce"}, {"kind": "def", "title": "Control accounts and the journal", "page": [22, 22], "items": [{"t": "def", "k": 1, "term": "Control account", "text": "An account in the general ledger recording the total value of a number of similar but individual items - used chiefly for receivables and payables", "id": "acffa2st-rv4-dea64-018d18"}, {"t": "def", "k": 1, "term": "Journal", "text": "A record of unusual movements between accounts - used for double entries that do not arise from the other books of prime entry (eg corrections, year-end adjustments)", "id": "acffa2st-rv4-dea64-df2c3c"}], "id": "acffa2st-rv4-dea64"}, {"kind": "compare", "title": "The trial balance", "page": [22, 29], "items": [{"t": "table", "rows": [["Error", "Disclosed by the trial balance?"], ["Omission", "No"], ["Commission", "No"], ["Principle", "No"], ["Original entry", "No"], ["Compensating errors", "No"], ["Single-sided entry / unequal debit and credit", "Yes"], ["Casting (addition) error in an account", "Yes"]], "id": "acffa2st-rv4-a3d69-e35798"}, {"t": "def", "k": 1, "term": "Trial balance", "text": "A list of all the balances in every account in the general ledger at the end of a period", "id": "acffa2st-rv4-a3d69-e557ae"}, {"t": "eg", "text": "Colin bought stationery for $430 but recorded $340 in both accounts - an error of original entry; the TB still balances", "id": "acffa2st-rv4-a3d69-acfad0"}], "id": "acffa2st-rv4-a3d69"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Questions ask which errors would cause a trial balance imbalance (single-sided, unequal or casting errors)", "id": "acffa2st-rv4-308d8-0a72d1"}, {"t": "exam", "text": "Balancing an account: the balance c/d goes on the side with the smaller total", "id": "acffa2st-rv4-308d8-8030b1"}], "id": "acffa2st-rv4-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Debiting the cash account for a payment - payments are credits", "id": "acffa2st-rv4-6483a-f32a15"}, {"t": "x", "text": "Thinking a balanced trial balance means there are no errors", "id": "acffa2st-rv4-6483a-ea888e"}, {"t": "x", "text": "Posting individual customer balances instead of control account totals to the trial balance", "id": "acffa2st-rv4-6483a-dd3ad9"}, {"t": "x", "text": "Using the journal for routine credit sales", "id": "acffa2st-rv4-6483a-4fd9f5"}], "id": "acffa2st-rv4-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "General ledger = nominal ledger", "id": "acffa2st-rv4-80e78-4fae2f"}, {"t": "pt", "text": "Posting: from books of prime entry to ledger accounts", "id": "acffa2st-rv4-80e78-b986b7"}, {"t": "pt", "text": "Every debit has an equal credit", "id": "acffa2st-rv4-80e78-2f915a"}, {"t": "pt", "text": "Cash receipt = debit; cash payment = credit", "id": "acffa2st-rv4-80e78-9e0f0b"}, {"t": "pt", "text": "Output tax on sales; input tax on purchases", "id": "acffa2st-rv4-80e78-f3abe3"}, {"t": "pt", "text": "Control accounts for receivables and payables", "id": "acffa2st-rv4-80e78-690020"}, {"t": "pt", "text": "Journal: unusual entries and corrections", "id": "acffa2st-rv4-80e78-a93495"}, {"t": "pt", "text": "TB lists all general ledger balances", "id": "acffa2st-rv4-80e78-e52b5c"}, {"t": "pt", "text": "Not disclosed: omission, commission, principle, original entry, compensating", "id": "acffa2st-rv4-80e78-c4d81b"}, {"t": "pt", "text": "Disclosed: single-sided, unequal, casting errors", "id": "acffa2st-rv4-80e78-6d77ef"}, {"t": "pt", "text": "Balance c/d on the smaller side", "id": "acffa2st-rv4-80e78-7762d3"}, {"t": "pt", "text": "Individual accounts are memoranda", "id": "acffa2st-rv4-80e78-3f965f"}], "id": "acffa2st-rv4-80e78"}], "source": "BPP FA2 Kit section 4: 'Did you know?' p22; questions 4.1-4.30 pp23-29; answers pp122-124", "summary": "The general (nominal) ledger, posting from books of prime entry, double entry, sales tax, cash entries, control accounts, the journal, the trial balance and errors it will not disclose.", "id": "acffa2st-rv4", "updated": "2026-11-13"}, {"num": "5", "title": "Accounting Principles and Characteristics", "pages": [31, 34], "syllabus": "B1", "status": "published", "branches": [{"kind": "concept", "title": "Seven accounting principles", "page": [32, 32], "items": [{"t": "pt", "k": 1, "text": "Accruals: income and expenses recognised in the period in which they arise, not when cash moves", "id": "acffa2st-rv5-4c7d2-4bb550"}, {"t": "pt", "k": 1, "text": "Going concern: the business will continue in operation for the foreseeable future", "id": "acffa2st-rv5-4c7d2-8b4914"}, {"t": "pt", "text": "Money measurement: only items that can be measured in money are recorded", "id": "acffa2st-rv5-4c7d2-eba15e"}, {"t": "pt", "k": 1, "text": "Business entity: the business is separate from its owner", "id": "acffa2st-rv5-4c7d2-eb565b"}, {"t": "pt", "text": "Consistency: the same treatment from period to period (and within a period)", "id": "acffa2st-rv5-4c7d2-3c11e6"}, {"t": "pt", "text": "Historical cost: items recorded at their original cost", "id": "acffa2st-rv5-4c7d2-b995c3"}, {"t": "pt", "k": 1, "text": "Materiality: an item is material if its omission or misstatement would influence users' decisions - immaterial items need not be treated strictly", "id": "acffa2st-rv5-4c7d2-4fe3a3"}, {"t": "pt", "text": "Others exist (eg prudence, duality)", "id": "acffa2st-rv5-4c7d2-56edeb"}], "id": "acffa2st-rv5-4c7d2"}, {"kind": "concept", "title": "Standards and qualitative characteristics", "page": [32, 32], "items": [{"t": "pt", "k": 1, "text": "International Financial Reporting Standards (IFRS Standards) are published by the International Accounting Standards Board (IASB)", "id": "acffa2st-rv5-ad292-703a3e"}, {"t": "pt", "k": 1, "text": "Two fundamental qualitative characteristics: RELEVANCE and FAITHFUL REPRESENTATION", "id": "acffa2st-rv5-ad292-f64091"}, {"t": "pt", "k": 1, "text": "Four enhancing characteristics: comparability • verifiability • timeliness • understandability", "id": "acffa2st-rv5-ad292-07f47b"}], "id": "acffa2st-rv5-ad292"}, {"kind": "compare", "title": "Principles vs characteristics", "page": [32, 32], "items": [{"t": "table", "rows": [["Group", "Members"], ["Accounting principles (concepts)", "Accruals, going concern, money measurement, business entity, consistency, historical cost, materiality"], ["Fundamental characteristics", "Relevance, faithful representation"], ["Enhancing characteristics", "Comparability, verifiability, timeliness, understandability"]], "id": "acffa2st-rv5-52133-73de7f"}], "id": "acffa2st-rv5-52133"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Questions describe a treatment and ask which principle it applies (eg recording rent owing at the year end = accruals)", "id": "acffa2st-rv5-308d8-e3b29d"}, {"t": "exam", "text": "Accounting standards are NOT required by law in themselves - questions test this", "id": "acffa2st-rv5-308d8-b9009a"}], "id": "acffa2st-rv5-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Failing to understand the difference between material and immaterial items", "id": "acffa2st-rv5-6483a-ac52a5"}, {"t": "x", "text": "Thinking that accounting standards are required by law", "id": "acffa2st-rv5-6483a-9b8c9b"}, {"t": "x", "text": "Confusing principles with qualitative characteristics", "id": "acffa2st-rv5-6483a-76ba3a"}, {"t": "x", "text": "Calling comparability a fundamental characteristic - it is enhancing", "id": "acffa2st-rv5-6483a-97bf63"}], "id": "acffa2st-rv5-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Seven principles: accruals, going concern, money measurement, business entity, consistency, historical cost, materiality", "id": "acffa2st-rv5-80e78-e63691"}, {"t": "pt", "text": "Accruals: match to the period", "id": "acffa2st-rv5-80e78-150b56"}, {"t": "pt", "text": "Going concern: continue for the foreseeable future", "id": "acffa2st-rv5-80e78-6585e0"}, {"t": "pt", "text": "Business entity: separate from the owner", "id": "acffa2st-rv5-80e78-59c4f4"}, {"t": "pt", "text": "Consistency: same treatment over time", "id": "acffa2st-rv5-80e78-f800d4"}, {"t": "pt", "text": "Materiality: would it influence decisions?", "id": "acffa2st-rv5-80e78-3ee3e7"}, {"t": "pt", "text": "IFRS Standards published by the IASB", "id": "acffa2st-rv5-80e78-91d0f6"}, {"t": "pt", "text": "Fundamental: relevance and faithful representation", "id": "acffa2st-rv5-80e78-c5fb5c"}, {"t": "pt", "text": "Enhancing: comparability, verifiability, timeliness, understandability", "id": "acffa2st-rv5-80e78-cd1577"}, {"t": "pt", "text": "Principles ≠ qualitative characteristics", "id": "acffa2st-rv5-80e78-5f8de4"}, {"t": "pt", "text": "Standards are not law in themselves", "id": "acffa2st-rv5-80e78-4f7d4a"}, {"t": "pt", "text": "Money measurement: only monetary items recorded", "id": "acffa2st-rv5-80e78-aa9094"}], "id": "acffa2st-rv5-80e78"}], "source": "BPP FA2 Kit section 5: 'Did you know?' p32; questions 5.1-5.11 pp33-34; answers p124", "summary": "Seven accounting principles, IFRS Standards and the IASB, and the fundamental and enhancing qualitative characteristics of financial information.", "id": "acffa2st-rv5", "updated": "2026-11-13"}, {"num": "6", "title": "Control Accounts and the Correction of Errors", "pages": [35, 46], "syllabus": "B2", "status": "published", "branches": [{"kind": "def", "title": "Control accounts", "page": [36, 36], "items": [{"t": "def", "k": 1, "term": "Receivables control account", "text": "An account recording transactions with all customers in total - its balance is the total amount due to the business from its customers", "id": "acffa2st-rv6-8950d-9e333d"}, {"t": "def", "k": 1, "term": "Payables control account", "text": "Records transactions with all suppliers in total - its balance is the total owed to suppliers", "id": "acffa2st-rv6-8950d-4c02e2"}, {"t": "pt", "k": 1, "text": "The trial balance includes the balances on control accounts but NOT the balances on the personal accounts in the receivables and payables ledgers", "id": "acffa2st-rv6-8950d-342606"}], "id": "acffa2st-rv6-8950d"}, {"kind": "concept", "title": "Four reasons for control accounts", "page": [36, 36], "items": [{"t": "pt", "k": 1, "text": "A check on the accuracy of entries made in the personal accounts", "id": "acffa2st-rv6-61cc4-10bde0"}, {"t": "pt", "k": 1, "text": "Help locate errors (postings made daily, weekly or monthly)", "id": "acffa2st-rv6-61cc4-7dc2be"}, {"t": "pt", "k": 1, "text": "An internal check where clerical duties are separated", "id": "acffa2st-rv6-61cc4-533491"}, {"t": "pt", "k": 1, "text": "A total balance extracted more quickly than many individual balances", "id": "acffa2st-rv6-61cc4-a352f0"}], "id": "acffa2st-rv6-61cc4"}, {"kind": "process", "title": "Correcting errors", "page": [36, 46], "items": [{"t": "pt", "k": 1, "text": "If correcting an error involves a double entry in the ledger accounts, use a JOURNAL entry", "id": "acffa2st-rv6-8bd31-d5f870"}, {"t": "pt", "k": 1, "text": "If the error broke the rule of double entry, correct it with a journal AND the SUSPENSE account", "id": "acffa2st-rv6-8bd31-cbba8e"}, {"t": "pt", "text": "Suspense accounts are also opened when it is not known immediately where to post an amount", "id": "acffa2st-rv6-8bd31-dcd0d4"}, {"t": "pt", "k": 1, "text": "Control account reconciliation: compare the control account balance with the total of the list of personal balances; correct each for the errors that affect it", "id": "acffa2st-rv6-8bd31-30801b"}, {"t": "pt", "text": "Errors in day book totals affect the control account; errors in posting to personal accounts affect the list of balances", "id": "acffa2st-rv6-8bd31-11dd77"}, {"t": "eg", "text": "Jan's TB debit total exceeded credits - a suspense account was opened for the difference", "id": "acffa2st-rv6-8bd31-80e08d"}], "id": "acffa2st-rv6-8bd31"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "This is the largest question section in the kit (39 questions) - reconciliations and suspense corrections are heavily tested", "id": "acffa2st-rv6-308d8-e50921"}, {"t": "exam", "text": "Decide for each error: control account, list of balances, or suspense", "id": "acffa2st-rv6-308d8-28bea1"}], "id": "acffa2st-rv6-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Including personal ledger balances in the trial balance alongside the control account", "id": "acffa2st-rv6-6483a-05b087"}, {"t": "x", "text": "Correcting a list-of-balances error in the control account", "id": "acffa2st-rv6-6483a-cbcc4a"}, {"t": "x", "text": "Clearing a suspense account with an error that did not affect the TB balance", "id": "acffa2st-rv6-6483a-81b984"}, {"t": "x", "text": "Getting the debit/credit wrong in correcting journals", "id": "acffa2st-rv6-6483a-c376bb"}], "id": "acffa2st-rv6-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Receivables control balance = total owed by customers", "id": "acffa2st-rv6-80e78-4e4ac5"}, {"t": "pt", "text": "Payables control balance = total owed to suppliers", "id": "acffa2st-rv6-80e78-e6c133"}, {"t": "pt", "text": "TB includes control accounts, not personal accounts", "id": "acffa2st-rv6-80e78-6e9efd"}, {"t": "pt", "text": "Reasons: accuracy check, locate errors, internal check, quick total", "id": "acffa2st-rv6-80e78-ff319f"}, {"t": "pt", "text": "Correct two-sided errors with a journal", "id": "acffa2st-rv6-80e78-ecf221"}, {"t": "pt", "text": "Correct double-entry breaks with journal + suspense", "id": "acffa2st-rv6-80e78-d520d2"}, {"t": "pt", "text": "Suspense also used when the posting is unknown", "id": "acffa2st-rv6-80e78-78f8d7"}, {"t": "pt", "text": "Reconcile control account to list of balances", "id": "acffa2st-rv6-80e78-7f4542"}, {"t": "pt", "text": "Day book total errors affect the control account", "id": "acffa2st-rv6-80e78-a46606"}, {"t": "pt", "text": "Posting errors to personal accounts affect the list", "id": "acffa2st-rv6-80e78-6fefa9"}, {"t": "pt", "text": "Clear suspense before the final accounts", "id": "acffa2st-rv6-80e78-2a5d6f"}, {"t": "pt", "text": "Journals need a narrative", "id": "acffa2st-rv6-80e78-fc8600"}], "id": "acffa2st-rv6-80e78"}], "source": "BPP FA2 Kit section 6: 'Did you know?' p36; questions 6.1-6.39 pp37-46; answers pp124-127", "summary": "Receivables and payables control accounts, why control accounts are kept, control account reconciliations, correcting errors with journals, and suspense accounts.", "id": "acffa2st-rv6", "updated": "2026-11-13"}, {"num": "7", "title": "Accruals and Prepayments", "pages": [47, 51], "syllabus": "B3", "status": "published", "branches": [{"kind": "def", "title": "Accruals and prepayments", "page": [48, 48], "items": [{"t": "def", "k": 1, "term": "Accruals", "text": "Expenses charged against the profits of a particular accounting period even though they have not yet been paid", "id": "acffa2st-rv7-9a741-89a047"}, {"t": "def", "k": 1, "term": "Prepayments", "text": "Payments made in one accounting period that should not be charged against profit until a later period, because they relate to that later period", "id": "acffa2st-rv7-9a741-279e56"}, {"t": "pt", "k": 1, "text": "Accruals are LIABILITIES and prepayments are ASSETS in the statement of financial position", "id": "acffa2st-rv7-9a741-a286ca"}], "id": "acffa2st-rv7-9a741"}, {"kind": "formula", "title": "Calculating the expense charge", "page": [48, 51], "items": [{"t": "f", "k": 1, "term": "Expense for the year", "text": "Cash paid - Opening accrual + Closing accrual + Opening prepayment - Closing prepayment", "vars": "time-apportion bills that span the year end", "eg": "Norah paid $1,765 for electricity; adjust for amounts owing at each year end", "id": "acffa2st-rv7-e9a7c-1d298a"}, {"t": "pt", "text": "Accrual entry: Dr Expense, Cr Accruals; prepayment entry: Dr Prepayments, Cr Expense", "id": "acffa2st-rv7-e9a7c-a5e48d"}, {"t": "pt", "k": 1, "text": "An accrual INCREASES the expense (reduces profit); a prepayment REDUCES the expense (increases profit)", "id": "acffa2st-rv7-e9a7c-ea441f"}, {"t": "pt", "text": "Accrued income (earned, not received) is an asset; income received in advance is a liability", "id": "acffa2st-rv7-e9a7c-625d97"}], "id": "acffa2st-rv7-e9a7c"}, {"kind": "compare", "title": "Effect summary", "page": [48, 48], "items": [{"t": "table", "rows": [["Item", "SOFP", "Effect on profit"], ["Accrued expense", "Current liability", "Decreases profit"], ["Prepaid expense", "Current asset", "Increases profit"], ["Accrued income", "Current asset", "Increases profit"], ["Income in advance", "Current liability", "Decreases profit"]], "id": "acffa2st-rv7-4f482-7be97c"}], "id": "acffa2st-rv7-4f482"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Typical MCQ: given payments and bills spanning the year end, find the charge to profit or loss or the year-end accrual/prepayment", "id": "acffa2st-rv7-308d8-a02609"}, {"t": "exam", "text": "Count the months carefully when time-apportioning", "id": "acffa2st-rv7-308d8-e7d94e"}], "id": "acffa2st-rv7-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing accruals with prepayments", "id": "acffa2st-rv7-6483a-84ebf3"}, {"t": "x", "text": "Showing an accrual as an asset", "id": "acffa2st-rv7-6483a-ac186e"}, {"t": "x", "text": "Ignoring opening accruals/prepayments when calculating the charge", "id": "acffa2st-rv7-6483a-b90428"}, {"t": "x", "text": "Time-apportioning with the wrong number of months", "id": "acffa2st-rv7-6483a-230a59"}], "id": "acffa2st-rv7-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Accrual: expense incurred, not yet paid", "id": "acffa2st-rv7-80e78-e6f8e7"}, {"t": "pt", "text": "Prepayment: paid in advance for a later period", "id": "acffa2st-rv7-80e78-32593c"}, {"t": "pt", "text": "Accruals = liabilities", "id": "acffa2st-rv7-80e78-b7af95"}, {"t": "pt", "text": "Prepayments = assets", "id": "acffa2st-rv7-80e78-01e05d"}, {"t": "pt", "text": "Accrual: Dr expense, Cr accruals", "id": "acffa2st-rv7-80e78-167a0c"}, {"t": "pt", "text": "Prepayment: Dr prepayments, Cr expense", "id": "acffa2st-rv7-80e78-e9afe3"}, {"t": "pt", "text": "Accruals reduce profit", "id": "acffa2st-rv7-80e78-763613"}, {"t": "pt", "text": "Prepayments increase profit", "id": "acffa2st-rv7-80e78-738da6"}, {"t": "pt", "text": "Charge = cash - opening accrual + closing accrual + opening prepayment - closing prepayment", "id": "acffa2st-rv7-80e78-20b20c"}, {"t": "pt", "text": "Accrued income = asset", "id": "acffa2st-rv7-80e78-924496"}, {"t": "pt", "text": "Income in advance = liability", "id": "acffa2st-rv7-80e78-0586e9"}, {"t": "pt", "text": "Time-apportion by months", "id": "acffa2st-rv7-80e78-e2b7b9"}], "id": "acffa2st-rv7-80e78"}], "source": "BPP FA2 Kit section 7: 'Did you know?' p48; questions 7.1-7.16 pp49-51; answers pp127-128", "summary": "Accruals and prepayments, their effect on profit and their presentation, and calculating expense charges from cash paid.", "id": "acffa2st-rv7", "updated": "2026-11-13"}, {"num": "8", "title": "Receivables and Irrecoverable Debts", "pages": [48, 54], "syllabus": "B4", "status": "published", "branches": [{"kind": "def", "title": "Irrecoverable debts", "page": [48, 48], "items": [{"t": "def", "k": 1, "term": "Irrecoverable debt", "text": "A specific debt which is not expected to be repaid - written off: Dr Irrecoverable debts expense, Cr Receivables", "id": "acffa2st-rv8-0030f-abf278"}, {"t": "pt", "k": 1, "text": "Debt recovered after being written off", "kids": [{"t": "pt", "text": "Paid in the SAME period as written off: reverse the write-off entry", "id": "acffa2st-rv8-0030f-9ea270"}, {"t": "pt", "text": "Paid AFTER the end of the period it was written off in: treat as sundry income in the statement of profit or loss", "id": "acffa2st-rv8-0030f-5f69bc"}], "id": "acffa2st-rv8-0030f-a162eb"}], "id": "acffa2st-rv8-0030f"}, {"kind": "formula", "title": "Allowance for receivables", "page": [48, 54], "items": [{"t": "def", "k": 1, "term": "Allowance for receivables", "text": "An estimate of the debts which are not expected to be repaid - often expressed as a percentage of the receivables balance", "id": "acffa2st-rv8-cce1c-963cdb"}, {"t": "pt", "k": 1, "text": "Creating/increasing: Dr Irrecoverable debts (receivables) expense, Cr Allowance for receivables; decreasing: the reverse", "id": "acffa2st-rv8-cce1c-e83c44"}, {"t": "f", "k": 1, "term": "Allowance movement", "text": "Required closing allowance - Opening allowance", "vars": "only the movement goes to profit or loss", "eg": "Colin: allowance on $56,800 at the required % compared with last year's", "id": "acffa2st-rv8-cce1c-bb69e8"}, {"t": "pt", "text": "Calculate the allowance on receivables AFTER writing off irrecoverable debts", "id": "acffa2st-rv8-cce1c-4c704d"}, {"t": "pt", "k": 1, "text": "Trade receivables in the SOFP are shown NET of the allowance for receivables", "id": "acffa2st-rv8-cce1c-006470"}, {"t": "def", "term": "Provision", "text": "A liability of uncertain timing or amount", "id": "acffa2st-rv8-cce1c-786ca4"}], "id": "acffa2st-rv8-cce1c"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Typical MCQ: write-offs, a change in the allowance and a recovery combine into one irrecoverable debts expense figure", "id": "acffa2st-rv8-308d8-3606ef"}, {"t": "exam", "text": "Check whether a recovery relates to the current or a previous period", "id": "acffa2st-rv8-308d8-c1a5bd"}], "id": "acffa2st-rv8-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing the double entry when creating or adjusting the allowance", "id": "acffa2st-rv8-6483a-5ca5b7"}, {"t": "x", "text": "Charging the full closing allowance instead of the movement", "id": "acffa2st-rv8-6483a-23bd75"}, {"t": "x", "text": "Calculating the allowance before deducting debts written off", "id": "acffa2st-rv8-6483a-ed6690"}, {"t": "x", "text": "Showing receivables gross of the allowance in the SOFP", "id": "acffa2st-rv8-6483a-94194d"}], "id": "acffa2st-rv8-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Irrecoverable debt: not expected to be repaid", "id": "acffa2st-rv8-80e78-63b5f9"}, {"t": "pt", "text": "Write-off: Dr irrecoverable debts expense, Cr receivables", "id": "acffa2st-rv8-80e78-f44c4d"}, {"t": "pt", "text": "Recovered same period: reverse the write-off", "id": "acffa2st-rv8-80e78-748781"}, {"t": "pt", "text": "Recovered later period: sundry income", "id": "acffa2st-rv8-80e78-5ad4e9"}, {"t": "pt", "text": "Allowance = estimate of debts not to be repaid", "id": "acffa2st-rv8-80e78-637e79"}, {"t": "pt", "text": "Often a % of receivables", "id": "acffa2st-rv8-80e78-a7634d"}, {"t": "pt", "text": "Increase: Dr expense, Cr allowance", "id": "acffa2st-rv8-80e78-b366cd"}, {"t": "pt", "text": "Decrease: Dr allowance, Cr expense", "id": "acffa2st-rv8-80e78-6f77ed"}, {"t": "pt", "text": "Only the movement hits P/L", "id": "acffa2st-rv8-80e78-ce0564"}, {"t": "pt", "text": "Write off first, then calculate the allowance", "id": "acffa2st-rv8-80e78-0fa136"}, {"t": "pt", "text": "Receivables shown net of allowance", "id": "acffa2st-rv8-80e78-1a6a05"}, {"t": "pt", "text": "Provision = liability of uncertain timing or amount", "id": "acffa2st-rv8-80e78-0e7ab4"}], "id": "acffa2st-rv8-80e78"}], "source": "BPP FA2 Kit section 8: 'Did you know?' p48; questions 8.1-8.13 pp52-54; answers pp128-129", "summary": "Irrecoverable debts and their write-off, debts recovered, the allowance for receivables, its double entry and presentation, and provisions.", "id": "acffa2st-rv8", "updated": "2026-11-13"}, {"num": "9", "title": "Cost of Goods Sold and the Treatment of Inventories", "pages": [55, 60], "syllabus": "B5", "status": "published", "branches": [{"kind": "formula", "title": "Cost of goods sold", "page": [56, 56], "items": [{"t": "f", "k": 1, "term": "Cost of goods sold", "text": "Opening inventory + Purchases - Closing inventory", "vars": "carriage inwards is added to purchases", "id": "acffa2st-rv9-90d74-464021"}, {"t": "def", "k": 1, "term": "Carriage", "text": "The cost of transporting purchased goods from the supplier to the business's premises (carriage inwards - part of cost of sales); carriage outwards (to customers) is a distribution expense", "id": "acffa2st-rv9-90d74-47e487"}, {"t": "pt", "text": "Goods taken by the owner for own use: Dr Drawings, Cr Purchases (at cost)", "id": "acffa2st-rv9-90d74-6b95a5"}], "id": "acffa2st-rv9-90d74"}, {"kind": "rule", "title": "Inventory valuation (IAS 2)", "page": [56, 59], "items": [{"t": "pt", "k": 1, "text": "Inventories are valued at the LOWER of cost and net realisable value (IAS 2 Inventories)", "id": "acffa2st-rv9-4bdb2-a8364e"}, {"t": "def", "k": 1, "term": "Net realisable value", "text": "The selling price less any costs still to be incurred in getting the inventory ready to sell and selling it", "id": "acffa2st-rv9-4bdb2-a034ae"}, {"t": "pt", "k": 1, "text": "Year-end quantity established by a physical inventory count, or by continuous inventory checks", "id": "acffa2st-rv9-4bdb2-88c685"}, {"t": "pt", "text": "Compare cost and NRV item by item", "id": "acffa2st-rv9-4bdb2-99920f"}, {"t": "eg", "text": "Kieron's antique clock cost more than it can now be sold for after repair costs - value at NRV", "id": "acffa2st-rv9-4bdb2-f327a6"}], "id": "acffa2st-rv9-4bdb2"}, {"kind": "compare", "title": "Pricing techniques", "page": [56, 59], "items": [{"t": "table", "rows": [["Technique", "Basis"], ["FIFO", "Oldest items issued first; closing inventory at latest prices"], ["Continuous weighted average", "New average cost calculated after each purchase"], ["Periodic weighted average", "One average cost for the whole period"]], "id": "acffa2st-rv9-6fe85-d8a37f"}, {"t": "pt", "text": "In rising prices FIFO gives the highest closing inventory and profit", "id": "acffa2st-rv9-6fe85-027e0c"}], "id": "acffa2st-rv9-6fe85"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Typical MCQ: value closing inventory at the lower of cost and NRV for several items, or calculate FIFO/average closing inventory", "id": "acffa2st-rv9-308d8-b4b761"}, {"t": "exam", "text": "Remember to deduct costs to complete and sell when finding NRV", "id": "acffa2st-rv9-308d8-cd4b49"}], "id": "acffa2st-rv9-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Thinking NRV is merely the selling price - deduct costs still to be incurred to complete and sell", "id": "acffa2st-rv9-6483a-be69fb"}, {"t": "x", "text": "Comparing total cost with total NRV instead of item by item", "id": "acffa2st-rv9-6483a-5dccad"}, {"t": "x", "text": "Treating carriage outwards as part of cost of sales", "id": "acffa2st-rv9-6483a-3f0f87"}, {"t": "x", "text": "Adding closing inventory in the cost of goods sold formula", "id": "acffa2st-rv9-6483a-2affac"}], "id": "acffa2st-rv9-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "COGS = opening inventory + purchases - closing inventory", "id": "acffa2st-rv9-80e78-75c367"}, {"t": "pt", "text": "Carriage inwards: part of cost of sales", "id": "acffa2st-rv9-80e78-1c0e7f"}, {"t": "pt", "text": "Carriage outwards: distribution expense", "id": "acffa2st-rv9-80e78-66e838"}, {"t": "pt", "text": "Lower of cost and NRV (IAS 2)", "id": "acffa2st-rv9-80e78-5fab1b"}, {"t": "pt", "text": "NRV = selling price - costs to complete and sell", "id": "acffa2st-rv9-80e78-1a592c"}, {"t": "pt", "text": "Compare item by item", "id": "acffa2st-rv9-80e78-f22e61"}, {"t": "pt", "text": "Count inventory at the year end or continuously", "id": "acffa2st-rv9-80e78-e0645a"}, {"t": "pt", "text": "FIFO: oldest first", "id": "acffa2st-rv9-80e78-6c2db6"}, {"t": "pt", "text": "Continuous average: after each purchase", "id": "acffa2st-rv9-80e78-e56f20"}, {"t": "pt", "text": "Periodic average: one for the period", "id": "acffa2st-rv9-80e78-e4c146"}, {"t": "pt", "text": "Rising prices: FIFO highest profit", "id": "acffa2st-rv9-80e78-93c98b"}, {"t": "pt", "text": "Owner's goods: Dr drawings, Cr purchases", "id": "acffa2st-rv9-80e78-193cf5"}], "id": "acffa2st-rv9-80e78"}], "source": "BPP FA2 Kit section 9: 'Did you know?' p56; questions 9.1-9.13 pp57-59; answers pp129-131", "summary": "Cost of goods sold, carriage, inventory counting, IAS 2 valuation at the lower of cost and net realisable value, and FIFO and weighted average pricing.", "id": "acffa2st-rv9", "updated": "2026-11-13"}, {"num": "10", "title": "Non-Current Assets and Depreciation", "pages": [61, 66], "syllabus": "B6", "status": "published", "branches": [{"kind": "def", "title": "Depreciation", "page": [62, 62], "items": [{"t": "def", "k": 1, "term": "Depreciation", "text": "A measure of the wearing out, consumption or other reduction in the useful economic life of a non-current asset through use, time or obsolescence", "id": "acffa2st-rv10-a6708-5e8750"}, {"t": "pt", "k": 1, "text": "Usually calculated by the straight-line method or the reducing balance method", "id": "acffa2st-rv10-a6708-b6458a"}, {"t": "pt", "k": 1, "text": "Depreciation charges should be spread fairly over the asset's life, matched to the accounting periods expected to benefit from its use", "id": "acffa2st-rv10-a6708-7711e3"}, {"t": "pt", "text": "The depreciation charge goes to profit or loss; accumulated depreciation is deducted from the asset's cost in the SOFP", "id": "acffa2st-rv10-a6708-a6c139"}], "id": "acffa2st-rv10-a6708"}, {"kind": "formula", "title": "Methods and disposals", "page": [62, 65], "items": [{"t": "f", "k": 1, "term": "Straight-line", "text": "(Cost - Residual value) / Useful life", "vars": "applied to COST each year", "id": "acffa2st-rv10-b2e72-131eb2"}, {"t": "f", "k": 1, "term": "Reducing balance", "text": "% x Carrying amount (cost - accumulated depreciation)", "vars": "the charge falls each year", "id": "acffa2st-rv10-b2e72-5d42f2"}, {"t": "f", "k": 1, "term": "Profit or loss on disposal", "text": "Sale proceeds - Carrying amount at the date of sale", "vars": "carrying amount = cost - accumulated depreciation", "eg": "Tina sold equipment: compare proceeds with its carrying amount", "id": "acffa2st-rv10-b2e72-3ac32c"}, {"t": "pt", "text": "Disposal entries: remove cost and accumulated depreciation to a disposal account, credit proceeds; the balance is the profit or loss", "id": "acffa2st-rv10-b2e72-9d7d9d"}], "id": "acffa2st-rv10-b2e72"}, {"kind": "concept", "title": "Non-current assets register", "page": [62, 62], "items": [{"t": "def", "k": 1, "term": "Non-current assets register", "text": "A listing of all non-current assets owned by the organisation, broken down perhaps by department, location or asset type", "id": "acffa2st-rv10-99b8c-6ae1f0"}, {"t": "pt", "text": "Used to check physical existence, reconcile with the general ledger and calculate depreciation", "id": "acffa2st-rv10-99b8c-5326a0"}], "id": "acffa2st-rv10-99b8c"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Typical MCQs: depreciation charge for a year with acquisitions and disposals; profit or loss on disposal; reducing balance carrying amount after several years", "id": "acffa2st-rv10-308d8-1c1a0b"}, {"t": "exam", "text": "Read whether a full year's charge is made in the year of purchase or a pro rata charge", "id": "acffa2st-rv10-308d8-bd5526"}], "id": "acffa2st-rv10-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Applying the straight-line method to carrying amount rather than cost", "id": "acffa2st-rv10-6483a-5d7f19"}, {"t": "x", "text": "Calculating profit or loss on disposal as proceeds minus COST instead of carrying amount", "id": "acffa2st-rv10-6483a-f93829"}, {"t": "x", "text": "Applying the reducing balance % to cost every year", "id": "acffa2st-rv10-6483a-7e1651"}, {"t": "x", "text": "Forgetting accumulated depreciation on disposal", "id": "acffa2st-rv10-6483a-9422b9"}], "id": "acffa2st-rv10-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Depreciation = reduction in useful life through use, time, obsolescence", "id": "acffa2st-rv10-80e78-477bac"}, {"t": "pt", "text": "Straight-line = (cost - residual) / life", "id": "acffa2st-rv10-80e78-931ef5"}, {"t": "pt", "text": "Reducing balance = % x carrying amount", "id": "acffa2st-rv10-80e78-44744e"}, {"t": "pt", "text": "Spread the charge over periods benefiting", "id": "acffa2st-rv10-80e78-7b61d5"}, {"t": "pt", "text": "Charge to P/L; accumulated depreciation deducted in SOFP", "id": "acffa2st-rv10-80e78-1831ac"}, {"t": "pt", "text": "Carrying amount = cost - accumulated depreciation", "id": "acffa2st-rv10-80e78-853b25"}, {"t": "pt", "text": "Disposal profit = proceeds - carrying amount", "id": "acffa2st-rv10-80e78-b7a16f"}, {"t": "pt", "text": "Disposal account removes cost and depreciation", "id": "acffa2st-rv10-80e78-a6b047"}, {"t": "pt", "text": "Register lists all non-current assets", "id": "acffa2st-rv10-80e78-77ab76"}, {"t": "pt", "text": "Register supports existence checks and reconciliation", "id": "acffa2st-rv10-80e78-20ef52"}, {"t": "pt", "text": "Straight-line on cost; reducing balance on carrying amount", "id": "acffa2st-rv10-80e78-ee0783"}, {"t": "pt", "text": "Check full-year vs pro rata policy", "id": "acffa2st-rv10-80e78-a26d15"}], "id": "acffa2st-rv10-80e78"}], "source": "BPP FA2 Kit section 10: 'Did you know?' p62; questions 10.1-10.20 pp63-65; answers pp131-133", "summary": "Depreciation and its methods, spreading the charge over the asset's life, accumulated depreciation, profit or loss on disposal and the non-current assets register.", "id": "acffa2st-rv10", "updated": "2026-11-13"}, {"num": "11", "title": "The Accounts of Sole Traders", "pages": [67, 74], "syllabus": "B7", "status": "published", "branches": [{"kind": "process", "title": "Year-end closing", "page": [68, 68], "items": [{"t": "pt", "k": 1, "text": "At the end of the financial year, the balances on income and expense accounts are transferred to the trading, income and expense account (statement of profit or loss)", "id": "acffa2st-rv11-501dd-f7ac70"}, {"t": "pt", "k": 1, "text": "Any balance on drawings is debited to the owner's capital in the statement of financial position", "id": "acffa2st-rv11-501dd-33b43f"}, {"t": "pt", "k": 1, "text": "Balances on asset, liability and capital accounts are carried forward to the next accounting period", "id": "acffa2st-rv11-501dd-220b00"}, {"t": "pt", "text": "Profit for the year is credited to capital", "id": "acffa2st-rv11-501dd-6799d4"}], "id": "acffa2st-rv11-501dd"}, {"kind": "formula", "title": "Sole trader statements", "page": [68, 73], "items": [{"t": "f", "term": "Gross profit", "text": "Sales - Cost of goods sold", "vars": "COGS = opening inventory + purchases - closing inventory", "id": "acffa2st-rv11-7111a-1e308a"}, {"t": "f", "term": "Net profit", "text": "Gross profit + Other income - Expenses", "id": "acffa2st-rv11-7111a-99ec07"}, {"t": "f", "k": 1, "term": "Closing capital", "text": "Opening capital + Capital introduced + Net profit - Drawings", "vars": "shown in the SOFP", "id": "acffa2st-rv11-7111a-7da476"}, {"t": "pt", "text": "Adjustments: depreciation, accruals and prepayments (eg Keith's accrued expenses $4,176), irrecoverable debts and allowance, closing inventory", "id": "acffa2st-rv11-7111a-8fba24"}, {"t": "pt", "k": 1, "text": "Goods taken for own use: Dr Drawings, Cr Purchases (cost of sales)", "id": "acffa2st-rv11-7111a-20d3eb"}, {"t": "eg", "text": "Bridget's business development loan: interest is an expense; the loan is a liability (current or non-current by repayment date)", "id": "acffa2st-rv11-7111a-40d183"}, {"t": "eg", "text": "Kieron's antique clock: inventory at the lower of cost and NRV", "id": "acffa2st-rv11-7111a-2a103f"}], "id": "acffa2st-rv11-7111a"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Typical MCQs: net profit after a list of adjustments, closing capital, or where an item appears in the statements", "id": "acffa2st-rv11-308d8-e25d7d"}, {"t": "exam", "text": "Drawings never appear in the statement of profit or loss", "id": "acffa2st-rv11-308d8-aa3e52"}], "id": "acffa2st-rv11-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing statement of financial position and statement of profit or loss items", "id": "acffa2st-rv11-6483a-6b26e8"}, {"t": "x", "text": "Not dealing correctly with goods taken for own use by the proprietor", "id": "acffa2st-rv11-6483a-240d0d"}, {"t": "x", "text": "Showing drawings as an expense", "id": "acffa2st-rv11-6483a-572c49"}, {"t": "x", "text": "Forgetting to add net profit to capital", "id": "acffa2st-rv11-6483a-91b664"}], "id": "acffa2st-rv11-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Income and expense balances transfer to the P/L", "id": "acffa2st-rv11-80e78-16c95a"}, {"t": "pt", "text": "Drawings debited to capital", "id": "acffa2st-rv11-80e78-070e2e"}, {"t": "pt", "text": "Asset, liability, capital balances carried forward", "id": "acffa2st-rv11-80e78-0445a8"}, {"t": "pt", "text": "Gross profit = sales - COGS", "id": "acffa2st-rv11-80e78-0dd1d4"}, {"t": "pt", "text": "Net profit = GP + other income - expenses", "id": "acffa2st-rv11-80e78-2424ef"}, {"t": "pt", "text": "Closing capital = opening + introduced + profit - drawings", "id": "acffa2st-rv11-80e78-d89ccc"}, {"t": "pt", "text": "Own-use goods: Dr drawings, Cr purchases", "id": "acffa2st-rv11-80e78-2b0ebc"}, {"t": "pt", "text": "Make all year-end adjustments before drafting", "id": "acffa2st-rv11-80e78-dea42b"}, {"t": "pt", "text": "Loan interest is an expense", "id": "acffa2st-rv11-80e78-0a0055"}, {"t": "pt", "text": "Drawings are not an expense", "id": "acffa2st-rv11-80e78-fbd5ea"}, {"t": "pt", "text": "Profit increases capital", "id": "acffa2st-rv11-80e78-fbbfa2"}, {"t": "pt", "text": "Inventory at lower of cost and NRV", "id": "acffa2st-rv11-80e78-ad9f95"}], "id": "acffa2st-rv11-80e78"}], "source": "BPP FA2 Kit section 11: 'Did you know?' p68; questions 11.1-11.25 pp69-73; answers pp133-134", "summary": "Closing off income and expense accounts at the year end, drawings and capital, carrying forward SOFP balances, and preparing a sole trader's statement of profit or loss and statement of financial position with adjustments.", "id": "acffa2st-rv11", "updated": "2026-11-13"}, {"num": "12", "title": "The Extended Trial Balance", "pages": [75, 82], "syllabus": "B8", "status": "published", "branches": [{"kind": "concept", "title": "The extended trial balance", "page": [76, 76], "items": [{"t": "def", "k": 1, "term": "Extended trial balance", "text": "A worksheet used to keep track of adjustments between the trial balance and the final accounts", "id": "acffa2st-rv12-ec21b-fa82bd"}, {"t": "pt", "k": 1, "text": "Columns: the ledger balances (trial balance), adjustments, accruals and prepayments, then two pairs of columns showing whether figures go to the statement of profit or loss or the statement of financial position", "id": "acffa2st-rv12-ec21b-f3bfcb"}, {"t": "pt", "text": "The ETB can be computerised (extracting the ledger balances automatically) or prepared on a spreadsheet", "id": "acffa2st-rv12-ec21b-b59224"}, {"t": "pt", "k": 1, "text": "The ETB produces balances that can be taken directly to the statement of financial position and statement of profit or loss", "id": "acffa2st-rv12-ec21b-a9808b"}], "id": "acffa2st-rv12-ec21b"}, {"kind": "process", "title": "Late adjustments", "page": [76, 79], "items": [{"t": "pt", "text": "Normally an error is entered in the journal and then the correcting entries are posted to the ledger accounts", "id": "acffa2st-rv12-d460c-46e224"}, {"t": "pt", "k": 1, "text": "Errors discovered at the last moment: enter the corrections in the journal and show their effect in the ETB 'other adjustments' column", "id": "acffa2st-rv12-d460c-77c1af"}, {"t": "pt", "text": "Each row is extended across: TB + adjustments -> P/L columns (income and expenses) or SOFP columns (assets, liabilities, capital, drawings)", "id": "acffa2st-rv12-d460c-29a095"}, {"t": "eg", "text": "Closing inventory appears in BOTH the P/L credit column (reducing cost of sales) and the SOFP debit column (asset)", "id": "acffa2st-rv12-d460c-9969eb"}], "id": "acffa2st-rv12-d460c"}, {"kind": "formula", "title": "Deriving profit from the ETB", "page": [76, 80], "items": [{"t": "f", "k": 1, "term": "Profit from ETB", "text": "P/L CREDIT column total - P/L DEBIT column total", "vars": "a positive result is a profit; the balancing figure also appears in the SOFP columns", "id": "acffa2st-rv12-5f2e7-dd021f"}, {"t": "pt", "text": "The profit figure balances the SOFP columns (credited to capital)", "id": "acffa2st-rv12-5f2e7-6e5fb0"}], "id": "acffa2st-rv12-5f2e7"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Typical MCQ: into which ETB columns (P/L debit/credit, SOFP debit/credit) does an item go?", "id": "acffa2st-rv12-308d8-e28e4d"}, {"t": "exam", "text": "Profit = credit column minus debit column in the P/L section", "id": "acffa2st-rv12-308d8-63289e"}], "id": "acffa2st-rv12-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Subtracting the credit column from the debit column to derive profit - subtract DEBIT from CREDIT", "id": "acffa2st-rv12-6483a-6ada3e"}, {"t": "x", "text": "Confusing statement of profit or loss items with statement of financial position items", "id": "acffa2st-rv12-6483a-3c3336"}, {"t": "x", "text": "Putting closing inventory in only one place - it goes in both P/L and SOFP columns", "id": "acffa2st-rv12-6483a-335a6e"}, {"t": "x", "text": "Forgetting to record late corrections in the adjustments column", "id": "acffa2st-rv12-6483a-80ce4c"}], "id": "acffa2st-rv12-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "ETB = worksheet from TB to final accounts", "id": "acffa2st-rv12-80e78-72ddf2"}, {"t": "pt", "text": "Columns: TB, adjustments, accruals/prepayments, P/L, SOFP", "id": "acffa2st-rv12-80e78-9a8603"}, {"t": "pt", "text": "Can be computerised or on a spreadsheet", "id": "acffa2st-rv12-80e78-b6e69a"}, {"t": "pt", "text": "Late errors: journal + 'other adjustments' column", "id": "acffa2st-rv12-80e78-6e77a1"}, {"t": "pt", "text": "Income and expenses -> P/L columns", "id": "acffa2st-rv12-80e78-59f55d"}, {"t": "pt", "text": "Assets, liabilities, capital, drawings -> SOFP columns", "id": "acffa2st-rv12-80e78-a468a7"}, {"t": "pt", "text": "Closing inventory in P/L (credit) and SOFP (debit)", "id": "acffa2st-rv12-80e78-4bd36b"}, {"t": "pt", "text": "Profit = P/L credit total - P/L debit total", "id": "acffa2st-rv12-80e78-32b31f"}, {"t": "pt", "text": "Profit balances the SOFP columns", "id": "acffa2st-rv12-80e78-d6b1ea"}, {"t": "pt", "text": "Balances go straight to the final statements", "id": "acffa2st-rv12-80e78-c3a7e5"}, {"t": "pt", "text": "Drawings go to SOFP columns", "id": "acffa2st-rv12-80e78-d9523e"}, {"t": "pt", "text": "Accruals and prepayments adjust expense rows", "id": "acffa2st-rv12-80e78-b4f134"}], "id": "acffa2st-rv12-80e78"}], "source": "BPP FA2 Kit section 12: 'Did you know?' p76; questions 12.1-12.17 pp77-80; answers pp135-136", "summary": "The extended trial balance (ETB) worksheet: columns for the trial balance, adjustments, accruals and prepayments, statement of profit or loss and statement of financial position; late error corrections; computerised and spreadsheet ETBs; deriving profit.", "id": "acffa2st-rv12", "updated": "2026-11-13"}, {"num": "13", "title": "Incomplete Records", "pages": [83, 88], "syllabus": "C1", "status": "published", "branches": [{"kind": "process", "title": "Approach to incomplete records", "page": [84, 84], "items": [{"t": "pt", "k": 1, "text": "Prepare an opening STATEMENT OF AFFAIRS if no statement of financial position is given (opening capital = opening assets - liabilities)", "id": "acffa2st-rv13-1b900-f2895d"}, {"t": "pt", "k": 1, "text": "Write up or complete the bank account and the cash receipts and payments account - there will usually be a BALANCING figure, typically drawings, bankings or cash sales", "id": "acffa2st-rv13-1b900-b8ccea"}, {"t": "pt", "k": 1, "text": "Use mark-up or gross profit margin, or complete the receivables and payables control accounts, to establish sales and purchases", "id": "acffa2st-rv13-1b900-12b485"}, {"t": "pt", "k": 1, "text": "Use the accounting equation to derive the profit or loss for the year", "id": "acffa2st-rv13-1b900-fe6e97"}], "id": "acffa2st-rv13-1b900"}, {"kind": "formula", "title": "Key techniques", "page": [84, 87], "items": [{"t": "f", "term": "Statement of affairs", "text": "Capital = Assets - Liabilities", "vars": "at the opening date", "id": "acffa2st-rv13-34b38-f77c10"}, {"t": "f", "term": "Profit from net assets", "text": "Closing net assets - Opening net assets + Drawings - Capital introduced", "vars": "when only net assets are known", "id": "acffa2st-rv13-34b38-45938a"}, {"t": "f", "k": 1, "term": "Mark-up", "text": "Gross profit / Cost of sales", "vars": "based on COST", "eg": "25% mark-up: sales = cost x 1.25", "id": "acffa2st-rv13-34b38-08ded4"}, {"t": "f", "k": 1, "term": "Gross profit margin", "text": "Gross profit / Sales", "vars": "based on SALES", "eg": "20% margin: cost = sales x 0.80", "id": "acffa2st-rv13-34b38-a81c80"}, {"t": "pt", "text": "Receivables control: opening + credit sales - cash received - irrecoverable debts = closing -> find credit sales", "id": "acffa2st-rv13-34b38-4b0ddf"}, {"t": "pt", "text": "Payables control: opening + credit purchases - payments = closing -> find credit purchases", "id": "acffa2st-rv13-34b38-cc9938"}, {"t": "pt", "text": "Lost inventory = expected closing inventory (from the margin) - actual closing inventory", "id": "acffa2st-rv13-34b38-bb3449"}], "id": "acffa2st-rv13-34b38"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Typical MCQs: missing sales from a mark-up, drawings as a balancing figure in the cash account, or profit from changes in net assets", "id": "acffa2st-rv13-308d8-702eae"}, {"t": "exam", "text": "Read carefully whether the question gives a mark-up or a margin", "id": "acffa2st-rv13-308d8-c47dcf"}], "id": "acffa2st-rv13-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Not recognising that a question involves incomplete records", "id": "acffa2st-rv13-6483a-d90c01"}, {"t": "x", "text": "Confusing mark-up with gross profit margin", "id": "acffa2st-rv13-6483a-699bb2"}, {"t": "x", "text": "Forgetting cash sales or cash drawings when reconstructing the cash account", "id": "acffa2st-rv13-6483a-070095"}, {"t": "x", "text": "Leaving out capital introduced when deriving profit from net assets", "id": "acffa2st-rv13-6483a-0e7ebb"}], "id": "acffa2st-rv13-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Statement of affairs gives opening capital", "id": "acffa2st-rv13-80e78-218d8c"}, {"t": "pt", "text": "Capital = assets - liabilities", "id": "acffa2st-rv13-80e78-d061b2"}, {"t": "pt", "text": "Cash/bank accounts give balancing figures (drawings, bankings, cash sales)", "id": "acffa2st-rv13-80e78-dba5f7"}, {"t": "pt", "text": "Mark-up = GP / cost", "id": "acffa2st-rv13-80e78-af6579"}, {"t": "pt", "text": "Margin = GP / sales", "id": "acffa2st-rv13-80e78-56e418"}, {"t": "pt", "text": "25% mark-up = 20% margin", "id": "acffa2st-rv13-80e78-e7da49"}, {"t": "pt", "text": "Control accounts find credit sales and purchases", "id": "acffa2st-rv13-80e78-f0cb1e"}, {"t": "pt", "text": "Profit = Δ net assets + drawings - capital introduced", "id": "acffa2st-rv13-80e78-51e920"}, {"t": "pt", "text": "Lost inventory = expected - actual", "id": "acffa2st-rv13-80e78-7571fd"}, {"t": "pt", "text": "Opening + credit sales - receipts = closing receivables", "id": "acffa2st-rv13-80e78-e119dd"}, {"t": "pt", "text": "Opening + purchases - payments = closing payables", "id": "acffa2st-rv13-80e78-bdca50"}, {"t": "pt", "text": "Identify mark-up vs margin first", "id": "acffa2st-rv13-80e78-3f2960"}], "id": "acffa2st-rv13-80e78"}], "source": "BPP FA2 Kit section 13: 'Did you know?' p84; questions 13.1-13.14 pp85-87; answers pp136-137", "summary": "Techniques for incomplete records: opening statement of affairs, reconstructing cash and bank accounts, using mark-up and margin, control accounts for sales and purchases, and the accounting equation for profit.", "id": "acffa2st-rv13", "updated": "2026-11-13"}, {"num": "14", "title": "Partnerships", "pages": [89, 94], "syllabus": "C2", "status": "published", "branches": [{"kind": "compare", "title": "Capital vs current accounts", "page": [90, 90], "items": [{"t": "table", "rows": [["Account", "Records"], ["Capital account", "The fixed capital of each partner"], ["Current account", "Each partner's share of profits and losses (salary, interest on capital, profit share) less drawings"]], "id": "acffa2st-rv14-40abc-6b09c8"}, {"t": "pt", "k": 1, "text": "The partnership's liability to its owners is held in these two accounts for each partner", "id": "acffa2st-rv14-40abc-bb62fb"}], "id": "acffa2st-rv14-40abc"}, {"kind": "process", "title": "The appropriation account", "page": [90, 93], "items": [{"t": "pt", "k": 1, "text": "Partnership profit is divided among the partners in the APPROPRIATION ACCOUNT, which follows the statement of profit or loss", "id": "acffa2st-rv14-f4d08-00284b"}, {"t": "pt", "k": 1, "text": "Order: net profit -> partners' salaries -> interest on capital (- interest on drawings if charged) -> residual profit shared in the PROFIT-SHARING RATIO", "id": "acffa2st-rv14-f4d08-7888a3"}, {"t": "pt", "text": "Each partner's share is credited to their current account; drawings are debited to it", "id": "acffa2st-rv14-f4d08-a90b33"}, {"t": "eg", "text": "Amber and Kieran: one is entitled to a salary - deduct it before sharing the residual profit", "id": "acffa2st-rv14-f4d08-174967"}, {"t": "eg", "text": "Bruce and Larry share profits in an agreed ratio - not necessarily equally", "id": "acffa2st-rv14-f4d08-bbeaa4"}], "id": "acffa2st-rv14-f4d08"}, {"kind": "process", "title": "New partner and goodwill", "page": [90, 93], "items": [{"t": "pt", "k": 1, "text": "When a new partner joins, the funds they bring in are credited to their CAPITAL account", "id": "acffa2st-rv14-00524-d07cad"}, {"t": "pt", "k": 1, "text": "The new partner must pay for a share of the partnership's goodwill", "id": "acffa2st-rv14-00524-fb98ee"}, {"t": "pt", "k": 1, "text": "Goodwill: the partners may choose whether to keep it in the accounts; if not, create it in the OLD profit-sharing ratio (Cr old partners' capital) and eliminate it in the NEW ratio (Dr partners' capital, including the new partner)", "id": "acffa2st-rv14-00524-1a06e1"}, {"t": "pt", "text": "Net effect: old partners are credited for their share of goodwill paid for by the new partner", "id": "acffa2st-rv14-00524-b32954"}], "id": "acffa2st-rv14-00524"}, {"kind": "exam", "title": "Exam focus", "page": null, "items": [{"t": "exam", "text": "Typical MCQs: a partner's profit share after salaries and interest; current account closing balance; capital balances after goodwill adjustments", "id": "acffa2st-rv14-308d8-37c0bd"}, {"t": "exam", "text": "Interest on capital and salaries are APPROPRIATIONS of profit, not expenses", "id": "acffa2st-rv14-308d8-3b29da"}], "id": "acffa2st-rv14-308d8"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Splitting profits equally between partners rather than according to the profit-sharing agreement", "id": "acffa2st-rv14-6483a-1792ba"}, {"t": "x", "text": "Incorrectly accounting for goodwill when a new partner joins", "id": "acffa2st-rv14-6483a-d09125"}, {"t": "x", "text": "Treating partners' salaries or interest on capital as expenses in the statement of profit or loss", "id": "acffa2st-rv14-6483a-31df10"}, {"t": "x", "text": "Posting drawings to the capital account instead of the current account", "id": "acffa2st-rv14-6483a-c46385"}], "id": "acffa2st-rv14-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Capital account: fixed capital", "id": "acffa2st-rv14-80e78-b23915"}, {"t": "pt", "text": "Current account: share of profits less drawings", "id": "acffa2st-rv14-80e78-aa2211"}, {"t": "pt", "text": "Appropriation account follows the P/L", "id": "acffa2st-rv14-80e78-52259d"}, {"t": "pt", "text": "Salaries and interest on capital first", "id": "acffa2st-rv14-80e78-e11410"}, {"t": "pt", "text": "Residual profit in the profit-sharing ratio", "id": "acffa2st-rv14-80e78-a23dd3"}, {"t": "pt", "text": "Salaries and interest are appropriations, not expenses", "id": "acffa2st-rv14-80e78-95fffa"}, {"t": "pt", "text": "Drawings debited to current accounts", "id": "acffa2st-rv14-80e78-22a57e"}, {"t": "pt", "text": "New partner's funds credited to their capital account", "id": "acffa2st-rv14-80e78-3b44e9"}, {"t": "pt", "text": "New partner pays for a share of goodwill", "id": "acffa2st-rv14-80e78-6989e3"}, {"t": "pt", "text": "Goodwill created in the old ratio", "id": "acffa2st-rv14-80e78-e4625c"}, {"t": "pt", "text": "Goodwill eliminated in the new ratio", "id": "acffa2st-rv14-80e78-ac2c85"}, {"t": "pt", "text": "Profit-sharing ratio is not necessarily equal", "id": "acffa2st-rv14-80e78-e69358"}], "id": "acffa2st-rv14-80e78"}], "source": "BPP FA2 Kit section 14: 'Did you know?' p90; questions 14.1-14.16 pp91-93; answers pp137-138", "summary": "Partners' capital and current accounts, the appropriation account (salaries, interest, profit-sharing ratio), admission of a new partner and accounting for goodwill.", "id": "acffa2st-rv14", "updated": "2026-11-13"}], "plannedChapters": 14}, {"id": "acfma", "code": "MA1", "name": "Management Information", "level": "Foundations in Accountancy", "book": "ACCA-MA.pdf | BPP FIA MA1 Interactive Text (2017 edition) | offset 19", "updated": "2026-11-12", "chapters": [{"num": "1", "title": "Business Organisation and Accounting", "pages": [3, 20], "syllabus": "A1", "status": "published", "branches": [{"kind": "concept", "title": "Office organisation", "page": [4, 8], "items": [{"t": "pt", "k": 1, "text": "The office is a centre for information and administration", "id": "acfma-rv1-53957-d9b9f6"}, {"t": "pt", "text": "Office functions: purchasing, HR, finance, sales and marketing, general administration", "id": "acfma-rv1-53957-fb9376"}, {"t": "def", "term": "Organisation chart", "text": "A traditional way of depicting the roles and relationships in an organisation", "id": "acfma-rv1-53957-08b3f7"}, {"t": "pt", "text": "Departmentation: functional (similar work grouped), geographical (territorial operations), product/brand", "id": "acfma-rv1-53957-e90f57"}, {"t": "pt", "text": "Centralised administration: consistency, economies of scale, specialist staff; decentralised: local knowledge, speed, less reliance on head office", "id": "acfma-rv1-53957-fbf29c"}, {"t": "def", "k": 1, "term": "Policy manual", "text": "A document that helps ensure all personnel follow procedures and best practices", "id": "acfma-rv1-53957-5e4d52"}], "id": "acfma-rv1-53957"}, {"kind": "process", "title": "Transactions and control", "page": [8, 10], "items": [{"t": "pt", "k": 1, "text": "Main transactions: making sales • making purchases • paying expenses • paying employees • purchasing non-current assets", "id": "acfma-rv1-003cb-bbdd6a"}, {"t": "pt", "text": "Each transaction involves several people and documents (eg order, delivery, invoice, payment)", "id": "acfma-rv1-003cb-57916c"}, {"t": "pt", "k": 1, "text": "Control over transactions: authorisation, segregation of duties, documentation, checking and reconciliation, physical security", "id": "acfma-rv1-003cb-1364c6"}, {"t": "pt", "text": "Every payment should be authorised by an appropriate person within set limits", "id": "acfma-rv1-003cb-c4ec3b"}], "id": "acfma-rv1-003cb"}, {"kind": "formula", "title": "Double entry and cost ledgers", "page": [11, 13], "items": [{"t": "pt", "k": 1, "text": "Double entry: every transaction has two equal and opposite effects - a debit and a credit", "id": "acfma-rv1-6221c-52675f"}, {"t": "f", "term": "Accounting equation", "text": "Assets - Liabilities = Capital + Profit - Drawings", "vars": "the statement of financial position always balances", "id": "acfma-rv1-6221c-e68347"}, {"t": "pt", "text": "Transactions first recorded in books of prime entry, totalled and posted to the ledgers", "id": "acfma-rv1-6221c-f66f78"}, {"t": "def", "k": 1, "term": "Integrated system", "text": "Combines the cost accounting and financial accounting functions in ONE set of accounts", "id": "acfma-rv1-6221c-6cf3ae"}, {"t": "def", "k": 1, "term": "Interlocking system", "text": "Separate ledgers are kept for cost accounting and financial accounting; the cost ledger has a cost ledger control account and the two profits must be reconciled", "id": "acfma-rv1-6221c-891dd9"}, {"t": "pt", "text": "Integrated: no duplication, no reconciliation needed; interlocking: each set designed for its purpose but needs reconciliation", "id": "acfma-rv1-6221c-8046bb"}, {"t": "exam", "text": "A question on double entry in the costing system is highly likely", "id": "acfma-rv1-6221c-e957fa"}], "id": "acfma-rv1-6221c"}, {"kind": "compare", "title": "Processing methods", "page": [14, 17], "items": [{"t": "table", "rows": [["Feature", "Batch processing", "Real-time (online) processing"], ["How", "Transactions grouped and stored, then processed together", "Transactions input and processed immediately"], ["Records", "Up to date only after each run", "Always up to date"], ["Typical use", "Payroll, periodic invoicing", "Bookings, stock control, banking"], ["Cost", "Cheaper, efficient for high volumes", "More expensive systems"]], "id": "acfma-rv1-a67db-a1533b"}, {"t": "pt", "k": 1, "text": "A computerised accounting system allows much quicker and more accurate processing, automatic posting and reports", "id": "acfma-rv1-a67db-8097b9"}, {"t": "exam", "text": "Computerised systems were singled out in examiner's reports as poorly understood", "id": "acfma-rv1-a67db-5ef0e8"}], "id": "acfma-rv1-a67db"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing integrated (one set of accounts) with interlocking (two sets, reconciled)", "id": "acfma-rv1-6483a-04b13a"}, {"t": "x", "text": "Thinking batch processing updates records immediately", "id": "acfma-rv1-6483a-1ebc58"}, {"t": "x", "text": "Forgetting that drawings reduce capital in the accounting equation", "id": "acfma-rv1-6483a-501f33"}, {"t": "x", "text": "Treating the policy manual as optional guidance - it sets required procedures", "id": "acfma-rv1-6483a-5ff505"}], "id": "acfma-rv1-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "The office is a centre for information and administration", "id": "acfma-rv1-80e78-d9b9f6"}, {"t": "pt", "text": "Departmentation: functional, geographical, product/brand", "id": "acfma-rv1-80e78-a67662"}, {"t": "pt", "text": "Policy manual ensures standard procedures", "id": "acfma-rv1-80e78-81e8ba"}, {"t": "pt", "text": "Transactions: sales, purchases, expenses, wages, non-current assets", "id": "acfma-rv1-80e78-e792aa"}, {"t": "pt", "text": "Controls: authorisation, segregation, documents, checks", "id": "acfma-rv1-80e78-3edb78"}, {"t": "pt", "text": "Double entry: equal debit and credit", "id": "acfma-rv1-80e78-3709ab"}, {"t": "pt", "text": "Assets - liabilities = capital + profit - drawings", "id": "acfma-rv1-80e78-8ca115"}, {"t": "pt", "text": "Books of prime entry -> ledgers", "id": "acfma-rv1-80e78-8e83b3"}, {"t": "pt", "text": "Integrated system: one set of cost and financial accounts", "id": "acfma-rv1-80e78-f4dc91"}, {"t": "pt", "text": "Interlocking: separate ledgers, profits reconciled", "id": "acfma-rv1-80e78-07ed74"}, {"t": "pt", "text": "Batch processing: grouped, periodic", "id": "acfma-rv1-80e78-675501"}, {"t": "pt", "text": "Real-time: immediate, always up to date", "id": "acfma-rv1-80e78-cec0db"}], "id": "acfma-rv1-80e78"}], "source": "BPP MA1 Text ch 1: sections 1-7 pp4-17", "summary": "The office and its functions, organisation charts and departmentation, the policy manual, main business transactions and their control, double entry, cost ledger systems (integrated vs interlocking) and computerised processing.", "id": "acfma-rv1", "updated": "2026-11-12"}, {"num": "2", "title": "Introduction to Management Information", "pages": [21, 36], "syllabus": "A2", "status": "published", "branches": [{"kind": "concept", "title": "Data and information", "page": [22, 24], "items": [{"t": "def", "k": 1, "term": "Data", "text": "Facts, figures and measurements - the raw material for processing", "id": "acfma-rv2-3c1cc-f4257c"}, {"t": "def", "k": 1, "term": "Information", "text": "Data that has been processed in such a way as to be meaningful to the person who receives it", "id": "acfma-rv2-3c1cc-cdb141"}, {"t": "pt", "k": 1, "text": "Purpose of management information: help managers to manage resources efficiently and effectively - planning, control and decision making", "id": "acfma-rv2-3c1cc-f789f7"}, {"t": "exam", "text": "Make sure you understand the role of management and the purpose of management information", "id": "acfma-rv2-3c1cc-b6cd0f"}], "id": "acfma-rv2-3c1cc"}, {"kind": "concept", "title": "Management reports", "page": [24, 26], "items": [{"t": "pt", "text": "Producing a useful report depends on understanding the user's needs", "id": "acfma-rv2-20d65-87d01f"}, {"t": "pt", "text": "Reports may show: comparisons between actual and budget, comparisons with previous periods, trends, exceptions and variances", "id": "acfma-rv2-20d65-3f419e"}, {"t": "eg", "text": "Summary monthly report to charity trustees: fundraising, costs, number of people helped", "id": "acfma-rv2-20d65-e21f32"}, {"t": "pt", "k": 1, "text": "Good information - ACCURATE: Accurate • Complete • Cost-beneficial • User-targeted • Relevant • Authoritative • Timely • Easy to use", "id": "acfma-rv2-20d65-187349"}], "id": "acfma-rv2-20d65"}, {"kind": "compare", "title": "Sources of information", "page": [27, 28], "items": [{"t": "table", "rows": [["Source", "Examples"], ["Internal - accounting records", "Receivables ledger, payables ledger, general ledger, cash book"], ["Internal - other", "Payroll, production, sales, personnel records, staff knowledge"], ["External", "Suppliers' price lists, customers, government statistics, trade journals, newspapers, the internet, banks, consultants"]], "id": "acfma-rv2-068b3-b37e49"}, {"t": "pt", "k": 1, "text": "Internal information comes from inside the organisation; external from outside (often captured routinely or researched)", "id": "acfma-rv2-068b3-9209b3"}, {"t": "exam", "text": "Internal and external sources of information could easily be examined", "id": "acfma-rv2-068b3-532939"}], "id": "acfma-rv2-068b3"}, {"kind": "compare", "title": "Management vs financial accounts", "page": [29, 31], "items": [{"t": "table", "rows": [["Feature", "Cost and management accounts", "Financial accounts"], ["Purpose", "Internal planning, control and decisions", "Accurate financial information for external users"], ["Rules", "No external rules on format or content", "Governed by law and accounting standards"], ["Users", "Managers", "Shareholders, lenders, tax authorities"], ["Detail", "Products, departments, activities", "The business as a whole"]], "id": "acfma-rv2-01d98-b29aac"}, {"t": "pt", "text": "Computer systems and coding structures sort the accounting information for both purposes", "id": "acfma-rv2-01d98-1e3c84"}, {"t": "pt", "k": 1, "text": "Limitations of cost and management accounting information: historic data may not predict the future; non-financial factors omitted; apportionments are arbitrary; may not be timely", "id": "acfma-rv2-01d98-9134ca"}, {"t": "pt", "text": "Trainee accountant's role: collect and record cost data, code transactions, prepare routine reports, deal with queries, spot unusual items", "id": "acfma-rv2-01d98-40fb18"}], "id": "acfma-rv2-01d98"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calling raw figures 'information' before they are processed into a meaningful form", "id": "acfma-rv2-6483a-debb11"}, {"t": "x", "text": "Thinking management accounts must follow accounting standards", "id": "acfma-rv2-6483a-f55a6d"}, {"t": "x", "text": "Treating ledgers as external sources - they are internal", "id": "acfma-rv2-6483a-7d5db9"}, {"t": "x", "text": "Forgetting cost-beneficial: information should cost less than its value", "id": "acfma-rv2-6483a-ed9070"}], "id": "acfma-rv2-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Data = raw facts; information = processed and meaningful", "id": "acfma-rv2-80e78-f9f177"}, {"t": "pt", "text": "Management information supports planning, control and decisions", "id": "acfma-rv2-80e78-48adbe"}, {"t": "pt", "text": "Reports should meet the user's needs", "id": "acfma-rv2-80e78-b94f7c"}, {"t": "pt", "text": "ACCURATE: accurate, complete, cost-beneficial, user-targeted, relevant, authoritative, timely, easy to use", "id": "acfma-rv2-80e78-dc9ed0"}, {"t": "pt", "text": "Internal sources: ledgers, payroll, production records", "id": "acfma-rv2-80e78-d7e54c"}, {"t": "pt", "text": "External sources: suppliers, government, journals, internet", "id": "acfma-rv2-80e78-6b36cf"}, {"t": "pt", "text": "Management accounts: no external rules", "id": "acfma-rv2-80e78-7decb0"}, {"t": "pt", "text": "Financial accounts: law and standards", "id": "acfma-rv2-80e78-ee7ae5"}, {"t": "pt", "text": "Coding sorts information for both", "id": "acfma-rv2-80e78-ada0d5"}, {"t": "pt", "text": "Limitations: historic, arbitrary, may lack non-financial data", "id": "acfma-rv2-80e78-9c241a"}, {"t": "pt", "text": "Trainee: record, code, report, query", "id": "acfma-rv2-80e78-2e5dd3"}], "id": "acfma-rv2-80e78"}], "source": "BPP MA1 Text ch 2: sections 1-7 pp22-31", "summary": "Data vs information, the purpose of management information, management reports, qualities of good information (ACCURATE), internal and external sources, cost and management vs financial accounts, limitations and the trainee accountant's role.", "id": "acfma-rv2", "updated": "2026-11-12"}, {"num": "3", "title": "Cost Units, Cost Classification and Profit Reporting", "pages": [37, 56], "syllabus": "B1", "status": "published", "branches": [{"kind": "concept", "title": "Cost units and classification", "page": [38, 41], "items": [{"t": "def", "k": 1, "term": "Cost unit", "text": "A unit of product or service to which costs can be related (eg a pen, a batch, a patient day)", "id": "acfma-rv3-4ef63-cb7a1a"}, {"t": "pt", "text": "Production cost of a pen: plastic, ink, labour and a share of factory costs", "id": "acfma-rv3-4ef63-fad4ff"}, {"t": "pt", "k": 1, "text": "Costs split into materials, labour and expenses - each direct or indirect", "id": "acfma-rv3-4ef63-5d0067"}, {"t": "def", "k": 1, "term": "Direct cost", "text": "Can be traced directly to a cost unit", "id": "acfma-rv3-4ef63-d34d8c"}, {"t": "def", "k": 1, "term": "Indirect cost (overhead)", "text": "Cannot be traced directly to a cost unit", "id": "acfma-rv3-4ef63-9945e2"}, {"t": "pt", "text": "Prime cost = direct materials + direct labour + direct expenses", "id": "acfma-rv3-4ef63-1b7635"}, {"t": "exam", "text": "An exam question may ask you to classify a cost as direct or indirect", "id": "acfma-rv3-4ef63-2738f9"}], "id": "acfma-rv3-4ef63"}, {"kind": "concept", "title": "Cost behaviour", "page": [42, 46], "items": [{"t": "def", "k": 1, "term": "Variable cost", "text": "Varies in total directly with the volume of output; constant per unit", "id": "acfma-rv3-2c532-0c0c61"}, {"t": "def", "k": 1, "term": "Fixed cost", "text": "Unaffected in total by changes in activity; per unit falls as output rises", "id": "acfma-rv3-2c532-fc7022"}, {"t": "def", "k": 1, "term": "Stepped-fixed cost", "text": "Fixed within certain levels of activity, then jumps (eg extra supervisor)", "id": "acfma-rv3-2c532-930ef5"}, {"t": "def", "k": 1, "term": "Mixed (semi-variable) cost", "text": "Contains a fixed and a variable element (eg phone rental + call charges)", "id": "acfma-rv3-2c532-76e0fc"}, {"t": "pt", "text": "Level of activity = the amount of work done or volume of production", "id": "acfma-rv3-2c532-97a598"}, {"t": "exam", "text": "Identifying cost behaviour types is a particularly important skill - you may be given a graph and asked which cost it shows", "id": "acfma-rv3-2c532-7c7f4c"}, {"t": "pt", "text": "Graph shapes: variable = straight line from origin; fixed = horizontal line; stepped = staircase; mixed = line starting above zero", "id": "acfma-rv3-2c532-f86cc3"}], "id": "acfma-rv3-2c532"}, {"kind": "formula", "title": "Product cost and functional costs", "page": [47, 48], "items": [{"t": "pt", "text": "Functional costs: production, distribution, selling, administration, finance", "id": "acfma-rv3-3f87f-6c2c19"}, {"t": "f", "k": 1, "term": "Unit cost card", "text": "Direct materials + Direct labour + Direct expenses = Prime cost; + Production overheads = Total production cost; + Non-production overheads = Total cost", "vars": "built up per cost unit", "eg": "Skeggy Co: per-Brace material, labour and overhead build to a unit cost", "id": "acfma-rv3-3f87f-3a2b74"}, {"t": "pt", "text": "Selling price = total cost + profit mark-up", "id": "acfma-rv3-3f87f-ad1db4"}], "id": "acfma-rv3-3f87f"}, {"kind": "compare", "title": "Absorption vs marginal costing profit", "page": [49, 52], "items": [{"t": "table", "rows": [["Point", "Absorption costing", "Marginal costing"], ["Unit cost includes", "Variable + fixed production cost", "Variable production cost only"], ["Fixed production overhead", "Absorbed into units and inventory", "Charged in full to the period"], ["Key measure", "Profit", "Contribution (sales - variable costs)"], ["Inventory value", "Higher", "Lower"]], "id": "acfma-rv3-0c5d1-6ebdc1"}, {"t": "pt", "k": 1, "text": "If closing inventory > opening inventory, absorption costing profit is HIGHER (some fixed overhead carried forward)", "id": "acfma-rv3-0c5d1-b35cf2"}, {"t": "def", "k": 1, "term": "Contribution", "text": "Sales revenue minus variable costs - contributes to fixed costs and profit", "id": "acfma-rv3-0c5d1-a97f41"}, {"t": "pt", "text": "Marginal costing is generally preferred for decision making; absorption for inventory valuation in financial accounts", "id": "acfma-rv3-0c5d1-ee1720"}, {"t": "exam", "text": "Absorption vs marginal costing featured repeatedly in examiner's reports as poorly answered", "id": "acfma-rv3-0c5d1-2d1235"}], "id": "acfma-rv3-0c5d1"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Saying fixed cost per unit is constant - it falls as output rises", "id": "acfma-rv3-6483a-69927e"}, {"t": "x", "text": "Confusing a stepped-fixed cost graph with a mixed cost graph", "id": "acfma-rv3-6483a-8a4c9a"}, {"t": "x", "text": "Including fixed production overhead in a marginal cost card", "id": "acfma-rv3-6483a-e67498"}, {"t": "x", "text": "Forgetting that profits are the same under both methods when inventory levels do not change", "id": "acfma-rv3-6483a-08c189"}], "id": "acfma-rv3-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Cost unit = unit of output to which costs relate", "id": "acfma-rv3-80e78-a3ef66"}, {"t": "pt", "text": "Direct = traceable; indirect = overhead", "id": "acfma-rv3-80e78-40c854"}, {"t": "pt", "text": "Prime cost = direct materials + labour + expenses", "id": "acfma-rv3-80e78-c242fb"}, {"t": "pt", "text": "Variable: constant per unit", "id": "acfma-rv3-80e78-c9bafb"}, {"t": "pt", "text": "Fixed: constant in total", "id": "acfma-rv3-80e78-c61fd4"}, {"t": "pt", "text": "Stepped-fixed: fixed within ranges", "id": "acfma-rv3-80e78-36aa01"}, {"t": "pt", "text": "Mixed: fixed + variable element", "id": "acfma-rv3-80e78-e1e453"}, {"t": "pt", "text": "Total production cost = prime cost + production overheads", "id": "acfma-rv3-80e78-3d77e7"}, {"t": "pt", "text": "Total cost = production cost + non-production overheads", "id": "acfma-rv3-80e78-7b80ca"}, {"t": "pt", "text": "Contribution = sales - variable costs", "id": "acfma-rv3-80e78-a00567"}, {"t": "pt", "text": "Inventory rising: absorption profit higher", "id": "acfma-rv3-80e78-5bdc21"}, {"t": "pt", "text": "Marginal costing aids decisions", "id": "acfma-rv3-80e78-7bc800"}], "id": "acfma-rv3-80e78"}], "source": "BPP MA1 Text ch 3: sections 1-8 pp38-52", "summary": "Cost units, production costs, direct and indirect costs, cost behaviour (variable, fixed, stepped, mixed), functional costs, building a product cost card, and absorption vs marginal costing profit.", "id": "acfma-rv3", "updated": "2026-11-12"}, {"num": "4", "title": "Management Responsibility and Performance Measurement", "pages": [57, 72], "syllabus": "B2", "status": "published", "branches": [{"kind": "compare", "title": "Responsibility centres", "page": [58, 60], "items": [{"t": "table", "rows": [["Centre", "Manager responsible for", "Examples"], ["Cost centre", "Costs only", "A department, a machine, a project, a person"], ["Profit centre", "Costs and revenues (profit)", "A sales division, a service centre charging users"], ["Investment centre", "Costs, revenues AND capital investment", "A subsidiary or autonomous division"]], "id": "acfma-rv4-5c393-f35bf9"}, {"t": "def", "k": 1, "term": "Responsibility centre", "text": "A function or department headed by a manager who is responsible for its performance", "id": "acfma-rv4-5c393-1e7764"}, {"t": "exam", "text": "Many students confuse cost UNITS (output) and cost CENTRES (where costs are collected) - don't make that mistake", "id": "acfma-rv4-5c393-cc9b68"}], "id": "acfma-rv4-5c393"}, {"kind": "formula", "title": "Cost centre measures", "page": [61, 63], "items": [{"t": "f", "k": 1, "term": "Productivity", "text": "Output / Input (resources used)", "vars": "eg units per labour hour", "id": "acfma-rv4-ff070-14a2cd"}, {"t": "f", "term": "Cost per unit", "text": "Total costs / Number of units produced", "vars": "should fall as efficiency improves", "id": "acfma-rv4-ff070-e098d5"}, {"t": "def", "k": 1, "term": "Standard hour", "text": "The amount of work achievable at standard efficiency in one hour", "id": "acfma-rv4-ff070-c59aeb"}, {"t": "f", "k": 1, "term": "Efficiency ratio", "text": "Standard hours of actual production / Actual hours worked x 100%", "id": "acfma-rv4-ff070-efc9b6"}, {"t": "f", "k": 1, "term": "Capacity utilisation ratio", "text": "Actual hours worked / Budgeted hours x 100%", "id": "acfma-rv4-ff070-f6a96e"}, {"t": "f", "k": 1, "term": "Production volume ratio", "text": "Standard hours of actual production / Budgeted hours x 100%", "vars": "= efficiency x capacity", "id": "acfma-rv4-ff070-cd5925"}, {"t": "exam", "text": "The standard hour was the subject of an MA1 examining team article", "id": "acfma-rv4-ff070-32ab70"}], "id": "acfma-rv4-ff070"}, {"kind": "formula", "title": "Profit centre measures", "page": [63, 64], "items": [{"t": "f", "k": 1, "term": "Net profit margin", "text": "Net profit / Sales x 100%", "id": "acfma-rv4-87433-09fbd4"}, {"t": "f", "term": "Gross profit margin", "text": "Gross profit / Sales x 100%", "id": "acfma-rv4-87433-977ac9"}, {"t": "f", "term": "Cost/sales ratios", "text": "Production cost of sales / Sales; distribution and marketing costs / Sales; administration costs / Sales", "vars": "explain why target profits are not met", "id": "acfma-rv4-87433-34835a"}], "id": "acfma-rv4-87433"}, {"kind": "formula", "title": "Investment centre measures", "page": [65, 68], "items": [{"t": "f", "k": 1, "term": "Return on capital employed (ROCE)", "text": "Profit before interest and tax / Capital employed x 100%", "vars": "capital employed = total assets - current liabilities", "id": "acfma-rv4-62b1d-983c20"}, {"t": "f", "k": 1, "term": "Residual income (RI)", "text": "Profit - Imputed interest (Capital employed x Cost of capital)", "vars": "absolute $ measure", "eg": "Company A RI $150,000 vs Company B $250,000 - B adds more value above its cost of capital", "id": "acfma-rv4-62b1d-f4d3ac"}, {"t": "f", "term": "Asset turnover", "text": "Sales / Capital employed", "vars": "how efficiently assets generate sales", "id": "acfma-rv4-62b1d-14ff0a"}, {"t": "f", "k": 1, "term": "ROCE link", "text": "ROCE = Asset turnover x Net profit margin", "id": "acfma-rv4-62b1d-f116b6"}, {"t": "pt", "text": "RI encourages managers to accept projects earning above the cost of capital; ROCE may make them reject projects that lower the current ROCE", "id": "acfma-rv4-62b1d-4fc47e"}, {"t": "exam", "text": "A residual income question was singled out as poorly answered (June 2012 examiner's report)", "id": "acfma-rv4-62b1d-60d8d7"}], "id": "acfma-rv4-62b1d"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing a cost unit with a cost centre", "id": "acfma-rv4-6483a-4a6270"}, {"t": "x", "text": "Mixing up the efficiency ratio (standard/actual hours) and capacity ratio (actual/budgeted hours)", "id": "acfma-rv4-6483a-96c1a5"}, {"t": "x", "text": "Calculating RI with the profit margin instead of deducting imputed interest", "id": "acfma-rv4-6483a-20cf7f"}, {"t": "x", "text": "Forgetting that ROCE = asset turnover x profit margin", "id": "acfma-rv4-6483a-532ad7"}], "id": "acfma-rv4-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Cost centre: costs; profit centre: costs and revenues; investment centre: plus capital", "id": "acfma-rv4-80e78-21fd2b"}, {"t": "pt", "text": "Cost unit ≠ cost centre", "id": "acfma-rv4-80e78-8951b9"}, {"t": "pt", "text": "Productivity = output / input", "id": "acfma-rv4-80e78-db9bf7"}, {"t": "pt", "text": "Efficiency = std hours produced / actual hours", "id": "acfma-rv4-80e78-ee0fc3"}, {"t": "pt", "text": "Capacity = actual hours / budgeted hours", "id": "acfma-rv4-80e78-e2ad30"}, {"t": "pt", "text": "Production volume = std hours produced / budgeted hours", "id": "acfma-rv4-80e78-13f0b0"}, {"t": "pt", "text": "Production volume = efficiency x capacity", "id": "acfma-rv4-80e78-126234"}, {"t": "pt", "text": "Net profit margin = net profit / sales", "id": "acfma-rv4-80e78-9e6c94"}, {"t": "pt", "text": "Cost/sales ratios explain missed targets", "id": "acfma-rv4-80e78-1df132"}, {"t": "pt", "text": "ROCE = PBIT / capital employed", "id": "acfma-rv4-80e78-1240e9"}, {"t": "pt", "text": "RI = profit - capital x cost of capital", "id": "acfma-rv4-80e78-481898"}, {"t": "pt", "text": "Asset turnover = sales / capital employed", "id": "acfma-rv4-80e78-be3f4b"}, {"t": "pt", "text": "ROCE = asset turnover x profit margin", "id": "acfma-rv4-80e78-b06e5b"}], "id": "acfma-rv4-80e78"}], "source": "BPP MA1 Text ch 4: sections 1-2 pp58-68", "summary": "Cost, profit and investment centres, and performance measures for each: productivity, cost per unit, standard hour ratios, profit margins, cost/sales ratios, ROCE, residual income and asset turnover.", "id": "acfma-rv4", "updated": "2026-11-12"}, {"num": "5", "title": "Source Documents and Coding", "pages": [73, 100], "syllabus": "B3", "status": "published", "branches": [{"kind": "concept", "title": "Coding", "page": [74, 78], "items": [{"t": "pt", "k": 1, "text": "Costs and income must be coded so they are correctly analysed, classified and recorded", "id": "acfma-rv5-70994-827d1a"}, {"t": "pt", "text": "Features of a good code: unique, brief, comprehensive (every item), elastic (room for new items), consistent/uniform, unambiguous, centrally controlled", "id": "acfma-rv5-70994-940e40"}, {"t": "pt", "text": "Types: sequential (progressive), block, hierarchical, significant digit, faceted, mnemonic, alphabetical (eg MIL 010 for Miller Co)", "id": "acfma-rv5-70994-0a630f"}, {"t": "eg", "text": "Numeric ranges: non-current assets 1000-1999, current assets 2000-2999 and so on", "id": "acfma-rv5-70994-ceb9d4"}, {"t": "pt", "k": 1, "text": "Advantages: briefer than descriptions, less ambiguity, easier analysis and computer processing", "id": "acfma-rv5-70994-0ad3dd"}, {"t": "exam", "text": "Coding featured as a weak area in the December 2014 examiner's report", "id": "acfma-rv5-70994-6184f7"}], "id": "acfma-rv5-70994"}, {"kind": "process", "title": "Purchasing and selling documents", "page": [79, 84], "items": [{"t": "pt", "k": 1, "text": "Sequence: purchase requisition -> quotation/estimate -> purchase order -> delivery note -> goods received note (GRN) -> purchase invoice", "id": "acfma-rv5-6b872-610687"}, {"t": "pt", "text": "Purchase requisition: prepared by the person who identifies the need", "id": "acfma-rv5-6b872-50ea8a"}, {"t": "pt", "text": "Quotation/estimate: from the supplier, may include prices, discounts and terms", "id": "acfma-rv5-6b872-56e10d"}, {"t": "pt", "text": "Purchase order: sent by the purchasing department to the supplier", "id": "acfma-rv5-6b872-a17b93"}, {"t": "pt", "text": "Delivery note: accompanies the goods; GRN: prepared on receipt and checked against the order", "id": "acfma-rv5-6b872-62f699"}, {"t": "pt", "text": "Purchase invoice: matched to the order and GRN before payment, then coded to the correct account", "id": "acfma-rv5-6b872-0ef950"}, {"t": "exam", "text": "The documents in the purchasing/selling cycle are important - expect questions on their order and purpose", "id": "acfma-rv5-6b872-db5c9e"}], "id": "acfma-rv5-6b872"}, {"kind": "formula", "title": "Recording materials", "page": [87, 89], "items": [{"t": "pt", "k": 1, "text": "Bin card: manual record of QUANTITY kept in the stores department for each line of inventory", "id": "acfma-rv5-2382b-c473f0"}, {"t": "pt", "k": 1, "text": "Stores ledger account: quantity AND VALUE, kept by the cost department", "id": "acfma-rv5-2382b-5655fe"}, {"t": "def", "k": 1, "term": "Materials requisition", "text": "Completed when materials are needed from stores - authorises the issue and identifies the cost centre/job to be charged", "id": "acfma-rv5-2382b-e75c8f"}, {"t": "pt", "text": "Materials returned note: unused materials sent back to stores", "id": "acfma-rv5-2382b-9fd69f"}, {"t": "f", "k": 1, "term": "Free inventory", "text": "Physical inventory + Inventory on order - Inventory requisitioned but not yet issued", "vars": "used for re-ordering decisions", "eg": "10,000 kg in stock + 4,000 on order - 6,000 requisitioned = 8,000 kg free", "id": "acfma-rv5-2382b-c6fc61"}, {"t": "exam", "text": "You may be given figures and asked to calculate free inventory", "id": "acfma-rv5-2382b-0025cd"}], "id": "acfma-rv5-2382b"}, {"kind": "concept", "title": "Labour and sales records", "page": [90, 94], "items": [{"t": "pt", "text": "Hourly paid workers: flat rate per hour plus overtime; attendance recorded on time sheets/clock cards", "id": "acfma-rv5-5c9e3-f5a71e"}, {"t": "pt", "k": 1, "text": "Job cards record the time spent on each job or batch - used to charge direct labour to jobs", "id": "acfma-rv5-5c9e3-19e704"}, {"t": "pt", "text": "Coding labour: by department first, then by product (eg department 10 product 20)", "id": "acfma-rv5-5c9e3-22a6ab"}, {"t": "pt", "text": "Sales income can be analysed by product, customer, region, sales person or channel - coding enables this", "id": "acfma-rv5-5c9e3-791797"}], "id": "acfma-rv5-5c9e3"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Putting the GRN before the delivery note - the delivery note arrives with the goods; the GRN is raised on acceptance", "id": "acfma-rv5-6483a-0e2689"}, {"t": "x", "text": "Treating the bin card as a record of value - it records quantity only", "id": "acfma-rv5-6483a-6d94ae"}, {"t": "x", "text": "Forgetting to deduct requisitioned-but-unissued inventory from free inventory", "id": "acfma-rv5-6483a-71413b"}, {"t": "x", "text": "Coding a cost to the wrong level when the hierarchy is department then product", "id": "acfma-rv5-6483a-aec740"}], "id": "acfma-rv5-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Good code: unique, brief, comprehensive, elastic, unambiguous", "id": "acfma-rv5-80e78-ace26c"}, {"t": "pt", "text": "Code types: sequential, block, hierarchical, faceted, mnemonic, alphabetical", "id": "acfma-rv5-80e78-5305a2"}, {"t": "pt", "text": "Requisition -> quotation -> purchase order -> delivery note -> GRN -> invoice", "id": "acfma-rv5-80e78-3a1933"}, {"t": "pt", "text": "Invoice checked against order and GRN", "id": "acfma-rv5-80e78-fd1772"}, {"t": "pt", "text": "Bin card = quantity in stores", "id": "acfma-rv5-80e78-16c789"}, {"t": "pt", "text": "Stores ledger = quantity and value", "id": "acfma-rv5-80e78-83b8d8"}, {"t": "pt", "text": "Materials requisition authorises issues", "id": "acfma-rv5-80e78-86b871"}, {"t": "pt", "text": "Free inventory = physical + on order - requisitioned not issued", "id": "acfma-rv5-80e78-cccddc"}, {"t": "pt", "text": "Time sheets record attendance", "id": "acfma-rv5-80e78-bebb51"}, {"t": "pt", "text": "Job cards record time per job", "id": "acfma-rv5-80e78-e735eb"}, {"t": "pt", "text": "Code labour by department then product", "id": "acfma-rv5-80e78-fa723e"}, {"t": "pt", "text": "Sales analysed by product, customer, region", "id": "acfma-rv5-80e78-accdf8"}], "id": "acfma-rv5-80e78"}], "source": "BPP MA1 Text ch 5: sections 1-5 pp74-94", "summary": "Coding systems and their features, purchasing and selling documents, documents for recording materials (bin cards, stores ledger, requisitions, free inventory), labour time records and job cards, coding labour and analysing sales income.", "id": "acfma-rv5", "updated": "2026-11-12"}, {"num": "6", "title": "Accounting for Material and Labour Costs", "pages": [101, 126], "syllabus": "B4", "status": "published", "branches": [{"kind": "concept", "title": "Materials and ordering", "page": [102, 106], "items": [{"t": "pt", "k": 1, "text": "Raw materials: goods purchased for incorporation into products for sale", "id": "acfma-rv6-e917e-d07814"}, {"t": "pt", "text": "Work in progress: an intermediate stage between raw materials and finished goods", "id": "acfma-rv6-e917e-3da8b0"}, {"t": "pt", "text": "Finished goods: products ready for sale or despatch", "id": "acfma-rv6-e917e-566059"}, {"t": "f", "k": 1, "term": "Units to produce", "text": "Units sold + Closing inventory - Opening inventory", "vars": "finished goods", "id": "acfma-rv6-e917e-5db975"}, {"t": "f", "k": 1, "term": "Materials purchases", "text": "Materials usage + Closing inventory of materials - Opening inventory of materials", "vars": "quantities first, then value", "id": "acfma-rv6-e917e-006cac"}, {"t": "exam", "text": "Order amounts featured as a weak area in examiner's reports (December 2012 and 2014)", "id": "acfma-rv6-e917e-812723"}], "id": "acfma-rv6-e917e"}, {"kind": "compare", "title": "Inventory valuation methods", "page": [107, 113], "items": [{"t": "table", "rows": [["Method", "Issues priced at", "Closing inventory", "Rising prices"], ["FIFO", "Oldest prices first", "Latest prices", "Lowest cost of issues, highest profit"], ["LIFO", "Latest prices first", "Oldest prices", "Highest cost of issues, lowest profit"], ["Periodic weighted average", "One average for the whole period", "Average", "Between the two"], ["Cumulative weighted average", "New average after each receipt", "Average", "Between the two"]], "id": "acfma-rv6-d5417-30b7d7"}, {"t": "pt", "k": 1, "text": "Material control account: Dr purchases; Cr issues to WIP (direct), production overhead (indirect); balance = closing inventory", "id": "acfma-rv6-d5417-683d55"}, {"t": "pt", "k": 1, "text": "Cost of issues + closing inventory = opening inventory + purchases under every method (eg $1,916 in the BPP example)", "id": "acfma-rv6-d5417-6a9622"}, {"t": "eg", "text": "Periodic average: (opening value + purchases) / (opening units + units bought) = $2.129 per unit", "id": "acfma-rv6-d5417-739916"}, {"t": "pt", "k": 1, "text": "There is no single 'correct' method - but in rising prices FIFO gives the highest closing inventory and profit", "id": "acfma-rv6-d5417-18b91c"}, {"t": "exam", "text": "The cost accounting double entry for materials is highly examinable", "id": "acfma-rv6-d5417-697443"}], "id": "acfma-rv6-d5417"}, {"kind": "formula", "title": "Remuneration and unit labour costs", "page": [113, 117], "items": [{"t": "pt", "text": "Time rate: hours x rate (shift premiums for unsocial hours)", "id": "acfma-rv6-828af-dffdd9"}, {"t": "f", "k": 1, "term": "Piecework", "text": "Units produced x Rate per unit", "vars": "often with a guaranteed minimum", "id": "acfma-rv6-828af-031d29"}, {"t": "f", "term": "Premium bonus", "text": "Bonus = % of time saved x hourly rate", "vars": "time saved = time allowed - time taken", "eg": "75% x 200 minutes saved x $6 per hour = $15 bonus; basic 8 hours x $6 = $48", "id": "acfma-rv6-828af-69a907"}, {"t": "pt", "text": "Unit labour cost = total labour cost / units produced - falls when productivity rises", "id": "acfma-rv6-828af-86aec4"}, {"t": "pt", "k": 1, "text": "Gross pay - employee deductions (income tax, employee benefit contributions) = net pay", "id": "acfma-rv6-828af-a75732"}, {"t": "pt", "k": 1, "text": "Employer's cost of employment = gross pay + employer's benefit contributions (and pension contributions)", "id": "acfma-rv6-828af-3439a6"}], "id": "acfma-rv6-828af"}, {"kind": "process", "title": "Accounting for labour", "page": [120, 123], "items": [{"t": "pt", "k": 1, "text": "Wages control account: Dr gross pay (net pay to bank, deductions to payables); Cr direct labour to WIP, indirect labour to production overhead control", "id": "acfma-rv6-5f5fa-05f79c"}, {"t": "pt", "k": 1, "text": "Direct labour = hours worked on production at the BASIC rate", "id": "acfma-rv6-5f5fa-4e6bf5"}, {"t": "pt", "k": 1, "text": "Overtime premium and idle time are INDIRECT (production overhead) unless overtime is at the customer's specific request", "id": "acfma-rv6-5f5fa-1b0e95"}, {"t": "exam", "text": "The cost accounting double entry for labour and the treatment of overtime and idle time are highly examinable (several examiner's reports)", "id": "acfma-rv6-5f5fa-08b279"}], "id": "acfma-rv6-5f5fa"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Charging overtime premium as direct labour by default", "id": "acfma-rv6-6483a-5d98cf"}, {"t": "x", "text": "Mixing up the production and purchases formulas - production uses finished goods inventory; purchases use materials inventory", "id": "acfma-rv6-6483a-f687dc"}, {"t": "x", "text": "Assuming LIFO gives the highest profit in rising prices - FIFO does", "id": "acfma-rv6-6483a-07b6f5"}, {"t": "x", "text": "Forgetting employer's contributions in the employer's cost of labour", "id": "acfma-rv6-6483a-2e8a67"}], "id": "acfma-rv6-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Raw materials, WIP, finished goods", "id": "acfma-rv6-80e78-f028ff"}, {"t": "pt", "text": "Production = sales + closing FG - opening FG", "id": "acfma-rv6-80e78-20bdfc"}, {"t": "pt", "text": "Purchases = usage + closing materials - opening materials", "id": "acfma-rv6-80e78-eb7749"}, {"t": "pt", "text": "FIFO: oldest prices to issues", "id": "acfma-rv6-80e78-960d24"}, {"t": "pt", "text": "LIFO: latest prices to issues", "id": "acfma-rv6-80e78-7a302b"}, {"t": "pt", "text": "Weighted average: periodic or cumulative", "id": "acfma-rv6-80e78-5ed307"}, {"t": "pt", "text": "Rising prices: FIFO highest profit", "id": "acfma-rv6-80e78-93c98b"}, {"t": "pt", "text": "Material control: Cr WIP (direct) and overhead (indirect)", "id": "acfma-rv6-80e78-26c431"}, {"t": "pt", "text": "Piecework = units x rate", "id": "acfma-rv6-80e78-6b3548"}, {"t": "pt", "text": "Premium bonus = % of time saved x rate", "id": "acfma-rv6-80e78-ba8e7b"}, {"t": "pt", "text": "Net pay = gross pay - deductions", "id": "acfma-rv6-80e78-3890eb"}, {"t": "pt", "text": "Employer cost = gross pay + employer contributions", "id": "acfma-rv6-80e78-403baf"}, {"t": "pt", "text": "Overtime premium and idle time = overhead", "id": "acfma-rv6-80e78-d3c280"}], "id": "acfma-rv6-80e78"}], "source": "BPP MA1 Text ch 6: sections 1-7 pp102-123", "summary": "Types of materials, order quantities, the material control account, FIFO/LIFO/weighted average valuation, remuneration methods, unit labour costs, gross pay and deductions, and accounting for labour including overtime and idle time.", "id": "acfma-rv6", "updated": "2026-11-12"}, {"num": "7", "title": "Overhead Costs", "pages": [127, 144], "syllabus": "B5", "status": "published", "branches": [{"kind": "process", "title": "Allocation and apportionment", "page": [128, 131], "items": [{"t": "pt", "k": 1, "text": "Overheads = indirect materials + indirect labour + indirect expenses", "id": "acfma-rv7-d5a4e-8fe170"}, {"t": "pt", "k": 1, "text": "Stages: allocate -> apportion -> reapportion service cost centres -> absorb into cost units", "id": "acfma-rv7-d5a4e-ed835f"}, {"t": "pt", "text": "Allocation: whole items charged to one cost centre (eg a department's supervisor)", "id": "acfma-rv7-d5a4e-59afd8"}, {"t": "pt", "text": "Apportionment: shared costs split on a fair basis - floor area (rent, rates), number of employees (canteen), value of machinery (depreciation, insurance)", "id": "acfma-rv7-d5a4e-79527e"}, {"t": "pt", "k": 1, "text": "Service cost centre costs (stores, maintenance, canteen) must be reapportioned to production cost centres", "id": "acfma-rv7-d5a4e-0e168f"}, {"t": "exam", "text": "Be able to carry out basic apportionment of overheads in an exam question", "id": "acfma-rv7-d5a4e-383f35"}], "id": "acfma-rv7-d5a4e"}, {"kind": "formula", "title": "Absorption", "page": [132, 135], "items": [{"t": "f", "k": 1, "term": "Overhead absorption rate (OAR)", "text": "Budgeted overhead / Budgeted activity", "vars": "activity = machine hours (machine-based department) or labour hours (labour-intensive) or units", "eg": "Assembly is machine-based -> rate per machine hour", "id": "acfma-rv7-c2214-854186"}, {"t": "pt", "k": 1, "text": "Predetermined rates are set in advance from budgets so product costs are available during the period", "id": "acfma-rv7-c2214-2842aa"}, {"t": "pt", "text": "Product cost = prime cost + (hours used in each department x that department's OAR)", "id": "acfma-rv7-c2214-fd3b26"}, {"t": "pt", "text": "Choose an absorption base that reflects how overhead is incurred", "id": "acfma-rv7-c2214-6e5967"}], "id": "acfma-rv7-c2214"}, {"kind": "formula", "title": "Under- and over-absorption", "page": [136, 138], "items": [{"t": "f", "k": 1, "term": "Absorbed overhead", "text": "Actual activity x Predetermined OAR", "vars": "compare with actual overhead incurred", "id": "acfma-rv7-4738c-4dcb5b"}, {"t": "f", "k": 1, "term": "Under/over-absorption", "text": "Absorbed overhead - Actual overhead", "vars": "absorbed < actual = UNDER-absorbed (debit to profit or loss, reduces profit); absorbed > actual = OVER-absorbed (credit, increases profit)", "eg": "Rex Co example", "id": "acfma-rv7-4738c-859ca4"}, {"t": "pt", "text": "Reasons: actual overhead differs from budget and/or actual activity differs from budget", "id": "acfma-rv7-4738c-4d2bf2"}], "id": "acfma-rv7-4738c"}, {"kind": "compare", "title": "Absorption vs marginal costing", "page": [139, 140], "items": [{"t": "table", "rows": [["Point", "Absorption costing", "Marginal costing"], ["Inventory valued at", "Full production cost", "Variable production cost"], ["Fixed production overhead", "Absorbed into units", "Period cost"], ["Profit when inventory rises", "Higher", "Lower"], ["Profit when inventory falls", "Lower", "Higher"]], "id": "acfma-rv7-edb86-68c0db"}, {"t": "f", "term": "Profit difference", "text": "Change in inventory units x Fixed overhead absorption rate per unit", "vars": "TLF Company example", "id": "acfma-rv7-edb86-94aba7"}, {"t": "pt", "text": "Marginal costing is significant for inventory valuation: lower values than absorption", "id": "acfma-rv7-edb86-b8db30"}], "id": "acfma-rv7-edb86"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using actual figures to set the OAR", "id": "acfma-rv7-6483a-e95f65"}, {"t": "x", "text": "Calling actual overhead above absorbed 'over-absorbed'", "id": "acfma-rv7-6483a-0c99e2"}, {"t": "x", "text": "Leaving service centre costs in service centres", "id": "acfma-rv7-6483a-4f4fd6"}, {"t": "x", "text": "Forgetting that the profit difference depends on the CHANGE in inventory", "id": "acfma-rv7-6483a-e5021e"}], "id": "acfma-rv7-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Overheads: indirect materials, labour, expenses", "id": "acfma-rv7-80e78-e59d3d"}, {"t": "pt", "text": "Allocate, apportion, reapportion, absorb", "id": "acfma-rv7-80e78-c27580"}, {"t": "pt", "text": "Floor area for rent; employees for canteen", "id": "acfma-rv7-80e78-482cd7"}, {"t": "pt", "text": "Service centres reapportioned to production centres", "id": "acfma-rv7-80e78-c225a5"}, {"t": "pt", "text": "OAR = budgeted overhead / budgeted activity", "id": "acfma-rv7-80e78-88c3e1"}, {"t": "pt", "text": "Machine hours for machine-based departments", "id": "acfma-rv7-80e78-61c653"}, {"t": "pt", "text": "Absorbed = actual activity x OAR", "id": "acfma-rv7-80e78-2beb47"}, {"t": "pt", "text": "Under-absorbed: actual > absorbed (reduces profit)", "id": "acfma-rv7-80e78-ec6fd5"}, {"t": "pt", "text": "Over-absorbed: absorbed > actual (increases profit)", "id": "acfma-rv7-80e78-50349b"}, {"t": "pt", "text": "Absorption values inventory at full production cost", "id": "acfma-rv7-80e78-986e59"}, {"t": "pt", "text": "Marginal values inventory at variable cost", "id": "acfma-rv7-80e78-12a3a9"}, {"t": "pt", "text": "Profit difference = Δ inventory x fixed OAR", "id": "acfma-rv7-80e78-c2c4a0"}], "id": "acfma-rv7-80e78"}], "source": "BPP MA1 Text ch 7: sections 1-4 pp128-140", "summary": "Absorption costing: allocation, apportionment and reapportionment of service centre costs, absorption rates and bases, under and over absorption, and inventory and profit under absorption vs marginal costing.", "id": "acfma-rv7", "updated": "2026-11-12"}, {"num": "8", "title": "Job, Batch and Process Costing", "pages": [145, 170], "syllabus": "B6", "status": "published", "branches": [{"kind": "concept", "title": "Job and batch costing", "page": [146, 151], "items": [{"t": "def", "k": 1, "term": "Job costing", "text": "A form of specific order costing where costs are attributed to individual jobs carried out to customer requirements", "id": "acfma-rv8-1a3e6-941a7f"}, {"t": "pt", "text": "Each job has a number and a job account in the work in progress ledger; completed jobs move to finished goods/cost of sales", "id": "acfma-rv8-1a3e6-e5e314"}, {"t": "pt", "text": "Job cost card: direct materials (requisitions), direct labour (job cards), direct expenses, production overhead absorbed, plus admin/selling overheads and profit for pricing", "id": "acfma-rv8-1a3e6-fbe321"}, {"t": "def", "k": 1, "term": "Batch", "text": "A cost unit consisting of a separate, readily identifiable group of product units which maintain their separate identity throughout the production process", "id": "acfma-rv8-1a3e6-a16528"}, {"t": "f", "k": 1, "term": "Cost per unit in a batch", "text": "Total batch cost / Number of units in the batch", "vars": "eg a batch of model cars", "id": "acfma-rv8-1a3e6-ba8892"}], "id": "acfma-rv8-1a3e6"}, {"kind": "process", "title": "Process costing", "page": [152, 158], "items": [{"t": "def", "k": 1, "term": "Process costing", "text": "A costing method used where there is continuous production of identical units through one or more processes", "id": "acfma-rv8-5dd03-ada7bb"}, {"t": "pt", "text": "Features: output of one process is the input to the next; costs collected per process; homogeneous units; losses expected", "id": "acfma-rv8-5dd03-a2bedb"}, {"t": "pt", "k": 1, "text": "Four steps: 1 determine output and losses -> 2 calculate cost per unit -> 3 calculate total cost of output, losses and WIP -> 4 complete the accounts", "id": "acfma-rv8-5dd03-e75481"}, {"t": "f", "k": 1, "term": "Cost per unit (with normal loss)", "text": "Process costs / Expected output", "vars": "expected output = input - normal loss (normal loss has no cost)", "eg": "1,000 units, $4,500, 10% normal loss: $4,500 / 900 = $5 per unit", "id": "acfma-rv8-5dd03-62ad42"}, {"t": "pt", "text": "Normal loss: expected, valued at scrap value (if any), not at cost", "id": "acfma-rv8-5dd03-553e8e"}, {"t": "exam", "text": "Process costing was the subject of two MA1 examining team articles - use the four-step approach to save time", "id": "acfma-rv8-5dd03-9b1924"}], "id": "acfma-rv8-5dd03"}, {"kind": "formula", "title": "Closing work in progress", "page": [159, 163], "items": [{"t": "def", "k": 1, "term": "Equivalent units", "text": "Notional whole units representing incomplete work - used to share costs between finished output and WIP", "id": "acfma-rv8-0dc3a-3502f9"}, {"t": "f", "term": "Equivalent units", "text": "Units of WIP x % complete", "vars": "calculated separately for materials and conversion costs when they are added at different rates", "eg": "400 units 50% complete = 200 EU", "id": "acfma-rv8-0dc3a-c3e72d"}, {"t": "f", "term": "Cost per equivalent unit", "text": "Cost of input / Total equivalent units (finished units + WIP EU)", "vars": "then value finished output and WIP separately", "id": "acfma-rv8-0dc3a-d6c8f1"}, {"t": "pt", "text": "Materials often 100% complete in WIP; labour and overhead partly complete", "id": "acfma-rv8-0dc3a-27d1bf"}, {"t": "exam", "text": "A December 2011 sample question in this area was poorly answered", "id": "acfma-rv8-0dc3a-663e1e"}], "id": "acfma-rv8-0dc3a"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Dividing process costs by input units instead of expected output", "id": "acfma-rv8-6483a-3c09c3"}, {"t": "x", "text": "Giving normal loss a share of process costs", "id": "acfma-rv8-6483a-3a9001"}, {"t": "x", "text": "Using one completion % for all cost elements when materials and conversion differ", "id": "acfma-rv8-6483a-07ebcf"}, {"t": "x", "text": "Treating a batch as a single unit of sale - divide batch cost by units in the batch", "id": "acfma-rv8-6483a-cc393c"}], "id": "acfma-rv8-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Job costing: customer-specific jobs", "id": "acfma-rv8-80e78-88756a"}, {"t": "pt", "text": "Job account in WIP; job cost card summarises costs", "id": "acfma-rv8-80e78-a8ec63"}, {"t": "pt", "text": "Batch = identifiable group of units; cost per unit = batch cost / units", "id": "acfma-rv8-80e78-ea70ff"}, {"t": "pt", "text": "Process costing: continuous identical output", "id": "acfma-rv8-80e78-d30f1a"}, {"t": "pt", "text": "Output of one process = input to the next", "id": "acfma-rv8-80e78-cd233b"}, {"t": "pt", "text": "Four steps: output/losses, cost per unit, total costs, accounts", "id": "acfma-rv8-80e78-16b021"}, {"t": "pt", "text": "Expected output = input - normal loss", "id": "acfma-rv8-80e78-9a7fc9"}, {"t": "pt", "text": "Normal loss: no cost, scrap value only", "id": "acfma-rv8-80e78-3dc312"}, {"t": "pt", "text": "Cost per unit = process costs / expected output", "id": "acfma-rv8-80e78-e6cec8"}, {"t": "pt", "text": "Equivalent units = WIP units x % complete", "id": "acfma-rv8-80e78-a46ee0"}, {"t": "pt", "text": "Separate EU for materials and conversion", "id": "acfma-rv8-80e78-62b68b"}, {"t": "pt", "text": "Cost per EU = cost / total EU", "id": "acfma-rv8-80e78-dd26a8"}], "id": "acfma-rv8-80e78"}], "source": "BPP MA1 Text ch 8: sections 1-6 pp146-163", "summary": "Job costing (job accounts and cost cards), batch costing, features of process costing, the four-step approach, normal losses, and equivalent units for closing work in progress.", "id": "acfma-rv8", "updated": "2026-11-12"}, {"num": "9", "title": "The Basics of Using Spreadsheets", "pages": [171, 200], "syllabus": "C1", "status": "published", "branches": [{"kind": "concept", "title": "Spreadsheet basics", "page": [173, 176], "items": [{"t": "def", "k": 1, "term": "Spreadsheet", "text": "An electronic piece of paper divided into rows and columns; each intersection is a cell holding text, values or formulae", "id": "acfma-rv9-fea22-0238a8"}, {"t": "pt", "text": "Why use them: calculate, analyse and manipulate numerical data; automatic recalculation; what-if analysis", "id": "acfma-rv9-fea22-eeb9ff"}, {"t": "pt", "text": "File menu: New (blank workbook), Open, Save (overwrites), Save As (new name, location or format)", "id": "acfma-rv9-fea22-bf0852"}, {"t": "pt", "text": "Navigation: cell references (column letter + row number, eg B3), ranges (A1:C10), worksheets in a workbook", "id": "acfma-rv9-fea22-9ade23"}, {"t": "exam", "text": "The December 2011 examiner singled out spreadsheets as an area of weakness", "id": "acfma-rv9-fea22-48bca1"}], "id": "acfma-rv9-fea22"}, {"kind": "rule", "title": "Security issues", "page": [183, 184], "items": [{"t": "pt", "k": 1, "text": "Cell protection/locking prevents users changing important cells (eg formulae)", "id": "acfma-rv9-2cd5e-26bbeb"}, {"t": "pt", "text": "Password protection restricts opening or modifying files", "id": "acfma-rv9-2cd5e-2b7dbf"}, {"t": "pt", "text": "Back-ups and version control prevent loss and confusion", "id": "acfma-rv9-2cd5e-b09ef7"}, {"t": "pt", "text": "Hidden rows/columns and sheets can hide data from casual users (not a strong control)", "id": "acfma-rv9-2cd5e-af6056"}], "id": "acfma-rv9-2cd5e"}, {"kind": "formula", "title": "Formulae and functions", "page": [185, 192], "items": [{"t": "pt", "k": 1, "text": "All Excel formulae start with = (eg =B6*0.175)", "id": "acfma-rv9-2be54-6b196f"}, {"t": "pt", "text": "Operators: + - * / ^ ; brackets change the order of operations: =(5+2)*3 = 21", "id": "acfma-rv9-2be54-d09fec"}, {"t": "f", "k": 1, "term": "SUM", "text": "=SUM(range)", "vars": "adds a range", "eg": "=SUM(E6:E7)", "id": "acfma-rv9-2be54-8c90e5"}, {"t": "f", "k": 1, "term": "IF", "text": "=IF(condition, value if true, value if false)", "vars": "conditional formulae", "eg": "=IF(B2>=1000, B2*0.95, B2) gives a 5% discount on orders of $1,000 or more", "id": "acfma-rv9-2be54-db9b13"}, {"t": "f", "term": "ROUND", "text": "=ROUND(number, number of decimal places)", "vars": "removes apparent rounding errors in totals", "id": "acfma-rv9-2be54-dc3ae3"}, {"t": "pt", "text": "Other functions: AVERAGE, MAX, MIN, COUNT; dates stored as serial numbers so they can be calculated", "id": "acfma-rv9-2be54-cf6cfb"}, {"t": "pt", "k": 1, "text": "Relative reference (B3) changes when copied; absolute reference ($B$3) stays fixed; mixed ($B3 or B$3) fixes one part", "id": "acfma-rv9-2be54-a462eb"}, {"t": "pt", "text": "Inserting or deleting rows and columns: formulae adjust automatically, but check SUM ranges", "id": "acfma-rv9-2be54-8a30a9"}, {"t": "exam", "text": "Identifying the correct formula for a cell could easily be an exam question", "id": "acfma-rv9-2be54-ee4bfe"}], "id": "acfma-rv9-2be54"}, {"kind": "concept", "title": "Errors in formulae", "page": [195, 197], "items": [{"t": "pt", "k": 1, "text": "Circular reference: a formula refers (directly or indirectly) to its own cell - usually a mistake", "id": "acfma-rv9-049f5-74750c"}, {"t": "pt", "text": "Error values", "kids": [{"t": "pt", "text": "#DIV/0! - division by zero", "id": "acfma-rv9-049f5-5ae539"}, {"t": "pt", "text": "#VALUE! - wrong type of argument (eg text in a calculation)", "id": "acfma-rv9-049f5-7224d6"}, {"t": "pt", "text": "#REF! - invalid cell reference (eg a deleted cell)", "id": "acfma-rv9-049f5-79c19f"}, {"t": "pt", "text": "#NAME? - unrecognised text (eg misspelt function)", "id": "acfma-rv9-049f5-4f7acb"}, {"t": "pt", "text": "#N/A - value not available", "id": "acfma-rv9-049f5-8d0a5d"}, {"t": "pt", "text": "#NUM! - invalid number", "id": "acfma-rv9-049f5-1cc83b"}, {"t": "pt", "text": "#### - column too narrow to display the value", "id": "acfma-rv9-049f5-f5464a"}], "id": "acfma-rv9-049f5-c1a3db"}, {"t": "pt", "text": "Errors should be identified, investigated and corrected - use formula auditing tools", "id": "acfma-rv9-049f5-63550c"}], "id": "acfma-rv9-049f5"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Forgetting the = sign at the start of a formula", "id": "acfma-rv9-6483a-547d91"}, {"t": "x", "text": "Copying a formula with a relative reference that should have been absolute (eg a tax rate cell)", "id": "acfma-rv9-6483a-8ce9c7"}, {"t": "x", "text": "Mis-ordering IF arguments - the TRUE result comes before the FALSE result", "id": "acfma-rv9-6483a-0b2d76"}, {"t": "x", "text": "Reading #### as an error in the formula - the column is just too narrow", "id": "acfma-rv9-6483a-7cf090"}], "id": "acfma-rv9-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Spreadsheet = rows, columns, cells", "id": "acfma-rv9-80e78-70ebd2"}, {"t": "pt", "text": "Cells hold text, values or formulae", "id": "acfma-rv9-80e78-5e605c"}, {"t": "pt", "text": "Formulae begin with =", "id": "acfma-rv9-80e78-6d1edf"}, {"t": "pt", "text": "Brackets control order of operations", "id": "acfma-rv9-80e78-0b85ef"}, {"t": "pt", "text": "=SUM(range); =IF(test, true, false); =ROUND(number, digits)", "id": "acfma-rv9-80e78-3d5c8a"}, {"t": "pt", "text": "Relative refs change when copied; absolute ($A$1) do not", "id": "acfma-rv9-80e78-c90f2f"}, {"t": "pt", "text": "Cell protection stops changes to key cells", "id": "acfma-rv9-80e78-547926"}, {"t": "pt", "text": "Passwords restrict access", "id": "acfma-rv9-80e78-7cd432"}, {"t": "pt", "text": "Circular reference = formula refers to itself", "id": "acfma-rv9-80e78-4cc10a"}, {"t": "pt", "text": "#DIV/0! = divide by zero", "id": "acfma-rv9-80e78-3621de"}, {"t": "pt", "text": "#REF! = invalid reference", "id": "acfma-rv9-80e78-fe907e"}, {"t": "pt", "text": "#NAME? = unrecognised text", "id": "acfma-rv9-80e78-51d869"}, {"t": "pt", "text": "#### = column too narrow", "id": "acfma-rv9-80e78-6ed75e"}], "id": "acfma-rv9-80e78"}], "source": "BPP MA1 Text ch 9: sections 1-4 pp173-197", "summary": "What spreadsheets are and why they are used, basic file and navigation skills, security (cell protection, passwords), formulae and functions (SUM, IF, ROUND, dates), relative and absolute references, and identifying and correcting errors.", "id": "acfma-rv9", "updated": "2026-11-12"}, {"num": "10", "title": "Using Spreadsheets to Present Information", "pages": [201, 226], "syllabus": "C2", "status": "published", "branches": [{"kind": "compare", "title": "Charts and graphs", "page": [202, 212], "items": [{"t": "table", "rows": [["Type", "Best for", "Note"], ["Simple column/bar chart", "Comparing magnitudes (eg expenditure by year)", "One of the most common methods"], ["Component (stacked) column chart", "Showing totals and their components", "Bar height = total"], ["Line graph", "Trends over time", "Widely used in commercial contexts"], ["Area chart", "Trends with emphasis on volume", "Like a line graph with shading"], ["Pie chart", "Relative size of components of a total", "360° = 100%"], ["Scatter diagram", "Relationship between two variables", "Can add a trend line"], ["Table", "Precise numerical information", "Rows and columns with clear titles"]], "id": "acfma-rv10-3c094-69b17a"}, {"t": "pt", "k": 1, "text": "Charts, graphs and tables are often excellent ways of communicating information", "id": "acfma-rv10-3c094-eb0906"}, {"t": "exam", "text": "You will NOT be required to prepare a graph in the exam - expect questions on how charts are used and interpreted", "id": "acfma-rv10-3c094-74325d"}, {"t": "exam", "text": "The presentation of information using charts was the subject of an examining team article", "id": "acfma-rv10-3c094-3a7d6e"}], "id": "acfma-rv10-3c094"}, {"kind": "process", "title": "Producing charts in Excel", "page": [212, 215], "items": [{"t": "pt", "text": "Select the data range -> choose a chart type from the Charts group -> add titles, axis labels, legend", "id": "acfma-rv10-56523-2a8641"}, {"t": "pt", "text": "Charts can be changed after creation: type, data range, formatting, titles", "id": "acfma-rv10-56523-94e0ad"}, {"t": "pt", "text": "Choose the chart that suits the message (trend -> line; composition -> pie or stacked column)", "id": "acfma-rv10-56523-b01684"}], "id": "acfma-rv10-56523"}, {"kind": "concept", "title": "Format and appearance", "page": [215, 220], "items": [{"t": "pt", "k": 1, "text": "A spreadsheet should have a title that clearly defines its purpose, plus clear row and column labels", "id": "acfma-rv10-44cdd-61105f"}, {"t": "pt", "text": "Freezing titles keeps headings visible when scrolling; splitting the screen shows different parts together", "id": "acfma-rv10-44cdd-addeb2"}, {"t": "pt", "text": "Number formatting: commas, currency, percentages, decimal places; gridlines on or off", "id": "acfma-rv10-44cdd-73808d"}, {"t": "pt", "text": "Data manipulation: sorting, filtering, subtotals, conditional formatting", "id": "acfma-rv10-44cdd-5db9d0"}], "id": "acfma-rv10-44cdd"}, {"kind": "concept", "title": "Linking and multi-sheet spreadsheets", "page": [221, 224], "items": [{"t": "pt", "text": "Spreadsheets can be linked with word processing documents (eg a report that updates from a spreadsheet)", "id": "acfma-rv10-414bb-5351bc"}, {"t": "pt", "text": "Formulae spanning files need care - moving or renaming the source breaks links", "id": "acfma-rv10-414bb-a09775"}, {"t": "pt", "k": 1, "text": "Multi-sheet (three-dimensional) workbooks: one sheet per period, department or scenario, with a summary sheet linked by formulae (eg =Sheet1!B5)", "id": "acfma-rv10-414bb-32b128"}, {"t": "pt", "text": "Uses: consolidating departmental budgets, monthly sheets summed into an annual sheet", "id": "acfma-rv10-414bb-d05716"}], "id": "acfma-rv10-414bb"}, {"kind": "concept", "title": "Uses and design", "page": [224, 226], "items": [{"t": "pt", "k": 1, "text": "Uses by management accountants: budgets, forecasts, cash flow projections, variance analysis, what-if analysis, reports and charts", "id": "acfma-rv10-835e6-9b79f9"}, {"t": "pt", "text": "Design considerations: one-time vs repeated use; used by the creator vs by others (needs documentation, protection, clear inputs); single vs multiple sheets; consistent layout across sheets", "id": "acfma-rv10-835e6-b09a33"}, {"t": "pt", "text": "Good design separates inputs, calculations and outputs and avoids hard-coded numbers inside formulae", "id": "acfma-rv10-835e6-d8c09b"}, {"t": "exam", "text": "The June 2012 examiner's report used spreadsheet uses as an example of a weak area", "id": "acfma-rv10-835e6-c8b1d8"}], "id": "acfma-rv10-835e6"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using a pie chart to show a trend over time - use a line graph", "id": "acfma-rv10-6483a-8f6ec3"}, {"t": "x", "text": "Expecting to draw charts in the CBE - questions test interpretation and choice", "id": "acfma-rv10-6483a-fc2a53"}, {"t": "x", "text": "Hard-coding values in formulae so changes are not picked up", "id": "acfma-rv10-6483a-627b6f"}, {"t": "x", "text": "Moving a linked source file and breaking formulae in other files", "id": "acfma-rv10-6483a-fb4196"}], "id": "acfma-rv10-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Column/bar: compare magnitudes", "id": "acfma-rv10-80e78-f0bb1e"}, {"t": "pt", "text": "Component (stacked) column: totals and parts", "id": "acfma-rv10-80e78-d3fd77"}, {"t": "pt", "text": "Line graph: trends over time", "id": "acfma-rv10-80e78-a31808"}, {"t": "pt", "text": "Pie chart: shares of a total (360° = 100%)", "id": "acfma-rv10-80e78-76f4e9"}, {"t": "pt", "text": "Scatter: relationship between two variables", "id": "acfma-rv10-80e78-4a908f"}, {"t": "pt", "text": "Tables: precise figures", "id": "acfma-rv10-80e78-bdb134"}, {"t": "pt", "text": "No graph drawing in the exam", "id": "acfma-rv10-80e78-a2a942"}, {"t": "pt", "text": "Title and labels make purpose clear", "id": "acfma-rv10-80e78-3e3b99"}, {"t": "pt", "text": "Freeze panes keeps headings visible", "id": "acfma-rv10-80e78-5f01b1"}, {"t": "pt", "text": "Multi-sheet workbooks: summary sheet links detail sheets", "id": "acfma-rv10-80e78-d9245e"}, {"t": "pt", "text": "Uses: budgets, forecasts, variances, what-if", "id": "acfma-rv10-80e78-c18996"}, {"t": "pt", "text": "Design: separate inputs, workings and outputs", "id": "acfma-rv10-80e78-b614b9"}, {"t": "pt", "text": "Document and protect sheets used by others", "id": "acfma-rv10-80e78-0f5411"}], "id": "acfma-rv10-80e78"}], "source": "BPP MA1 Text ch 10: sections 1-7 pp202-226", "summary": "Charts, graphs and tables (column/bar, component, line, area, pie, scatter), producing charts in Excel, spreadsheet format and appearance, data manipulation, linking files and sheets, uses by management accountants and spreadsheet design.", "id": "acfma-rv10", "updated": "2026-11-12"}], "plannedChapters": 10}, {"id": "acfma2", "code": "MA2", "name": "Managing Costs and Finances", "level": "Foundations in Accountancy", "book": "ACCA-MA2-ST.pdf | BPP FIA MA2 Interactive Text (scanned) | offset 10", "updated": "2026-11-13", "note": "The MA2 study text in the portal is a scanned PDF with no text layer. Maps were built from an OCR reading of every page (Windows OCR) cross-checked against chapter structure; page references are the book's printed numbers.", "chapters": [{"num": "1", "title": "Management Information", "pages": [3, 26], "syllabus": "A1, A2", "status": "published", "branches": [{"kind": "concept", "title": "Purpose of management information", "page": [4, 8], "items": [{"t": "pt", "k": 1, "text": "Managers need information to plan, control and make decisions", "id": "acfma2-rv1-4c3d1-91b7d9"}, {"t": "def", "term": "Planning", "text": "Establishing an objective or identifying a problem and choosing a strategy to achieve the objective or alleviate the problem", "id": "acfma2-rv1-4c3d1-c70f3c"}, {"t": "def", "term": "Control", "text": "Monitoring something in order to keep it on course - comparing actual with plan and taking action", "id": "acfma2-rv1-4c3d1-7f0483"}, {"t": "def", "term": "Decision making", "text": "Choosing between various alternatives - linked to planning", "id": "acfma2-rv1-4c3d1-a1e266"}, {"t": "pt", "k": 1, "text": "Good information (ACCURATE): accurate • complete • cost-beneficial • user-targeted • relevant • authoritative • timely • easy to use", "id": "acfma2-rv1-4c3d1-aeda54"}], "id": "acfma2-rv1-4c3d1"}, {"kind": "concept", "title": "Sources of information", "page": [8, 11], "items": [{"t": "pt", "text": "Internal: accounting records (ledgers, cash book), payroll, production and sales records, staff", "id": "acfma2-rv1-068b3-fa371e"}, {"t": "pt", "text": "External: suppliers, customers, government statistics, trade journals, the internet", "id": "acfma2-rv1-068b3-c534b7"}, {"t": "pt", "k": 1, "text": "Information can be financial, non-financial, or a combination", "id": "acfma2-rv1-068b3-01a627"}, {"t": "pt", "k": 1, "text": "Management information is a common source for financial accounts (external users) and management accounts (internal users)", "id": "acfma2-rv1-068b3-9f856a"}, {"t": "pt", "text": "Management accounts: format entirely at management's discretion; cost accounts are part of management accounts", "id": "acfma2-rv1-068b3-7e6923"}], "id": "acfma2-rv1-068b3"}, {"kind": "concept", "title": "Costs, cost units and centres", "page": [13, 17], "items": [{"t": "def", "k": 1, "term": "Cost unit", "text": "A unit of product or service which has costs attached to it - the basic control unit for costing", "id": "acfma2-rv1-e8dad-aa88a3"}, {"t": "def", "k": 1, "term": "Cost centre", "text": "The essential 'building block' of a costing system - a location, function or item of equipment for which costs are collected", "id": "acfma2-rv1-e8dad-6424d4"}, {"t": "pt", "k": 1, "text": "Direct costs (materials, labour, expenses traced to the unit) = prime cost; indirect costs = overheads", "id": "acfma2-rv1-e8dad-111833"}, {"t": "pt", "k": 1, "text": "Variable costs change with the volume of production; fixed costs do not", "id": "acfma2-rv1-e8dad-ce4cd7"}, {"t": "pt", "text": "Production cost of a pen: plastic, ink, labour and a share of factory overheads", "id": "acfma2-rv1-e8dad-542e9e"}], "id": "acfma2-rv1-e8dad"}, {"kind": "compare", "title": "Costing methods", "page": [17, 18], "items": [{"t": "table", "rows": [["Method", "Used when", "Cost unit"], ["Job costing", "Work to customer's special order", "The job"], ["Batch costing", "Identical items produced as a batch", "The batch (then per unit)"], ["Process costing", "Continuous or repetitive processes, units not separately identifiable", "Unit of process output"], ["Service costing", "Service organisations - no tangible goods", "Composite unit (eg patient day)"]], "id": "acfma2-rv1-b91f7-2a6361"}, {"t": "pt", "text": "Whatever method is used, overheads must still be attributed to units (absorption)", "id": "acfma2-rv1-b91f7-9fbc3d"}], "id": "acfma2-rv1-b91f7"}, {"kind": "concept", "title": "Coding", "page": [20, 22], "items": [{"t": "pt", "k": 1, "text": "Each account/cost is given a code so it can be classified and processed (eg a four-digit code: department + type of cost)", "id": "acfma2-rv1-70994-70bad1"}, {"t": "pt", "text": "Types of code: sequential, block, significant digit, hierarchical, faceted, mnemonic", "id": "acfma2-rv1-70994-eb5f78"}, {"t": "pt", "k": 1, "text": "Advantages: briefer than a description (saves clerical time and storage), less ambiguous, easier computer processing and analysis", "id": "acfma2-rv1-70994-07a6e0"}, {"t": "exam", "text": "Questions often ask for the correct code for a transaction given a coding table", "id": "acfma2-rv1-70994-0176ec"}], "id": "acfma2-rv1-70994"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Confusing a cost unit (output) with a cost centre (where costs are collected)", "id": "acfma2-rv1-6483a-82c02e"}, {"t": "x", "text": "Classifying production overheads as prime cost", "id": "acfma2-rv1-6483a-a76d80"}, {"t": "x", "text": "Using job costing for continuous process production", "id": "acfma2-rv1-6483a-bb5cc7"}, {"t": "x", "text": "Thinking management accounts must follow a set legal format", "id": "acfma2-rv1-6483a-175d22"}], "id": "acfma2-rv1-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Information for planning, control and decisions", "id": "acfma2-rv1-80e78-00865d"}, {"t": "pt", "text": "ACCURATE qualities of good information", "id": "acfma2-rv1-80e78-5a0f16"}, {"t": "pt", "text": "Internal and external sources", "id": "acfma2-rv1-80e78-e67cf3"}, {"t": "pt", "text": "Financial, non-financial or combined information", "id": "acfma2-rv1-80e78-ebfc81"}, {"t": "pt", "text": "Management accounts: format at management's discretion", "id": "acfma2-rv1-80e78-bfcb5b"}, {"t": "pt", "text": "Cost unit = unit of output with costs attached", "id": "acfma2-rv1-80e78-d93f51"}, {"t": "pt", "text": "Cost centre = building block of a costing system", "id": "acfma2-rv1-80e78-838d57"}, {"t": "pt", "text": "Prime cost = direct materials + labour + expenses", "id": "acfma2-rv1-80e78-c242fb"}, {"t": "pt", "text": "Overheads = indirect costs", "id": "acfma2-rv1-80e78-ceb41a"}, {"t": "pt", "text": "Costing methods: job, batch, process, service", "id": "acfma2-rv1-80e78-dad750"}, {"t": "pt", "text": "Codes: brief, unambiguous, aid processing", "id": "acfma2-rv1-80e78-f86ae1"}, {"t": "pt", "text": "Code types: sequential, block, hierarchical, faceted, mnemonic", "id": "acfma2-rv1-80e78-5d9673"}], "id": "acfma2-rv1-80e78"}], "source": "BPP MA2 Text ch 1 (OCR): sections 1-8 pp4-22", "summary": "Purpose and qualities of management information, sources, financial vs management vs cost accounts, cost units, cost centres, direct and indirect costs, fixed and variable costs, costing methods and coding.", "id": "acfma2-rv1", "updated": "2026-11-13"}, {"num": "2", "title": "The Role of Information Technology", "pages": [27, 36], "syllabus": "A3", "status": "published", "branches": [{"kind": "concept", "title": "Advantages of computers", "page": [29, 29], "items": [{"t": "pt", "k": 1, "text": "Computers are widely used for data processing because of their speed, accuracy, ability to handle large volumes, storage capacity and consistency", "id": "acfma2-rv2-65cbe-a700f5"}, {"t": "pt", "text": "Limitations: no judgement (garbage in, garbage out), cost, reliance on systems and data security", "id": "acfma2-rv2-65cbe-18dc1f"}], "id": "acfma2-rv2-65cbe"}, {"kind": "compare", "title": "Input, storage and output", "page": [30, 32], "items": [{"t": "table", "rows": [["Category", "Examples", "Note"], ["Direct input", "Keyboard (typing and numeric keys), touch screen, voice recognition", "Keyboard is the principal method of direct data entry"], ["Automatic input", "Document reading (OCR, MICR, bar codes), card readers (magnetic stripe, smart/chip cards)", "Fast and accurate for high volumes"], ["Storage", "Hard disks (direct access), CD/DVD, memory sticks (USB drives), cloud", "Back-up copies held separately"], ["Output", "Printers (laser = whole page, high quality), VDU/monitor screens", "Choice depends on purpose"]], "id": "acfma2-rv2-d7a4c-6a33d5"}, {"t": "pt", "k": 1, "text": "Choice of output medium depends on: whether a hard copy is needed, volume, speed, quality, the number of users, confidentiality and cost", "id": "acfma2-rv2-d7a4c-c026cd"}, {"t": "def", "term": "Touch screen", "text": "A display screen that enables users to make selections by touching areas of the screen", "id": "acfma2-rv2-d7a4c-79fe33"}, {"t": "pt", "text": "A VDU (monitor) displays text and graphics and lets users check data visually", "id": "acfma2-rv2-d7a4c-42b62e"}], "id": "acfma2-rv2-d7a4c"}, {"kind": "concept", "title": "Management information systems", "page": [33, 34], "items": [{"t": "def", "k": 1, "term": "Management information system (MIS)", "text": "A collective term for the hardware and software used to drive a database system whose outputs are both operational and management information", "id": "acfma2-rv2-53fa6-f6572b"}, {"t": "pt", "text": "Management should formally plan an MIS rather than let it develop haphazardly", "id": "acfma2-rv2-53fa6-9497f3"}, {"t": "pt", "k": 1, "text": "Essential characteristics: provide information that is relevant, timely, accurate and at the right level of detail for each level of management; flexible; cost-effective", "id": "acfma2-rv2-53fa6-db7397"}, {"t": "pt", "text": "MIS supports planning, control and decision making at strategic, tactical and operational levels", "id": "acfma2-rv2-53fa6-bae431"}, {"t": "exam", "text": "Expect questions on which input device suits a situation (eg bar codes at a supermarket checkout)", "id": "acfma2-rv2-53fa6-1efe71"}], "id": "acfma2-rv2-53fa6"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Thinking computers prevent input errors - garbage in, garbage out", "id": "acfma2-rv2-6483a-c4af22"}, {"t": "x", "text": "Choosing printed output where on-screen enquiry is enough (cost and confidentiality)", "id": "acfma2-rv2-6483a-5cda28"}, {"t": "x", "text": "Treating an MIS as only hardware - it is hardware, software and the information outputs", "id": "acfma2-rv2-6483a-9c64e6"}, {"t": "x", "text": "Forgetting back-up of stored data", "id": "acfma2-rv2-6483a-58b00b"}], "id": "acfma2-rv2-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Computers: speed, accuracy, volume, storage", "id": "acfma2-rv2-80e78-f6b315"}, {"t": "pt", "text": "No judgement: garbage in, garbage out", "id": "acfma2-rv2-80e78-c5b9df"}, {"t": "pt", "text": "Keyboard: main direct entry", "id": "acfma2-rv2-80e78-22b869"}, {"t": "pt", "text": "Automatic input: OCR, MICR, bar codes, card readers", "id": "acfma2-rv2-80e78-e941f0"}, {"t": "pt", "text": "Touch screens and voice recognition", "id": "acfma2-rv2-80e78-151b40"}, {"t": "pt", "text": "Storage: hard disk, DVD, memory stick, cloud", "id": "acfma2-rv2-80e78-624d81"}, {"t": "pt", "text": "Laser printer: whole page, high quality", "id": "acfma2-rv2-80e78-2de591"}, {"t": "pt", "text": "Output choice: hard copy, volume, speed, quality, users, cost", "id": "acfma2-rv2-80e78-9a4d21"}, {"t": "pt", "text": "MIS = hardware and software producing operational and management information", "id": "acfma2-rv2-80e78-596d6e"}, {"t": "pt", "text": "Plan the MIS formally", "id": "acfma2-rv2-80e78-7eadc8"}, {"t": "pt", "text": "MIS: relevant, timely, accurate, right detail", "id": "acfma2-rv2-80e78-68d517"}, {"t": "pt", "text": "Back up stored data", "id": "acfma2-rv2-80e78-1276f1"}], "id": "acfma2-rv2-80e78"}], "source": "BPP MA2 Text ch 2 (OCR): sections 1-5 pp29-34", "summary": "Advantages of computers, input devices, storage media, output devices and the choice of medium, and management information systems (MIS).", "id": "acfma2-rv2", "updated": "2026-11-13"}, {"num": "3", "title": "Cost Classification", "pages": [37, 46], "syllabus": "B1", "status": "published", "branches": [{"kind": "formula", "title": "Direct costs", "page": [38, 40], "items": [{"t": "f", "k": 1, "term": "Prime cost", "text": "Direct material cost + Direct labour cost + Direct expenses", "vars": "the total of direct costs", "id": "acfma2-rv3-14127-9892fc"}, {"t": "def", "k": 1, "term": "Direct material", "text": "All material becoming part of the product (unless used in negligible amounts and/or having negligible cost)", "id": "acfma2-rv3-14127-16cd51"}, {"t": "def", "term": "Direct labour", "text": "The specific costs of the workforce used to make a product or provide a service", "id": "acfma2-rv3-14127-d73973"}, {"t": "def", "term": "Direct expenses", "text": "Expenses incurred on a specific product other than direct material and direct labour (eg hire of special equipment)", "id": "acfma2-rv3-14127-81bcc2"}], "id": "acfma2-rv3-14127"}, {"kind": "concept", "title": "Overheads", "page": [40, 41], "items": [{"t": "def", "k": 1, "term": "Indirect cost (overhead)", "text": "A cost incurred in making a product or providing a service that cannot be traced directly and in full to it", "id": "acfma2-rv3-5852c-a26d79"}, {"t": "pt", "k": 1, "text": "Production (factory) overhead: indirect materials, wages and expenses in the factory", "id": "acfma2-rv3-5852c-29a6e9"}, {"t": "pt", "text": "Administration overhead: indirect costs of administration (eg depreciation of office buildings and equipment)", "id": "acfma2-rv3-5852c-41ec8a"}, {"t": "pt", "text": "Selling overhead: promoting sales and retaining customers (eg printing catalogues and price lists)", "id": "acfma2-rv3-5852c-dd732c"}, {"t": "pt", "text": "Distribution overhead: making the packed product ready for despatch and delivering it (eg wages of packers, drivers, despatch clerks)", "id": "acfma2-rv3-5852c-f235ca"}, {"t": "f", "term": "Total cost", "text": "Prime cost + Production overhead + Administration + Selling + Distribution overheads", "vars": "production cost = prime cost + production overhead", "id": "acfma2-rv3-5852c-70c6ec"}], "id": "acfma2-rv3-5852c"}, {"kind": "concept", "title": "Controllability", "page": [44, 44], "items": [{"t": "def", "k": 1, "term": "Controllable cost", "text": "A cost that can be influenced by a manager within a given time period", "id": "acfma2-rv3-54bdc-9127cd"}, {"t": "pt", "k": 1, "text": "Most variable costs are controllable in the short term (managers influence usage)", "id": "acfma2-rv3-54bdc-edaae2"}, {"t": "pt", "text": "Fixed costs are often assumed uncontrollable in the short run - not always so (eg discretionary spending)", "id": "acfma2-rv3-54bdc-3414dc"}, {"t": "pt", "text": "Managers should be judged only on costs they can control", "id": "acfma2-rv3-54bdc-fd4e1a"}, {"t": "exam", "text": "Expect MCQs classifying a cost into direct, production overhead, administration, selling or distribution", "id": "acfma2-rv3-54bdc-d3c035"}], "id": "acfma2-rv3-54bdc"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Classifying packers' wages as selling overhead - they are distribution overhead", "id": "acfma2-rv3-6483a-4b0537"}, {"t": "x", "text": "Treating negligible-cost materials (glue, thread) as direct material - usually indirect", "id": "acfma2-rv3-6483a-dcc92a"}, {"t": "x", "text": "Assuming every fixed cost is uncontrollable", "id": "acfma2-rv3-6483a-a078e5"}, {"t": "x", "text": "Forgetting direct expenses in prime cost", "id": "acfma2-rv3-6483a-05413a"}], "id": "acfma2-rv3-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Prime cost = direct materials + labour + expenses", "id": "acfma2-rv3-80e78-c242fb"}, {"t": "pt", "text": "Direct material: becomes part of the product", "id": "acfma2-rv3-80e78-e12504"}, {"t": "pt", "text": "Direct labour: workforce making the product", "id": "acfma2-rv3-80e78-6962d2"}, {"t": "pt", "text": "Direct expenses: specific to a product", "id": "acfma2-rv3-80e78-5a51d2"}, {"t": "pt", "text": "Overhead = indirect cost", "id": "acfma2-rv3-80e78-e8e2f8"}, {"t": "pt", "text": "Production overhead: indirect factory costs", "id": "acfma2-rv3-80e78-ea0da6"}, {"t": "pt", "text": "Administration: office costs and depreciation of office assets", "id": "acfma2-rv3-80e78-bf426d"}, {"t": "pt", "text": "Selling: catalogues, sales staff, advertising", "id": "acfma2-rv3-80e78-296bc8"}, {"t": "pt", "text": "Distribution: packers, drivers, despatch", "id": "acfma2-rv3-80e78-0eb1b1"}, {"t": "pt", "text": "Production cost = prime cost + production overhead", "id": "acfma2-rv3-80e78-04938d"}, {"t": "pt", "text": "Controllable cost: influenced by the manager", "id": "acfma2-rv3-80e78-c40d82"}, {"t": "pt", "text": "Variable costs mostly controllable short term", "id": "acfma2-rv3-80e78-fff137"}], "id": "acfma2-rv3-80e78"}], "source": "BPP MA2 Text ch 3 (OCR): sections 1-5 pp38-46", "summary": "Total cost build-up, direct material, labour and expenses, production, administration, selling and distribution overheads, functional classification and the controllability of costs.", "id": "acfma2-rv3", "updated": "2026-11-13"}, {"num": "4", "title": "Cost Behaviour", "pages": [47, 64], "syllabus": "B2", "status": "published", "branches": [{"kind": "concept", "title": "Cost behaviour patterns", "page": [48, 55], "items": [{"t": "pt", "k": 1, "text": "Basic principle: as the level of activity rises, total costs usually rise; the major influence on cost is volume of output", "id": "acfma2-rv4-8b535-51c701"}, {"t": "pt", "text": "Measures of activity: units produced, invoices issued, hours worked, kilometres travelled", "id": "acfma2-rv4-8b535-6be049"}, {"t": "def", "k": 1, "term": "Fixed cost", "text": "Unaffected in TOTAL by increases or decreases in the volume of output (a period cost)", "id": "acfma2-rv4-8b535-15656a"}, {"t": "def", "k": 1, "term": "Stepped-fixed cost", "text": "Fixed in nature but only within certain levels of activity (eg rent of extra space)", "id": "acfma2-rv4-8b535-642c5d"}, {"t": "def", "k": 1, "term": "Variable cost", "text": "Varies in TOTAL directly with the volume of output - the cost PER UNIT is constant", "id": "acfma2-rv4-8b535-1835cc"}, {"t": "def", "k": 1, "term": "Semi-variable (semi-fixed, mixed) cost", "text": "Contains both fixed and variable components (eg electricity standing charge + usage; basic salary + commission)", "id": "acfma2-rv4-8b535-27f3fd"}, {"t": "eg", "text": "Company cars: road tax and insurance fixed; petrol, oil, repairs vary with kilometres", "id": "acfma2-rv4-8b535-31df0e"}, {"t": "pt", "text": "Cost per unit: fixed cost per unit falls as activity rises; total cost per unit therefore falls", "id": "acfma2-rv4-8b535-79fb0b"}], "id": "acfma2-rv4-8b535"}, {"kind": "formula", "title": "The high-low method", "page": [56, 58], "items": [{"t": "pt", "k": 1, "text": "Assumption: within the normal (relevant) range of output, costs are fixed, variable or semi-variable and behave linearly", "id": "acfma2-rv4-85c47-c96b41"}, {"t": "pt", "k": 1, "text": "Steps: identify the periods of HIGHEST and LOWEST ACTIVITY -> difference in cost / difference in activity = variable cost per unit -> fixed cost = total cost - (activity x variable cost per unit)", "id": "acfma2-rv4-85c47-7e7d0b"}, {"t": "f", "k": 1, "term": "Variable cost per unit", "text": "(Total cost at highest activity - Total cost at lowest activity) / (Highest activity - Lowest activity)", "vars": "DG Co: (170,000 - 140,000) / (90,000 - 60,000) = $1 per unit", "id": "acfma2-rv4-85c47-59a1a2"}, {"t": "f", "term": "Fixed cost", "text": "Total cost at either level - (Units x Variable cost per unit)", "vars": "170,000 - 90,000 x $1 = $80,000", "id": "acfma2-rv4-85c47-531bba"}, {"t": "f", "term": "Cost estimate", "text": "Fixed cost + Variable cost per unit x Activity", "vars": "used to forecast costs at another level", "id": "acfma2-rv4-85c47-24853f"}, {"t": "exam", "text": "Use the highest and lowest ACTIVITY levels, not the highest and lowest costs", "id": "acfma2-rv4-85c47-701f2b"}], "id": "acfma2-rv4-85c47"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Selecting the highest and lowest costs instead of activity", "id": "acfma2-rv4-6483a-18a655"}, {"t": "x", "text": "Saying variable cost per unit rises with output - it is constant", "id": "acfma2-rv4-6483a-0a7d82"}, {"t": "x", "text": "Forgetting the fixed element of a semi-variable cost when forecasting", "id": "acfma2-rv4-6483a-9dd5c0"}, {"t": "x", "text": "Applying the high-low result outside the relevant range without caution", "id": "acfma2-rv4-6483a-e39143"}], "id": "acfma2-rv4-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Activity is the main influence on cost", "id": "acfma2-rv4-80e78-7841bb"}, {"t": "pt", "text": "Fixed: constant in total, falls per unit", "id": "acfma2-rv4-80e78-701725"}, {"t": "pt", "text": "Stepped-fixed: fixed within activity ranges", "id": "acfma2-rv4-80e78-497cea"}, {"t": "pt", "text": "Variable: rises in total, constant per unit", "id": "acfma2-rv4-80e78-9527a3"}, {"t": "pt", "text": "Semi-variable: fixed + variable elements", "id": "acfma2-rv4-80e78-9a3290"}, {"t": "pt", "text": "Relevant range assumption", "id": "acfma2-rv4-80e78-67446b"}, {"t": "pt", "text": "High-low: highest and lowest activity", "id": "acfma2-rv4-80e78-fbb247"}, {"t": "pt", "text": "VC per unit = Δcost / Δactivity", "id": "acfma2-rv4-80e78-5d12a4"}, {"t": "pt", "text": "FC = total cost - activity x VC", "id": "acfma2-rv4-80e78-9d2358"}, {"t": "pt", "text": "Forecast = FC + VC x activity", "id": "acfma2-rv4-80e78-c3b49e"}, {"t": "pt", "text": "Fixed cost per unit falls as output rises", "id": "acfma2-rv4-80e78-e5ee51"}, {"t": "pt", "text": "Graphs: fixed horizontal, variable from origin, mixed above origin", "id": "acfma2-rv4-80e78-a558af"}], "id": "acfma2-rv4-80e78"}], "source": "BPP MA2 Text ch 4 (OCR): sections 1-3 pp48-58", "summary": "Cost behaviour and activity, fixed, stepped-fixed, variable and semi-variable costs, other patterns, cost per unit at different activity levels, assumptions, and the high-low method.", "id": "acfma2-rv4", "updated": "2026-11-13"}, {"num": "5", "title": "Information for Comparison", "pages": [65, 86], "syllabus": "B3", "status": "published", "branches": [{"kind": "concept", "title": "Types of comparison", "page": [66, 69], "items": [{"t": "pt", "k": 1, "text": "Comparisons: with previous periods (beware seasonal fluctuations), with forecasts (eg cash flow forecast), with budgets, and non-financial comparisons", "id": "acfma2-rv5-a0dc1-a3a0f4"}, {"t": "eg", "text": "A Christmas decorations company's December quarter cannot fairly be compared with the September quarter - compare with the same quarter last year", "id": "acfma2-rv5-a0dc1-ce25bd"}, {"t": "eg", "text": "Hospital casualty department: non-financial measures such as waiting times", "id": "acfma2-rv5-a0dc1-449034"}, {"t": "pt", "text": "Long-term goals are divided into objectives (measurable steps) and targets", "id": "acfma2-rv5-a0dc1-4ea948"}, {"t": "pt", "k": 1, "text": "Control cycle: decide goals and objectives -> develop plan -> decide resources and performance standards -> implement -> measure actual results -> compare with goals and take action", "id": "acfma2-rv5-a0dc1-4d69f1"}], "id": "acfma2-rv5-a0dc1"}, {"kind": "formula", "title": "Flexed budgets and percentage variances", "page": [69, 72], "items": [{"t": "pt", "k": 1, "text": "A fixed budget is set for one level of activity; to compare fairly, FLEX the budget to the actual level of activity", "id": "acfma2-rv5-25f9a-91f701"}, {"t": "f", "term": "Flexed budget cost", "text": "Budgeted variable cost per unit x Actual units + Budgeted fixed cost", "vars": "variable costs flex; fixed costs do not", "eg": "3,000 units x $3 = $9,000 variable", "id": "acfma2-rv5-25f9a-1a3a42"}, {"t": "f", "k": 1, "term": "Variance %", "text": "Variance / Budgeted amount x 100%", "vars": "helps decide significance", "eg": "$500 adverse on a budget of $5,000 = 10%", "id": "acfma2-rv5-25f9a-18d12b"}, {"t": "pt", "text": "Comparisons with budgets also help co-ordination (eg sales cannot rise without production capacity)", "id": "acfma2-rv5-25f9a-e3a591"}], "id": "acfma2-rv5-25f9a"}, {"kind": "formula", "title": "Sales and cost variances", "page": [73, 77], "items": [{"t": "f", "k": 1, "term": "Total sales revenue variance", "text": "Actual revenue - Budgeted revenue = Activity (volume) variance + Selling price variance", "id": "acfma2-rv5-d309d-b23a74"}, {"t": "f", "k": 1, "term": "Sales activity (volume) variance", "text": "(Actual units - Budgeted units) x Budgeted selling price", "vars": "SM Co: budget 740 units at $21", "id": "acfma2-rv5-d309d-14bd5f"}, {"t": "f", "k": 1, "term": "Selling price variance", "text": "(Actual price - Budgeted price) x Actual units sold", "id": "acfma2-rv5-d309d-5f6875"}, {"t": "f", "k": 1, "term": "Total direct cost variance", "text": "Flexed budget cost - Actual cost = Activity variance + Purchase price/efficiency of usage variance", "id": "acfma2-rv5-d309d-90c852"}, {"t": "f", "term": "Cost activity (volume) variance", "text": "(Budgeted units - Actual units) x Budgeted cost per unit", "vars": "due only to the change in volume", "eg": "CTF Co: budget 800 units at $20", "id": "acfma2-rv5-d309d-4cf2e8"}, {"t": "f", "term": "Purchase price / efficiency of usage variance", "text": "(Actual units x Budgeted cost per unit) - Actual cost", "vars": "due to price paid or efficiency of use", "eg": "Blob Co: labour budget $10.20 per unit for 20,000 units", "id": "acfma2-rv5-d309d-1505c2"}, {"t": "pt", "text": "A higher activity level gives an ADVERSE cost activity variance (more spent) but is not necessarily bad performance", "id": "acfma2-rv5-d309d-4add4d"}], "id": "acfma2-rv5-d309d"}, {"kind": "process", "title": "Exception reporting and investigation", "page": [78, 79], "items": [{"t": "pt", "k": 1, "text": "Exception reporting: report only significant variances to the responsible manager - saves management time", "id": "acfma2-rv5-94a4d-136082"}, {"t": "pt", "k": 1, "text": "Decide whether to investigate using: size (absolute and %), controllable or non-controllable, adverse or favourable, trend, cost of investigation vs benefit", "id": "acfma2-rv5-94a4d-403918"}, {"t": "eg", "text": "Copper pipe manufacturer budgeted $25,000 on copper; a large price rise in copper is non-controllable - investigate supplier options rather than blame the manager", "id": "acfma2-rv5-94a4d-3dda18"}, {"t": "exam", "text": "Expect calculations of activity and price variances using the MA2 terminology", "id": "acfma2-rv5-94a4d-65a820"}], "id": "acfma2-rv5-94a4d"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Comparing actual costs with the ORIGINAL budget when activity has changed", "id": "acfma2-rv5-6483a-576236"}, {"t": "x", "text": "Flexing fixed costs", "id": "acfma2-rv5-6483a-22834f"}, {"t": "x", "text": "Calling every adverse variance poor performance - volume changes and non-controllable prices cause variances too", "id": "acfma2-rv5-6483a-7ffea5"}, {"t": "x", "text": "Using budgeted units in the selling price variance - use actual units sold", "id": "acfma2-rv5-6483a-0fb360"}], "id": "acfma2-rv5-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Compare with previous periods, forecasts, budgets, non-financial data", "id": "acfma2-rv5-80e78-42b9ad"}, {"t": "pt", "text": "Watch seasonal effects in period comparisons", "id": "acfma2-rv5-80e78-252ae5"}, {"t": "pt", "text": "Control cycle: goals, plan, standards, implement, measure, act", "id": "acfma2-rv5-80e78-11bdc6"}, {"t": "pt", "text": "Flex the budget to actual activity", "id": "acfma2-rv5-80e78-16a1eb"}, {"t": "pt", "text": "Variable costs flex; fixed costs do not", "id": "acfma2-rv5-80e78-cb52ce"}, {"t": "pt", "text": "Variance % = variance / budget", "id": "acfma2-rv5-80e78-68afef"}, {"t": "pt", "text": "Sales revenue variance = activity + selling price variance", "id": "acfma2-rv5-80e78-e5e2d6"}, {"t": "pt", "text": "Activity variance from volume change", "id": "acfma2-rv5-80e78-4adcb4"}, {"t": "pt", "text": "Price/efficiency variance from rates or usage", "id": "acfma2-rv5-80e78-3db4be"}, {"t": "pt", "text": "Exception reporting: significant variances only", "id": "acfma2-rv5-80e78-80c2ac"}, {"t": "pt", "text": "Investigate by size, controllability, trend, cost vs benefit", "id": "acfma2-rv5-80e78-766a73"}, {"t": "pt", "text": "Non-controllable variances need different action", "id": "acfma2-rv5-80e78-37c318"}], "id": "acfma2-rv5-80e78"}], "source": "BPP MA2 Text ch 5 (OCR): sections 1-7 pp66-79", "summary": "Comparisons with previous periods, forecasts, non-financial and budget figures, the control cycle, flexed budgets, percentage variances, sales and cost variances split into activity and price/efficiency elements, exception reporting and investigation.", "id": "acfma2-rv5", "updated": "2026-11-13"}, {"num": "6", "title": "Reporting Management Information", "pages": [87, 104], "syllabus": "B4", "status": "published", "branches": [{"kind": "compare", "title": "Methods of communication", "page": [90, 93], "items": [{"t": "table", "rows": [["Method", "Use", "Key features"], ["Letter", "Communicating with someone OUTSIDE the organisation", "Address, reference, date, salutation, close matching the salutation"], ["Memo", "Internal communication - same function as a letter internally", "To, from, date, subject; no salutation needed"], ["Email", "Internal or external, fast", "Dangers: confidentiality, viruses, overload, informality, legal records"], ["Report", "Standard (routine) or ad hoc (one-off) information for decisions", "Formal: title, to/from/date, introduction, findings, conclusions, recommendations, appendices"]], "id": "acfma2-rv6-f5853-ae8721"}, {"t": "pt", "k": 1, "text": "Choose the format according to the purpose, the audience, the formality required and urgency", "id": "acfma2-rv6-f5853-c6a788"}, {"t": "pt", "text": "Short formal report example: proposed updating of the company policy manual", "id": "acfma2-rv6-f5853-b8292c"}, {"t": "pt", "k": 1, "text": "Email dangers: confidentiality (safeguard passwords), viruses, sending to the wrong person, legal status of messages", "id": "acfma2-rv6-f5853-86bca5"}], "id": "acfma2-rv6-f5853"}, {"kind": "compare", "title": "Tables, charts and graphs", "page": [94, 96], "items": [{"t": "table", "rows": [["Presentation", "Best for"], ["Table", "Organising detailed figures in rows and columns"], ["Column / bar chart", "Showing or comparing magnitudes"], ["Pie chart", "Relative sizes of components of a total (each slice a fraction of 360°)"], ["Line graph", "Relationship between two variables, eg trends over time"], ["Scatter diagram", "Plotting pairs of values to see if they are related"]], "id": "acfma2-rv6-25ad3-9dafdb"}, {"t": "f", "term": "Pie chart slice", "text": "Fraction of total x 360°", "vars": "1/8 x 360° = 45°", "id": "acfma2-rv6-25ad3-c80261"}], "id": "acfma2-rv6-25ad3"}, {"kind": "rule", "title": "Confidentiality and data protection", "page": [97, 99], "items": [{"t": "pt", "k": 1, "text": "Personal data must be handled under data protection law (eg UK Data Protection Act)", "id": "acfma2-rv6-6b62f-ae8cc9"}, {"t": "def", "k": 1, "term": "Personal data", "text": "Information about a living individual, including expressions of opinion about them", "id": "acfma2-rv6-6b62f-59cb1d"}, {"t": "pt", "text": "Rights of data subjects include access to their data and correction of inaccurate data", "id": "acfma2-rv6-6b62f-a23e00"}, {"t": "pt", "k": 1, "text": "Internal requirements: the policy manual lays down confidentiality rules (eg who may see payroll or customer data, passwords, locking files)", "id": "acfma2-rv6-6b62f-3d7182"}, {"t": "exam", "text": "Questions may ask which communication method is most appropriate in a scenario", "id": "acfma2-rv6-6b62f-80d584"}], "id": "acfma2-rv6-6b62f"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using a memo to write to a customer - use a letter", "id": "acfma2-rv6-6483a-42fd9c"}, {"t": "x", "text": "Using a pie chart to show a trend over time", "id": "acfma2-rv6-6483a-076f56"}, {"t": "x", "text": "Sending confidential information by email without safeguards", "id": "acfma2-rv6-6483a-ad6ebd"}, {"t": "x", "text": "Leaving conclusions out of a report", "id": "acfma2-rv6-6483a-2ef45a"}], "id": "acfma2-rv6-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Letter: external", "id": "acfma2-rv6-80e78-c2e72b"}, {"t": "pt", "text": "Memo: internal", "id": "acfma2-rv6-80e78-622416"}, {"t": "pt", "text": "Email: fast but confidentiality and virus risks", "id": "acfma2-rv6-80e78-cafe9f"}, {"t": "pt", "text": "Reports: standard or ad hoc", "id": "acfma2-rv6-80e78-ea35cc"}, {"t": "pt", "text": "Report structure: introduction, findings, conclusions, recommendations, appendices", "id": "acfma2-rv6-80e78-93d85d"}, {"t": "pt", "text": "Tables organise detailed figures", "id": "acfma2-rv6-80e78-4db006"}, {"t": "pt", "text": "Bar charts compare magnitudes", "id": "acfma2-rv6-80e78-aecff2"}, {"t": "pt", "text": "Pie chart: shares of a total (360°)", "id": "acfma2-rv6-80e78-a6a864"}, {"t": "pt", "text": "Line graph: trends/relationships", "id": "acfma2-rv6-80e78-e45b1a"}, {"t": "pt", "text": "Scatter diagram: paired values", "id": "acfma2-rv6-80e78-e81bb7"}, {"t": "pt", "text": "Personal data = about a living individual", "id": "acfma2-rv6-80e78-9fe3e3"}, {"t": "pt", "text": "Follow data protection and policy manual rules", "id": "acfma2-rv6-80e78-917144"}], "id": "acfma2-rv6-80e78"}], "source": "BPP MA2 Text ch 6 (OCR): sections 1-3 pp88-99", "summary": "Types of written communication (letters, memos, emails, reports), presenting information in tables, charts and graphs, and confidentiality and data protection requirements.", "id": "acfma2-rv6", "updated": "2026-11-13"}, {"num": "7", "title": "Materials", "pages": [105, 136], "syllabus": "C1", "status": "published", "branches": [{"kind": "concept", "title": "Classifying and buying materials", "page": [106, 114], "items": [{"t": "pt", "k": 1, "text": "Raw materials (goods purchased for incorporation into products), work in progress (intermediate stage), finished goods (ready for sale or despatch)", "id": "acfma2-rv7-5c95c-c9de5c"}, {"t": "pt", "text": "Direct vs indirect materials depending on how easily they can be traced to the product", "id": "acfma2-rv7-5c95c-f98a2b"}, {"t": "pt", "k": 1, "text": "Purchasing documents: purchase requisition -> order form -> (supplier's despatch note) -> delivery note -> goods received note (GRN, after inspection) -> invoice", "id": "acfma2-rv7-5c95c-5f0e75"}, {"t": "pt", "text": "Buying department keeps cost information to find the best suppliers", "id": "acfma2-rv7-5c95c-faaa70"}, {"t": "f", "term": "Material input with wastage", "text": "Required output / (1 - wastage %)", "vars": "buy extra to allow for loss in production", "eg": "100 kg of output with 3% loss needs 100 / 0.97 = 103.09 kg", "id": "acfma2-rv7-5c95c-77403e"}, {"t": "pt", "text": "High wastage is an avoidable expense - control by monitoring standards, training, better handling", "id": "acfma2-rv7-5c95c-5a8f51"}], "id": "acfma2-rv7-5c95c"}, {"kind": "compare", "title": "JIT vs buffer inventory", "page": [115, 115], "items": [{"t": "table", "rows": [["Policy", "Approach", "Risk"], ["Just-in-time (JIT)", "Materials arrive exactly when needed - minimal inventory", "Stockouts if a supplier is late"], ["Buffer (safety) inventory", "Keep a reserve to cover uncertain usage or lead time", "Higher holding costs"]], "id": "acfma2-rv7-84502-7e6931"}], "id": "acfma2-rv7-84502"}, {"kind": "compare", "title": "Inventory valuation", "page": [116, 120], "items": [{"t": "table", "rows": [["Method", "Issues priced at", "Rising prices"], ["FIFO", "Earliest receipts first", "Lowest cost of issues, highest closing inventory"], ["LIFO", "Latest receipts first", "Highest cost of issues, lowest closing inventory"], ["Cumulative weighted average", "Average recalculated after each receipt", "In between"]], "id": "acfma2-rv7-e343a-c753a2"}, {"t": "pt", "k": 1, "text": "The problem: identical units bought at different prices - which cost goes to production and which stays in inventory?", "id": "acfma2-rv7-e343a-720f71"}], "id": "acfma2-rv7-e343a"}, {"kind": "concept", "title": "Storekeeping and inventory costs", "page": [121, 127], "items": [{"t": "pt", "text": "Locating inventory: organised stores, bin locations; each item coded unambiguously", "id": "acfma2-rv7-60ab1-9e9c5d"}, {"t": "pt", "text": "Issues only against an authorised materials requisition", "id": "acfma2-rv7-60ab1-5d34b8"}, {"t": "pt", "k": 1, "text": "Stocktaking: count physical inventory at a date and check against the records; investigate discrepancies (errors, theft, damage)", "id": "acfma2-rv7-60ab1-7ea062"}, {"t": "pt", "k": 1, "text": "Inventory costs: purchase costs • ordering costs (admin, delivery) • holding costs (storage, insurance, deterioration, capital tied up) • stockout costs (lost sales, goodwill, idle production)", "id": "acfma2-rv7-60ab1-a44ebd"}], "id": "acfma2-rv7-60ab1"}, {"kind": "formula", "title": "Control levels and EOQ", "page": [127, 131], "items": [{"t": "f", "k": 1, "term": "Reorder level", "text": "Maximum usage x Maximum lead time", "vars": "order when inventory reaches this level", "id": "acfma2-rv7-afc8c-83d9e6"}, {"t": "f", "k": 1, "term": "Minimum level", "text": "Reorder level - (Average usage x Average lead time)", "vars": "warning: dangerously low", "id": "acfma2-rv7-afc8c-f29197"}, {"t": "f", "k": 1, "term": "Maximum level", "text": "Reorder level + Reorder quantity - (Minimum usage x Minimum lead time)", "vars": "warning: wastefully high", "id": "acfma2-rv7-afc8c-65a943"}, {"t": "f", "term": "Average inventory", "text": "Minimum (buffer) level + ½ Reorder quantity", "id": "acfma2-rv7-afc8c-a61de4"}, {"t": "f", "k": 1, "term": "EOQ", "text": "√(2 x Co x D / Ch)", "vars": "Co = cost of placing an order; D = annual demand; Ch = cost of holding one unit for a year", "eg": "formula to learn", "id": "acfma2-rv7-afc8c-bcf41e"}, {"t": "pt", "text": "EOQ minimises total ordering plus holding costs", "id": "acfma2-rv7-afc8c-201766"}], "id": "acfma2-rv7-afc8c"}, {"kind": "concept", "title": "Computerised inventory systems", "page": [132, 132], "items": [{"t": "pt", "text": "Inventory file: code, description, location, quantities, reorder levels, prices, supplier", "id": "acfma2-rv7-a2d92-15f4e5"}, {"t": "pt", "text": "Reports: inventory levels, items below reorder level, slow-moving items, valuation", "id": "acfma2-rv7-a2d92-126522"}, {"t": "pt", "text": "Bill of materials facility lists the components for an assembly", "id": "acfma2-rv7-a2d92-6d034d"}, {"t": "x", "text": "Computerising records does NOT guarantee 100% accuracy - errors, theft and wastage still occur", "id": "acfma2-rv7-a2d92-686c40"}, {"t": "exam", "text": "Expect reorder level, maximum level and EOQ calculations", "id": "acfma2-rv7-a2d92-f38321"}], "id": "acfma2-rv7-a2d92"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Calculating input as output x (1 + wastage%) - divide by (1 - wastage%)", "id": "acfma2-rv7-6483a-59662b"}, {"t": "x", "text": "Using average usage in the reorder level formula", "id": "acfma2-rv7-6483a-478331"}, {"t": "x", "text": "Assuming computerised records are always accurate", "id": "acfma2-rv7-6483a-170a53"}, {"t": "x", "text": "Mixing up FIFO and LIFO results in rising prices", "id": "acfma2-rv7-6483a-75878f"}], "id": "acfma2-rv7-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Raw materials, WIP, finished goods", "id": "acfma2-rv7-80e78-f028ff"}, {"t": "pt", "text": "Requisition -> order -> delivery note -> GRN -> invoice", "id": "acfma2-rv7-80e78-c0fd2f"}, {"t": "pt", "text": "Input = output / (1 - wastage %)", "id": "acfma2-rv7-80e78-1a67ef"}, {"t": "pt", "text": "JIT minimises inventory; buffer protects against stockouts", "id": "acfma2-rv7-80e78-5a5b6d"}, {"t": "pt", "text": "FIFO: earliest costs to issues", "id": "acfma2-rv7-80e78-311345"}, {"t": "pt", "text": "LIFO: latest costs to issues", "id": "acfma2-rv7-80e78-df2b2b"}, {"t": "pt", "text": "Stocktake and investigate discrepancies", "id": "acfma2-rv7-80e78-3c6616"}, {"t": "pt", "text": "Costs: purchase, ordering, holding, stockout", "id": "acfma2-rv7-80e78-c66ea1"}, {"t": "pt", "text": "Reorder level = max usage x max lead time", "id": "acfma2-rv7-80e78-fa7712"}, {"t": "pt", "text": "Minimum = reorder level - avg usage x avg lead time", "id": "acfma2-rv7-80e78-3de8e1"}, {"t": "pt", "text": "Maximum = reorder level + reorder qty - min usage x min lead time", "id": "acfma2-rv7-80e78-e56be2"}, {"t": "pt", "text": "EOQ = √(2CoD/Ch)", "id": "acfma2-rv7-80e78-097ef4"}], "id": "acfma2-rv7-80e78"}], "source": "BPP MA2 Text ch 7 (OCR): sections 1-6 pp106-132", "summary": "Classifying materials, purchasing procedures and documents, material requirements allowing for wastage, JIT and buffer inventory, FIFO/LIFO/average valuation, storekeeping, stocktaking, inventory costs, control levels, EOQ and computerised inventory systems.", "id": "acfma2-rv7", "updated": "2026-11-13"}, {"num": "8", "title": "Labour", "pages": [137, 156], "syllabus": "C2", "status": "published", "branches": [{"kind": "concept", "title": "Recording labour", "page": [139, 146], "items": [{"t": "pt", "text": "Labour costs determined by: prior agreement (time rates), output (piecework), or a combination with incentives", "id": "acfma2-rv8-3ff1b-3334c8"}, {"t": "pt", "k": 1, "text": "Attendance time: clock cards or attendance records (hours at work, absence)", "id": "acfma2-rv8-3ff1b-cfb11f"}, {"t": "pt", "k": 1, "text": "Job time: job cards, timesheets, route cards - time spent on each job so labour can be charged to jobs", "id": "acfma2-rv8-3ff1b-e5d9c2"}, {"t": "pt", "text": "Continuous production: record time for the process rather than each unit", "id": "acfma2-rv8-3ff1b-bb1902"}, {"t": "pt", "text": "Salaried staff may complete timesheets so their time can be charged to clients/jobs", "id": "acfma2-rv8-3ff1b-fcc0b8"}, {"t": "def", "k": 1, "term": "Idle time", "text": "Time when employees are paid but cannot work through no fault of their own (eg machine breakdown, waiting for materials)", "id": "acfma2-rv8-3ff1b-deda40"}, {"t": "pt", "text": "Coding of job costs links labour hours to jobs and cost centres", "id": "acfma2-rv8-3ff1b-d93746"}], "id": "acfma2-rv8-3ff1b"}, {"kind": "formula", "title": "Overtime, incentives and bonuses", "page": [146, 149], "items": [{"t": "pt", "k": 1, "text": "Overtime: basic rate for overtime hours is direct labour; the overtime PREMIUM is usually an indirect cost (overhead)", "id": "acfma2-rv8-091d5-702400"}, {"t": "eg", "text": "36 hours at $4 basic + 6 hours overtime at $4 + premium ¼ x 6 x $4 = $6 (premium = overhead)", "id": "acfma2-rv8-091d5-132a88"}, {"t": "pt", "k": 1, "text": "Five incentive schemes: piecework • time-saved bonus • discretionary bonus • group bonus • profit sharing", "id": "acfma2-rv8-091d5-1be189"}, {"t": "f", "term": "Piecework", "text": "Units produced (or piecework hours) x Rate", "vars": "47.5 piecework hours x $5 = $237.50", "id": "acfma2-rv8-091d5-753486"}, {"t": "f", "term": "Time-saved bonus", "text": "Time saved x Bonus rate", "vars": "time saved = time allowed - time taken", "eg": "garage job allowed 45 minutes", "id": "acfma2-rv8-091d5-3b1d02"}, {"t": "pt", "text": "Discretionary bonus: given at the employer's discretion (common in small businesses)", "id": "acfma2-rv8-091d5-647b69"}, {"t": "pt", "text": "Group bonus: when individual effort cannot be measured; profit sharing: a share of year-end profits", "id": "acfma2-rv8-091d5-e92178"}, {"t": "pt", "text": "Absence: holidays, sickness, training - paid absence is usually an overhead", "id": "acfma2-rv8-091d5-7b5b82"}], "id": "acfma2-rv8-091d5"}, {"kind": "formula", "title": "Labour turnover and efficiency", "page": [152, 154], "items": [{"t": "f", "k": 1, "term": "Labour turnover rate", "text": "Number of leavers replaced / Average number of employees x 100%", "vars": "average = (start + end) / 2", "id": "acfma2-rv8-712bc-1d074b"}, {"t": "pt", "text": "Reasons: better pay elsewhere, poor conditions, relocation, retirement, dismissal", "id": "acfma2-rv8-712bc-0a35ad"}, {"t": "pt", "k": 1, "text": "Costs: replacement costs (recruitment, selection, training, lost output) and preventative costs (welfare, pay, conditions)", "id": "acfma2-rv8-712bc-bef2f6"}, {"t": "pt", "text": "Reduce turnover: satisfactory pay and conditions, good management, training and career prospects", "id": "acfma2-rv8-712bc-bc008e"}, {"t": "f", "term": "Efficiency ratio", "text": "Standard hours of output / Actual hours worked x 100%", "id": "acfma2-rv8-712bc-310e87"}, {"t": "f", "term": "Capacity ratio", "text": "Actual hours worked / Budgeted hours x 100%", "id": "acfma2-rv8-712bc-2f9cb6"}, {"t": "f", "k": 1, "term": "Idle time ratio", "text": "Idle hours / Total hours paid x 100%", "vars": "controls idle time", "id": "acfma2-rv8-712bc-51daa9"}, {"t": "exam", "text": "Expect calculations of gross pay with overtime and bonuses, and of labour turnover", "id": "acfma2-rv8-712bc-3354e8"}], "id": "acfma2-rv8-712bc"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Charging overtime premium to the job as direct labour by default", "id": "acfma2-rv8-6483a-33dcfc"}, {"t": "x", "text": "Including leavers who are not replaced in labour turnover", "id": "acfma2-rv8-6483a-c648ee"}, {"t": "x", "text": "Treating idle time as productive direct labour", "id": "acfma2-rv8-6483a-f0ad55"}, {"t": "x", "text": "Confusing attendance time (at work) with job time (on specific jobs)", "id": "acfma2-rv8-6483a-211524"}], "id": "acfma2-rv8-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Attendance time: clock cards", "id": "acfma2-rv8-80e78-a81078"}, {"t": "pt", "text": "Job time: job cards, timesheets", "id": "acfma2-rv8-80e78-e19303"}, {"t": "pt", "text": "Idle time: paid but unable to work", "id": "acfma2-rv8-80e78-87e8e3"}, {"t": "pt", "text": "Overtime at basic rate = direct; premium = overhead", "id": "acfma2-rv8-80e78-172ae8"}, {"t": "pt", "text": "Incentives: piecework, time-saved, discretionary, group, profit sharing", "id": "acfma2-rv8-80e78-f25394"}, {"t": "pt", "text": "Piecework = units x rate", "id": "acfma2-rv8-80e78-6b3548"}, {"t": "pt", "text": "Time-saved bonus = time saved x rate", "id": "acfma2-rv8-80e78-162ee8"}, {"t": "pt", "text": "Labour turnover = replaced leavers / average employees", "id": "acfma2-rv8-80e78-6c6192"}, {"t": "pt", "text": "Replacement and preventative costs of turnover", "id": "acfma2-rv8-80e78-88c737"}, {"t": "pt", "text": "Efficiency = standard hours / actual hours", "id": "acfma2-rv8-80e78-617880"}, {"t": "pt", "text": "Capacity = actual hours / budgeted hours", "id": "acfma2-rv8-80e78-e2ad30"}, {"t": "pt", "text": "Idle time ratio = idle hours / total hours", "id": "acfma2-rv8-80e78-324485"}], "id": "acfma2-rv8-80e78"}], "source": "BPP MA2 Text ch 8 (OCR): sections 1-5 pp138-154", "summary": "Determining labour costs, basic pay, recording attendance and job time, idle time, coding, overtime, incentive and bonus schemes, absence, direct vs indirect labour, labour turnover and labour efficiency ratios.", "id": "acfma2-rv8", "updated": "2026-11-13"}, {"num": "9", "title": "Expenses", "pages": [157, 172], "syllabus": "C3", "status": "published", "branches": [{"kind": "compare", "title": "Revenue vs capital expenditure", "page": [158, 160], "items": [{"t": "table", "rows": [["Type", "Meaning", "Treatment"], ["Revenue expenditure", "Day-to-day running costs, repairs, maintenance", "Charged as an expense in the period"], ["Capital expenditure", "Acquiring or improving non-current assets", "Capitalised and depreciated over the asset's life"]], "id": "acfma2-rv9-ae848-f169ca"}, {"t": "pt", "k": 1, "text": "Revenue expenditure is of more relevance to product costing; capital expenditure enters product costs through depreciation", "id": "acfma2-rv9-ae848-d53ab2"}], "id": "acfma2-rv9-ae848"}, {"kind": "concept", "title": "Types of expense", "page": [161, 162], "items": [{"t": "pt", "text": "Rent: usually an annual charge payable quarterly in advance - fixed", "id": "acfma2-rv9-5fc2f-36816f"}, {"t": "pt", "text": "Insurance: premiums for buildings, contents, vehicles - fixed", "id": "acfma2-rv9-5fc2f-d4ac46"}, {"t": "pt", "k": 1, "text": "Electricity, gas and telecommunications: usually TWO elements - a fixed standing charge and a variable usage charge (semi-variable)", "id": "acfma2-rv9-5fc2f-ea7d56"}, {"t": "pt", "text": "Subscriptions: usually paid annually (trade bodies, journals)", "id": "acfma2-rv9-5fc2f-f86cd5"}, {"t": "pt", "text": "Professional fees: based on time spent on the client's business (accountants, solicitors)", "id": "acfma2-rv9-5fc2f-1685a7"}, {"t": "pt", "text": "Hire charges: payable on a time basis (eg a cement mixer per day)", "id": "acfma2-rv9-5fc2f-36b81e"}, {"t": "def", "k": 1, "term": "Discretionary costs", "text": "Costs incurred at somebody's discretion (eg training, advertising, R&D) - can be cut in the short term", "id": "acfma2-rv9-5fc2f-7ed431"}], "id": "acfma2-rv9-5fc2f"}, {"kind": "formula", "title": "Depreciation", "page": [162, 164], "items": [{"t": "pt", "k": 1, "text": "Objective: spread the cost of a non-current asset (less residual value) over its useful life - a charge for using the asset", "id": "acfma2-rv9-a6708-586965"}, {"t": "pt", "k": 1, "text": "Four principal methods: straight line • reducing balance • machine hour • units of production (output)", "id": "acfma2-rv9-a6708-bf2e43"}, {"t": "f", "term": "Straight line", "text": "(Cost - Residual value) / Useful life (years)", "id": "acfma2-rv9-a6708-74ef60"}, {"t": "f", "term": "Reducing balance", "text": "% x Carrying amount at the start of the year", "id": "acfma2-rv9-a6708-1059e6"}, {"t": "f", "term": "Machine hour method", "text": "(Cost - Residual value) / Total expected machine hours x Hours used", "vars": "suits assets whose wear relates to use", "eg": "590 days total usage -> depreciation per day", "id": "acfma2-rv9-a6708-acdcc1"}, {"t": "f", "term": "Units of production", "text": "(Cost - Residual value) / Total expected output x Units produced", "vars": "$60,000 / 6,000 units = $10 per unit", "id": "acfma2-rv9-a6708-403704"}, {"t": "pt", "text": "In practice the straight line method is most often used (simple)", "id": "acfma2-rv9-a6708-6ea1fc"}], "id": "acfma2-rv9-a6708"}, {"kind": "process", "title": "Direct and indirect expenses", "page": [165, 167], "items": [{"t": "pt", "k": 1, "text": "Direct expenses (eg plant hire for a specific job, solicitor's fees for a specific contract) are charged directly to the cost unit", "id": "acfma2-rv9-5cd72-ac3966"}, {"t": "def", "k": 1, "term": "Allocation", "text": "The process by which whole cost items are charged to a cost centre", "id": "acfma2-rv9-5cd72-5292ad"}, {"t": "pt", "text": "Indirect expenses shared between cost centres are apportioned on a fair basis (eg rent by floor area)", "id": "acfma2-rv9-5cd72-3c015c"}, {"t": "pt", "text": "Documentation: code invoices to the cost centre/cost unit; apportionment schedules", "id": "acfma2-rv9-5cd72-8880ef"}, {"t": "pt", "text": "Responsibility accounting: managers should only be accountable for costs they can control - apportioned costs are usually not controllable", "id": "acfma2-rv9-5cd72-1d7fbd"}, {"t": "exam", "text": "Expect questions classifying an expense as capital or revenue, direct or indirect", "id": "acfma2-rv9-5cd72-242719"}], "id": "acfma2-rv9-5cd72"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Treating utility bills as wholly variable - they include a fixed standing charge", "id": "acfma2-rv9-6483a-da945e"}, {"t": "x", "text": "Expensing the purchase of a machine instead of depreciating it", "id": "acfma2-rv9-6483a-e4d97a"}, {"t": "x", "text": "Holding a manager responsible for apportioned rent", "id": "acfma2-rv9-6483a-f1eb61"}, {"t": "x", "text": "Applying the reducing balance % to cost instead of carrying amount", "id": "acfma2-rv9-6483a-7736ad"}], "id": "acfma2-rv9-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Revenue expenditure: running costs, expensed", "id": "acfma2-rv9-80e78-71958c"}, {"t": "pt", "text": "Capital expenditure: non-current assets, depreciated", "id": "acfma2-rv9-80e78-a8569b"}, {"t": "pt", "text": "Rent and insurance: fixed", "id": "acfma2-rv9-80e78-86c68d"}, {"t": "pt", "text": "Utilities: standing charge + usage (semi-variable)", "id": "acfma2-rv9-80e78-895af8"}, {"t": "pt", "text": "Professional fees: time-based", "id": "acfma2-rv9-80e78-aeb84d"}, {"t": "pt", "text": "Discretionary costs can be cut short term", "id": "acfma2-rv9-80e78-7dead9"}, {"t": "pt", "text": "Depreciation methods: straight line, reducing balance, machine hour, units of production", "id": "acfma2-rv9-80e78-4849bd"}, {"t": "pt", "text": "Straight line = (cost - residual) / life", "id": "acfma2-rv9-80e78-f10f72"}, {"t": "pt", "text": "Units of production = cost per unit x units", "id": "acfma2-rv9-80e78-67b3ba"}, {"t": "pt", "text": "Direct expenses charged to cost units", "id": "acfma2-rv9-80e78-30dbfb"}, {"t": "pt", "text": "Allocation: whole items to one cost centre", "id": "acfma2-rv9-80e78-d55be3"}, {"t": "pt", "text": "Apportionment: shared costs on a fair basis", "id": "acfma2-rv9-80e78-037eae"}], "id": "acfma2-rv9-80e78"}], "source": "BPP MA2 Text ch 9 (OCR): sections 1-4 pp158-167", "summary": "Revenue vs capital expenditure, types of expense (rent, insurance, utilities, subscriptions, fees, hire, discretionary costs), depreciation methods, and direct vs indirect expenses with allocation and apportionment.", "id": "acfma2-rv9", "updated": "2026-11-13"}, {"num": "10", "title": "Overheads and Absorption Costing", "pages": [173, 198], "syllabus": "D1", "status": "published", "branches": [{"kind": "concept", "title": "Absorption costing basics", "page": [174, 176], "items": [{"t": "def", "k": 1, "term": "Overhead", "text": "An indirect cost incurred in making a product or providing a service that cannot be traced directly and in full", "id": "acfma2-rv10-fdfff-e152a2"}, {"t": "pt", "k": 1, "text": "Objective of absorption costing: include in the total cost of a product an appropriate share of the organisation's total overhead", "id": "acfma2-rv10-fdfff-0c8178"}, {"t": "pt", "text": "Reasons: inventory valuation, pricing, establishing profitability of products", "id": "acfma2-rv10-fdfff-7628fb"}, {"t": "f", "term": "Full production cost", "text": "Prime cost + Production overhead absorbed", "vars": "also called factory cost", "id": "acfma2-rv10-fdfff-47cf24"}, {"t": "pt", "k": 1, "text": "Procedure: allocate -> apportion -> reapportion service centre costs -> absorb into cost units", "id": "acfma2-rv10-fdfff-af25b1"}, {"t": "def", "term": "Allocation", "text": "Assigning WHOLE items of cost to cost centres", "id": "acfma2-rv10-fdfff-73fefa"}], "id": "acfma2-rv10-fdfff"}, {"kind": "process", "title": "Apportionment and reapportionment", "page": [177, 186], "items": [{"t": "pt", "k": 1, "text": "Apportionment shares common costs out on a fair basis", "id": "acfma2-rv10-4f6d9-aa9461"}, {"t": "pt", "text": "Bases: floor area (rent, rates, heating, lighting) • number of employees (canteen, personnel) • value of machinery (depreciation, insurance) • machine hours or kW (power)", "id": "acfma2-rv10-4f6d9-14aaeb"}, {"t": "pt", "k": 1, "text": "Service cost centre costs are reapportioned to production cost centres, because only production centres make output", "id": "acfma2-rv10-4f6d9-fb851a"}, {"t": "pt", "text": "Direct method: ignores work done by service centres for each other", "id": "acfma2-rv10-4f6d9-08c983"}, {"t": "pt", "k": 1, "text": "Step-down method: recognises some inter-service work - reapportion one service centre (including to the other service centre) then the second to production only", "id": "acfma2-rv10-4f6d9-08c608"}, {"t": "exam", "text": "You only need to know the direct and step-down methods for MA2", "id": "acfma2-rv10-4f6d9-15082d"}], "id": "acfma2-rv10-4f6d9"}, {"kind": "formula", "title": "Absorption and under/over absorption", "page": [187, 191], "items": [{"t": "pt", "k": 1, "text": "Absorption bases: rate per machine hour, rate per direct labour hour, rate per unit, % of prime cost, % of direct labour cost", "id": "acfma2-rv10-c313e-8a7668"}, {"t": "f", "k": 1, "term": "Predetermined overhead absorption rate", "text": "Budgeted overhead / Budgeted activity level", "vars": "set in advance from budgets", "id": "acfma2-rv10-c313e-d42ffd"}, {"t": "pt", "text": "Actual absorption rates (actual overhead / actual activity) are only known after the period - too late for pricing and inventory decisions", "id": "acfma2-rv10-c313e-078b47"}, {"t": "f", "k": 1, "term": "Under/over absorption", "text": "Actual overhead incurred - Overhead absorbed (actual activity x predetermined rate)", "vars": "positive = UNDER-absorbed; negative = OVER-absorbed", "id": "acfma2-rv10-c313e-4be13b"}, {"t": "pt", "text": "Absorption is arbitrary: even fair bases cannot measure exactly how much overhead each unit causes", "id": "acfma2-rv10-c313e-af8720"}], "id": "acfma2-rv10-c313e"}, {"kind": "concept", "title": "Non-production overheads", "page": [192, 193], "items": [{"t": "pt", "text": "Administration overheads: executive salaries, office costs, depreciation of office equipment", "id": "acfma2-rv10-0dc7c-fcdcd1"}, {"t": "pt", "text": "Selling and distribution overheads: often considered together - sales staff, advertising, delivery", "id": "acfma2-rv10-0dc7c-f976a9"}, {"t": "pt", "text": "Two approaches: absorb them into product cost using a chosen basis (eg % of production cost) or treat them as period costs", "id": "acfma2-rv10-0dc7c-13dce9"}, {"t": "exam", "text": "Questions often ask for the under/over absorbed amount and its effect on profit", "id": "acfma2-rv10-0dc7c-fe046a"}], "id": "acfma2-rv10-0dc7c"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using actual activity to set the predetermined rate", "id": "acfma2-rv10-6483a-7a2da8"}, {"t": "x", "text": "Leaving overheads in service cost centres", "id": "acfma2-rv10-6483a-3ba211"}, {"t": "x", "text": "Calling actual > absorbed 'over-absorbed'", "id": "acfma2-rv10-6483a-a3d69a"}, {"t": "x", "text": "Thinking absorption costing gives a precise cost per unit - it is arbitrary", "id": "acfma2-rv10-6483a-56b1a5"}], "id": "acfma2-rv10-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Overhead = indirect cost", "id": "acfma2-rv10-80e78-e8e2f8"}, {"t": "pt", "text": "Absorption costing shares overheads into product cost", "id": "acfma2-rv10-80e78-1225b0"}, {"t": "pt", "text": "Full production cost = prime cost + production overhead", "id": "acfma2-rv10-80e78-5b3940"}, {"t": "pt", "text": "Allocate -> apportion -> reapportion -> absorb", "id": "acfma2-rv10-80e78-a1b47c"}, {"t": "pt", "text": "Allocation: whole items to a cost centre", "id": "acfma2-rv10-80e78-756d2f"}, {"t": "pt", "text": "Apportionment bases: floor area, employees, machinery value", "id": "acfma2-rv10-80e78-81294f"}, {"t": "pt", "text": "Service centres reapportioned to production centres", "id": "acfma2-rv10-80e78-c225a5"}, {"t": "pt", "text": "Direct method ignores inter-service work", "id": "acfma2-rv10-80e78-2ec46a"}, {"t": "pt", "text": "Step-down recognises some inter-service work", "id": "acfma2-rv10-80e78-609729"}, {"t": "pt", "text": "OAR = budgeted overhead / budgeted activity", "id": "acfma2-rv10-80e78-88c3e1"}, {"t": "pt", "text": "Under-absorbed: actual > absorbed", "id": "acfma2-rv10-80e78-af1aaf"}, {"t": "pt", "text": "Over-absorbed: absorbed > actual", "id": "acfma2-rv10-80e78-5ee626"}], "id": "acfma2-rv10-80e78"}], "source": "BPP MA2 Text ch 10 (OCR): sections 1-8 pp174-193", "summary": "Overheads, the objective of absorption costing, allocation, apportionment bases, reapportionment of service centre costs (direct and step-down), absorption bases, predetermined rates, under/over absorption and non-production overheads.", "id": "acfma2-rv10", "updated": "2026-11-13"}, {"num": "11", "title": "Marginal Costing and Absorption Costing", "pages": [199, 214], "syllabus": "D2", "status": "published", "branches": [{"kind": "def", "title": "Marginal cost and contribution", "page": [200, 201], "items": [{"t": "def", "k": 1, "term": "Marginal cost", "text": "The cost of a unit of product or service which would be avoided if that unit were not produced or provided - its variable cost", "id": "acfma2-rv11-a568f-31f98b"}, {"t": "def", "k": 1, "term": "Contribution", "text": "The difference between sales value and the marginal (variable) cost of sales", "id": "acfma2-rv11-a568f-01a0f1"}, {"t": "pt", "text": "Marginal costing: only variable costs are charged to cost units; fixed costs of the period are written off in full against total contribution", "id": "acfma2-rv11-a568f-1a5971"}, {"t": "pt", "text": "Closing inventory is valued at marginal (variable production) cost", "id": "acfma2-rv11-a568f-6228cf"}], "id": "acfma2-rv11-a568f"}, {"kind": "compare", "title": "Marginal vs absorption costing", "page": [201, 210], "items": [{"t": "table", "rows": [["Point", "Marginal costing", "Absorption costing"], ["Fixed production overhead", "Period cost - charged in full", "Absorbed into units and carried in inventory"], ["Inventory valuation", "Variable production cost", "Full production cost"], ["Profit measure", "Contribution, then profit", "Gross profit, then profit"], ["Use", "Decision making, CVP", "Financial accounts (inventory valuation), pricing"]], "id": "acfma2-rv11-5e023-dd44fd"}, {"t": "pt", "k": 1, "text": "Inventory rising (production > sales): absorption profit HIGHER", "id": "acfma2-rv11-5e023-d553e8"}, {"t": "pt", "k": 1, "text": "Inventory falling (sales > production): marginal profit HIGHER", "id": "acfma2-rv11-5e023-f605e9"}, {"t": "pt", "k": 1, "text": "No change in inventory: profits are the SAME", "id": "acfma2-rv11-5e023-4a88eb"}], "id": "acfma2-rv11-5e023"}, {"kind": "formula", "title": "Reconciling profits", "page": [208, 210], "items": [{"t": "f", "k": 1, "term": "Profit difference", "text": "Change in inventory units x Fixed production overhead absorption rate per unit", "vars": "explains absorption profit vs marginal profit", "id": "acfma2-rv11-3ac4a-82238b"}, {"t": "f", "term": "Contribution per unit", "text": "Selling price - Variable cost per unit", "vars": "total contribution - fixed costs = profit", "id": "acfma2-rv11-3ac4a-1c3fc0"}], "id": "acfma2-rv11-3ac4a"}, {"kind": "concept", "title": "Arguments for each method", "page": [210, 212], "items": [{"t": "pt", "text": "For marginal costing: simple, no under/over absorption, contribution helps decisions, profit cannot be inflated by building inventory", "id": "acfma2-rv11-ffedc-9c532e"}, {"t": "pt", "text": "For absorption costing: required for financial reporting inventory valuation, fixed production costs are part of making the product, avoids showing losses when inventory is built up for seasonal sales", "id": "acfma2-rv11-ffedc-aa5616"}, {"t": "exam", "text": "Expect questions on the profit difference and on valuing closing inventory under each method", "id": "acfma2-rv11-ffedc-e903c2"}], "id": "acfma2-rv11-ffedc"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Including fixed production overhead in marginal cost of inventory", "id": "acfma2-rv11-6483a-e99094"}, {"t": "x", "text": "Reversing the profit comparison when inventory rises", "id": "acfma2-rv11-6483a-1e10d9"}, {"t": "x", "text": "Treating fixed selling costs as absorbed into inventory", "id": "acfma2-rv11-6483a-c521ad"}, {"t": "x", "text": "Calculating the difference on total inventory rather than the CHANGE", "id": "acfma2-rv11-6483a-487cab"}], "id": "acfma2-rv11-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Marginal cost = variable cost of one unit", "id": "acfma2-rv11-80e78-56fdb4"}, {"t": "pt", "text": "Contribution = sales - marginal cost of sales", "id": "acfma2-rv11-80e78-ecbfc2"}, {"t": "pt", "text": "Marginal costing: fixed costs are period costs", "id": "acfma2-rv11-80e78-9853eb"}, {"t": "pt", "text": "Absorption: fixed production overhead in inventory", "id": "acfma2-rv11-80e78-0d26f9"}, {"t": "pt", "text": "Inventory up: absorption profit higher", "id": "acfma2-rv11-80e78-86fa89"}, {"t": "pt", "text": "Inventory down: marginal profit higher", "id": "acfma2-rv11-80e78-498b9b"}, {"t": "pt", "text": "No change: same profit", "id": "acfma2-rv11-80e78-ea68a5"}, {"t": "pt", "text": "Difference = Δ inventory x fixed OAR", "id": "acfma2-rv11-80e78-583113"}, {"t": "pt", "text": "Marginal costing aids decisions", "id": "acfma2-rv11-80e78-7bc800"}, {"t": "pt", "text": "Absorption required for financial reporting", "id": "acfma2-rv11-80e78-2c6d83"}, {"t": "pt", "text": "Contribution per unit = price - VC per unit", "id": "acfma2-rv11-80e78-16e1d1"}, {"t": "pt", "text": "Profit = total contribution - fixed costs", "id": "acfma2-rv11-80e78-1ffc44"}], "id": "acfma2-rv11-80e78"}], "source": "BPP MA2 Text ch 11 (OCR): sections 1-4 pp200-212", "summary": "Marginal cost and contribution, marginal costing principles, profit under marginal vs absorption costing, reconciling the two profits and the arguments for each.", "id": "acfma2-rv11", "updated": "2026-11-13"}, {"num": "12", "title": "Cost Bookkeeping", "pages": [215, 234], "syllabus": "D3", "status": "published", "branches": [{"kind": "process", "title": "Cost bookkeeping entries", "page": [216, 224], "items": [{"t": "pt", "k": 1, "text": "Control accounts are summary accounts in the ledger (materials, wages, production overhead, WIP, finished goods)", "id": "acfma2-rv12-f2f10-4988c1"}, {"t": "pt", "k": 1, "text": "Materials: Dr Materials control (purchases); issues - Dr WIP (direct), Dr Production overhead control (indirect), Cr Materials control", "id": "acfma2-rv12-f2f10-b94028"}, {"t": "pt", "k": 1, "text": "Labour: Dr Wages control (gross pay); Cr Wages control - Dr WIP (direct labour), Dr Production overhead control (indirect labour)", "id": "acfma2-rv12-f2f10-eb1e3b"}, {"t": "pt", "k": 1, "text": "Overheads: Dr Production overhead control (actual overhead incurred); Cr Production overhead control, Dr WIP (overhead ABSORBED)", "id": "acfma2-rv12-f2f10-8330fa"}, {"t": "pt", "text": "Completed production: Dr Finished goods, Cr WIP; sales: Dr Cost of sales, Cr Finished goods", "id": "acfma2-rv12-f2f10-0f80e7"}, {"t": "pt", "text": "Under-absorbed overhead: Dr P/L (or under/over-absorbed account), Cr Production overhead control; over-absorbed: the reverse", "id": "acfma2-rv12-f2f10-0b8807"}, {"t": "pt", "text": "Marginal costing systems: only VARIABLE production costs flow into WIP; fixed overheads go straight to profit or loss", "id": "acfma2-rv12-f2f10-ae7356"}], "id": "acfma2-rv12-f2f10"}, {"kind": "compare", "title": "Interlocking vs integrated systems", "page": [227, 231], "items": [{"t": "table", "rows": [["Feature", "Interlocking system", "Integrated system"], ["Ledgers", "Separate cost ledger and financial ledger", "One combined set of accounts"], ["Link", "Cost ledger control account", "None needed"], ["Reconciliation", "Cost and financial profits must be reconciled", "No reconciliation needed"], ["Main advantage", "Each ledger designed for its own purpose", "Saves administration time and cost"]], "id": "acfma2-rv12-6838e-bb41e7"}, {"t": "def", "k": 1, "term": "Interlocking system", "text": "A bookkeeping system where separate ledger accounts are kept for the cost accounting function and the financial accounting function", "id": "acfma2-rv12-6838e-863cd9"}, {"t": "def", "k": 1, "term": "Cost ledger control account", "text": "In an interlocking system, the account in the cost ledger that represents the financial ledger - it carries the other side of entries that relate to the financial ledger (eg purchases, wages paid, overheads, sales)", "id": "acfma2-rv12-6838e-d5d018"}, {"t": "def", "k": 1, "term": "Notional cost", "text": "A cost introduced into cost accounts that is not an actual cash expense (eg notional rent on owned premises) - causes a difference between cost and financial profits", "id": "acfma2-rv12-6838e-46447d"}, {"t": "pt", "text": "Reasons cost and financial profits differ (interlocking): notional costs, different inventory valuations, items in only one set of accounts (eg interest, discounts)", "id": "acfma2-rv12-6838e-93595e"}, {"t": "exam", "text": "Expect questions identifying the double entry for an issue of indirect materials or for absorbed overhead", "id": "acfma2-rv12-6838e-76ce8b"}], "id": "acfma2-rv12-6838e"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Debiting WIP with actual overhead - WIP is debited with overhead ABSORBED", "id": "acfma2-rv12-6483a-3b7913"}, {"t": "x", "text": "Debiting indirect materials to WIP - they go to production overhead control", "id": "acfma2-rv12-6483a-ae4806"}, {"t": "x", "text": "Expecting to reconcile profits in an integrated system - there is only one set of accounts", "id": "acfma2-rv12-6483a-e7d171"}, {"t": "x", "text": "Treating notional costs as cash expenses in the financial accounts", "id": "acfma2-rv12-6483a-db8d65"}], "id": "acfma2-rv12-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Control accounts summarise cost flows", "id": "acfma2-rv12-80e78-c816ed"}, {"t": "pt", "text": "Direct materials: Dr WIP; indirect: Dr production overhead", "id": "acfma2-rv12-80e78-97ba68"}, {"t": "pt", "text": "Direct labour: Dr WIP; indirect: Dr production overhead", "id": "acfma2-rv12-80e78-169b9f"}, {"t": "pt", "text": "Actual overhead: Dr production overhead control", "id": "acfma2-rv12-80e78-6b6f28"}, {"t": "pt", "text": "Absorbed overhead: Dr WIP, Cr production overhead control", "id": "acfma2-rv12-80e78-8911f1"}, {"t": "pt", "text": "Completed output: Dr finished goods, Cr WIP", "id": "acfma2-rv12-80e78-351ca2"}, {"t": "pt", "text": "Sales: Dr cost of sales, Cr finished goods", "id": "acfma2-rv12-80e78-130d52"}, {"t": "pt", "text": "Under-absorbed: Dr P/L", "id": "acfma2-rv12-80e78-9d7da3"}, {"t": "pt", "text": "Marginal system: only variable costs in WIP", "id": "acfma2-rv12-80e78-6644cf"}, {"t": "pt", "text": "Interlocking: two ledgers, cost ledger control account, reconcile profits", "id": "acfma2-rv12-80e78-2b6dad"}, {"t": "pt", "text": "Integrated: one ledger, saves time", "id": "acfma2-rv12-80e78-f914fe"}, {"t": "pt", "text": "Notional costs cause profit differences", "id": "acfma2-rv12-80e78-5a347f"}], "id": "acfma2-rv12-80e78"}], "source": "BPP MA2 Text ch 12 (OCR): sections 1-4 pp216-231", "summary": "Cost ledger accounting for materials, labour and overheads, the flow of costs through control accounts in absorption and marginal systems, interlocking vs integrated systems, the cost ledger control account and notional costs.", "id": "acfma2-rv12", "updated": "2026-11-13"}, {"num": "13", "title": "Job, Batch and Service Costing", "pages": [235, 250], "syllabus": "D4", "status": "published", "branches": [{"kind": "process", "title": "Job costing", "page": [236, 242], "items": [{"t": "def", "k": 1, "term": "Job costing", "text": "A costing method where costs are attributed to individual jobs carried out to customer specifications", "id": "acfma2-rv13-c040f-6034d9"}, {"t": "pt", "text": "Aim: collect direct materials, direct labour, direct expenses and overheads for each job", "id": "acfma2-rv13-c040f-ec414c"}, {"t": "pt", "text": "Procedure: customer enquiry -> estimate and quotation -> job number -> collect actual costs -> compare actual with estimate -> invoice", "id": "acfma2-rv13-c040f-596f13"}, {"t": "pt", "k": 1, "text": "Each job has a separate job account (in the WIP control) and a job card recording actual and estimated costs, overheads absorbed and admin overhead", "id": "acfma2-rv13-c040f-36f1ba"}, {"t": "pt", "text": "Materials from requisitions; labour from job/time cards; overheads absorbed (eg 40% of prime cost)", "id": "acfma2-rv13-c040f-017b1c"}, {"t": "f", "term": "Cost plus pricing", "text": "Selling price = Total cost x (1 + Mark-up %)", "vars": "mark-up on cost; or price = cost / (1 - margin %) for a margin on sales", "id": "acfma2-rv13-c040f-4893ae"}, {"t": "pt", "text": "Incomplete jobs at the period end = work in progress", "id": "acfma2-rv13-c040f-6f56c6"}], "id": "acfma2-rv13-c040f"}, {"kind": "concept", "title": "Batch costing", "page": [242, 244], "items": [{"t": "def", "k": 1, "term": "Batch costing", "text": "Used where common equipment produces batches of different products - each batch is treated as a job", "id": "acfma2-rv13-4d0fb-186e58"}, {"t": "f", "term": "Cost per unit in a batch", "text": "Total batch cost / Number of units in the batch", "id": "acfma2-rv13-4d0fb-ba8892"}, {"t": "pt", "k": 1, "text": "Controlling costs: compare actual job/batch costs with estimates, investigate overruns, review pricing", "id": "acfma2-rv13-4d0fb-e33d43"}], "id": "acfma2-rv13-4d0fb"}, {"kind": "concept", "title": "Service costing", "page": [245, 246], "items": [{"t": "pt", "k": 1, "text": "Service costing is used by organisations providing services (hospitals, transport, hotels, canteens)", "id": "acfma2-rv13-1000d-49f9e6"}, {"t": "pt", "k": 1, "text": "The main problem: defining a realistic cost unit - often a COMPOSITE cost unit", "id": "acfma2-rv13-1000d-8294a2"}, {"t": "pt", "text": "Examples: passenger-kilometre, tonne-kilometre, patient-day, room-night, meals served", "id": "acfma2-rv13-1000d-cc89e0"}, {"t": "f", "term": "Cost per service unit", "text": "Total costs for the period / Number of service units supplied", "id": "acfma2-rv13-1000d-acad89"}, {"t": "exam", "text": "Expect questions selecting the appropriate cost unit for a service", "id": "acfma2-rv13-1000d-5a8fc2"}], "id": "acfma2-rv13-1000d"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using job costing where output is continuous and identical (that is process costing)", "id": "acfma2-rv13-6483a-af2fd5"}, {"t": "x", "text": "Confusing mark-up (on cost) with margin (on selling price)", "id": "acfma2-rv13-6483a-4347f9"}, {"t": "x", "text": "Using a single measure where a composite unit suits better", "id": "acfma2-rv13-6483a-24f34b"}, {"t": "x", "text": "Forgetting overheads absorbed when building a job cost", "id": "acfma2-rv13-6483a-f3adf8"}], "id": "acfma2-rv13-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Job costing: customer-specified jobs", "id": "acfma2-rv13-80e78-785bad"}, {"t": "pt", "text": "Job account in WIP; job card records costs", "id": "acfma2-rv13-80e78-ca57cc"}, {"t": "pt", "text": "Materials from requisitions; labour from job cards", "id": "acfma2-rv13-80e78-071cdd"}, {"t": "pt", "text": "Overheads absorbed at a predetermined rate", "id": "acfma2-rv13-80e78-384cb5"}, {"t": "pt", "text": "Price = cost x (1 + mark-up)", "id": "acfma2-rv13-80e78-0bf545"}, {"t": "pt", "text": "Incomplete jobs = WIP", "id": "acfma2-rv13-80e78-65a8b1"}, {"t": "pt", "text": "Batch costing: batch treated as a job", "id": "acfma2-rv13-80e78-a4f3ec"}, {"t": "pt", "text": "Cost per unit = batch cost / units", "id": "acfma2-rv13-80e78-9cda8b"}, {"t": "pt", "text": "Compare actual with estimates to control costs", "id": "acfma2-rv13-80e78-5e758d"}, {"t": "pt", "text": "Service costing for service organisations", "id": "acfma2-rv13-80e78-16bb93"}, {"t": "pt", "text": "Composite cost units: passenger-km, tonne-km, patient-day", "id": "acfma2-rv13-80e78-76a6c2"}, {"t": "pt", "text": "Cost per service unit = total cost / service units", "id": "acfma2-rv13-80e78-ada303"}], "id": "acfma2-rv13-80e78"}], "source": "BPP MA2 Text ch 13 (OCR): sections 1-3 pp236-246", "summary": "Job costing procedure, job accounts and job cards, cost plus pricing, batch costing, controlling costs in job and batch costing, and service costing with composite cost units.", "id": "acfma2-rv13", "updated": "2026-11-13"}, {"num": "14", "title": "Process Costing", "pages": [251, 270], "syllabus": "D5", "status": "published", "branches": [{"kind": "concept", "title": "Process costing basics", "page": [252, 253], "items": [{"t": "def", "k": 1, "term": "Process costing", "text": "A costing method used to determine the cost of units manufactured in a continuous or repetitive series of processes where units are not separately identifiable", "id": "acfma2-rv14-92f93-0d8430"}, {"t": "pt", "text": "Features: output of one process is the input to the next; costs collected for each process; losses are expected", "id": "acfma2-rv14-92f93-65a2bb"}, {"t": "pt", "k": 1, "text": "Four steps: determine output and losses -> calculate cost per unit -> calculate total cost of output and losses -> complete the accounts", "id": "acfma2-rv14-92f93-bc9d8a"}], "id": "acfma2-rv14-92f93"}, {"kind": "rule", "title": "Losses and scrap", "page": [253, 259], "items": [{"t": "pt", "k": 1, "text": "Normal loss: expected - not given a cost; valued at scrap value (credited to the process account)", "id": "acfma2-rv14-1e4d4-94686c"}, {"t": "pt", "k": 1, "text": "Abnormal loss: actual loss greater than normal - valued at the same cost per unit as good output; debited to an abnormal loss account", "id": "acfma2-rv14-1e4d4-1471fd"}, {"t": "pt", "k": 1, "text": "Abnormal gain: actual loss less than normal - valued at cost per unit; credited to an abnormal gain account", "id": "acfma2-rv14-1e4d4-7178a5"}, {"t": "f", "term": "Cost per unit", "text": "(Process costs - Scrap value of normal loss) / Expected output", "vars": "expected output = input - normal loss", "eg": "eg output transferred at $4.90 per unit", "id": "acfma2-rv14-1e4d4-ad8d79"}, {"t": "pt", "text": "Scrap value of abnormal loss reduces the net cost of abnormal loss (credited to the abnormal loss account)", "id": "acfma2-rv14-1e4d4-29eb1a"}], "id": "acfma2-rv14-1e4d4"}, {"kind": "formula", "title": "Joint products", "page": [260, 262], "items": [{"t": "def", "k": 1, "term": "Joint products", "text": "Two or more products from the same process, each with significant value, not separately identifiable until the split-off point", "id": "acfma2-rv14-38a20-8a66d8"}, {"t": "pt", "text": "Common (joint) costs incurred before split-off must be shared out to value inventory and calculate profit", "id": "acfma2-rv14-38a20-29a296"}, {"t": "f", "k": 1, "term": "Physical measurement", "text": "Common cost x (Units/weight of product / Total units/weight of all joint products)", "vars": "unsuitable if products have very different values", "id": "acfma2-rv14-38a20-9867d9"}, {"t": "f", "k": 1, "term": "Net realisable value at split-off", "text": "Common cost x (NRV of product / Total NRV of all joint products)", "vars": "NRV = final sales value - further processing and selling costs after split-off", "id": "acfma2-rv14-38a20-acf2f5"}, {"t": "pt", "text": "Usefulness is limited: joint cost apportionment is arbitrary and should not drive decisions (eg whether to process further)", "id": "acfma2-rv14-38a20-47282a"}, {"t": "exam", "text": "Expect cost per unit and abnormal loss valuation, and joint cost apportionment questions", "id": "acfma2-rv14-38a20-e948bd"}], "id": "acfma2-rv14-38a20"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Valuing normal loss at cost - it is valued at scrap value only", "id": "acfma2-rv14-6483a-f10ed9"}, {"t": "x", "text": "Dividing by input instead of expected output", "id": "acfma2-rv14-6483a-0f9481"}, {"t": "x", "text": "Using sales value AFTER further processing without deducting the further processing costs", "id": "acfma2-rv14-6483a-13cde3"}, {"t": "x", "text": "Using apportioned joint costs to decide whether to process further", "id": "acfma2-rv14-6483a-4c2406"}], "id": "acfma2-rv14-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Process costing: continuous, units not identifiable", "id": "acfma2-rv14-80e78-e8a982"}, {"t": "pt", "text": "Four steps: output/losses, cost per unit, total costs, accounts", "id": "acfma2-rv14-80e78-16b021"}, {"t": "pt", "text": "Normal loss: no cost, scrap value", "id": "acfma2-rv14-80e78-55af8f"}, {"t": "pt", "text": "Abnormal loss/gain: valued at cost per unit", "id": "acfma2-rv14-80e78-72602e"}, {"t": "pt", "text": "Cost per unit = (costs - scrap of normal loss) / expected output", "id": "acfma2-rv14-80e78-45ceb6"}, {"t": "pt", "text": "Expected output = input - normal loss", "id": "acfma2-rv14-80e78-9a7fc9"}, {"t": "pt", "text": "Abnormal loss scrap value reduces its net cost", "id": "acfma2-rv14-80e78-576ec6"}, {"t": "pt", "text": "Joint products: significant value, split-off point", "id": "acfma2-rv14-80e78-702816"}, {"t": "pt", "text": "Common costs shared before split-off", "id": "acfma2-rv14-80e78-06b719"}, {"t": "pt", "text": "Physical measurement: by units or weight", "id": "acfma2-rv14-80e78-3913d4"}, {"t": "pt", "text": "NRV method: sales value - further costs", "id": "acfma2-rv14-80e78-2eb042"}, {"t": "pt", "text": "Joint cost apportionment is arbitrary for decisions", "id": "acfma2-rv14-80e78-2034c1"}], "id": "acfma2-rv14-80e78"}], "source": "BPP MA2 Text ch 14 (OCR): sections 1-4 pp252-262", "summary": "Features of process costing, the four-step framework, normal and abnormal losses and gains, scrap values, joint products and common costs apportioned by physical measurement or net realisable value at split-off.", "id": "acfma2-rv14", "updated": "2026-11-13"}, {"num": "15", "title": "Cost-Volume-Profit (CVP) Analysis", "pages": [271, 288], "syllabus": "E1", "status": "published", "branches": [{"kind": "formula", "title": "Breakeven and margin of safety", "page": [272, 276], "items": [{"t": "pt", "k": 1, "text": "CVP analysis studies how profit changes with volume, given cost behaviour (fixed vs variable)", "id": "acfma2-rv15-717bb-fc1fc8"}, {"t": "f", "k": 1, "term": "Breakeven point (units)", "text": "Total fixed costs / Contribution per unit", "vars": "contribution per unit = selling price - variable cost per unit", "id": "acfma2-rv15-717bb-2baab3"}, {"t": "f", "k": 1, "term": "Contribution to sales (C/S) ratio", "text": "Contribution per unit / Selling price per unit (or total contribution / total sales)", "vars": "also called the profit/volume (P/V) ratio", "id": "acfma2-rv15-717bb-0ee844"}, {"t": "f", "k": 1, "term": "Breakeven point (revenue)", "text": "Fixed costs / C/S ratio", "vars": "the alternative method using the ratio", "id": "acfma2-rv15-717bb-183beb"}, {"t": "f", "k": 1, "term": "Margin of safety", "text": "Budgeted sales - Breakeven sales", "vars": "as units, revenue or % of budgeted sales", "eg": "shows how far sales can fall before a loss", "id": "acfma2-rv15-717bb-81c0ae"}, {"t": "f", "k": 1, "term": "Sales for a target profit", "text": "(Fixed costs + Target profit) / Contribution per unit", "vars": "eg (fixed costs + $63,000 target) / contribution per unit", "id": "acfma2-rv15-717bb-e7abce"}, {"t": "pt", "text": "At breakeven: total contribution = fixed costs (S - V = F)", "id": "acfma2-rv15-717bb-421c2e"}], "id": "acfma2-rv15-717bb"}, {"kind": "concept", "title": "Changing price or costs", "page": [276, 279], "items": [{"t": "pt", "text": "A price cut lowers contribution per unit, raising the breakeven point; more volume is needed to keep profit", "id": "acfma2-rv15-56089-11f810"}, {"t": "pt", "text": "Higher fixed costs raise breakeven; higher variable cost per unit lowers contribution and raises breakeven", "id": "acfma2-rv15-56089-0e3832"}, {"t": "pt", "k": 1, "text": "Given no change in fixed costs, total profit is maximised by maximising total contribution", "id": "acfma2-rv15-56089-4360dd"}], "id": "acfma2-rv15-56089"}, {"kind": "compare", "title": "CVP charts", "page": [279, 284], "items": [{"t": "table", "rows": [["Chart", "Shows", "Breakeven"], ["Breakeven chart", "Fixed cost line, total cost line and sales revenue line against volume", "Where sales line crosses total cost line"], ["Contribution breakeven chart", "Variable cost line drawn first, fixed costs above it - contribution visible", "Same point"], ["Profit/volume (P/V) chart", "Profit or loss at each level of sales; starts at minus fixed costs on the y axis", "Where the profit line crosses the x axis"]], "id": "acfma2-rv15-1a749-a59857"}, {"t": "pt", "k": 1, "text": "The P/V chart clearly shows the effect on profit and breakeven of any change in price, costs or volume", "id": "acfma2-rv15-1a749-d2abf5"}, {"t": "exam", "text": "Expect breakeven, margin of safety and target profit calculations", "id": "acfma2-rv15-1a749-697d8e"}], "id": "acfma2-rv15-1a749"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Dividing fixed costs by selling price instead of contribution per unit", "id": "acfma2-rv15-6483a-167d9d"}, {"t": "x", "text": "Forgetting to add the target profit to fixed costs", "id": "acfma2-rv15-6483a-162b43"}, {"t": "x", "text": "Reading breakeven on a P/V chart where the line meets the y axis - that point is the fixed costs (loss)", "id": "acfma2-rv15-6483a-cdfc26"}, {"t": "x", "text": "Including fixed costs in contribution", "id": "acfma2-rv15-6483a-3c5f3e"}], "id": "acfma2-rv15-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Contribution per unit = price - variable cost", "id": "acfma2-rv15-80e78-1a4774"}, {"t": "pt", "text": "Breakeven units = fixed costs / contribution per unit", "id": "acfma2-rv15-80e78-d149ea"}, {"t": "pt", "text": "C/S ratio = contribution / sales", "id": "acfma2-rv15-80e78-6cf2c2"}, {"t": "pt", "text": "Breakeven revenue = fixed costs / C/S ratio", "id": "acfma2-rv15-80e78-339aa1"}, {"t": "pt", "text": "Margin of safety = budgeted sales - breakeven sales", "id": "acfma2-rv15-80e78-15f553"}, {"t": "pt", "text": "Target sales = (fixed costs + target profit) / contribution per unit", "id": "acfma2-rv15-80e78-4759ba"}, {"t": "pt", "text": "At breakeven, contribution = fixed costs", "id": "acfma2-rv15-80e78-82b139"}, {"t": "pt", "text": "Price cut raises breakeven", "id": "acfma2-rv15-80e78-2420eb"}, {"t": "pt", "text": "Breakeven chart: sales line meets total cost line", "id": "acfma2-rv15-80e78-cfdb8d"}, {"t": "pt", "text": "Contribution chart shows contribution visibly", "id": "acfma2-rv15-80e78-3c1717"}, {"t": "pt", "text": "P/V chart starts at minus fixed costs", "id": "acfma2-rv15-80e78-fb3a99"}, {"t": "pt", "text": "Maximise contribution to maximise profit", "id": "acfma2-rv15-80e78-6d14cd"}], "id": "acfma2-rv15-80e78"}], "source": "BPP MA2 Text ch 15 (OCR): sections 1-5 pp272-284", "summary": "Breakeven point, contribution to sales ratio, margin of safety, target profits, decisions to change price or costs, breakeven charts, contribution charts and profit/volume charts.", "id": "acfma2-rv15", "updated": "2026-11-13"}, {"num": "16", "title": "Short-Term Decisions", "pages": [289, 302], "syllabus": "E2", "status": "published", "branches": [{"kind": "concept", "title": "Relevant costs", "page": [290, 293], "items": [{"t": "def", "k": 1, "term": "Relevant cost", "text": "A future cash flow incurred incrementally as a result of a possible future course of action (decision)", "id": "acfma2-rv16-a12af-b3ff6a"}, {"t": "pt", "k": 1, "text": "Non-relevant: sunk costs (already incurred), committed costs, absorbed overhead (a notional accounting cost), depreciation", "id": "acfma2-rv16-a12af-1ea2bf"}, {"t": "pt", "text": "A variable cost can be non-relevant if it is in fact a sunk cost (eg materials already bought with no alternative use)", "id": "acfma2-rv16-a12af-24f78f"}, {"t": "pt", "k": 1, "text": "Attributable (specific) fixed costs ARE relevant - they would be incurred or saved by the decision", "id": "acfma2-rv16-a12af-ede3f3"}, {"t": "pt", "k": 1, "text": "Relevant cost of materials: generally their current REPLACEMENT cost; if in inventory with no other use and not to be replaced, their scrap/realisable value (or nil)", "id": "acfma2-rv16-a12af-7c3eee"}, {"t": "pt", "text": "Relevant cost of labour: if spare capacity and paid anyway, nil; if diverted from other work, wage + lost contribution (opportunity cost)", "id": "acfma2-rv16-a12af-217e12"}], "id": "acfma2-rv16-a12af"}, {"kind": "process", "title": "Limiting factor analysis", "page": [294, 295], "items": [{"t": "def", "k": 1, "term": "Limiting factor", "text": "A scarce resource that limits the organisation's activities (eg materials, labour hours, machine hours)", "id": "acfma2-rv16-35c06-fad89e"}, {"t": "pt", "k": 1, "text": "Steps: calculate contribution per unit -> divide by the units of limiting factor used -> rank products by contribution PER UNIT OF LIMITING FACTOR -> allocate the scarce resource in rank order (up to demand)", "id": "acfma2-rv16-35c06-0edda4"}, {"t": "f", "term": "Contribution per limiting factor", "text": "Contribution per unit / Units of limiting factor per unit of product", "vars": "eg $12 contribution / 3 labour hours = $4 per hour", "id": "acfma2-rv16-35c06-525d1e"}, {"t": "pt", "text": "Assumption: management wishes to maximise profit (= maximise contribution, as fixed costs are unchanged)", "id": "acfma2-rv16-35c06-b72206"}], "id": "acfma2-rv16-35c06"}, {"kind": "decision", "title": "Make or buy-in", "page": [296, 298], "items": [{"t": "dq", "text": "Is the variable cost of making in-house LOWER than the price of buying in (plus any avoidable fixed costs)?", "yes": "Make in-house", "no": "Buy in from the subcontractor", "id": "acfma2-rv16-d4154-ee5deb"}, {"t": "pt", "k": 1, "text": "Compare: relevant (incremental) cost of making = variable cost + attributable fixed costs saved if bought in, vs the purchase price", "id": "acfma2-rv16-d4154-389e16"}, {"t": "pt", "k": 1, "text": "With a limiting factor: buy in the products with the LOWEST extra cost of buying per unit of scarce resource saved", "id": "acfma2-rv16-d4154-b9a217"}, {"t": "f", "term": "Extra cost of buying per unit of scarce resource", "text": "(Buy-in price - Variable cost of making) / Units of scarce resource saved", "id": "acfma2-rv16-d4154-6419eb"}, {"t": "pt", "text": "Non-financial factors: quality, reliability of supply, loss of skills, confidentiality, employee morale, supplier dependence", "id": "acfma2-rv16-d4154-e4cd97"}, {"t": "exam", "text": "Expect questions on the relevant cost of materials and on ranking products by contribution per limiting factor", "id": "acfma2-rv16-d4154-fdb89b"}], "id": "acfma2-rv16-d4154"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Including absorbed fixed overhead or depreciation in a decision", "id": "acfma2-rv16-6483a-31f173"}, {"t": "x", "text": "Ranking by contribution per unit instead of per unit of the limiting factor", "id": "acfma2-rv16-6483a-6538ea"}, {"t": "x", "text": "Valuing materials in inventory at historical cost", "id": "acfma2-rv16-6483a-1d59e1"}, {"t": "x", "text": "Ignoring non-financial factors in make or buy", "id": "acfma2-rv16-6483a-cc5edf"}], "id": "acfma2-rv16-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Relevant = future, incremental cash flow", "id": "acfma2-rv16-80e78-5d3e78"}, {"t": "pt", "text": "Sunk and committed costs are irrelevant", "id": "acfma2-rv16-80e78-44a526"}, {"t": "pt", "text": "Absorbed overhead is notional - ignore", "id": "acfma2-rv16-80e78-0687e1"}, {"t": "pt", "text": "Attributable fixed costs are relevant", "id": "acfma2-rv16-80e78-5f3db4"}, {"t": "pt", "text": "Materials: replacement cost (or realisable value if no use)", "id": "acfma2-rv16-80e78-8e5b35"}, {"t": "pt", "text": "Labour: opportunity cost if diverted", "id": "acfma2-rv16-80e78-fbaeec"}, {"t": "pt", "text": "Limiting factor = scarce resource", "id": "acfma2-rv16-80e78-9179e9"}, {"t": "pt", "text": "Rank by contribution per unit of limiting factor", "id": "acfma2-rv16-80e78-7a92c4"}, {"t": "pt", "text": "Make if relevant cost of making < buy-in price", "id": "acfma2-rv16-80e78-a5b4d4"}, {"t": "pt", "text": "With scarce resources, buy in lowest extra cost per resource saved", "id": "acfma2-rv16-80e78-9c81a0"}, {"t": "pt", "text": "Consider quality, supply, skills, morale", "id": "acfma2-rv16-80e78-d0f06b"}, {"t": "pt", "text": "Maximise contribution to maximise profit", "id": "acfma2-rv16-80e78-6d14cd"}], "id": "acfma2-rv16-80e78"}], "source": "BPP MA2 Text ch 16 (OCR): sections 1-3 pp290-298", "summary": "Relevant costs (incremental, sunk, attributable, absorbed overhead, materials and labour), limiting factor analysis and make or buy-in decisions.", "id": "acfma2-rv16", "updated": "2026-11-13"}, {"num": "17", "title": "Capital Investment Appraisal", "pages": [303, 328], "syllabus": "E3", "status": "published", "branches": [{"kind": "formula", "title": "Interest", "page": [305, 308], "items": [{"t": "f", "k": 1, "term": "Simple interest", "text": "Interest = P x r x n", "vars": "interest earned only on the original principal", "eg": "$1,000 at 10% for 3 years = $300", "id": "acfma2-rv17-7680e-d85074"}, {"t": "f", "k": 1, "term": "Compound interest", "text": "V = P(1 + r)^n", "vars": "interest earned on interest", "eg": "$10,000 at 10% for 2 years = $12,100", "id": "acfma2-rv17-7680e-9250ee"}, {"t": "pt", "text": "Nominal rate: the stated annual rate (eg 12% compounded monthly)", "id": "acfma2-rv17-7680e-ae17e7"}, {"t": "f", "k": 1, "term": "Effective annual rate", "text": "(1 + r)^n - 1", "vars": "r = rate per period, n = periods per year", "eg": "1% per month: 1.01^12 - 1 = 12.68%", "id": "acfma2-rv17-7680e-ca49b4"}], "id": "acfma2-rv17-7680e"}, {"kind": "formula", "title": "Discounting and present values", "page": [308, 312], "items": [{"t": "def", "k": 1, "term": "Present value", "text": "The cash equivalent now of a sum to be received or paid in the future", "id": "acfma2-rv17-963c2-5f193d"}, {"t": "f", "k": 1, "term": "Discounting", "text": "PV = V / (1 + r)^n = V x discount factor", "vars": "converts a future value to a present value", "eg": "$11,000 in 1 year at 10% = $10,000", "id": "acfma2-rv17-963c2-5256ce"}, {"t": "pt", "text": "Present value tables give discount factors for each rate and year", "id": "acfma2-rv17-963c2-061926"}, {"t": "f", "k": 1, "term": "Annuity", "text": "PV = Annual cash flow x Annuity factor", "vars": "a constant sum each year for a given number of years", "id": "acfma2-rv17-963c2-fc8826"}, {"t": "f", "k": 1, "term": "Perpetuity", "text": "PV = Annual cash flow / r", "vars": "an annuity that lasts forever", "id": "acfma2-rv17-963c2-9c6f5d"}, {"t": "pt", "text": "Annuity tables assume the first payment is at the END of year 1; a payment now (time 0) has a factor of 1", "id": "acfma2-rv17-963c2-d1a23c"}], "id": "acfma2-rv17-963c2"}, {"kind": "concept", "title": "Cash vs profit", "page": [313, 315], "items": [{"t": "pt", "k": 1, "text": "In appraisal use CASH FLOWS, not profit - exclude depreciation and other non-cash items", "id": "acfma2-rv17-3a9ce-9f2b5e"}, {"t": "pt", "text": "Net profit and net cash flow differ because of timing differences (credit), non-cash items, capital items", "id": "acfma2-rv17-3a9ce-cea288"}, {"t": "def", "k": 1, "term": "Cost of capital", "text": "The cost of the funds the company uses, and the minimum return required from investments - the discount rate", "id": "acfma2-rv17-3a9ce-993c29"}, {"t": "pt", "text": "Relevant cash flows: incremental, future cash flows caused by the project", "id": "acfma2-rv17-3a9ce-b652cc"}], "id": "acfma2-rv17-3a9ce"}, {"kind": "formula", "title": "NPV, IRR and payback", "page": [314, 323], "items": [{"t": "f", "k": 1, "term": "Net present value (NPV)", "text": "PV of cash inflows - PV of cash outflows (at the cost of capital)", "vars": "positive -> accept", "id": "acfma2-rv17-1b930-024863"}, {"t": "def", "k": 1, "term": "Internal rate of return (IRR)", "text": "The discount rate at which the NPV of a project is zero", "id": "acfma2-rv17-1b930-ecc084"}, {"t": "f", "k": 1, "term": "IRR (interpolation)", "text": "IRR = A + [NPV_A / (NPV_A - NPV_B)] x (B - A)", "vars": "A = lower rate, B = higher rate", "eg": "accept if IRR > cost of capital", "id": "acfma2-rv17-1b930-37d8e0"}, {"t": "pt", "text": "Constant annual flows: IRR found where cumulative annuity factor = investment / annual cash flow", "id": "acfma2-rv17-1b930-b9683d"}, {"t": "f", "k": 1, "term": "Payback period", "text": "Time for cumulative cash inflows to repay the initial investment", "vars": "simple, favours liquidity; ignores later cash flows and time value", "id": "acfma2-rv17-1b930-46bd0c"}, {"t": "f", "term": "Discounted payback", "text": "Time for cumulative DISCOUNTED cash inflows to repay the investment", "vars": "allows for the time value of money", "id": "acfma2-rv17-1b930-adbf92"}, {"t": "exam", "text": "Expect NPV with discount and annuity factors, IRR interpolation and payback questions", "id": "acfma2-rv17-1b930-7b493b"}], "id": "acfma2-rv17-1b930"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Including depreciation in the cash flows", "id": "acfma2-rv17-6483a-5aa749"}, {"t": "x", "text": "Using annuity factors for flows that start at time 0", "id": "acfma2-rv17-6483a-d0d10a"}, {"t": "x", "text": "Treating the nominal rate as the effective rate when compounding is more frequent than annual", "id": "acfma2-rv17-6483a-5ab457"}, {"t": "x", "text": "Accepting a project because IRR is positive - compare IRR with the cost of capital", "id": "acfma2-rv17-6483a-fb7913"}], "id": "acfma2-rv17-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Simple interest = P x r x n", "id": "acfma2-rv17-80e78-bf1f3f"}, {"t": "pt", "text": "Compound: V = P(1 + r)^n", "id": "acfma2-rv17-80e78-ab2b2c"}, {"t": "pt", "text": "Effective rate = (1 + r)^n - 1", "id": "acfma2-rv17-80e78-797dff"}, {"t": "pt", "text": "PV = V / (1 + r)^n", "id": "acfma2-rv17-80e78-d0996d"}, {"t": "pt", "text": "Annuity PV = cash flow x annuity factor", "id": "acfma2-rv17-80e78-9cc181"}, {"t": "pt", "text": "Perpetuity PV = cash flow / r", "id": "acfma2-rv17-80e78-5fb1a7"}, {"t": "pt", "text": "Use cash flows, not profits", "id": "acfma2-rv17-80e78-18d3c5"}, {"t": "pt", "text": "Cost of capital = discount rate", "id": "acfma2-rv17-80e78-20b80e"}, {"t": "pt", "text": "NPV > 0: accept", "id": "acfma2-rv17-80e78-191916"}, {"t": "pt", "text": "IRR: NPV = 0", "id": "acfma2-rv17-80e78-1ed5ea"}, {"t": "pt", "text": "IRR = A + [NPV_A / (NPV_A - NPV_B)] x (B - A)", "id": "acfma2-rv17-80e78-99241d"}, {"t": "pt", "text": "Payback: time to recover investment", "id": "acfma2-rv17-80e78-288b0f"}, {"t": "pt", "text": "Discounted payback uses discounted flows", "id": "acfma2-rv17-80e78-ffc4a6"}], "id": "acfma2-rv17-80e78"}], "source": "BPP MA2 Text ch 17 (OCR): sections 1-8 pp304-323", "summary": "Simple and compound interest, nominal and effective rates, compounding and discounting, present value tables, annuities and perpetuities, cash vs profit, NPV, cost of capital, IRR by interpolation and payback (including discounted payback).", "id": "acfma2-rv17", "updated": "2026-11-13"}, {"num": "18", "title": "Cash and Cash Flows", "pages": [329, 342], "syllabus": "F1", "status": "published", "branches": [{"kind": "formula", "title": "Working capital", "page": [331, 333], "items": [{"t": "def", "k": 1, "term": "Working capital", "text": "The difference between a firm's current assets and its current liabilities (inventory, receivables, cash less payables)", "id": "acfma2-rv18-124fd-06f8f1"}, {"t": "def", "k": 1, "term": "Working capital (cash operating) cycle", "text": "The period between cash outflows for materials and cash inflows from customers", "id": "acfma2-rv18-124fd-ec69c7"}, {"t": "f", "k": 1, "term": "Working capital cycle", "text": "Inventory days + Receivables days - Payables days", "vars": "raw materials, WIP and finished goods holding periods + credit given - credit taken", "eg": "Inventory 60 + receivables 45 - payables 30 = 75 days", "id": "acfma2-rv18-124fd-135154"}, {"t": "pt", "text": "Different types of business have different cycles (eg a supermarket sells for cash and takes credit from suppliers - a short or negative cycle)", "id": "acfma2-rv18-124fd-5a8301"}], "id": "acfma2-rv18-124fd"}, {"kind": "concept", "title": "Cash flows", "page": [334, 337], "items": [{"t": "pt", "k": 1, "text": "Cash outflows: payments to suppliers, wages, expenses, capital expenditure, interest, tax, dividends/drawings, loan repayments", "id": "acfma2-rv18-0a665-77e7ce"}, {"t": "pt", "text": "Cash inflows: cash sales, receipts from credit customers, sale of assets, new loans, share issues, interest received", "id": "acfma2-rv18-0a665-731834"}, {"t": "pt", "k": 1, "text": "Profit differs from cash because of: timing (credit sales and purchases), non-cash items (depreciation, provisions), capital items (asset purchases, loans), inventory changes, drawings and dividends", "id": "acfma2-rv18-0a665-f6ff3c"}, {"t": "pt", "k": 1, "text": "Negative operational cash flows usually indicate the business cannot generate cash from trading - a serious warning even if profitable", "id": "acfma2-rv18-0a665-1ff5f0"}, {"t": "eg", "text": "David Co won a $1m contract but must pay suppliers and staff before the customer pays - profitable but short of cash", "id": "acfma2-rv18-0a665-0bb63a"}], "id": "acfma2-rv18-0a665"}, {"kind": "concept", "title": "Accruals vs cash", "page": [339, 339], "items": [{"t": "def", "k": 1, "term": "Accruals basis", "text": "The effects of transactions are recognised when they occur (not when cash is received or paid) and recorded in the period to which they relate", "id": "acfma2-rv18-d6b17-207e88"}, {"t": "pt", "text": "Accruals accounting helps investors judge performance; cash flow information shows liquidity and the ability to survive", "id": "acfma2-rv18-d6b17-38fec9"}, {"t": "pt", "k": 1, "text": "Survival in business depends on the ability to generate cash - profit alone is not enough", "id": "acfma2-rv18-d6b17-c7056c"}, {"t": "exam", "text": "Expect working capital cycle calculations and questions on why profit and cash differ", "id": "acfma2-rv18-d6b17-ed159d"}], "id": "acfma2-rv18-d6b17"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Adding payables days in the working capital cycle - they are deducted", "id": "acfma2-rv18-6483a-263363"}, {"t": "x", "text": "Thinking a profitable business always has enough cash", "id": "acfma2-rv18-6483a-8d95b5"}, {"t": "x", "text": "Treating depreciation as a cash outflow", "id": "acfma2-rv18-6483a-08dadc"}, {"t": "x", "text": "Ignoring capital expenditure and loan repayments when forecasting cash", "id": "acfma2-rv18-6483a-978cc2"}], "id": "acfma2-rv18-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Working capital = current assets - current liabilities", "id": "acfma2-rv18-80e78-7a25a2"}, {"t": "pt", "text": "Cycle = inventory days + receivables days - payables days", "id": "acfma2-rv18-80e78-d24693"}, {"t": "pt", "text": "Cycle length varies by type of business", "id": "acfma2-rv18-80e78-e0cfb1"}, {"t": "pt", "text": "Outflows: suppliers, wages, expenses, capital, interest, tax, dividends", "id": "acfma2-rv18-80e78-71e6bb"}, {"t": "pt", "text": "Inflows: sales, receipts, asset sales, loans, shares", "id": "acfma2-rv18-80e78-433e0d"}, {"t": "pt", "text": "Profit ≠ cash: timing, non-cash items, capital items", "id": "acfma2-rv18-80e78-644ced"}, {"t": "pt", "text": "Depreciation is not a cash flow", "id": "acfma2-rv18-80e78-561d9c"}, {"t": "pt", "text": "Negative operating cash flow = warning sign", "id": "acfma2-rv18-80e78-3a9127"}, {"t": "pt", "text": "Accruals: recognise when transactions occur", "id": "acfma2-rv18-80e78-6eade9"}, {"t": "pt", "text": "Cash information shows liquidity", "id": "acfma2-rv18-80e78-e5eec7"}, {"t": "pt", "text": "Survival depends on generating cash", "id": "acfma2-rv18-80e78-4f6f6f"}, {"t": "pt", "text": "Profitable firms can still fail through lack of cash", "id": "acfma2-rv18-80e78-ed3a6d"}], "id": "acfma2-rv18-80e78"}], "source": "BPP MA2 Text ch 18 (OCR): sections 1-5 pp330-339", "summary": "Cash and working capital, the working capital cycle, cash inflows and outflows, why profit differs from cash, negative cash flows, the accruals concept and the importance of cash flow information.", "id": "acfma2-rv18", "updated": "2026-11-13"}, {"num": "19", "title": "Cash and Treasury Management", "pages": [343, 350], "syllabus": "F2", "status": "published", "branches": [{"kind": "concept", "title": "Treasury management", "page": [344, 345], "items": [{"t": "pt", "k": 1, "text": "Treasury management in a large business is often a centralised function managing cash, funds and currency - markets are volatile (interest and exchange rates change continually)", "id": "acfma2-rv19-435a2-137a02"}, {"t": "pt", "text": "Treasurer's core roles (Association of Corporate Treasurers): corporate financial objectives • liquidity management (working capital, banking relationships, money management) • funding management • currency management (exposure, exchange dealing) • corporate finance (share capital, listing, mergers) • related subjects (tax, risk management, pensions)", "id": "acfma2-rv19-435a2-81f169"}, {"t": "def", "k": 1, "term": "Liquidity management", "text": "Making sure the organisation has the liquid funds it needs and invests any surplus to earn a return", "id": "acfma2-rv19-435a2-04fd32"}, {"t": "pt", "text": "Foreign exchange risk: values of assets and liabilities in one currency change with exchange rates", "id": "acfma2-rv19-435a2-073ba3"}], "id": "acfma2-rv19-435a2"}, {"kind": "rule", "title": "Cash handling procedures", "page": [345, 347], "items": [{"t": "pt", "k": 1, "text": "Objectives: all monies received are recorded and banked; cash and cheques are safeguarded against loss or theft; all payments are authorised, made to the correct payees and recorded", "id": "acfma2-rv19-9bfd3-534cf1"}, {"t": "pt", "k": 1, "text": "Segregation of duties between receiving, recording and banking cash", "id": "acfma2-rv19-9bfd3-40be70"}, {"t": "pt", "text": "Receipts by post: two people open mail, list amounts received, restrictive crossing of cheques, date-stamp", "id": "acfma2-rv19-9bfd3-4675c8"}, {"t": "pt", "text": "Cash sales: serially numbered receipts, cash registers with sealed till rolls, agree collections to till rolls and bankings, investigate shortages and surpluses", "id": "acfma2-rv19-9bfd3-2394f2"}, {"t": "pt", "text": "Banking: bank daily, intact; agree paying-in slips to receipt records and the cash book", "id": "acfma2-rv19-9bfd3-e4675b"}, {"t": "pt", "text": "General: prompt recording, limit cashiers' duties, holiday arrangements (rotation), custody of receipt books", "id": "acfma2-rv19-9bfd3-b1fc89"}, {"t": "pt", "text": "Payments: authorised before payment, supporting documents, cheque signatories within limits", "id": "acfma2-rv19-9bfd3-9670d6"}], "id": "acfma2-rv19-9bfd3"}, {"kind": "concept", "title": "Economic and financial environment", "page": [347, 348], "items": [{"t": "pt", "k": 1, "text": "Trends affect cash balances: interest rates (cost of borrowing, return on surplus cash), inflation, exchange rates, economic growth or recession (customer demand and payment), government policy, bank lending conditions", "id": "acfma2-rv19-fd840-728cbe"}, {"t": "exam", "text": "Expect questions identifying a missing cash control or a treasury function", "id": "acfma2-rv19-fd840-9d1fd1"}], "id": "acfma2-rv19-fd840"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Letting one person receive, record and bank cash - segregate duties", "id": "acfma2-rv19-6483a-b7dc9a"}, {"t": "x", "text": "Banking cash 'net' after paying expenses from it - bank receipts intact", "id": "acfma2-rv19-6483a-f6654a"}, {"t": "x", "text": "Treating treasury as only day-to-day banking - it also covers funding, currency and risk", "id": "acfma2-rv19-6483a-b9bd0e"}, {"t": "x", "text": "Ignoring interest and exchange rate trends when planning cash", "id": "acfma2-rv19-6483a-32369f"}], "id": "acfma2-rv19-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Treasury: cash, funding, currency, corporate finance, risk", "id": "acfma2-rv19-80e78-9cb468"}, {"t": "pt", "text": "Liquidity management: enough cash, invest surpluses", "id": "acfma2-rv19-80e78-72b3c1"}, {"t": "pt", "text": "Currency risk from exchange rate movements", "id": "acfma2-rv19-80e78-af4c45"}, {"t": "pt", "text": "Record and bank all receipts", "id": "acfma2-rv19-80e78-d2ad76"}, {"t": "pt", "text": "Safeguard cash and cheques", "id": "acfma2-rv19-80e78-8b00e6"}, {"t": "pt", "text": "Authorise all payments", "id": "acfma2-rv19-80e78-b3315e"}, {"t": "pt", "text": "Segregate receiving, recording and banking", "id": "acfma2-rv19-80e78-0ecdd2"}, {"t": "pt", "text": "Two people open the post and list receipts", "id": "acfma2-rv19-80e78-bc8cb7"}, {"t": "pt", "text": "Sealed till rolls and numbered receipts", "id": "acfma2-rv19-80e78-f267f7"}, {"t": "pt", "text": "Bank daily and intact", "id": "acfma2-rv19-80e78-49b3ef"}, {"t": "pt", "text": "Investigate cash shortages and surpluses", "id": "acfma2-rv19-80e78-76bb5f"}, {"t": "pt", "text": "Interest, inflation and exchange rates affect cash", "id": "acfma2-rv19-80e78-d144f9"}], "id": "acfma2-rv19-80e78"}], "source": "BPP MA2 Text ch 19 (OCR): sections 1-3 pp344-348", "summary": "The role of treasury management, cash handling procedures and controls over receipts and payments, and how the economic and financial environment affects cash balances.", "id": "acfma2-rv19", "updated": "2026-11-13"}, {"num": "20", "title": "Forecasting Cash Flows", "pages": [351, 384], "syllabus": "F3", "status": "published", "branches": [{"kind": "process", "title": "Cash forecasts", "page": [352, 360], "items": [{"t": "pt", "k": 1, "text": "A cash budget/forecast shows whether the organisation will have enough cash, when deficits or surpluses will arise and how large they will be", "id": "acfma2-rv20-98858-9c0818"}, {"t": "pt", "text": "Forecast deficiency: arrange borrowing (overdraft, loan), delay payments, speed up receipts", "id": "acfma2-rv20-98858-d58021"}, {"t": "pt", "text": "Forecast surplus: plan short-term investment of the surplus", "id": "acfma2-rv20-98858-a1005f"}, {"t": "pt", "k": 1, "text": "Receipts and payments forecast: estimated receipts (cash sales, receivables, other) - payments = net cash flow; + opening balance = closing balance", "id": "acfma2-rv20-98858-659b3f"}, {"t": "pt", "text": "Revised forecasts keep forecasts up to date; rolling forecasts add a new period as each period ends", "id": "acfma2-rv20-98858-628d76"}, {"t": "pt", "text": "Guidelines: break into periods (daily, weekly, monthly), use credit periods for timing, exclude non-cash items (depreciation)", "id": "acfma2-rv20-98858-c54814"}], "id": "acfma2-rv20-98858"}, {"kind": "concept", "title": "Control and corrective action", "page": [361, 365], "items": [{"t": "pt", "k": 1, "text": "Why forecasts differ from actual: poor forecasting, unforeseen events, changes in trading conditions, timing", "id": "acfma2-rv20-3a34c-7a7458"}, {"t": "pt", "text": "Cash flow control reports compare actual with forecast regularly for responsible managers", "id": "acfma2-rv20-3a34c-3e0978"}, {"t": "pt", "text": "Cash flow problems: making losses, inflation, growth (overtrading), seasonal trade, one-off large items", "id": "acfma2-rv20-3a34c-808bb9"}, {"t": "pt", "k": 1, "text": "Short-term deficits: control the working capital cycle - chase receivables, reduce inventory, take more credit, use an overdraft", "id": "acfma2-rv20-3a34c-bbc6d4"}, {"t": "pt", "text": "Longer-term methods: shorten the operating cycle, sell non-essential assets, raise long-term finance, postpone capital expenditure", "id": "acfma2-rv20-3a34c-47e71f"}, {"t": "pt", "text": "Quality control: review forecast accuracy and improve methods", "id": "acfma2-rv20-3a34c-893bc8"}], "id": "acfma2-rv20-3a34c"}, {"kind": "formula", "title": "Index numbers", "page": [365, 367], "items": [{"t": "def", "k": 1, "term": "Index", "text": "A measure over time of the average changes in prices of items or in quantities, relative to a base period (= 100)", "id": "acfma2-rv20-49501-69f62c"}, {"t": "f", "term": "Index points", "text": "Difference in the index value between one year and another", "vars": "not the same as a % change", "id": "acfma2-rv20-49501-301805"}, {"t": "f", "term": "Adjusting cash forecasts for prices", "text": "Forecast value = Current value x (Future index / Current index)", "id": "acfma2-rv20-49501-9d9998"}], "id": "acfma2-rv20-49501"}, {"kind": "formula", "title": "Time series", "page": [368, 380], "items": [{"t": "pt", "k": 1, "text": "Four components: trend • seasonal variations • cyclical variations • random variations", "id": "acfma2-rv20-bd041-2bc726"}, {"t": "pt", "k": 1, "text": "Trend: the way the figures are moving in the long term; found using moving averages", "id": "acfma2-rv20-bd041-bc6cb8"}, {"t": "f", "term": "Moving average", "text": "Average of a fixed number of consecutive periods (the length of the cycle)", "vars": "even number of periods -> centre with a second moving average", "id": "acfma2-rv20-bd041-36f380"}, {"t": "f", "k": 1, "term": "Additive model", "text": "Y = T + S + R", "vars": "seasonal variation = actual - trend", "id": "acfma2-rv20-bd041-212423"}, {"t": "f", "k": 1, "term": "Multiplicative model", "text": "Y = T x S x R", "vars": "seasonal index = actual / trend", "id": "acfma2-rv20-bd041-3b9334"}, {"t": "pt", "text": "Forecast = extrapolated trend adjusted by the seasonal variation", "id": "acfma2-rv20-bd041-fbd437"}, {"t": "pt", "text": "Problems: past patterns may not continue; extrapolation is uncertain; random events", "id": "acfma2-rv20-bd041-2ae594"}, {"t": "exam", "text": "Expect cash budget timing calculations and moving average/seasonal variation questions", "id": "acfma2-rv20-bd041-99c039"}], "id": "acfma2-rv20-bd041"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Including depreciation in a cash forecast", "id": "acfma2-rv20-6483a-d0e7a7"}, {"t": "x", "text": "Recording credit sales as cash in the month of sale", "id": "acfma2-rv20-6483a-6e55d9"}, {"t": "x", "text": "Failing to centre moving averages over an even number of periods", "id": "acfma2-rv20-6483a-540ea2"}, {"t": "x", "text": "Applying an additive variation as a multiplier", "id": "acfma2-rv20-6483a-810ba7"}], "id": "acfma2-rv20-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Cash budget shows timing and size of deficits and surpluses", "id": "acfma2-rv20-80e78-fee4cc"}, {"t": "pt", "text": "Deficit: borrow, delay payments, speed receipts", "id": "acfma2-rv20-80e78-d6c0bf"}, {"t": "pt", "text": "Surplus: invest short term", "id": "acfma2-rv20-80e78-10d3eb"}, {"t": "pt", "text": "Closing cash = opening + receipts - payments", "id": "acfma2-rv20-80e78-07261a"}, {"t": "pt", "text": "Rolling forecasts add a period as one ends", "id": "acfma2-rv20-80e78-b41a79"}, {"t": "pt", "text": "Exclude non-cash items", "id": "acfma2-rv20-80e78-5bdcec"}, {"t": "pt", "text": "Short-term fixes: working capital cycle control", "id": "acfma2-rv20-80e78-bb4e28"}, {"t": "pt", "text": "Long-term fixes: long-term finance, asset sales", "id": "acfma2-rv20-80e78-43d3ca"}, {"t": "pt", "text": "Index base period = 100", "id": "acfma2-rv20-80e78-25802b"}, {"t": "pt", "text": "Time series: trend, seasonal, cyclical, random", "id": "acfma2-rv20-80e78-5aef5b"}, {"t": "pt", "text": "Additive Y = T + S + R", "id": "acfma2-rv20-80e78-bec659"}, {"t": "pt", "text": "Multiplicative Y = T x S x R", "id": "acfma2-rv20-80e78-31a7a5"}, {"t": "pt", "text": "Centre even-period moving averages", "id": "acfma2-rv20-80e78-af1edd"}], "id": "acfma2-rv20-80e78"}], "source": "BPP MA2 Text ch 20 (OCR): sections 1-9 pp352-380", "summary": "Cash budgets and forecasts, deficiencies and surpluses, receipts and payments forecasts, revised and rolling forecasts, uncertainty and control reports, corrective action, index numbers and time series (trend, seasonal variations, moving averages, additive and multiplicative models).", "id": "acfma2-rv20", "updated": "2026-11-13"}, {"num": "21", "title": "Investing Surplus Funds", "pages": [385, 398], "syllabus": "F4", "status": "published", "branches": [{"kind": "concept", "title": "Principles of investing surplus cash", "page": [388, 390], "items": [{"t": "pt", "k": 1, "text": "Surplus cash should be managed with regard to LIQUIDITY, SAFETY and PROFITABILITY", "id": "acfma2-rv21-8812b-805fb8"}, {"t": "pt", "text": "Liquidity: funds available when needed; safety: low risk of loss of capital; profitability: a reasonable return", "id": "acfma2-rv21-8812b-c1b957"}, {"t": "pt", "k": 1, "text": "Guidelines: limits on amounts per investment/institution, approved types of investment, minimum credit ratings, maximum terms, authorisation levels", "id": "acfma2-rv21-8812b-baca0b"}, {"t": "pt", "text": "Legal restrictions: some organisations (eg trustees, charities) are restricted by law in what they can invest in", "id": "acfma2-rv21-8812b-28fac0"}, {"t": "pt", "text": "Public sector organisations are subject to rules affecting how they invest (approved lists, prudence)", "id": "acfma2-rv21-8812b-95c7b8"}], "id": "acfma2-rv21-8812b"}, {"kind": "compare", "title": "Short-term investments", "page": [391, 394], "items": [{"t": "table", "rows": [["Investment", "Features", "Risk / return"], ["High street bank deposits", "Instant access or notice/fixed term", "Low risk; capital secure; lower return"], ["Finance company deposits", "Varying terms", "Slightly higher risk and return"], ["Money-market deposits", "Fixed term or notice accounts, large sums", "Reasonable return; low risk"], ["Certificates of deposit (CDs)", "Issued by banks for a fixed term; can be SOLD before maturity", "Attractive interest; liquid via the secondary market"], ["Gilts (government stocks)", "Fixed interest or index-linked", "About as safe as possible - no default risk; price can change"], ["Local authority stocks", "Similar to gilts", "Very low risk"]], "id": "acfma2-rv21-f8993-8e0923"}, {"t": "def", "k": 1, "term": "Certificate of deposit (CD)", "text": "A certificate issued by a bank for a deposit of a fixed sum for a fixed term - can be sold before maturity", "id": "acfma2-rv21-f8993-0feb9a"}, {"t": "pt", "text": "Index-linked stocks: both interest and the eventual redemption value rise with inflation", "id": "acfma2-rv21-f8993-574262"}, {"t": "pt", "k": 1, "text": "Gilt prices move inversely with interest rates - a rise in rates lowers prices (capital risk if sold early)", "id": "acfma2-rv21-f8993-24377c"}], "id": "acfma2-rv21-f8993"}, {"kind": "concept", "title": "Risk and return", "page": [395, 395], "items": [{"t": "pt", "k": 1, "text": "The return an investor expects depends on the level of risk - higher risk requires a higher return", "id": "acfma2-rv21-b806e-b4b582"}, {"t": "pt", "text": "Risks: default (credit) risk, interest rate risk, liquidity risk, inflation risk", "id": "acfma2-rv21-b806e-689959"}, {"t": "exam", "text": "Expect questions matching an investment to a requirement (eg safest, most liquid, inflation-protected)", "id": "acfma2-rv21-b806e-ebd4c9"}], "id": "acfma2-rv21-b806e"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Thinking gilts have no price risk - they have no DEFAULT risk, but prices fall when interest rates rise", "id": "acfma2-rv21-6483a-fb537a"}, {"t": "x", "text": "Choosing the highest return regardless of safety and liquidity", "id": "acfma2-rv21-6483a-e80289"}, {"t": "x", "text": "Forgetting that CDs can be traded before maturity", "id": "acfma2-rv21-6483a-21f43c"}, {"t": "x", "text": "Ignoring legal restrictions on investment by certain organisations", "id": "acfma2-rv21-6483a-3243ea"}], "id": "acfma2-rv21-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Surplus cash: liquidity, safety, profitability", "id": "acfma2-rv21-80e78-a5987e"}, {"t": "pt", "text": "Guidelines: limits, approved types, ratings, terms", "id": "acfma2-rv21-80e78-cd55db"}, {"t": "pt", "text": "Legal and public sector restrictions apply", "id": "acfma2-rv21-80e78-e98ad7"}, {"t": "pt", "text": "Bank deposits: low risk, capital secure", "id": "acfma2-rv21-80e78-e032f9"}, {"t": "pt", "text": "Money-market: large sums, reasonable return", "id": "acfma2-rv21-80e78-f544b5"}, {"t": "pt", "text": "CDs: fixed term but tradeable", "id": "acfma2-rv21-80e78-8f6e2b"}, {"t": "pt", "text": "Gilts: no default risk", "id": "acfma2-rv21-80e78-a718a0"}, {"t": "pt", "text": "Index-linked gilts protect against inflation", "id": "acfma2-rv21-80e78-d58906"}, {"t": "pt", "text": "Gilt prices fall when interest rates rise", "id": "acfma2-rv21-80e78-415003"}, {"t": "pt", "text": "Higher risk requires higher return", "id": "acfma2-rv21-80e78-1a9879"}, {"t": "pt", "text": "Risks: default, interest rate, liquidity, inflation", "id": "acfma2-rv21-80e78-513174"}, {"t": "pt", "text": "Match investments to needs", "id": "acfma2-rv21-80e78-c039be"}], "id": "acfma2-rv21-80e78"}], "source": "BPP MA2 Text ch 21 (OCR): sections 1-8 pp386-395", "summary": "Principles for investing surplus cash (liquidity, safety, profitability), investment guidelines and legal restrictions, public sector rules, and the risks and returns of bank and finance company deposits, money-market deposits, certificates of deposit, gilts and local authority stocks.", "id": "acfma2-rv21", "updated": "2026-11-13"}, {"num": "22", "title": "Raising Finance from a Bank", "pages": [399, 419], "syllabus": "F4", "status": "published", "branches": [{"kind": "concept", "title": "Bank-customer relationships", "page": [401, 402], "items": [{"t": "pt", "k": 1, "text": "Receivable/payable: the customer deposits money - the bank owes it (and vice versa for borrowing)", "id": "acfma2-rv22-7bf51-976e5f"}, {"t": "pt", "text": "Mortgagor/mortgagee: the customer gives the bank security over an asset", "id": "acfma2-rv22-7bf51-e8cc02"}, {"t": "pt", "text": "Fiduciary: a relationship based on trust where the bank must act in good faith", "id": "acfma2-rv22-7bf51-e690b3"}, {"t": "pt", "text": "The treasury department should maintain good, open relationships with the bank", "id": "acfma2-rv22-7bf51-13bff4"}], "id": "acfma2-rv22-7bf51"}, {"kind": "concept", "title": "Lending criteria", "page": [402, 404], "items": [{"t": "pt", "k": 1, "text": "Banks assess: character of the borrower • ability to borrow and repay • margin of profit (interest and fees) • purpose of the borrowing • amount • repayment terms • insurance against non-payment (security) - remembered as CAMPARI", "id": "acfma2-rv22-550b1-5f90fd"}, {"t": "pt", "k": 1, "text": "Repayment is the MOST important requirement for a lending decision", "id": "acfma2-rv22-550b1-bc82a9"}, {"t": "pt", "text": "The bank must be satisfied the purpose is legal, sensible and in line with its policy", "id": "acfma2-rv22-550b1-2a2b43"}], "id": "acfma2-rv22-550b1"}, {"kind": "rule", "title": "Security and guarantees", "page": [404, 405], "items": [{"t": "pt", "k": 1, "text": "Good security is: easy to value, easy to take legal title to, stable in value, easy to realise", "id": "acfma2-rv22-26961-219b35"}, {"t": "def", "k": 1, "term": "Personal guarantee", "text": "A promise by an individual (eg a director) to repay the business's debt if it cannot - because a company is a separate legal entity from its owners", "id": "acfma2-rv22-26961-3869ad"}, {"t": "pt", "text": "Fixed charge over specific assets; floating charge over changing assets (eg inventory)", "id": "acfma2-rv22-26961-ad95a2"}], "id": "acfma2-rv22-26961"}, {"kind": "compare", "title": "Overdraft vs loan", "page": [406, 412], "items": [{"t": "table", "rows": [["Feature", "Overdraft", "Medium-term loan"], ["Purpose", "Day-to-day trading, working capital, short-term needs", "Specific longer-term purpose (eg buying assets)"], ["Interest", "Only on the amount overdrawn, daily", "On the whole loan"], ["Repayment", "Repayable on demand", "Agreed schedule over the term"], ["Flexibility", "High - draw as needed", "Certainty for both parties"], ["Cost", "Often higher rate, arrangement/commitment fees", "Fixed or variable rate agreed"]], "id": "acfma2-rv22-52630-27de02"}, {"t": "pt", "k": 1, "text": "Overdraft advantages: interest paid only when overdrawn; flexible; bank can review regularly", "id": "acfma2-rv22-52630-c9bcd0"}, {"t": "pt", "k": 1, "text": "Loan advantages: both borrower and bank know exactly what is to be repaid and when; not repayable on demand; suits long-term assets", "id": "acfma2-rv22-52630-b4c515"}, {"t": "pt", "text": "Revolving credit facility: similar to an overdraft - borrow, repay and re-borrow up to a limit for a set period", "id": "acfma2-rv22-52630-4d1160"}, {"t": "pt", "k": 1, "text": "Loan repayment profiles: amortising (equal instalments of capital and interest) • balloon (small early payments, large final payment) • bullet (all capital repaid at the end)", "id": "acfma2-rv22-52630-8124d3"}, {"t": "def", "term": "Loan covenant", "text": "Obligations on the borrower beyond repayment (eg maintaining gearing or interest cover levels, providing financial information)", "id": "acfma2-rv22-52630-65ee40"}, {"t": "pt", "text": "Banks check the borrower can service the debt from the working capital cycle and profits", "id": "acfma2-rv22-52630-2cbf40"}, {"t": "exam", "text": "Expect questions matching the right type of bank finance to a business need", "id": "acfma2-rv22-52630-a923b8"}], "id": "acfma2-rv22-52630"}, {"kind": "mistakes", "title": "Common mistakes", "page": null, "items": [{"t": "x", "text": "Using an overdraft to finance long-term assets - mismatch of term", "id": "acfma2-rv22-6483a-ae5f37"}, {"t": "x", "text": "Forgetting overdrafts are repayable on demand", "id": "acfma2-rv22-6483a-0da2ac"}, {"t": "x", "text": "Confusing a balloon repayment with a bullet repayment", "id": "acfma2-rv22-6483a-ccc52c"}, {"t": "x", "text": "Thinking a company's owner is automatically liable for its debts - only under a personal guarantee", "id": "acfma2-rv22-6483a-398667"}], "id": "acfma2-rv22-6483a"}, {"kind": "recall", "title": "Quick recall", "page": null, "items": [{"t": "pt", "text": "Relationships: receivable/payable, mortgagor/mortgagee, fiduciary", "id": "acfma2-rv22-80e78-10007d"}, {"t": "pt", "text": "CAMPARI: character, ability, margin, purpose, amount, repayment, insurance", "id": "acfma2-rv22-80e78-b56393"}, {"t": "pt", "text": "Repayment is the most important criterion", "id": "acfma2-rv22-80e78-91d38a"}, {"t": "pt", "text": "Good security: valuable, stable, easy to realise", "id": "acfma2-rv22-80e78-92e88f"}, {"t": "pt", "text": "Personal guarantee covers a company's debts", "id": "acfma2-rv22-80e78-a70313"}, {"t": "pt", "text": "Overdraft: short term, repayable on demand, interest on balance used", "id": "acfma2-rv22-80e78-b447a2"}, {"t": "pt", "text": "Loan: term, schedule, certainty", "id": "acfma2-rv22-80e78-f78fe3"}, {"t": "pt", "text": "Revolving credit: borrow and re-borrow to a limit", "id": "acfma2-rv22-80e78-8996f0"}, {"t": "pt", "text": "Amortising, balloon, bullet repayments", "id": "acfma2-rv22-80e78-10c024"}, {"t": "pt", "text": "Covenants restrict the borrower", "id": "acfma2-rv22-80e78-14fe04"}, {"t": "pt", "text": "Match finance term to the asset's life", "id": "acfma2-rv22-80e78-506880"}, {"t": "pt", "text": "Banks check ability to service debt", "id": "acfma2-rv22-80e78-886409"}], "id": "acfma2-rv22-80e78"}], "source": "BPP MA2 Text ch 22 (OCR): sections 1-7 pp400-412", "summary": "The bank-customer relationship, lending criteria, security and personal guarantees, overdrafts and their uses, revolving credit, medium-term loans (term, repayment profiles, interest, covenants) and overdraft vs loan.", "id": "acfma2-rv22", "updated": "2026-11-13"}], "plannedChapters": 22}], "preview": true};
